  ui_story_1_1_B26_dialog_content = "......",
  ui_story_1_1_B27_dialog_content = "아... 혹시 나 때문에 많이 놀랐어?",
  ui_story_1_1_B28_dialog_content = "하지만 방금 네가 갑자기 안으로 들어와서 나도 놀랐어.",
  ui_story_1_1_B29_dialog_content = "역시 난 지금 이게 무슨 상황인지 전혀 모르겠어.",
  ui_story_1_1_B30_dialog_content = "역시 만나서 이야기하는 게 좋겠어. 너희 오로리안은 이런 소통 방식에 익숙하지 않을 수도 있으니까.",
  ui_story_1_1_85_dialog_content = "아무튼, 복도를 따라 전진해. 난 마지막 방에서 널 기다리고 있어.",
  ui_story_1_1_86_dialog_content = "우와...",
  ui_story_1_1_A34_dialog_content = "에...",
  ui_story_1_1_87_dialog_content = "왜, 내 얼굴에 뭔가 묻었어? 방금 신경 써서 세수까지 하고 왔는데...",
  ui_story_1_1_88_dialog_content = "아냐. 진짜로 살아있는 사람일 줄은 몰랐거든. 유령은 아닌 거지...?",
  ui_story_1_1_89_dialog_content = "<size=40>말했잖아! 유령 같은 건 없다니깐!</size>",
  ui_story_1_1_B31_dialog_content = "그럼 왜 너도 아까 「와」라고 한 건데?",
  ui_story_1_1_B32_dialog_content = "...나도 진짜 살아있는 사람을 만날 줄은 몰랐으니까.",
  ui_story_1_1_90_dialog_content = "그럼 피차일반이잖아... 그래서 넌 대체 누구야? 여긴... 콜로서스인 거지?",
  ui_story_1_1_91_dialog_content = "맞아, 그리고 난 이 콜로서스의 주인이야. 그리고 방금 네게 정신 감응을 했던 사람이기도 하고.",
  ui_story_1_1_92_dialog_content = "말도 안 돼. 그 능력은 역사책에서밖에 못 봤다고. 하지만...",
  ui_story_1_1_93_dialog_content = "하지만...?",
  ui_story_1_1_94_dialog_content = "설마 너...|\n「<color=#FFB400>아이테르</color>」인 거야?!",
  ui_story_1_1_95_dialog_content = "뭘 그렇게 놀라는 건데? 맞아. 난 「아이테르」야.",
  ui_story_1_1_96_dialog_content = "...여긴 혹시 너밖에 없는 거야?",
  ui_story_1_1_97_dialog_content = "맞아, 난 지금까지 혼자 여기서 살고 있었어. 내 고향은 17년 전에 암귀에게 습격당했거든...",
  ui_story_1_1_A29_dialog_content = "음, 그 일은 나도 들은 적 있어...",
  ui_story_1_1_B33_dialog_content = "그럼, 너한테 질문을 좀 해도 될까?",
  ui_story_1_1_B34_dialog_content = "뭐, 뭐야, 너무 가깝잖아. 아이테르 씨...",
  ui_story_1_1_B35_dialog_content = "아, 미안해. 음... 그러니까...",
  ui_story_1_1_B36_option_content = "다른 아이테르를 본 적 있어?",
  ui_story_1_1_B37_option_content = "17년 전에 대체 무슨 일이 있었던 거야?",
  ui_story_1_1_B38_option_content = "오로리안과 암귀는 뭐지?",
  ui_story_1_1_B39_dialog_content = "난 기억이 있던 순간부터 계속 이곳에 있었어. 통신 시스템도 망가졌고. 그래서...",
  ui_story_1_1_B40_dialog_content = "잠깐만, 일단 진정해... 난 다른 아이테르는 만나본 적 없어.\n하지만 그들은 어쩌면 내가 가보지 못한 곳에 있는 건 아닐까?",
  ui_story_1_1_B41_dialog_content = "...그럼 어째서 날 찾으러 오지 않는 거지?",
  ui_story_1_1_B42_dialog_content = "......",
  ui_story_1_1_B43_dialog_content = "17년 전... 헤븐즈 밸리에서 무슨 일이 있었는지 난 문서로밖에 접하지 못했어.\n그리고 가끔 이상한 <color=#FFB400>꿈</color>을 꾸곤 해...",
  ui_story_1_1_B44_dialog_content = "꿈?",
  ui_story_1_1_B45_dialog_content = "그때 그 재앙에 대해... 좀 더 자세히 말해줄 수 있을까?",
  ui_story_1_1_B46_dialog_content = "그 일이 벌어졌을 때 난 갓 태어난 아기였어. 그래서 자세한 것까진 몰라.",
  ui_story_1_1_B47_dialog_content = "내가 아는 건 그저 「암귀들이 갑자기 <color=#FFB400>조직적인 습격</color>을 시작」했고,\n하룻밤 사이에 아이테르가 모여 살던 헤븐즈 밸리를 파괴했다는 거야.",
  ui_story_1_1_B48_dialog_content = "...음, 그건 나도 알고 있어.",
  ui_story_1_1_B49_dialog_content = "그럼 더 도움이 될 만한 이야기는 없을 것 같네. 미안...",
  ui_story_1_1_B50_dialog_content = "그래서... 그럼 넌 「<color=#FFB400>오로리안</color>」인 거지?",
  ui_story_1_1_B51_dialog_content = "응. 한때 우리와 아이테르는 함께 암귀에 맞서 싸웠다고 들었어.",
  ui_story_1_1_B52_dialog_content = "방금 그 괴물들이 바로 암귀인 거야?",
  ui_story_1_1_B53_dialog_content = "맞아. 저 「생물」들은 온 대륙에서 기승을 부리고 있어. 아무도 녀석들이 어디서 왔는지 몰라.",
  ui_story_1_1_B54_dialog_content = "대륙 반대편에서 왔다는 말도 있고, 어떤 사람들은 하늘이 내린 벌이라고 말하기도 해...",
  ui_story_1_1_B55_dialog_content = "아무튼, 역사가 시작했을 때부터, 암귀는 늘 우리 모두의 적이었어.",
  ui_story_1_1_B56_dialog_content = "음... 그것도 전부 자료에서 읽은 적 있어.",
  ui_story_1_1_B57_dialog_content = "그럼 왜 물어보는 거야...",
  ui_story_1_1_B58_option_content = "또 궁금한 게 있어.",
  ui_story_1_1_B59_option_content = "......",
  ui_story_1_1_B60_dialog_content = "또 궁금한 게 있어.",
  ui_story_1_1_98_dialog_content = "맞다, 그럼 넌 계속... 혼자 여기 있었던 거야? 밖으로 나오고 싶지는 않았어?",
  ui_story_1_1_99_dialog_content = "그건 말이지... 난 전투 능력이 없거든. 너희처럼 <color=#FFB400>루미나틱스</color>를 쓸 수 없어.",
  ui_story_1_1_100_dialog_content = "난 빛의 궤적을 볼 수 있지만, 그걸 가지고 싸울 능력은 없어. 참 아이러니하지?",
  ui_story_1_1_101_dialog_content = "아니... 난 오로리안들이 빛의 힘을 이용해 싸우면서, 정작 그 빛을 눈으로 볼 수 없다는 게\n더 아이러니한 일이라고 생각해...",
  ui_story_1_1_103_dialog_content = "아무튼, 그동안 난 계속 이곳에 있었고, 스카이워커호의 생명유지 시스템에 의지해서 오늘까지 살아왔어.",
  ui_story_1_1_104_dialog_content = "「<color=#FFB400>스카이워커호</color>」? 이 콜로서스 말이야? 대단하네! 이름도 있었구나...",
  ui_story_1_1_105_dialog_content = "당연하지. 콜로서스는 마법과 과학, 생명공학의 결합체니까. 자아도 지니고 있다고.",
  ui_story_1_1_106_dialog_content = "그래서 넌 콜로서스와도 소통할 수 있는 거구나. 게다가 감응 능력을 가진 아이테르니까...",
  ui_story_1_1_107_dialog_content = "맞아, 그건 우리 아이테르가 날 때부터 지니는 능력이니까.",
  ui_story_1_1_109_dialog_content = "왜 그래? 어디 다쳤어?",
  ui_story_1_1_110_dialog_content = "......",
  ui_story_1_1_111_dialog_content = "...음, 아무것도 아냐. 그냥 다른 일이 좀 생각이 나서.",
  ui_story_1_1_112_dialog_content = "참! 그럼 이거 아직 가동할 수 있는 거야? 어쩌면...",
  ui_story_1_1_113_dialog_content = "미안. 스카이워커는 비록 한때 세상에 몇 대밖에 없던 천공급 콜로서스지만,\n지금의 난... 가동시킬 수 없어.",
  ui_story_1_1_114_dialog_content = "그나저나 바이스 넌 콜로서스에 대해서 꽤 잘 아는 것 같은데?",
  ui_story_1_1_115_dialog_content = "그냥 조금 아는 정도야! 관련 서적을 본 적 있거든.\n이번 임무도 사실 아직 존재할지도 모르는 콜로서스를 찾...",
  ui_story_1_1_A31_dialog_content = "어라, 방금 내 이름 부른 거야? 아직 안 알려줬던 것 같은데...",
  ui_story_1_1_A32_dialog_content = "감응 능력으로 알았어. 방금 너랑 네 동료들이 밖에서 대화하는 걸 들었거든.",
  ui_story_1_1_A33_dialog_content = "아, 하하, 미안. 역시 아이테르구나.",
  ui_story_1_1_116_dialog_content = "스카이워커호를 가동할 수 없는 건 아쉽지만, 그래도 더 귀중한 보물을 찾았으니까 됐지 뭐!",
  ui_story_1_1_117_dialog_content = "...지금 날 말하는 건 아니지?",
  ui_story_1_1_118_dialog_content = "참, 너한테 부탁하고 싶은 게 있어... 그러고 보니 아직 이름도 안 물어봤네...",
  ui_story_1_1_119_dialog_content = "PlayerName.",
  ui_story_1_1_120_dialog_content = "PlayerName? 역시 뭔가 묘하게 이국적인 분위기인걸!",
  ui_story_1_1_121_dialog_content = "사실은 아까 위에서 떨어질 때 동료들이랑 흩어졌거든. 그 애들을 찾는 걸 도와줄 수 있을까?",
  ui_story_1_1_122_dialog_content = "아직은 감응이 되지 않아. 스카이워커, 방법이 있어?",
  ui_story_1_1_123_dialog_content = "신호 발사대 쪽에 오로리안이 두 명 있습니다. 꽤 많은 수의 암귀가 그쪽으로 향하고 있습니다.",
  ui_story_1_1_124_dialog_content = "다시 말해서, 지금 이곳도 이제는 안전하지 않습니다.",
  ui_story_1_1_125_dialog_content = "신호 발사대 근처에 있어. 곤란한 상황인 것 같아.",
  ui_story_1_1_126_dialog_content = "그럼 난 도우러 가야만 해!",
  ui_story_1_1_127_dialog_content = "그리고 네 도움도 필요해! 넌 빛의 분포를 볼 수 있으니까, 우릴 지휘해줄 수 있어!",
  ui_story_1_1_128_dialog_content = "그럼 아까처럼 내 전투력이 몇 배는 더 강해질 거야!",
  ui_story_1_1_129_option_content = "하지만 난 싸움은 잘 못하는데...",
  ui_story_1_1_130_option_content = "그럼 같이 가자!",
  ui_story_1_1_131_dialog_content = "걱정 마. 내가 널 지켜줄게!",
  ui_story_1_1_132_dialog_content = "저 소녀의 말이 맞습니다. 암귀가 침입한 이상, 그녀와 함께 움직이는 편이 더 안전할 겁니다.",
  ui_story_1_1_133_dialog_content = "알겠어, 그럼 그렇게 할게. 바이스. 대신 나도 부탁이 있어.",
  ui_story_1_1_134_dialog_content = "좋아! 걱정할 거 없어. 내가 지켜줄 테니까!",
  ui_story_1_1_135_dialog_content = "좋습니다. 활력이 넘치는 오로리안이로군요. 바이스라고 했습니까?",
  ui_story_1_1_X6_dialog_content = "PlayerName, 당신도 큰 결정을 내리셨군요.",
  ui_story_1_1_136_dialog_content = "그럼 너도 날 도와줬으면 해.",
  ui_story_1_1_B61_dialog_content = "물론이야! 무슨 일이든, 내가 할 수 있는 거라면 얼마든지!",
  ui_story_1_1_137_dialog_content = "날 이곳에서 데리고 나가줘.",
  ui_story_1_1_138_dialog_content = "밖으로 가고 싶은 거지? 알겠어. 준비는 된 거지?",
  ui_story_1_1_139_dialog_content = "그건... 잘 모르겠어.",
  ui_story_1_1_140_dialog_content = "하지만 난 반드시 떠나야 해!",
  ui_story_1_2_1_dialog_content = "안젤, 난 틀렸어...",
  ui_story_1_2_2_dialog_content = "이 암귀 녀석들, 끝이 없는 것 같은데? 이제 힘도 얼마 안 남았어...",
  ui_story_1_2_3_dialog_content = "여기선 해가 보이지 않아서 빛의 힘이 부쩍 줄어버렸어.\n게다가 암귀 녀석들도 빛의 억제가 없으니 더 날뛰게 됐어!",
  ui_story_1_2_4_dialog_content = "어떻게든 위로 돌아가야 하는데... 바이스는 대체 어디 있는 거지...",
  ui_story_1_2_6_dialog_content = "구구! 여기서 죽고 싶진 않아...",
  ui_story_1_2_7_dialog_content = "도브! 나야!",
  ui_story_1_2_8_dialog_content = "다행이야. 이 바보 녀석, 그나마 빛의 힘이 약해진 덕에 바이스가 안 다칠 수 있었어.",
  ui_story_1_2_9_dialog_content = "바, 바이스? 괜찮아...?",
  ui_story_1_2_10_dialog_content = "난 괜찮아! PlayerName 덕분에 너흴 찾을 수 있었어!",
  ui_story_1_2_11_dialog_content = "PlayerName? 누구? 아무도 안 보이는데?",
  ui_story_1_2_12_dialog_content = "지금 다른 곳에 있어. 하지만 우리가 어떻게 해야 할지 알려줄 거야!\n너희는 그대로 발을 맞추기만 하면 돼!",
  ui_story_1_2_13_dialog_content = "발을 맞춘다고? 어떻게? 우리가...",
  ui_story_1_2_14_option_content = "(강제 감응!)",
  ui_story_1_2_15_dialog_content = "방금 꿈을 꾼 건 아니겠지... 마치 빛 속을 걷는 것 같았어...",
  ui_story_1_2_16_dialog_content = "이게 어떻게 된 거야? 바이스... 그리고 저 녀석은 왜 계속 문 뒤에 숨어 있는 건데?",
  ui_story_1_2_17_dialog_content = "미안... 난 싸울 수가 없거든.",
  ui_story_1_2_18_dialog_content = "루미나의 시각과 감응 능력... 그럼 네가 바로 그...",
  ui_story_1_2_19_dialog_content = "바이스, 너한테 이런 친구가 있었다는 말은 못 들었는걸.",
  ui_story_1_2_20_option_content = "방금 처음 만났어...",
  ui_story_1_2_21_option_content = "「친구」...?",
  ui_story_1_2_22_dialog_content = "응. 우리가 떨어졌을 때 PlayerName 얘가 날 구해줬어.",
  ui_story_1_2_23_dialog_content = "그리고 이 콜로서스의 주인이자, 아이테르야.",
  ui_story_1_2_24_dialog_content = "내... 「친구」?",
  ui_story_1_2_25_dialog_content = "PlayerName... 왜 그래?",
  ui_story_1_2_26_dialog_content = "음, 아무것도 아냐...",
  ui_story_1_2_28_dialog_content = "내가 떨어진 뒤에도 암귀와 마주쳤는데, PlayerName 얘가 날 구해줬어.",
  ui_story_1_2_29_dialog_content = "이쪽은 안젤, 이 녀석은 도브, 모두 우리 소대의 일원이야.",
  ui_story_1_2_30_dialog_content = "난 PlayerName, 이 콜로서스의 주인이고, 아이테르야.",
  ui_story_1_2_31_dialog_content = "도와줘서 고마워, PlayerName. 어쩌면 너한테 물어볼 게 많을 것 같아...",
  ui_story_1_2_32_dialog_content = "아이...테... 뭐? 무슨 소리인지 하나도 모르겠다고...",
  ui_story_1_2_33_dialog_content = "아무튼 고마워, PlayerName. 그럼 앞으로 우린 친구인 거야!",
  ui_story_1_2_34_dialog_content = "나도 「친구」가 생기는 날이 올 줄은 몰랐어...",
  ui_story_1_3_1_dialog_content = "바이스, 이제 어떡하지? 암귀의 수가 너무 많아. 지원이 필요해.",
  ui_story_1_3_2_dialog_content = "우리가 가져온 통신기는 전투 중에 망가졌어. <color=#FFB400>조종사</color>, 스카이워커호에 연락 수단이 있을까?",
  ui_story_1_3_3_dialog_content = "이미 망가졌어.",
  ui_story_1_3_X1_dialog_content = "그럼 무기는 있겠지...?",
  ui_story_1_3_X2_dialog_content = "무기 같은 건 전혀 없어...",
  ui_story_1_3_4_dialog_content = "이건 콜로서스잖아? 그럼 왜 가동하지 않는 건데?",
  ui_story_1_3_X3_dialog_content = "<color=#e8d9bb>가동 실패. 누적 실패 횟수, 3921회.</color>",
  ui_story_1_3_X4_dialog_content = "가동이 안 돼...",
  ui_story_1_3_X5_dialog_content = "어째서...?",
  ui_story_1_3_X6_dialog_content = "...몇 년 동안 수도 없이 시도했지만, 왠지는 몰라도 매번 가동에 실패했어.",
  ui_story_1_3_X7_dialog_content = "정말 미안해. 하지만 콜로서스의 상태는 정말 좋지 않아...",
  ui_story_1_3_X8_dialog_content = "내 생명을 유지시켜준 것만으로도 이미 전력을 다한 셈이야. 스카이워커도 무척 고생했다고.",
  ui_story_1_3_X9_dialog_content = "칭찬, 감사합니다, PlayerName.",
  ui_story_1_3_X10_dialog_content = "......",
  ui_story_1_3_6_dialog_content = "잠깐만, 조종사.",
  ui_story_1_3_X11_dialog_content = "가동도 안 되고, 무기도 없지만, 대신...",
  ui_story_1_3_7_dialog_content = "여기도 신호 발사대가 있어. 아까 말했잖아. 맞지?",
  ui_story_1_3_8_dialog_content = "모든 콜로서스에는 신호 발사대가 있다고 알고 있어. 그걸로 구조 신호를 발사하는 거지.",
  ui_story_1_3_A1_dialog_content = "누군가 우리의 구조 신호를 발견한다면 분명히 우릴 구하러 와 줄 거야!",
  ui_story_1_3_9_dialog_content = "아마 가까운 곳에 있겠지? 아까 안젤이랑 도브가 신호 발사대 근처에 있다고 했잖아!",
  ui_story_1_3_10_dialog_content = "...어떻게 그렇게 콜로서스에 대해 잘 알고 있는 거야?",
  ui_story_1_3_X12_dialog_content = "헤헤, 그냥 조금 아는 정도야. 평소엔 다들 이런 건 「쓸모없는」 지식이라고 말했지만 말이야...",
  ui_story_1_3_X13_dialog_content = "발사대는 확실히 이 근처에 있어. 그리고 손상되지도 않았고 말이야.",
  ui_story_1_3_X14_dialog_content = "하지만... 아마 내가 무슨 말을 할지 알 거야...",
  ui_story_1_3_11_dialog_content = "나한테는 신호탄을 발사하는 데 필요한 재료가...",
  ui_story_1_3_12_dialog_content = "<color=#FFB400>루맘버</color> 말이지?",
  ui_story_1_3_13_dialog_content = "어떻게 알았... 아, 역시 「조금 안다」는 건가?",
  ui_story_1_3_14_dialog_content = "루맘버라면 마침 우리가 가지고 있어.",
  ui_story_1_3_15_dialog_content = "크흠, 바이스, 그거...",
  ui_story_1_3_16_dialog_content = "왜? 너한테 하나 있는 거 봤어. 바로 네 가방 안에 말이야.",
  ui_story_1_3_18_dialog_content = "엄청 비싼 거라고...",
  ui_story_1_3_19_dialog_content = "목숨이 달린 순간에 무슨 소리야! 지금 그렇게 쩨쩨하게 굴 때야, 도브?",
  ui_story_1_3_B1_dialog_content = "그럼 경비로 청구해도 돼?",
  ui_story_1_3_B2_dialog_content = "당연하지! 그리고 돌아가면 휴가도 10일 더 줄게. 됐지?",
  ui_story_1_3_B3_dialog_content = "구구구! 약속 꼭 지켜!",
  ui_story_1_3_B4_dialog_content = "그럼 얼른 신호 발사대로 가자!",
  ui_story_1_3_A2_dialog_content = "도중에 암귀가 있을지도 모르니까 다들 조심해!",
  ui_story_1_3_24_dialog_content = "도착했어! 여긴 꽤 찾기 어렵겠는걸. 역시 조종사답네!",
  ui_story_1_3_25_dialog_content = "17년 동안 여기서만 지냈으니 그럴 수밖에...",
  ui_story_1_3_26_dialog_content = "제때 도착해서 다행이야. 조금만 더 늦었으면 이곳도 암귀의 공격을 받았을 거야...",
  ui_story_1_3_27_dialog_content = "다행히 설비는 파괴되지 않았어.",
  ui_story_1_3_28_dialog_content = "그러니까, 저게 바로 컨트롤러인 거지?",
  ui_story_1_3_29_dialog_content = "와아, 실물로 보는 건 처음이야. 그럼 조작은...",
  ui_story_1_3_30_dialog_content = "루맘버를 발사기에 넣고 <color=#FFB400>레버만 당기면</color> 돼.",
  ui_story_1_3_31_dialog_content = "정작 재료가 없어서 지금까지 실제로 써본 적은 없었지만 말이야...",
  ui_story_1_3_33_dialog_content = "하지만 오늘은 믿음직한 동료와 함께라고! 그렇지? 도브~",
  ui_story_1_3_34_dialog_content = "바이스, 내 루맘버... 소중하게 대해줄 거지?",
  ui_story_1_3_35_dialog_content = "물론이지.",
  ui_story_1_3_36_dialog_content = "......",
  ui_story_1_3_B5_dialog_content = "...도브, 손 놔도 돼...",
  ui_story_1_3_B6_dialog_content = "구구... 주겠다고 한 거 그냥 취소하면 안 될까...",
  ui_story_1_3_B7_dialog_content = "약속을 어기는 사람은 암귀 손가락 천 개를 먹어야 하는데도?",
  ui_story_1_3_B8_dialog_content = "구우우!",
  ui_story_1_4_1_dialog_content = "우와아! 발사했어! 엄청 눈부시네!",
  ui_story_1_4_2_dialog_content = "정말 해냈어... 바이스, 고마워!",
  ui_story_1_4_3_dialog_content = "응? 난 아무것도 안 했는걸! 그냥 잔머리를 좀 써봤을 뿐이랄까?",
  ui_story_1_4_4_dialog_content = "정말 나한테 고마우면, 일단 여길 벗어난 뒤에 다시 말해 줘!",
  ui_story_1_4_5_dialog_content = "이 오로리안은 역시 평범하지 않습니다. 당신과도 손발이 잘 맞는 것 같군요.",
  ui_story_1_4_6_dialog_content = "그 오랜 시간의 적막함이... 드디어 깨졌어.",
  ui_story_1_4_X1_dialog_content = "하지만 어째 별로 안 기쁜 것 같네, PlayerName? 어디 몸이 불편한 데라도 있어?",
  ui_story_1_4_X2_dialog_content = "아니, 그냥... 눈꺼풀이 좀 무거워서...",
  ui_story_1_4_B29_dialog_content = "혹시 졸린 거야? 아! 마침 나한테...\n《기계 제도학》 책이 있는데 볼래?",
  ui_story_1_4_B30_dialog_content = "난 졸릴 때마다 이 책을 보거든. 도표로 가득한 책을 보면 정신이 맑아진다니까!",
  ui_story_1_4_B31_dialog_content = "다른 사람도 너처럼 그럴 것 같진 않은걸, 바이스...",
  ui_story_1_4_X3_dialog_content = "에? 하지만... 앗!",
  ui_story_1_4_X4_dialog_content = "왜 그래? 내 얼굴에 또 뭐가 묻었어?",
  ui_story_1_4_X5_dialog_content = "코피! 너 지금 코피 흘리고 있어!",
  ui_story_1_4_X6_dialog_content = "이, 이런, 너무 무리하게 감응한 모양이야...",
  ui_story_1_4_X7_dialog_content = "신호를 발사하면서 머리에 부담을 준 것 같아...",
  ui_story_1_4_A1_dialog_content = "에엣?! 하지만 아까 우릴 지휘할 때는 거뜬했잖아?",
  ui_story_1_4_A2_dialog_content = "콜로서스를 조종하는 건... 더 많은... 에너지가 필요해...\n괜찮아. 전에도 이런 적 있었으니까... 곧 괜찮아질...",
  ui_story_1_4_7_option_content = "아, 안 되겠어...",
  ui_story_1_4_8_option_content = "바이...스...",
  ui_story_1_4_9_dialog_content = "괘, 괜찮아?! 앗! 다들 PlayerName 좀 도와줘! 갑자기 쓰러져버렸어!",
  ui_story_1_4_10_dialog_content = "잠깐, 나 혼자는 무리라고! 너희 둘, 얼른 도와줘... PlayerName, 너무 무겁잖아!",
  ui_story_1_4_12_dialog_content = "신호가 더 많은 암귀를 불러왔습니다. 서둘러 이동해야 합니다!",
  ui_story_1_4_13_dialog_content = "바이스 중위님, 지금 같은 상황에서 기절한 이 사람을 데리고 움직인다면, 모두가 위험해질 겁니다.",
  ui_story_1_4_A6_dialog_content = "또한 제 임무는 블랑 님을 <color=#FFB400>28호 지하성</color>으로 호송하는 겁니다. 다른 임무는...",
  ui_story_1_4_A3_dialog_content = "우릴 지원하러 와준 건 고마워.|\n하지만 우린 PlayerName 덕분에 살 수 있었어. 그러니 보답을 해야만 해.",
  ui_story_1_4_14_dialog_content = "우리 <color=#FFB400>일루미나 연방</color>에겐 은혜를 원수로 갚는 일은 있을 수 없어!",
  ui_story_1_4_A4_dialog_content = "게다가 PlayerName... 이 사람은 아이테르야.",
  ui_story_1_4_15_dialog_content = "그게... 정말입니까?",
  ui_story_1_4_16_dialog_content = "하지만 우린 지금도 전투를 수행할 능력이 부족합니다.\n이대로면 이 사람만이 아니라 그 누구의 안전도 보장할 수 없습니다!",
  ui_story_1_4_17_dialog_content = "네 말이 맞아.|\n그럼 넌 모두를 데리고 떠나. 보급만 조금 나눠주면 내가 여기 남을 테니까.",
  ui_story_1_4_18_dialog_content = "정말 용감한 아가씨네요. 바이스 중위님.",
  ui_story_1_4_19_dialog_content = "아직 제 소개를 못 했네요. 전 블랑이에요. 잘 부탁해요.",
  ui_story_1_4_20_dialog_content = "죄송해요. 블랑 씨, 저희 때문에 일정이 지체됐네요...",
  ui_story_1_4_21_dialog_content = "괜찮아요. 구조 신호를 보고도 모른 척하는 건 있을 수 없는 일이잖아요.",
  ui_story_1_4_22_dialog_content = "게다가 이렇게 콜로서스도 볼 수 있게 됐으니 헛걸음은 아닌걸요.",
  ui_story_1_4_23_dialog_content = "바이스가 남기로 결정한 이상, 연합 탐색 소대의 일원으로서 나도 함께할 거야.",
  ui_story_1_4_24_dialog_content = "구구? 그...그럼 나도 남을게... 따지고 보면 우리가 살 수 있었던 것도 PlayerName 덕분이니까...",
  ui_story_1_4_25_dialog_content = "너희들...",
  ui_story_1_4_A5_dialog_content = "아! 다행이야, 깨어났구나!|\n네가 기절해 있는 동안 지원이 도착했어. 지금 좀 어때? 움직일 수 있겠어?",
  ui_story_1_4_26_dialog_content = "음...",
  ui_story_1_4_28_dialog_content = "바이스 중위님, 방금 들어온 소식입니다만, 이 근처에서 카라켄의 흔적이 발견되었다고 합니다.",
  ui_story_1_4_29_dialog_content = "<color=#FFB400>고위 암귀 카라켄</color>? 확실히 요즘 계속 날뛰고 있긴 했지만, 녀석이 어째서 이쪽으로...",
  ui_story_1_4_30_dialog_content = "아무튼 그건 지금 우리가 상대할 수 있는 적이 아냐! 어서 이동해야 해!",
  ui_story_1_4_31_dialog_content = "PlayerName, 우리랑 같이 갈 수 있겠어?",
  ui_story_1_4_32_dialog_content = "나도 같이 가고 싶어. 바이스. 하지만 스카이워커호는...",
  ui_story_1_4_33_dialog_content = "이 콜로서스가 그 스카이워커호인 겁니까? 회수 작업은 우선 돌아간 후에 신중히 의논하는 게 좋겠습니다.",
  ui_story_1_4_X8_dialog_content = "제 의무는 여러분의 안전을 지키는 것뿐, 다른 건 중요하지 않습니다.",
  ui_story_1_4_X9_dialog_content = "괜찮습니다, PlayerName. 당신만 안전하다면 제 안위는 중요하지 않습니다.",
  ui_story_1_4_X10_dialog_content = "우선 모두와 함께 이곳을 벗어나십시오.",
  ui_story_1_4_B1_option_content = "미안해. 금방 다시 데리러 올게!",
  ui_story_1_4_B2_option_content = "...같이 떠날 방법은 없을까?",
  ui_story_1_4_B3_option_content = "일단 짐을 좀 싸야겠어...",
  ui_story_1_4_B4_dialog_content = "결정했어. 너희와 같이 갈게!",
  ui_story_1_4_B5_dialog_content = "이 순간을 오랫동안 기다려왔어... 밖이 어떤 모습이든 상관없어. 난 내 눈으로 직접 볼 테니까.",
  ui_story_1_4_B6_dialog_content = "그리고 내 동족들한테 물어보고 싶은 것도 아주 많다고.",
  ui_story_1_4_B7_dialog_content = "좋아! 그럼 전투 준비를 하자. 만약 다수의 암귀가 근처에 있다면, 싸움을 피할 순 없을 거야!",
  ui_story_1_4_B9_dialog_content = "미련, 공포, 불안... 이러한 감정들은 강해지기 위해 필요한 디딤돌입니다.",
  ui_story_1_4_B10_dialog_content = "부디 그러한 감정을 극복하는 법을 배우시길 바랍니다. 저와의 작별부터 시작해서 말입니다.",
  ui_story_1_4_B11_dialog_content = "스카이워커...",
  ui_story_1_4_B12_dialog_content = "이곳을 떠나 한 사람의 아이테르가 되십시오. 이제 이렇게 동료들도 많지 않습니까.",
  ui_story_1_4_B13_dialog_content = "그리고 저는 언제나 이곳에 있을 테니, 걱정하지 마십시오.",
  ui_story_1_4_B14_dialog_content = "PlayerName, 어서 가야 해. 암귀가 더 많이 몰려오기 전에!",
  ui_story_1_4_B15_dialog_content = "알겠어...",
  ui_story_1_4_B16_dialog_content = "좋아! 다들 집중해! 언제든 싸울 준비를 하고 여길 벗어나는 거야!",
  ui_story_1_4_B17_dialog_content = "에? 짐?",
  ui_story_1_4_B18_dialog_content = "낡은 부품으로 만든 만화경이랑, 전선으로 만든 공, 그리고 루미나 물감으로 그린 그라피티랑...",
  ui_story_1_4_B19_dialog_content = "......",
  ui_story_1_4_B20_dialog_content = "비웃지 말아줘... 비록 별 볼 일 없는 물건이긴 하지만,\n그래도 오랫동안 내 곁에 있어 준 녀석들이니까...",
  ui_story_1_4_B21_dialog_content = "심지어 이름까지 지어줬다고...",
  ui_story_1_4_B22_dialog_content = "...당신 심정은 잘 이해하지만, 지금은 그런 것에 연연할 때가 아닙니다.",
  ui_story_1_4_B23_dialog_content = "PlayerName, 절 믿으십시오. 이곳을 떠나고 나면 훨씬 가치 있는 것들을 얻게 될 겁니다.",
  ui_story_1_4_B24_dialog_content = "그리고 저와 녀석들은 항상 이곳에 있을 겁니다. 모든 게 끝나면 저희를 찾으러 와주십시오.",
  ui_story_1_4_B25_dialog_content = "아무래도 그럴 수밖에 없겠어...",
  ui_story_1_4_B26_dialog_content = "이상한 말만 해서 미안해... 그럼 우선 이곳을 떠나자.",
  ui_story_1_4_B32_dialog_content = "아하하, 괜찮아! 나도 이상한 취미가 잔뜩 있는걸!",
  ui_story_1_4_B27_dialog_content = "좋아! 정신 바짝 차려! 암귀가 모여들기 전에 어서 출구를 찾아야 해!",
  ui_story_1_4_B28_dialog_content = "조종사, 너도 언제든지 전투를 지휘할 수 있게 준비해 줘!",
  ui_story_1_8_1_dialog_content = "정말 암귀가 왜 이리 많은 거야... 더는 여기 머무를 수가 없겠어.",
  ui_story_1_8_B37_dialog_content = "전부 파괴된 흔적들이네... 그동안 매일 깨끗하게 청소해오던 곳인데...",
  ui_story_1_8_2_dialog_content = "미안해, PlayerName. 우리가 멋대로 오지만 않았어도...",
  ui_story_1_8_3_dialog_content = "그럼 나도 이곳에서 나갈 기회가 없었을 거야. 자책하지 마, 너희 잘못이 아니야.\n잘못이라면 그림자에서 기어 나온 저 녀석들한테 있겠지.",
  ui_story_1_8_B29_dialog_content = "걱정 마. 스카이워커호를 회수하면 일루미나에 신청해서 제대로 수리해줄게!",
  ui_story_1_8_B30_dialog_content = "게다가 인테리어도 새롭게 해줄 수 있다고!",
  ui_story_1_8_B31_dialog_content = "원하는 디자인 있어? 오픈형 주방은 어때? 문어 우유죽 같은 것도 만들 수 있을 거야!",
  ui_story_1_8_B32_dialog_content = "난 요리는 할 줄 몰라. 요리는 전부 스카이워커가 맡아왔어...",
  ui_story_1_8_B33_dialog_content = "아, 그렇구나. 그럼 초대형 욕조는? 하루를 끝내고 뜨거운 물에 몸을 담그고 책을 읽으면...",
  ui_story_1_8_B34_dialog_content = "아, 아니, 일단 지금은 필요 없을 것 같아...",
  ui_story_1_8_B35_dialog_content = "그럼 역시 실용적인 기계 제도실이 더 중요하겠지?",
  ui_story_1_8_B36_dialog_content = "바이스, 기분 풀어주려는 거면 고맙지만 됐어. 지금은 정말 괜찮아졌으니까.",
  ui_story_1_8_4_dialog_content = "에? 아... 미안해...",
  ui_story_1_8_B38_dialog_content = "그냥 네가 왠지 좀 울적해 보여서, 내가 재미있어할 만한 것들로 화제를 돌리면 좀 나아질까 싶었어...",
  ui_story_1_8_5_dialog_content = "게다가 지휘해야 하는 인원도 많아졌으니까...\n네가 또 코피라도 쏟는 건 아닐까 걱정도 되고 말이지...",
  ui_story_1_8_6_dialog_content = "너희 모두의 전투를 동시에 보조하는 것도 사실 별문제는 아냐.\n콜로서스와의 감응에 비하면, 그 정도는...",
  ui_story_1_8_7_dialog_content = "<size=45>전방에 위험 요소가 있습니다! 후퇴하십시오! 어서!</size>",
  ui_story_1_8_8_dialog_content = "이, 이건?!",
  ui_story_1_8_9_dialog_content = "이 힘이라면 역시... 제길, 결국 마주친 건가!",
  ui_story_1_8_10_dialog_content = "<color=#FFB400>카라켄</color>!",
  ui_story_1_8_11_dialog_content = "<anim type=Shake><size=50>크오오오오!</size></anim>",
  ui_story_1_8_12_dialog_content = "이렇게 큰 암귀도 있었단 말이야?! 설마 헤븐즈 밸리도 이런 녀석들한테...",
  ui_story_1_8_13_dialog_content = "조심해, PlayerName! 어서 안전한 곳에 숨어!",
  ui_story_1_8_14_dialog_content = "안전한 곳이 어디 있단 말입니까?! 지금 상황을 돌파하려면 카라켄과 정면으로 맞서는 수밖에 없습니다!",
  ui_story_1_8_15_option_content = "그럼 정면 돌파하자!",
  ui_story_1_8_16_option_content = "그럼 난 후방에서 지원할게!",
  ui_story_1_8_17_dialog_content = "좋아, 바로 그 기세야! 가자!",
  ui_story_1_8_A2_dialog_content = "지금까지 해온 것처럼 지휘를 부탁할게, 조종사!",
  ui_story_1_8_18_dialog_content = "그럼 바로 모두와 정신 감응을 진행할 테니까, 준비해 줘!",
  ui_story_1_8_19_dialog_content = "부탁할게! 그럼 공격하자!",
  ui_story_1_8_20_dialog_content = "<anim type=Shake><size=50>크오오오──!</size></anim>",
  ui_story_1_8_21_dialog_content = "시끄럽게 굴지 마! 얌전하게 지하로 돌아가라고!",
  ui_story_1_8_B1_dialog_content = "그륵, 그아악...",
  ui_story_1_8_B2_dialog_content = "뭔가... 말을 하고 있는 것 같은데?",
  ui_story_1_8_B3_option_content = "끝장내버려, 바이스.",
  ui_story_1_8_B4_option_content = "(강제 감응!)",
  ui_story_1_8_B6_dialog_content = "속사 감지!",
  ui_story_1_8_B7_dialog_content = "녀석이 하는 말이 무슨 뜻이든, 별로 알고 싶지 않아...",
  ui_story_1_8_B8_dialog_content = "냄새가 너무 지독하다고...!",
  ui_story_1_8_B9_dialog_content = "이건 <color=#FFB400>다크매터</color>의 냄새야. 모든 암귀가 이런 에너지를 통해 움직이고 있어.",
  ui_story_1_8_B10_dialog_content = "누구든 너무 많이 접하면 구역질이 날 거야...",
  ui_story_1_8_B11_dialog_content = "끼익... 키이익...",
  ui_story_1_8_B12_dialog_content = "역시나... 암귀들의 언어는 전혀 알아들을 수 없네...",
  ui_story_1_8_B13_dialog_content = "지금까진 아직 다른 생물과 감응해 본 적은 없었어...\n역시 아직은 능력을 사용하는 게 능숙하지 않아서일까?",
  ui_story_1_8_B14_dialog_content = "...<color=#FFB400>아이</color>...<color=#FFB400>테르</color>?",
  ui_story_1_8_B15_dialog_content = "......?",
  ui_story_1_8_B16_dialog_content = "캬아악...",
  ui_story_1_8_B17_dialog_content = "죽었어...? 아쉽지만 더 많은 정보는 읽어낼 수 없었어. 하지만 이 녀석의 감정은 무척 강렬했어.",
  ui_story_1_8_B18_dialog_content = "죽음에 대한 공포보단 오히려... 의아해하는 것 같았는데, 왜지?",
  ui_story_1_8_22_dialog_content = "우리가... 고위 암귀를 이기다니...",
  ui_story_1_8_23_dialog_content = "설마 나도 모르는 사이에 강해진 건가?",
  ui_story_1_8_24_dialog_content = "정신 차려. PlayerName 아니었으면 넌 어디로 가야 할지도 몰랐을걸.",
  ui_story_1_8_25_dialog_content = "PlayerName 씨가 루미나를 감지하는 능력은 정말 신기하군요.",
  ui_story_1_8_A3_dialog_content = "솔직히 저도 일부 고참 병사들의 말을 통해서만 들었을 뿐입니다만.",
  ui_story_1_8_26_dialog_content = "그 당시 아이테르가 우리 군과 함께했던 전투에선 모두 승리할 수 있었다고 했는데,\n아무래도 과장이 아니었던 모양입니다.",
  ui_story_1_8_27_dialog_content = "이 앞에 출구가 있어. 그럼 얼른 이곳을 떠나자!",
  ui_story_1_8_28_dialog_content = "PlayerName, 몸은 괜찮아?",
  ui_story_1_8_B19_dialog_content = "나쁘지 않아. 그것보다... 혹시... 내가 주의해야 할 점은 없을까?",
  ui_story_1_8_B20_dialog_content = "무슨 얘기야?",
  ui_story_1_8_B21_dialog_content = "난 줄곧 콜로서스에서만 살았잖아. 그래서 바깥세상이 실제로 어떤지는 전혀 몰라...",
  ui_story_1_8_B22_dialog_content = "혹시 숨을 참아야 해?",
  ui_story_1_8_B23_dialog_content = "공기 중에 미지의 세균이 있다거나?",
  ui_story_1_8_B24_dialog_content = "햇빛에 적응하려면 눈을 감는 게 좋겠지?",
  ui_story_1_8_B25_dialog_content = "아, 역시 얼굴을 가리는 편이 좋으려나...",
  ui_story_1_8_B26_dialog_content = "...이 녀석, 17년 동안 무슨 생각을 하며 살았는지 알 것 같아.",
  ui_story_1_8_B27_dialog_content = "아하하, 그 정도는 아니야. 내가 하는 것처럼 하면 돼.\n바깥세상은 네가 상상했던 것처럼 이상한 곳이 아냐.",
  ui_story_1_8_B28_dialog_content = "자, 손 이리 줘.",
  ui_story_1_8_29_dialog_content = "<color=#FFB400>새로운 세계</color>...",
  ui_story_1_8_30_dialog_content = "──?!",
  ui_story_1_8_31_dialog_content = "바이스... 우리 큰일 난 것 같아...",
  ui_story_1_8_32_dialog_content = "말도 안 돼, <color=#FFB400>암귀 군단</color>이잖아?! 어째서 여기 있는 건데...?!",
  ui_story_1_8_33_dialog_content = "다들 어서 돌아가! 입구를 막아야 해!",
  ui_story_1_8_34_dialog_content = "이쪽으로 올 때만 해도 분명히 없었는데... 취약한 벽면은 제가 강화하겠습니다!",
  ui_story_1_8_A4_dialog_content = "하지만 이렇게 되면 다시 나가기 어려워질 겁니다. 바이스 중위님!",
  ui_story_1_8_36_dialog_content = "어째서 암귀가 저렇게 많은 거야... 여기는 전선도 아니잖아... 저 규모는 대체 뭐냐고!",
  ui_story_1_8_37_dialog_content = "진정하십시오, 바이스 중위님. 아무래도 대량의 암귀가 전선을 넘어 이곳까지 온 것 같습니다.",
  ui_story_1_8_38_dialog_content = "그게 문제야. 녀석들이 어떻게 일루미나의 봉쇄를 뚫은 거지?",
  ui_story_1_8_39_dialog_content = "어쩌면 지면을 넘나들 수 있는 운송 수단이 있을지도...",
  ui_story_1_8_40_dialog_content = "저렇게 많은 암귀를 태울 수 있는 게 대체 뭔데? 설마 콜로서스가 하나 더 있는 건 아니겠지?\n그렇다면 우연이라고 하기엔 너무하잖아?",
  ui_story_1_8_41_dialog_content = "내가 괜한 생각을 한 건지도 몰라. 하지만... 이곳을 벗어날 방법은 역시 하나밖에 없겠어.",
  ui_story_1_8_42_dialog_content = "<color=#FFB400>이 콜로서스를 가동</color>하는 거야.",
  ui_story_1_8_44_dialog_content = "하지만 한 번도 성공한 적 없다고 했잖아...",
  ui_story_1_8_45_dialog_content = "다른 방법은 없어. 한 번 더 해보는 수밖에.",
  ui_story_1_8_46_dialog_content = "끝내 콜로서스 가동조차 할 수 없다면 그게 무슨 아이테르야...",
  ui_story_1_8_47_dialog_content = "하지만 너 벌써 한 번 기절했었잖아... 버틸 수 있겠어?",
  ui_story_1_8_48_dialog_content = "설마 억지로 가동하다가 네 머리가... 폭발하거나 하는 건 아니지?",
  ui_story_1_8_49_dialog_content = "걱정해 줘서 고마워. 하지만 그래도 해보는 수밖에 없어!",
  ui_story_1_8_50_dialog_content = "......",
  ui_story_1_8_51_dialog_content = "바이스... 너 지금 설마...",
  ui_story_1_8_52_dialog_content = "맞아, 이론적으론 나도 도와줄 수 있어. 어디까지나 이론상이지만 말이야.",
  ui_story_1_8_53_dialog_content = "그게 무슨 말이야?",
  ui_story_1_8_54_dialog_content = "좋아! 난 준비됐어! 무슨 문제라도 생긴다면 임기응변으로 대응하면 돼!\n난 해결 못 할 문제는 없다고 믿어!",
  ui_story_1_8_55_dialog_content = "지금까지는 너 혼자였지만, 이번에는 우리도 있으니까, 어쩌면 쉽게 해낼 수도 있잖아?",
  ui_story_1_8_56_dialog_content = "어떻게 그렇게 자신할 수 있는 건데?",
  ui_story_1_8_57_dialog_content = "당연하지. 난 낙관주의자거든, PlayerName.",
  ui_story_1_8_59_dialog_content = "이 정도 고난은 여정을 시작하는 시련일 뿐이야! 그리고 넌 이제 더는 혼자가 아니야!",
  ui_story_1_8_60_dialog_content = "...좋아, 그럼 같이 함교로 가자!",
  ui_story_1_8_61_dialog_content = "PlayerName...",
  ui_story_1_8_62_dialog_content = "이번에는 널 꼭 가동하겠어, 스카이워커!",
  ui_story_1_9_1_dialog_content = "<color=#e8d9bb>제어 시스템 점검... 이상 무. 가동 중...</color>",
  ui_story_1_9_2_dialog_content = "<color=#e8d9bb>바이오 모듈 점검... 이상 발견, 빈사 상태.</color>",
  ui_story_1_9_3_dialog_content = "<color=#e8d9bb>생명유지 시스템 점검... 중단 상태.</color>",
  ui_story_1_9_4_dialog_content = "<color=#e8d9bb>엔진 점검... 이상 무. 가동 개시...</color>",
  ui_story_1_9_5_dialog_content = "<color=#e8d9bb>10%... 23%...</color>",
  ui_story_1_9_6_dialog_content = "<color=#e8d9bb>76%... 85%...</color>",
  ui_story_1_9_7_dialog_content = "<color=#e8d9bb>가동 실패. 누적 실패 횟수, 3922회.</color>",
  ui_story_1_9_8_dialog_content = "역시나 똑같아... 안 된다고...",
  ui_story_1_9_10_dialog_content = "어째서... 대체 왜 안 되는 건데?! 대체 뭐가 문제인 거냐고...",
  ui_story_1_9_11_dialog_content = "으윽! 또, 무리한 건가...",
  ui_story_1_9_12_dialog_content = "구구... PlayerName, 괜찮은 거야...?",
  ui_story_1_9_13_dialog_content = "바이스, 네게 확신이 있다면, 지금이 바로 그 타이밍인 것 같아.",
  ui_story_1_9_14_dialog_content = "응! 그러니까 이 「피아노」처럼 생긴 게 콜로서스의 컨트롤러인 거지?",
  ui_story_1_9_15_dialog_content = "나랑 같이 콜로서스를 가동해 보자, 조종사.",
  ui_story_1_9_16_dialog_content = "같이...? 바이스, 넌 오로리안이잖아. 감응 능력이 없다고...",
  ui_story_1_9_17_dialog_content = "하지만 너한테 힘이 될 순 있을 거야. 내가... 도와줄게.",
  ui_story_1_9_18_dialog_content = "......?",
  ui_story_1_9_19_dialog_content = "날 믿어, PlayerName. 나와 넌 사실... 비슷한 점들이 있거든.",
  ui_story_1_9_21_dialog_content = "말하자면 길어. 나중에 기회가 되면 얘기해 줄게!",
  ui_story_1_9_22_dialog_content = "...하지만 정말 이 컨트롤러를 어떻게 사용하는지 알고 있는 거야?",
  ui_story_1_9_23_dialog_content = "물론이지! 내가 콜로서스에 대해 어느 정도 알고 있다는 걸 잊지 말라고!",
  ui_story_1_9_24_dialog_content = "게다가 일루미나에서도 계속 「콜로서스 재건 및 조종사 육성」 계획을 진행해 왔거든. 아쉽게도 난...",
  ui_story_1_9_25_dialog_content = "아무튼 우리 둘이서 힘을 합치면 엔진을 가동할 수 있을지도 몰라!",
  ui_story_1_9_26_dialog_content = "만약 문제가 생긴다면 우린...|\n네 말처럼 「머리가 폭발」할지도 몰라.",
  ui_story_1_9_27_dialog_content = "그래도 지금은 이 방법뿐이야. 위험이 있더라도 시도해 보는 수밖에 없어.",
  ui_story_1_9_28_dialog_content = "알겠어. 이렇게 된 이상 이제 물러설 곳도 없어. 자, 여기 와서 앉아.",
  ui_story_1_9_29_dialog_content = "내가 어떻게 「연주」하는지 알려줄게.",
  ui_story_1_9_30_dialog_content = "<color=#e8d9bb>엔진 점검... 이상 무. 가동 개시...</color>",
  ui_story_1_9_B1_dialog_content = "조종사, 그럼 어떻게 하면 될까?",
  ui_story_1_9_B2_dialog_content = "간단해. 피아노를 연주하듯이 하면 돼.",
  ui_story_1_9_B3_dialog_content = "하지만 내 눈엔 악보가 보이지 않는걸. 내가 눌러야 할 건반을 알려줄래?",
  ui_story_1_9_31_dialog_content = "<color=#e8d9bb>16%... 33%...</color>",
  ui_story_1_9_B4_dialog_content = "느껴져... 에너지가 요동치는 게...",
  ui_story_1_9_B5_dialog_content = "지금 루미나를 주입하고 있는 거야?",
  ui_story_1_9_B6_dialog_content = "응. 마치 대화하는 것처럼. 비록 콜로서스의 언어는 이해할 수 없지만 말이야.",
  ui_story_1_9_B7_dialog_content = "건반의 언어가 바로 콜로서스의 언어야, 바이스.",
  ui_story_1_9_32_dialog_content = "<color=#e8d9bb>89%... 97%...</color>",
  ui_story_1_9_B8_dialog_content = "얼마 안 남았어... 정말... 믿을 수가 없어...",
  ui_story_1_9_B9_dialog_content = "조종사, 악보도 곧 마지막 장이지?",
  ui_story_1_9_B10_dialog_content = "맞아. 이제 콜로서스의 가동 명령을 완성하자, 바이스.",
  ui_story_1_9_B11_dialog_content = "마지막 음표...",
  ui_story_1_9_33_dialog_content = "<color=#e8d9bb>100%, 가동 성공.</color>",
  ui_story_1_9_34_dialog_content = "어떻게 된 거지?! 주변이 밝아졌습니다!",
  ui_story_1_9_35_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_1_9_36_dialog_content = "함교가 빛나고 있어...?",
  ui_story_1_9_37_dialog_content = "<size=45>서, 서...성공했어!</size>",
  ui_story_1_9_38_dialog_content = "...!",
  ui_story_1_9_40_dialog_content = "PlayerName! 해내셨군요. 여기까지 해낼 줄은 정말 몰랐습니다.",
  ui_story_1_9_41_dialog_content = "이게 바로... 함교의 모습이구나! 전부 반짝거려!",
  ui_story_1_9_42_dialog_content = "너무 아름다워. 이게 루미나의 색인 거야?",
  ui_story_1_9_A1_dialog_content = "아니면... 설마 오로라?!",
  ui_story_1_9_43_dialog_content = "정말 대단해! 이런 건 처음 봐...",
  ui_story_1_9_44_dialog_content = "이게 진짜... 하늘이라고? 너무 눈이 부셔, 하지만 정말 아름다워...",
  ui_story_1_9_45_dialog_content = "우리가 정말 해낼 줄은 몰랐어! 이렇게 힘이 넘치는 느낌은 처음이야!",
  ui_story_1_9_46_dialog_content = "정말 「살아났구나」, 스카이워커!",
  ui_story_1_9_47_dialog_content = "그렇습니다. 에너지가 몸 곳곳으로 퍼지고 있습니다. 하지만 이륙을 위해선 아직 시간이 더 필요합니다.",
  ui_story_1_9_48_dialog_content = "주변에 적이 있을지도 모릅니다. 경계를 늦춰서는 안 됩니다.",
  ui_story_1_9_49_dialog_content = "역시 오랫동안 움직이질 않았으니까, 몸을 좀 풀어야 되는 거야?",
  ui_story_1_9_50_dialog_content = "하하, 그렇게 이해해도 좋습니다. 당신 모습은 무척 편안해 보이는군요.",
  ui_story_1_9_51_dialog_content = "PlayerName! 몸은 괜찮아?",
  ui_story_1_9_52_dialog_content = "지금 아주 좋아, 바이스! 전혀 불편하지 않아!",
  ui_story_1_9_A2_dialog_content = "난 지금까지 과연 어떤 계기로 이곳을 떠나서, 다시 세상으로 돌아가게 될지 계속 상상해 왔어.",
  ui_story_1_9_A3_dialog_content = "하지만 그게 오늘처럼 이뤄질 줄은 정말 몰랐어. 그것도 오로리안들과 함께라니...",
  ui_story_1_9_53_dialog_content = "나 혼자선 상상조차 못 했던 일을 우리가 같이 해낸 거야!",
  ui_story_1_9_54_dialog_content = "나도 정말 생각도 못 했어...",
  ui_story_1_9_A4_dialog_content = "온전한 콜로서스와 눈앞의 이 「오로라」까지...",
  ui_story_1_9_55_dialog_content = "난 어제까지만 해도 혼자서는 암귀 하나 상대하지 못하는 일루미나의 말단 장교였는걸~",
  ui_story_1_9_56_dialog_content = "아... 갑자기 어지러워... 또... 그 꿈이... 보여...",
  ui_story_1_9_58_dialog_content = "<color=#FFB400>슈모르</color>, 어째서!",
  ui_story_1_9_59_dialog_content = "슈모르, 이 배신자! 힘을 위해 동족을 배신한 거냐!",
  ui_story_1_9_60_dialog_content = "배신... 투항... 그건 모두 위선자와 겁쟁이의 묘비명일 뿐이야.",
  ui_story_1_9_61_dialog_content = "헤븐즈 밸리는 이미 부패했어. 난 내 방식대로 당신들이 말하는 가치를 실현하겠어.",
  ui_story_1_9_62_dialog_content = "발버둥 치지 마. 난 단순히 약육강식의 논리를 충실하게 따르려는 것뿐이니까.",
  ui_story_1_9_63_dialog_content = "안 돼!",
  ui_story_1_9_64_dialog_content = "... 또 그 꿈입니까?",
  ui_story_1_9_65_dialog_content = "아니... 더 길었어. 스카이워커, 이건 대체 무슨 의미인 거야?\n어째서 이런 장면들이 자꾸 나한테 보이는 거냐고...",
  ui_story_1_9_A5_dialog_content = "......",
  ui_story_1_9_66_option_content = "일단은 신경 안 쓸래.",
  ui_story_1_9_A6_option_content = "이건 절대 환영이 아니야!",
  ui_story_1_9_67_option_content = "나한테 숨기는 거 있어?",
  ui_story_1_9_B12_dialog_content = "난... 이제 더는 이런 무의미한 환영에 얽매이지 않겠어.",
  ui_story_1_9_B13_dialog_content = "이제 막 가동에 성공했으니까, 콜로서스의 안정 유지를 위해 정신을 집중해야 해. 어서...",
  ui_story_1_9_B14_dialog_content = "PlayerName, 비록 힘드시겠지만, 당신이 보신 광경들... 그 안에서 답을 찾으실 수 있을 겁니다.",
  ui_story_1_9_B15_dialog_content = "저 또한 한 가지 답을 찾고 있습니다. 그리고 우린 이제 준비가 되었습니다.",
  ui_story_1_9_B16_dialog_content = "또 어려운 말을 하네, 스카이워커. 하지만 어쨌든... 오늘 난 해냈어.",
  ui_story_1_9_B17_dialog_content = "맞습니다. 아이테르로서 계속 나아가십시오. 푸른 하늘이 눈앞에 있습니다.",
  ui_story_1_9_B18_dialog_content = "너무 생생했어... 분명히 다 있었던 일이야. 환영이 아니라고! 정말 일어났던 일인 거지? 그렇지?!",
  ui_story_1_9_B19_dialog_content = "그것들이 당신의 의식 속에 존재하는 한, 현실에도 흔적을 남겼을 것입니다.\n그 점은 부인할 수 없겠군요.",
  ui_story_1_9_B20_dialog_content = "그렇게 돌려서 말하지 마. 스카이워커... 난 답이 필요해!",
  ui_story_1_9_B21_dialog_content = "유감입니다. 저도 알려드리고 싶지만, 불가능합니다.",
  ui_story_1_9_B22_dialog_content = "전 기억이 없습니다. 모든 것이 그날 밤 사라졌습니다.\n제가 유일하게 기억하는 것은 그저 당신을 살아남게 하라는 명령뿐입니다.",
  ui_story_1_9_B23_dialog_content = "......",
  ui_story_1_9_B24_dialog_content = "그것이 진실이든, 환상이든, 이제 출발할 때가 되었습니다.",
  ui_story_1_9_B25_dialog_content = "게다가 당신도 이제 직접 답을 찾아 나설 준비가 되었습니다. 그렇지 않습니까?",
  ui_story_1_9_B26_dialog_content = "대답해 줘, 스카이워커. 대체 뭘 숨기고 있는 거야... 내가 본 것들이 진짜냐고!",
  ui_story_1_9_B27_dialog_content = "전 모릅니다, PlayerName.",
  ui_story_1_9_B28_dialog_content = "농담하지 마...",
  ui_story_1_9_B29_dialog_content = "전 당신을 속인 적이 없습니다.\n전 당시의 모든 것을 기억의 바다에서 「잃어」버렸습니다. 그게 전부입니다.",
  ui_story_1_9_B30_dialog_content = "저는 줄곧 당신에게 애매모호한 희망이 아닌, 확실한 답을 드리고 싶었습니다.\n하지만 아무래도 우리의 운명이 엇갈릴 순간이 찾아온 모양입니다.",
  ui_story_1_9_B31_dialog_content = "새로운 동료의 도움을 받는다면, 당신은 이제 직접 답을 찾을 준비가 되었습니다. 그렇지 않습니까?",
  ui_story_1_9_B32_dialog_content = "하지만 그 답이란 게 대체 뭔데...",
  ui_story_1_9_B33_dialog_content = "내 종족, 그리고 헤븐즈 밸리, 만약 그 답이 내가 가장 두려워하던 것이라면...",
  ui_story_1_9_B34_dialog_content = "이 모든 게 무슨 의미가 있을까?",
  ui_story_1_10_1_dialog_content = "<color=#e8d9bb>어딘가의 장소</color>",
  ui_story_1_10_2_dialog_content = "『보고드립니다... 몇몇 오로리안이 콜로서스 스카이워커호의 내부로 진입했고,\n안에는 아이테르가 있었습니다...』",
  ui_story_1_10_3_dialog_content = "『오로리안들이 너무 강한 탓에, 카라켄은 진리의 명령을 완수하지 못했습니다...』",
  ui_story_1_10_A1_dialog_content = "『이에 카라켄은 죄인으로서, 달게 벌을 받고자 어머니께서 계시는 피안으로 돌아왔습니다...』",
  ui_story_1_10_4_dialog_content = "『<color=#FFB400>이클립스</color>여, 영원하라.』",
  ui_story_1_10_5_dialog_content = "이게 카라켄이 남긴 「유언」이야? 「오로리안과 아이테르한테 졌다」고?",
  ui_story_1_10_6_dialog_content = "흥, <color=#FFB400>그때</color> 놓친 녀석이 있었을 줄은 몰랐네. 하나도 남기지 않았다고 생각했는데.",
  ui_story_1_10_A2_dialog_content = "내가 직접 가서 그 아이테르 녀석을 처리하는 게 좋겠지?",
  ui_story_1_10_7_dialog_content = "자신의 <color=#FFB400>동족</color>을 모조리 없애는 게 그렇게 즐겁나?",
  ui_story_1_10_8_dialog_content = "... 동족? 그거 정말 오랜만에 듣는 말이네.",
  ui_story_1_10_9_dialog_content = "네가 해야 할 더 중요한 일이 있을 텐데. 그런 쓸데없는 일에 정신 팔지 말라고.",
  ui_story_1_10_10_dialog_content = "우리가 원하는 건 그 콜로서스에 없어. 시간 낭비하지 마. 얼마나 더 기다릴 셈이야?",
  ui_story_1_10_11_dialog_content = "그 아이테르라면 그냥 <color=#FFB400>맥거핀</color>한테 맡겨. 마침 그 주변에 있잖아?",
  ui_story_1_10_12_dialog_content = "지금 그 녀석한테 카라켄의 뒤처리를 맡기겠다는 거야?",
  ui_story_1_10_13_dialog_content = "그 오로리안들에겐 맥거핀이면 충분해. 게다가 산채로 데려오면 더 좋겠지...",
  ui_story_1_10_14_dialog_content = "녀석에겐 일을 마치고 즉시 합류하라고 할 거야. 일을 그르치면 안 되니까.",
  ui_story_1_10_A3_dialog_content = "녀석은 너와는 다르게 말을 잘 듣거든. 좀 보고 배워 봐.",
  ui_story_1_10_15_dialog_content = "...흥, 그 일에 비하면 정체불명의 아이테르 정도는 신경 쓸 가치도 없어.",
  ui_story_1_10_16_dialog_content = "하지만 날 얕보지 마. 기회만 되면 네 목을 비틀어버릴 테니까.",
  ui_story_1_10_17_dialog_content = "하.하.하... 이번 농담은 꽤 재밌었어. <color=#FFB400>슈모르</color>.",
  ui_story_1_10_18_dialog_content = "맥거핀, 그럼 여기까지만 데려다줄게. 일을 망치면 어떻게 될지는 알고 있겠지?",
  ui_story_1_10_19_dialog_content = "물론입니다. 맥거핀은 그 무엇도 두렵지 않습니다...",
  ui_story_1_10_21_dialog_content = "목표가 눈앞에 있군. 악취 나는 뼈, 도망친 콜로서스... 감히 우리의 땅에 모습을 드러내다니.",
  ui_story_1_10_22_dialog_content = "녀석이 이륙하기 전에 바닥에서 꼼짝 못 하게 만들어라!",
  ui_story_1_10_23_dialog_content = "그리고 저 돼지우리를 샅샅이 뒤져 아이테르를 잡아다 그분께 바친다!",
  ui_story_1_10_24_dialog_content = "<size=45>어머니의 이름으로. 진격하라!</size>",
  ui_story_1_10_25_dialog_content = "저 규모라니... 진심인가.",
  ui_story_1_10_26_dialog_content = "콜로서스가 가동된 후, 저흰 적들의 시야에 완전히 노출됐습니다.\n주변의 모든 암귀가 이곳으로 몰려들고 있습니다.",
  ui_story_1_10_27_dialog_content = "어쩔 수 없는 일이야. 그래서, 스카이워커호는 예열 시간이 더 필요한 거지?",
  ui_story_1_10_B1_dialog_content = "......",
  ui_story_1_10_B2_dialog_content = "PlayerName?",
  ui_story_1_10_B3_dialog_content = "응? 미안. 방금... 딴생각을 하고 있었어.",
  ui_story_1_10_B4_dialog_content = "...스카이워커호의 예열에 시간이 얼마나 더 필요할지 좀 물어보려고.",
  ui_story_1_10_28_dialog_content = "정확히는 모르겠어. 스카이워커호가 움직이려면 시간이 조금 더 필요할 것 같아.\n그래도 하늘로 날아오르고 나면 우린 안전해질 거야.",
  ui_story_1_10_30_dialog_content = "시간을 벌어주십시오, PlayerName.",
  ui_story_1_10_31_dialog_content = "이제 곧 모두를 데리고 떠날 수 있습니다... 새로운 세계의 하늘이라니, 정말 기대되는군요.",
  ui_story_1_10_32_dialog_content = "우리가 스카이워커호를 지켜야만 해! 콜로서스가 날아오를 때까지만 버티면 돼!",
  ui_story_1_10_33_dialog_content = "좋아! 그럼 흩어져서 모든 입구를 지키는 거야!",
  ui_story_1_10_34_dialog_content = "PlayerName, 넌 함교에 남아줘!",
  ui_story_1_10_35_dialog_content = "아무래도 「시가전」을 준비해야겠군요. 병사들은 날 따라 이쪽으로!",
  ui_story_1_10_A4_dialog_content = "무기를 장전해라. 스카이워커호가 예열할 시간을 벌어야 한다!",
  ui_story_1_10_36_dialog_content = "여명의 빛을 위하여!",
  ui_story_1_10_37_dialog_content = "여명의 빛을 위하여!",
  ui_story_1_10_38_dialog_content = "...무슨 빛을 위하여?",
  ui_story_1_14_1_dialog_content = "『콜로서스의 예열이 끝나간다! 당장 파괴하라! 콜로서스를 오로리안들의 무덤으로 만들어라!』",
  ui_story_1_14_2_dialog_content = "『우린 이미 콜로서스의 각 구역에 돌입했다. 하지만 함교의 격렬한 저항 탓에 손실이 막중하다...』",
  ui_story_1_14_3_dialog_content = "『그래서? 우리가 죽음을 두려워하는 존재였던가?』",
  ui_story_1_14_4_dialog_content = "『물론 아니지!』",
  ui_story_1_14_5_dialog_content = "『그럼 발톱을 날카롭게 세워라. 더 이상의 망설임은 더는 용납하지 않는다.』",
  ui_story_1_14_A1_dialog_content = "『죽더라도 쓰러지는 순간까지 적의 배를 가르는 거다!』",
  ui_story_1_14_6_dialog_content = "『안내해라. 저항하는 오로리안 놈들을 내가 직접 손봐줄 테니...!』",
  ui_story_1_14_7_dialog_content = "<color=#e8d9bb>콜로서스 내부</color>",
  ui_story_1_14_8_dialog_content = "모두 어서 쉬어라. 암귀가 곧 공격해 올 테니, 탄약을 점검하고 사상자를 확인해라.",
  ui_story_1_14_9_dialog_content = "보고드립니다! 잔탄 11발, 참전 6명, 경상 4명, 그리고 2명은...",
  ui_story_1_14_10_dialog_content = "...음, 알았다.",
  ui_story_1_14_11_dialog_content = "대장님, 역시 후퇴하는 게...",
  ui_story_1_14_12_dialog_content = "그럴 순 없다! 지금 바이스 중위님과 일행들이 가장 중요한 함교를 지키고 있다.\n우린 외부의 다른 암귀를 저지해야 해!",
  ui_story_1_14_13_dialog_content = "모두 살아남기 위해 최선을 다하고 있다. 힘든 건 모두 똑같단 말이다! 그러니 그런 말은 하지 말도록. 알겠나, 제군!",
  ui_story_1_14_14_dialog_content = "모두 정신 똑바로 차려라! 탄약이 없다면 칼을 뽑아서라도 맞서 싸우는 거다!",
  ui_story_1_15_1_dialog_content = "도망치게... 둘 줄 알고!",
  ui_story_1_15_2_dialog_content = "좋았어! 이제 함교 쪽 암귀는 전부 해치웠어!",
  ui_story_1_15_3_dialog_content = "PlayerName, 네 지휘도 점점 능숙해지는걸!",
  ui_story_1_15_4_dialog_content = "오늘은 기술도 그렇고, 두뇌 「회전 속도」도 그렇고, 눈에 띌 정도로 성장한 느낌이야...",
  ui_story_1_15_5_dialog_content = "콜로서스의 다른 곳 상황은 어떨지 모르겠네...",
  ui_story_1_15_6_dialog_content = "스카이워커, 얼마나 남았어?",
  ui_story_1_15_7_dialog_content = "마침 지금 엔진 점화를 마쳤습니다. 죄송합니다만. 모두 꽉 잡아주십시오.|\n<size=45>콜로서스, 이륙합니다!</size>",
  ui_story_1_15_8_dialog_content = "나, 날아오른 거야?!",
  ui_story_1_15_9_dialog_content = "우와앗! 컨트롤러에서 떨어질 뻔했네... 바깥 좀 봐! 엄청 높아! 우리 지금... 날고 있는 거야?!",
  ui_story_1_15_10_dialog_content = "다들 뭐라도 잡아!",
  ui_story_1_15_11_dialog_content = "아! 아야! 바이스! 너 지금 내 머리 잡고 있어!",
  ui_story_1_15_A1_dialog_content = "하늘... 정말 오랜만이로군요. 마지막 비행은 피비린내가 진동하는 밤하늘이었습니다만...",
  ui_story_1_15_A2_dialog_content = "PlayerName, 속력을 더 내도 되겠습니까?",
  ui_story_1_15_A3_dialog_content = "물론이야, 스카이워커. 계속 날아올라 줘!",
  ui_story_1_15_12_dialog_content = "최대 출력으로 날아오르는 거야! 암귀 녀석들을 모두 떨쳐버릴 수 있게!",
  ui_story_1_15_13_dialog_content = "알겠습니다. 가장 높은 하늘까지 날아올라 보겠습니다.",
  ui_story_1_15_14_dialog_content = "바이스 중위님! 이 진동은 대체?!",
  ui_story_1_15_15_dialog_content = "마침 연락하려고 했어! 드디어 이륙에 성공했어!",
  ui_story_1_15_16_dialog_content = "그렇군요... 정말 다행입니다... 전... 이미 끝나버린... 줄... 알았...습니다...",
  ui_story_1_15_17_dialog_content = "끝나다니? 무슨 일이야? 너희 괜찮은 거야?!",
  ui_story_1_15_18_dialog_content = "커다란 녀석이... 들어왔습니다... 저흰 녀석을... 막지 못했고, 많은 병사가...",
  ui_story_1_15_19_dialog_content = "녀석은 함교로 곧장 갔습니다... 고위 암귀인 것 같습니다... 죄송합니다...",
  ui_story_1_15_20_dialog_content = "설마 강력한 적이 나타난 건가?! 아직 안 끝났어, 다들 경계를 유지해!",
  ui_story_1_15_21_dialog_content = "어, 어째서 온도가 갑자기 내려간 거지? 추워...",
  ui_story_1_15_22_dialog_content = "온도가 아니야, 도브. 이건 다크매터의 기운이야... 다들 조심해. 적이 이미 나타났어.",
  ui_story_1_15_23_dialog_content = "<color=#e8d9bb>갑자기 매서운 추위가 몰아쳤다──</color>",
  ui_story_1_15_25_dialog_content = "관짝이 하늘을 날게 만들다니, 쓸모없는 것들. 하지만 네놈들도 여기까지다.",
  ui_story_1_15_26_dialog_content = "또 고위 암귀인가?!",
  ui_story_1_15_27_dialog_content = "내겐 <color=#FFB400>맥거핀</color>이라는 이름이 있다, 오로리안이여. 어머니께서 내리신 이름이지...",
  ui_story_1_15_28_dialog_content = "이 이름을 기억해라. 너희가 진리의 피안에 닿았을 때 인도해줄 등불이 될 테니!",
  ui_story_1_15_29_dialog_content = "이 암귀는 왜 말을 할 수 있는 거야? 「어머니」? 「진리」? 그게 무슨 뜻인데?",
  ui_story_1_15_30_dialog_content = "녀석을 상대해 주지 마, PlayerName! 통용어를 할 줄 아는 암귀는 아주 적어. 심상치 않은 녀석이야!",
  ui_story_1_15_31_dialog_content = "우리가 통용어를 익힌 건 오로리안들에게 깨달음을 주기 위해서다.\n허나 이 개미 놈들은 역시나 우둔하고 어리석군...",
  ui_story_1_15_32_dialog_content = "곧 죽을 자들에 대한 존중은 이걸로 충분하겠지. 이제...",
  ui_story_1_15_33_dialog_content = "죽어라.",
  ui_story_1_15_34_option_content = "그건 네 얘기겠지!",
  ui_story_1_15_35_option_content = "다들 준비해!",
  ui_story_1_15_36_dialog_content = "감히... 내게 상처를 입히다니! 자비는 여기까지다!",
  ui_story_1_15_37_dialog_content = "고통 없는 죽음을 선사하려 했거늘, 봐주는 것도 한계가 있다.",
  ui_story_1_15_38_dialog_content = "<color=#FFB400>슈모르 님</color>... 이 맥거핀에게 정말 어려운 임무를 주셨군요.",
  ui_story_1_15_39_dialog_content = "<color=#FFB400>슈모르</color>...?! 내가 꿈속에서 들었던 이름이잖아!\n네가 그 이름을 어떻게 아는 거지? 그게 대체 누구인 건데!",
  ui_story_1_15_40_dialog_content = "아이테르, 당시의 일에 대해 아무것도 모르는 건 아닌 모양이군... 허나 그게 무슨 의미가 있지?",
  ui_story_1_15_B1_dialog_content = "네 종족은 우리가 모조리 죽였다. 살아남아서 만족스러운가?",
  ui_story_1_15_B2_dialog_content = "뭐...라고?",
  ui_story_1_15_B3_dialog_content = "이상한 질문이군. 내 말을 알아들을 지능은 있으리라 생각하는데 말이지.",
  ui_story_1_15_B4_dialog_content = "네 종족은 <color=#FFB400>모두 죽었다</color>.",
  ui_story_1_15_B5_dialog_content = "헤븐즈 밸리는 이미 존재하지 않는다.",
  ui_story_1_15_B6_dialog_content = "불바다, 울부짖음, 하나도 남기지 않고 모조리 짓밟아서...|\n없애버렸다.",
  ui_story_1_15_B7_dialog_content = "...아...아니, 아니야.",
  ui_story_1_15_B8_dialog_content = "그럴 리 없어...",
  ui_story_1_15_B9_dialog_content = "입 닥쳐, 암귀! 네가 뭘 알아?!",
  ui_story_1_15_B10_dialog_content = "왜냐하면 내가 그 자리에 있었기 때문이지. <color=#FFB400>우리</color> 모두 말이야...\n그토록 성대한 의식에 누가 빠질 수 있겠나?",
  ui_story_1_15_B11_dialog_content = "언젠가 오로리안의 방어선을 돌파해, 너희에게도 동일한 「멸족의 의식」을 치러주마.",
  ui_story_1_15_41_dialog_content = "PlayerName, 저 암귀 말을 믿지 마!",
  ui_story_1_15_42_dialog_content = "너희가 믿고 안 믿고는 상관없다. 어차피 모두 죽을 테니 말이다.",
  ui_story_1_15_44_dialog_content = "그렇게 될 줄 알고?!",
  ui_story_1_15_46_dialog_content = "어리석구나. 목숨이라도 부지할 수 있었던 녀석이 죽음을 자초하다니!",
  ui_story_1_15_47_dialog_content = "으악...!",
  ui_story_1_15_48_dialog_content = "의미 없는 행동이군. 내게 짓밟히는 게 네놈의 계획인가?",
  ui_story_1_15_49_dialog_content = "포...<color=#FFB400>폭탄</color>이다, 멍청한 괴물 자식아...",
  ui_story_1_15_50_dialog_content = "네놈...!",
  ui_story_1_15_53_dialog_content = "<size=45>같이 지옥으로 떨어지는 거다, 멍청아.</size>",
  ui_story_1_15_54_dialog_content = "PlayerName! 여러분이 있는 위치에 폭발로 틈이 발생했습니다. 조심하십시오!",
  ui_story_1_15_55_dialog_content = "풍압이다! 휘, 휩쓸린다!",
  ui_story_1_15_56_dialog_content = "잠깐!",
  ui_story_1_15_B13_dialog_content = "대장님!",
  ui_story_1_15_B14_dialog_content = "가까이 가지 마! 내 손을 잡아! 잘못하면 빨려 나갈 거야!",
  ui_story_1_15_B15_dialog_content = "제길, 어째서 이렇게 된 거냐고... 이제 거의 끝이었는데...!",
  ui_story_1_15_57_dialog_content = "포...폭발한 거야? 저 오로리안... 어째서...",
  ui_story_1_15_A4_dialog_content = "아까 조각난 건... 그 사람 몸인 거야...?",
  ui_story_1_15_58_dialog_content = "PlayerName! 진정하십시오. 정신이 흔들리고 있습니다.",
  ui_story_1_15_A5_dialog_content = "기억 속... 동족들의 몸도...",
  ui_story_1_15_A6_dialog_content = "그렇게 다 죽은 건가... <color=#FFB400>전부 다 죽은 거야</color>? 그럼 헤븐즈 밸리 바깥에는?\n아니면 이 대륙 바깥은? 설마 내가 <color=#FFB400>마지막 아이테르인 거야</color>?",
  ui_story_1_15_A7_dialog_content = "심박수가 급상승하고 있습니다. 지난번처럼 과부하되지 않게 조심하십시오.",
  ui_story_1_15_B12_dialog_content = "아니! ...이럴 순 없어. 내가 어떻게 여기까지 왔는데...",
  ui_story_1_15_A8_dialog_content = "<size=45>웃기지 마!</size>",
  ui_story_1_15_59_dialog_content = "코, 콜로서스가 갑자기 가속하다니?! 이대로면...",
  ui_story_1_15_60_dialog_content = "아이테르! 무슨 짓을 한 거냐! 이런, 더는 붙잡을 수...",
  ui_story_1_15_61_dialog_content = "<size=45>아니야, 그럴 리 없어...</size>",
  ui_story_1_15_62_dialog_content = "<size=45>조종사, 고개 숙여!</size>",
  ui_story_1_15_63_dialog_content = "크오오오...!",
  ui_story_2_1_A1_dialog_content = "「콜로서스가 드디어 날아올랐다」",
  ui_story_2_1_A2_dialog_content = "「얼마 전만 해도, 영원히 땅속에 묻혀있을 줄 알았는데」",
  ui_story_2_1_A3_dialog_content = "「하지만 이 모든 게 이루어진 순간」",
  ui_story_2_1_A4_dialog_content = "「나의 삶은 다시 의미를 잃어버렸다」",
  ui_story_2_1_A5_dialog_content = "「아이테르는... 이미 존재하지 않기 때문이다.」",
  ui_story_2_1_1_dialog_content = "응? 일지 쓰고 있었어?",
  ui_story_2_1_3_dialog_content = "응. 습관이야. 혼자선 다른 할 일도 없거든.",
  ui_story_2_1_4_dialog_content = "일지를 쓰면 시간 개념을 유지할 수 있어. 비록 별 쓸모는 없지만 말이야...",
  ui_story_2_1_5_dialog_content = "좋은 습관인걸. PlayerName 넌 자신한테 굉장히 엄격한 사람인 것 같아...",
  ui_story_2_1_6_dialog_content = "지금 상황은 어때?",
  ui_story_2_1_B26_dialog_content = "일단 위험에선 벗어났어. 부상자 배치도 거의 끝났고.",
  ui_story_2_1_B27_dialog_content = "그... 자기 목숨을 던졌던 병사는...",
  ui_story_2_1_B28_dialog_content = "......",
  ui_story_2_1_B29_dialog_content = "시신은 회수할 수 없었어. 대신 내가 묘비를 세워줄 거야.",
  ui_story_2_1_B30_dialog_content = "......",
  ui_story_2_1_B31_dialog_content = "...누가 죽는 걸 본 건 처음이야?",
  ui_story_2_1_B32_dialog_content = "아니.",
  ui_story_2_1_B33_dialog_content = "하지만 이런 일은 몇 번을 겪어도 익숙해질 수 없어...",
  ui_story_2_1_B34_dialog_content = "그 사람의 가족들은... 어떻게 되는 거야?",
  ui_story_2_1_B35_dialog_content = "걱정 마. 가족들은 일루미나 연방에서 최선을 다해 돌볼 거야.",
  ui_story_2_1_B37_dialog_content = "우린 여명의 빛을 위해 희생한 모든 영웅을 기억할 테니까.",
  ui_story_2_1_B38_dialog_content = "미안해, PlayerName.",
  ui_story_2_1_B39_dialog_content = "왜 사과하는 건데?",
  ui_story_2_1_B40_dialog_content = "그냥 스스로 너무 미안한 마음이 들었거든. 오늘 일어난 모든 일 때문에...",
  ui_story_2_1_B41_dialog_content = "하지만 살아남은 사람이 할 수 있는 건, 떠난 이들의 희생이 헛되지 않게 앞으로 나아가는 것뿐이야.",
  ui_story_2_1_F1_dialog_content = "......",
  ui_story_2_1_7_dialog_content = "무슨 계획이라도 있어?",
  ui_story_2_1_8_dialog_content = "...잘 모르겠어.",
  ui_story_2_1_9_dialog_content = "아니면... 나랑 같이 일루미나에 가지 않을래?",
  ui_story_2_1_10_dialog_content = "너... 맥거핀이 했던 얘기... 들었어?",
  ui_story_2_1_A8_dialog_content = "들었어. 하지만 그건 녀석의 말일 뿐이야.",
  ui_story_2_1_11_dialog_content = "내 동족은 모두 죽었어. 헤븐즈 밸리는 이미 존재하지 않아.",
  ui_story_2_1_13_dialog_content = "......",
  ui_story_2_1_A9_dialog_content = "넌 돌아갈 수 있는 고향이 있고, 동족도 많이 있지만, 난...",
  ui_story_2_1_14_dialog_content = "...PlayerName, 그렇게 생각하지 마.",
  ui_story_2_1_15_dialog_content = "분명히 너처럼 살아있는 다른 아이테르들이 있을 거야!",
  ui_story_2_1_B1_dialog_content = "......",
  ui_story_2_1_B2_dialog_content = "내가 찾는 걸 도와줄게!",
  ui_story_2_1_B3_dialog_content = "미안해, 바이스. 난 그저...",
  ui_story_2_1_B4_dialog_content = "괜찮아, 이해해.",
  ui_story_2_1_B5_dialog_content = "나는 지하에서 17년을 버텼어. 그러면서 헤븐즈 밸리에 대해 17년을 상상했어.",
  ui_story_2_1_B6_dialog_content = "하지만 그 모든 게... 이미 사라져 버렸다니... 받아들일 수 없어... 절대로!",
  ui_story_2_1_B7_dialog_content = "그럼 받아들이지 마, PlayerName.",
  ui_story_2_1_B8_dialog_content = "난... 17년 전에 대체 무슨 일이 있었던 건지 알고 싶어!",
  ui_story_2_1_B9_dialog_content = "좋아! 그럼 대륙을 탐험하면서 그때의 진실을 찾아보자!",
  ui_story_2_1_B10_dialog_content = "하지만 그 전에 먼저 넌 휴식을 취해야 해. 나랑 일루미나에 가자.",
  ui_story_2_1_A10_option_content = "알았어. 일단 같이 갈게.",
  ui_story_2_1_A11_option_content = "아니, 내겐 나만의 길이 있어.",
  ui_story_2_1_A12_dialog_content = "네 말이 맞아, 바이스.",
  ui_story_2_1_A13_dialog_content = "게다가 이젠 난 갈 곳도 없으니까...",
  ui_story_2_1_A14_dialog_content = "걱정할 거 없어. 일루미나에 가면 분명히 마음에 들 거야~",
  ui_story_2_1_B11_dialog_content = "「<color=#FFB400>슈모르</color>」 말이야? ...그 이름, 내겐 멀고 낯설게 느껴져.",
  ui_story_2_1_B12_dialog_content = "계속해서 그 얼굴을 떠올리는 것 외에는 아무것도 할 수 없는걸.",
  ui_story_2_1_B13_dialog_content = "그러니 더더욱 자신과 이 콜로서스를 잘 돌봐줘야 해.",
  ui_story_2_1_B14_dialog_content = "네가 생각을 다 정리하고, 스카이워커도 제대로 정비를 마치고 나면,\n내가 다시 너랑 같이 모험을 나설게.",
  ui_story_2_1_A15_dialog_content = "어째서?",
  ui_story_2_1_A16_dialog_content = "응? 그러니까, 일루미나 연방은...",
  ui_story_2_1_A17_dialog_content = "내 말은, 왜 넌 나한테 친구가 되어주려는 건데? 왜 날 돕는 거야?",
  ui_story_2_1_A18_dialog_content = "당연한 거 아냐? 넌 내 목숨을 구했잖아!",
  ui_story_2_1_A19_dialog_content = "게다가 네 능력은 오로리안에게 무척 중요한 의미가 있어...",
  ui_story_2_1_A20_dialog_content = "그 「콜로서스 조종사」 계획인가 뭔가 하는 것 때문에?",
  ui_story_2_1_A21_dialog_content = "「콜로서스 재건 및 조종사 육성」 계획이야.",
  ui_story_2_1_A22_dialog_content = "사실은 나도 그... 아, 아니야. 아무것도 아냐!",
  ui_story_2_1_A23_dialog_content = "네가 무슨 말을 하는 건지는 잘 모르겠지만...",
  ui_story_2_1_F2_dialog_content = "난 널 믿고 싶어, 바이스.",
  ui_story_2_1_A24_dialog_content = "PlayerName... 고마워.",
  ui_story_2_1_A25_dialog_content = "좋아, 그럼 일단 가까운 일루미나 지하성부터 얼른 찾아볼까? 푹 쉬고 제대로 정비하지 않으면...",
  ui_story_2_1_A26_dialog_content = "그동안 난 끊임없이 노력해 왔어.",
  ui_story_2_1_A28_dialog_content = "매일 셀 수 없을 만큼 기절해 가면서, 콜로서스를 다시 가동하려고 시도했어.",
  ui_story_2_1_B15_dialog_content = "그리고 매일 스카이워커가 가르쳐 주는 지식을 습득했어.\n그게 무슨 쓸모가 있을지는 알 수 없었지만 말이야...",
  ui_story_2_1_B16_dialog_content = "매일 난 바깥세상을 내 눈으로 볼 날을 생각하고, 헤븐즈 밸리로 돌아갈 수 있길 빌었어.",
  ui_story_2_1_B17_dialog_content = "이해해, PlayerName. 무척 힘들었을 거야.",
  ui_story_2_1_B19_dialog_content = "난 내가 가야 할 길이 있다고 생각해.",
  ui_story_2_1_B20_dialog_content = "하지만 어디로 갈 건데?",
  ui_story_2_1_B21_dialog_content = "......",
  ui_story_2_1_B22_dialog_content = "집으로... 헤븐즈 밸리로 갈 거야.",
  ui_story_2_1_B23_dialog_content = "그리고 <color=#FFB400>슈모르</color>를 찾겠어.",
  ui_story_2_1_A29_dialog_content = "PlayerName, 너 혼자선 너무 위험해!",
  ui_story_2_1_A30_dialog_content = "위험할 거라는 건 알아. 하지만 난 진실을 알고 싶고, 집에 돌아가고 싶어.",
  ui_story_2_1_A31_dialog_content = "너도 스카이워커도 이제 막 바깥으로 나왔고, 짧은 시간에 너무 많은 일을 겪었어...\n그러니까 둘 다 휴식이 꼭 필요해.",
  ui_story_2_1_A32_dialog_content = "상태가 좋아지고 나면, 내...내가 도와줄게...",
  ui_story_2_1_A33_dialog_content = "왜 날 도와주려는 건데?",
  ui_story_2_1_A34_dialog_content = "당연한 거 아냐? 넌 내 목숨을 구했잖아!",
  ui_story_2_1_A35_dialog_content = "게다가... 네 능력은 오로리안에게 무척 중요한 의미가 있어.",
  ui_story_2_1_A36_dialog_content = "......",
  ui_story_2_1_A37_dialog_content = "우린 함께 공동의 적에 맞서 싸울 수 있을 거야. 예전의 오로리안과 아이테르들처럼 말이야!",
  ui_story_2_1_A38_dialog_content = "하지만 지금은 우선 가장 가까운 일루미나 지하성을 찾고, 푹 쉬면서 정비해야 해...",
  ui_story_2_1_19_dialog_content = "앗! 뭐지?",
  ui_story_2_1_20_dialog_content = "스카이워커, 무슨 일이야!?",
  ui_story_2_1_21_dialog_content = "순항 시스템에 여러 손상이 발견되어, 당분간 복구할 수 없습니다.",
  ui_story_2_1_22_dialog_content = "17년 동안 정비가 원활하지 않아서인지, 역시 오래 버티지 못하는군요...\n아무래도 다시 지면으로 돌아가야 할 것 같습니다.",
  ui_story_2_1_23_dialog_content = "PlayerName, 아무래도 이번 여정은 여기까지가 될 것 같습니다.",
  ui_story_2_1_24_dialog_content = "......",
  ui_story_2_1_25_dialog_content = "무슨 일이 있어도 자신과 동료를 지키십시오.",
  ui_story_2_1_26_dialog_content = "당신은 분명히... 더 강해질 수... 있을 겁니다.",
  ui_story_2_1_A43_dialog_content = "스카이워커, 스카이워커!",
  ui_story_2_1_27_dialog_content = "PlayerName!",
  ui_story_2_1_28_dialog_content = "충돌에 대비해!",
  ui_story_2_1_29_dialog_content = "방금 강렬한 루미나 파동이 느껴졌어.",
  ui_story_2_1_30_dialog_content = "슈모르 님, 모든 것이 제 통제 속에 있습니다.",
  ui_story_2_1_A44_dialog_content = "하늘에서 떨어진 패배자는 지킬 수 있는 약속만 하는 게 좋을 것 같은데.",
  ui_story_2_1_A45_dialog_content = "......",
  ui_story_2_1_X1_dialog_content = "넌 카라켄보다 강해. 그 점은 인정해. 하지만 우리의 명령을 완수하지 못한다면...",
  ui_story_2_1_X2_dialog_content = "너도 폐기물에 불과해, 맥거핀.",
  ui_story_2_1_31_dialog_content = "콜로서스는 영원한 피난처가 되진 못할 것입니다. 녀석들은 무의미한 발버둥만 치고 있을 뿐입니다!",
  ui_story_2_1_32_dialog_content = "기대하시는 결과를 곧 보여드리겠습니다.",
  ui_story_2_1_33_dialog_content = "두 번째 기회를 소중히 여겨. 내 인내심이 한계에 다다르기 전에 제대로 처리하는 게 좋을 거야.",
  ui_story_2_1_35_dialog_content = "알겠습니다. 슈모르 님.",
  ui_story_2_1_36_dialog_content = "『콜로서스... 추락... 서쪽... 황야...』",
  ui_story_2_1_37_dialog_content = "『서쪽이라, <color=#FFB400>아비시어</color>의 무리로군... 대답하라!』",
  ui_story_2_1_38_dialog_content = "『말씀하십시오.』",
  ui_story_2_1_39_dialog_content = "『그들을 쫓아가서 없애라... 내가 곧 가겠다!』",
  ui_story_2_1_40_dialog_content = "『아비시어, 명을 받들겠습니다. 암귀, 출격한다!』",
  ui_story_2_2_2_dialog_content = "아야... 엣?",
  ui_story_2_2_3_dialog_content = "바이스, 내 몸에서 내려와 줄래...?",
  ui_story_2_2_A1_dialog_content = "앗? 미, 미안... 괜찮아?",
  ui_story_2_2_A2_dialog_content = "적어도 살아는 있는 것 같네...",
  ui_story_2_2_4_dialog_content = "암귀가 포위해 왔다고?! 이렇게 빨리?",
  ui_story_2_2_5_dialog_content = "PlayerName! 어서 명령을 내려 줘!",
  ui_story_2_2_6_dialog_content = "<color=#e8d9bb>추락으로 인한 거대한 소음에 암귀들이 몰려들었다.</color>",
  ui_story_2_3_1_dialog_content = "상황이 어때?",
  ui_story_2_3_2_dialog_content = "바이스 중위님, 대규모의 암귀가 다가오는 것이 감지되었습니다!\n하지만 저흰 이미 전투 자원이 고갈되었습니다!",
  ui_story_2_3_3_dialog_content = "여기서 가장 가까운 지하성이 어디지?",
  ui_story_2_3_A1_dialog_content = "28호 지하성이 근처에 있습니다. 그쪽으로 대피하는 것이 좋겠습니다!",
  ui_story_2_3_A2_dialog_content = "바이스 중위님, 명령을 내려 주십시오!",
  ui_story_2_3_4_dialog_content = "전원, 목표는 28호 지하성, 전속력으로 전진한다!",
  ui_story_2_3_6_dialog_content = "PlayerName, 우리도 가자!",
  ui_story_2_3_7_dialog_content = "난 됐어. 너희끼리 가.",
  ui_story_2_3_8_dialog_content = "PlayerName?!",
  ui_story_2_3_A3_dialog_content = "너희라도 빨리 대피해. 더 늦으면 못 떠날 거야.",
  ui_story_2_3_A4_dialog_content = "우리랑 같이 안 갈 생각이야?",
  ui_story_2_3_9_dialog_content = "스카이워커는 상처를 입었어. 난 떠날 수 없어...",
  ui_story_2_3_10_dialog_content = "17년간 내가 살아남을 수 있었던 건 모두 스카이워커 덕분이야. 이젠 내게 남겨진 유일한 「가족」이라고.",
  ui_story_2_3_A5_dialog_content = "......",
  ui_story_2_3_11_dialog_content = "만약 맥거핀이 했던 말이 사실이라면...",
  ui_story_2_3_12_dialog_content = "어쨌든 난 절대 스카이워커를 떠나지 않을 거야.",
  ui_story_2_3_13_dialog_content = "너 혼자 여기 있으면 암귀들은 어떻게 상대하려고 그래?!",
  ui_story_2_3_A6_dialog_content = "그 암귀들이 노리는 건 어차피 나잖아? 그럼 내가 여기 남으면 모두에게도 잘된 일이야.",
  ui_story_2_3_14_dialog_content = "너 그게 무슨...!",
  ui_story_2_3_15_dialog_content = "...알겠어. 병사, 모두를 데리고 지하성으로 이동해!",
  ui_story_2_3_A7_dialog_content = "바이스 중위님, 그럼 중위님께선...",
  ui_story_2_3_A8_dialog_content = "시간 낭비하지 말고, 지금 즉시 출발해!",
  ui_story_2_3_A9_dialog_content = "예!",
  ui_story_2_3_A10_dialog_content = "바이스, 넌 이미 날 충분히 많이 도와줬어. 이제 어서 동료들과 함께 여길 떠나.",
  ui_story_2_3_16_dialog_content = "너도 내 동료야. 너 혼자 죽게 내버려 둘 순 없어!",
  ui_story_2_3_17_dialog_content = "이대로 계속 있다간 우리 모두 죽고 말 거야.",
  ui_story_2_3_18_dialog_content = "PlayerName!",
  ui_story_2_3_19_dialog_content = "<anim type=Shake><size=45>크오오!</size></anim>",
  ui_story_2_3_B3_dialog_content = "바이스!",
  ui_story_2_3_B4_dialog_content = "무, 물러서! 안전한 곳에 숨어!",
  ui_story_2_3_B5_dialog_content = "이 녀석들, 정말 빨리도 오네...",
  ui_story_2_3_B6_option_content = "[감응 전개]",
  ui_story_2_3_B7_dialog_content = "키이익!",
  ui_story_2_3_B8_dialog_content = "내가 동료라고 했잖아!",
  ui_story_2_3_B9_dialog_content = "바이스...",
  ui_story_2_3_B10_dialog_content = "크오오오!",
  ui_story_2_3_22_dialog_content = "으아악!",
  ui_story_2_3_A11_dialog_content = "아파! 집중이 안 돼...",
  ui_story_2_3_F1_dialog_content = "PlayerName! 조금만 버텨, 바로 갈게!",
  ui_story_2_3_B11_dialog_content = "<anim type=Shake><size=45>크오오!</size></anim>",
  ui_story_2_3_B12_dialog_content = "<color=#e8d9bb>미처 반응하기도 전에, 암귀들이 동시에 바이스에게 달려들었다.</color>",
  ui_story_2_3_B13_dialog_content = "아악!",
  ui_story_2_3_B14_dialog_content = "도, 도망...쳐. 어서... 숨어...",
  ui_story_2_3_B15_dialog_content = "바이스?!",
  ui_story_2_3_24_option_content = "[감응 전개]",
  ui_story_2_3_25_dialog_content = "안 돼. 이미 의식을 잃었어...",
  ui_story_2_3_26_dialog_content = "싸워야 해... 싸울 방법을 생각하자. 이대로 주저앉을 순 없어...",
  ui_story_2_3_27_dialog_content = "<color=#e8d9bb>암귀들은 의식을 잃은 바이스를 지나 포위해 오기 시작했다...</color>",
  ui_story_2_3_28_dialog_content = "어이, 목숨을 건다고 문제가 해결되진 않아. 암귀를 죽이는 건 아무나 할 수 있는 게 아니라고.",
  ui_story_2_3_29_dialog_content = "얘들아, 가자!",
  ui_story_2_3_30_dialog_content = "<size=45>오늘도 실컷 날뛰는 거다!</size>",
  ui_story_2_3_31_dialog_content = "오케이, 대장!",
  ui_story_2_3_32_dialog_content = "폭발 조심!",
  ui_story_2_3_33_dialog_content = "신나게 놀아보자고~",
  ui_story_2_3_34_dialog_content = "아저씨, 비켜. 거치적거리잖아!",
  ui_story_2_3_36_dialog_content = "당신들 누구야?! 뭘 하려는 건데?",
  ui_story_2_3_37_dialog_content = "하, 보면 몰라? 우린 약탈자다.",
  ui_story_2_3_38_dialog_content = "우리가 네 목숨을 구했으니까, 얼른 돈이 될 만한 물건을 내놔!",
  ui_story_2_3_F2_dialog_content = "아하하하핫!",
  ui_story_2_3_39_dialog_content = "소개하지. 난 <color=#FFB400>사메야마</color>, <color=#FFB400>레디젤 렌치</color>의 대장이다.",
  ui_story_2_3_40_dialog_content = "저 폼 잡는 걸 좋아하는 녀석은 <color=#FFB400>레지나</color>다.",
  ui_story_2_3_41_dialog_content = "폭탄을 갖고 노는 녀석은 <color=#FFB400>봄버 존</color>이고.",
  ui_story_2_3_42_dialog_content = "내 왼팔과 오른팔이지.",
  ui_story_2_3_43_dialog_content = "레디젤... 렌치? 약탈자...?! 무슨 짓을 하려는 거야? 콜로서스에 손대지 마!",
  ui_story_2_3_44_dialog_content = "이 커다란 녀석 말하는 거야? 왜 들어갈 수 없는 거지? 그럼... 그냥 날려버려야지~!",
  ui_story_2_3_45_dialog_content = "얘들아! 물건 옮겨~",
  ui_story_2_3_46_dialog_content = "우오오! 펑펑 누님 만세!",
  ui_story_2_3_47_dialog_content = "하하하하! 설마 이런 데서 콜로서스를 건지다니, 오늘 정말 운이 끝내주게 좋잖아!",
  ui_story_2_3_A12_dialog_content = "얼른 분해해서 가지고 돌아간다!",
  ui_story_2_3_48_dialog_content = "다 잡은 물고기를 놓칠 순 없지!",
  ui_story_2_3_49_dialog_content = "스카이워커... 콜로서스를 망가트리면 안 돼! 안에 생명유지 장치도 있어...",
  ui_story_2_3_50_dialog_content = "내 동료 바이스가 다쳤어. 장치를 계속 사용해야만 해...!",
  ui_story_2_3_51_dialog_content = "이 아가씨, 상태가 썩 좋지 않군.",
  ui_story_2_3_52_dialog_content = "...잠깐, 이 제복은... 일루미나?",
  ui_story_2_3_53_dialog_content = "어이, 잘 모르나 본데, 우리랑 이 군인 나리들은 썩 좋은 사이가 아니라고.",
  ui_story_2_3_54_dialog_content = "그리고 이 콜로서스는 이미 우리 재산이니까 거래 대상이 아냐.\n그 여자애를 구하고 싶으면, 다른 걸 내놔.",
  ui_story_2_3_55_dialog_content = "근데 네 꼴을 보니 돈이 있는 것 같지는 않은걸? 꼬락서니 좀 봐, 대체 얼마나 못 씻은 거야?",
  ui_story_2_3_56_option_content = "나 돈 있어. 돈 많다고!",
  ui_story_2_3_57_option_content = "날 화나게 하지 마, 오로리안!",
  ui_story_2_3_58_dialog_content = "그럼 솔직하게 말할게. 내가 가진 것 중에 제일 가치가 있는 건 물론 이 콜로서스야.\n어때? 너희도 이런 건 본 적 없지?!",
  ui_story_2_3_59_dialog_content = "흥, 누가 콜로서스를 본 적 없대?\n하지만... 확실히 우리 캠프 안에 있는 것보다는 이 녀석이 훨씬 멀쩡한걸...",
  ui_story_2_3_60_dialog_content = "그래! 그러니까 너희가 계속 이렇게 분해한다면, 겨우 찾은 멀쩡한 콜로서스의 가치가 사라지지 않겠어?!",
  ui_story_2_3_61_dialog_content = "쳇... 귀찮네! 한바탕 화력 전개할 타이밍인 줄 알았는데! 대장, 어떻게 할까?",
  ui_story_2_3_62_dialog_content = "......",
  ui_story_2_3_63_dialog_content = "녀석의 말도 일리가 있어. 일단 멈춰.",
  ui_story_2_3_64_dialog_content = "그래, 그래. 얼른 멈춰!",
  ui_story_2_3_65_dialog_content = "어이, 너. 이리 와 봐라.",
  ui_story_2_3_66_dialog_content = "말해, 넌 정체가 뭐냐?",
  ui_story_2_3_67_dialog_content = "......",
  ui_story_2_3_68_dialog_content = "뭐, 네가 말하지 않아도 얼추 알 순 있지. 네 그 모습은 17년 전의 그 사람들과 같은 모습이니까.",
  ui_story_2_3_69_dialog_content = "이렇게 큰 녀석을 끌고 돌아다니면서 지금까지 살아남은 것도 대단하네!",
  ui_story_2_3_70_dialog_content = "나에 대해서 알고 있는 거야...?",
  ui_story_2_3_71_dialog_content = "그 사건이 그리 오래된 일은 아니니 말이지, <color=#FFB400>아이테르</color>. 난 뭔가를 잘 잊어버리는 타입이 아니거든.",
  ui_story_2_3_72_dialog_content = "너흰 내가 누군지 몰라. 멋대로 굴면 후회하게 될 거야! 나, 난 너희가 무섭지 않다고!",
  ui_story_2_3_73_dialog_content = "......",
  ui_story_2_3_74_dialog_content = "...이 녀석, 머리라도 다쳤나?",
  ui_story_2_3_75_dialog_content = "웃기는군. 네가 <color=#FFB400>그 종족</color>이라는 게 우리한테 위협이 될 거라 생각하는 거냐?",
  ui_story_2_3_76_dialog_content = "똑바로 판단하는 게 좋을 거다. 우린 모두 흉악하기 짝이 없는 강도들이라고.",
  ui_story_2_3_77_dialog_content = "...내 종족을 아는 거야?",
  ui_story_2_3_78_dialog_content = "...그 옷과 이 콜로서스, 무엇을 믿어야 할지 모르겠다는 눈빛까지. 척 보면 척 아니겠어?",
  ui_story_2_3_79_dialog_content = "좋은 가격에 팔 수 있을지도 모르겠어...",
  ui_story_2_3_80_dialog_content = "파, 판다고?! 다 같은 오로리안이면서 왜 날 대하는 방식이 이렇게 다른 건데?!",
  ui_story_2_3_81_dialog_content = "오해하지 마라, <color=#FFB400>아이테르</color>. 넌 우리 같은 강도단에겐 아무것도 아니니까.",
  ui_story_2_3_82_dialog_content = "아이테르? 암귀한테 다 죽은 그 종족 말이야?",
  ui_story_2_3_B1_dialog_content = "다 죽은...",
  ui_story_2_3_B2_dialog_content = "그러니까, 17년 전 헤븐즈 밸리가 습격을 받은 뒤로... 정말 다른 생존자는 없었던 거야?",
  ui_story_2_3_83_dialog_content = "혹시 그때에 대해 더 알고 있는 건 없어...?",
  ui_story_2_3_84_dialog_content = "미안하지만 그때 일은 정말 하룻밤 사이에 순식간에 벌어졌고, 순식간에 끝나버렸지.",
  ui_story_2_3_85_dialog_content = "그때 난 아직 꼬맹이였고 말이야. 그러니 뭘 자세히 알 수 있겠어?",
  ui_story_2_3_89_dialog_content = "자, 쓸데없는 소리는 이쯤 하자고! 아이테르도 콜로서스도, 이제는 다 우리 거다!",
  ui_story_2_3_90_dialog_content = "그럼, 바이스는...",
  ui_story_2_3_91_dialog_content = "이미 <color=#FFB400>생명유지 장치</color>로 옮겨서 치료 중이다! 우린 강도긴 해도 살인범은 아니라고!",
  ui_story_2_3_92_dialog_content = "너흰 어떻게 그렇게 콜로서스를 잘 알고 있는 건데...?",
  ui_story_2_3_93_dialog_content = "콜로서스를 가진 게 너희 아이테르뿐이라고 생각하지 마라.\n우리 레디젤 렌치도 나름의 「<color=#FFB400>수단</color>」이 있거든.",
  ui_story_2_3_94_dialog_content = "그럼 어디 보자고. 너흴 사겠다고 돈을 들고 오는 사람이 있을지 말이야... 아이테르!",
  ui_story_2_4_1_dialog_content = "대장, 암귀 무리가 또 우리 쪽으로 오는데요.",
  ui_story_2_4_2_dialog_content = "그래, 정말 끝도 없이 오는군. 그럼 어떻게 콜로서스를 끌고 돌아가지?",
  ui_story_2_4_3_dialog_content = "그러고 보니 PlayerName, 너희도 지금까지 암귀한테 추격당하고 있던 거겠지?",
  ui_story_2_4_4_dialog_content = "맞아...",
  ui_story_2_4_5_dialog_content = "쳇, 정말 골칫덩어리 같은 녀석이군.",
  ui_story_2_4_6_dialog_content = "다들 정신 바짝 차려라! 벌레가 다가온다!",
  ui_story_2_4_7_dialog_content = "그럼 우리도 말로만 듣던 아이테르의 그 「감응의 힘」이란 걸 느껴볼 수 있을까?",
  ui_story_2_4_8_dialog_content = "당신들은 내 지휘 없이도 잘 싸우잖아...",
  ui_story_2_4_9_dialog_content = "모처럼의 기회 아니겠어? 식견도 넓히고, 대체 그 빛의 궤적이란 게 뭔지도 좀 보고 싶으니 말이야!",
  ui_story_2_4_10_dialog_content = "적이 온다! 뜨거운 맛을 보여줘라. 끝까지 버텨!",
  ui_story_2_8_1_dialog_content = "놈들이 이런 우회 전술을 구사하는 걸 우연으로 보긴 힘들겠지.",
  ui_story_2_8_2_dialog_content = "암귀 녀석들, 대체 언제 이렇게 똑똑해진 거야?",
  ui_story_2_8_3_dialog_content = "펑펑, 네 생각은 어때?",
  ui_story_2_8_4_dialog_content = "고위 암귀가 지휘하고 있는 건 아니겠지?",
  ui_story_2_8_5_dialog_content = "재수 없는 소리 마!",
  ui_story_2_8_7_dialog_content = "고위 암귀...",
  ui_story_2_8_B1_dialog_content = "어이쿠, 벌써 시간이 이렇게 됐나?",
  ui_story_2_8_B2_dialog_content = "대장, 이제야 생각난 거야?!",
  ui_story_2_8_B3_dialog_content = "미안, 미안. 아이테르와 같이 싸우는 게 끝내줘서 시간 가는 줄도 몰랐지 뭐야...",
  ui_story_2_8_B4_dialog_content = "다들 스톱! <color=#FFB400>밥 먹을 시간이다</color>!",
  ui_story_2_8_B5_dialog_content = "<anim type=Shake><size=45>우오오오오오! 밥이다!</size></anim>",
  ui_story_2_8_SS_dialog_content = "레디젤 야외 식사 CG",
  ui_story_2_8_B6_dialog_content = "어이! 밀지 마! 대장 먼저도 모르냐?!",
  ui_story_2_8_B7_dialog_content = "하하하, 먼저 먹어! 두 통만 남겨 달라고!",
  ui_story_2_8_B8_dialog_content = "다...다들 대체 뭘 하는 거야...?",
  ui_story_2_8_B9_dialog_content = "밥 먹는 거 처음 보냐? 이상해? 지금까지 밥을 먹어본 적이 없는 거야?",
  ui_story_2_8_B10_dialog_content = "내 말은... 너무 야만적인 것 같아서...",
  ui_story_2_8_B11_dialog_content = "그게 바로 생존 욕구라는 거다, PlayerName. 우리의 생명력을 우습게 보지 마라.",
  ui_story_2_8_B12_dialog_content = "먹고 마실 수 있기에 우리가 살아있는 거고, 살아 있다는 건 더 잘 먹고 마시기 위해서라고!",
  ui_story_2_8_B13_dialog_content = "대장, 계속 그 아이테르랑 떠들다간 고기고 뭐고 싹 다 바닥날걸!",
  ui_story_2_8_B14_dialog_content = "내가 <color=#FFB400>도마뱀 고기</color> 두 개 챙겨놨어!",
  ui_story_2_8_B15_dialog_content = "아이테르한테 줘. 난 아직 배가 안 고파.",
  ui_story_2_8_B16_dialog_content = "자!",
  ui_story_2_8_B17_dialog_content = "...나...나도 배 안 고파...",
  ui_story_2_8_B18_dialog_content = "이 자식, 왜 계속 그렇게 풀이 죽어 있어?",
  ui_story_2_8_B19_dialog_content = "밖에 나온 건 처음이라고 안 했어?",
  ui_story_2_8_B20_dialog_content = "그럼 여기저기 돌아다니면서 놀고 싶지 않아?",
  ui_story_2_8_B21_dialog_content = "뭘 그렇게 축 처져 있는 거냐고!",
  ui_story_2_8_B22_dialog_content = "어째, 바깥세상이 땅속보다 별로였나?",
  ui_story_2_8_B23_dialog_content = "뭐?",
  ui_story_2_8_B24_dialog_content = "난 네가 무슨 일을 겪었는지 따윈 관심 없어.\n하지만 지금 너도, 저 콜로서스도, 그리고 저 아가씨도 다 멀쩡하잖아?",
  ui_story_2_8_B25_dialog_content = "그리고 네가 아이테르라서 쓸모가 있었으니 망정이지, 가만히 있으면 어디서 밥이 저절로 나올 줄 알았어?",
  ui_story_2_8_B26_dialog_content = "이 세상엔 쉽게 살아갈 수 있는 녀석은 아무도 없어. 그렇게 끙끙대고만 있어봤자 바뀌는 건 없다고.",
  ui_story_2_8_B27_dialog_content = "그런 얼간이라면 살려줄 가치가 없잖아? 데리고 가 봤자 귀찮기만 하겠지.",
  ui_story_2_8_B28_dialog_content = "내가 죽으면 더 귀찮아질걸? 이...일루미나에서 당신들을 가만 두지 않을 거라고!",
  ui_story_2_8_B29_dialog_content = "하하하하하하하!",
  ui_story_2_8_B30_dialog_content = "뭐가 웃기는데?",
  ui_story_2_8_B33_dialog_content = "그래도 얼간이는 아닌 모양이군. 그럼 됐어!",
  ui_story_2_8_8_dialog_content = "찾았다! 아이테르!",
  ui_story_2_8_9_dialog_content = "<color=#FFB400>아비시어</color>?!",
  ui_story_2_8_B34_dialog_content = "암귀! 정말 날 쫓아온 건가?!",
  ui_story_2_8_B35_dialog_content = "식사 중지! 대형을 펼쳐라. 전투 준비!",
  ui_story_2_8_10_dialog_content = "어떻게 남이 밥을 먹을 때 공격할 수가 있지? 흥, 정말 형편없군.",
  ui_story_2_8_B36_dialog_content = "아무래도 내가 기본적인 예의를 좀 가르쳐 줘야겠어!",
  ui_story_2_8_11_dialog_content = "이거 생각보다 어렵겠는데...",
  ui_story_2_8_12_dialog_content = "이 <color=#FFB400>기차</color>...",
  ui_story_2_8_13_dialog_content = "설마 <color=#FFB400>그 녀석</color>은 아니겠지...",
  ui_story_2_8_14_dialog_content = "꼴이 정말 처참하군, 사메야마.",
  ui_story_2_8_15_dialog_content = "암귀와 소꿉장난이라도 하고 있는 건가?",
  ui_story_2_8_16_dialog_content = "너일 줄 알았다. 군인 나리. 한동안 네 군량엔 손을 댄 적 없잖아?",
  ui_story_2_8_17_dialog_content = "나는 일루미나의 동료를 데리러 왔을 뿐이다. 군량에 대한 일은 다음에 갚아주마.",
  ui_story_2_8_18_dialog_content = "오? 그 아가씨 말인가?",
  ui_story_2_8_19_dialog_content = "이것 참 공교롭군. 나도 마침 그 아가씨를 돌려보낼까 생각 중이었거든.",
  ui_story_2_8_20_dialog_content = "그녀뿐만 아니라, 그 콜로서스 역시 <color=#FFB400>일루미나 연방</color>의 재산이다.",
  ui_story_2_8_21_dialog_content = "억지 부리지 마, 흰머리 괴물!",
  ui_story_2_8_22_dialog_content = "네 기차를 터트려 버리는 수가 있다고!",
  ui_story_2_8_23_dialog_content = "성급하게 굴지 마, 펑펑.",
  ui_story_2_8_24_dialog_content = "이 녀석은 방금 그 아비시어보다 더 성가신 녀석이라고.",
  ui_story_2_8_25_dialog_content = "어차피 그저 콜로서스일 뿐이잖아. 분해할 수도 없고 팔 수도 없지. 우리한테는 그리 중요하지 않아.",
  ui_story_2_8_26_dialog_content = "흥! 운 좋은 줄 알아!",
  ui_story_2_8_B37_dialog_content = "카론, 저 커다란 녀석과 이 꼬마를 잘 대해줘야 할 거다.",
  ui_story_2_8_B38_dialog_content = "PlayerName 녀석은 내 생각보다 훨씬 재밌는 것 같으니까.",
  ui_story_2_8_B39_dialog_content = "뭐?",
  ui_story_2_8_B40_dialog_content = "휴, 이거 아깝네! 귀한 보물을 손에 넣었는데 말이지!",
  ui_story_2_8_B41_dialog_content = "PlayerName, 비록 지금은 풀이 잔뜩 죽은 것처럼 보이지만...",
  ui_story_2_8_B42_dialog_content = "그래도 여전히 빛의 기운이 가득하다고.",
  ui_story_2_8_B43_dialog_content = "빛의 기운? 하지만 난 빛의 힘을 쓰지 못해...",
  ui_story_2_8_B44_dialog_content = "쯧, 비유 몰라? 비유!",
  ui_story_2_8_B48_dialog_content = "역시 나이가 들면 다들 어렵게 얘기하는 건가...",
  ui_story_2_8_B49_dialog_content = "하하하, 농담도 할 줄 아는 거냐. 기분이 좀 나아진 모양이군.",
  ui_story_2_8_B50_dialog_content = "기억해라, 아이테르. 죽는 건 쉬운 일이다. 하지만 살아있는 이상, 최선을 다해 사는 거다!",
  ui_story_2_8_B51_dialog_content = "「<color=#FFB400>희망</color>」이란 건 찾다 보면 반드시 찾아지기 마련이거든.",
  ui_story_2_8_B52_dialog_content = "백야 아래에서든, 어둠 속에서든 말이야...",
  ui_story_2_8_B53_dialog_content = "그건 또 어디서 보고 베낀 말이지?",
  ui_story_2_8_B54_dialog_content = "음... 어디서 본 건지 까먹었다.",
  ui_story_2_8_B55_dialog_content = "며칠 못 본 새에 책이라도 읽기 시작한 거냐.",
  ui_story_2_8_B56_dialog_content = "하하하하! 군인 나리, 열심히 살아가는 우리 유민들을 얕보지 마! 그럼, 다음에 또 만나자고!",
  ui_story_2_8_28_dialog_content = "또 만나게 될 거라는 예감이 드니 말이야...",
  ui_story_2_8_29_dialog_content = "레디젤 렌치, 돌아가자! 오늘 저녁은 샌드버그 특식으로 기분 좀 내 볼까!",
  ui_story_2_8_31_dialog_content = "...좀 좋은 소식을 가져올 순 없는 거야? 맥거핀.",
  ui_story_2_8_32_dialog_content = "일루미나의 증원이 도착했습니다. <color=#FFB400>카론</color>이라고 하는 오로리안입니다...",
  ui_story_2_8_33_dialog_content = "카론? 정말 그리운 이름이네.",
  ui_story_2_8_34_dialog_content = "그럼, 그 아이테르도 데려간 건가?",
  ui_story_2_8_35_dialog_content = "그들은 <color=#FFB400>28호 지하성</color>으로 향했습니다.",
  ui_story_2_8_36_dialog_content = "적어도 아비시어가 목표의 위치를 찾아냈으니, 그럼 이제 뭘 해야 할지는 알고 있겠지.",
  ui_story_2_8_37_dialog_content = "모두 원하시는 대로 이루어질 것입니다.",
  ui_story_2_8_38_dialog_content = "오로리안의 지하성...",
  ui_story_2_8_39_dialog_content = "쥐새끼들이 구멍에 숨어 있으면 안심할 수 있다고 생각한 건가.",
  ui_story_2_8_40_dialog_content = "후회해라, 겁쟁이들... 그런 곳에 숨어든 것을.",
  ui_story_2_8_41_dialog_content = "모두 함께 그곳에 묻어주마!",
  ui_story_2_9_1_dialog_content = "당신은... 누구지?",
  ui_story_2_9_2_dialog_content = "난 <color=#FFB400>28호 병참 지하성</color>의 책임관이다.",
  ui_story_2_9_3_dialog_content = "카론이라 부르면 된다.",
  ui_story_2_9_4_dialog_content = "바이스는 어디 있지?",
  ui_story_2_9_5_dialog_content = "콜로서스의 생명유지 장치 안에 있어. 바이스는 다쳤어. 나...난 바이스를 지키지 못했어.",
  ui_story_2_9_6_dialog_content = "당신은 그럼 바이스의...",
  ui_story_2_9_7_dialog_content = "바이스가 내게 이번 탐색 작전에 대해 미리 보고해뒀다.",
  ui_story_2_9_8_dialog_content = "그리고 난 콜로서스의 구조 신호를 보고, 암귀를 따라 너흴 찾아낸 거다.",
  ui_story_2_9_9_dialog_content = "바이스의 상황은 어떤가.",
  ui_story_2_9_10_dialog_content = "콜로서스의 생명유지 장치 덕분에 안정적인 상태야.",
  ui_story_2_9_11_dialog_content = "이제 어떻게 하지?",
  ui_story_2_9_12_dialog_content = "넌 질문이 정말 많군. 우선 나와 함께 28호 지하성으로 가면 된다.",
  ui_story_2_9_13_dialog_content = "카론 님께서 돌아오셨다!",
  ui_story_2_9_14_dialog_content = "우와! 엄청나게 크네. 이번엔 대체 뭘 가져오신 거지?",
  ui_story_2_9_15_dialog_content = "어서 교통 부서에 연락해서 카론 님 전용 철로를 열어.",
  ui_story_2_9_17_dialog_content = "카론 님, 어서 오십시오.",
  ui_story_2_9_18_dialog_content = "이건... 콜로서스?!",
  ui_story_2_9_19_dialog_content = "그렇다. 콜로서스 안에 부상자가 있으니, 의료팀에게 알려라.",
  ui_story_2_9_20_dialog_content = "그리고, 일루미나 소대 하나가... 희생되었다.",
  ui_story_2_9_21_dialog_content = "...알겠습니다! 바로 후속 조치를 한 뒤에 대원을 보충하겠습니다.",
  ui_story_2_9_22_dialog_content = "그래, 수고하도록.",
  ui_story_2_9_23_dialog_content = "전선의 상황은 어떤가?",
  ui_story_2_9_24_dialog_content = "이상 없습니다!",
  ui_story_2_9_25_dialog_content = "이상하군. 저런 대규모의 암귀가 어떻게 전선을 넘은 거지?",
  ui_story_2_9_26_dialog_content = "통신반에게 알린다. <color=#FFB400>자난 본부</color>와 연결해라. 잠시 후 본부와 통화할 테니 말이다.",
  ui_story_2_9_B1_dialog_content = "......",
  ui_story_2_9_B2_dialog_content = "왜 그러지? 이렇게 큰 지하 공간과 조직은 처음 보는 건가?",
  ui_story_2_9_B3_dialog_content = "이곳이... 일루미나?",
  ui_story_2_9_B4_dialog_content = "이곳은 일루미나 연방의 지하성 중 하나일 뿐이다, 28번이지.",
  ui_story_2_9_B5_dialog_content = "28호 지하성이 비록 암귀에 맞서는 최전방은 아니지만, 핵심 병참 기지로서 중요한 역할을 담당하고 있다.",
  ui_story_2_9_F1_dialog_content = "이곳이 함락되면 암귀는 우리의 방어선을 뚫고 전진할 수 있게 된다...",
  ui_story_2_9_B6_dialog_content = "참, 아이테르, 지리를 공부한 적 있나?",
  ui_story_2_9_F2_dialog_content = "조금... 배운 적 있어. 만약 암귀가 방어선을 돌파한다면,\n대륙의 내부로 곧바로 들어설 수 있게 되는 거지?",
  ui_story_2_9_B7_dialog_content = "그렇다! 한쪽은 영원한 아침이고 한쪽은 영원한 밤, 대륙은 그 사이에서 우리가 살아갈 수 있는\n유일한 곳이다. 그러니 우린 결코 물러설 수 없지.",
  ui_story_2_9_B8_dialog_content = "우리 일루미나는 암귀와 싸우기 위해 태어났다. 그건 우리의 숙명이자 사명이다.",
  ui_story_2_9_B9_dialog_content = "우리는 우리의 터전을 지켜야만 한다.",
  ui_story_2_9_B10_dialog_content = "터전... 오로리안의 땅을 말하는 거야?",
  ui_story_2_9_B11_dialog_content = "정확하게는 모든 <color=#FFB400>소중한 것들</color>이 있는 곳이다.",
  ui_story_2_9_B13_dialog_content = "그건 오로리안일 수도, 유적일 수도, 또 「보잘것없는」 기억일 수도 있다.",
  ui_story_2_9_B14_dialog_content = "의외로... 꽤 낭만적이네.",
  ui_story_2_9_B15_dialog_content = "그런가? 난 그게 우릴 살아가게 하는 가장 현실적인 동력이라고 생각하는데 말이지.",
  ui_story_2_9_B16_dialog_content = "그게 바로 「<color=#FFB400>희망</color>」이란 것이다!",
  ui_story_2_9_B17_dialog_content = "만약 절망을 바꿀 수 없다면, 희망으로 영원한 암흑을 메워나가면 되는 거다.",
  ui_story_2_9_B18_dialog_content = "음, 어쩌다 보니 명언이 탄생했군.",
  ui_story_2_9_B19_dialog_content = "...사메야마가 했던 말이랑 비슷한데...",
  ui_story_2_9_B20_dialog_content = "보아하니 정신이 좀 없어 보이는군. 이제 뭘 할 생각이지? 휴식인가?",
  ui_story_2_9_B21_dialog_content = "아니면 네 다른 동료들을 찾아갈 건가?",
  ui_story_2_9_B22_dialog_content = "동료...? 난 내 동족들이 어디 있는지 몰라...",
  ui_story_2_9_B23_dialog_content = "내가 말하는 건 그 오로리안들이다. 그들은 네 동료가 아닌가?",
  ui_story_2_9_B24_dialog_content = "아... 마, 맞아. 확실히 많은 도움을 받았어...",
  ui_story_2_9_B25_dialog_content = "잠깐 생각을 정리해야 할 것 같아. 오늘은 너무 정신없는 날이었어...",
  ui_story_2_9_B26_dialog_content = "음, 그럼 혼자 알아서 쉬어라. 난 아직 해야 할 일간 보고와 작업이 남았으니, 먼저 가보겠다.",
  ui_story_2_9_B27_dialog_content = "갑자기 냉담해졌는데...?",
  ui_story_2_9_B28_dialog_content = "아무리 낭만적인 시인이라도, 책임져야 할 업무 계획은 있는 법이다.",
  ui_story_2_9_B30_dialog_content = "그리고 너무 자책하지 마라.",
  ui_story_2_9_B31_dialog_content = "일루미나 병사들의 죽음은 너만을 위한 게 아니라, 우리의 사명을 위한 것이다.",
  ui_story_2_9_27_dialog_content = "그걸로 네 기분이 좀 편해졌으면 좋겠군.",
  ui_story_2_9_28_dialog_content = "......",
  ui_story_2_9_29_dialog_content = "아...아이테르? 라고 부르면 되겠습니까? 휴식실은 이쪽입니다.",
  ui_story_2_9_30_dialog_content = "절 따라오십시오. 비록 초면이지만, 카론 님이 데리고 오신 분이니 괜찮겠죠.",
  ui_story_2_9_32_dialog_content = "28호 지하성에 오신 걸 환영합니다.",
  ui_story_2_9_33_dialog_content = "28호 지하성에서 자난을 호출한다. 여기는 카론, 보고해야 할 중요한 일이 있다.",
  ui_story_2_9_34_dialog_content = "여기는 자난, <color=#FFB400>히이로</color>입니다.",
  ui_story_2_9_35_dialog_content = "문어.",
  ui_story_2_9_36_dialog_content = "<color=#FFB400>「트레인맨은 정말 멋지지」</color>.",
  ui_story_2_9_37_dialog_content = "히이로, 오늘은 네가 당직인가.",
  ui_story_2_9_38_dialog_content = "답어는?",
  ui_story_2_9_39_dialog_content = "<color=#FFB400>「피어나는 벚꽃」</color>...",
  ui_story_2_9_41_dialog_content = "바이스의 임무는 어떻게 되고 있습니까?",
  ui_story_2_9_42_dialog_content = "마침 그 일에 대해 말하려던 참이다.",
  ui_story_2_9_43_dialog_content = "콜로서스를 찾았고, 이미 28호 지하성으로 이송했다.",
  ui_story_2_9_44_dialog_content = "바이스는 부상을 당했고, 치료를 받는 중이다.",
  ui_story_2_9_45_dialog_content = "부상? 심각합니까?",
  ui_story_2_9_46_dialog_content = "걱정할 거 없다. 지금은 괜찮으니까.",
  ui_story_2_9_47_dialog_content = "카론, 당신은 바이스의 임시 상관이니, 당신에게도 책임이 있습니다.",
  ui_story_2_9_48_dialog_content = "무슨 일이 있었던 겁니까? 말해보세요.",
  ui_story_2_9_49_dialog_content = "바이스의 추측이 옳았다.",
  ui_story_2_9_50_dialog_content = "17년 전 헤븐즈 밸리를 떠난 콜로서스 중에서, 한 대가 28호 지하성 근처에 추락한 게 사실이었다.",
  ui_story_2_9_51_dialog_content = "바이스 일행은 다수의 암귀와 조우했고, 그 암귀들은 콜로서스를 추적하는 듯했다.",
  ui_story_2_9_52_dialog_content = "바이스가 콜로서스를 발견한 후 당신들에게 지원을 요청하지 않았습니까?",
  ui_story_2_9_F3_dialog_content = "신호는 확인했고, 내가 갔을 땐...",
  ui_story_2_9_53_dialog_content = "지원이 늦었던 겁니까?",
  ui_story_2_9_54_dialog_content = "히이로, 말을 좀 끝까지 들어줬으면 좋겠군. 이번 상황은 무척 복잡하다.",
  ui_story_2_9_55_dialog_content = "그 콜로서스는 지하에 묻혀 있었다. 하지만 너도 이건 몰랐을 거다.\n그 콜로서스 안에는 아이테르 한 명이 생존해 있었던 거다.",
  ui_story_2_9_57_dialog_content = "아이테르?",
  ui_story_2_9_58_dialog_content = "그러니까, 그 아이테르는 지하에서 17년을 살았다는 겁니까...",
  ui_story_2_9_60_dialog_content = "그리고 어떻게 됐습니까?",
  ui_story_2_9_61_dialog_content = "바이스가 콜로서스를 통해 구조 신호를 발사했다.",
  ui_story_2_9_62_dialog_content = "난 즉시 출발했고, 그곳에 도착한 후 대규모의 암귀가 남긴 흔적을 발견했다.",
  ui_story_2_9_63_dialog_content = "그리고 아이테르를 통해 그들과 교전한 게 카라켄, 맥거핀과 아비시어라는 사실을 알았지.",
  ui_story_2_9_64_dialog_content = "고위 암귀가 세 마리나?",
  ui_story_2_9_65_dialog_content = "그것도 일루미나의 방어선을 넘어 28호 지하성 근처에 잠입했다는 겁니까?",
  ui_story_2_9_66_dialog_content = "바로 그게 의문인 거다. 카라켄은 방어선 아래를 넘나드는 능력이 있지만,\n나머지 암귀는 그러지 못할 텐데 말이야.",
  ui_story_2_9_67_dialog_content = "게다가 엄청난 수의 하급 암귀를 이끌고서 말이지.",
  ui_story_2_9_68_dialog_content = "마치 하늘에서 내려온 것처럼 저들의 흔적을 찾을 수 없었다. 17년 전의 헤븐즈 밸리처럼.",
  ui_story_2_9_69_dialog_content = "그럼 암귀가 방어선을 넘을 수단을 찾아냈다는 뜻이겠지요.",
  ui_story_2_9_70_dialog_content = "그럴 수도 있겠지...",
  ui_story_2_9_71_dialog_content = "또한, 맥거핀이 아직 살아있을지 모른다는 점도 위험 요소 중 하나다.",
  ui_story_2_9_72_dialog_content = "좋습니다. 바로 대원수님께 전하도록 하겠습니다.",
  ui_story_2_9_73_dialog_content = "모두 위험에 대비하십시오.",
  ui_story_2_9_74_dialog_content = "28호 지하성은 전선의 중요한 보급 라인입니다. 그곳의 물자는...",
  ui_story_2_9_75_dialog_content = "히이로, 무엇을 해야 할지는 나도 잘 알고 있다.",
  ui_story_2_9_76_dialog_content = "<color=#e8d9bb>며칠 후, 콜로서스 수리장</color>",
  ui_story_2_9_77_dialog_content = "역시 여기 있었네.",
  ui_story_2_9_78_dialog_content = "바이스?! 너 상처는 괜찮아? 이제 움직일 수 있는 거야?!",
  ui_story_2_9_79_dialog_content = "일루미나의 의료 기술이라면 이 정도는 아무것도 아냐.",
  ui_story_2_9_80_dialog_content = "스카이워커호는 어때?",
  ui_story_2_9_81_dialog_content = "이제 문제없어. 일루미나의 과학기술은 정말 놀랍네. 며칠 만에 망가졌던 유닛을 모두 수리했어.",
  ui_story_2_9_82_dialog_content = "이제 인부들이 마지막 코팅 작업을 하고 있는 것 같아.\n왠지 좀 지나치게 완벽을 추구하는 것 같지만...",
  ui_story_2_9_83_dialog_content = "그리고 저 눈에 띄는 일루미나 마크만 좀 지워 준다면 더 좋겠는데 말이지...",
  ui_story_2_9_84_dialog_content = "일루미나의 기술자들이 이런 실력을 갖추고 있었을 줄은 몰랐습니다...\n저 대신 바이스에게 감사 인사를 전해주십시오.",
  ui_story_2_9_87_dialog_content = "그거야 당연하지. 일루미나의 과학력은 세계 제일이거든!",
  ui_story_2_9_88_dialog_content = "내 제복과 무기 모두 과학반의 작품이야. 이것들은 모두 우리가 수행하는 작전의 기반이 되는 것들이야.",
  ui_story_2_9_89_dialog_content = "이건 엔지니어링된 루미나 장치야. 오로리안이 자신의 힘을 조절하고 발동시킬 수 있도록 도와줘.",
  ui_story_2_9_90_dialog_content = "이런 방식은 운용 효율과 술식 발동 속도 면에서 「의식화」로는 얻을 수 없는 이점을 발휘해.",
  ui_story_2_9_91_dialog_content = "비록 의식화에 비해 위력은 많이 약하지만,\n우리처럼 집단 작전을 수행하는 스타일에는 꽤 잘 맞는 편이야.",
  ui_story_2_9_A1_dialog_content = "......",
  ui_story_2_9_A2_dialog_content = "......",
  ui_story_2_9_A3_dialog_content = "아, 혹시 이해가 안 되는 부분이 있는 거야?",
  ui_story_2_9_A4_dialog_content = "...음, 거의 다?",
  ui_story_2_9_A5_dialog_content = "엣? 그렇게 어려웠나? 아, 미안. 네가 이 세계에 대해 잘 모른다는 걸 잊고 있었어...",
  ui_story_2_9_A6_dialog_content = "음... 그럼 이 이야기보다는...",
  ui_story_2_9_A7_dialog_content = "바이스, 우리가 추락하고... 그때...",
  ui_story_2_9_98_dialog_content = "내 말이 조금... 음...",
  ui_story_2_9_99_dialog_content = "아무튼... 미안해!",
  ui_story_2_9_100_dialog_content = "에? 왜 갑자기 사과하는 거야?",
  ui_story_2_9_101_dialog_content = "전에 난 계속 내 입장에서만 이야기했고, 널 다치게 했어. 며칠 동안 악몽도 꿨고...",
  ui_story_2_9_102_dialog_content = "아, 그 이야기구나. 전혀 사과할 필요 없어!",
  ui_story_2_9_103_dialog_content = "그때 난 너와 스카이워커의 관계에 대해 잘 몰랐으니까... 무턱대고 제안한 내 잘못이야.",
  ui_story_2_9_104_dialog_content = "네가 그곳에 남아 혼자서 암귀와 상대한다고 생각하니, 너무 조급해졌지 뭐야.",
  ui_story_2_9_105_dialog_content = "아무튼 이젠 괜찮으니까!",
  ui_story_2_9_107_dialog_content = "앞으로도 잘 부탁할게, PlayerName.",
  ui_story_2_9_108_dialog_content = "응!",
  ui_story_2_9_109_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_2_9_110_dialog_content = "<color=#e8d9bb>진동이 점점 격렬해진다. 왠지 발밑에서 전해져 오는 것 같다.</color>",
  ui_story_2_9X_1_dialog_content = "<color=#e8d9bb>미묘한 진동이 전해진다.</color>",
  ui_story_2_9X_2_dialog_content = "<color=#e8d9bb>진동이 점점 격렬해진다. 왠지 발밑에서 전해져 오는 것 같다.</color>",
  ui_story_2_9X_3_dialog_content = "뭔가 이상한데...",
  ui_story_2_9X_4_dialog_content = "...뭔가 진동하고 있어. 스카이워커호인가?",
  ui_story_2_9X_5_dialog_content = "그럴 리 없어. 내가 한번 감응해볼게.",
  ui_story_2_9X_6_dialog_content = "<color=#e8d9bb>콰콰쾅──!</color>",
  ui_story_2_9X_7_dialog_content = "이 경보는... 방어망에 구멍이 뚫렸나?!\n그럴 리가! 분명 가동률도 100%인데... 대체 어디에서...?",
  ui_story_2_9X_8_dialog_content = "바이스! 방어망에... ■■... 균열... ■■■... 공격을... 받고 있다! 너희는...",
  ui_story_2_9X_9_dialog_content = "뭐라고요? 카론 님, 잘 안 들려요!",
  ui_story_2_9X_19_dialog_content = "바이스! 암귀가 느껴져!",
  ui_story_2_9X_20_dialog_content = "암귀? 지하성에?! 말도 안 돼!",
  ui_story_2_9X_21_dialog_content = "세 마리... 열 마리... 점점 더 많아지잖아. 바이스, 암귀가 끊임없이 늘어나고 있어!",
  ui_story_2_9X_22_dialog_content = "방금 그 진동, 뭔가 예감이 안 좋아! 어쩌면 이 지하성은 이미...",
  ui_story_2_9X_23_dialog_content = "그럼 놈들이 오는 쪽으로 가자! 진짜로 암귀가 침입했다면, 놈들을 주거 구역 밖에서 막아내야 해!",
  ui_story_2_9X_24_dialog_content = "전투를 준비해줘, PlayerName!",
  ui_story_2_9X_25_dialog_content = "맡겨줘!",
  ui_story_2_9X_26_dialog_content = "가라... 죽여라... 보이는 모든 것을 파괴하라...",
  ui_story_2_9X_27_dialog_content = "더 이상의 실패는 없다... 오로리안의 피와 뼈로, 실패의 굴욕을 씻으리라!",
  ui_story_2_9X_28_dialog_content = "<size=45>이 지하성에 있는 모든 걸 없애버려라!</size>",
  ui_story_2_10_19_dialog_content = "바이스, PlayerName!",
  ui_story_2_10_20_dialog_content = "카론 님, 괜찮아요?",
  ui_story_2_10_21_dialog_content = "바이스?",
  ui_story_2_10_22_dialog_content = "<color=#FFB400>지하성의 방어망이 뚫렸다</color>... 성채를 곧바로 공격하다니, 이런 건 들어본 적도 없단 말이다!",
  ui_story_2_10_23_dialog_content = "게다가 왜 습격을 감행한 거지? 그것도 이렇게 조직적으로 지하성의 약점을 공격하다니 말이야.",
  ui_story_2_10_24_dialog_content = "이상해. 분명 뭔가가 있다! 지하성은 지금까지 이런 상황을 겪은 적이 없었다고!",
  ui_story_2_10_25_dialog_content = "그럼 지금은 어떻게 대응하죠?!\n우린 아직 싸울 수 있는 사람이 많으니까, 우선 구멍난 방어망 쪽으로 집결하죠!",
  ui_story_2_10_26_dialog_content = "퇴각 계획을 실행한다. 이미 대량의 암귀가 방어망을 돌파했으니,\n일루미나 규정에 따라 이는 S급 위협에 준하는 상황이다. 그러니 성을 버릴 수밖에 없다.",
  ui_story_2_10_27_dialog_content = "...죄송해요, 예상하지 못했어요...",
  ui_story_2_10_28_dialog_content = "정신 차려라, 바이스. 지금은 서둘러 부상자와 시민을 대피시켜야 한다!",
  ui_story_2_10_29_option_content = "상황이 그렇게 심각해?!",
  ui_story_2_10_30_option_content = "반격의 여지는 없는 거야?",
  ui_story_2_10_31_dialog_content = "주변을 봐라! 28호 지하성은 전투 전선이 아니다.\n이곳에 있는 건 부상자와 후방 담당 병사뿐이란 말이다!",
  ui_story_2_10_32_dialog_content = "최대한 힘을 비축하고, 우선 다른 지하성으로 피난하는 게 상책이다!",
  ui_story_2_10_33_dialog_content = "지금 상황은 어떻죠?",
  ui_story_2_10_34_dialog_content = "암귀 투성이다. 게다가 고위 암귀도 있는 듯하군... 어찌 됐든 우린 여기 있어서는 안 된다!",
  ui_story_2_10_A1_dialog_content = "맥거핀이야...",
  ui_story_2_10_35_dialog_content = "얼마 뒤면 이 지하성은 암귀의 소굴이 되고 말 거다...",
  ui_story_2_10_36_dialog_content = "알겠어요! PlayerName, 우린 너의 인도가 필요해. 함께 사람들을 대피시키자!",
  ui_story_2_10_40_dialog_content = "좋아, 단 한 사람도 포기할 수 없어!",
  ui_story_2_10_41_dialog_content = "당연하지. 나 역시 단 한 사람의 동료도 포기하지 않는다! 반드시 완벽하고 화려하게 철수하겠다!",
  ui_story_2_10_42_dialog_content = "가자, 시간이 없어!",
  ui_story_2_10_43_dialog_content = "바로 이거다! 오로리안에게 숨 돌릴 틈조차 주지 마라! 콜로서스와 아이테르의 위치를 발견하면...",
  ui_story_2_10_44_dialog_content = "<size=45>내게 바로 알려라!</size>",
  ui_story_2_12_3_dialog_content = "더럽고 구역질 나는 생물들, 그림자 안에서 얌전히 있으란 말이다!",
  ui_story_2_12_4_dialog_content = "어째서 이 화려한 지하성을 망가트리는 거지?! 정말 최악이군!",
  ui_story_2_12_5_dialog_content = "끄에엑──!",
  ui_story_2_12_6_dialog_content = "무슨 말인지 못 알아듣는단 말이다!",
  ui_story_2_12_7_dialog_content = "이대로 가다간 암귀가 우리보다 먼저 주거 구역에 도착하겠어!",
  ui_story_2_12_8_dialog_content = "카론 님, 기차는요? 그걸로 이동하면 안 되나요?",
  ui_story_2_12_9_dialog_content = "이곳엔 피안호가 이동할 철로가 없다.",
  ui_story_2_12_10_dialog_content = "그걸 지금 소환했다간 사람을 구하기는커녕 시체 하나 안 남을 거다.",
  ui_story_2_12_11_dialog_content = "절체절명의 순간 전까진...",
  ui_story_2_12_12_dialog_content = "근데 이게 정말 내가 알던 그 암귀인가? 어떻게 이렇게... 조직적이고, 명확한 목적을 보이는 거지?",
  ui_story_2_12_13_dialog_content = "<color=#FFB400>마치 뭔가를 향해...</color>",
  ui_story_2_12_14_dialog_content = "......",
  ui_story_2_12_15_dialog_content = "아, 놈들의 목표가 아이테르였나? 이번엔 정말 뜨거운 감자를 받은 모양이군...",
  ui_story_2_12_16_dialog_content = "<color=#e8d9bb>지하성이 다시 한번 요동치기 시작한다.</color>",
  ui_story_2_12_17_dialog_content = "인정하고 싶지 않지만, 우리 아무래도 궁지에 몰린 것 같은데?",
  ui_story_2_12_18_dialog_content = "아직 희망은 있어. 우리의 에이스가 아직 나서지 않았으니까!",
  ui_story_2_12_19_dialog_content = "PlayerName, 네 말은 설마...",
  ui_story_2_12_20_dialog_content = "<color=#FFB400>스카이워커호</color>!",
  ui_story_2_12_24_dialog_content = "맞아! 그럼 PlayerName하고 내가 전에 했던 것처럼...",
  ui_story_2_12_25_dialog_content = "그 녀석은 아직 에너지 충전 중이다. 지금이라면 아직 충전이 끝나지 않았을 거다.",
  ui_story_2_12_26_dialog_content = "그래도 해봐야 아는 거잖아요? 게다가 콜로서스는 모두를 데리고 이곳을 탈출할 수 있어요...",
  ui_story_2_12_X26_dialog_content = "가요. 지금은 우리의 운명을 스카이워커호한테 거는 수밖에 없어요.",
  ui_story_2_12_27_dialog_content = "이런 「위기의 순간」은 이제 익숙합니다. 하지만 서둘러야 합니다.",
  ui_story_2_12_X27_dialog_content = "암귀의 기운이 가까워지고 있습니다...",
  ui_story_2_12_28_dialog_content = "다른 방법이 없군. 난 가서 사람들을 콜로서스에 탑승시킬 준비를 하겠다.",
  ui_story_2_12_29_dialog_content = "그럼 우린 어서 가자! 콜로서스를 가동하는 거야!",
  ui_story_2_13_1_dialog_content = "<color=#e8d9bb>지하 정박장, 콜로서스 스카이워커호</color>",
  ui_story_2_13_2_dialog_content = "점점 많아지는군요...",
  ui_story_2_13_3_dialog_content = "그르르... 크으으...",
  ui_story_2_13_4_dialog_content = "역시나! 콜로서스 쪽에도 암귀가 모여들기 시작했어!",
  ui_story_2_13_5_dialog_content = "아...",
  ui_story_2_13_6_dialog_content = "저거... 설마 신호를 보내는 거야? 멀리 있는 동족과 소통하는 건가...?",
  ui_story_2_13_7_dialog_content = "알 게 뭐야! 일단 다들 콜로서스에 들어가자. 부상자와 아이들부터! 우리가 엄호할게!",
  ui_story_2_13_8_dialog_content = "기차를 쓸 필요는 없겠군... 오늘 화려한 피날레가 있을 것이라 여겼건만.",
  ui_story_2_13_9_dialog_content = "우선 이 정도로 만족해 볼까...",
  ui_story_2_13_10_dialog_content = "갑자기 그... 리모컨은 뭔데?",
  ui_story_2_13_11_dialog_content = "...<color=#FFB400>레드 키</color>? 그걸 언제...",
  ui_story_2_13_12_dialog_content = "모든 흔적을 지우는 건 S급 철수의 표준 과정이지 않나. 제법 볼만한 불꽃놀이가 될 거다.",
  ui_story_2_13_13_dialog_content = "하지만 이 지하성은 정말 아쉽군... 몇 년을 지낸 곳인데 말이야.",
  ui_story_2_13_14_dialog_content = "「28호 지하성의 책임관」이라...\n하, 결국 이 지하성을 지켜내지 못했으니, 불명예 퇴임을 하는 셈인가.",
  ui_story_2_13_15_dialog_content = "죄송해요...",
  ui_story_2_13_16_dialog_content = "왜 사과하는 거지? 설마 너희가 고의로 암귀를 유인하기라도 했나?",
  ui_story_2_13_17_dialog_content = "아니에요!",
  ui_story_2_13_18_dialog_content = "진정해라, 중위... 그저 농담일 뿐이니까.",
  ui_story_2_13_19_dialog_content = "그저 28호 지하성의 명이 다했다고 여길 수밖에. 누굴 원망할 문제가 아니다.",
  ui_story_2_13_20_dialog_content = "어쩌면... 만물에는 그 끝이 정해져 있을 테니까..",
  ui_story_2_13_21_dialog_content = "영원한 아침과 밤도 끝나는 날이 있듯이 말이야... 음, 이거 의도치 않게 멋진 시를 지어버렸군.",
  ui_story_2_13_22_dialog_content = "빨리 안 올라가고 뭐 하나? 레드 키에 죽어도 내 책임은 아니라고.",
  ui_story_2_13_23_dialog_content = "중위님! 암귀, 암귀 무리가 또 왔습니다! 뒤에는 아직 부상자가...!",
  ui_story_2_13_24_dialog_content = "알겠어! 우리가 버틸 테니, 남은 인원들은 서둘러!",
  ui_story_2_13_25_dialog_content = "피날레의 시간이 아직 오지 않은 건가. 일단 레드 키는 미뤄야겠군.",
  ui_story_2_14_1_dialog_content = "드디어 들어왔어! 모두 다친 데는 없어?",
  ui_story_2_14_2_dialog_content = "인원 체크 중입니다! 다 온 것 같습니다만... 카론 님은 어디 계십니까?",
  ui_story_2_14_3_dialog_content = "카론 님? 다른 곳에서 콜로서스 탑승구를 엄호하고 계셔...",
  ui_story_2_14_4_dialog_content = "오래 기다리게 해서 죄송합니다, 중위님! 남은 사람은 없겠죠?!\n암귀도 이미 발 디딜 틈이 없을 정도로 많아졌습니다!",
  ui_story_2_14_5_dialog_content = "고마워! 이런 고생에 휘말리게 해서 정말...",
  ui_story_2_14_6_dialog_content = "중위님, 그런 말씀 마십시오! 우선 사람들을 데리고 이곳을 떠나는 게 좋겠습니다. 가시죠!",
  ui_story_2_14_7_dialog_content = "잠깐! 아직 남은 사람이 있어! 카론 님은 어디 계신 거지?",
  ui_story_2_14_8_dialog_content = "카론 님이라면 방금 낙오된 부상자를 엄호하고 있는 걸 봤습니다! 아마...",
  ui_story_2_14_9_dialog_content = "보인다! 저기 계셔!",
  ui_story_2_14_10_dialog_content = "젠장, 이 녀석들이 내 옷을 더럽혔군...",
  ui_story_2_14_11_dialog_content = "그 사람은 아직도 고군분투하고 있습니다. 모든 지하성의 암귀가 모여들고 있습니다.",
  ui_story_2_14_12_dialog_content = "놈들의 진격 루트는 명확합니다. 모두 저를 노리고 달려들고 있습니다.",
  ui_story_2_14_13_dialog_content = "어서 타요!",
  ui_story_2_14_14_dialog_content = "나도 그러고 싶다고! 하지만 이 개돼지들이! 날! 화가! 나게! 하잖아!",
  ui_story_2_14_15_dialog_content = "적어도 너희에게 접근하게 두진 않겠다!",
  ui_story_2_14_16_dialog_content = "안 되겠어, 카론 님을 지원하러 갈게... PlayerName, 같이 가자! 다른 사람은 제자리에서 기다려!",
  ui_story_2_14_17_dialog_content = "캬악──?!",
  ui_story_2_14_18_dialog_content = "너무 많아! 전진하는 것조차... 힘들어!",
  ui_story_2_14_19_dialog_content = "가동이 더 늦는다면 우리도 함께 묻혀버릴 겁니다. 지금은 망설일 때가 아닙니다.",
  ui_story_2_14_20_option_content = "바이스, 이제 가야 해.",
  ui_story_2_14_21_dialog_content = "안 돼! 우린 한 사람도 버리지 않을 거라고!",
  ui_story_2_14_22_dialog_content = "PlayerName의 말이 맞습니다. 우린 빨리 떠나야 합니다!",
  ui_story_2_14_23_dialog_content = "카론 님은 널 구했잖아! 아니, 우리 모두가 그에게 빚이 있어...\n이건 일루미나인의 정신에 어긋나는 일이라고!",
  ui_story_2_14_24_dialog_content = "하지만 우리도 모든 주민의 목숨을 담보로 모험을 할 순 없잖아!",
  ui_story_2_14_25_dialog_content = "알고 있어... 나도 물론 그 정도는 안단 말이야... 정말, 대체 왜 이렇게 돼버린 거야?!",
  ui_story_2_14_26_option_content = "안 돼, 카론 씨를 구해야 해.",
  ui_story_2_14_27_dialog_content = "확실합니까? PlayerName.",
  ui_story_2_14_28_dialog_content = "이 지하성의 모든 주민이 이곳에 있습니다. 실패의 대가가 어떨지 똑똑히 생각하셨습니까?",
  ui_story_2_14_29_dialog_content = "난 우리가 해낼 거라고 믿어!",
  ui_story_2_14_31_dialog_content = "그 변함없는 자신감이, 기적을 일으킬지도 모르지요...",
  ui_story_2_14_32_dialog_content = "그게 바로 당신이 남들과 다른 점일지도 모르겠습니다, PlayerName...",
  ui_story_2_15_1_dialog_content = "카론 님!",
  ui_story_2_15_X1_dialog_content = "크오오오!",
  ui_story_2_15_F1_dialog_content = "이런, 전혀 다가갈 수가 없어...",
  ui_story_2_15_X2_dialog_content = "바이스! 어리석은 짓 마라!",
  ui_story_2_15_X3_dialog_content = "이 더러운 것들, 용서할 수 없다! 본때를 보여주마!",
  ui_story_2_15_X4_dialog_content = "<color=#e8d9bb>슈우웅──!</color>",
  ui_story_2_15_A1_dialog_content = "카론 님?! 지금 뭘 하시는 거죠?! 지금 신호탄을 쏘면 암귀가 더 많이 몰려올 거예요!",
  ui_story_2_15_X6_dialog_content = "중위, 뭘 기다리는 거냐?! 정말 미숙하군! 멋대로 성가시게 굴지 말란 말이다!",
  ui_story_2_15_2_dialog_content = "이 몸은 삼도천 열차의 카론, 명예와 외모의 결정체, 내 영광스러운 사명을 방해하지 마라!",
  ui_story_2_15_3_dialog_content = "설마 지금... 일부러 그러신 건가요?!",
  ui_story_2_15_4_dialog_content = "PlayerName, 내 화려한 자태에 미련을 버리고, 어서 출발해라!",
  ui_story_2_15_5_dialog_content = "카론 님, 지금은 그런 말을 할 때가 아니라구요! 책임관님이 승선하지 않으시면, 저흰 절대...",
  ui_story_2_15_A2_dialog_content = "안심해라! 이 정도 적으론 날 막을 수 없다. 알잖나, 바이스!",
  ui_story_2_15_A3_dialog_content = "너희들이 오히려 방해된단 말이다! 이 삼도천 열차, 암귀 도살자 카론을 막지 말란 거다!",
  ui_story_2_15_A4_dialog_content = "카론 님...",
  ui_story_2_15_A5_dialog_content = "중위, 어서 모두를 데리고 떠나라! 이건 명령이다! 난 알아서 탈출할 테니 말이다.",
  ui_story_2_15_A6_dialog_content = "...알겠습니다. PlayerName, 가동을 준비하자...",
  ui_story_2_15_A7_dialog_content = "가동에 성공했어...",
  ui_story_2_15_A8_dialog_content = "스카이워커, 탑승구를 열어둬. 카론 씨가 언제든 올 수 있으니까!",
  ui_story_2_15_A9_dialog_content = "PlayerName, 정말 확신하십니까?",
  ui_story_2_15_A10_dialog_content = "...무슨 뜻이야?",
  ui_story_2_15_A11_dialog_content = "카론 그 사람... 전혀 「따라오려는」 모습이 아닙니다.",
  ui_story_2_15_A12_dialog_content = "오히려 지금 암귀 무리 속으로 나아가고 있습니다...",
  ui_story_2_15_A13_dialog_content = "뭐라고?! 카론 씨, 설마...",
  ui_story_2_15_6_dialog_content = "이, 이 경보음은?!",
  ui_story_2_15_7_dialog_content = "중위님! 자폭 프로그램입니다. 카론 님이 레드 키를 누르셨습니다!",
  ui_story_2_15_8_dialog_content = "그런 건 나도 알아!",
  ui_story_2_15_A14_dialog_content = "카론 님은... 처음부터 이럴 생각이셨던 거야...!?",
  ui_story_2_15_9_dialog_content = "엔진 분사구가 정리됐습니다. 그 오로리안, 잊지 않겠습니다. 그럼 꽉 잡으십시오.",
  ui_story_2_15_10_option_content = "출발!",
  ui_story_2_15_13_dialog_content = "선체에 파손이 발생했습니다. 백색 날개에 <color=#FFB400>뭔가 걸린 것 같습니다만, 이 무게감은 심상치 않군요.</color>",
  ui_story_2_15_14_dialog_content = "......",
  ui_story_2_15_15_option_content = "괜찮아?",
  ui_story_2_15_17_dialog_content = "...꽉 잡아, PlayerName. 아직 위험에서 벗어난 건 아니니까...",
  ui_story_2_15_18_dialog_content = "카론 님이 레드 키를 눌렀어. 지하성이... 폭발하기 전에 반드시 안전한 고도까지 날아올라야 해.",
  ui_story_2_15_19_option_content = "미안해...",
  ui_story_2_15_20_option_content = "카론 씨는...",
  ui_story_2_15_21_dialog_content = "약속했어... 누구도 포기하지 않겠다고... 약속했는데...",
  ui_story_2_15_F2_dialog_content = "네 잘못이 아니야, PlayerName. 이건 내 탓이야...",
  ui_story_2_15_22_dialog_content = "내가 더 노력했다면... 아니, 다른 길로 마중을 나갔다면...\n암귀의 방해를 피할 수 있었을지도 몰라.",
  ui_story_2_15_23_dialog_content = "아니, 어쩌면 처음부터 카론 님과 따로 움직이는 게 아니었는데...",
  ui_story_2_15_24_dialog_content = "감동적인 연극은 거기까지다. 하마터면 놓칠 뻔했군.",
  ui_story_2_15_25_dialog_content = "정말 끈질긴 녀석들이로군... 내 예상을 뛰어넘었다.",
  ui_story_2_15_26_dialog_content = "대체 어떻게...?!",
  ui_story_2_15_27_dialog_content = "포기해라, 저항해 봐야 의미 없다! 네놈들의 잔꾀에 또 넘어갈 일은 없을 거다. 절대...",
  ui_story_2_15_28_option_content = "어째서 날 쫓아온 거지?",
  ui_story_2_15_29_dialog_content = "난 내 사명을 완수해야 한다.",
  ui_story_2_15_30_dialog_content = "그 사명은 말이지. 바로 신앙이 없는 모든 생명을 없애는 것이다.",
  ui_story_2_15_31_option_content = "대체 너희 목적이 뭐야?!",
  ui_story_2_15_32_dialog_content = "이 모든 것은 우리의 사명을 위해서다.",
  ui_story_2_15_33_dialog_content = "우리의 힘은 우리의 믿음에서 나오지.",
  ui_story_2_15_34_dialog_content = "그리고 우리의 믿음은 우리의 어머니에게서 나온다.",
  ui_story_2_15_35_dialog_content = "아이테르, 그리고 오로리안, 이 대륙에서 연명하고 있는 하등한 생물들,\n우리에게 죽는 것이 너희가 누릴 수 있는 가장 큰 행복이다.",
  ui_story_2_15_36_dialog_content = "무의미한 몸부림을 멈춰라. 그저 고통만 늘어날 뿐이니. 그 어리석은 병사들처럼 말이지.",
  ui_story_2_15_37_dialog_content = "비행을 멈추고 땅으로 돌아가라. 그럼 모든 오로리안이 유쾌한 종말을 맞이할 수 있을 거다.",
  ui_story_2_15_38_dialog_content = "난 항복하지 않아. 그리고 절대... 내 동료를 해치게 두지 않겠어!",
  ui_story_2_15_39_dialog_content = "명예로운 죽음을 원하는가? 좋다.",
  ui_story_2_15_40_dialog_content = "그럼 그 집념에 어울리는 죽음을 선사하지.",
  ui_story_2_15_41_dialog_content = "그러나 너희는 가장 잔인한 방식으로 죽음에 이르게 될 것이다.",
  ui_story_2_15_89_dialog_content = "주인이시여... 저는... 실패했습니다...",
  ui_story_2_15_91_dialog_content = "허나, 이게... 끝은 아니다...",
  ui_story_2_15_X92_dialog_content = "내 참회라도 듣고 싶나? 하하... 하하하하...",
  ui_story_2_15_X93_dialog_content = "순간뿐인 하찮은 「승리」 속에서 허우적대라!",
  ui_story_2_15_X94_dialog_content = "결국 주인님께서 너흴 심판할 것이다.\n그분께서 직접 너흴 마주하는 순간, 오로리안이든 나약한 아이테르든...",
  ui_story_2_15_X95_dialog_content = "그 비열한 목구멍에서 신음 하나 내뱉지 못하리라...",
  ui_story_2_15_92_dialog_content = "「슈모르」. 이 이름을 머릿속에 새겨둬라.",
  ui_story_2_15_93_dialog_content = "그분의 힘을 너희는 결코 상상조차 하지 못할 것이다.",
  ui_story_2_15_42_dialog_content = "...이번에는 다시 돌아올 수 없겠지.",
  ui_story_2_15_43_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_2_15_44_dialog_content = "28호 지하성이... 폭발했어...",
  ui_story_2_15_45_dialog_content = "<color=#e8d9bb>불꽃은 여명과 함께 찾아왔다. 마치 새로운 생명에게 인사하고, 떠난 이들을 애도하듯이...</color>",
  ui_story_2_15_46_dialog_content = "안녕... 지하성 28호. 그리고 카론 님...",
  ui_story_2_15_47_dialog_content = "정말 미안해...",
  ui_story_2_15_48_dialog_content = "그건 그분의 선택이었어. PlayerName, 네 잘못이 아니야.",
  ui_story_2_15_49_dialog_content = "우릴 지키기 위해 자신의 안위도 생각하지 않고, 마지막까지 그렇게...",
  ui_story_2_15_51_option_content = "그는 모두에게 모범이 될 거야.",
  ui_story_2_15_52_dialog_content = "하지만 목숨을 잃었는데, 모범이 되는 게 무슨 의미가 있어...?",
  ui_story_2_15_B1_dialog_content = "모두가 말하는 「모범」은 대체 무슨 뜻인 거지...?",
  ui_story_2_15_B2_dialog_content = "난 이렇게 생각해. 카론 씨는 자신이 「소중히 여기는 것」들을 지키려 한 거야.",
  ui_story_2_15_B3_dialog_content = "......",
  ui_story_2_15_B4_dialog_content = "병사, 동료, 친구... 그리고 이 지하성 말이야.",
  ui_story_2_15_53_option_content = "그는 우리 모두의 마음속에서 살아갈 거야.",
  ui_story_2_15_54_dialog_content = "마음속에? 냉정하게 들릴 수도 있겠지만... 그렇다고 죽은 사람이 살아 돌아오지는 않아, PlayerName.",
  ui_story_2_15_55_dialog_content = "살아남은 사람들만 괴로울 뿐이라고...",
  ui_story_2_15_B5_dialog_content = "네가 겪었던 그 고통처럼 말이야. 설마 이런 결말을 납득하는 건 아니지...?",
  ui_story_2_15_B6_dialog_content = "하지만 받아들일 수밖에 없어...",
  ui_story_2_15_B7_dialog_content = "카론 씨는 「소중히 여기는 것」들을 지키기 위해 희생한 거야. 병사와, 동료들을 위해...",
  ui_story_2_15_B8_dialog_content = "그 마음을 저버려서는 안 돼, 바이스.",
  ui_story_2_15_B9_dialog_content = "무슨 뜻인지 알아, PlayerName. 하지만 지금은 너무 혼란스러워...",
  ui_story_2_15_B10_dialog_content = "남을 지키고, 희생하는 것, 그게 일루미나의 미덕이라는 건 당연히 알고 있어.",
  ui_story_2_15_B11_dialog_content = "하지만 주변 사람들이 하나둘씩 떠나가는 걸 보면... 말처럼 쉽게 받아들일 수가 없어.",
  ui_story_2_15_57_dialog_content = "우린 매일 「여명의 빛」을 위한다고 말하지만, 우린... 정말로 오로라의 일부가 되어\n후손들을 지킬 수 있는 걸까...?",
  ui_story_2_15_58_dialog_content = "만약 언젠가...",
  ui_story_2_15_59_dialog_content = "언젠가... 우리 역시 똑같은 결정을 내려야 할 때가 온다면...",
  ui_story_2_15_60_dialog_content = "상상조차 못 하겠어...",
  ui_story_2_15_61_dialog_content = "「희망」.",
  ui_story_2_15_62_dialog_content = "......?",
  ui_story_2_15_63_dialog_content = "카론 씨가 그랬어. 「만약 절망을 바꿀 수 없다면, 희망으로 영원한 암흑을 메워나가면 된다」고 말이야.",
  ui_story_2_15_66_option_content = "...정말 그 사람과 어울리는 말이라니까.",
  ui_story_2_15_F3_dialog_content = "「삼도천 열차의 카론」, 난 그 이름을 절대 잊지 않을 거야.",
  ui_story_2_15_F4_dialog_content = "「삼도천 열차」...?",
  ui_story_2_15_F5_dialog_content = "왜 그래?",
  ui_story_2_15_70_dialog_content = "근데 카론 씨는 왜 「삼도천 열차」라고 불리는 건데?",
  ui_story_2_15_71_dialog_content = "그건 그분의 그... 현란한 기차 때문이야. 너도 봤잖아.",
  ui_story_2_15_72_dialog_content = "카론 님은 전임 지하철 관리자였어.\n그래서 언제든지 그 「피안호」라는 기차를... 소환할 수... 있는 거야...",
  ui_story_2_15_73_dialog_content = "앗!",
  ui_story_2_15_74_dialog_content = "기차? 잠깐만... 그 신호탄은...",
  ui_story_2_15_79_dialog_content = "그럼 설마...",
  ui_story_2_15_80_dialog_content = "바이스 중위님, PlayerName 씨! 하늘을 보십시오!",
  ui_story_2_15_81_dialog_content = "...<color=#FFB400>아무래도 모든 것이 그의 연극이었던 모양입니다</color>.",
  ui_story_2_15_82_dialog_content = "<size=45>화──려한 피날레였다!</size>",
  ui_story_2_15_A15_dialog_content = "불꽃과 박수 소리, 그리고 감동에 찬 모두의 눈물까지! 이 몸이 기꺼이 받아주도록 하지!",
  ui_story_2_15_83_dialog_content = "<size=45>삼도천 열차 카론, 이 자리에 등장!</size>",
  ui_story_2_15_84_dialog_content = "관객들이여, 날 위한 감동의 눈물을 흘렸는가!",
  ui_story_2_15_F6_dialog_content = "그럼 행운의 관객을 무작위로 추첨해 소감을 듣도록 하지. PlayerName, 기분이 어떤가?",
  ui_story_2_15_X85_dialog_content = "에... 저, 정말 멋진 퍼포먼스였어...",
  ui_story_2_15_85_dialog_content = "...역시... 카론 님 답다고 해야 할까요...",
  ui_story_2_15_86_dialog_content = "정말... 기뻐해야 할지, 화를 내야 할지 모르겠네...",
  ui_story_2_15_87_option_content = "다행이야... 으윽!",
  ui_story_2_15_88_dialog_content = "PlayerName?",
  ui_story_2_15_X88_dialog_content = "아... 머리가... 또 시작이야...",
  ui_story_2_15_95_dialog_content = "언젠가 본 것만 같은 광경...",
  ui_story_2_15_96_dialog_content = "바이스...",
  ui_story_2_15_100_dialog_content = "PlayerName! 나 여기 있어! 정신 바짝 차려!",
  ui_story_2_15_101_dialog_content = "<color=#e8d9bb><color=#FFB400>콜로서스 유적</color>의 다른 어딘가</color>",
  ui_story_2_15_102_dialog_content = "......",
  ui_story_2_15_103_dialog_content = "괜찮으십니까?",
  ui_story_2_15_104_dialog_content = "왜 그런 말을 하는 건데?",
  ui_story_2_15_105_dialog_content = "방금 한눈을 파셨습니다. 오랫동안 기다려온 기회인데, 정신을 다른 곳에 팔지는 않으시겠죠...",
  ui_story_2_15_106_dialog_content = "...불필요한 질문은 하지 마, 암귀. 난 그저... 아마 착각일 거야.",
  ui_story_2_15_107_dialog_content = "그럼 순조로운 사냥이 되시길. 부디 당신이 줄곧 원하던 물건을 찾으시길 바랍니다.",
  ui_story_2_15_108_dialog_content = "사냥이라... 흥, 그 표현은 그래도 마음에 드네.",
  ui_story_2_15_109_dialog_content = "내 목소리가 들려? ...난 네 존재를 느낄 수 있어...",
  ui_story_2_15_110_dialog_content = "아마 넌 지금쯤 <color=#FFB400>동족</color>인 내 존재를 감응했겠지... 내겐 시간이 얼마 남지 않았어.",
  ui_story_2_15_111_dialog_content = "디바우러호, <color=#FFB400>그 여자</color>... 불길한 검은색... 동족상잔의 죄인...",
  ui_story_2_15_112_dialog_content = "그 여자가 날 찾아냈어...",
  ui_story_2_15_113_dialog_content = "나와 내 콜로서스에겐... 이제 시간이 없어...",
  ui_story_3_1_1_dialog_content = "들려? 비록 널 모르지만, 그래도 네가 내 「동족」인 건 알 수 있어...",
  ui_story_3_1_2_dialog_content = "넌... 분명히 내 목소리를... 들을 수 있을 거야...",
  ui_story_3_1_3_dialog_content = "신호탄을 발사했다. 모두 움직이지 말고 제자리에서 대기하도록.",
  ui_story_3_1_4_dialog_content = "으음? 바이스, PlayerName 녀석이 깨어났다!",
  ui_story_3_1_5_dialog_content = "헌데 아직도 화려했던 내 공연의 여운 속에 빠져있는 것 같군.",
  ui_story_3_1_6_dialog_content = "정말 고마워요. 카론 님, 이제 가서 응급 치료를 받으세요!",
  ui_story_3_1_7_dialog_content = "괜찮다. 난 아주 멀쩡하다고.\n하지만 방금 내 영웅적인 자태를 진귀한 영상 자료로 남겨두지 못한 게 아쉽군...",
  ui_story_3_1_8_dialog_content = "...그게 중요한가요...",
  ui_story_3_1_9_dialog_content = "그나저나 레드 키의 위력은 정말 엄청나군. 사실 전부터 눌러보고는 싶었다만...",
  ui_story_3_1_10_dialog_content = "카론 님, 28호 지하성이 폐허가 되어 버렸는데... 아쉽지 않으세요?",
  ui_story_3_1_11_dialog_content = "물론 아쉽지. 하지만 눈물을 흘리며 슬퍼할 정도는 아니다.\n왜냐하면, 우리에게 아직 <color=#FFB400>터전</color>이 남아있기 때문이지.",
  ui_story_3_1_12_dialog_content = "터전?",
  ui_story_3_1_13_dialog_content = "그래, 주위를 봐라.",
  ui_story_3_1_14_dialog_content = "주민과 병사들, 일루미나 연방에서 가장 중요한 「자산」이 모두 무사하지 않나.",
  ui_story_3_1_15_dialog_content = "「소중한 것」이 있는 곳, 그곳이 바로 우리의 터전이다.",
  ui_story_3_1_F1_dialog_content = "음...",
  ui_story_3_1_16_dialog_content = "자네와 저 아이테르도 다치진 않았겠지? 생각해 보니 자네들을 구하는 것도 벌써 두 번째인가.",
  ui_story_3_1_F2_dialog_content = "고마워요, 카론 님...",
  ui_story_3_1_17_dialog_content = "그럼 일단 피해 상황을 확인해야겠군. 너흰 멋대로 다니지 말고 여기서 명령을 기다려라!",
  ui_story_3_1_18_dialog_content = "네, 알겠어요...",
  ui_story_3_1_19_dialog_content = "카론 씨는... 의외로 상냥하네.",
  ui_story_3_1_20_dialog_content = "PlayerName, 괜찮아? 방금...",
  ui_story_3_1_B1_dialog_content = "괜찮아, 아무것도 아냐.",
  ui_story_3_1_B2_dialog_content = "안색이 안 좋으니까 너무 무리하지 마.",
  ui_story_3_1_B3_dialog_content = "고마워, 바이스... 계속 함께 있어 줘서.",
  ui_story_3_1_B4_dialog_content = "헤에, 천만에, 우린 이미 잘 맞는 파트너잖아!",
  ui_story_3_1_B5_dialog_content = "네 덕에 우리도 고위 암귀들을 물리칠 수 있었고 말이야~",
  ui_story_3_1_B6_dialog_content = "이건 그저 <color=#FFB400>시작</color>일 뿐이야, 바이스.",
  ui_story_3_1_B7_dialog_content = "에? 시작?",
  ui_story_3_1_B8_dialog_content = "맥거핀이 죽기 전에 또 그 이름을 말했어... <color=#FFB400>슈모르</color>.",
  ui_story_3_1_B9_dialog_content = "「슈모르」... 대체 어떤 녀석인 거지?",
  ui_story_3_1_B10_dialog_content = "아직은 잘 모르겠어. 하지만 그 녀석은 분명히 모든 진실을 알고 있을 거라고 생각해.",
  ui_story_3_1_B11_dialog_content = "미안해, 바이스. 난 반드시 「슈모르」를 찾고, 진실을 알아내야만 해.",
  ui_story_3_1_B12_dialog_content = "PlayerName... 왜 갑자기 그렇게 의욕을 내게 된 거야?",
  ui_story_3_1_B13_dialog_content = "난... 내 「<color=#FFB400>터전</color>」을 다시 찾았어.",
  ui_story_3_1_B14_dialog_content = "...내가 부상을 치료하는 동안 카론 님이랑 둘이서 이상한 암호라도 주고받은 건 아니지...?",
  ui_story_3_1_B15_dialog_content = "대신 맥거핀한테서 「슈모르」에 대한 정보를 더 얻지 못한 건 아쉬운걸...",
  ui_story_3_1_B17_dialog_content = "괜찮아. 일루미나 연방의 총사령부에 돌아가면 관련 자료를 찾을 수 있을지도 몰라.",
  ui_story_3_1_B18_dialog_content = "PlayerName? 왜 그래...?",
  ui_story_3_1_B21_dialog_content = "──구해줘...",
  ui_story_3_1_B22_dialog_content = "──어서── ...들려!?──",
  ui_story_3_1_B23_dialog_content = "PlayerName, 느껴지십니까? 조금 전부터 마치...",
  ui_story_3_1_B24_dialog_content = "맞아. <color=#FFB400>누군가 우리한테 도와달라고 하는 것 같은데</color>?",
  ui_story_3_1_21_dialog_content = "──디바우러... 호가... 지금── ...이제... 난 시간이 없어──",
  ui_story_3_1_22_dialog_content = "너한테 무슨 소리가 들린다는 거지?",
  ui_story_3_1_23_option_content = "이런 감응을 할 수 있는 건 아이테르밖에 없어!",
  ui_story_3_1_24_dialog_content = "내 동족이야...! 나처럼 살아남은 <color=#FFB400>생존자</color>인 걸까?!",
  ui_story_3_1_25_dialog_content = "그렇습니다. 게다가 전달하는 내용으로 볼 때, 굉장히 위험한 상황에 처한 듯합니다.",
  ui_story_3_1_26_dialog_content = "어쩌면 우리와 같은 처지일지도 모르겠습니다...",
  ui_story_3_1_27_option_content = "남자애 목소리였어.",
  ui_story_3_1_28_dialog_content = "그렇습니다. 그의 의식은 공포로 가득 차 있었습니다. 절망적인 상황인 것 같습니다.",
  ui_story_3_1_F3_dialog_content = "이렇게 감응할 수 있다는 건... 내 동족인 건가?!",
  ui_story_3_1_29_dialog_content = "그렇습니다. 하지만 상대방 콜로서스의 신호가 미약한 탓에,\n제가 여러 차례 연결을 시도했지만 포착되질 않고 있습니다.",
  ui_story_3_1_30_dialog_content = "도움을 청하고 있었어. 그 사람과 그의 콜로서스한테 뭔가 무서운 일이 벌어지고 있는 것 같아...",
  ui_story_3_1_31_dialog_content = "<color=#FFB400>또 다른 아이테르</color>인 거야?",
  ui_story_3_1_32_dialog_content = "그럼 그 사람을 찾으면 다른 콜로서스도 찾을 수 있다는 거야?",
  ui_story_3_1_33_dialog_content = "바이스, 날 도와줄 수 있을까?",
  ui_story_3_1_34_dialog_content = "......",
  ui_story_3_1_35_dialog_content = "중위, 나한테 말할 일이 있나?",
  ui_story_3_1_36_dialog_content = "에... 저희가...",
  ui_story_3_1_37_dialog_content = "다른 아이테르의 구조 요청을 받았어!",
  ui_story_3_1_38_dialog_content = "...?!",
  ui_story_3_1_39_dialog_content = "갑자기 아이테르가 둘이나 나타나다니, 뭐가 어떻게 된 거냐?",
  ui_story_3_1_40_dialog_content = "확실해. 그 감응 방식은 나와 똑같았어!",
  ui_story_3_1_41_dialog_content = "어디지? 근처에 있나?",
  ui_story_3_1_42_dialog_content = "그건 모르겠어... 하지만 대략적인 방향 정도는 알 수 있어... 지금 바로 출발해야 해!",
  ui_story_3_1_43_dialog_content = "......",
  ui_story_3_1_44_dialog_content = "그럴 순 없다.",
  ui_story_3_1_45_dialog_content = "책임관님!",
  ui_story_3_1_46_dialog_content = "조직은 규율을 따라야 한다! 방금 너희가 얼마나 큰 혼란을 일으켰는지 모르는 거냐!",
  ui_story_3_1_47_dialog_content = "하지만...",
  ui_story_3_1_48_dialog_content = "모두가 보고 있다. 이럴 때 혼란을 가중해선 안 된단 말이다.",
  ui_story_3_1_49_dialog_content = "게다가 네 직속상관, 제3군단의 히이로 군단장이 곧 도착할 거다.",
  ui_story_3_1_50_dialog_content = "상관에게 현재 상황에 대해 보고도 안 할 셈인가?",
  ui_story_3_1_51_dialog_content = "......",
  ui_story_3_1_52_dialog_content = "하지만 이대로 시간을 허비하고 있을 순 없어요...",
  ui_story_3_1_53_dialog_content = "이런 단서를 언제 또 찾을 수 있을지 모른다구요.",
  ui_story_3_1_54_dialog_content = "게다가 그 사람은 정말 도움이 필요해 보였어! 분명 위험한 상황일 거라고!",
  ui_story_3_1_55_dialog_content = "그 사람은 내 동족이야, 카론 씨. 내 진정한... 아직 살아있는 동족이라고!",
  ui_story_3_1_56_dialog_content = "............",
  ui_story_3_1_57_dialog_content = "책임관님...",
  ui_story_3_1_58_dialog_content = "네게 얼마나 중요한 일인지는 충분히 이해한다. PlayerName.",
  ui_story_3_1_59_dialog_content = "하지만 일루미나 연방도 규칙이 있다. 특히 나 같은 장교가 현장에 있다면 더욱 엄격히 지켜야 하지.",
  ui_story_3_1_60_dialog_content = "다만...",
  ui_story_3_1_61_dialog_content = "...!",
  ui_story_3_1_62_dialog_content = "...다만 내가 너희의 계획에 대해 모르고 있는 경우라면 예외가 되겠지.",
  ui_story_3_1_63_dialog_content = "에?",
  ui_story_3_1_64_dialog_content = "바이스 자네도 엄연한 중위이지 않나. 게다가 내가 자네 직속상관도 아니고 말이야.",
  ui_story_3_1_A1_dialog_content = "그러니 자네도 어느 정도의 단독 결정권을 가지고 있다는 거다.\n일루미나 연방을 위험에 빠트리는 일만 아니라면 말이야.",
  ui_story_3_1_A2_dialog_content = "크흠, 다시 한번 강조하지. 일루미나 연방의 동료들이 모두 지켜보고 있다.",
  ui_story_3_1_A3_dialog_content = "어떻게 해야 할지 알았어, 바이스.",
  ui_story_3_1_65_dialog_content = "좋은 생각이라도 있어?",
  ui_story_3_1_B25_option_content = "몰래 나가면 돼.",
  ui_story_3_1_B26_option_content = "연기를 하면 돼.",
  ui_story_3_1_66_dialog_content = "PlayerName, 카론 님 앞에서 그런 말을 하면 어떡해...",
  ui_story_3_1_67_dialog_content = "음? 무슨 말을 했나? 방금 바람 소리가 너무 커서 아무것도 못 들었다만.",
  ui_story_3_1_68_dialog_content = "......",
  ui_story_3_1_B26_dialog_content = "카론 님, 설마 방금 저희한테 암시를...",
  ui_story_3_1_B27_dialog_content = "암시? 난 아무것도 암시하지 않았다! 무슨 소리를 하는 건가.",
  ui_story_3_1_B28_dialog_content = "방금 그건 그저 중위로서 자네가 어떤 선택을 할 수 있는지를 다시 알려준 것뿐이었다, 바이스.",
  ui_story_3_1_B29_dialog_content = "어떻게 할 것인지는 결국 너희들의 선택이지.",
  ui_story_3_1_B30_dialog_content = "알겠어요, 책임관님. 감사해요.",
  ui_story_3_1_B31_dialog_content = "곧 히이로가 도착한다. 만약 「내가 모르는 일」 같은 걸 하려면 지금 하는 게 좋을 거다.",
  ui_story_3_1_B32_dialog_content = "히이로가 온 뒤라면 정말로 남아서 보고를 해야 할 테니 말이다.",
  ui_story_3_1_B33_dialog_content = "카론 씨는... 정말 재미있는 사람이네.",
  ui_story_3_1_B34_dialog_content = "휴... 긴장돼. 너무 긴장된다고... 히이로 군단장님이 어떤 반응을 보이실지...",
  ui_story_3_1_B35_dialog_content = "연기...?",
  ui_story_3_1_B36_dialog_content = "흠, 흠흠!",
  ui_story_3_1_B37_dialog_content = "아, 카론 씨. 이 일을 얘기해도 될지... 잘 모르겠어!",
  ui_story_3_1_B38_dialog_content = "얼마든지 말하게. 아이테르!",
  ui_story_3_1_B39_dialog_content = "방금 스카이워커호한테 들었는데, 대규모의 암귀가 콜로서스의 흔적을 따라 쫓아오고 있다고 해!",
  ui_story_3_1_B40_dialog_content = "에? 뭐라고?",
  ui_story_3_1_B41_dialog_content = "뭐라고?! 콜로서스가 더 많은 암귀를 끌어들이고 있다는 말이냐!?",
  ui_story_3_1_B42_dialog_content = "이런 일을 왜 더 빨리 보고하지 않은 건가! 정말 위험한 일이 아닌가!",
  ui_story_3_1_B43_dialog_content = "???",
  ui_story_3_1_B44_dialog_content = "(바이스! 너도 「연기」를 거들어!)",
  ui_story_3_1_B45_dialog_content = "아, 아! 죄송해요. 저도... 방금 알게 된... 모양인데요...?",
  ui_story_3_1_B46_dialog_content = "흥! 정말 이해할 수 없군! 방금 지옥 불에서 벗어난 이들을 더 큰 위험에 밀어 넣으려고 하다니!",
  ui_story_3_1_B47_dialog_content = "집단을 위협하는 이런 행위는 결코 용납할 수 없다!",
  ui_story_3_1_B48_dialog_content = "어, 그...그럼 어떡하죠!?",
  ui_story_3_1_B49_dialog_content = "어서 이 콜로서스를 끌고 가라! 불쌍한 사람들에게서 멀리 떨어지란 말이다!",
  ui_story_3_1_B50_dialog_content = "네! 알겠어요!",
  ui_story_3_1_B51_dialog_content = "(얼른 가자!)",
  ui_story_3_1_B52_dialog_content = "고, 고마워요, 카론 님.",
  ui_story_3_1_B53_dialog_content = "...흥.",
  ui_story_3_1_B55_dialog_content = "방금 그 어색한 연극... 꼭 해야 하는 거였어...?",
  ui_story_3_1_B56_dialog_content = "모르겠어. 하지만 카론 씨는 즐거워하는 것 같던데?",
  ui_story_3_1_B57_dialog_content = "게다가 우리도 떠날 이유는 있어야 하잖아. 네 직속 상관이 오기 전에 말이야.",
  ui_story_3_1_B58_dialog_content = "맞아, 히이로 님...",
  ui_story_3_1_B59_dialog_content = "휴우, 히이로 군단장님이 우리가 멋대로 떠났다는 걸 알게 되면 뭐라고 하실까...",
  ui_story_3_1_69_option_content = "후회해?",
  ui_story_3_1_70_dialog_content = "아니!",
  ui_story_3_1_71_dialog_content = "그 「히이로」라는 상관이 이해심이 많은 사람이었으면 좋겠네.",
  ui_story_3_1_72_dialog_content = "...네가 그렇게 말하니까 조금 후회되는걸.",
  ui_story_3_1_73_option_content = "이게 옳은 선택이었으면 좋겠어.",
  ui_story_3_1_74_dialog_content = "옳은 선택인지 아닌지는 아무도 모를 거야...",
  ui_story_3_1_76_dialog_content = "으아아아, 히이로 님이 절대 날 가만 두지 않으실 거야!",
  ui_story_3_1_77_dialog_content = "아이테르의 생명 신호를 목적지로 설정합니다. 가속 카운트다운.",
  ui_story_3_1_78_dialog_content = "5... 4... 3... 2...",
  ui_story_3_1_79_dialog_content = "1, 이륙합니다!",
  ui_story_3_1_80_dialog_content = "카론 님. 이번 사건의 보고서를 준비했습니다. 이렇게 처리하면 되겠습니까...?",
  ui_story_3_1_81_dialog_content = "어디 볼까, 음... 으음... 이 부분은 별로군.",
  ui_story_3_1_82_dialog_content = "바이스와 아이테르에 대한 부분을 좀 더 자세히,\n그들의 행동과 이곳에서 일어난 일을 연관시켜야 한단 말이다.",
  ui_story_3_1_83_dialog_content = "아, 알겠습니다!",
  ui_story_3_1_84_dialog_content = "날 믿어라. 그 여자도 널 세세하게 추궁하거나 하진 않을 거다.",
  ui_story_3_1_85_dialog_content = "이건 제 예상과 다르군요, 카론.",
  ui_story_3_1_86_dialog_content = "......",
  ui_story_3_1_87_dialog_content = "28호 지하성을 묻는 거라면, 저 폐허가 바로 그거다. 군단장 나리.",
  ui_story_3_1_88_dialog_content = "제가 이미 아는 사실을 반복해서 말하지 마세요, 카론. 브리핑에서 이야기했던 콜로서스는 어디 있습니까?",
  ui_story_3_1_89_dialog_content = "새장에 갇혀 있던 새는 이미 화려하게 날아가 버렸다.",
  ui_story_3_1_90_dialog_content = "그럼 제 부하는 지금 어디 있습니까?",
  ui_story_3_1_91_dialog_content = "갔다. 콜로서스를 타고.",
  ui_story_3_1_92_dialog_content = "지하성 28호 책임관 카론, 지금 제 부하가 명령을 위반했다고 말하는 겁니까?",
  ui_story_3_1_93_dialog_content = "난 그녀가 그 아이테르와 함께 있다고 말한 것뿐이다.",
  ui_story_3_1_94_dialog_content = "아이테르...",
  ui_story_3_1_95_dialog_content = "카론 님! 이쪽은 이미... 앗, 군단장님, 말씀 중에 죄송합니다!",
  ui_story_3_1_96_dialog_content = "말하세요.",
  ui_story_3_1_97_dialog_content = "예. 현재까지의 피해 규모와 사람들의 상태를 모두 파악했습니다. 다음 지시를 부탁드립니다!",
  ui_story_3_1_98_dialog_content = "기존 계획대로 저들을 가장 가까운 지하성으로 배치하도록 하세요.\n제가 1대대와 3대대를 남겨서 가는 길을 보호하겠습니다.",
  ui_story_3_1_99_dialog_content = "사람들을 지키는 건 우리로도 충분하다. 네가 신경 쓸 필요는...",
  ui_story_3_1_100_dialog_content = "나머지는 절 따라오도록 하세요.",
  ui_story_3_1_101_dialog_content = "......",
  ui_story_3_1_102_dialog_content = "인간미 없는 모습은 여전하군, 히이로.",
  ui_story_3_1_103_dialog_content = "뭐 하고 있어?",
  ui_story_3_1_104_dialog_content = "응? 나?",
  ui_story_3_1_A4_dialog_content = "이건 뭐야? 요리 도구인가?",
  ui_story_3_1_A5_dialog_content = "...이건 소형 원격 통신기야.",
  ui_story_3_1_105_dialog_content = "일루미나에서 만든 거야? 그동안엔 보여준 적 없는 것 같은데?",
  ui_story_3_1_106_dialog_content = "이건 방금 카론 님이 나한테 슬쩍 주신 거야.",
  ui_story_3_1_107_dialog_content = "카론 씨...",
  ui_story_3_1_108_dialog_content = "어떻게 하는 거지. 아, 정말 어렵네...",
  ui_story_3_1_109_dialog_content = "내 기억엔... 여길 교차시키고, 감아서 넣어서... 주파수를 조정하면...",
  ui_story_3_1_111_dialog_content = "앗, 연결됐다!",
  ui_story_3_1_112_dialog_content = "현재 위치를 보고하세요.",
  ui_story_3_1_113_dialog_content = "히이로 군단장님?",
  ui_story_3_1_114_dialog_content = "아직 상관은 알아보는 모양이군요, 중위. 왜 멋대로 떠난 겁니까?",
  ui_story_3_1_115_dialog_content = "죄송해요... 28호 지하성은 암귀의 습격을 받았고, 자폭 프로그램에 따라 폭발했어요.",
  ui_story_3_1_116_dialog_content = "제가 이미 아는 사실을 반복해서 말하지 마세요. 왜 멋대로 콜로서스를 가지고 떠났는지 묻는 겁니다.",
  ui_story_3_1_117_dialog_content = "콜로서스는... 제가...",
  ui_story_3_1_118_dialog_content = "저기... 먼저 하나 짚고 넘어가고 싶은데, 콜로서스는 당신들 게 아니에요.",
  ui_story_3_1_119_dialog_content = "...바로 당신이로군요...",
  ui_story_3_1_120_dialog_content = "그래요. 제가 바로 이 콜로서스의 주인이에요.",
  ui_story_3_1_122_dialog_content = "지금 당신과 당신의 그 소중한 콜로서스 때문에 28호 지하성이 지도에서 사라져 버렸습니다.",
  ui_story_3_1_A6_dialog_content = "일루미나 연방에 해명이 필요하다고 생각하지 않습니까?",
  ui_story_3_1_123_dialog_content = "정말 미안해요...하지만 그럴 만한 사정이 있었어요!",
  ui_story_3_1_124_dialog_content = "맥거핀은 「<color=#FFB400>슈모르</color>」라는 녀석에 대해 언급했는데...",
  ui_story_3_1_125_dialog_content = "맥거핀, 슈모르, 그런 이상한 이름에는 관심 없습니다.",
  ui_story_3_1_126_dialog_content = "하지만 28호 지하성, 그리고 이 모든 일이... 그 「슈모르」와 관계가 있단 말이에요!",
  ui_story_3_1_127_dialog_content = "으음?",
  ui_story_3_1_128_dialog_content = "군단장님, 저희한테 다른 아이테르에 대한 단서가 있어요.\n아마도 다른 콜로서스를 찾을 수 있을지도 몰라요!",
  ui_story_3_1_129_dialog_content = "...그게 정말입니까?",
  ui_story_3_1_130_dialog_content = "하지만 그 아이테르와 콜로서스가 지금 위험에 처한 것 같아요!",
  ui_story_3_1_131_dialog_content = "PlayerName한테 계획이 하나 있는데, 전...",
  ui_story_3_1_132_dialog_content = "전 그를 돕고 싶어요! 이건 우리 일루미나에도 매우 중요한 일이니까요!",
  ui_story_3_1_133_dialog_content = "중위, 한 가지 당부하겠는데...",
  ui_story_3_1_A7_dialog_content = "당신은 일루미나 연방의 병사입니다! 잘 생각하세요!",
  ui_story_3_1_134_dialog_content = "군단장님, 죄송해요. 저도 전에는 저 사람을 막았지만, 이번엔 저 사람이 옳다고 생각해요!",
  ui_story_3_1_135_dialog_content = "바이스...?",
  ui_story_3_1_136_dialog_content = "이번엔, 틀리지 않을 거예요...",
  ui_story_3_1_137_dialog_content = "전 제 동족을 구하고, 모든 진실을 밝혀내고 말겠어요.",
  ui_story_3_1_A8_dialog_content = "......",
  ui_story_3_1_A9_dialog_content = "............",
  ui_story_3_1_138_dialog_content = "하아... 얼마나 자신이 있죠?",
  ui_story_3_1_139_dialog_content = "절대 암귀 녀석들 뜻대로 되게 만들지 않을 거예요!",
  ui_story_3_1_140_dialog_content = "...좋습니다. 목적지의 좌표를 전달하세요. 지금 당장.",
  ui_story_3_1_141_dialog_content = "당신의 통신 신호가 불안정해서, 이쪽에선 당신들의 위치를 추적할 수가 없습니다.",
  ui_story_3_1_142_dialog_content = "그리고 바이스, 절대 자신의 입장을 잊지 말고! 어리석은 행동은 하지...",
  ui_story_3_1_144_dialog_content = "에? 신호가 갑자기 끊겼는데?!",
  ui_story_3_1_145_dialog_content = "이전과는 다른... 강한 위압감이 느껴집니다.",
  ui_story_3_1_146_dialog_content = "내 동족이 구조를 요청하면서 「<color=#FFB400>디바우러호</color>」라는 이름을 말했어.",
  ui_story_3_1_A10_dialog_content = "저 녀석인가?",
  ui_story_3_1_147_dialog_content = "저도 모릅니다, PlayerName. 하지만 매우 강력한 힘이 느껴집니다. 바로...",
  ui_story_3_1_148_dialog_content = "이곳에 있습니다!",
  ui_story_3_1_A11_dialog_content = "바이스, 스카이워커가 목적지를 찾았어. 그곳에 「디바우러호」라는 게 있을 것 같아.",
  ui_story_3_1_A12_dialog_content = "지금 우린 가진 정보가 너무 적어. 더 조심해야 해.",
  ui_story_3_1_149_dialog_content = "「디바우러호」? 설마 콜로서스?!",
  ui_story_3_1_150_dialog_content = "아직은 확실하지 않아...",
  ui_story_3_1_151_dialog_content = "에...",
  ui_story_3_1_152_dialog_content = "PlayerName, 만약 제가 진심으로 당신을 막겠다면, 제 말을 들으시겠습니까?",
  ui_story_3_1_153_dialog_content = "스카이워커... 미안해.",
  ui_story_3_1_154_dialog_content = "이미 예상했습니다...",
  ui_story_3_1_155_dialog_content = "곧 착륙합니다. 모두 전투 준비를 하십시오.",
  ui_story_3_1_A13_dialog_content = "아래에 다수의 암귀가 보입니다!",
  ui_story_3_3_1_dialog_content = "응? 누가 왔네.",
  ui_story_3_3_2_dialog_content = "주제도 모르고... 감히 날 방해하러 와?",
  ui_story_3_3_3_dialog_content = "제가 가서 처리하면 되겠습니까?",
  ui_story_3_3_4_dialog_content = "당장은 그럴 필요 없어. 앞으로 할 일이 더 중요하니까.",
  ui_story_3_3_5_dialog_content = "슈모르... 뭘 하러 온 거지?",
  ui_story_3_3_6_dialog_content = "헤에? 왔구나, 귀여운 녀석. 그때처럼 도망친 줄 알았는데 말이야.",
  ui_story_3_3_7_dialog_content = "콜로서스 <color=#FFB400>아르카누스호</color>의 주인.",
  ui_story_3_3_8_dialog_content = "아, 이게 아니지, 더 매력적인 별명으로 불러야겠지? 「겁쟁이 <color=#FFB400>멘델슨</color>」.",
  ui_story_3_3_9_dialog_content = "콜록... 깨어나자마자 네 역겨운 기운부터 느껴지더군... 슈모르.",
  ui_story_3_3_10_dialog_content = "아니면 「<color=#FFB400>디바우러호의 주인</color>」이라고 불러야 하나?",
  ui_story_3_3_11_dialog_content = "너니까 특별히 봐줄게. 복잡하게 가지 말고 쉽게 끝내자고.",
  ui_story_3_3_12_dialog_content = "내가 <color=#FFB400>그 물건</color>을 찾을 수 있게 안내해.",
  ui_story_3_3_A1_dialog_content = "무슨 소린지 모르겠네. 내겐 아무것도 없어, 슈모르. 그저 시시한 역사만 남아있을 뿐이라고...",
  ui_story_3_3_A2_dialog_content = "그리고 더러운 비밀도 있지, 내가 모를 거라고 생각하지 마.",
  ui_story_3_3_A3_dialog_content = "「<color=#FFB400>싱크탱크 컴포넌트</color>」! 어서 내놔. 너한테 하나 있다는 건 알고 있으니까.",
  ui_story_3_3_A4_dialog_content = "...그걸로 뭘 하려는 거지?",
  ui_story_3_3_A5_dialog_content = "알고 싶은 정보를... 얻으려는 것뿐이야.",
  ui_story_3_3_A6_dialog_content = "네 목적이 내가 생각하는 그게 맞다면, 절대 받아들일 수 없어.",
  ui_story_3_3_A7_dialog_content = "그건 명백히 금지되어 있어. 콜로서스의 사명을 어기는 「잘못된 길」이라고!",
  ui_story_3_3_13_dialog_content = "나보고 그걸 도우라고?",
  ui_story_3_3_14_dialog_content = "넌 「아르카누스」에 대해 뭔가 오해하고 있는 모양인데, 슈모르.",
  ui_story_3_3_15_dialog_content = "박하게 굴지 마, 멘델슨.",
  ui_story_3_3_16_dialog_content = "우린 모두 같은 힘에 의지했어. 안 그래? 아니면 네가 오늘까지 어떻게 살아남았겠어.",
  ui_story_3_3_17_dialog_content = "그건 아이테르는 결코 가질 수 없는 힘이야. 너랑 난 똑같아.",
  ui_story_3_3_18_dialog_content = "그래서 하루도 후회하지 않은 날이 없어. 슈모르... 쿨럭, 이럴 줄 알았다면...",
  ui_story_3_3_19_dialog_content = "음...? 네 몸, 붕괴하고 있는 것 같네...",
  ui_story_3_3_A8_dialog_content = "아무래도 멘델슨 넌 온전한 은혜를 받지 못한 모양이구나. 불쌍한 녀석...",
  ui_story_3_3_20_dialog_content = "네 꼴 좀 봐. 말하기조차 힘겨워하잖아... 정말로 마음이 아픈걸!",
  ui_story_3_3_22_dialog_content = "내가 서 있는 곳이 너희의 무덤이 될 거다. 단 한 발자국도 넘어갈 수 없다.",
  ui_story_3_3_23_dialog_content = "알아들었지? 이 선을 넘어서는 순간 지옥을 맛보게 될 거야.",
  ui_story_3_3_24_dialog_content = "내겐 전투 능력은 없지만, 아르카누스호가 아무한테나 짓밟히는 어린양은 아니라고. 콜록...",
  ui_story_3_3_25_dialog_content = "인간형 방화벽이라... 겁쟁이 특유의 보호 메커니즘입니까?",
  ui_story_3_3_26_dialog_content = "날 무시하지 마, 슈모르!",
  ui_story_3_3_27_dialog_content = "제가 나설까요?",
  ui_story_3_3_A9_dialog_content = "됐다고 했지! 이건 우리끼리의 문제야!",
  ui_story_3_3_28_dialog_content = "흥, 집고양이, 그리고 충견인가... 멘델슨한테 잘 어울리네.",
  ui_story_3_3_29_dialog_content = "그러니까 넌 찌질한 겁쟁이라는 거야.",
  ui_story_3_3_30_dialog_content = "무례하다!",
  ui_story_3_3_31_dialog_content = "이제 됐어. 꿇어라!",
  ui_story_3_3_32_dialog_content = "행동 불가! 행동 불가! 최우선 레벨의 명령 수락, 강제 실행!",
  ui_story_3_3_33_dialog_content = "필릭스! 주인님... 어서 필릭스를 보...",
  ui_story_3_3_34_dialog_content = "아아아악...",
  ui_story_3_3_35_dialog_content = "피니, 필릭스... 어떻게 된 거야... 슈모르! 대체 무슨 짓을 한 거야?!",
  ui_story_3_3_36_dialog_content = "이 「장난감들」, 꽤 재밌는걸, 멘델슨.",
  ui_story_3_3_37_dialog_content = "결정했어. 이제부터 녀석들은 내 거야.",
  ui_story_3_3_38_dialog_content = "역시 넌 몸과 영혼만 타락한 게 아니었어... 넌 이미 다른 무언가가 돼 버렸다고, 슈모르!",
  ui_story_3_3_39_dialog_content = "칭찬 고마워. 하지만 그렇다고 내가 할 일이 바뀌진 않을 거야.",
  ui_story_3_3_40_dialog_content = "저들을 돌려줘! 이 괴물아!",
  ui_story_3_3_41_dialog_content = "아아, 그 요구는 의외로 마음에 드는걸! 필릭스, 피니... 라고 했지?",
  ui_story_3_3_42_dialog_content = "예.",
  ui_story_3_3_43_dialog_content = "멘델슨을 잡아 와!",
  ui_story_3_3_44_dialog_content = "뭐...뭐라고!?",
  ui_story_3_3_45_dialog_content = "쳇, 또 도망쳤네.",
  ui_story_3_3_46_dialog_content = "「날 무시하지 마」라고 해도, 결국 하나도 변하지 않았잖아. 그때처럼 여전히 겁쟁이야.",
  ui_story_3_3_47_dialog_content = "이제 어떻게 할까요, 주인님?",
  ui_story_3_3_48_dialog_content = "추격해, 끝까지 쫓아가서 끌고 와. 어디 한 번 더 보자고...",
  ui_story_3_3_49_dialog_content = "그땐 과연 어떤 표정을 지으려나?",
  ui_story_3_3_50_dialog_content = "알겠습니다.",
  ui_story_3_3_51_dialog_content = "알겠습니다.",
  ui_story_3_3_52_dialog_content = "나, 난 이대로 잡힐 수 없어... 내 말 들려...? 어서 구해줘...",
  ui_story_3_3_53_dialog_content = "듣고 있어! 어디야?! 너도 아이테르 맞지?!",
  ui_story_3_3_54_dialog_content = "디바우러호의... 힘이 더 강해졌어...",
  ui_story_3_3_55_dialog_content = "내 「싱크탱크 컴포넌트」를... 빼앗길 순 없어. 절대 그 「방법」을 알아내게 해선 안 돼...",
  ui_story_3_3_56_dialog_content = "넌 날 벗어날 수 없어. 말하는 것조차 힘겨운 모습 좀 봐... 정말 마음이 아프네.",
  ui_story_3_3_57_dialog_content = "슈모르... 이번엔 네 뜻대론 안 될 거야, 절대로...",
  ui_story_3_3_58_dialog_content = "도망칠 수 있을 것 같아?",
  ui_story_3_3_59_dialog_content = "하지만... 넌 이미 이겼어. 아냐? 넌 처음부터 승자였잖아.",
  ui_story_3_3_60_dialog_content = "그 사악한 힘으로 날 침식하고, 널 막을 수 없게 만들었어.",
  ui_story_3_3_61_dialog_content = "...아니, 반드시 막아야 해... 이건 내 사명, 아르카누스호의 사명이라고...",
  ui_story_3_3_62_dialog_content = "...넌 항상 못난 겁쟁이였어.",
  ui_story_3_3_63_dialog_content = "난 대체 살아야 하는 걸까, 아니면 죽어야 하는 걸까...",
  ui_story_3_3_64_dialog_content = "『누가 있다! 잡아라!』",
  ui_story_3_3_65_dialog_content = "거기 있지? 내 동족, 난 이제 계속 도망쳐야 해!",
  ui_story_3_3_66_dialog_content = "부디 서둘러 줘... 나를, 그리고 너 자신을 위해서!",
  ui_story_3_3_A10_dialog_content = "...그 사람, 지금 암귀한테 쫓기고 있어. 하지만 정확한 위치는 알아낼 수가 없어...",
  ui_story_3_3_A11_dialog_content = "알겠어. 조금 더 빨리 움직이자!",
  ui_story_3_3_A12_dialog_content = "PlayerName, 전방에 암귀가 점점 더 많아지고 있어. 경계를 늦추면 안 돼!",
  ui_story_3_7_1_dialog_content = "여기도 암귀가 잔뜩 있네... PlayerName, 괜찮아?",
  ui_story_3_7_2_dialog_content = "난 괜찮아.",
  ui_story_3_7_3_dialog_content = "네가 말한 그 아이테르는...",
  ui_story_3_7_4_dialog_content = "잠깐만!",
  ui_story_3_7_5_dialog_content = "...잡힐 순 없어... 안 돼...",
  ui_story_3_7_6_dialog_content = "우린 이미 들어왔어! 어디야?! 내 말 들려?",
  ui_story_3_7_7_dialog_content = "어서 이쪽으로 와! 내가 지켜줄게!",
  ui_story_3_7_8_dialog_content = "드디어... 왔구나, 동족!",
  ui_story_3_7_9_dialog_content = "미안, 늦었지! 내 말 잘 들리는 거야?!",
  ui_story_3_7_10_dialog_content = "당연하지. 동족... 그리고 네가 보여. 거기 있는 게 너구나?",
  ui_story_3_7_16_dialog_content = "누구야?!",
  ui_story_3_7_17_dialog_content = "쿨럭, 적이. 뒤에...",
  ui_story_3_7_18_dialog_content = "괜찮아?! 드디어 만났어. 정말 다행이야... 이번엔 늦지 않았어!",
  ui_story_3_7_A5_dialog_content = "아, 설마 이 사람이...?",
  ui_story_3_7_A6_dialog_content = "그래, 바이스. 우리한테 계속 구조 요청을 보내던 그 아이테르야!",
  ui_story_3_7_19_dialog_content = "...상태가 무척 안 좋아 보여. PlayerName, 저 몸의 상처는 암귀가 남긴 게 아냐...",
  ui_story_3_7_20_dialog_content = "누가 이런 짓을 한 거야...?",
  ui_story_3_7_22_dialog_content = "목표물, 멘델슨을 찾았다.",
  ui_story_3_7_23_dialog_content = "체포 명령 실행 준비.",
  ui_story_3_7_24_dialog_content = "필릭스, 피니...",
  ui_story_3_7_25_dialog_content = "동족! 뒤로 물러서!",
  ui_story_3_7_26_dialog_content = "저 사람은 네가 챙겨줘, PlayerName! 전투는 우리한테 맡겨!",
  ui_story_3_7_27_dialog_content = "필릭스, 피니...",
  ui_story_3_7_28_dialog_content = "미안해... 결국 난 아무것도 하지 못했어...",
  ui_story_3_7_29_dialog_content = "암귀는 아닌 것 같은데, 어떻게 된 거야?",
  ui_story_3_7_30_dialog_content = "둘은 원래 날 호위하는 이 콜로서스의 방어 체계였어.",
  ui_story_3_7_31_dialog_content = "하지만 왜 당신을 공격하는 건데?",
  ui_story_3_7_32_dialog_content = "슈모르가... 강력한 힘으로 내 권한을 빼앗아 버렸어...",
  ui_story_3_7_33_dialog_content = "어떻게 그런 일이...",
  ui_story_3_7_34_dialog_content = "정말 미안해...",
  ui_story_3_7_35_dialog_content = "모든 게... 그때와 똑같아...",
  ui_story_3_7_36_dialog_content = "동족, 네 이름은 뭐야?",
  ui_story_3_7_37_dialog_content = "난 아르카누스호의 주인, 멘델슨이야.",
  ui_story_3_7_38_dialog_content = "아르카누스호... 익숙한 이름입니다. 아쉽게도 지금은 많은 것을 잊어버렸지만 말입니다...",
  ui_story_3_7_40_dialog_content = "그날 운 좋게 살아남은 콜로서스들은 저마다 자신의 주인을 보호하기 위해 서로 연락을 끊었어.",
  ui_story_3_7_41_dialog_content = "아무래도 그동안 스카이워커호가 널 지켜준 모양이네. 정말... 다행이야...",
  ui_story_3_7_42_dialog_content = "계속 여기 있었던 거야? 다른 아이테르는 없어?",
  ui_story_3_7_43_dialog_content = "어째서 그렇게 됐어? 디바우러호는 또 뭔데...?",
  ui_story_3_7_44_dialog_content = "쿨럭, 난, 쿨럭쿨럭...",
  ui_story_3_7_45_dialog_content = "부상이 심각해... PlayerName, 우선 좀 쉬게 해 주자...",
  ui_story_3_7_46_dialog_content = "미안해. 난 너희들과 달라... PlayerName, 스카이워커호...",
  ui_story_3_7_47_dialog_content = "네가 살아있다는 건 스카이워커호가 아이테르 보호 임무를 잘 수행해 왔다는 뜻이겠지.",
  ui_story_3_7_48_dialog_content = "하지만 난 유일한 사명을 완수하지 못했어...",
  ui_story_3_7_49_dialog_content = "미안한데 무슨 말인지 잘 모르겠어.",
  ui_story_3_7_50_dialog_content = "PlayerName, 스카이워커호가 알려주지 않은 거야?",
  ui_story_3_7_51_dialog_content = "...유감이지만 제 기억은 추락할 때 손상을 입었습니다.",
  ui_story_3_7_52_dialog_content = "PlayerName에 대한 복종 및 보호 명령 외에는 아무런 기억도 없습니다...",
  ui_story_3_7_53_dialog_content = "스카이워커호도 그날 피해를 입었어.",
  ui_story_3_7_54_dialog_content = "그렇구나... 쿨럭... 너희의 대화에는 감응했어...",
  ui_story_3_7_55_dialog_content = "이걸 운이 좋다고 해야 하나, 없다고 해야 하나...",
  ui_story_3_7_56_dialog_content = "그럼 여기엔 대체 무슨 일이 있었던 거야?",
  ui_story_3_7_57_dialog_content = "이 콜로서스, 아르카누스호에는 「<color=#FFB400>싱크탱크 컴포넌트</color>」라는 매우 중요한 물건이 있어...",
  ui_story_3_7_A1_dialog_content = "그 안에는 많은 정보가 담겨 있어. 아이테르들의 역사 자료부터 오로리안 세계의 고서까지...",
  ui_story_3_7_58_dialog_content = "무상한 광명의 찬송가도, 어두운 심연의 속삭임도 있어...",
  ui_story_3_7_60_dialog_content = "하지만 디바우러호, 그러니까 슈모르가 원하는 건 가장 볼품없는 내용이야...",
  ui_story_3_7_61_dialog_content = "그 슈모르란 사람도 역시 이곳에 있는 거야?!",
  ui_story_3_7_62_dialog_content = "그래. 지금 이 순간, 슈모르는 내 코어 구역으로 달려가 「싱크탱크 컴포넌트」를 강제로 차지하고...",
  ui_story_3_7_A2_dialog_content = "그걸 이용해서... 아니, 이건 말할 수 없어. 이건 절대로 밝혀선 안 되는 거니까...!",
  ui_story_3_7_63_dialog_content = "그럼 우리가 가서 막을게! 바이스, 도와줘!",
  ui_story_3_7_64_dialog_content = "그럼 동족한테 길을 안내해 달라고 하자. 나도 28호 지하성을 파괴한 배후를 직접 처단하고 싶으니까!",
  ui_story_3_7_65_dialog_content = "너도 이 날을 기다리고 있었잖아, PlayerName.",
  ui_story_3_7_A3_dialog_content = "그래. 이제 더는 기다릴 수 없어. 모든 진실을 알아내고 말겠어...",
  ui_story_3_7_A4_dialog_content = "조심해, PlayerName... 슈모르는...",
  ui_story_3_7_66_dialog_content = "쿨럭쿨럭... 쿨럭...",
  ui_story_3_7_67_dialog_content = "몸 상태가 악화되고 있어. 내가 어떻게 하면 될까...?",
  ui_story_3_7_68_dialog_content = "이 사람을 여기 남겨둘 순 없어, PlayerName. 하지만 우린 반드시 가야 해...",
  ui_story_3_7_69_dialog_content = "......",
  ui_story_3_7_70_dialog_content = "걱정하지 마, 동족.",
  ui_story_3_7_71_dialog_content = "난 괜찮아. 내가 안내하는 게 더 효율적이니까...",
  ui_story_3_7_72_dialog_content = "게다가 아르카누스호의 주인으로서, 슈모르가 「싱크탱크 컴포넌트」를\n가져가지 못하게 하는 것도 내... 의무야...",
  ui_story_3_7_73_dialog_content = "고마워, 멘델슨. 이 모든 게 끝나면 꼭 나한테 아이테르에 대한 이야기를 들려줘!",
  ui_story_3_7_74_dialog_content = "물론이야, PlayerName. 내가... 헤븐즈 밸리에 대한 모든 걸 알려줄게...",
  ui_story_3_7_75_dialog_content = "그럼 출발하자. 길을 안내해 줘, 멘델슨!",
  ui_story_3_7_76_dialog_content = "우리가 슈모르를 막을 테니까!",
  ui_story_3_9_A1_dialog_content = "(내가 대체 뭘 하는 거지... 분명히 도망칠 기회가 있었는데... 왜 또 돌아가는 거야...)",
  ui_story_3_9_A2_dialog_content = "(저 힘은 이길 수 없잖아. 안 그래? ...어째서 고집을 부리는 거야...)",
  ui_story_3_9_A3_dialog_content = "(도망쳐, 멘델슨. 그런 의미 없는 「임무」는 버리고, 네 목숨을 위해서...)",
  ui_story_3_9_2_dialog_content = "내... 목숨을 위해서...인가?",
  ui_story_3_9_3_dialog_content = "왜 멈춘 거야? 벌써 도착했어?",
  ui_story_3_9_4_dialog_content = "너희들... 정말로 잘 생각했어? 도망치려면 아직 늦지 않았어...",
  ui_story_3_9_5_dialog_content = "슈모르는 평범한 적이 아니야. 필릭스와 피니한테 한 짓을 봐...",
  ui_story_3_9_6_dialog_content = "주저하지 않고 날 지키던 녀석들이 이젠 내게 칼을 겨누고 있어...",
  ui_story_3_9_7_dialog_content = "확실히 슈모르의 능력은 우리가 생각하는 것보다 훨씬 더 강할지도 모릅니다.",
  ui_story_3_9_8_dialog_content = "PlayerName, 전투능력도 없는 아이테르인 네가 왜 슈모르에게 맞서려고 하는 거야?",
  ui_story_3_9_10_dialog_content = "난 계속 그 사람을 찾고 있었어. 물어봐야 할 게 너무 많아. 28호 지하성, 17년 전의 일...",
  ui_story_3_9_A4_dialog_content = "그리고 지금, 슈모르는 내 동족을 또 해치려 하고 있어...",
  ui_story_3_9_13_dialog_content = "피하기만 할 순 없어! 반드시 막아야 해!",
  ui_story_3_9_14_dialog_content = "당장 도망친다고 생각하면 속은 편하겠지. 하지만 우리가 어디로 도망칠 수 있는데?",
  ui_story_3_9_15_dialog_content = "아무리 원해도 돌아갈 수 없는 곳이 있기 마련이야, 멘델슨. 우리 눈앞에 놓인 게 철옹성이라 해도...",
  ui_story_3_9_A5_dialog_content = "동료들과 함께 머리가 깨지도록 부딪혀 보면 돼.",
  ui_story_3_9_16_dialog_content = "네 뜻은 알겠어. 맞아, 내가 무슨 생각을 했던 거지...",
  ui_story_3_9_18_dialog_content = "헤븐즈 밸리는 이미 무너졌고, 가족과 친구들은 암귀에게 참혹하게 살해당했어.",
  ui_story_3_9_19_dialog_content = "오직 나 혼자, 약해빠지고 겁쟁이인 나만...\n구차하게 살아남기 위해 아르카누스호를 가지고... 도망쳤어...",
  ui_story_3_9_20_dialog_content = "그리고 지금도 여전히 도망칠 생각만 하고 말이야.",
  ui_story_3_9_21_dialog_content = "멘델슨 씨...",
  ui_story_3_9_22_dialog_content = "내가 여기서 머뭇거리기만 한다면, 아무것도 달라진 게 없는 셈이겠지... 우린...",
  ui_story_3_9_23_dialog_content = "멘델슨!",
  ui_story_3_9_24_dialog_content = "아... 이건...",
  ui_story_3_9_25_dialog_content = "괜찮아? 왜 갑자기 아파하는 거야?!",
  ui_story_3_9_26_dialog_content = "벌써 시작된 건가... 슈모르... 알 것 같아. <color=#FFB400>이미 손에 넣은 거야</color>...!",
  ui_story_3_9_27_dialog_content = "강력한 힘이 느껴져! 아르카누스호를 완전히 삼켜버릴 어둠의 힘이야!",
  ui_story_3_9_28_dialog_content = "최후의 빛마저 삼켜버릴지도 몰라...",
  ui_story_3_9_29_dialog_content = "내가 도울 방법이 없는 거야? 멘델슨!",
  ui_story_3_9_30_dialog_content = "...걱정하지... 마! 이렇게 된 이상, 처음이자 마지막으로\n내 나약함을 떨쳐낼 수 있을 것 같으니까...",
  ui_story_3_9_A8_dialog_content = "가자, PlayerName. 그리고 네 동료들도 함께!",
  ui_story_3_9_A9_dialog_content = "눈앞의 암귀를 어둠 속 가장 깊은 곳까지 쓸어버리는 거야...",
  ui_story_3_9_A10_dialog_content = "그리고 뒤를 조심해! 적의 습격이야!",
  ui_story_3_9_31_dialog_content = "멘델슨, 사랑하는 내 동생, 무의미한 발악은 이제 그만해.",
  ui_story_3_9_32_dialog_content = "이렇게 꼭꼭 숨겨놔도 결국 찾아내 버렸잖아. 이 「<color=#FFB400>싱크탱크 컴포넌트</color>」를!",
  ui_story_3_9_33_dialog_content = "전혀 어렵지 않았어. 시시할 정도였다니까.",
  ui_story_3_9_34_dialog_content = "자, 이제 네가 간직한 비밀을 보여줘...",
  ui_story_3_9_A11_dialog_content = "흥, 역시 암호화를 해뒀네. 아무래도 시간이 좀 걸리겠어...",
  ui_story_3_9_35_dialog_content = "주인님께서 기다리십니다...",
  ui_story_3_9_36_dialog_content = "언제까지 그렇게 미적거릴 셈이지?",
  ui_story_3_9_37_dialog_content = "별 거 아니니 신경 쓰지마. 금방 끝날 거야...",
  ui_story_3_9_38_dialog_content = "조금만 더 있으면 모든 데이터를 파악할 수 있어. 「그 방법」도 함께 말이야...",
  ui_story_3_9_39_dialog_content = "여기에 숨겨진 비밀이 내 <color=#FFB400>검은 콜로서스</color>와 하나가 되어, 진화의 핵심축이 될 거라고!",
  ui_story_3_9_41_dialog_content = "...마지막으로 시간을 조금 더 줄게, 슈모르.",
  ui_story_3_9_42_dialog_content = "『가라, 동족들아.』",
  ui_story_3_9_43_dialog_content = "꼭 그렇게 소란을 피워야겠어?",
  ui_story_3_9_44_dialog_content = "아직 한참 부족해. 네가 멘델슨한테서 빼앗은 「장난감」들이 쓰러졌다는 보고를 받았거든...",
  ui_story_3_9_45_dialog_content = "그 스카이워커호의 주인, 네 동족한테 말이야.",
  ui_story_3_9_47_dialog_content = "그럼 더 좋지 않아? 내가 필요한 정보를 해독하고 나면, 놈들까지 전부 없애겠어.",
  ui_story_3_9_48_dialog_content = "묵은 빚은 언제든 청산할 수 있어. 중요한 건 계획이야, 슈모르.\n의외의 상황이 생기지 않도록 조심하는 게 좋을 거야.",
  ui_story_3_9_50_dialog_content = "내가 참을 수 있을 것 같아? ...그때 놓친 녀석이 지금 코앞에 있는데, 나보고 참으라고?",
  ui_story_3_9_51_dialog_content = "난 혼돈, 무질서, 충동을 좋아하지 않아.",
  ui_story_3_9_52_dialog_content = "그리고 싸움 역시 좋아하지 않아. 그런 천박한 취미엔 관심 없어.",
  ui_story_3_9_53_dialog_content = "......",
  ui_story_3_9_54_dialog_content = "자, 얘기는 여기까지 할까.",
  ui_story_3_9_56_dialog_content = "타바드!",
  ui_story_3_9_57_dialog_content = "어둠 속에서 오랜 시간 기다렸습니다... 제가 나서면 되겠습니까? 주인님.",
  ui_story_3_9_58_dialog_content = "알아서 처리해.",
  ui_story_3_9_59_dialog_content = "예... 주인님.",
  ui_story_3_9_61_dialog_content = "제 손으로 놈들을 갈기갈기 찢어버리겠습니다. 그들의 희미한 빛은 결국 어둠 속으로 사라질 것입니다...",
  ui_story_3_9_A12_dialog_content = "PlayerName, 느껴져? 암귀들이 전부 우리 쪽으로 오고 있는 것 같아...",
  ui_story_3_9_A13_dialog_content = "응. 계속 모여들고 있어. 하지만 이 정도로 우릴 막을 순 없잖아?",
  ui_story_3_9_A14_dialog_content = "당연하지. 계속 움직이자. 길을 막는 암귀는 모두 쓸어버리는 거야!",
  ui_story_3_12_2_dialog_content = "도착했어.",
  ui_story_3_12_3_dialog_content = "여긴가요? 「싱크탱크 컴포넌트」를 보관해둔 곳이...",
  ui_story_3_12_4_dialog_content = "그래, 바로 이 앞이야... 슈모르를 조심해...",
  ui_story_3_12_5_dialog_content = "멘델슨, 우리가 함께 이 모든 걸 끝내자!",
  ui_story_3_12_6_dialog_content = "고마워, PlayerName, 우리가 같이... 막는 거야...",
  ui_story_3_12_7_dialog_content = "멘델슨 씨... 진정해요. 호흡이 힘들어 보여요. 몸이...",
  ui_story_3_12_9_dialog_content = "...신경쓰지 마. <color=#FFB400>어둠의 힘</color>은... 제어할 수 없어. 게다가 이미 전신에 퍼졌거든.",
  ui_story_3_12_10_dialog_content = "그, 그게 무슨 말이죠?",
  ui_story_3_12_12_dialog_content = "...17년 전 그날, 난 살아남기 위해 <color=#FFB400>암귀의 힘</color>을 받아들였어...",
  ui_story_3_12_A1_dialog_content = "<color=#FFB400>슈모르처럼</color> 말이야. 하지만 내 몸은 반대로 점점 쇠약해져갔지...",
  ui_story_3_12_A2_dialog_content = "「신앙」이 확고하지 않아서일까? 아니면 내가 「구차한 연명」을 원하지 않아서일까...",
  ui_story_3_12_15_dialog_content = "얘야, 이건 그저 찰나의 고통일 뿐이다... 후회할 결정은 하지 마라.",
  ui_story_3_12_16_dialog_content = "선생님... 죄송해요. 이미 늦었어요. 저, 전 살고 싶어요...",
  ui_story_3_12_17_dialog_content = "살아남기 위해 암귀의 힘을 받아들였다고? 어째서...",
  ui_story_3_12_18_dialog_content = "우습지? 비록 이런 괴물이 되어버렸지만, 난 여전히 「아르카누스호」의 임무를 수행하고 있어...",
  ui_story_3_12_A3_dialog_content = "그럼 난 대체 뭘까... 난 대체, 누구일까...",
  ui_story_3_12_A4_dialog_content = "포기하지 마. 슈모르만 쓰러트리고 나면, 회복할 방법을 찾아낼 수 있을 거야!",
  ui_story_3_12_A5_dialog_content = "소용없어. 이미 늦었어... 운명은 정말 공교롭다니까.",
  ui_story_3_12_19_dialog_content = "그동안 난 어둠의 힘에 의지해서, 캄캄한 지하에 숨어 수년간 잠들어 있었어...",
  ui_story_3_12_20_dialog_content = "이번에도 전처럼 겁쟁이답게 도망갈 수 있을 거라고 생각했어.",
  ui_story_3_12_21_dialog_content = "그렇게 어두운 구석 어딘가에 숨어서, 이 무의미한 생명을 계속해서 이어나가려고 했지...",
  ui_story_3_12_22_dialog_content = "하지만 그러다 너흴 만난 거야. 그리고 어쩌면...\n나도 한 번쯤은 용기를 낼 수 있지 않을까 싶었어...",
  ui_story_3_12_23_dialog_content = "그러니까 이번에는 피하지 않겠어. 산산조각 난 이 운명 속에서 함께 미래를 구하는 거야!",
  ui_story_3_13_1_dialog_content = "<color=#e8d9bb>아르카누스호 유적 외부</color>",
  ui_story_3_13_2_dialog_content = "타바드, 저들이 왔나?",
  ui_story_3_13_3_dialog_content = "3개의 불안한 영혼이 보입니다. 그중 하나는 바람 앞의 등불처럼 마지막 남은 숨을 헐떡이고 있습니다.",
  ui_story_3_13_4_dialog_content = "좋아. 마음대로 해.",
  ui_story_3_13_5_dialog_content = "명령대로, 어머니를 위해 모두 없애버리겠습니다. 오로라 아래 「이클립스」만이 영원하리니.",
  ui_story_3_13_6_dialog_content = "바로 저 녀석이야?",
  ui_story_3_13_8_dialog_content = "늦게도 오는군... 너흰 멋진 공연을 놓쳤다.",
  ui_story_3_13_9_dialog_content = "뭐야, 한 마리뿐이야?!",
  ui_story_3_13_10_dialog_content = "타바드 혼자서 충분하다.",
  ui_story_3_13_11_dialog_content = "충분하다고?",
  ui_story_3_13_12_dialog_content = "PlayerName... 아이테르의 잔당이여, 그 오로리안과는 달리 네게는 더 어울리는 길이 있다.",
  ui_story_3_13_13_dialog_content = "어떻게 PlayerName의 이름을 알고 있지?",
  ui_story_3_13_14_dialog_content = "모든 지식, 모든 시야, 모든 미래가 우리에게 있다.|\nPlayerName, 넌 이런 걸 갈망하지 않았나?",
  ui_story_3_13_15_dialog_content = "숨길 필요 없다. PlayerName. 난 너희 아이테르의 마음속 갈망을 알고 있다.\n네가 무엇을 원하는지 알고 있단 말이다...",
  ui_story_3_13_16_dialog_content = "PlayerName?",
  ui_story_3_13_17_dialog_content = "넌 강한 힘을 갈망하지. 그 나약한 오로리안 뒤에 서 있는 게 다가 아니라...",
  ui_story_3_13_18_dialog_content = "난...",
  ui_story_3_13_19_dialog_content = "더 가까이, 그래. 조금 더 가까이 와라. 너도 내 주인처럼 <color=#FFB400>이클립스를 받아들여라</color>!",
  ui_story_3_13_20_dialog_content = "이클립스?",
  ui_story_3_13_21_dialog_content = "웃기지 마!",
  ui_story_3_13_22_dialog_content = "...실의에 빠진 떠돌이 개가 또 꼬리를 흔들며 돌아왔군.",
  ui_story_3_13_23_dialog_content = "가장 보고 싶지 않았던 망령이겠지. 네 주인은, 그 녀석은 어디 있지!?",
  ui_story_3_13_A1_dialog_content = "(「싱크탱크 컴포넌트」도, 슈모르도 없어!)",
  ui_story_3_13_24_dialog_content = "이건 좀 의외로군, 멘델슨.",
  ui_story_3_13_25_dialog_content = "눈앞에서 동족이 살해당할 때도 더러운 개처럼 콜로서스에 숨어 나서지도 못했던 네놈이...",
  ui_story_3_13_26_dialog_content = "자신의 의식을 봉인하고 현실을 직시하길 거부했던 네가 그분 앞에 서려고 하는 날이 올 줄이야.",
  ui_story_3_13_27_dialog_content = "하지만 벌벌 떨며 온몸으로 나약함과 무력함을 드러내는 네 모습을 보니 여전히 참 우습구나.",
  ui_story_3_13_28_dialog_content = "입 닥치고 멘델슨한테서 떨어져!",
  ui_story_3_13_29_dialog_content = "괜찮아?",
  ui_story_3_13_30_dialog_content = "미안해. 아, 아무래도 진짜 원흉은 도망친 모양이야...",
  ui_story_3_13_31_dialog_content = "「싱크탱크 컴포넌트」마저 가지고 가버렸... 크윽! 이제 곧 한계인 것 같아...",
  ui_story_3_13_32_dialog_content = "안 돼... 반드시 해야 할 일이 하나 있어...",
  ui_story_3_13_33_dialog_content = "나머지는 우리한테 맡기고 좀 쉬어!",
  ui_story_3_13_34_dialog_content = "재미있군. 곧 죽을 녀석들끼리 서로 동정하다니.",
  ui_story_3_13_35_dialog_content = "PlayerName! 망설일 거 없어!",
  ui_story_3_13_36_dialog_content = "전투 지휘를 부탁할게!",
  ui_story_3_13_37_dialog_content = "끝난 건가...",
  ui_story_3_13_38_dialog_content = "<color=#e8d9bb>그 순간, 주변이 기이한 침묵 속에 잠겼다.</color>",
  ui_story_3_13_39_dialog_content = "아, 안 돼. 어둠의 힘이 모이고 있어! 놈의 공격을 조심해!",
  ui_story_3_13_40_dialog_content = "타바드는 여기서 끝나지 않는다. 위대한 사명을 위한 타바드의 각오를 보여주마!",
  ui_story_3_13_41_dialog_content = "어둠이여, 저 아이테르를 집어삼켜라!",
  ui_story_3_13_42_dialog_content = "이런, 나한테 온다...!",
  ui_story_3_13_43_dialog_content = "뜻대로 될 줄 알고? 내가 목숨을 걸고서라도 지키겠어!",
  ui_story_3_13_44_dialog_content = "옳은 말씀입니다, 중위!",
  ui_story_3_13_45_dialog_content = "<color=#e8d9bb>스윽──!</color>",
  ui_story_3_13_F1_dialog_content = "크오오오!",
  ui_story_3_13_46_dialog_content = "구, 군단장님!",
  ui_story_3_13_47_dialog_content = "아무래도 때맞춰 온 것 같군요.",
  ui_story_3_13_48_dialog_content = "『...처...천하고, 더러운, 어리석은... 약...자... 쓰레...』",
  ui_story_3_13_49_dialog_content = "암귀가... 벚꽃으로 변했어?",
  ui_story_3_13_50_dialog_content = "도와주셔서 감사해요!",
  ui_story_3_13_51_dialog_content = "바이스 중위, 당신의 행동은 일루미나의 규율을 심각하게 위반한 것입니다.\n무척이나 위험한 행동이라는 것은 알고 있습니까?",
  ui_story_3_13_52_dialog_content = "......",
  ui_story_3_13_53_dialog_content = "바이스 중위!",
  ui_story_3_13_54_dialog_content = "네!",
  ui_story_3_13_55_dialog_content = "돌아가면 최소 5,000자 분량으로 경위서를 쓰세요.\n내용은 이 콜로서스와 저 전투능력이 없는 아이테르에 대해서입니다.",
  ui_story_3_13_56_dialog_content = "콜로서스를 조종할 수 있고, 뛰어난 지휘 능력이 있는 아이테르라구요!",
  ui_story_3_13_57_dialog_content = "제가 이미 아는 사실을 반복해서 말하지 마세요.",
  ui_story_3_13_58_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_3_13_59_dialog_content = "멘델슨, 네 몸이!",
  ui_story_3_13_60_dialog_content = "이럴 수가! 설마...",
  ui_story_3_13_61_dialog_content = "아무래도... 내 운명은 이미 정해져 있었던 것 같아... 이제 내 선택의 대가를 치를 시간이야.",
  ui_story_3_13_62_dialog_content = "안 돼... 우리가 널 구해줄 수 있다고! 바이스! 그렇지?!",
  ui_story_3_13_63_dialog_content = "PlayerName, 난...",
  ui_story_3_13_64_dialog_content = "괜찮아. 내 선택이야. 난... 진작에 죽었어야 했어. 이제 마침내 제자리로 찾아온 거야...",
  ui_story_3_13_A2_dialog_content = "지금은 내 생사보다 더 중요한 일이 있어, PlayerName...",
  ui_story_3_13_A3_dialog_content = "이미 이렇게 된 이상... 나도 더는 비밀을 감출 필요가 없을 것 같네...",
  ui_story_3_13_65_dialog_content = "「싱크탱크 컴포넌트」, 기억하지? <color=#FFB400>지금부터 내가 하는 말을 꼭 기억해 둬</color>...",
  ui_story_3_13_A4_dialog_content = "원래 콜로서스는 각자의 특성이 있지만, 직접적인 전투 능력은 갖추고 있지 않아...",
  ui_story_3_13_A5_dialog_content = "하지만 디바우러호는 달라... 이론적으로 유일하게 공격 능력을 갖춘 콜로서스야!",
  ui_story_3_13_66_dialog_content = "다행히도 아직 완전한 상태는 아냐...",
  ui_story_3_13_67_dialog_content = "그리고 그 주인, 슈모르는... 그 콜로서스를 고칠 방법을 찾고 있어. 그녀한테 필요한 건...",
  ui_story_3_13_X67_dialog_content = "「<color=#FFB400>싱크탱크 컴포넌트</color>」",
  ui_story_3_13_X68_dialog_content = "「<color=#FFB400>자생 유닛</color>」",
  ui_story_3_13_X69_dialog_content = "「<color=#FFB400>화염 제어 모듈</color>」",
  ui_story_3_13_X70_dialog_content = "...이 세 가지야.",
  ui_story_3_13_A6_dialog_content = "슈모르가 「싱크탱크 컴포넌트」를 먼저 찾은 이유는...\n그걸 통해 다른 두 부품의 위치를 알아낼 수 있기 때문이야...",
  ui_story_3_13_68_dialog_content = "모든 것을 압도하는 힘을 얻기 위해...\n슈모르는 어떠한 대가를 치르더라도 세 가지를 다 찾아내겠지...",
  ui_story_3_13_69_dialog_content = "하지만 벌써 당신의 「싱크탱크 컴포넌트」를 손에 넣었잖아!",
  ui_story_3_13_70_dialog_content = "아니, 얻지 못할 거야... 그 컴포넌트는 방어 프로세스를 지니고 있어.\n내가 죽으면 프로세스가 실행될 거야. 내가 주는 마지막 「깜짝 선물」인 셈이지...",
  ui_story_3_13_71_dialog_content = "멘델슨, 분명히 다른 방법이 있을 거야...\n우선 안정을 취해야 해! 네 몸이 낫고 나면 시간은 얼마든지 있어!",
  ui_story_3_13_72_dialog_content = "우리가 같이 슈모르를 막는 거야! 함께 고향으로 돌아갈 수도 있다고!",
  ui_story_3_13_73_dialog_content = "난 그곳에 가본 적이 없잖아. 그러니까 네가 나한테 헤븐즈 밸리 이야기를 해 줘야지...",
  ui_story_3_13_74_dialog_content = "안타깝지만 그건 힘들 것 같아. 스카이워커호한테 알려달라고 해... 아니면 다른 동족을 찾아서...",
  ui_story_3_13_75_dialog_content = "안 돼! 멘델슨!",
  ui_story_3_13_A7_dialog_content = "조용히... 내 말 들어. 시간이 많지 않아...",
  ui_story_3_13_76_dialog_content = "내가 가면... 슈모르는 분명히 <color=#FFB400>백야성</color>, 오로리안들의 「최후의 도시」로 향할 거야...",
  ui_story_3_13_A8_dialog_content = "그곳에 「싱크탱크 컴포넌트」가 하나 더 있어! 맞아, 컴포넌트는 한 개가 아니야...",
  ui_story_3_13_A9_dialog_content = "이 위협을 반드시 백야성에 알려야 해. PlayerName...",
  ui_story_3_13_A10_dialog_content = "그곳의 오로리안들은... 그 「싱크탱크 컴포넌트」의 중요성을... 모를 거야...",
  ui_story_3_13_77_dialog_content = "멘델슨! 제발! 나만 남겨두지 마!",
  ui_story_3_13_78_dialog_content = "PlayerName, 나도 너와... 그리고 새로 알게 된 친구들과... 함께하고 싶어...",
  ui_story_3_13_79_dialog_content = "하지만 이젠 더는 도망치고 싶지 않아... 슈모르가 뜻을 이루게 둘 순 없어...",
  ui_story_3_13_80_dialog_content = "적어도 컴포넌트를 손에 넣는 건 포기해야 할 거야...\n「지렁이」도... 밟으면 꿈틀한다는 걸 녀석도 이제 알았을 테니까...",
  ui_story_3_13_81_dialog_content = "멘델슨...",
  ui_story_3_13_82_dialog_content = "정말 아름다워...",
  ui_story_3_13_83_dialog_content = "......",
  ui_story_3_13_84_dialog_content = "저 드래곤은... 정말 특별하네.",
  ui_story_3_13_F2_dialog_content = "저건 히이로 님의 <color=#FFB400>앵룡</color>이야.",
  ui_story_3_13_F3_dialog_content = "이 세상엔... 저런 색깔도 있었던 거구나. 더 많이 보고 싶은걸...",
  ui_story_3_13_85_dialog_content = "지금까지... 어둠 속에 숨어 있으면서... 하늘의 색깔도 잊어버릴 뻔했어...",
  ui_story_3_13_86_dialog_content = "PlayerName! 히이로 님! 설마 아무 방법도 없는 건가요? 정말 이대로 보고만 있어야 하는 건가요...",
  ui_story_3_13_F4_dialog_content = "......",
  ui_story_3_13_F5_dialog_content = "......",
  ui_story_3_13_87_dialog_content = "PlayerName, 너와 더 많은 이야기를 하고 싶어... 스카이워커호... 예전처럼, 모두와 함께...",
  ui_story_3_13_88_dialog_content = "한 번 더... 하늘을 보고 싶어...",
  ui_story_3_13_89_dialog_content = "스카이워커!",
  ui_story_3_13_90_dialog_content = "네, PlayerName.",
  ui_story_3_13_91_dialog_content = "감응해 줘! 멘델슨과 감응하는 거야! 하늘을... 멘델슨한테 보여줘...",
  ui_story_3_13_92_dialog_content = "...네.",
  ui_story_3_13_93_dialog_content = "아, 오랜만에 보는... 푸른 하늘이네...",
  ui_story_3_13_94_dialog_content = "멘델슨! 내 스카이워커호를 너와 함께 나눌게!",
  ui_story_3_13_95_dialog_content = "지금부터 영원히, 스카이워커가 네 눈과 귀가 되어... 구름 위의 풍경을 모두 보여줄 거야...",
  ui_story_3_13_96_dialog_content = "이게... 죽음이구나... 상상했던 것과는, 조금... 다르네... 외로워...",
  ui_story_3_13_97_dialog_content = "여기 있습니다. 주인님.",
  ui_story_3_13_98_dialog_content = "이 목소리...?!",
  ui_story_3_13_99_dialog_content = "저희 모두 여기 있어요.",
  ui_story_3_13_100_dialog_content = "주인님, 우리가 당신과 끝까지 함께할 겁니다.",
  ui_story_3_13_101_dialog_content = "피니... 필릭... 스...",
  ui_story_3_13_103_dialog_content = "멘델슨!",
  ui_story_3_13_104_dialog_content = "......",
  ui_story_3_13_105_dialog_content = "......",
  ui_story_3_13_106_dialog_content = "<size=45>슈모르... 내 「깜짝 선물」은 잘 받았겠지?</size>",
  ui_story_3_13_107_dialog_content = "음?",
  ui_story_3_13_108_dialog_content = "「싱크탱크 컴포넌트」가... <color=#FFB400>분열</color>하고 있잖아?! 안 돼!",
  ui_story_3_13_110_dialog_content = "<anim type=Shake>멘...델...슨──!</anim>",
  ui_story_3_13_111_dialog_content = "정말 꼴불견이네, 슈모르. 예상 밖의 상황이 생긴 모양이지?",
  ui_story_3_13_112_dialog_content = "멘델슨이 이런 짓을 벌일 줄이야... 이건 이제 쓸모가 없어졌어.",
  ui_story_3_13_113_dialog_content = "그 겁쟁이, 잔챙이가 감히...",
  ui_story_3_13_114_dialog_content = "하하, 아하하하! 역시 내 동족답네!",
  ui_story_3_13_115_dialog_content = "줄곧 나약한 녀석이라고만 생각했는데, 죽기 전에 이런 음모를 꾸밀 줄이야.",
  ui_story_3_13_116_dialog_content = "설마 아무런 정보도 얻지 못했다고 말하진 않겠지.",
  ui_story_3_13_118_dialog_content = "비록 한 마디 말뿐이지만, 새로운 정보를 알아냈어...",
  ui_story_3_13_120_dialog_content = "동일한 「싱크탱크 컴포넌트」가 <color=#FFB400>백야성</color>에도 하나 있었어.",
  ui_story_3_13_121_dialog_content = "그리고 그 어리석은 오로리안들은 그게 뭘 의미하는지 모르고 있는 것 같아...",
  ui_story_3_13_122_dialog_content = "백야성은 쉽게 들어갈 수 있는 곳이 아냐.\n너한테 이 상황을 어떻게 수습하게 만들지 생각해 봐야겠네...",
  ui_story_3_13_123_dialog_content = "두고 봐, 멘델슨. 죽어서도 못 감을 그 눈으로 잘 보는 게 좋을 거야. 누구도 날 막을 순 없다고...",
  ui_story_3_13_124_dialog_content = "네가 한 일들이 아무런 의미도 없다는 걸 깨닫게 해주겠어.",
  ui_story_3_14_A2_dialog_content = "<color=#e8d9bb>백야성, 자료관</color>",
  ui_story_3_14_1_dialog_content = "휴... 오늘도 물건이 정말 많군.",
  ui_story_3_14_2_dialog_content = "정말 엉망진창에 온갖 게 다 있다니까. 으음? 이건...",
  ui_story_3_14_3_dialog_content = "<color=#e8d9bb>콰당!</color>",
  ui_story_3_14_4_dialog_content = "어이쿠!",
  ui_story_3_14_5_dialog_content = "괜찮아? 어디 안 부딪혔어?",
  ui_story_3_14_6_dialog_content = "난 괜찮아. 왜 이런 물건도 하나 제대로 못 옮기는 건데!",
  ui_story_3_14_7_dialog_content = "미, 미안해. 난 오늘이 처음이라...",
  ui_story_3_14_8_dialog_content = "으아아, 이, 이런! 뭐 하는 거야?!",
  ui_story_3_14_9_dialog_content = "미안, 정말 미안해. 일부러 그런 건 아니라고...",
  ui_story_3_14_10_dialog_content = "왜 떨어트려도 하필 <color=#FFB400>그걸</color> 떨어트린 거야! 그게 얼마나 귀한 물건인데!",
  ui_story_3_14_11_dialog_content = "내...내가 주울게.",
  ui_story_3_14_12_dialog_content = "내가 할게. 정확히 뭔지는 잘 모르겠지만, 딱 봐도 값진 물건이잖아.",
  ui_story_3_14_13_dialog_content = "발소리가 들려온다.",
  ui_story_3_14_14_dialog_content = "너희들! 근무 시간에 잡담하는 거냐! 일에 집중해라!",
  ui_story_3_14_15_dialog_content = "중대장님! 지, 지금 자료관의 물건들을 정리하고 있었습니다. 작업은 이제 절반 정도...",
  ui_story_3_14_16_dialog_content = "여긴 됐으니 돌아가라.",
  ui_story_3_14_17_dialog_content = "예! 중대장님!",
  ui_story_3_14_18_dialog_content = "예! 중대장님!",
  ui_story_3_14_A1_dialog_content = "그래, 이 물건... <color=#FFB400>그분</color>의 설명대로군...",
  ui_story_3_14_19_dialog_content = "귀중한 물건이지만, 백야성의 높으신 분들은 널 그저 골동품이라고만 여기는 것 같군...",
  ui_story_3_14_20_dialog_content = "<color=#FFB400>너의 진정한 가치</color>를... 누군가는 알고 있겠지...",
  ui_story_3_14_B1_dialog_content = "중대장님! 군단장님께서 보고를 명하셨습니다!",
  ui_story_3_14_B2_dialog_content = "......",
  ui_story_3_14_B3_dialog_content = "알겠다. 바로 가지.",
  ui_story_4_1_1_dialog_content = "「<color=#FFB400>싱크탱크 컴포넌트</color>」, 「<color=#FFB400>자생 유닛</color>」, 「<color=#FFB400>화염 제어 모듈</color>」...\n그래서 그것들은 대체 어떻게 생긴 건데?",
  ui_story_4_1_2_dialog_content = "멘델슨이 준 정보는 너무 제한적이야.\n또 다른 「싱크탱크 컴포넌트」가 백야성에 있다는 걸 알았다곤 해도...",
  ui_story_4_1_3_dialog_content = "또 다른 콜로서스가 있지는 않겠습니까?",
  ui_story_4_1_4_dialog_content = "녀석들의 계획이 뭐든 간에, 반드시 우리가 앞서 움직여야 해!",
  ui_story_4_1_5_dialog_content = "그럼 곧장 백야성으로 가는 거야? 그다음엔?",
  ui_story_4_1_6_option_content = "임기응변이지!",
  ui_story_4_1_7_option_content = "사실 그다음은 잘 모르겠어.",
  ui_story_4_1_8_dialog_content = "전혀 믿음직하지 않은걸, PlayerName...",
  ui_story_4_1_9_dialog_content = "지금 우린 상대에 대해 전혀 몰라. 상대의 실력, 목적, 심지어 어떻게 생겼는지도 모른다고.",
  ui_story_4_1_10_dialog_content = "정말 놀랄 만큼 솔직한걸...",
  ui_story_4_1_11_dialog_content = "하지만 상대에 대해 아무것도 모르는 상태에선 우리도 전략을 세울 수 없어.",
  ui_story_4_1_12_dialog_content = "상대의 실력, 목적, 심지어 얼굴도 전혀 모르잖아.",
  ui_story_4_1_13_dialog_content = "게다가 백야성은 일루미나와 달라. 굉장히... 까다로운 곳이야...",
  ui_story_4_1_14_dialog_content = "<color=#e8d9bb>바이스의 얼굴 위로 난감하다는 듯한 표정이 떠올랐다.\n아무래도 골치 아픈 일이 생각 난 모양이었다.</color>",
  ui_story_4_1_15_dialog_content = "하지만 PlayerName, 조종사는 너니까 네가 결정해.",
  ui_story_4_1_16_dialog_content = "역시 그래도 백야성에 가 보는 게 좋겠어.",
  ui_story_4_1_17_dialog_content = "바이스, 이 결정이 위험할 수도 있다는 건 알고 있지만...",
  ui_story_4_1_18_dialog_content = "이건 17년 전 진실에 대한 유일한 단서야...",
  ui_story_4_1_19_dialog_content = "좋아... 하지만! 먼저 히이로 군단장님께 보고해야겠어.\n이 일은 네가 생각하는 것보다 훨씬 어려울 테니까...",
  ui_story_4_1_20_dialog_content = "그래도 자기 상관을 잊어버리진 않은 모양이군요.",
  ui_story_4_1_21_dialog_content = "꺄앗! 군단장님 아직 계셨어요?!",
  ui_story_4_1_22_dialog_content = "전 계속 여기 있었습니다만, 바이스 중위. PlayerName,\n당신 동족의 일에는 저도 유감이지만, 백야성 관련 첩보는 신중하게 취급할 필요가 있습니다.",
  ui_story_4_1_23_dialog_content = "신중하게 취급한다니... 무슨 뜻이죠?",
  ui_story_4_1_24_dialog_content = "확실하게 조사하기 전까진, 멘델슨의 말은 증거가 될 수 없습니다.\n게다가 고위 암귀가 이미 여러 차례 모습을 드러낸 이상,\n당신들은 성급하게 행동하지 않는 게 좋을 겁니다.",
  ui_story_4_1_25_dialog_content = "하지만 시간이 없어요. 만약 정말 무슨 일이 생긴다면... 스카이워커호가 우릴 지켜줄 거예요!",
  ui_story_4_1_26_dialog_content = "...미안하지만 솔직히 말하죠. PlayerName.",
  ui_story_4_1_27_dialog_content = "전 처음부터 당신의 콜로서스를 주목하고 있었고, 카론으로부터 기본적인 데이터를 받았습니다.",
  ui_story_4_1_A1_dialog_content = "과거에 있었던 콜로서스의 기준으로 말하자면...",
  ui_story_4_1_28_dialog_content = "당신의 스카이워커호는 <color=#FFB400>6레벨</color>입니다.",
  ui_story_4_1_29_dialog_content = "......",
  ui_story_4_1_30_dialog_content = "네? 그렇게 높다구요? 역시 스카이워커호라니까.",
  ui_story_4_1_31_dialog_content = "최상급은 1레벨입니다. 숫자가 커질수록 성능은 떨어집니다.",
  ui_story_4_1_32_dialog_content = "......?",
  ui_story_4_1_33_dialog_content = "그럼 가장 낮은 레벨은 몇인데요?",
  ui_story_4_1_34_dialog_content = "<color=#FFB400>6레벨</color>입니다.",
  ui_story_4_1_35_dialog_content = "...?!",
  ui_story_4_1_36_dialog_content = "스카이워커! 너 「천공급」 콜로서스라고 하지 않았어?!",
  ui_story_4_1_37_dialog_content = "그건 당신에게 살아갈 동기를 부여하기 위해 했던 불가피한 거짓말입니다.",
  ui_story_4_1_A2_dialog_content = "그리고 애초부터 「천공급」이란 설정은 없었습니다.",
  ui_story_4_1_38_dialog_content = "날 기만한 걸 그렇게 태연하게 인정하는 거야?!",
  ui_story_4_1_39_dialog_content = "6레벨 콜로서스는 생명 유지, 적재 및 운송 기능만 지니고 있고...",
  ui_story_4_1_40_dialog_content = "「도주」 임무 수행에 적합합니다.",
  ui_story_4_1_41_dialog_content = "알겠으니까 그만 말해요...",
  ui_story_4_1_42_dialog_content = "PlayerName, 엄청 실망한 모양이네...",
  ui_story_4_1_43_dialog_content = "제가 괜한 말을 한 모양이군요... 하지만 낙담할 필요는 없습니다, PlayerName.",
  ui_story_4_1_44_dialog_content = "아이테르로서 당신은 남들에겐 없는 재능이 있고, 뛰어난 지휘 능력도 가지고 있습니다.\n그 점은 저도 전혀 의심하지 않습니다.",
  ui_story_4_1_45_dialog_content = "게다가 바이스 중위가 저렇게 당신을 좋게 보고 있다는 건,\n당신이 그만큼 신뢰할 수 있는 사람이기 때문이겠죠.",
  ui_story_4_1_46_dialog_content = "에?",
  ui_story_4_1_47_dialog_content = "고마워요, 히이로 씨. 그럼... 최선을 다할게요.",
  ui_story_4_1_48_dialog_content = "그럼 어서 출발하자! 슈모르도 분명히 움직이기 시작했을 거야. 우리도 서둘러야 해!",
  ui_story_4_1_49_dialog_content = "알겠어! 그럼 군단장님, 백야성으로 가는 출입 허가 서류를 발급해 주실 수 있을까요?",
  ui_story_4_1_50_dialog_content = "그건 안 됩니다. 스스로 방법을 생각하도록 하세요.",
  ui_story_4_1_51_dialog_content = "에에?",
  ui_story_4_1_52_dialog_content = "유감스럽지만, 아직 검증되지 않은 정보를 바탕으로 일루미나 연방 차원에서 공식적인 행동을\n취하는 건 곤란합니다. 하물며 백야성과 관계가 있는 일이라면 더욱 신중해야겠죠.",
  ui_story_4_1_54_dialog_content = "......",
  ui_story_4_1_55_dialog_content = "당신 이력에 「백야성 유학 경험 있음」이라고 적혀있던 걸 기억합니다만.\n이참에 동창과 지난 추억을 되새겨 보는 것도 좋겠군요.",
  ui_story_4_1_56_dialog_content = "제 기억이 틀리지 않았다면, 백야성의 호위대장, 「<color=#FFB400>카렌</color>」이라는 자와 동창 아니었습니까?",
  ui_story_4_1_57_dialog_content = "그래서 더 골치가 아픈 건데요... 하아...",
  ui_story_4_1_58_dialog_content = "<color=#e8d9bb>백야성 상공</color>",
  ui_story_4_1_59_dialog_content = "저기 <color=#FFB400>떠 있는 공중 도시</color>가 바로 목적지겠군요.",
  ui_story_4_1_60_dialog_content = "도착한 것 같네. 역시 콜로서스는 정말 빠르다니까...",
  ui_story_4_1_X1_dialog_content = "바이스, 그 차림새는...",
  ui_story_4_1_X2_dialog_content = "약간의 위장일 뿐이야! 카렌한테 설명을 위한 편지를 보내두긴 했지만,\n그래도 역시 눈에 띄지 않는 게 좋아...",
  ui_story_4_1_X3_dialog_content = "...그게 오히려 더 눈에 띌 것 같은데.",
  ui_story_4_1_61_dialog_content = "PlayerName, 저길 봐!",
  ui_story_4_1_62_dialog_content = "저기가 바로 백야성이야.",
  ui_story_4_1_64_option_content = "저곳이 「최후의 도시」인가...",
  ui_story_4_1_65_option_content = "저 도시는 어떻게 떠 있는 거지...",
  ui_story_4_1_66_dialog_content = "응? 혼자 뭐라고 중얼거리는 거야? 어서 이리 와. 임무가 시작되기 전에 다시 한번 설명해 줄게!",
  ui_story_4_1_67_dialog_content = "지금부터 무슨 일이 발생하든지 대답하는 건 나한테 맡겨. 알겠지?",
  ui_story_4_1_68_dialog_content = "절대 충동적으로 행동하면 안 돼. 잊지 마, 우린 슈모르보다 먼저 목표를 찾아내야 해!",
  ui_story_4_1_69_dialog_content = "알겠어, 바이스 중위. 역시 믿음직스럽다니까!",
  ui_story_4_1_70_dialog_content = "응, 그럼 증명서를 다시 한번 확인해 볼게... 「그 녀석」은 정말 상대하기 싫은데...",
  ui_story_4_1_71_dialog_content = "PlayerName, 조금 불안합니다. 제가 혼자 여기 있어도 정말 괜찮겠습니까?",
  ui_story_4_1_72_dialog_content = "어쩔 수 없어, 스카이워커. 너도 네가 얼마나 눈에 띄는지 알잖아.",
  ui_story_4_1_73_dialog_content = "함께 있으면 백야성에 들어가는 건 고사하고, 성 근처에도 못 갈 거야.",
  ui_story_4_1_74_dialog_content = "게다가 넌 6레벨이라면서? 전투 지원은 불가능한 거 아냐?",
  ui_story_4_1_75_dialog_content = "...아직도 마음에 담아두고 계신 겁니까.",
  ui_story_4_1_76_dialog_content = "알겠습니다. 틀린 말도 아니니, 전투는 모두 여러분에게 맡기겠습니다.",
  ui_story_4_1_A3_dialog_content = "저는 은폐된 공역에서 대기하고 있겠습니다. 부디 조심하십시오.",
  ui_story_4_1_77_dialog_content = "좋아, 그럼 출발하자. 방금 도시 입장 줄을 봤는데 엄~청나게 길더라고.",
  ui_story_4_1_A4_dialog_content = "휴... 줄 서는 건 진짜 싫은데...",
  ui_story_4_1_78_dialog_content = "「그 녀석」... 백야성의 호위대장, <color=#FFB400>카렌 드 솔라드</color>도 만나고 싶지 않고.",
  ui_story_4_1_79_dialog_content = "그 호위대장이 무슨 문제라도 있어?",
  ui_story_4_1_80_dialog_content = "하아... 조금만 있으면 알게 돼. 분명히 성문 앞에서 우릴 기다리고 있을 테니까!",
  ui_story_4_1_81_dialog_content = "바이스, 네가 말한 호위대장이 어디 있는데?",
  ui_story_4_1_82_dialog_content = "쉿!",
  ui_story_4_1_83_dialog_content = "질서를 지켜서 검사에 협조해 주십시오!",
  ui_story_4_1_84_dialog_content = "임시 통행증을 소지한 외부인은 24시간 이상 체류할 수 없으며,\n이를 위반할 경우 법에 의거해 백야성에서 추방될 것입니다!",
  ui_story_4_1_85_dialog_content = "의심스러운 사람이 발견되면 즉시 백야성 경비병에게 보고해 주십시오!",
  ui_story_4_1_86_dialog_content = "PlayerName, 다시 한번 말하지만, 무슨 일이 발생해도 절대...",
  ui_story_4_1_87_dialog_content = "거기 수상하게 수군대지 말고, 통행증을 꺼내십시오!",
  ui_story_4_1_88_dialog_content = "아, 네...",
  ui_story_4_1_89_dialog_content = "또 일루미나입니까... 최전방이 그렇게 한가합니까? 옷차림이 수상하군요, 꼬마 아가씨.",
  ui_story_4_1_90_dialog_content = "...으엑, 이번엔 개인적인 일로 온 거예요.",
  ui_story_4_1_91_dialog_content = "왜 그렇게 이리저리 힐끔거리는 겁니까? 백야성에 처음 오십니까?",
  ui_story_4_1_92_dialog_content = "아뇨. 전 이곳의 유학생이었어요. 이번에는 A급 통행증 연장 수속 때문에 온 거예요...",
  ui_story_4_1_93_dialog_content = "옆에 있는 사람은 일행입니까? 「난 수상한 사람이다」라고 얼굴에 쓰여 있습니다만.",
  ui_story_4_1_94_option_content = "나? 난 얼마 전에 땅에서 겨우 나왔는데?",
  ui_story_4_1_95_option_content = "(바이스가 아무 말도 하지 말라고 했는데...)",
  ui_story_4_1_96_dialog_content = "...지금 나랑 농담하자는 겁니까? 증명서 꺼내세요! 사람마다 증명서 하나라고 쓰여 있지 않습니까!",
  ui_story_4_1_97_dialog_content = "당신한테 묻고 있잖습니까. 귀가 안 좋습니까?!",
  ui_story_4_1_98_dialog_content = "미안해요. 이 친구는 저랑 같이 온 거예요.\n제 신청서는 특별 허가를 받은 거니까, 한 번 더 자세히 살펴보세요!",
  ui_story_4_1_99_dialog_content = "이건 당신네 호위대장 카렌의...",
  ui_story_4_1_100_dialog_content = "「호위대장」? ...아, 당신이었군요!",
  ui_story_4_1_101_dialog_content = "그럼 진작 좀 말하지... 알겠습니다. 이곳에서 잠시만 기다려 주십시오.",
  ui_story_4_1_102_dialog_content = "휴...",
  ui_story_4_1_103_dialog_content = "한가로워 보이네. 일루미나에서는 할 일이 없는 모양이야?",
  ui_story_4_1_104_dialog_content = "하아, <color=#FFB400>카렌</color>... 오랜만이네. 넌 여전히 그렇게... 위풍당당하구나.",
  ui_story_4_1_105_dialog_content = "호위대장의 이름을 그냥 부르다니... 배짱 하나는 존경스러운걸...",
  ui_story_4_1_106_dialog_content = "이 이상한 패션의 언니, 어디서 본 것 같아...",
  ui_story_4_1_107_dialog_content = "아! 카렌 언니의 동창이구나?",
  ui_story_4_1_108_dialog_content = "라파엘, 조용히 해... 호위대장이 이야기하게 해줘~",
  ui_story_4_1_109_dialog_content = "우리 미카엘 좀 보고 배워. 아무 말도 안 하고 진중하잖아~",
  ui_story_4_1_110_dialog_content = "......",
  ui_story_4_1_111_dialog_content = "모두 조용히.",
  ui_story_4_1_112_dialog_content = "이렇게 전부 따라올 필요는 없어. 호위대는 규정대로 순찰하도록 해.",
  ui_story_4_1_113_dialog_content = "이 두 방문자는 나한테 맡겨.",
  ui_story_4_1_114_dialog_content = "자기소개는 필요 없겠지?",
  ui_story_4_1_115_dialog_content = "카렌, 단도직입적으로 말할게. 우리가 여기 온 건...",
  ui_story_4_1_116_dialog_content = "편지에 쓰여 있던 거로 충분해. 네 문법은 여전하더구나. 경어 사용도 엉망진창이고.",
  ui_story_4_1_117_dialog_content = "그러니까... 「<color=#FFB400>암귀가 백야성을 노리고 있다.</color>」는 말인 거지?",
  ui_story_4_1_118_dialog_content = "이런 상황에서도 문법 지적을 하는 거냐고...",
  ui_story_4_1_A5_dialog_content = "맞아, 우리가 얻은 정보에 따르면, 「슈모르」라는 녀석이 백야성을 노리고 있어.",
  ui_story_4_1_119_dialog_content = "우린 그 녀석이 백야성에서 「<color=#FFB400>싱크탱크 컴포넌트</color>」를 훔치려 한다고 예상하고 있어.",
  ui_story_4_1_120_dialog_content = "「싱크탱크 컴포넌트」? 미안하지만 들어본 적 없는걸.\n하지만 백야성에선 그 무엇도 훔쳐갈 수 없을 거야...",
  ui_story_4_1_122_dialog_content = "음? 당신은 누구지?",
  ui_story_4_1_123_dialog_content = "...내가 대답해도 돼?",
  ui_story_4_1_124_dialog_content = "이 정도 소리로 말하면 안 들릴 줄 알았어?",
  ui_story_4_1_125_dialog_content = "......",
  ui_story_4_1_126_dialog_content = "PlayerName 얘는 말이지... 카렌, 너한테만 알려줄 수 있어. 저기, 가, 가까이 좀...",
  ui_story_4_1_127_dialog_content = "그러니까 저 사람이... 혼자 숨어서 살아남은 그 「이기적인 아이테르」란 말이지? 그럼 그 콜로서스는?",
  ui_story_4_1_128_dialog_content = "스카이워커호라고 하는데... 지금 백야성 위의 공역에 멈춰있어. 아마 탐지할 수 없을 거야.",
  ui_story_4_1_129_dialog_content = "...!",
  ui_story_4_1_130_dialog_content = "걱정 마. 「도망만 칠 수 있는」, 「전투 능력은 전혀 없는」 6레벨 콜로서스야.",
  ui_story_4_1_131_dialog_content = "흥.",
  ui_story_4_1_132_dialog_content = "그런 건 지금 중요하지 않아. 카렌, PlayerName의 신분은 이미 알려줬으니까, 우릴 믿어줘!",
  ui_story_4_1_133_dialog_content = "그 정도 증거론 부족해... 더 설득력 있는 건 없어?",
  ui_story_4_1_134_dialog_content = "그 외엔 아직 없어... 암귀는 분명히 백야성에 들어오려고 시도 중일 거야.\n어쩌면 줄 서 있는 사람들 사이에 섞여 있을지도 몰라!",
  ui_story_4_1_137_dialog_content = "호위대장님! 긴급 상황입니다!",
  ui_story_4_1_139_dialog_content = "...?! 그게 정말인가?",
  ui_story_4_1_140_dialog_content = "무슨 얘기를 하는 거지?",
  ui_story_4_1_141_dialog_content = "잘 모르지만 별로 좋은 소식은 아닌 것 같네...",
  ui_story_4_1_142_dialog_content = "바이스, 동창의 옛정을 생각해서... 일단은 널 믿고 입성을 허가할게.",
  ui_story_4_1_143_dialog_content = "하지만 너희의 모든 일정에 내가 동행하겠어.\n만약 거짓말인 게 밝혀진다면, 그에 상응하는 처벌을 받아야 할 거야!",
  ui_story_4_1_144_dialog_content = "뭐, 좋아. 알겠어! 그럼 빨리 가보자! 일단 먼저...",
  ui_story_4_1_145_dialog_content = "<color=#FFB400>다운타운 구역</color>부터 시작하자.",
  ui_story_4_1_146_dialog_content = "다운타운 구역?",
  ui_story_4_1_147_dialog_content = "그래... 조금 전 다운타운 구역에서 <color=#FFB400>습격 사건</color>이 발생했어.",
  ui_story_4_1_148_dialog_content = "?!",
  ui_story_4_2_1_dialog_content = "<color=#e8d9bb>다운타운 구역</color>",
  ui_story_4_2_2_dialog_content = "정신없이 놀았네. 늦었으니 지름길로 갈까...",
  ui_story_4_2_3_dialog_content = "응? 거기 누구... 으아아아아아악!",
  ui_story_4_2_4_dialog_content = "시끄럽네.",
  ui_story_4_2_5_dialog_content = "미안, 미안, 내 실수.",
  ui_story_4_2_6_dialog_content = "죽은 거 맞아?",
  ui_story_4_2_A1_dialog_content = "걱정 마. 이미 해치웠으니까.",
  ui_story_4_2_7_dialog_content = "날 원망하지 마라, 불쌍한 녀석. 그러게 왜 이런 시간에 여길 돌아다닌 거냐.",
  ui_story_4_2_8_dialog_content = "운도 중요한 생존 능력이라고.",
  ui_story_4_2_9_dialog_content = "여전히 이런 녀석들과 쓸데없는 말을 하는 걸 즐기는구나, 거츠더.",
  ui_story_4_2_A2_dialog_content = "이렇게나 오랜만에 만났는데, 나한테 말한 것보다 저놈한테 한 말이 더 많잖아!",
  ui_story_4_2_10_dialog_content = "스예트, 난 단 한 순간도 널 그리워하지 않은 적이 없어. 넌 영원히 내 마음 속에 있을 거야.",
  ui_story_4_2_11_dialog_content = "입만 살아서는... 일단 본론부터 말하자면, 그분께서 소식을 전하셨어. 우릴 써주시겠다고 말이야.",
  ui_story_4_2_12_dialog_content = "지금?",
  ui_story_4_2_13_dialog_content = "그래, 상세한 계획은 천천히 알려줄게.",
  ui_story_4_2_14_dialog_content = "꼬마 친구들을 미끼로 보내놨으니, 곧 호위대가 이 근처로 올 거야. 당신은 기회를 봐서...",
  ui_story_4_2_15_dialog_content = "잠깐, 정말 결정한 거야? 스예트, 그렇게 큰 위험을 무릅쓸 필요는 없어. 넌 내가...",
  ui_story_4_2_16_dialog_content = "됐어, 거츠더. 말하지 마. 내가 하자는 대로 해줘.",
  ui_story_4_2_17_dialog_content = "난 여기에 호위대를 붙잡아 둘 테니, 당신은... 가서 <color=#FFB400>그 물건을 훔쳐 와</color>.",
  ui_story_4_2_18_dialog_content = "...물건 위치는 이미 확인해뒀어. 하지만 정말 그게 다야?",
  ui_story_4_2_19_dialog_content = "그래. 그걸로 끝이야. 이번 계획만 성공하면 우리가 원하던 자유를 얻을 수 있어. 안 그래?",
  ui_story_4_2_20_dialog_content = "...좋아. 아무튼 네 설득력 하나는 알아줘야 한다니까.",
  ui_story_4_2_21_dialog_content = "보고드립니다! 주민이 암귀의 습격을 받았다고 신고했습니다!",
  ui_story_4_2_22_dialog_content = "같은 곳이 아니야? 설마 다른 한패가 있는 건가?",
  ui_story_4_2_23_dialog_content = "카렌 언니! 우리가 왔어!",
  ui_story_4_2_24_dialog_content = "......",
  ui_story_4_2_25_dialog_content = "너희는 동쪽 구역을 조사해 줘! 적은 한 곳에만 있는 게 아닌 것 같아.",
  ui_story_4_2_26_dialog_content = "알겠어! 다른 호위대원들은?",
  ui_story_4_2_27_dialog_content = "업타운 구역에 있어. 호위대의 대부분은 귀족의 거처를 지켜야 하니까... 그분의 명령도 있었고 말이야.",
  ui_story_4_2_28_dialog_content = "<color=#FFB400>성주 전하</color> 말인가...",
  ui_story_4_2_29_dialog_content = "지금까지 보고된 습격 지점은 모두 동쪽 구역이야. 다운타운 구역의 관리자도 이미 그곳으로 갔어.",
  ui_story_4_2_30_dialog_content = "그럼 난... 서쪽 구역으로 가야겠어. 이상한 느낌이 들거든...",
  ui_story_4_2_31_dialog_content = "또 저 눈빛이야. 「뭔가 엄청난 걸 생각해내곤 즉시 행동에 옮기는」 모습.",
  ui_story_4_2_32_dialog_content = "함께 학교에 다닐 때도 저런 눈빛이었던 거야?",
  ui_story_4_2_33_dialog_content = "응. 격투 수업에서 날 때려눕히려고 했을 때라든지 말이야.",
  ui_story_4_2_34_dialog_content = "...카렌은 엄청 대단한 사람인 모양이네.",
  ui_story_4_2_35_dialog_content = "아부해봤자 너한테 좋을 건 없어. 서쪽 구역으로 가자... PlayerName, 넌 싸울 수 있어?",
  ui_story_4_2_36_dialog_content = "싸울 순 없지만, 지휘와 인도를 해줄 순 있어.",
  ui_story_4_2_37_dialog_content = "네가 하는 말이라 그런지, 신빙성이 떨어지네.",
  ui_story_4_2_38_dialog_content = "하지만 자신을 증명할 기회는 줄게.",
  ui_story_4_2_39_dialog_content = "엄청난 압박감이네...",
  ui_story_4_3_1_dialog_content = "의외로 지휘에 꽤 재능이 있네.",
  ui_story_4_3_2_dialog_content = "게다가... 이게 바로 빛의 궤적인가? 이런 능력을 지닌 종족이 내가 태어나기 전에 멸망해 버렸다니.",
  ui_story_4_3_3_dialog_content = "나이가 들통나 버렸네, 카렌 양.",
  ui_story_4_3_4_dialog_content = "우쭐대지 마. 지금 서쪽 구역에도 암귀가 나타났으니까, 방심해선 안 돼.",
  ui_story_4_3_5_dialog_content = "암귀의 수가 생각보다 많잖아...",
  ui_story_4_3_6_option_content = "백야성은 「난공불락」 아니었어?",
  ui_story_4_3_7_option_content = "성문의 경비병이 암귀를 막을 수 없는 거야?",
  ui_story_4_3_8_dialog_content = "「난공불락」은 업타운 구역을 가리키는 말이야. 다운타운 구역은 그렇지 않아...",
  ui_story_4_3_9_dialog_content = "경비병도 물론 제 역할을 하곤 있어.\n하지만 대부분의 경비병이 지키는 건 업타운 구역이지, 다운타운 구역은 아냐.",
  ui_story_4_3_10_dialog_content = "우리가 지금 있는 다운타운 구역은 스스로 살아남아야 하는 곳이야. 안 그래? 카렌.",
  ui_story_4_3_F1_dialog_content = "......",
  ui_story_4_3_11_dialog_content = "다운타운 구역과 업타운 구역의 대우가 그 정도로 다른 거야?",
  ui_story_4_3_12_dialog_content = "어쩔 수 없어. 그게 바로 「백야성」이니까...",
  ui_story_4_3_13_dialog_content = "늦어서 죄송합니다... 중대장 거츠더, 보고드립니다.",
  ui_story_4_3_14_dialog_content = "특이사항이 있나?",
  ui_story_4_3_15_dialog_content = "없었습니다, 호위대장님.",
  ui_story_4_3_16_dialog_content = "사람을 모아 성안의 주민을 먼저 대피시킨다! 그리고 다운타운 구역 입구를 봉쇄해라!",
  ui_story_4_3_17_dialog_content = "이미 완료했습니다, 호위대장님.",
  ui_story_4_3_18_dialog_content = "빠르군. 그럼 이제 우리와 함께...",
  ui_story_4_3_19_dialog_content = "죄송합니다만, 아직 많은 사람이 도시 밖에 갇혀있습니다. 반드시 저들이 성으로 들어오도록 해야 합니다.",
  ui_story_4_3_20_dialog_content = "그렇지 않으면 모두 암귀에게 속수무책으로 당하고 말 겁니다.",
  ui_story_4_3_21_dialog_content = "...좋다. 그럼 병사 몇을 남기고 가보도록.",
  ui_story_4_3_22_dialog_content = "그럼 먼저 물러가겠습니다. 만물은 백야 아래에.",
  ui_story_4_3_23_dialog_content = "카렌, 방금 그 사람은...?",
  ui_story_4_3_24_dialog_content = "다운타운 구역의 중대장 중 하나야. 대부분의 경계 임무를 책임지고 있어. 꽤 능력 있는 사람이야.",
  ui_story_4_3_25_dialog_content = "게다가... 한때는 <color=#FFB400>유명한 기사</color>였기도 했고.",
  ui_story_4_3_26_dialog_content = "역시 사람은 겉모습으로 판단하면 안 되는 건가...",
  ui_story_4_3_27_dialog_content = "자, 우리도 계속할까. 놓쳤던 암귀들이 다운타운 구역에서 소동을 피우고 있는 모양이야.",
  ui_story_4_3_28_dialog_content = "그리고 나도 너희가 말한 그 「<color=#FFB400>슈모르</color>」라는 녀석을 꼭 한번 보고 싶은걸...",
  ui_story_4_6_1_dialog_content = "보고드립니다! 동쪽 구역은 모두 정리됐습니다!",
  ui_story_4_6_2_dialog_content = "호위대장님, 서쪽 구역에서 새로운 보고가 들어왔습니다! 아무래도 고위 암귀 같습니다!",
  ui_story_4_6_3_dialog_content = "역시! 어디지? 위치를 보고해라!",
  ui_story_4_6_4_dialog_content = "설마 지금까지는 전부 속임수였던 건가?\n그럼 「싱크탱크 컴포넌트」는 분명히 고위 암귀 근처에 있을 거야!",
  ui_story_4_6_5_dialog_content = "아직 늦진 않은 것 같아!",
  ui_story_4_6_6_dialog_content = "우리 쪽엔 직감이 좋은 카렌이 있잖아!",
  ui_story_4_6_7_dialog_content = "......",
  ui_story_4_6_8_dialog_content = "으앗, 또 그런 눈빛... 왜, 뭔가 이상해?",
  ui_story_4_6_9_dialog_content = "...모르겠어. 하지만 이 느낌, 좋지 않아... 아무튼 일단 가자!",
  ui_story_4_6_10_dialog_content = "스예트! 계획을 멈춰야만 해!",
  ui_story_4_6_11_dialog_content = "무슨 소릴 하는 거야? 그 공주님, 카렌 드 솔라드도 이미 우리 계획대로 움직이고 있잖아!",
  ui_story_4_6_12_dialog_content = "이럴 때 멈추라니? 거츠더, 지금 같은 상황에서 당신이랑 말싸움하고 싶지 않아.",
  ui_story_4_6_13_dialog_content = "카렌 말고 일루미나 쪽 녀석도 함께 있다고! 저들도 「싱크탱크 컴포넌트」를 찾고 있는 것 같아!",
  ui_story_4_6_14_dialog_content = "게다가 자료관의 문을 여는 게 쉽지 않아. 시간 안에 가능할지 모르겠다고...",
  ui_story_4_6_15_dialog_content = "아니, 안 돼. 우린 그런 녀석들 때문에 멈출 순 없어!",
  ui_story_4_6_16_dialog_content = "절대... 절대로 허락할 수 없다고...",
  ui_story_4_6_17_dialog_content = "그럼 이제 어떻게 하지?",
  ui_story_4_6_18_dialog_content = "내가 시간을 더 끌어줄게!",
  ui_story_4_6_19_dialog_content = "<color=#FFB400>샤를</color>... 그래, 샤를을 깨워서 함께 하면...",
  ui_story_4_6_20_dialog_content = "안 돼! 스예트, 네가 무슨 생각이든, 그건 절대 안 된다고!",
  ui_story_4_6_21_dialog_content = "네 동생 샤를은... 이미 제어할 수 없을 지경으로 미쳐버렸어!",
  ui_story_4_6_22_dialog_content = "미쳤다고? 후훗... 나라고 다를 게 있을까?",
  ui_story_4_6_23_dialog_content = "거츠더, 이곳을 떠나. 날 실망하게 만들지 말고 당신이 가야 할 곳으로 가.",
  ui_story_4_6_24_dialog_content = "...약속한 곳에서 기다릴게, 스예트.",
  ui_story_4_6_25_dialog_content = "기사한테 한 약속이니까 넌 반드시 지킬 거야. 그렇지?",
  ui_story_4_6_26_dialog_content = "당연하지, 거츠더. 무슨 일이 있어도... 반드시 우리의 약속을 지킬게...",
  ui_story_4_6_27_dialog_content = "샤를, 잘 잤니? 일어나렴, 언니랑 같이... 놀자.",
  ui_story_4_6_28_dialog_content = "노, 놀자...",
  ui_story_4_7_1_dialog_content = "<color=#e8d9bb>다운타운 구역, 골목 안쪽</color>",
  ui_story_4_7_2_dialog_content = "호위대장님, 방금 시체 한 구를 발견했습니다. 다운타운 쪽을 담당하던 경비병으로 확인됐습니다.",
  ui_story_4_7_3_dialog_content = "상처는 하나뿐이었습니다... 일격에 심장을 관통당했습니다...",
  ui_story_4_7_4_dialog_content = "경비병 전원! 수색을 시작하라, 내 백성을 해치는 녀석을 결코 용납할 순 없어!",
  ui_story_4_7_5_dialog_content = "「<color=#FFB400>내 백성</color>」?",
  ui_story_4_7_6_dialog_content = "뭐, 확실히 카렌이 백성들을 아끼긴 하지...",
  ui_story_4_7_7_dialog_content = "아니, 내가 궁금한 건... 왜 「<color=#FFB400>내 백성</color>」인 건데?",
  ui_story_4_7_8_dialog_content = "아... 내가 말 안 했나? 카렌은 말이지... <color=#FFB400>백야성 성주님의 딸</color>이거든.",
  ui_story_4_7_9_dialog_content = "...?!",
  ui_story_4_7_10_dialog_content = "미안, 미안, 정신이 없어서 알려주는 걸 잊어버렸네...",
  ui_story_4_7_11_dialog_content = "하지만 적어도 지금 이 순간의 카렌은 「백야성의 호위대장」일 뿐이야.",
  ui_story_4_7_13_dialog_content = "으앗! 무슨 소리지!?",
  ui_story_4_7_14_dialog_content = "경비병! 어서 소리가 난 곳을 찾아라!",
  ui_story_4_7_16_dialog_content = "다른 사람한테... 이 모습을 보여주는 건 처음이네.",
  ui_story_4_7_17_dialog_content = "민가가... 폭발했잖아?",
  ui_story_4_7_18_dialog_content = "저 사람 뭔가 이상해! 카렌, PlayerName, 조심해!",
  ui_story_4_7_19_dialog_content = "...넌 ...스예트?",
  ui_story_4_7_20_dialog_content = "이런 날이 올 줄은 몰랐네... 내가 공주님과 이렇게 같은 눈높이로 마주 보고 있다니 말이야...",
  ui_story_4_7_21_dialog_content = "어때? 내 새로운 모습. 전에 비하면 어느 쪽이 더 예쁘려나?",
  ui_story_4_7_22_dialog_content = "카렌, 아는 사이야?",
  ui_story_4_7_23_dialog_content = "오래전에는 그랬지. 지금은 자신의 신앙을 져버린 가련한 인간일 뿐이야.",
  ui_story_4_7_24_dialog_content = "「가련한 인간」이라... 맞아, 그렇지.",
  ui_story_4_7_25_dialog_content = "높은 분들이 보기에 난 그저 업타운 구역의 벌레보다도 못한\n구차한 삶을 살아야 하니까, 얼마나 가련하겠어...",
  ui_story_4_7_26_dialog_content = "그건 네가 스스로 타락했기 때문이야!",
  ui_story_4_7_27_dialog_content = "지금 네 꼴을 봐... 그 모습을 대체 뭐라고 형용해야 할지도 난 모르겠다고.",
  ui_story_4_7_28_dialog_content = "내가 타락했다고? 꼬마 공주님, 당신이 그 고귀한 침대에서 태어나지 못했다면 어땠을 것 같아?",
  ui_story_4_7_29_dialog_content = "만약 곰팡이가 핀 볏짚 위에서 태어났다면, 아무것도 아닐 거잖아?",
  ui_story_4_7_30_dialog_content = "......",
  ui_story_4_7_31_dialog_content = "대답할 수 없겠지. 이 모든 게 「스스로 타락」했기 때문이라고 쉽게 떠들어 대다니,\n역시 오만한 공주님다워.",
  ui_story_4_7_32_dialog_content = "스예트, 전에 내가 했던 말, 아직 기억하겠지?",
  ui_story_4_7_33_dialog_content = "난 백야의 이름으로 맹세했어. 네가 다시 이곳에 발을 들인다면, 이 창으로 정의를 실현하겠다고!",
  ui_story_4_7_34_dialog_content = "오늘 난 그 맹세를 지키겠어.",
  ui_story_4_7_35_dialog_content = "사실 떠난 적도 없어. 난 줄곧 당신 곁에 있었거든. 빛이 비치지 않는 구석에 말이야...",
  ui_story_4_7_36_dialog_content = "놀랍지 않아? 게다가 「친구」도 많이 생겼지 뭐야.",
  ui_story_4_7_37_dialog_content = "뭐라고...?!",
  ui_story_4_7_38_dialog_content = "내 「동생」, 귀여운 샤를. 내 곁으로 오렴!",
  ui_story_4_7_39_dialog_content = "어, 언니... 샤를...",
  ui_story_4_7_40_dialog_content = "「놀고」 싶다고? 정말 어쩔 수가 없다니까~",
  ui_story_4_7_41_dialog_content = "자, 우리 같이 앞에 있는 귀여운 공주님이랑 「놀아」보자~",
  ui_story_4_7_42_dialog_content = "...놀자──!",
  ui_story_4_7_43_dialog_content = "조심해──!",
  ui_story_4_7_44_dialog_content = "어째서어어어! 말도 안 돼! 대체 왜... 너!",
  ui_story_4_7_45_dialog_content = "넌 누구지?! 어째서 녀석들을 이끌고 지휘할 수 있는 건데?!",
  ui_story_4_7_46_dialog_content = "설마 넌... 아이테르?!",
  ui_story_4_7_47_dialog_content = "......",
  ui_story_4_7_48_dialog_content = "재미없어... 재미없어! 언니, 갈래...",
  ui_story_4_7_49_dialog_content = "안 돼, 아직 시간이 더 필요해. 우리도... 이대로 그만둘 순 없어!",
  ui_story_4_7_50_dialog_content = "너, 그리고 백야성의 졸개들! 어디 한번 따라와 보라고!",
  ui_story_4_7_51_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_4_7_53_dialog_content = "콜록, 콜록... 이런! <color=#FFB400>도망쳤어</color>!",
  ui_story_4_7_54_dialog_content = "업타운! 업타운 구역 쪽으로 도망쳤다!",
  ui_story_4_7_55_dialog_content = "경보를 울려라! 호위대 전원한테 알려! 신속하게 업타운 구역으로 돌아가 방어하라!",
  ui_story_4_7_56_dialog_content = "PlayerName! 빨리! 우리도 쫓아가야 해!",
  ui_story_4_8_1_dialog_content = "<color=#e8d9bb>업타운 구역에서 멀리 떨어진 백야성 자료관</color>",
  ui_story_4_8_2_dialog_content = "왼쪽으로... 3도... 오른쪽... 14도... 다시...",
  ui_story_4_8_3_dialog_content = "제길, 또 막히다니... 이 암호, 대체 어떻게 되먹은 거야?!\n역시 지난번에 뒷문을 만들어 놓지 않았던 게 실수였어...",
  ui_story_4_8_4_dialog_content = "그냥 폭탄을 사용하면... 아니지, 그건 안 돼. 만에 하나 컴포넌트에 손상이라도 간다면...",
  ui_story_4_8_5_dialog_content = "자료관 같은 곳에서 왜 이런 자물쇠를 쓰는 거지...?",
  ui_story_4_8_6_dialog_content = "거츠더.",
  ui_story_4_8_7_dialog_content = "스예트! 미안해, 시간이 좀 더 필요해. 자료관의 문이...",
  ui_story_4_8_8_dialog_content = "잠깐, 싸우고 있어?",
  ui_story_4_8_9_dialog_content = "아니... 미안, 나... 도망치는 중이야.",
  ui_story_4_8_10_dialog_content = "아이테르가 있어! 거츠더... 녀석들 사이에 아이테르가 있었다고!",
  ui_story_4_8_11_dialog_content = "카렌과 싸웠어? 어디 다친 데는?!",
  ui_story_4_8_12_dialog_content = "잘 들어. 내가 놈들을 업타운 구역 남쪽으로 데려갈게. 그곳이 당신과 가장 먼 곳이니까...",
  ui_story_4_8_A1_dialog_content = "그럼 시간은 충분할 거야...",
  ui_story_4_8_13_dialog_content = "안 돼! 업타운 구역으로 간다는 건 죽겠다는 거나 마찬가지라고!",
  ui_story_4_8_14_dialog_content = "스예트, 우리 목적을 잊지 마...",
  ui_story_4_8_15_dialog_content = "<color=#FFB400>그분</color>께서 도와주실 거야. 난 믿어. 약속했으니까...",
  ui_story_4_8_16_dialog_content = "신념은 우리의 힘이야, 거츠더. 우리가 선택한 이상, 끝까지 가야만 해!",
  ui_story_4_8_17_dialog_content = "백야성 밖에서 봐, 달링.",
  ui_story_4_8_18_dialog_content = "스예트──!",
  ui_story_4_8_19_dialog_content = "자, 잠깐. 너무 빠르다고...",
  ui_story_4_8_20_dialog_content = "카렌, 그 샤를이라는 애는 또 누구야? 둘 다 원래 오로리안이었던 거야?",
  ui_story_4_8_21_dialog_content = "인정하고 싶진 않지만, 맞아. 둘 다 백야성과 갈등이 있었던... 변절자일 뿐이야.",
  ui_story_4_8_22_dialog_content = "PlayerName, 조금 전 지휘는 정말 훌륭했어. 사실 난 네가 고위 암귀 앞에선 위축될 거라고 생각했거든.",
  ui_story_4_8_23_dialog_content = "넌 내가 생각한 아이테르와는 전혀 다른 것 같아.",
  ui_story_4_8_24_option_content = "이건 내 사명일 뿐이야.",
  ui_story_4_8_25_option_content = "아니, 나도 다른 아이테르와 다르지 않아.",
  ui_story_4_8_26_dialog_content = "카렌 양, 당신도 호위대장으로 열심히 싸우고 있잖아?",
  ui_story_4_8_A2_dialog_content = "우린 싸움을 좋아하지 않아. 그리고 직접 싸울 능력도 없어.",
  ui_story_4_8_27_dialog_content = "우린 그저 암귀의 승리를 바라지 않을 뿐이야.",
  ui_story_4_8_28_dialog_content = "난 내 동족들도 한때 이런 마음으로 전투에 임했을 거라고 믿어.",
  ui_story_4_8_29_dialog_content = "싸울 능력이 없는데도 싸워야 하는 게 무섭지 않아?",
  ui_story_4_8_31_dialog_content = "알고 있어. 내 동족들도 한때 목숨을 걸고 암귀에게 맞서 싸웠고, 중요한 역할을 했어.",
  ui_story_4_8_32_dialog_content = "나도 다른 동족과 다르지 않을 거야.",
  ui_story_4_8_33_dialog_content = "네 능력은 확실히 인상적이라고 생각해.",
  ui_story_4_8_34_dialog_content = "어쩌면 이 능력이... 우리가 그런 참혹한 습격을 당했던 이유일지도 몰라.",
  ui_story_4_8_35_dialog_content = "너무 무력하다고 생각하지 않아?",
  ui_story_4_8_36_dialog_content = "아니, 난... 나만의 사명이 있으니까.",
  ui_story_4_8_37_dialog_content = "그 사명을 위해 네 목숨까지 내놓을 생각이란 거지?",
  ui_story_4_8_F1_dialog_content = "그래, 이건 나 한 사람만을 위한 싸움이 아니니까.",
  ui_story_4_8_38_dialog_content = "재미있네, 바이스. 네 파트너, 꽤나 재미있는걸.",
  ui_story_4_8_39_dialog_content = "자신이 위험에 빠져도 <color=#FFB400>다른 사람을 위해 싸운다</color>는 건가...",
  ui_story_4_8_40_dialog_content = "......",
  ui_story_4_8_41_dialog_content = "...!",
  ui_story_4_8_46_dialog_content = "라파엘, 있니?",
  ui_story_4_8_47_dialog_content = "여기 있어!",
  ui_story_4_8_48_dialog_content = "넌 우리와 함께 업타운 구역으로 가지 않아도 돼. 넌... 반대 방향으로 가는 게 좋겠어.",
  ui_story_4_8_49_dialog_content = "에엣?! 어째서?",
  ui_story_4_8_50_dialog_content = "녀석이 「업타운 구역」으로 도망치는 건, 죽으러 가는 거나 다름없잖아?",
  ui_story_4_8_51_dialog_content = "그렇다는 건, 애초에 도주가 목적이 아니라... 오히려...",
  ui_story_4_8_52_dialog_content = "계속해서 우리의 주의를 끌려는 속셈인가?",
  ui_story_4_8_53_dialog_content = "맞아, 그래도 우린 쫓아갈 수밖에 없어.",
  ui_story_4_8_54_dialog_content = "그러니 라파엘은 반대 방향으로 가서 조사해줬으면 좋겠어. 그 근처 어딘가에 누군가가 있을 거 같단 예감이 들어...",
  ui_story_4_8_55_dialog_content = "오오오! 이해했어! 그러니까 의심스러운 사람을 찾으라는 거지? 지금 출발할게!",
  ui_story_4_8_56_dialog_content = "카렌은 정말 예리하구나. 어떤 일도 네 눈을 속일 순 없을 것 같아.",
  ui_story_4_8_57_dialog_content = "정반대야. 내겐 아직 많은 일을 정확하게 판단할 수 있는 능력은 없어.\n「입장」이라는 건 너무나도 복잡하니까...",
  ui_story_4_8_58_dialog_content = "됐어. 집중하자. 길에 새로운 벌레가 쏟아져나왔으니까, 어서 처리하자.",
  ui_story_4_12_1_dialog_content = "......",
  ui_story_4_12_2_dialog_content = "......",
  ui_story_4_12_3_dialog_content = "어... 그러니까 중대장 씨가 여기 있는 건...",
  ui_story_4_12_4_dialog_content = "하아, 두 번이나 말했지만 난 자료관의 직원을 호송하러 왔다. 믿지 못하겠다면 그들에게 물어보도록.",
  ui_story_4_12_5_dialog_content = "하지만 전에 대장님께 보고하기로는 주민들을 도우러 성 밖에 간다고...",
  ui_story_4_12_6_dialog_content = "내가 도운 주민이 자료관 사람이다. 지금 막 데려온 참이었다.",
  ui_story_4_12_7_dialog_content = "에... 그럼 손에 있는 상자는 뭔가요...? 왜 천으로 덮여 있나요?",
  ui_story_4_12_8_dialog_content = "아, 이거 말인가. 지난주에 여기에 뒀던 서류를 포장한 거다.",
  ui_story_4_12_9_dialog_content = "내용은... 주로 최근 반년간 암귀에게 희생된 주민들의... 검시 보고서다.",
  ui_story_4_12_10_dialog_content = "으엑...",
  ui_story_4_12_11_dialog_content = "치안 업무를 위해선 참고해야 하거든. 안에는 현장 사진, 시신 해부도 같은 것들이 들어있다.",
  ui_story_4_12_12_dialog_content = "...보겠나?",
  ui_story_4_12_13_dialog_content = "......",
  ui_story_4_12_14_dialog_content = "......",
  ui_story_4_12_15_dialog_content = "아하하, 아니, 됐어요.",
  ui_story_4_12_16_dialog_content = "괜찮다. 지금 상황이 심상치 않으니, 만약 조사하라는 명령을 받았다면...",
  ui_story_4_12_17_dialog_content = "으아아악, 아니에요! 저, 전 그럼 저쪽을 순찰하러 갈게요!",
  ui_story_4_12_18_dialog_content = "......",
  ui_story_4_13_1_dialog_content = "보고드립니다! 핏자국이 이곳까지 이어져 있습니다! 아무래도 이 문으로 들어간 것 같습니다!",
  ui_story_4_13_2_dialog_content = "핏자국의 간격이 짧아졌어... 속도는 느려졌고, 우리가 따라잡고 있는 거야!",
  ui_story_4_13_3_dialog_content = "서두르자, 바로 앞에 있을지도 몰라!",
  ui_story_4_13_4_dialog_content = "우와, 어느새 이렇게 멀리 왔네. 업타운 구역에 거의 다 왔어...",
  ui_story_4_13_5_dialog_content = "업타운 구역을 돌파할 수 없다는 건 저들도 알고 있겠지. 여기서 죽음을 각오하겠다는 건가.",
  ui_story_4_13_6_dialog_content = "어디 해보라지, 몇 번을 해도 결과는 같을 테니. 배신자의 결말은 변하지 않아!",
  ui_story_4_13_7_dialog_content = "언니... 조, 졸려...",
  ui_story_4_13_8_dialog_content = "자면 안 돼, 샤를... 미안, 많이 힘든 거 알고 있어...",
  ui_story_4_13_9_dialog_content = "벌써 온 건가... 정말 빠른걸. 역시... 카렌답네...",
  ui_story_4_13_10_dialog_content = "이제... 그분의 약속을 증명할 시간이야...",
  ui_story_4_13_11_dialog_content = "안녕, 스예트.",
  ui_story_4_13_12_dialog_content = "저...저흰, 궁지에 몰렸어요... 적 중에 아이테르가 있어요!",
  ui_story_4_13_13_dialog_content = "...원수는 외나무다리에서 만난다더니.",
  ui_story_4_13_14_dialog_content = "도와주세요...! 거츠더 쪽은 아직 마무리가 안 됐어요... 시간이 필요해요!",
  ui_story_4_13_15_dialog_content = "저희에게 적을 물리칠 힘을 내려주세요... 부디... 살아갈 희망을 주세요...!",
  ui_story_4_13_16_dialog_content = "그건 두 가지 요구잖니, 스예트.",
  ui_story_4_13_17_dialog_content = "...!",
  ui_story_4_13_18_dialog_content = "적을 쓰러트리고 싶니? 아니면 살고 싶니?",
  ui_story_4_14_1_dialog_content = "스예트, 샤를.",
  ui_story_4_14_3_dialog_content = "...왔구나...",
  ui_story_4_14_4_dialog_content = "언니...",
  ui_story_4_14_5_dialog_content = "스예트, 말해. <color=#FFB400>누굴 위해서 시간을 벌고 있는 거지</color>?",
  ui_story_4_14_6_dialog_content = "......",
  ui_story_4_14_7_dialog_content = "대답할 생각이 없어 보이네. 그럼 더는 봐주지 않겠어!",
  ui_story_4_14_8_dialog_content = "카렌... 당신 눈엔 우리가 독 안에 든 쥐로 보이는 모양이지?",
  ui_story_4_14_9_dialog_content = "미안하지만... 그분께서 이미 우리에게 새로운 힘을... 주셨거든...",
  ui_story_4_14_10_dialog_content = "「그분」? 설마... 슈모르?",
  ui_story_4_14_11_dialog_content = "우린... 우린 살아서... 이 썩어빠진 백야성을 보란 듯이 떠날 거야!",
  ui_story_4_14_13_dialog_content = "당신이라고 영원히 이기기만 할 순 없을 거야... 꼬마 공주님!",
  ui_story_4_14_14_dialog_content = "언... 니? 지금... 몸이...",
  ui_story_4_14_15_dialog_content = "<anim type=Shake>꺄아아아아아악!</anim>",
  ui_story_4_14_17_dialog_content = "뭐야... <color=#FFB400>하나로 융합</color>한 거야?!",
  ui_story_4_14_18_dialog_content = "아까 그 애들에게 준 거, 평범한 힘은 아니겠지.",
  ui_story_4_14_19_dialog_content = "맞아, 하지만 그건 그 애들이 원했던 거야. 적을 쓰러뜨릴 수 있는 힘 말이야.",
  ui_story_4_14_21_dialog_content = "저 피조물에 이름을 지어줄까? 너라면 뭐라고 부를 것 같아?",
  ui_story_4_14_22_dialog_content = "...재미없어, 그런 거.",
  ui_story_4_14_23_dialog_content = "<anim type=Shake>아아아아악──! 아파, 아파! 어째서, 이게 아냐! 우린──</anim>",
  ui_story_4_14_24_dialog_content = "<anim type=Shake>언니... 힘이, 넘쳐── 근데... 너무 아파...!</anim>",
  ui_story_4_14_25_dialog_content = "<anim type=Shake>드, 듣고 계신가요! 이게 대체 뭐죠? 약속했던 게 이거냐구요!</anim>",
  ui_story_4_14_26_dialog_content = "PlayerName, 뒤로 물러나... 저건 이미, 괴물의 범주를 넘어섰어...",
  ui_story_4_14_27_option_content = "두려워하지 마. 내가 있잖아.",
  ui_story_4_14_28_option_content = "집중해. 이길 수 있어.",
  ui_story_4_14_29_dialog_content = "지금 내 몸이 떨리는 건... 분노 때문이야...",
  ui_story_4_14_30_dialog_content = "대체 어떤 녀석이 「이런」 짓을 하는 거지?!",
  ui_story_4_14_31_dialog_content = "좋아. 그럼 평소처럼 부탁해, PlayerName!",
  ui_story_4_14_32_dialog_content = "<anim type=Shake>아파... 아파! 언니, 나... 너무 아파...</anim>",
  ui_story_4_14_33_dialog_content = "<anim type=Shake>샤를... 우, 우릴 죽여...</anim>",
  ui_story_4_14_35_dialog_content = "......",
  ui_story_4_14_36_dialog_content = "이건 대체 어떻게 된 거야... 「힘을 준다」는 게 대체 무슨 의미지?",
  ui_story_4_14_A1_dialog_content = "어떻게 한 건지는 모르겠지만, 어둠에 몸을 맡긴 이상... 결말은 정해져 있어.",
  ui_story_4_14_37_dialog_content = "백야의 이름으로 너희에게...",
  ui_story_4_14_38_dialog_content = "<anim type=Shake>민들레...</anim>",
  ui_story_4_14_39_dialog_content = "...?",
  ui_story_4_14_40_dialog_content = "<anim type=Shake>민들레... 난... 민들레가 돼서... 날아갈 거야...</anim>",
  ui_story_4_14_41_dialog_content = "넌 이미 엉망진창이야. 아니, 난 지금 '너'라고 해야 할지 '너희'라고 해야 할지조차 모르겠네...",
  ui_story_4_14_42_dialog_content = "<anim type=Shake>나, 난 그분의 계획을... 완수했는데...</anim>",
  ui_story_4_14_43_dialog_content = "<anim type=Shake>어째서... 약속과 다르잖아... 나의... 거츠더가 기다리고 있는데...</anim>",
  ui_story_4_14_44_dialog_content = "<anim type=Shake>그분께선... 대체 왜...</anim>",
  ui_story_4_14_45_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_4_14_46_dialog_content = "또, 또 폭발이야?!",
  ui_story_4_14_47_dialog_content = "보고할게... <color=#FFB400>자료관</color>! 자료관 쪽에서 폭발이 일어났어! 미, 미안해...",
  ui_story_4_14_48_dialog_content = "알겠어! 그런데 라파엘 네가 왜 사과하는데?",
  ui_story_4_14_49_dialog_content = "<anim type=Shake>히히... 키, 히힉... 드디어, 당신의 패배야... 꼬마 공주님...</anim>",
  ui_story_4_14_50_dialog_content = "<anim type=Shake>거, 거츠더... 나의... 거츠더... 꼭 살아남아 해...</anim>",
  ui_story_4_14_53_dialog_content = "비록 적이지만... 저런 모습은 보고 있기가 너무 힘들어.",
  ui_story_4_14_54_dialog_content = "<color=#e8d9bb>자료관 밖</color>",
  ui_story_4_14_55_dialog_content = "...그러니까, 그래서 그 반역자를 그냥 지나쳤다는 말이지?",
  ui_story_4_14_56_dialog_content = "...미안해. 카렌 언니... 그때 내가...",
  ui_story_4_14_57_dialog_content = "<color=#FFB400>도시 전체를 수색해 거츠더를 체포해라</color>. 지금, 당장.",
  ui_story_4_14_58_dialog_content = "...네, 알겠습니다!",
  ui_story_4_14_59_dialog_content = "치안을 망가트리고 도시를 멋대로 파괴하다니... 이런 악행은 용납할 수 없어...",
  ui_story_4_14_60_dialog_content = "그 녀석이 설마 자료관에서 그걸 훔친 건 아니겠지...",
  ui_story_4_14_61_dialog_content = "「싱크탱크 컴포넌트」...",
  ui_story_4_14_62_dialog_content = "도둑맞은 데다가, 어떤 모양인지도 못 봤어... 그야말로 실패네...",
  ui_story_4_14_63_dialog_content = "내게도 책임이 있어. 아니, 내가 책임을 져야겠지.",
  ui_story_4_14_64_dialog_content = "카렌, 정말 미안해...",
  ui_story_4_14_65_dialog_content = "암귀는 반격해 올 거야, 바이스.",
  ui_story_4_14_66_dialog_content = "오히려 이번 위기를 「불러온」 게 너랑 PlayerName인 점이 다행이라고 생각해.",
  ui_story_4_14_67_dialog_content = "다른 사람이었다면 더 큰 피해를 보았을지도 모르니까.",
  ui_story_4_14_68_dialog_content = "지금 칭찬하는 거야, 탓하는 거야...?",
  ui_story_4_14_69_dialog_content = "칭찬이겠지...?",
  ui_story_4_14_70_dialog_content = "호위대장으로서 난 책무를 다하지 못했어... 반드시 성주 전하께 처벌을 받아야 해.",
  ui_story_4_14_71_dialog_content = "그래도 아버지니까 용서해 주시지 않을까?",
  ui_story_4_14_72_dialog_content = "...아무래도 넌 백야성과 그분에 대해 전혀 모르는 모양이네.",
  ui_story_4_14_73_dialog_content = "그럼 우리도 일루미나로 돌아가서 이후의 계획을 논의해봐야겠어.",
  ui_story_4_14_74_dialog_content = "옛말에 「월요일을 놓쳐서 고민하고 있다면, 화요일도 놓칠 것이다」라고 했거든.",
  ui_story_4_14_75_dialog_content = "그런 말이 정말 있다고...?",
  ui_story_4_14_76_dialog_content = "...넌 정말로 낙천적이네, 바이스.",
  ui_story_4_14_77_dialog_content = "어차피 이미 벌어진 일인데, 낙담하고 있어봤자 아무 의미도 없잖아!",
  ui_story_4_14_78_dialog_content = "그럼 나도 업타운 구역으로 가서 성주 전하께 보고해야겠네. 너흰 조심해서 돌아가.",
  ui_story_4_14_79_dialog_content = "그리고 PlayerName... 아마 우리 다시 만나게 될 거야.",
  ui_story_4_14_80_dialog_content = "<color=#e8d9bb>같은 시간, 어딘가</color>",
  ui_story_4_14_81_dialog_content = "그 자매들, 죽어버렸어.",
  ui_story_4_14_82_dialog_content = "...예상했던 거 아냐?",
  ui_story_4_14_83_dialog_content = "두 가지 소식이 있어. 우선 「싱크탱크 컴포넌트」는 손에 넣었어. 그리고...",
  ui_story_4_14_84_dialog_content = "지난번 그 아이테르가 또 나타났어.",
  ui_story_4_14_85_dialog_content = "PlayerName, 그런 이름이었던 거로 기억하는데.",
  ui_story_4_14_86_dialog_content = "역시 동족을 잊지 못하는 모양이네.",
  ui_story_4_14_90_dialog_content = "...다시 한번 말하지만, 난 이미 그따위 하등 생물이 아니라고!",
  ui_story_4_14_91_dialog_content = "오히려 네 부하들이 멍청하고 꾸물거려서 계획을 전부 망칠 뻔했잖아!",
  ui_story_4_14_92_dialog_content = "다음 부품은 내가 직접 찾겠어! 날 가로막는 녀석은... 그 누구라 해도 갈기갈기 찢어줄 테니까.",
  ui_story_4_14_93_dialog_content = "컴포넌트는? 얼른 이리 내! 거츠더!",
  ui_story_4_14_95_dialog_content = "스예트... 스예트... 그, 그럴 수가!",
  ui_story_4_14_96_dialog_content = "약속했는데... 나와 함께 떠나기로 약속했는데... 함께 자유를 얻어서...",
  ui_story_4_14_97_dialog_content = "대체 무슨 일이 일어난 거야...?!",
  ui_story_4_14_98_dialog_content = "거기서 혼자 중얼거리고 있지 말라고! 정말 한심하기 짝이 없네!",
  ui_story_4_14_99_dialog_content = "그 둘은 백야성 호위대한테 당했어.\n네게 우리의 명령을 완수할 시간이 남아 있다는 걸 다행으로 여겨야 할 거야!",
  ui_story_4_14_100_dialog_content = "...카렌...!",
  ui_story_4_14_101_dialog_content = "좋은 표정이야, 거츠더. 수배령의 모습과는 전혀 다른 사람이 됐는걸.",
  ui_story_4_14_102_dialog_content = "피에는 피로 갚아주마...!",
  ui_story_5_1_1_dialog_content = "카렌 대장, 그건 그대의 선택인가?",
  ui_story_5_1_2_dialog_content = "네, 전하. 그 아이테르를 관찰할 필요가 있다고 생각합니다. 그는... 무척 특별합니다.",
  ui_story_5_1_3_dialog_content = "그대의 행동에 간섭하진 않겠다. 허나 그대가 자신의 입장을 잘 인식하고 있었으면 좋겠군, 호위대장.",
  ui_story_5_1_4_dialog_content = "네, 전하. 만물은 백야 아래에.",
  ui_story_5_1_5_dialog_content = "상황은 알겠습니다. 30분 후에 군단장 정례 회의가 열리니, 회의에서 상세한 보고를 올리도록 하세요.",
  ui_story_5_1_6_dialog_content = "하지만 구체적으로 어떻게 할지는 협의 결과에 달렸습니다.",
  ui_story_5_1_7_dialog_content = "...그럼 첫 번째 의제는 여기까지입니다.",
  ui_story_5_1_A1_dialog_content = "방금 언급한 좌표 근처의 암귀 활동 조사는 군단장 세 분께 맡기겠어요.",
  ui_story_5_1_8_dialog_content = "<size=30>흠흠, PlayerName, 방금 저분은 제1군단의 <color=#FFB400>시로나</color> 군단장님이야.</size>",
  ui_story_5_1_A2_dialog_content = "<size=30>그리고 이분은 제2군단의 <color=#FFB400>바튼</color> 군단장님인데, 모두 군부의 대표적인 인물이라고 할 수 있어.</size>",
  ui_story_5_1_9_dialog_content = "알겠어. 최근 자난 근처에도 수상한 고위 암귀가 나타났어. 좋은 징조는 아니야.",
  ui_story_5_1_10_dialog_content = "세 분을 소집한 것도 그런 이유 때문이에요.\n최대한 경계를 유지해 주세요. 아주 사소한 위협도 놓쳐서는 안 돼요.",
  ui_story_5_1_11_dialog_content = "이 두 녀석은 뭐지?",
  ui_story_5_1_12_dialog_content = "그 둘이 바로 오늘의 두 번째 의제예요. 히이로, 상황 설명을 부탁드릴게요.",
  ui_story_5_1_13_dialog_content = "콜로서스를 조종할 수 있는 남겨진 아이테르라...",
  ui_story_5_1_14_dialog_content = "......",
  ui_story_5_1_15_option_content = "왜, 왜 다들 날 보는 거야?",
  ui_story_5_1_16_dialog_content = "얼굴 빨개진 거 아니야?",
  ui_story_5_1_X16_dialog_content = "역시 아직 꼬맹이로군.",
  ui_story_5_1_17_option_content = "그럼 지금 바로 보여드릴까요?",
  ui_story_5_1_18_dialog_content = "여기서 콜로서스를 조종하면 지붕이 무너질 거라고.",
  ui_story_5_1_19_dialog_content = "역시 극도로 위험한 인물이로군. 애송이, 넌 그 슈모르와 무슨 관계지?",
  ui_story_5_1_20_dialog_content = "군단장님! PlayerName 이 친구는 슈모르와 달라요!",
  ui_story_5_1_21_dialog_content = "긴장할 거 없어. 전투 능력도 없고 오염되지도 않은 아이테르라면,\n암귀에게 투항한 그 녀석들과는 확실히 다르니까.",
  ui_story_5_1_22_dialog_content = "지금까지 살아남은 아이테르가 있을 줄은 몰랐어. 그 재앙으로 이미 다 죽은 줄 알았거든.",
  ui_story_5_1_23_dialog_content = "본론으로 돌아가지. 너희들이 말한 슈모르 그 녀석은 세 개의 부품에 대해 얼마나 파악하고 있는 거냐?",
  ui_story_5_1_24_dialog_content = "단서가 하나도 없어요. 나머지 두 부품을 찾는 방법이 「싱크탱크 컴포넌트」 안에 있다 보니...",
  ui_story_5_1_25_dialog_content = "그리고 슈모르는 이미 「싱크탱크 컴포넌트」를 손에 넣었을 거예요. 상황이 좋지 않아요.",
  ui_story_5_1_26_dialog_content = "지금 가장 급한 건 저들보다 먼저 두 부품을 찾아내는 거예요!",
  ui_story_5_1_27_dialog_content = "군단장님들께서 도움을 주셨으면 해요. 아니면... 이 일에 직접 개입해 주세요.",
  ui_story_5_1_28_dialog_content = "일루미나 군단의 최우선 임무는 전선과 본부 자난성을 지키는 거야.",
  ui_story_5_1_29_dialog_content = "최근 암귀의 습격이 갈수록 빈번해지고 있어.\n일상적인 경계 임무만으로도 이미 포화 상태야. 아마 인원 차출은 어려울 거야.",
  ui_story_5_1_30_dialog_content = "내가 해줄 말은 항상 똑같다. 대원수의 명이 없는 한, 그 누구도 나와 내 군단을 지휘할 수 없다.",
  ui_story_5_1_31_dialog_content = "히이로는요? 바이스의 상관으로서 어떻게 생각하세요?",
  ui_story_5_1_32_dialog_content = "일루미나의 군인은 명령에 복종할 뿐입니다.",
  ui_story_5_1_33_dialog_content = "알겠어요.",
  ui_story_5_1_34_dialog_content = "미안해요, PlayerName. 확실한 명령이 내려오기 전까지 우린 당신들을 도와줄 수 없어요.",
  ui_story_5_1_35_dialog_content = "PlayerName, 뭔가 느껴져?",
  ui_story_5_1_36_dialog_content = "아무것도. 뭔가 이상한 느낌은 전혀 들지 않아.",
  ui_story_5_1_37_dialog_content = "너마저 느껴지는 게 없다니, 어쩌면 좋지?",
  ui_story_5_1_38_dialog_content = "멘델슨은 죽기 전에 슈모르가 반드시 다음 부품을 찾으러 갈 거라고 말했어.",
  ui_story_5_1_39_dialog_content = "슈모르의 흔적을 찾아낼 수 있다면 그 단서를 따라 다른 실마리를 잡을 수 있을지도 몰라.",
  ui_story_5_1_40_dialog_content = "하지만 아무리 눈을 씻고 찾아봐도 슈모르는 보이질 않는걸.\n그럼 정말 이대로 기다리는 수밖에 없단 말이야?",
  ui_story_5_1_41_dialog_content = "흐아아암, 에엣~ 왜 다들 풀이 죽어 있다냥? 회의가 순조롭지 않았나 봐?",
  ui_story_5_1_42_dialog_content = "<color=#FFB400>필리시</color> 선배!",
  ui_story_5_1_43_dialog_content = "아아, 그렇게 흥분할 거 없어. 필리시는 선물을 주려고 왔을 뿐이다냥. 자, 받아.",
  ui_story_5_1_44_dialog_content = "<color=#FFB400>《무명인-13호 콜로서스 유적 연구 보고서》</color>?",
  ui_story_5_1_45_dialog_content = "쓰느라 시간이 엄청 걸렸다구!",
  ui_story_5_1_46_dialog_content = "비비안이 필리시한테 무척 어려운 임무를 줘서 피곤해... 너무 강행군인 일정이다냥.",
  ui_story_5_1_47_dialog_content = "「이름 없는 콜로서스가 추락한 곳에서 스스로 성장하는 컴포넌트가 발견되었다.\n이는 성장형 콜로서스 특유의...」",
  ui_story_5_1_48_dialog_content = "「핵심은 유적 깊은 곳에 잠들어 있다. 봉인을 해제하는 방법은\n아직 밝혀지지 않았으며, 계속해서 탐색 중이다...」",
  ui_story_5_1_49_dialog_content = "이건... 설마 「<color=#FFB400>자생 유닛</color>」을 말하는 걸까요?!",
  ui_story_5_1_50_dialog_content = "가능성이 얼마나 될진 모르지~ 하지만 지금은 그 가능성에 기대를 거는 수밖에 없다냥.",
  ui_story_5_1_51_dialog_content = "아, 맞다. 비비안이 전해주라고 한 말이 있다냥...",
  ui_story_5_1_52_dialog_content = "비록 지금 군단장들은 도움을 줄 수 없지만, 유적 쪽에도 일루미나 사람이 있을 거랬다냥!",
  ui_story_5_1_53_dialog_content = "하~암. 필리시는 더는 못 버티겠어. 자러 가겠다냥. 그럼 꿈에서 응원해 줄게!",
  ui_story_5_1_54_dialog_content = "필리시 선배는 여전하네.",
  ui_story_5_1_55_option_content = "콜로서스에 저런 동료가 있다면...",
  ui_story_5_1_56_dialog_content = "선배는 일루미나의 정보부장이니까, 이 정도로 도움을 준 것만으로도 이미 충분해.",
  ui_story_5_1_57_dialog_content = "필리시 선배가 우리 작전에 직접 참여해주면, 적어도 정보 수집에 있어서만큼은 확실할 텐데 말이야.",
  ui_story_5_1_58_dialog_content = "하지만 금방이라도 잠들 것 같던데.",
  ui_story_5_1_59_dialog_content = "아마 일 때문에 스트레스가 너무 심해서 그럴 거야...",
  ui_story_5_1_60_option_content = "사실 나도 엄청 졸려... 그럼 우리도 좀 쉬는 게...",
  ui_story_5_1_61_dialog_content = "그럼 지금 잠깐 쉬자.",
  ui_story_5_1_A4_dialog_content = "안 돼! 정신 차려, PlayerName! 이 문제들만 해결하고 나면...",
  ui_story_5_1_62_dialog_content = "내가 자난에서 가장 큰 도서관에 데려가서 제대로 쉬게 해 줄게!",
  ui_story_5_1_63_dialog_content = "...놀이공원이나 카페를 가는 게 맞지 않아? 일이 끝났는데도 공부를 하라니 너무 가혹하잖아.",
  ui_story_5_1_64_dialog_content = "어쨌든, 남은 시간이 별로 없어! 반드시 슈모르보다 먼저 다음 부품을 찾아내야 해!",
  ui_story_5_1_65_dialog_content = "콜로서스를 가동하러 가자!",
  ui_story_5_1_66_dialog_content = "기합이 잔뜩 들어간 걸 보니, 보고도 마치고 방법도 찾은 모양이네.",
  ui_story_5_1_67_dialog_content = "카렌?!",
  ui_story_5_1_68_dialog_content = "놀랄 거 없어. 성주님께 특별 파견을 신청해 슈모르의 일에 대한 조사의 전권을 맡게 됐으니까.",
  ui_story_5_1_69_dialog_content = "백야성을 위협하는 모든 행위는 엄벌을 받게 될 거야, 암귀와 결탁하는 자는 결코 용서치 않아.",
  ui_story_5_1_70_dialog_content = "<size=30>카렌은... 정말 엄청나게 냉정한 것 같네. 조심하는 게 좋겠어...</size>",
  ui_story_5_1_71_dialog_content = "뭐라고 했지?",
  ui_story_5_1_72_dialog_content = "응? 내가 무슨 말 했어?!",
  ui_story_5_1_73_dialog_content = "스스로 결백하다면 날 두려워할 필요는 없어.",
  ui_story_5_1_A5_dialog_content = "날 두려워해야 하는 건 스예트, 거츠더 일파나 그 배후의 녀석이겠지.",
  ui_story_5_1_74_dialog_content = "거츠더...라면... 전에 스예트가 혼란을 일으킨 틈에 도망가려고 했던 녀석이지?",
  ui_story_5_1_75_dialog_content = "그래. 그 이클립스에 빌붙은 배신자는 자신이 그림자 속에 숨어 비호를 받을 수 있을 거라 생각하겠지.",
  ui_story_5_1_76_dialog_content = "하지만 솔라드 가문의 날카로운 검은 반드시 배신자의 심장을 꿰뚫을 거야. 세상 어디에 있든지 말이야.",
  ui_story_5_1_77_dialog_content = "그럼 잡담은 여기까지 하고. 이제 어디로 갈 거지?",
  ui_story_5_1_78_dialog_content = "무명인-13호 콜로서스 유적으로 갈 거야. 호위대장은 콜로서스 유적에 가본 적 있어?",
  ui_story_5_1_79_dialog_content = "그게 중요한가? ...나는 과거의 산물에 빠지지 않아. 내가 지켜야 할 것들은 눈앞에 있으니까.",
  ui_story_5_1_80_dialog_content = "뭐, 그것보다... PlayerName, 늦지 않게 정보를 제공해 준 점은 감사를 표할게.",
  ui_story_5_1_81_dialog_content = "이번 작전은 나도 동행할 거야. 내 창에 맹세하건대,\n절대 배신자가 그 뜻을 이루도록 내버려 두지 않겠어!",
  ui_story_5_2_1_dialog_content = "(뭔가 소리가 들리는 것 같아. 슬프고... 그리운 기분이 드는 소리가...)",
  ui_story_5_2_2_dialog_content = "잃어버린 고향을 위해 꽃을 바칩니다. 한때 바람결에 살랑이던 나무가 우거진 곳...",
  ui_story_5_2_3_dialog_content = "사라진 동족을 위해 오로라를 기도합니다. 빛이 너그러이 모든 생명을 비추기를...",
  ui_story_5_2_4_dialog_content = "우리의 고통은 시간과 함께 흘러가고, 기억이 먼지로 변해, 끝내 공허로 돌아갑니다...",
  ui_story_5_2_5_dialog_content = "태양은 변함없이 떠오르겠지만, 우린 깊은 잠 가운데 영원한 안식을 맞이할 것입니다.",
  ui_story_5_2_6_dialog_content = "선생님... 이렇게 하면 되나요? 하지만 전 아직도 무서워요...",
  ui_story_5_2_7_dialog_content = "제가 심은 꽃은 아직 싹을 틔우지 못했어요. 꽃이 피는 걸 보고 싶은걸요.",
  ui_story_5_2_8_dialog_content = "두려워하지 말거라, 얘야. 눈을 감으렴. 죽음은 찰나일 뿐이란다. 선생님이 계속 네 곁에 있을 거다.",
  ui_story_5_2_9_dialog_content = "(내... <color=#FFB400>동족</color>? 이건 현실일까, 환상일까...)",
  ui_story_5_2_10_dialog_content = "시시한 죽음의 기도네. 자, 난 분명 너희에게 선택지를 줬어.",
  ui_story_5_2_11_dialog_content = "목적지 상공에 도착했어. PlayerName, 괜찮아?",
  ui_story_5_2_12_option_content = "바이스...",
  ui_story_5_2_13_dialog_content = "무서워하지 마, 내가 있잖아. 뭔가 느껴지는 거야?",
  ui_story_5_2_14_dialog_content = "환영이 보여... 대체 뭐지?",
  ui_story_5_2_15_dialog_content = "어쩌면 죽은 아이테르가 이 유적에 남긴 강한 집념일지도 모릅니다.",
  ui_story_5_2_16_dialog_content = "... 죽은 아이테르... 그렇구나. 그래서 그들은 멘델슨처럼 나와 대화하지 못하는 거구나.",
  ui_story_5_2_17_dialog_content = "그렇습니다. 그들의 시신은 이미 풍화되어 먼지로 변했을 것입니다.",
  ui_story_5_2_18_option_content = "화, 환영이... 더 많이 보이는 것 같아.",
  ui_story_5_2_19_dialog_content = "PlayerName, 누군가의 의식과 감응한 거야? 설마 이 유적에 생존자가 있는 걸까?",
  ui_story_5_2_A1_dialog_content = "이곳에는 생존자의 기척이 없습니다. 당신이 본 장면은 환영일 것입니다...",
  ui_story_5_2_20_dialog_content = "슬픔과 절망의 허상... 어쩌면 죽은 아이테르들이 남긴 의식의 잔재일지도 모릅니다...",
  ui_story_5_2_21_dialog_content = "맞아. 저건 동족들의 사념일 거야.",
  ui_story_5_2_A2_dialog_content = "우릴 내려줘, 스카이워커.",
  ui_story_5_2_24_dialog_content = "도착했어, <color=#FFB400>무명인-13호 유적</color>이야.",
  ui_story_5_2_25_dialog_content = "「최초로 이곳을 발견한 자는 눈앞에 잠들어 있는 이름 없는 콜로서스의 모습에 놀라며...」",
  ui_story_5_2_26_dialog_content = "「콜로서스가 하늘에서 떨어져 잠든 별이라고 생각했다.」",
  ui_story_5_2_27_dialog_content = "「콜로서스에는 이미 그 어떤 생명의 흔적도 없었다. 시간의 흐름에 따라 이곳에는 공허만이 남아 있었다.」",
  ui_story_5_2_28_dialog_content = "이 스산한 분위기... 이런 곳은 처음이네.",
  ui_story_5_2_29_dialog_content = "헤븐즈 밸리의 재난에 관한 건 예전에 자료실의 책에서 본 적 있어.",
  ui_story_5_2_30_dialog_content = "「암귀가 밀물처럼 밀려와 헤븐즈 밸리의 후예들을 덮쳤고,\n암귀의 추종자 외에는 그 누구도 살아남지 못했다.」",
  ui_story_5_2_31_dialog_content = "하지만 이렇게 가까이에서 직접 보니, 이 모습은 생각했던 것보다... 마음이 아프네...",
  ui_story_5_2_A3_dialog_content = "......",
  ui_story_5_2_A4_dialog_content = "바이스, 너도 많은 걸 느꼈겠지?",
  ui_story_5_2_A5_dialog_content = "응, 내가 느끼는 게 PlayerName처럼 강렬하진 않겠지만, 나도... 슬픔이 느껴져.",
  ui_story_5_2_34_dialog_content = "PlayerName, 넌 어떻게 살아남은 거지?",
  ui_story_5_2_35_dialog_content = "재앙이 벌어졌을 때, 스카이워커호가 명령에 따라 아직 아기였던 날 데리고 도망쳤다는 것밖에 몰라.",
  ui_story_5_2_A6_dialog_content = "그 후로 17년이라는 시간을 지하에서 생활했어. 얼마 전까지 말이야.",
  ui_story_5_2_36_dialog_content = "그러다 바이스가 날 바깥으로 이끌어 준 거야...\n아쉽게도 바깥세상이 지하보다 더 좋은 것 같지는 않지만.",
  ui_story_5_2_37_dialog_content = "난... 다시 내 종족과... 멘델슨과 이야기를 나누고 싶어...",
  ui_story_5_2_38_dialog_content = "PlayerName...",
  ui_story_5_2_39_dialog_content = "아이테르의 비극이 다시 되풀이돼선 안 돼...",
  ui_story_5_2_40_dialog_content = "물론이지. 그 어떤 종족도 그런 비극을 맞이해선 안 돼.",
  ui_story_5_2_41_dialog_content = "저길 봐, 중간에 있는 가장 큰 콜로서스가 자료에 나와 있는 우리의 목적지겠지?",
  ui_story_5_2_A7_dialog_content = "자료에 따르면 「<color=#FFB400>컬쳐리스트</color>」라는 이름인 것 같아. 유일하게 스스로 성장할 수 있는 콜로서스라고 해.",
  ui_story_5_2_42_dialog_content = "「<color=#FFB400>자생 유닛</color>」은 아마 저기에 있을 거야.",
  ui_story_5_2_43_dialog_content = "콜로서스가 이렇게 망가져 버렸는데 그게 무사히 남아 있을까?",
  ui_story_5_2_44_dialog_content = "자료에 적힌 정보는 여기까지야.",
  ui_story_5_2_45_dialog_content = "들어가서 살펴보자. 분명히 뭔가 단서가 있을 거야.",
  ui_story_5_2_46_dialog_content = "PlayerName, 알고 있지? 이건 무척 위험한 일이야. 멘델슨 때처럼...",
  ui_story_5_2_F1_dialog_content = "알고 있어. 들어가면 나도 같은 위험에 처하고, 그 사람처럼 사라질 수도 있겠지.",
  ui_story_5_2_47_dialog_content = "난 지금까지도 멘델슨이 사라지는 모습이 눈앞에 생생해. 그를 구하지 못했다는 무력감도...",
  ui_story_5_2_48_dialog_content = "만약 도저히 감당할 수 없다면... 지금이라도 포기해도 괜찮아.",
  ui_story_5_2_F2_dialog_content = "바이스, 나도 무서워. 하지만 내게 다른 선택지는 없어.",
  ui_story_5_2_F3_dialog_content = "난 이미 생각을 정했어... 어떤 위험이 닥치든, 앞으로 무슨 일이 벌어지든, 난 물러서지 않을 거야.",
  ui_story_5_2_49_dialog_content = "알겠어... 그럼 나도 너 혼자서 이 모든 걸 마주하도록 두진 않을게.\n어떤 상황이 닥쳐도 난 네 곁에 있을 테니까.",
  ui_story_5_2_A8_dialog_content = "<color=#e8d9bb>유적 내부</color>",
  ui_story_5_2_50_dialog_content = "기본 모듈은 거의 다 망가져 버렸잖아. 곤란한걸.",
  ui_story_5_2_51_dialog_content = "이곳의 코어 부품을 꺼내려면 아무래도 콜로서스를 다시 가동시켜야 할 것 같네.",
  ui_story_5_2_52_dialog_content = "이 목소리는...",
  ui_story_5_2_53_option_content = "설마... 슈모르!?",
  ui_story_5_2_54_dialog_content = "아, 아니. <color=#FFB400>그로누</color> 선배야!",
  ui_story_5_2_55_option_content = "일루미나의 동료야?",
  ui_story_5_2_56_dialog_content = "응! <color=#FFB400>그로누</color> 선배야.",
  ui_story_5_2_57_dialog_content = "선배는 일루미나 과학기술부의 연구원장이야. 콜로서스와 루미나의 힘에 대해 심층적인 연구를 하고 있어.",
  ui_story_5_2_58_dialog_content = "선배!",
  ui_story_5_2_59_dialog_content = "바이스?! 이럴 때 날 도와줄 파티원이 나타날 줄은 몰랐는걸~",
  ui_story_5_2_60_dialog_content = "필리시가 말한 사람이 너였구나~",
  ui_story_5_2_61_dialog_content = "그나저나 필리시 녀석, 무슨 마취라도 당한 것처럼 말하다 말고 잠들었지 뭐야.",
  ui_story_5_2_62_dialog_content = "나 혼자 얼마나 당황했다고! 정말 상습 탈주자답다니까! 그래도 행운의 여신은 내 편인걸~",
  ui_story_5_2_63_dialog_content = "맞다. 넌 「완전판」 콜로서스를 가지고 있다면서?! 정말 신기하네!\n그러니까 그 콜로서스는 모든 콘텐츠가 다 있다는 얘기잖아!",
  ui_story_5_2_64_dialog_content = "<size=45>그럼 나도 좀 플레이하게 해 줘!</size>",
  ui_story_5_2_65_dialog_content = "뭐?",
  ui_story_5_2_66_dialog_content = "크흠, 내가 너무 흥분했나 봐. 그럼 일단 「메인 퀘스트」로 돌아가 볼까!",
  ui_story_5_2_67_dialog_content = "그로누 선배는 다른 건 다 괜찮은데 말하는 방식이 조금 이상해서 알아듣기 힘들어.",
  ui_story_5_2_68_dialog_content = "어쩌면 무언가에 너무 빠져든 후유증일지도...",
  ui_story_5_2_69_dialog_content = "그로누 선배, 여기 혼자 있었던 거예요?",
  ui_story_5_2_70_dialog_content = "맞아! 이 콜로서스는 파손이 너무 심해서 조사가 쉽지 않아.\n그러니까 서브 퀘스트 정도밖에 안 되는 셈이야.",
  ui_story_5_2_71_dialog_content = "근데 왠지 이 안에 우리가 아직 제대로 조사하지 않은 게 있는 것 같아.",
  ui_story_5_2_72_dialog_content = "게다가 서브 퀘스트를 전부 깨는 것도 게이머의 기본 소양이잖아?\n그래서 비비안한테 며칠 휴가를 내고 다시 조사해보러 왔어.",
  ui_story_5_2_73_dialog_content = "참, 너흰 이곳에... 「<color=#FFB400>자생 유닛</color>」을 찾으러 온 거지?",
  ui_story_5_2_74_dialog_content = "맞아요. 조사 중에 뭔가 발견하신 게 있나요?",
  ui_story_5_2_75_dialog_content = "이 콜로서스에 그런 성장형 부품이 있는 건 확실하지만, 단순히 힘만 가지고는 빼낼 수 없어.",
  ui_story_5_2_77_dialog_content = "콜로서스는 고대 최첨단 과학기술의 결정체야. 현재 일루미나의 기술 수준으로는 완전한 분석이 불가능해.",
  ui_story_5_2_78_dialog_content = "다른 방법은 없나요?",
  ui_story_5_2_79_dialog_content = "방법? 없는 건 아니야.",
  ui_story_5_2_80_dialog_content = "네가 바로 필리시가 말했던 <color=#FFB400>「살아남은 아이테르」</color>인 거지? 기본 칭호도 있고 꼭 주인공 같네.",
  ui_story_5_2_81_dialog_content = "완제 아이테르가 있다면 이 거대한 녀석을 다시 가동해볼 수도 있어.",
  ui_story_5_2_82_dialog_content = "그럼 시간이 없으니 어서...",
  ui_story_5_2_83_dialog_content = "<anim type=Shake>크에엑!</anim>",
  ui_story_5_2_84_dialog_content = "방해하는 녀석이 나타났네. 아무래도 골칫거리부터 모두 없앤 뒤에 일을 시작할 수 있겠어.",
  ui_story_5_2_A9_dialog_content = "그럼 서둘러 처리하자!",
  ui_story_5_2_85_dialog_content = "두 번째 부품인 「자생 유닛」이 있는 곳, 분명 네 마음에 들 거야...",
  ui_story_5_2_86_dialog_content = "어떤 대단한 곳인가 했더니, 벌레들이 묻힌 쓰레기장이잖아.",
  ui_story_5_2_87_dialog_content = "이 죽어버린 「약자」들한테 내가 원하는 부품이 있다고? 설마 내가 진작에 망가트려 버린 건 아니겠지?",
  ui_story_5_2_88_dialog_content = "아아! 짜증 나네. <color=#FFB400>그 여자</color>, 날 놀리는 거야?! 난 이 약해빠진 녀석들하곤 다르다고 했잖아!",
  ui_story_5_2_89_dialog_content = "약자라면 찢기고 짓밟히고 산산조각이 나는 게 당연하다고!",
  ui_story_5_2_90_dialog_content = "젠장, 그 여자가 날 돕고 있는 건 알지만, 이 참을 수 없는 느낌은 도저히 가시질 않잖아.",
  ui_story_5_2_91_dialog_content = "그 쓸모없는 암귀들, 지난번에 문제가 생길 뻔하지만 않았으면 내가 직접 나설 필요도 없었을 텐데.",
  ui_story_5_2_92_dialog_content = "그리고 그 아이테르... 흥, 그 녀석이 나타나는 건 조금 기대되긴 하네...",
  ui_story_5_3_1_dialog_content = "콜로서스 내부도 손상이 정말 심각하네요... 길이 전혀 보이질 않아요. 방향은 맞게 가고 있는 걸까요?",
  ui_story_5_3_2_dialog_content = "걱정 마. 난 프로잖아. 함교의 위치는 이미 완벽하게 파악했어. 바로 전방 200m에 있어!",
  ui_story_5_3_3_dialog_content = "나처럼 방향 감각이 뛰어난 사람한테는 아주 쉬운 일이라니까.",
  ui_story_5_3_4_dialog_content = "무슨 소리지?",
  ui_story_5_3_5_dialog_content = "이 근처는 아닌 것 같아.",
  ui_story_5_3_6_dialog_content = "뭔가 음산한 느낌이 드는데...",
  ui_story_5_3_8_dialog_content = "PlayerName, 왜 그래? 괜찮아?",
  ui_story_5_3_9_dialog_content = "고위 암귀보다 훨씬 더 강렬한 기운이 느껴져! 어쩌면... 슈모르일지도 몰라!",
  ui_story_5_3_10_dialog_content = "진정해. 계획대로 계속 움직이자.",
  ui_story_5_3_11_dialog_content = "녀석이 정말 왔다면, 이곳에서 처리하면 돼.",
  ui_story_5_3_12_dialog_content = "하지만...",
  ui_story_5_3_13_dialog_content = "예외는 없어. 녀석은 선을 넘었어. 자신의 행동에 대한 책임을 지게 만들겠어.",
  ui_story_5_3_A1_dialog_content = "계속 가자. 앞에 아직 더 많은 암귀가 우릴 기다리고 있어.",
  ui_story_5_3_14_dialog_content = "익숙한 기운... 흐음, 설마 진짜로 그 녀석이 온 건가?",
  ui_story_5_3_16_dialog_content = "실력도 별볼일 없는 약자 주제에, 꽤나 끈질기다니까.",
  ui_story_5_3_17_dialog_content = "멘델슨이 죽고 나니, 이번엔 PlayerName인가? 부품을 지키려고 정말 애를 쓰고 있네. 후후.",
  ui_story_5_3_18_dialog_content = "난 이미 경고했어. 내가 선택한 길만이 올바른 길이라고...",
  ui_story_5_3_A2_dialog_content = "칼을 들고 일어서야만 자신의 운명을 개척할 수 있어. 아니면... 영원히 불쌍한 사냥감이 될 뿐이야.",
  ui_story_5_3_A3_dialog_content = "하찮은 녀석들! 루미나의 기운을 따라서 손님 마중이나 나가 봐!\n우선 녀석들한테 준비 운동이라도 시켜 주라고!",
  ui_story_5_3_A4_dialog_content = "갑자기 이번 전투에 아주 살짝 기대가 되기 시작되는걸.",
  ui_story_5_3_A5_dialog_content = "『알겠습니다... 공격이다...!』",
  ui_story_5_7_A14_dialog_content = "목적지... 도착! 이곳이 바로 이 콜로서스의 함교야!",
  ui_story_5_7_A15_dialog_content = "암귀 녀석들, 정말 끈질기네... 경계를 늦춰선 안 돼!",
  ui_story_5_7_A16_dialog_content = "전에도 아~주 오랫동안 연구했지만, 「자생 유닛」을 함교에서 꺼낼 방법이 없었어. 진행이 막힌 거지.",
  ui_story_5_7_A17_dialog_content = "그럼 여기부터는 너한테 부탁할게! 아이테르라면 콜로서스를 가동시킬 수 있겠지!",
  ui_story_5_7_A18_dialog_content = "응, 최선을 다할게.",
  ui_story_5_7_1_dialog_content = "콜로서스를 가동하려면 먼저 에너지 비축 상태부터 확인해야 해.",
  ui_story_5_7_2_dialog_content = "이 콜로서스는 심각한 손상을 입긴 했지만, 에너지가 꽤 많이 남아 있으니까 다시 가동할 수 있을 거야.",
  ui_story_5_7_3_dialog_content = "그다음은 콜로서스와의 감응이야. 그래야만 컨트롤러를 가동할 수 있어.\n그리고 그걸 할 수 있는 건 오직 아이테르뿐이야.",
  ui_story_5_7_4_dialog_content = "세 번째는 컨트롤러 조종인데...",
  ui_story_5_7_5_dialog_content = "그래, 바로 그렇게. 잘했다.",
  ui_story_5_7_6_dialog_content = "목소리...? 누구야?",
  ui_story_5_7_7_dialog_content = "정말 기쁘구나... 정말... 아주 오랫동안 우리의 동족, 우리의 후예를 보지 못했는데 말이야.",
  ui_story_5_7_8_dialog_content = "홀로 자라면서 남과의 교류도, 접촉도 없었다니, 많이 고생했겠구나.",
  ui_story_5_7_9_dialog_content = "어떻게 그걸 알고 있는 거야...?",
  ui_story_5_7_11_dialog_content = "나도 너와 같다. 아름다운 헤븐즈 밸리에서 왔지.",
  ui_story_5_7_14_dialog_content = "어릴 적부터 우리 종족은 함께 배우며 생활했고, 노랫소리에 귀를 기울이며 콜로서스와 대화를 나누었다.",
  ui_story_5_7_A1_dialog_content = "그건 따뜻하고, 견고한 공동체였지, PlayerName. 아이테르의 터전이었다.",
  ui_story_5_7_15_option_content = "하지만 당신... 몸이 투명하잖아?",
  ui_story_5_7_16_dialog_content = "왜 당신 모습을 제대로 볼 수 없는 거야?",
  ui_story_5_7_17_dialog_content = "왜냐하면 난 그저... 네 마음속의 사념일 뿐이니까.\n네가 우릴 보고 싶어 해야만 모습을 드러낼 수 있어.",
  ui_story_5_7_18_dialog_content = "우린 도망치려고 했지만, 결국은 죽음을 맞이했지.\n몸은 썩어 해골이 되었고, 영혼은 끝없는 하늘을 떠돌게 되었다.",
  ui_story_5_7_19_dialog_content = "그녀는 암귀를 이끌고 모든 동족을 잔인하게 살해했고... 그때의 어둠은 오로라조차도 꿰뚫을 수 없었다.",
  ui_story_5_7_20_dialog_content = "그녀는 지금도 여전히 자신의 망집에 사로잡혀 있지.",
  ui_story_5_7_21_dialog_content = "불쌍한 아이야, 네가 홀로 살아온 나날들은 무척 외롭고 고통스러웠겠구나.",
  ui_story_5_7_22_dialog_content = "비록 내가 널 안아 줄 순 없지만, 적어도 너와 함께... 추억의 노래를 불러줄 순 있단다.",
  ui_story_5_7_23_dialog_content = "느껴보거라. 스카이워커호를 제어할 때처럼... 콜로서스를 느끼는 거다.",
  ui_story_5_7_24_dialog_content = "마지막으로 남겨진 낯선 아이야, 이 선물을 받거라.",
  ui_story_5_7_A2_dialog_content = "(그저 환영일 뿐인데, 어째서지? 손길이 내 피부에 닿는 게 느껴져.)",
  ui_story_5_7_25_dialog_content = "(이미 죽은 사람이라는 건 알고 있어. 하지만 왜지?\n그의 의식이 생사를 넘어서 날 이끌어주고 있어...)",
  ui_story_5_7_26_dialog_content = "(이 콜로서스를 밝히자 너희가 보이기 시작했어.)",
  ui_story_5_7_27_dialog_content = "(무슨 노래를 부르는 거야? 경건한 느낌이네... 누굴 애도하는 거야? 너흰 이미 흙으로 돌아갔잖아.)",
  ui_story_5_7_28_dialog_content = "(이런 멜로디는 들어본 적 없어. 하지만 어째서 너희와 함께 흥얼거리게 되는 걸까.)",
  ui_story_5_7_29_dialog_content = "(고마워, 날 위해 연주해주는 거구나... 시간을 초월한 교향시, 영원히... 잊지 않을게.)",
  ui_story_5_7_30_dialog_content = "내... 동족들... 당신들이 정말 존재했다면 좋았을 텐데.",
  ui_story_5_7_31_dialog_content = "콜로서스가 가동되고 있어!",
  ui_story_5_7_32_dialog_content = "콜로서스에서 형용할 수 없는 소리가 울리고 있어...\n오열하는 것 같으면서도, 뭔가 다른 느낌도 들어...",
  ui_story_5_7_33_dialog_content = "누군가 PlayerName 너와 함께 노래하고 있다는 느낌을 받았어. 충만한 감정이 전해진 것 같아.",
  ui_story_5_7_34_dialog_content = "PlayerName, 나도 함께할게.",
  ui_story_5_7_35_dialog_content = "얼마 안 남았어... 5... 4... 가동 성공!",
  ui_story_5_7_36_dialog_content = "봐! 저게 바로 핵심 부품, 「<color=#FFB400>자생 유닛</color>」이야!",
  ui_story_5_7_37_dialog_content = "어서 가지고...",
  ui_story_5_7_38_dialog_content = "뭐, 뭐야? 어떻게 된 거야!?",
  ui_story_5_7_39_dialog_content = "<anim type=Shake>크오오!</anim>",
  ui_story_5_7_40_dialog_content = "아무래도 때맞춰 온 것 같네.",
  ui_story_5_7_41_dialog_content = "넌... 슈모르?!",
  ui_story_5_7_A3_dialog_content = "그럼, 네가 바로 PlayerName인가?",
  ui_story_5_7_A4_dialog_content = "내가 생각했던 것보다 더 애송이잖아. 그런 무능하고 두려움에 찬 얼굴이라니... 하.",
  ui_story_5_7_42_dialog_content = "자아도취의 노래도 여기까지야. 너희 덕분에 자생 유닛을 빼낼 수 있었어.",
  ui_story_5_7_A5_dialog_content = "슈모르... 정말 네가... 지금 내 앞에...",
  ui_story_5_7_45_dialog_content = "괴... 괴로워...",
  ui_story_5_7_46_dialog_content = "누가... 우릴 좀... 구해줘요...",
  ui_story_5_7_47_dialog_content = "널 보니 그 아이테르들이 떠오르네, PlayerName. 저들을 짓밟는 건 마치 개미를 밟는 느낌이었어.",
  ui_story_5_7_48_dialog_content = "나도 한때는 너희처럼 싸울 힘도 없는 쓰레기들과 똑같이 나약했었다는 걸 생각하면, 정말... 역겨워.",
  ui_story_5_7_49_dialog_content = "말이 많은 타입이네.",
  ui_story_5_7_50_dialog_content = "반항이 너무 약하잖아. 실망스러운걸.",
  ui_story_5_7_51_dialog_content = "전에 그 더러운 암귀들이 백야성을 습격하게 만든 게 바로 너인가?",
  ui_story_5_7_52_dialog_content = "그 녀석들은 쓸모 있는 놈이 하나도 없더라고.",
  ui_story_5_7_53_dialog_content = "용서하지 않겠다! 그 더러운 손으로 최후의 도시를 건드렸으니, 대가를 치르게 될 거다!",
  ui_story_5_7_54_dialog_content = "그래서 너희가 뭘 할 수 있다는 거지?",
  ui_story_5_7_55_dialog_content = "PlayerName! 괜찮아?!",
  ui_story_5_7_A6_dialog_content = "(침착해, 침착하자... 위협 따위 무시하면 돼. 난 할 수 있어...)",
  ui_story_5_7_A7_dialog_content = "(평소처럼 싸우면 되는 거야. 그럼 저 녀석, 재앙의 근원, 슈모르를...)",
  ui_story_5_7_A8_dialog_content = "PlayerName! 너, 눈빛이──",
  ui_story_5_7_A9_dialog_content = "후우...",
  ui_story_5_7_A10_dialog_content = "바이스, 난 괜찮아. 카렌과 자리를 지켜줘. 계속 해온 것처럼, 내가 전력을 다해 인도할게.",
  ui_story_5_7_A11_dialog_content = "...좋아. 준비됐어!",
  ui_story_5_7_56_dialog_content = "그럼 지휘를 부탁할게, PlayerName. 내 창으로 모든 악을 꿰뚫을 테니까!",
  ui_story_5_7_57_dialog_content = "모두 준비해! 적은... 슈모르야!",
  ui_story_5_7_A12_dialog_content = "약자라면 순순히 부서져 버려야지.",
  ui_story_5_7_58_dialog_content = "말했잖아. 약자는 약자답게 얌전히 엎드려 있으면 된다고! 왜 발악하는 건데!",
  ui_story_5_7_59_dialog_content = "쳇, 정말 성가시네. 지휘니, 인도니 해봤자 결국 뒤에 숨은 겁쟁이일 뿐이잖아?",
  ui_story_5_7_60_dialog_content = "뭐, 그래도 인정할게. 넌 다른 아이테르와는 조금 다른 것 같네...",
  ui_story_5_7_61_option_content = "아니, 나도 다른 아이테르와 다르지 않아.",
  ui_story_5_7_62_option_content = "넌 내가 충분히 상대할 수 있어.",
  ui_story_5_7_63_dialog_content = "무슨 멍청한 소릴 하는 거야? 널 칭찬하는 게 아니야. 그저 네게 사형을 선고한 것뿐이니까.",
  ui_story_5_7_64_dialog_content = "그런 힘은 내겐 너무나도 보잘것없거든.",
  ui_story_5_7_65_dialog_content = "무슨... 이런 힘이...",
  ui_story_5_7_66_dialog_content = "선택해, 조각조각 찢겨 죽을지, 아니면 완전히 뭉개져 죽을지.",
  ui_story_5_7_67_dialog_content = "바로 지금이야!",
  ui_story_5_7_68_dialog_content = "응? 이 진동은...",
  ui_story_5_7_69_dialog_content = "컨티뉴! 코인 러시라고! 다행히 시간 끄는 건 잘 해냈어!",
  ui_story_5_7_70_dialog_content = "부품은 무사히 확보했어! 카렌, PlayerName!",
  ui_story_5_7_71_dialog_content = "저쪽은 내가 막을 테니까 너희는 어서 부품을 가지고 철수해!",
  ui_story_5_7_72_option_content = "하지만 그로누 씨?!",
  ui_story_5_7_73_dialog_content = "난 괜찮아! 마침 내 궁극기를 보여줄 때도 됐으니까!",
  ui_story_5_7_74_option_content = "알겠어!",
  ui_story_5_7_75_dialog_content = "게임의 룰을 활용하는 건 중요한 능력이야. 넌 아주 잘하고 있어!\n그럼 반드시 부품을 일루미나에 가지고 돌아가야 해!",
  ui_story_5_7_76_dialog_content = "슈모르의 힘은 보통이 아냐. 당신 혼자서는...",
  ui_story_5_7_77_dialog_content = "나도 보통 연구원이 아니라고! 힘을 가장 잘 이해하고 있는 건 나야! 난 강해!",
  ui_story_5_7_78_dialog_content = "알겠어. 바이스, PlayerName, 가자. 그로누가 만들어 준 기회를 헛되이 해서는 안 돼.",
  ui_story_5_7_79_dialog_content = "너희 잡담을 봐주는 건 여기까지야. 어서 부품을 내놔.",
  ui_story_5_7_80_dialog_content = "어떡하지? 난 진짜로 너랑 한 판 싸우고 싶은데?",
  ui_story_5_7_A13_dialog_content = "암귀의 능력을 손에 넣은 아이테르, 지옥 난이도의 데스 매치, 듣기만 해도 설레잖아!",
  ui_story_5_7_81_dialog_content = "나랑 게임 한 판 하자!",
  ui_story_5_7_82_dialog_content = "...재미없기 짝이 없네!",
  ui_story_5_7_83_dialog_content = "바이스, 이미 시간이 꽤 지났는데... 그로누는 아직도 연락이 없잖아.",
  ui_story_5_7_84_dialog_content = "그로누 선배... 괜찮겠지?",
  ui_story_5_7_85_dialog_content = "더는 미룰 수 없어. 이제 이륙해야 해.",
  ui_story_5_7_86_dialog_content = "알고 있어...",
  ui_story_5_7_87_dialog_content = "무슨 소리 들리지 않아? 통신기가 울리는 것 같아!",
  ui_story_5_7_88_dialog_content = "이건...",
  ui_story_5_7_89_dialog_content = "<color=#FFB400>그로누 선배</color>?!",
  ui_story_5_8_1_dialog_content = "바이스, 빨리 부품과 스카이워커호를 데리고 일루미나로 돌아가, 돌...",
  ui_story_5_8_2_dialog_content = "그로누 선배!",
  ui_story_5_8_3_dialog_content = "닥쳐! 내가 언제 그런 말을 하라고 했어?!",
  ui_story_5_8_4_dialog_content = "잘 들어, 잔챙이들. 두 번 말하지 않을 테니까.",
  ui_story_5_8_5_dialog_content = "30분 안에 바로 여기로 돌아와 「자생 유닛」을 나한테 넘겨. 아니면 이 녀석은 반드시 죽을 테니까.",
  ui_story_5_8_6_dialog_content = "무시해! 빨리 돌아가! 이건 명령이야!",
  ui_story_5_8_7_dialog_content = "조용히 하라고!",
  ui_story_5_8_8_dialog_content = "30분은 너무 짧아. 지금 일루미나에 지원을 요청해도 올 수 있는 사람이 없을 거야...",
  ui_story_5_8_9_dialog_content = "지금 「자생 유닛」을 가지고 돌아가면 더 많은 생명을 지킬 수 있어.",
  ui_story_5_8_10_dialog_content = "이럴 때는 상관의 명령을 따라야 한다는 건 알아. 그건 줄곧 일루미나인에게 가장 중요한 규칙이었어...",
  ui_story_5_8_11_dialog_content = "하지만 난 그로누 선배를 여기서 죽게 내버려 둘 수 없어...",
  ui_story_5_8_12_dialog_content = "여전하네. 좋게 말하면 착한 거지만, 나쁘게 말하면 우유부단한 거야.",
  ui_story_5_8_13_dialog_content = "한 사람의 생명이냐, 아니면 수많은 사람의 생명이냐. 이게 그렇게 어려운 선택인가?",
  ui_story_5_8_14_dialog_content = "...난 모든 사람을 지키고 싶어.",
  ui_story_5_8_15_dialog_content = "크오오──!",
  ui_story_5_8_16_dialog_content = "우선 콜로서스에 올라탄 이 불청객들부터 처리하고 다시 얘기하자고.",
  ui_story_5_10_1_dialog_content = "어디 보자. 숨을 줄밖에 모르는 잔챙이들이 왜 아직도 조용한 거지? 시간이라도 끌겠다는 걸까?",
  ui_story_5_10_2_dialog_content = "하지만 내 인내심엔 한계가 있어. 남은 시간은 20분... 아니, 19분이네.",
  ui_story_5_10_3_dialog_content = "19분 뒤에 이 노란 머리의 몸을 조금씩 조각내겠어.",
  ui_story_5_10_4_dialog_content = "어떤 비명을 지를지 상상만 해도 설레는걸.",
  ui_story_5_10_5_dialog_content = "부품을 넘겨주는 것 외에 그로누 선배를 구할 수 있는 다른 방법은 없는 거야?!",
  ui_story_5_10_6_dialog_content = "녀석은 미쳤어. 말이 통할 상대가 아냐.",
  ui_story_5_10_7_option_content = "방법이 하나만 있는 건 아닐 거야.",
  ui_story_5_10_8_dialog_content = "에?",
  ui_story_5_10_9_dialog_content = "나한테 방법이 있어. 상황을 역전시킬 수 있을지도 몰라... 15분이면... 충분할 거야.",
  ui_story_5_10_10_dialog_content = "무슨 뜻이지?",
  ui_story_5_10_11_dialog_content = "퇴각하는 척 우회 공격을 하는 거야...",
  ui_story_5_10_12_option_content = "난 모두를 지키고 싶어.",
  ui_story_5_10_13_dialog_content = "PlayerName... 내 생각에 동의하는 거야?",
  ui_story_5_10_14_dialog_content = "그로누의 목숨이든 누구의 목숨이든, 모두 다 지켜내야 해.",
  ui_story_5_10_15_dialog_content = "바이스도 그렇고, 너까지 그런 생각이라니... 어쩔 수가 없네.",
  ui_story_5_10_16_dialog_content = "하지만 적어도 뭔가 방법이 있으니까 그렇게 말을 하는 거겠지?",
  ui_story_5_10_17_dialog_content = "그래. 좀 위험하겠지만... 두 사람의 도움이 필요해.",
  ui_story_5_10_A1_dialog_content = "이제 우리가 먼저 공격하는 거야. 신속하게!",
  ui_story_5_10_A2_dialog_content = "내가 생각한 방법을 설명해 줄게...",
  ui_story_5_10_18_dialog_content = "이제 몇 분 남지도 않았는데 떠나지도 착륙하지도 않다니, 아직도 고민하고 있는 건가?",
  ui_story_5_10_19_dialog_content = "왕좌... 가동!",
  ui_story_5_10_20_dialog_content = "정말 주제를 모르는 녀석이네.",
  ui_story_5_10_21_dialog_content = "이것도 효과가 없다고...?!",
  ui_story_5_10_22_dialog_content = "세 번의 자살 공격이라니, 정말 목숨이 아깝지도 않은 모양이네.\n하지만 얌전히 있는 게 좋을 거야. 아직 네가 죽을 차례는 아니니까.",
  ui_story_5_10_23_dialog_content = "쇼크── 체...",
  ui_story_5_10_24_dialog_content = "...어지러워! 결국 이렇게 게임 오버인 건가...",
  ui_story_5_10_25_dialog_content = "잘 자, 몇 분 뒤면 내가 영원한 잠에 들게 해 줄 테니까.",
  ui_story_5_10_A3_dialog_content = "여기 한 마리 더 있어!",
  ui_story_5_10_A4_dialog_content = "아주 신속했어! 슈모르가 알아차리진 않았겠지?",
  ui_story_5_10_A5_dialog_content = "난 적한테서 도망치고 숨는 전투 방식은 정말 질색이야. PlayerName.",
  ui_story_5_10_A6_dialog_content = "그래도 아주 잘해줬어. 계속 나아가자. 우리한테 남은 선택지는 하나뿐이야.",
  ui_story_5_13_1_dialog_content = "5분 남았네. 야, 일어나.",
  ui_story_5_13_2_dialog_content = "쿨, 쿨쿨... 눈앞에 별이 가득해. 별을 먹으면 레벨업할 수 있으려나...",
  ui_story_5_13_3_dialog_content = "일어나라고 했잖아.",
  ui_story_5_13_4_dialog_content = "으아악! 방금 시끄럽다고 기절시켜놓고 이제 와선 또 깨우다니, 역시 메인 빌런답네!",
  ui_story_5_13_5_dialog_content = "5분 남았어. 녀석들은 아직도 움직이지 않고 있고. 이미 널 버린 건 아니겠지?",
  ui_story_5_13_6_dialog_content = "그래야 맞지. 녀석들이 돌아온다면 네가 공격하기 전에 내가 먼저 흠씬 패줄 거였으니까.",
  ui_story_5_13_7_dialog_content = "됐어. 마침 나도 기다리기 지겹던 참이었어.",
  ui_story_5_13_A1_dialog_content = "조금 귀찮긴 하지만, 지금 널 해치우고 녀석들을 처리하러 가는 것도 나쁘지 않은 선택일 것 같네.",
  ui_story_5_13_8_dialog_content = "잠깐잠깐잠깐, 정말 시간이 되기도 전에 인질을 죽일 생각이야? 그건 게임 규칙에 어긋나잖아!",
  ui_story_5_13_9_dialog_content = "게임 규칙? 강자가 곧 규칙이야!",
  ui_story_5_13_A2_dialog_content = "그 시끄러운 입을 영원히 닫아줄게──",
  ui_story_5_13_10_dialog_content = "뭐야?!",
  ui_story_5_13_11_dialog_content = "피어나라, 빙화여!",
  ui_story_5_13_12_dialog_content = "설마 기습을 할 줄이야...",
  ui_story_5_13_13_dialog_content = "슈모르는 정서나 상태가 무척 불안정하니까, 약속을 지키지 않을 가능성이 높아.",
  ui_story_5_13_14_dialog_content = "그로누가 매우 위험한 상황이야. 최대한 빨리 움직여야 해.",
  ui_story_5_13_A3_dialog_content = "난 준비됐어, PlayerName. 네 계획대로 하자!",
  ui_story_5_13_A13_dialog_content = "스카이워커호를 제자리에 정박해 슈모르의 판단을 흐리게 만든다. 그리고...",
  ui_story_5_13_17_dialog_content = "슈모르를 기습하는 거야! 우리가 먼저 공격할 거라고는 전혀 생각하지 못할 테니까!",
  ui_story_5_13_18_dialog_content = "망설이는 척하면서 기습을 벌인 거야?",
  ui_story_5_13_19_dialog_content = "이런 단순한 방법이 확실히 효과가 있었던 모양이네!\n포기해, 슈모르! 주변의 암귀들도 우리가 전부 처치했으니까!",
  ui_story_5_13_20_dialog_content = "흥, 이걸로 「성공」했다고 생각한다면...",
  ui_story_5_13_21_dialog_content = "날 잊으면 안 되지! 받아라!",
  ui_story_5_13_22_dialog_content = "공격이 먹혔어! 빌런이 다쳤어! 이번엔 4인 파티라고! 전세 대역전!",
  ui_story_5_13_A4_dialog_content = "가장 중요한 부품은 안전한 곳에 숨겨둔 거지? 그럼 이제 당당하게 두드려 팰 수 있겠네!",
  ui_story_5_13_24_dialog_content = "카렌, 같이 공격하자!",
  ui_story_5_13_26_dialog_content = "알겠어! 녀석에게 맞설 틈을 줘선 안 돼!",
  ui_story_5_13_27_dialog_content = "아무래도 넌 그 정도가 끝이었던 모양이네.",
  ui_story_5_13_28_dialog_content = "...내가... 너희 같은 쓰레기들한테 얕보이다니.",
  ui_story_5_13_29_dialog_content = "주변의 분위기가 변한 것 같은데?!",
  ui_story_5_13_30_dialog_content = "녀석의 힘이... 그동안 느꼈던 것과는 전혀 달라!",
  ui_story_5_13_31_dialog_content = "참을 수 없어. 용납할 수 없어! 너희들이 죽음을 자초한 이상 나도 더는 봐줄 필요 없겠지!",
  ui_story_5_13_A14_dialog_content = "그래! 아까보다 더 잘 싸우잖아! 조금만 더 하면 날 즐겁게 해 줄 수 있겠는걸.",
  ui_story_5_13_A15_dialog_content = "하지만 방금 「날 이길 수 있다」고 생각하던 그 표정들은 정말 불쾌했어! 당장 꿇어!",
  ui_story_5_13_A16_dialog_content = "어, 어째서 힘이 더 강해진 거지?!",
  ui_story_5_13_A17_dialog_content = "설마 지금까지 계속... 힘을 숨겼던 건가... 그저... 우릴 가지고 놀려고?",
  ui_story_5_13_32_dialog_content = "(살해당할 거야! 이대로 가다간 정말 죽을지도 몰라──)",
  ui_story_5_13_A5_dialog_content = "(동족들도 이런 절망을 느꼈던 거야? 이런 압도적인 힘 앞에서...)",
  ui_story_5_13_33_dialog_content = "(암귀의 힘을 받아들인 아이테르가... 이렇게까지 강해진단 말이야?)",
  ui_story_5_13_34_dialog_content = "두려워? 약해빠진 아이테르도 이렇게 강해질 수 있어. 이게 바로 이클립스가 하사한 힘이야!",
  ui_story_5_13_35_dialog_content = "<size=45>오로리안보다 더 강하다고!</size>",
  ui_story_5_13_36_dialog_content = "아, 아파... 숨을 쉴 수가... 없어.",
  ui_story_5_13_37_dialog_content = "이제 선택할 차례야. 녀석의 목숨과 「자생 유닛」 중에서 골라.",
  ui_story_5_13_38_dialog_content = "크윽... 절대... 넘기면 안 돼...!",
  ui_story_5_13_39_dialog_content = "그로누! 바이스, 카렌까지...",
  ui_story_5_13_40_dialog_content = "제길, 아직 싸울 수 있어... 더... 싸울 수...",
  ui_story_5_13_41_dialog_content = "난...",
  ui_story_5_13_42_dialog_content = "음, 무슨 생각이라도 있는 거야? 설마... 나와 싸우려는 건 아니겠지?\n전투 능력이라곤 하나도 없는 네가?",
  ui_story_5_13_43_dialog_content = "하하... 아하하하! 너무 웃기는걸.",
  ui_story_5_13_44_dialog_content = "내겐... 싸울 힘은 없어도, 주먹은 있어...",
  ui_story_5_13_45_dialog_content = "슈모르!",
  ui_story_5_13_46_dialog_content = "PlayerName, 안 돼!",
  ui_story_5_13_47_dialog_content = "난 루미나의 힘은 없는 아이테르지만... 적어도 난 싸우는 게 두렵지 않아.",
  ui_story_5_13_48_dialog_content = "반드시 지킬 거야. 내 동족, 동료, 친구들을!",
  ui_story_5_13_A6_dialog_content = "주먹이 으깨지면 이빨로 물어뜯겠어. 이빨이 빠지면 머리라도 부딪히겠어!",
  ui_story_5_13_A7_dialog_content = "날 굴복시킬 순 없어. 아이테르를 굴복시킬 수 없을 거라고! 슈모르... 이번에는, 내가...",
  ui_story_5_13_49_dialog_content = "<size=45>모두의 앞에 서겠어!</size>",
  ui_story_5_13_A8_dialog_content = "......",
  ui_story_5_13_A9_dialog_content = "흥... 재미없어.",
  ui_story_5_13_50_dialog_content = "그 진부한 「허풍」은 충분히 들었다고. 그렇게 애쓰며 외쳐댈 필요가 있어?",
  ui_story_5_13_51_dialog_content = "으윽...",
  ui_story_5_13_52_dialog_content = "PlayerName, 어째서 그런 거야...",
  ui_story_5_13_53_dialog_content = "쓰레기, 빨리 선택해. 부품인지 저들의 목숨인지. 숫자를 세겠어. 10, 9...",
  ui_story_5_13_54_option_content = "조건이 있어...",
  ui_story_5_13_55_option_content = "알겠어, 부품을 줄게.",
  ui_story_5_13_56_dialog_content = "흥, 지금 나랑 협상을 하겠다는 거야? 아하하...",
  ui_story_5_13_57_dialog_content = "부품은 줄 수 있지만, 먼저 저들을 보내줘!",
  ui_story_5_13_58_dialog_content = "웃겨 죽겠네. 진심으로 하는 소리야? 무릎 꿇고 자비나 구하지 그래.",
  ui_story_5_13_59_dialog_content = "먼저 저들을 보내주면 내 목숨과 부품은 전부 네 거야. 받아들이지 않는다면 내가 부품을 파괴하겠어.",
  ui_story_5_13_60_dialog_content = "파괴하겠다고? 「용감하게 죽겠다」 이거야? 멘델슨한테 배우기라도 한 모양이지? 정말 역겹네.",
  ui_story_5_13_F1_dialog_content = "좋아, 저들은 가도 좋아.",
  ui_story_5_13_F2_dialog_content = "부품은 줄게.",
  ui_story_5_13_F3_dialog_content = "아이테르는 늘 이렇게 불쌍하다니까. 힘이 없으면 남에게 짓밟힐 뿐이야.\n힘겹게 살아남는 것조차 강자가 베푸는 자비 덕분이라고.",
  ui_story_5_13_F4_dialog_content = "아하하, 남에게 유린당하는 느낌이 어때? 정말 싫지?",
  ui_story_5_13_F5_dialog_content = "옛날 일이 또 생각나지 않아?",
  ui_story_5_13_F6_dialog_content = "잘 기억해 둬. <size=45>약자</size>라면 그 굴욕감에 익숙해져야 할 테니까.\n안 그러면 비굴하게 살아남을 기회조차 없을 거야.",
  ui_story_5_13_61_dialog_content = "아이테르는 늘 이렇게 불쌍하다니까. 힘이 없으면 남에게 짓밟힐 뿐이야.\n힘겹게 살아남는 것조차 강자가 베푸는 자비 덕분이라고.",
  ui_story_5_13_F7_dialog_content = "부품만 아니었으면 내가 너희 따위한테 눈길이라도 줬을 것 같아?",
  ui_story_5_13_68_dialog_content = "목숨을 건진 걸 축하해. 이건 강자의 자비야. 은혜에 감사하게 생각하라고. 아하하...",
  ui_story_5_13_69_dialog_content = "그로누 선배, 괜찮아요? 두 시간이나 기절해 있었어요...",
  ui_story_5_13_70_dialog_content = "HP가 거의 바닥 났지만... 그래도 겨우 살아났네...",
  ui_story_5_13_F8_dialog_content = "미안해, 날 구한다고 결국 부품을 빼앗겨 버렸잖아.",
  ui_story_5_13_71_dialog_content = "아니에요, 그로누 선배. 저희가 힘이 부족했던 거예요...",
  ui_story_5_13_72_dialog_content = "하지만 적어도 저희 모두 살아있잖아요. 최악은 아니에요.",
  ui_story_5_13_73_dialog_content = "너흰 이미 충분히 잘했어!",
  ui_story_5_13_74_dialog_content = "전에 필리시가 이 일에 대해 말해줬을 땐 믿지 않았어. 하지만 내 눈으로 직접 보니...",
  ui_story_5_13_A10_dialog_content = "슈모르의 힘은 내 상상 이상으로 강했어!",
  ui_story_5_13_75_dialog_content = "이곳에서 일어난 일을 모두 보고할게. 상부에 이 일의 심각성을 알려야 해.",
  ui_story_5_13_76_dialog_content = "이제 세 번째 부품만 남은 거지?",
  ui_story_5_13_77_dialog_content = "<color=#FFB400>「화염 제어 모듈」...</color>",
  ui_story_5_13_78_dialog_content = "콜로서스를 개조하고 공격 능력을 강화하는 최강의 무기 부품...\n하지만 우린 그게 어디 있는지 아직 몰라.",
  ui_story_5_13_79_option_content = "어떻게 해야 할지 알았어.",
  ui_story_5_13_F9_dialog_content = "난 슈모르와 충분히 접촉했어. 그 끔찍한 기운은 죽어서도 잊지 못할 거야.",
  ui_story_5_13_F10_dialog_content = "지금은 아직 멀리 가지 않았어. 내가 눈을 감고...",
  ui_story_5_13_F11_dialog_content = "「약자」처럼 소리 없이 잠잠하게 의식을 감응한다면, 슈모르는 절대 알아채지 못할 거야.",
  ui_story_5_13_80_dialog_content = "(여긴... 함정이 가득해... 뭔가... 복잡한 미궁 같은데?)",
  ui_story_5_13_81_dialog_content = "(신비로운 어둠의 공간, 악취미의 수집품이 가득한 곳...)",
  ui_story_5_13_82_dialog_content = "슈모르는 어디로 가야 하는지 분명히 알고 있을 거야...",
  ui_story_5_13_83_dialog_content = "...<color=#FFB400>속삭이는 회랑</color>인가...",
  ui_story_5_13_85_option_content = "속삭이는 회랑!",
  ui_story_6_1_1_dialog_content = "슈모르는 정말 끔찍한 상대였어...",
  ui_story_6_1_2_dialog_content = "녀석이 모든 부품을 모으고 나면 상대하기가 더 어려워질 거야...",
  ui_story_6_1_3_dialog_content = "(카렌과 바이스 둘다 기가 죽은 것 같아. 분위기를 좀 바꿔봐야겠어.)",
  ui_story_6_1_F1_dialog_content = "지금이라도 슈모르를 바로 추격하면 다음 부품을 손에 넣는 걸 막을 수 있을지도 몰라.",
  ui_story_6_1_F2_dialog_content = "물론 무척 위험하겠지...",
  ui_story_6_1_4_option_content = "카렌, 어떻게 생각해?",
  ui_story_6_1_5_dialog_content = "시간을 끌면 안 돼. 지금 바로 녀석을 쫓아가야 해.",
  ui_story_6_1_6_option_content = "바이스, 네 생각은 어때?",
  ui_story_6_1_7_dialog_content = "이미 본부에 메시지를 보내서 <color=#FFB400>속삭이는 회랑</color>으로 가겠다고 보고했어.",
  ui_story_6_1_8_dialog_content = "속삭이는 회랑에 대해... 아는 사람 있어?",
  ui_story_6_1_9_dialog_content = "거긴 <color=#FFB400>움브라톤</color>의 세력권에 속할 거야. 백야성에서 유학할 때 들어본 적 있어.",
  ui_story_6_1_10_dialog_content = "역시 수업을 한 번도 빼먹지 않은 우등생답네. 더 자세한 정보도 알고 있겠지?",
  ui_story_6_1_11_dialog_content = "크흠, 흠. 속삭이는 회랑은 원래 움브라톤 바깥에 있는 지하 유적이었어.",
  ui_story_6_1_12_dialog_content = "백야성 사람들이 그걸 발견했고, 거기서 유물들을 많이 발굴했어.",
  ui_story_6_1_13_dialog_content = "하지만 발굴 가치가 떨어진 뒤에는 아무도 관리하지 않게 되어 폐허가 됐어.",
  ui_story_6_1_14_dialog_content = "그 후에는 떠돌이나 범죄자의 집결지가 되어 무질서한 곳으로 변해버렸지.",
  ui_story_6_1_A1_dialog_content = "그러다 10여 년 전에 <color=#FFB400>이스타반 클랜</color>이라는 조직이 움브라톤에 나타났어.",
  ui_story_6_1_A2_dialog_content = "그 조직의 수장은 이스타반이라는 사람인데, 많은 사람들의 추앙을 받으며 「섀도우마스터」라 불리고 있어.",
  ui_story_6_1_A3_dialog_content = "그들이 속삭이는 회랑을 맡아 관리한 후로는 멋대로 그곳에 들어가려 하는 사람이 없게 됐어.",
  ui_story_6_1_A4_dialog_content = "듣기로는 지금은 각종 진귀한 골동품을 보관하는 「보관소」가 되었다고 해.",
  ui_story_6_1_A5_dialog_content = "역시 「걸어 다니는 사전」이 옆에 있으니 참 편리한걸...",
  ui_story_6_1_F3_dialog_content = "헤헷, 고마워.",
  ui_story_6_1_A6_dialog_content = "그래서 「섀도우마스터」한테도 편지를 한번 보내봤어. 그들의 도움을 받을 수 있다면 좋을 텐데 말이야.",
  ui_story_6_1_A7_dialog_content = "어쩌면 속삭이는 회랑에 도착했을 때 섀도우마스터가 보낸 사람이 우릴 맞이할지도 몰라.",
  ui_story_6_1_A8_dialog_content = "네 문법이 예전 그대로라면 섀도우마스터는 상대도 안 해줄 것 같은데.",
  ui_story_6_1_F4_dialog_content = "에이, 어차피 지금은 체면 같은 걸 생각할 상황도 아니잖아!",
  ui_story_6_1_15_dialog_content = "아! 그리고 방금 들어온 소식인데, 일루미나 사령부에서 또 회의를 했다고 해...",
  ui_story_6_1_16_dialog_content = "군단장 여러분, 잘 생각해 보세요.\n속삭이는 회랑은 섀도우마스터의 영역이긴 하지만, 적의 정체가 이미 확실해졌고...",
  ui_story_6_1_17_dialog_content = "게다가 그로누 연구원장을 공격한 건 명백한 도발행위입니다.",
  ui_story_6_1_F5_dialog_content = "PlayerName 일행이 소식을 전해주지 않았다면, 우린 슈모르의 소행에 대해 전혀 몰랐을 겁니다.",
  ui_story_6_1_18_dialog_content = "애초에 그 녀석들이 없었으면 이런 일이 일어나지 않았을지도 모르잖아?",
  ui_story_6_1_19_dialog_content = "아니요, PlayerName의 존재 여부는 슈모르가 무기의 부품을 모으는 것과는 직접적인 관계가 없습니다.",
  ui_story_6_1_20_dialog_content = "책임 소재는 일단 됐으니까, 히이로! 넌 나랑 같이 움직일 건지만 결정해 줘!",
  ui_story_6_1_21_dialog_content = "아... 저기...",
  ui_story_6_1_22_dialog_content = "함께 하고 싶지 않은 게 아닙니다.\n일루미나를 위협하는 자들 앞에선 우리 모두가 같은 마음일 겁니다...",
  ui_story_6_1_23_dialog_content = "하지만 대원수님께선 「때를 기다린다」는 명령을 내리셨습니다.",
  ui_story_6_1_X23_dialog_content = "대원수님이 왜 그런 명을 내리신 거지?",
  ui_story_6_1_X24_dialog_content = "아아~ 다들 기다려 보세요! 여러분의 마음은 저도 이해해요.",
  ui_story_6_1_X25_dialog_content = "하지만 대원수님의 명령이 없는 한, 우린 계속해서 상황을 지켜보는 수밖에 없어요!",
  ui_story_6_1_X26_dialog_content = "어쩌면 더 심오한 계획이 있으실지도 모르잖아요? 여명의 빛을 믿으세요!",
  ui_story_6_1_X27_dialog_content = "......",
  ui_story_6_1_X28_dialog_content = "바튼은? 왜 안 온 거지?",
  ui_story_6_1_X29_dialog_content = "바튼하고 그 근육녀도 진격에 동의했다면 대원수님한테 좀 더 얘기해볼 수 있었을 텐데 말이야.",
  ui_story_6_1_X30_dialog_content = "다른 군단장들도 임시 임무를 받았거든요~",
  ui_story_6_1_X31_dialog_content = "시로나는 저와 함께 백야성 근교에 가서 방어선을 구축해야 해요!",
  ui_story_6_1_25_dialog_content = "어찌 됐든 우선 겉으로라도 대응하는 모습을 보여야 하니까요.",
  ui_story_6_1_27_dialog_content = "...이렇게 된 상황이야. 결국 슈모르의 목적이 뭐든 간에, 우리끼리 알아내는 수밖에 없어.",
  ui_story_6_1_28_dialog_content = "지난번에는 다행히 필리시 선배랑 그로누 선배의 도움을 받았지만, 이번에는...",
  ui_story_6_1_F6_dialog_content = "우리가 가야 할 곳은 움브라톤의 관할 범위 안이고, 움브라톤 바로 위에는 백야성이 있어...",
  ui_story_6_1_F7_dialog_content = "응, 이해해. 일루미나와 백야성은 비록 외적으로는 협력 관계지만, 여전히 서로 거리를 두고 있으니까.",
  ui_story_6_1_29_dialog_content = "하지만 이대로 가면 양쪽 모두에게 좋은 일이 아니야. 특히 지금 같은 상황에선 더더욱.",
  ui_story_6_1_30_dialog_content = "백야성 쪽은 내가 최대한 힘써볼게. 적어도...",
  ui_story_6_1_31_dialog_content = "카렌 호위대장, 상황은 어떤가?",
  ui_story_6_1_32_dialog_content = "죄송합니다. 저흰 실패했습니다. <color=#FFB400>「자생 유닛」</color>도 빼앗기고 말았습니다.",
  ui_story_6_1_33_dialog_content = "사망자는?",
  ui_story_6_1_34_dialog_content = "없습니다.",
  ui_story_6_1_35_dialog_content = "하지만 녀석이 저희보다 먼저 속삭이는 회랑으로 향했습니다.",
  ui_story_6_1_36_dialog_content = "솔라드 전하, 호위대 파견을 청합니다. 가능하면 사천사의 지원이 필요합니다.",
  ui_story_6_1_37_dialog_content = "불허한다.",
  ui_story_6_1_38_dialog_content = "아버... 전하, 녀석에게 <color=#FFB400>「화염 제어 모듈」</color>마저 빼앗긴다면, 최악의 상황이 오고 말 겁니다!",
  ui_story_6_1_39_dialog_content = "녀석은 심지어 콜로서스를 개조해 백야성을 위협해올 수도 있습니다!",
  ui_story_6_1_40_dialog_content = "그렇다, 카렌 대장. 그 점을 염려하여 호위대를 파견할 수 없는 것이다.",
  ui_story_6_1_41_dialog_content = "전하, 전 호위대장으로서 호위대의 통솔권이 있습니다. 부디 사천사를 동원하는 것을 허락해 주십시오.",
  ui_story_6_1_42_dialog_content = "그 권리를 내가 없앨 수도 있다만, 대장.",
  ui_story_6_1_43_dialog_content = "그럼 전 호위대장으로서 백야성을 대표해 이들을 도울 겁니다. 저 혼자서라도 말입니다.",
  ui_story_6_1_45_dialog_content = "카렌, 네 용기는 치하하마.",
  ui_story_6_1_46_dialog_content = "PlayerName! 백야 아래의 백성으로서, 그대들이 카렌 호위대장의 안전을 보장할 수 있길 바란다.",
  ui_story_6_1_47_dialog_content = "네? 아, 알겠습니다...",
  ui_story_6_1_48_dialog_content = "<size=30>나도 PlayerName도 백야성 사람이 아닌데...</size>",
  ui_story_6_1_49_dialog_content = "어차피 카렌이 호위대장이 아니었어도 우린 당연히 서로를 지켜줄 거였잖아. 우린 동료니까!",
  ui_story_6_1_50_dialog_content = "...잡담은 됐어. 이제 곧 목적지에 도착하겠지?",
  ui_story_6_1_51_dialog_content = "이 부근은 전부 황무지네. 오랫동안 아무도 오지 않은 모양이야.",
  ui_story_6_1_52_dialog_content = "역시 스카이워커호가 있어서 다행이야! 아니었으면 슈모르를 따라잡지 못했을 거야!",
  ui_story_6_1_F8_dialog_content = "스카이워커호, 바이스가 널 칭찬하고 있어.",
  ui_story_6_1_53_dialog_content = "애초에 전 당신을 위해 존재합니다. 도움이 됐다니 영광입니다.",
  ui_story_6_1_54_dialog_content = "이곳에서는 과거의 헤븐즈 밸리처럼 불안한 기운이 느껴지는군요. 모두 조심하십시오.",
  ui_story_6_1_55_dialog_content = "PlayerName, 여긴 어디서든 암귀가 나타날 수 있어. 지금 스카이워커호가 있는 곳은 안전할까?",
  ui_story_6_1_56_dialog_content = "저 언덕 바깥쪽에 세워뒀어. 마침 숲이 있어서 콜로서스가 가려지거든.",
  ui_story_6_1_57_dialog_content = "걱정 마. 스카이워커는 「은신」 능력이 있으니까, 우린 안심하고 싸워도 돼.\n거기서 우릴 기다리고 있을 거야.",
  ui_story_6_1_58_dialog_content = "「누군가가 내가 돌아오는 걸 기다린다」니, 갑자기 포근한 기분이 들어...\n여기에 따뜻한 욕조 같은 것도 하나 있으면 좋을 텐데.",
  ui_story_6_1_59_dialog_content = "정말 유치한 생각이네.",
  ui_story_6_1_A9_dialog_content = "게다가 이런 곳에 네가 말한 「보관소」가 있다고? 아무리 봐도 황량한 벌판뿐인걸.",
  ui_story_6_1_A10_dialog_content = "속삭이는 회랑의 입구는 숨겨져 있어. 자세히 조사하지 않으면 찾기 힘들 거야.",
  ui_story_6_1_A11_dialog_content = "설마 바이스 넌 이미...",
  ui_story_6_1_A12_dialog_content = "맞아! 입구는 바로 우리 발밑에 있어!",
  ui_story_6_1_A13_dialog_content = "발밑...? 속삭이는 회랑이 지하에 있다고?",
  ui_story_6_1_A14_dialog_content = "지면을 조심해! 장치를 가동시킬 거니까~",
  ui_story_6_1_A15_dialog_content = "땅이... 갈라지고 있어?!",
  ui_story_6_1_A16_dialog_content = "와... 이건 정말...",
  ui_story_6_1_A17_dialog_content = "정말 복잡하네. 왜 이런 설계를 했는지 이해할 수가 없어.",
  ui_story_6_1_A18_dialog_content = "불법을 저지른 자나 당당히 드러낼 수 없는 장물 따위에나 이런 은밀한 곳이 필요한 법이라고.",
  ui_story_6_1_A19_dialog_content = "이 아래가 바로 속삭이는 회랑이야. PlayerName, 뭔가 느껴져?",
  ui_story_6_1_60_dialog_content = "슈모르는... 이 아래에 있어. 지하에서 솟아오르는 한기가 느껴져.",
  ui_story_6_1_A20_dialog_content = "역시, 여긴 엄청 춥네!",
  ui_story_6_1_A21_dialog_content = "지금은 불평할 때가 아냐. 우린 서둘러야 해.",
  ui_story_6_1_61_dialog_content = "녀석의 정확한 위치를 감응해낼 순 없는 거야?",
  ui_story_6_1_62_dialog_content = "미안. 감응 능력으로도 속삭이는 회랑 내부에 있다는 정도밖에 모르겠어. 구체적인 위치까지는...",
  ui_story_6_1_63_dialog_content = "그럼 쉽지 않겠는데...",
  ui_story_6_1_64_dialog_content = "속삭이는 회랑의 지형은 아주 복잡하다고 해. 숨겨진 문이나 비밀 통로가 여기저기 있어서,\n섀도우마스터만 이곳의 길을 알고 있다고 해.",
  ui_story_6_1_65_dialog_content = "그래서 이곳이 「보관소」가 된 거야.",
  ui_story_6_1_F9_dialog_content = "물건을 여기 두는 게 움브라톤에 두는 것보다 더 안전할 테니까.",
  ui_story_6_1_66_dialog_content = "잠깐, 누군가 오고 있어!",
  ui_story_6_1_67_dialog_content = "조심해! 암귀일 수도 있어...",
  ui_story_6_1_68_dialog_content = "PlayerName 네가 전혀 당황하지 않은 걸 보니, 오로리안일 것 같은데.",
  ui_story_6_1_70_dialog_content = "꽤나 떠들썩하네! 이렇게나 많은 벽과 문을 사이에 두고도 너희의 열정적인 토론이 들려올 정도였다니까.",
  ui_story_6_1_71_dialog_content = "후후후, 정말 흥미로운걸. 백야성의 귀족 아가씨, 일루미나 군인 소녀에 아이테르까지...",
  ui_story_6_1_72_dialog_content = "너희가 바로 그분이 말한 그 콜로서스 팀이겠지?",
  ui_story_6_1_73_dialog_content = "비록 백야성과 일루미나는 모두 방관하고 있지만,\n섀도우마스터는 나한테 너흴 맞이해 달라고 특별히 부탁했어.",
  ui_story_6_1_X73_dialog_content = "정말 곤란하게 만든다니까~",
  ui_story_6_1_74_dialog_content = "역시... 결정적인 순간에 조력자가 나타났어!",
  ui_story_6_1_F10_dialog_content = "「샤엘」이라고 불러. 무슨 도움이 필요하니?",
  ui_story_6_1_75_option_content = "혹시 누가 여기 들어온 걸 봤나요?",
  ui_story_6_1_76_dialog_content = "이곳은 평소에 오는 사람이 거의 없어. 하지만 최근에 암귀가 왔던 것 같아.\n그래도 아직 잃어버린 건 없어.",
  ui_story_6_1_77_dialog_content = "슈모르...",
  ui_story_6_1_78_dialog_content = "너희가 상대해야 하는 적이 지금 이 안에 있는 거야? 난 그게 좀 신경이 쓰이는걸.",
  ui_story_6_1_79_dialog_content = "난 그쪽이 방금 우리 얘기를 엿들은 게 더 신경이 쓰이는데?",
  ui_story_6_1_80_dialog_content = "음~ PlayerName, 파트너들이 꽤 예리한걸~",
  ui_story_6_1_81_dialog_content = "크흠, 샤엘 씨, 질문에 답하고 싶지 않다면 괜찮아요. 그럼 이곳에 대해 설명을 좀 해주시겠어요?",
  ui_story_6_1_82_dialog_content = "다들 알다시피 여긴 원래 폐허였어.",
  ui_story_6_1_83_dialog_content = "그래서 땅값이 저렴했고, 섀도우마스터가 이곳을 사들였어.\n그러니까 이곳을 가장 잘 아는 건 그 사람뿐이야.",
  ui_story_6_1_84_dialog_content = "이곳엔 경비병 같은 건 없어.\n하지만 함부로 침범한 자들의 결말은 「함정을 밟거나」, 「길을 잃거나」 둘 중 하나야.",
  ui_story_6_1_85_dialog_content = "그래서 물건이 보관된 방을 찾으려면 안내자가 필요해.",
  ui_story_6_1_86_dialog_content = "그럼 우리의 안내자는...",
  ui_story_6_1_87_dialog_content = "여기 누가 또 있니?",
  ui_story_6_1_88_dialog_content = "아! 당신이 하는 건가요... 그럼 부탁할게요.",
  ui_story_6_1_89_dialog_content = "응? 내가 언제 안내해준다고 했어?",
  ui_story_6_1_90_dialog_content = "정말 귀여운 아가씨네~ PlayerName, 정말 복도 많구나...",
  ui_story_6_1_91_dialog_content = "...샤엘 씨, 아무래도 뭔가 오해한 것 같은데요...",
  ui_story_6_1_92_dialog_content = "그럼 우리가 무엇을 찾고 있는지 알고 있어? 「화염 제어 모듈」에 대해 들어본 적은?",
  ui_story_6_1_93_dialog_content = "음... 모르겠는데...",
