  ui_story_6_1_124_dialog_content = "샤엘 씨, 그럼 우리가 무엇을 찾고 있는지 알고 있어? 「화염 제어 모듈」에 대해 들어본 적은?",
  ui_story_6_1_125_dialog_content = "음... 모르겠는데...",
  ui_story_6_1_126_dialog_content = "<size=30>거짓말이야.</size>",
  ui_story_6_1_127_dialog_content = "<size=30>알고 있어.</size>",
  ui_story_6_1_128_dialog_content = "샤엘 씨, 우리는 이곳에 멋대로 침입하려는 게 아니에요. 그 편지의 내용으로 증명할 수 있을 거예요.",
  ui_story_6_1_129_dialog_content = "알고 있어. 너희들은 그 「슈모르」라는 녀석을 막으려는 거지?",
  ui_story_6_1_130_dialog_content = "맞아요. 백야성에서 있었던 일에 대해선 이미 들었겠죠.",
  ui_story_6_1_131_dialog_content = "슈모르는 <color=#FFB400>「화염 제어 모듈」</color>을 손에 넣기 위해 어떤 수단도 가리지 않을 거예요.",
  ui_story_6_1_132_dialog_content = "녀석이 여기 올 거라는 걸 알게 된 후, 우린 즉시 섀도우마스터에게 이 소식을 전했어요.\n만약 대규모의 암귀가 나타난다면...",
  ui_story_6_1_F11_dialog_content = "움브라톤이 위험에 빠질 수도 있겠지... 음, 정말 진심 어린 걱정이네~ 믿지 않는 것도 힘들겠어.",
  ui_story_6_1_F12_dialog_content = "그런데, 그 사람이 여기 올 거라는 건 어떻게 알았어?",
  ui_story_6_1_F13_dialog_content = "그것도 말해줄 수 있어요... 전 아이테르의 감응 능력으로 녀석의 행적을 알아냈어요.",
  ui_story_6_1_134_dialog_content = "헤에? 역시 아이테르답게 신기한 능력이 있구나.\n그럼 네 정직함에 대한 보상으로, 내가 잠깐 동안 가이드가 되어줄게~",
  ui_story_6_1_135_dialog_content = "고마워요. 그럼 부탁드릴게요.",
  ui_story_6_1_136_dialog_content = "헤에~ 귀여워라~",
  ui_story_6_1_137_dialog_content = "...몇 층 더 남았죠? 곧 도착하나요?",
  ui_story_6_1_138_dialog_content = "아직 멀었어~ 이제 막 외곽에 도착했을 뿐인걸! 온 것보다 몇 배는 더 가야 해.",
  ui_story_6_1_139_dialog_content = "세상에, 여긴 자난성보다 더 복잡하네요.",
  ui_story_6_1_140_dialog_content = "왜 「화염 제어 모듈」을 이곳에 숨긴 거죠?",
  ui_story_6_1_141_dialog_content = "십여 년 전, 암귀와의 전쟁이 벌어졌을 때,\n섀도우마스터가 어느 버려진 전장에서 그걸 찾아냈다고 들었어.",
  ui_story_6_1_142_dialog_content = "나도 딱 한 번 본 적 있는데, 그냥 먼지가 잔뜩 쌓인 골동품 같았어.",
  ui_story_6_1_143_dialog_content = "너희가 아니었다면 그 물건은 이곳에 영원히 숨겨져 있었을지도 몰라.",
  ui_story_6_1_144_dialog_content = "잠깐. 이곳... 뭔가 이상해.",
  ui_story_6_1_145_dialog_content = "누가 이 문을 파괴한 것 같은데?",
  ui_story_6_1_146_dialog_content = "이 흔적을 보면 분명 오로리안은 아닐 것 같네.",
  ui_story_6_1_147_dialog_content = "휴우~ 난 정말 싸우고 싶지 않은데 말이야~",
  ui_story_6_1_148_dialog_content = "PlayerName, 뭔가 느껴져?",
  ui_story_6_1_149_dialog_content = "슈모르의 기운은 계속 느껴지고 있어.",
  ui_story_6_1_150_dialog_content = "역시 녀석이 먼저 선수를 친 건가. 녀석과의 거리는 어느 정도지?",
  ui_story_6_1_151_dialog_content = "가깝지도, 멀지도 않은 것 같아... 이제 암귀와 마주치게 될지도 몰라. 모두 조심해.",
  ui_story_6_1_152_dialog_content = "......",
  ui_story_6_1_153_dialog_content = "그럼 아직 따라잡을 수 있을 거야! 녀석은 가이드가 없으니 길을 잃었을 수도 있어.\n하지만 우리한테는 안내자가 있으니까...",
  ui_story_6_1_154_dialog_content = "이봐! 안내자! 어딜 가는 거지? 반대로 가야 하는 건가?",
  ui_story_6_1_155_dialog_content = "샤엘 씨, 혹시... 생각이 바뀐 건가요?",
  ui_story_6_1_156_dialog_content = "이해해요, 샤엘 씨. 지금 이건 무척 위험한 일이니까. 우리도 강요하진 않을게요.",
  ui_story_6_1_157_dialog_content = "확실히 위험한 일이지만, 전투에서 물러서는 사람은 함께 싸우는 동료에게 방해가 될 뿐이야.",
  ui_story_6_1_158_dialog_content = "너희들~ 내가 언제 「전투에서 물러선다」고 했어? 난 끝까지 너희들을 안내할 거라고~",
  ui_story_6_1_159_dialog_content = "하지만 난 싸우는 건 잘 못 하거든~ 그래서 너희와 같이 움직이진 않을 거야~",
  ui_story_6_1_160_dialog_content = "하지만 같이 안 움직이면 어떻게 안내해줄 거죠? 설마 원격으로 안내를...",
  ui_story_6_1_161_dialog_content = "귀여운 바이스의 말대로야~ 난 이곳에서 너희와 연락을 주고받을게.",
  ui_story_6_1_162_dialog_content = "너희가 주변의 모습을 대강 알려주면 내가 구체적인 위치를 알 수 있어~",
  ui_story_6_1_163_dialog_content = "저럴 줄 알았어... 저런 게 바로 움브라톤의 처세술이라고, 바이스.",
  ui_story_6_1_164_dialog_content = "하지만 방금 전 원격 지시를 해달라는 뜻이 아니었는데요...\n샤엘 씨... 역시 함께 가는 게 좋을 것 같아요.",
  ui_story_6_1_165_dialog_content = "오? 그것도 괜찮네~ 그럼 난 바깥에서 너흴 기다리고 있을게~\n원격으로 지시해줄 테니까 계속 연락하자고~",
  ui_story_6_1_168_dialog_content = "그리고 만약 살아서 나올 수 있다면, PlayerName...",
  ui_story_6_1_169_dialog_content = "우리 가게에 오는 거 잊지 마. 이제 우린 친구라고 할 수 있으니까 지인 할인도 해줄게~",
  ui_story_6_1_170_dialog_content = "그럼 행운을 빌게~",
  ui_story_6_1_171_dialog_content = "저 샤엘 씨는 분명히 장사를 아주 잘하는 상인일 것 같아...",
  ui_story_6_1_172_dialog_content = "저기, 설마 내가 말실수를 해서 이렇게 된 건 아니지? 「원격 지시」 말이야...",
  ui_story_6_1_173_dialog_content = "신경 쓰지 마, 바이스. 차라리 지금 저렇게 물러서는 게 중요한 순간에 발목 잡히는 것보다 나아.",
