  ui_story_6_1_175_dialog_content = "긴장할 거 없어. 이 앞을 막는 자가 누구라 해도, 내가 본때를 보여주겠어.",
  ui_story_6_2_X29_dialog_content = "아...? 흐음... 음...",
  ui_story_6_2_X30_dialog_content = "카론 님? 왜 갑자기 이상한 소리를 내는 거다냥?",
  ui_story_6_2_X31_dialog_content = "필리시 양, 여전히 안색이...",
  ui_story_6_2_X32_dialog_content = "수면 부족인가.",
  ui_story_6_2_X33_dialog_content = "사실 난 지금 상부의 회의가 끝나기를 기다리고 있다. 28호 지하성의 경비 결산 때문에 말이지...",
  ui_story_6_2_X34_dialog_content = "다들 가버렸으니 다음에 얘기하라냥.",
  ui_story_6_2_X35_dialog_content = "왜 다들 이렇게 빨리 가는 거냐! 아직 지급하지 못한 수당이 잔뜩 있단 말이다!",
  ui_story_6_2_X36_dialog_content = "어쩔 수 없다냥. 다들 긴급 명령에 따라 방어선을 구축하러 주변 구역으로 향했다냥.",
  ui_story_6_2_X37_dialog_content = "휴, 바이스가 벌써 <color=#FFB400>속삭이는 회랑</color>에 위험 요소가 있다고 보고했는데...",
  ui_story_6_2_X38_dialog_content = "대원수님은 왜 이런 결정을 내린 건지 필리시는 전혀 모르겠다냥...",
  ui_story_6_2_X39_dialog_content = "음? 잠깐, 잠깐. 갑자기 정보량이 너무 많잖아.",
  ui_story_6_2_X40_dialog_content = "좀 더 자세히 설명해 줄 수 있겠나? 바이스와 PlayerName 일행이 또 곤경에 처한 건가?",
  ui_story_6_2_X41_dialog_content = "곤경? 에, 뭐라고 해야 하냥. 어쩌면 「<color=#FFB400>사상 최악의 재앙</color>」일지도 모르겠다냥...",
  ui_story_6_2_X42_dialog_content = "재앙?!",
  ui_story_6_2_1_dialog_content = "...이미 꽤 온 것 같은데.",
  ui_story_6_2_2_dialog_content = "나조차도 짙은 암귀의 기운을 느낄 수 있을 정도야.",
  ui_story_6_2_3_dialog_content = "샤엘 씨...",
  ui_story_6_2_4_dialog_content = "음? 여기 있어.",
  ui_story_6_2_6_dialog_content = "달링~ 길을 잃은 거야?",
  ui_story_6_2_7_dialog_content = "길을 잃지는 않았어. 하지만 이곳은 확실히 미궁처럼 복잡하네. 게다가 어두컴컴해서 답답하다고.",
  ui_story_6_2_9_dialog_content = "다들 좀 봐. 여기 흔적이 뭔가 이상해. 암귀의 발자국도 있고, 게다가...",
  ui_story_6_2_10_dialog_content = "이건 「군화」 발자국 같은데?",
  ui_story_6_2_11_dialog_content = "군화? 이건...",
  ui_story_6_2_12_dialog_content = "오로리안의 기운이 느껴져. 지원군일까?!",
  ui_story_6_2_13_dialog_content = "백야성의 제식 군화야. 틀림없어. 게다가 호위대 소속이야.",
  ui_story_6_2_14_dialog_content = "발자국이 뚜렷한 걸 보면 전투는 없었어. 심지어... 그 어떤 두려움도 느껴지지 않아.",
  ui_story_6_2_15_dialog_content = "발자국만 보고도 그렇게 많이 알아낼 수 있는 거야?",
  ui_story_6_2_16_dialog_content = "<color=#FFB400>거츠더</color>야.",
  ui_story_6_2_X16_dialog_content = "거츠더? 거츠더라면 그때...",
  ui_story_6_2_17_option_content = "스예트를 추격할 때 들었던 것 같아.",
  ui_story_6_2_18_option_content = "그때 「싱크탱크 컴포넌트」를 훔쳐 간 녀석?",
  ui_story_6_2_19_dialog_content = "맞아. 하지만 거츠더는 실종되지 않았어?",
  ui_story_6_2_20_dialog_content = "우릴 배신하고 도망쳐서 이클립스에 빌붙었지. 증거도 확실해...",
  ui_story_6_2_21_dialog_content = "그와 그의 연인은 이미 오래전부터 암귀를 위해서 일해 왔어. 이건 백야성의 수치나 다름없다고.",
  ui_story_6_2_22_dialog_content = "하필 이때 이곳에 암귀와 함께 움직이고, 호위대의 군화를 신고 있을 녀석은...",
  ui_story_6_2_23_dialog_content = "거츠더밖에 없어!",
  ui_story_6_2_24_dialog_content = "대체 어째서 그러는 거지?",
  ui_story_6_2_25_dialog_content = "그건 아무도 몰라.",
  ui_story_6_2_26_dialog_content = "거츠더는 성실하게 일했다고 들었어. 전쟁 영웅이기도 했고.\n그러니 그 누구도 그를 의심하지 않았던 거야.",
  ui_story_6_2_27_dialog_content = "설마 거츠더는 스예트의 일로 악심을 품은 걸까? 그럼 이곳에 온 건...",
  ui_story_6_2_28_dialog_content = "주인을 따라 떠도는 패배자일 뿐이야. 마침 잘 됐어.",
  ui_story_6_2_29_dialog_content = "이번에 마주친다면, 녀석을 슈모르와 함께 이곳에 묻어버리겠어!",
  ui_story_6_2_30_dialog_content = "쳇, 지겨워 죽겠네. 길이 꼭 구불구불한 창자 같잖아!\n게다가 자꾸 누군가가 계속 지켜보는 느낌이 든단 말이지...",
  ui_story_6_2_31_dialog_content = "지긋지긋해! 거츠더, 노래나 한번 불러봐.",
  ui_story_6_2_32_dialog_content = "......",
  ui_story_6_2_33_dialog_content = "거츠더, 그 눈빛은 뭐야?",
  ui_story_6_2_34_dialog_content = "스예트를 죽인 녀석이 왔는데, 기쁘게 전투의 노래라도 불러야 하는 거 아니야?",
  ui_story_6_2_35_dialog_content = "놈들이 쫓아왔다. 네가 말한 대로...",
  ui_story_6_2_36_dialog_content = "스예트를 죽인... 그놈들이 오고 있다는 거지?",
  ui_story_6_2_37_dialog_content = "그래. 그 열등한 잔챙이들은 놈들의 발목조차 잡지 못할 줄 알았다니까... 정말 끈질기네.",
  ui_story_6_2_39_dialog_content = "스예트는...",
  ui_story_6_2_40_dialog_content = "처참했지. 거츠더, 나조차도 끔찍하다고 생각할 정도였는걸.",
  ui_story_6_2_41_dialog_content = "어째서! 그 둘은...",
  ui_story_6_2_42_dialog_content = "스예트는 내게 영광스러운 임무라고 말했단 말이다! 어째서 너와 그분께 도움을 청하지 않은 거지?",
  ui_story_6_2_A1_dialog_content = "아니, 그녀의 성격이라면 분명히 도움을 청했을 거야... 그럼 설마...",
  ui_story_6_2_43_dialog_content = "왜 소리를 지르고 그래?",
  ui_story_6_2_44_dialog_content = "...미안하다.",
  ui_story_6_2_45_dialog_content = "PlayerName 녀석이 가련한 스예트를 죽게 만들었다고 들었어.",
  ui_story_6_2_46_dialog_content = "네가 스예트를 풀어주자 다운타운은 혼란에 빠졌지. 업타운 녀석들은 신경 쓸 생각도 없었고.",
  ui_story_6_2_47_dialog_content = "하지만 PlayerName 녀석과 그 두 「사냥개」가 둘을 끝까지 쫓은 거야.",
  ui_story_6_2_48_dialog_content = "...빌어먹을 놈들!",
  ui_story_6_2_49_dialog_content = "맞아. 물건도 못 훔친 도둑을 때려죽이다니, 정말 어이없지 않아?",
  ui_story_6_2_50_dialog_content = "결국 궁지에 몰린 스예트와 그 여동생은... 휴... 끔찍한 괴물로 변해버린 거야.",
  ui_story_6_2_51_dialog_content = "...스예트... 스예트...",
  ui_story_6_2_52_dialog_content = "하고 싶은 게 있다면 지금 바로 가서 해도 돼.",
  ui_story_6_2_53_dialog_content = "내가 찾는 「화염 제어 모듈」은 바로 이 앞에 있을 거야. 넌 어쩔 생각이야?",
  ui_story_6_2_54_dialog_content = "PlayerName──!",
  ui_story_6_2_55_dialog_content = "오? 복수할 준비는 다 된 모양이네.",
  ui_story_6_2_56_dialog_content = "──엣취!",
  ui_story_6_2_57_dialog_content = "왜 그래, PlayerName? 너무 추워서 그래?",
  ui_story_6_2_58_dialog_content = "아니... 이상하게 온몸에 소름이 돋았지 뭐야.",
  ui_story_6_2_59_dialog_content = "PlayerName, 넌 아이테르니까, 이곳의 다크매터가 네게는 너무 짙을 수도 있겠네.",
  ui_story_6_2_60_dialog_content = "조금만 더 버텨. 아직 처리해야 할 적이 많으니까.",
  ui_story_6_2_61_dialog_content = "알고 있어... 그럼 계속 이동하자...",
  ui_story_6_6_1_dialog_content = "아무래도 이상한 곳으로 와버린 것 같은데. 샤엘 씨!",
  ui_story_6_6_2_dialog_content = "냠냠... 응?",
  ui_story_6_6_3_dialog_content = "샤엘 씨... 뭘 먹고 있는 건가요?",
  ui_story_6_6_4_dialog_content = "어... 음, 차랑 디저트를 좀 먹었어... 무슨 일이야?",
  ui_story_6_6_5_dialog_content = "그러니까 이 길이 「<color=#FFB400>화염 제어 모듈</color>」이 있는 곳으로 가는 게 맞죠?",
  ui_story_6_6_6_dialog_content = "아... 당연하지! 내가 얼마나 힘들게 「화염 제어 모듈」이 있을 법한 곳을 기억해 낸 건데.",
  ui_story_6_6_7_dialog_content = "남의 말을 잘 믿어야지, 달링~ 아, 맞다. 앞에 있는 함정 조심해~",
  ui_story_6_6_8_dialog_content = "잠깐. 뭔가 느껴져...",
  ui_story_6_6_9_dialog_content = "암귀인가?",
  ui_story_6_6_10_dialog_content = "아니. 오로리안... 같아.",
  ui_story_6_6_11_dialog_content = "오로리안? 샤엘 씨, 그쪽에서 들어온 사람은 없었지?",
  ui_story_6_6_12_dialog_content = "파리 한 마리도 안 들어갔어.",
  ui_story_6_6_13_dialog_content = "그럼 거츠더겠지... 어쩌면 전방에 매복이 있을지도 몰라.",
  ui_story_6_6_14_dialog_content = "매복?",
  ui_story_6_6_15_dialog_content = "이 앞은 교차로인 데다 함정도 있어.",
  ui_story_6_6_16_dialog_content = "거기에 오랫동안 방치된 탓에 지붕이 무너지거나 땅이 꺼질 수도 있으니,\n최고의 매복 장소라고 할 수 있어.",
  ui_story_6_6_17_dialog_content = "그는 한때 기사였지만, 이젠 이클립스에 빌붙은 이상 어떤 짓을 벌일지는 아무도 몰라.",
  ui_story_6_6_18_dialog_content = "내가 앞장설게. 거츠더... 녀석에게 공정한 심판을 내려주겠어.",
  ui_story_6_7_1_dialog_content = "휴... 위험했어. 카렌이 주의를 줘서 망정이지, 안 그랬으면 조금 전에 함정에 빠졌을 거야.",
  ui_story_6_7_2_dialog_content = "나도 여러 번 경고했잖아. 맞지?",
  ui_story_6_7_3_dialog_content = "방금 하늘에서 떨어진 화염병 함정에 하마터면 귀여운 PlayerName의 목숨이 날아갈 뻔했잖아.",
  ui_story_6_7_4_dialog_content = "정말 깜짝 놀라 죽는 줄 알았다구요...",
  ui_story_6_7_5_dialog_content = "이게 거츠더의 전략이야. 녀석은 이미 암귀처럼 뻔뻔하고 비열하게 변했어...",
  ui_story_6_7_6_dialog_content = "호랑이도 제 말하면 온다더니.",
  ui_story_6_7_7_dialog_content = "...네놈들이...",
  ui_story_6_7_8_dialog_content = "네놈들이... 감히 스예트를... 죽이다니!",
  ui_story_6_7_9_dialog_content = "역시... 복수하러 온 거였어.",
  ui_story_6_7_10_dialog_content = "복수? 그래, 방금의 함정에 당하지 않은 건 정말 아쉽군...",
  ui_story_6_7_11_dialog_content = "너흴 그냥 죽이는 것만으로는 내 원한이 풀리지 않을 테니까!",
  ui_story_6_7_F1_dialog_content = "우릴 죽이고 싶다고?!",
  ui_story_6_7_12_dialog_content = "거츠더! 백야성의 기사로서 명예를 저버리고 암귀에게 투항하다니... 결코 용서할 수 없다!",
  ui_story_6_7_13_dialog_content = "용서? 내가 네 용서가 필요한가? 난 한때 백야성의 기사였지만, 이제는 암귀의 정예 수하다...",
  ui_story_6_7_14_dialog_content = "하지만 이건 모두 스예트를 위해서였어! 그런데 그녀를... 너희가...",
  ui_story_6_7_15_dialog_content = "암귀보다 더 잔인한 게 바로 네놈들이야... 네놈들이 스예트를 죽였어!",
  ui_story_6_7_16_dialog_content = "거츠더! 스예트... 그들은 스스로 죽음을 선택했어!",
  ui_story_6_7_17_dialog_content = "거츠더, 그 두 사람이 고통에서 해방되고 싶어서 죽음을 택한 거야...",
  ui_story_6_7_18_dialog_content = "그럴 리 없어!",
  ui_story_6_7_19_dialog_content = "스예트는... 항상 자유를 동경했다.\n너희가 궁지로 몰아넣은 게 아니라면 죽음을 선택할 리 없단 말이다!",
  ui_story_6_7_20_dialog_content = "슈모르가 우릴 막으라고 널 보낸 거지?",
  ui_story_6_7_21_dialog_content = "아니, 난 복수를 위해 온 거다. 너희, 그리고 백야성에게 말이다!",
  ui_story_6_7_22_dialog_content = "슈모르가 뭘 하든... 나와는 상관없다.",
  ui_story_6_7_23_dialog_content = "배신자가 첩자를 위해 복수한다고?",
  ui_story_6_7_27_dialog_content = "......",
  ui_story_6_7_28_dialog_content = "카렌, 녀석의 증오가 더 강해지고 있어. 조심해...",
  ui_story_6_7_29_dialog_content = "증오? 그건 배신자가 태어날 때부터 지닌 감정일 뿐이야!",
  ui_story_6_7_30_dialog_content = "저들은 더는 갈 곳이 없거든. 그러니까 증오를 품는 거라고...",
  ui_story_6_7_31_dialog_content = "그저 심판자를 원망하고, 자신의 돌이킬 수 없는 과거를 원망하고, 미래가 없다는 걸 원망할 뿐.",
  ui_story_6_7_32_dialog_content = "그런 녀석들과는 대화할 가치도 없어.",
  ui_story_6_7_33_dialog_content = "백야성의 호위대장이자 성주의 딸인 네가 우릴 이해할 수 있을 거라 생각하나?",
  ui_story_6_7_34_dialog_content = "설령 내가 배신자가 아니었더라도, 넌 내 증오를 이해하지 못했을 거다!",
  ui_story_6_7_35_dialog_content = "난 그저 너희가 스예트를 죽게 만든 걸 증오할 뿐이다!",
  ui_story_6_7_36_dialog_content = "그래. 스예트는 암귀가 되었고, 너희는 오로리안이지.\n적으로서 전장에서 죽는 건 스예트의 운명이었을 거다.",
  ui_story_6_7_37_dialog_content = "하지만 스예트를 그 지경까지 몰아넣은 건! 바로 네놈들이잖아!",
  ui_story_6_7_38_dialog_content = "모, 모습이 변했어...!",
  ui_story_6_7_39_dialog_content = "복수... 복수하겠어... 너처럼 말이야, PlayerName.",
  ui_story_6_7_40_dialog_content = "우린... 똑같다. 복수의 길에 올라선 이상... 다시는 돌이킬 수 없다...",
  ui_story_6_7_41_dialog_content = "나처럼? 무슨 뜻이지...?",
  ui_story_6_7_42_dialog_content = "암귀처럼 변할 수 있다니... 네 주인한테 힘이라도 빈 거냐?!",
  ui_story_6_7_43_dialog_content = "...복수하겠다! PlayerName! 이제 서로의 검 아래 죽을 뿐이다!",
  ui_story_6_7_44_dialog_content = "함께 저승에서 스예트한테 용서를 비는 거다!",
  ui_story_6_7_45_dialog_content = "물러서, PlayerName! 전투를 지원해!",
  ui_story_6_7_X45_dialog_content = "스예트... 내가 졌어...",
  ui_story_6_7_48_dialog_content = "심판을 받아들일 준비는 됐나? 배신자.",
  ui_story_6_7_49_dialog_content = "......",
  ui_story_6_7_50_dialog_content = "어째서 아무 말도 안 하는 거지? 죽음을 앞두니 드디어 후회가 되는 건가?",
  ui_story_6_7_51_dialog_content = "아니. 난 후회하지 않는다. 난 내 결말을 알고 있었으니까.",
  ui_story_6_7_52_dialog_content = "지금은 그저... 스예트의 마지막 순간이 어땠는지 알고 싶을 뿐이다.",
  ui_story_6_7_53_dialog_content = "네가 그걸 알 필요는 없어!",
  ui_story_6_7_F2_dialog_content = "잠깐만! 역시 이 일을 해명하는 게 좋을 것 같아...",
  ui_story_6_7_54_dialog_content = "우리가 스예트를 추격한 건 사실이야. 하지만 우린 그들의 목적을 알아내려 했을 뿐이야.",
  ui_story_6_7_55_dialog_content = "맞아, 죽일 생각은 전혀 없었어.",
  ui_story_6_7_56_dialog_content = "하지만 그들은 도망치기 위해 어떤 암귀에게 도움을 청했어.",
  ui_story_6_7_57_dialog_content = "...슈모르인가?",
  ui_story_6_7_58_dialog_content = "아니... 그 기운은 슈모르가 아니었어. 다른 녀석, 슈모르보다 훨씬 더 강한 녀석이었어.",
  ui_story_6_7_59_dialog_content = "그리고 그들의 몸에 엄청난 변화가 일어났지. 마치 양초처럼... 융합해버린 거야.",
  ui_story_6_7_60_dialog_content = "게다가 그건 두 사람이 스스로 융합하고 있다기보다는...",
  ui_story_6_7_61_dialog_content = "어떤 저항할 수 없는 힘에 의해 억지로 당하고 있는 것 같았어...",
  ui_story_6_7_62_dialog_content = "그럼 그 뒤엔...!",
  ui_story_6_7_63_dialog_content = "우린 결국 스예트를 죽일 수밖에 없었어.",
  ui_story_6_7_64_dialog_content = "...그녀는 고통스럽게 떠났나?",
  ui_story_6_7_65_dialog_content = "그건...",
  ui_story_6_7_66_option_content = "아주 고통스럽게 떠났어.",
  ui_story_6_7_67_dialog_content = "<anim type=Shake><size=45>...빌어먹을...!</size></anim>",
  ui_story_6_7_69_dialog_content = "우리가 그들과 싸우려고 하기 전부터, 이미 누군가가 그들의 몸에 힘을 불어넣었어...",
  ui_story_6_7_70_dialog_content = "그리고 강제로 둘을 융합시켜 암귀로 만들어 버렸지. 그게 그들이 고통스러워 했던 진짜 이유야.",
  ui_story_6_7_71_option_content = "우리가 고통을 덜어줬어.",
  ui_story_6_7_72_dialog_content = "너희가... 그녀를 해방시켜준 건가?",
  ui_story_6_7_73_dialog_content = "그래. 우리도 그들이 고통에 몸부림치는 걸 보고만 있을 순 없었으니까.",
  ui_story_6_7_74_dialog_content = "우리가 그들과 싸우려고 하기 전부터, 이미 누군가가 그들의 몸에 힘을 불어넣었어...",
  ui_story_6_7_75_dialog_content = "그리고 강제로 둘을 융합시켜 암귀로 만들어 버렸지. 그게 그들이 고통스러워 했던 진짜 이유야.",
  ui_story_6_7_76_dialog_content = "어쩌면 그건 자신들의 후회에서 비롯된 것일지도 몰라.",
  ui_story_6_7_78_dialog_content = "특히 스예트가 그때... 우리와 싸우는 걸 망설이고 있는 걸 느낄 수 있었어.",
  ui_story_6_7_79_dialog_content = "그저 도망치고 싶었고, 백야성을 떠나서 먼 곳으로 가고 싶었을 거야...",
  ui_story_6_7_80_dialog_content = "그리고... 마지막에 어떤 꽃에 대해 말했던 것 같아.",
  ui_story_6_7_81_dialog_content = "꽃...?",
  ui_story_6_7_82_option_content = "「민들레」.",
  ui_story_6_7_83_dialog_content = "<size=45>...!</size>",
  ui_story_6_7_84_dialog_content = "우린 그 말에 담긴 뜻을 알 수 없었지만, 넌... 아마 알고 있겠지.",
  ui_story_6_7_85_dialog_content = "...미안해... 정말 미안해, 스예트...",
  ui_story_6_7_86_dialog_content = "넌 분명히 내게 말했어... 난 알아챘어야만 했어... 그때의 우리에겐 아직 기회가 있었는데...",
  ui_story_6_7_87_dialog_content = "거츠더, 거츠더, 근처에 어디 재미있는 곳 없을까?",
  ui_story_6_7_88_dialog_content = "놀러 가려고?",
  ui_story_6_7_89_dialog_content = "놀자는 게 아냐. 혹시 속삭이는 회랑이라고 알아?",
  ui_story_6_7_90_dialog_content = "거긴 무척 비밀스러운 곳인 것 같아.\n거기 가면 아무도 우릴 찾을 수 없을 거야! 거기서 평생 살 수도 있을걸!",
  ui_story_6_7_91_dialog_content = "아니면 레디젤 사막도 나쁘지 않을 것 같아. 조금 덥긴 하겠지만.",
  ui_story_6_7_92_dialog_content = "백야성을 떠나겠다고? 어느 귀족한테 미움이라도 산 거야?",
  ui_story_6_7_93_dialog_content = "백야성이 아니라... 이클립스야.",
  ui_story_6_7_94_dialog_content = "난 민들레가 되고 싶어.",
  ui_story_6_7_95_dialog_content = "음? 왜 갑자기 그렇게 말하는 건데?",
  ui_story_6_7_96_dialog_content = "민들레는 절대 붙잡히지 않잖아. 수천 개의 작은 자신들로 변해서 바람을 타고 날아가니까.",
  ui_story_6_7_97_dialog_content = "그렇게 날고... 또 날아서... 이 세상 어디든지 갈 수 있어.",
  ui_story_6_7_98_dialog_content = "사실 그 「작은 자신들」은 민들레의 씨앗이야... 그리고 물에 떨어지면 어쩔 건데?",
  ui_story_6_7_99_dialog_content = "당신 정말! 쳇... 말 안 해!",
  ui_story_6_7_100_dialog_content = "자유... 그래. 스예트는 항상 백야성을 떠나고 싶다고 했었지. 이클립스 때문에 말이야.",
  ui_story_6_7_101_dialog_content = "그녀는 나와 함께... 민들레처럼... 멀리 날아가고 싶다고 했다.",
  ui_story_6_7_102_dialog_content = "넌 정말 무지하구나, 거츠더. 이클립스야말로 세상 만물의 종점이야. 아니, 이건 진리라고...",
  ui_story_6_7_103_dialog_content = "...정말 PlayerName 그놈이 스예트를 죽였나?",
  ui_story_6_7_104_dialog_content = "어떻게 된 건지 이미 설명했잖아. 그렇게 의심이 많아서야... 내 기대가 너무 컸던 걸까?",
  ui_story_6_7_105_dialog_content = "네 나약함을 거두고, 우리에 대한 불신을 버려, 거츠더.",
  ui_story_6_7_106_dialog_content = "하나만 기억하면 돼. 그들은 살아남을 수 있었어. 그런데 PlayerName 그자가 그들의 운명을 바꾼 거야.",
  ui_story_6_7_107_dialog_content = "바꾼 거라고. 네 운명을...",
  ui_story_6_7_108_dialog_content = "아니! 아니야! 거짓말! 거짓말이다!",
  ui_story_6_7_109_dialog_content = "거츠더!",
  ui_story_6_7_110_dialog_content = "나, 난... 스예트, 스예트... 스예트는 떠나려고 했는데, 왜 융합을 하겠어?!",
  ui_story_6_7_111_dialog_content = "우린 다크매터를 사용할 수 없어. 스예트 자매를 암귀로 융합시킬 수 있는 힘은 다크매터뿐이야.",
  ui_story_6_7_112_dialog_content = "두 사람에게 다크매터를 주입한 게 슈모르가 아니라면, 슈모르와 관계가 있는 암귀일 거야.",
  ui_story_6_7_113_dialog_content = "...그 녀석, 그 녀석이야, 그, 그 녀석이라고...!",
  ui_story_6_7_114_dialog_content = "거츠더... 알고 있는 게 있어?",
  ui_story_6_7_116_dialog_content = "......",
  ui_story_6_7_119_dialog_content = "<color=#FFB400>슈모르</color>가... 어디에 있는지 알고 있다.",
  ui_story_6_8_1_dialog_content = "카렌... 녀석이 정말 우릴 슈모르한테 데려가 줄까?",
  ui_story_6_8_2_dialog_content = "가는 길에 암귀가 별로 없는 것도 뭔가 이상해. 설마 또 다른 함정은 아니겠지?",
  ui_story_6_8_F1_dialog_content = "또 다른 함정이라니?",
  ui_story_6_8_3_dialog_content = "녀석이 다시 배신한다면 내가 다시 쓰러트리면 돼. 하지만 이번엔... 그 어떤 동정도 없을 거야.",
  ui_story_6_8_F2_dialog_content = "......",
  ui_story_6_8_4_dialog_content = "미안해, 거츠더... 우린 여전히 널 의심할 수밖에 없어. 하지만 반박하고 싶다면 말해도 좋아.",
  ui_story_6_8_5_dialog_content = "배신자가 뭘 반박할 수 있겠어?",
  ui_story_6_8_6_dialog_content = "아... 배신자라, 한때는 백야성의 영웅이었는데 말이지.",
  ui_story_6_8_7_dialog_content = "난 열여덟 살 때 정식 기사가 됐었다. 그것도 성주에게 직접 임명을 받았다고.",
  ui_story_6_8_8_dialog_content = "<color=#FFB400>「어둠의 위기」</color>, 너희도 알고 있겠지.",
  ui_story_6_8_9_dialog_content = "17년 전에 시작돼서 오랜 시간 지속됐던 전쟁 말이지...",
  ui_story_6_8_10_dialog_content = "17년 전... 암귀가 아이테르들이 사는 곳을 습격했지.\n그 습격은 아무런 징조도 없었고, 백야성조차 크게 당황했었다.",
  ui_story_6_8_11_dialog_content = "그 후, 우린 긴급 훈련 명령을 받았다...\n언제 닥칠지 모르는 암귀의 대규모 습격에 맞서기 위해서였지.",
  ui_story_6_8_12_dialog_content = "명령을 받았을 때의 난 너희보다 어렸다. 이제 막 기사의 수행원이 되었었지.",
  ui_story_6_8_13_dialog_content = "난 맹훈련을 거쳐 백야성 호위대에서 4년간 보결로 복무했었다.",
  ui_story_6_8_14_dialog_content = "그러다 너한테 기회가 찾아왔지.",
  ui_story_6_8_15_dialog_content = "그래. 어느 화창한 아침이었다. 백야성에서는 움브라톤을 습격한 암귀를 막기 위해\n군대를 출병시켰고, 성에는 방어 병력이 부족했다.",
  ui_story_6_8_16_dialog_content = "그때 한 암귀가 백야성의 다운타운 구역에 침입했고... 나는 위험에 처한 귀족 소녀를 구했다.",
  ui_story_6_8_19_dialog_content = "그 후 나는 호위대를 따라 출전했고, 내가 용감하게 나선 덕분에...",
  ui_story_6_8_20_dialog_content = "돌아온 후 얼마 지나지 않아 성주는 직접 날 기사로 임명했지.",
  ui_story_6_8_22_dialog_content = "듣기에는 아주 좋은 시작 같은데.",
  ui_story_6_8_23_dialog_content = "그래. 마치 동화처럼 난 「기사와 공주님의 결혼」이라는 멋진 결말을 맞이했다.",
  ui_story_6_8_27_dialog_content = "한 달 뒤, 난 그 귀족 소녀와... 결혼식을 올렸다.",
  ui_story_6_8_28_dialog_content = "그 사람이 스예트인 거지?",
  ui_story_6_8_29_dialog_content = "아니.",
  ui_story_6_8_30_dialog_content = "...?!",
  ui_story_6_8_31_dialog_content = "그녀는 귀족 가문의 아가씨였다. 차녀였지만 말이지.",
  ui_story_6_8_32_dialog_content = "하지만 우리의 신분 차이는 개인의 노력으로 메꿀 수 없는 것이었다...",
  ui_story_6_8_33_dialog_content = "아내의 가문은 그녀에게 힘이 되어줬지만, 그녀를 무너지게 만들기도 했지...",
  ui_story_6_8_34_dialog_content = "달콤했던 날들은 점차 무미건조해졌고, 비교와 불만, 원망과 다툼이 이어지며, 끝내는 무감각해졌지.",
  ui_story_6_8_35_dialog_content = "몇 년 후, 난 그녀에게 마치 길가의 돌멩이 같은 존재가 되어 있었다.",
  ui_story_6_8_36_dialog_content = "내가 사라져 주길 바랬던 건 그녀였고... 그러다 난 스예트를 만나게 되었지.",
  ui_story_6_8_45_dialog_content = "그녀는 내 얼어붙은 듯한 삶에 소년 시절의 잔잔한 물결을 만들어냈다.",
  ui_story_6_8_46_dialog_content = "그녀를 보면 마치 젊은 시절로 돌아간 것 같았지.",
  ui_story_6_8_47_dialog_content = "가문이나 지위 따위는 아무래도 좋았다.\n난 그저 전장에서 공을 세워, 사랑하는 사람의 마음을 얻고 싶었을 뿐이었으니까...",
  ui_story_6_8_49_dialog_content = "집어 치워! 거츠더, 그 누구도 널 동정하지 않아.",
  ui_story_6_8_50_dialog_content = "네가 끝내 저지른 짓을 봐.",
  ui_story_6_8_51_dialog_content = "아내를 배신하고, 암귀와 결탁해 경비병을 습격하고, 모두에게 해를 끼쳤어!",
  ui_story_6_8_53_dialog_content = "한때는 백야성의 영웅이였을지도 모르지만, 지금은 그저 신의를 저버린 죄인일 뿐이야!",
  ui_story_6_8_54_dialog_content = "크큭... 하하하하! 그래, 난 백야성을 배신했지. 용서받을 수 없는 죄라고.",
  ui_story_6_8_F3_dialog_content = "하지만 난 내가 잘못했다고 생각하지 않는다. 난 그저 진정한 사랑을 추구했을 뿐...",
  ui_story_6_8_55_dialog_content = "이해할 수 없어. 정말...터무니없잖아.",
  ui_story_6_8_63_dialog_content = "그래서 이야기는 끝난 거야?",
  ui_story_6_8_64_dialog_content = "미안해요, 샤엘 씨... 완전히 잊고 있었네요!",
  ui_story_6_8_65_dialog_content = "난 그냥 거츠더가 잘못된 길로 안내하진 않았다는 걸 말해주려던 참이었어...",
  ui_story_6_8_66_dialog_content = "지금 안내하는 방향은 내가 기억하고 있는 길과 일치해. 게다가 함정 같은 곳도 피해 가고 있어.",
  ui_story_6_8_67_dialog_content = "......",
  ui_story_6_8_68_dialog_content = "난 너희들의 이해를 바라는 게 아니다. 말했지 않나. 슈모르에게 데려가 주겠다고.\n그리고... 난 내가 해야 할 일이 있다.",
  ui_story_6_9_1_dialog_content = "역시나 기회주의자답네.",
  ui_story_6_9_2_dialog_content = "거츠더 말이야?",
  ui_story_6_9_3_dialog_content = "아무래도 네 설득력은 PlayerName보다 못한 모양이야.",
  ui_story_6_9_4_dialog_content = "그래서 어쨌다는 거야? 거츠더가 우릴 배신할 거라는 건 알고 있었어.\n그저 내가 예상한 시기와 맞지 않았을 뿐이지...",
  ui_story_6_9_5_dialog_content = "PlayerName 때문에 그래?",
  ui_story_6_9_6_dialog_content = "그래. 저들이 거츠더를 살려둘 줄은 몰랐어. 전부 PlayerName의 수작이겠지. 정말 위선적이네.",
  ui_story_6_9_7_dialog_content = "똑똑한 거겠지. 역시 넌 「예상」 같은 건 하지 마, 슈모르. 머리 쓰는 건 너랑 어울리지 않아.",
  ui_story_6_9_8_dialog_content = "언젠간 반드시 네 목을 비틀어 주겠어...",
  ui_story_6_9_9_dialog_content = "흥, 어차피 우리가 저들보다 빨라. 벌써 「<color=#FFB400>화염 제어 모듈</color>」의 기운이 느껴지거든.",
  ui_story_6_9_10_dialog_content = "모듈을 손에 넣으면 거기서 PlayerName 녀석을 기다릴 거야. 그리고...",
  ui_story_6_9_11_dialog_content = "일망타진.",
  ui_story_6_9_12_dialog_content = "하, 그래. 일망타진. 그 단어 참 마음에 들어.",
  ui_story_6_9_13_dialog_content = "넌 어휘력을 좀 늘릴 필요가 있겠어.\n어쨌든 조심하는 게 좋을 거야. 그자들 뒤에는 백야성과 일루미나가 있으니까.",
  ui_story_6_9_14_dialog_content = "놈들의 군대는 오지 않을 거야. 오로리안들 사이에는 우스꽝스러운 의심과 간극이 가득하거든.",
  ui_story_6_9_15_dialog_content = "아니면 와서 감상할래? 녀석들 표정이 정말 볼만할 거야.",
  ui_story_6_9_16_dialog_content = "됐어. 너도 알잖아. 난 싸우는 게 싫어.",
  ui_story_6_9_17_dialog_content = "하지만 널 위해 내가 조수 하나를 준비했어.\n아니지, 저들에게 줄 <color=#FFB400>선물</color>이라고 해야 하나?",
  ui_story_6_9_18_dialog_content = "선물? 조수? 오오! 설마 그 녀석이야?",
  ui_story_6_9_19_dialog_content = "맞아. 저들의 <color=#FFB400>오래된 친구</color>야. 내가 조금 더 「강하게」 만들어줬어.",
  ui_story_6_9_20_dialog_content = "역시 너도 놀아줄 의욕이 넘치잖아? 매일 그런 「창작」을 하고 말이야.",
  ui_story_6_9_21_dialog_content = "난 계획에 따라 적절하게 움직이고 있는 거야. 네 그 행동들은 「민폐」라고 하는 거고.",
  ui_story_6_9_22_dialog_content = "피차일반이야.",
  ui_story_6_9_23_dialog_content = "잡담은 여기까지 하고, 이 선물을 봐...",
  ui_story_6_9_24_dialog_content = "헤에에, 정말 예쁜데? PlayerName 녀석이 옛 친구를 보면 어떤 표정을 지으려나?",
  ui_story_6_9_25_dialog_content = "얼른 보고 싶어지는걸...",
  ui_story_6_9_A1_dialog_content = "거츠더, 얼마나 더 남았지?",
  ui_story_6_9_A2_dialog_content = "금방이다. 날 믿어라. 그 위선적인 얼굴을 더 보고 싶은 건 오히려 내 쪽이니 말이야...",
  ui_story_6_9_A3_dialog_content = "......",
  ui_story_6_9_A4_dialog_content = "전방에 매복이 있다. 슈모르가 남긴 암귀겠지. 너흰 전투엔 능숙하잖아? 너희 차례다.",
  ui_story_6_13_1_dialog_content = "여긴... 이미 속삭이는 회랑 끝까지 온 것 같은데?",
  ui_story_6_13_2_dialog_content = "그래. 슈모르는 분명 이 근처에...",
  ui_story_6_13_3_dialog_content = "앞에서 녀석의 기운이 느껴져.",
  ui_story_6_13_5_dialog_content = "근처를 찾아봐. 거대한 유리병 아래에 코드가 하나 적혀 있을 거야.",
  ui_story_6_13_6_dialog_content = "음, 정확히 뭐였더라, 아마...",
  ui_story_6_13_7_dialog_content = "<color=#FFB400>「RX6007」</color>.",
  ui_story_6_13_8_dialog_content = "맞아! 바로 그거야! 물품을 보관할 때 정하는 거거든! 그걸 왜 알고 있어?",
  ui_story_6_13_10_dialog_content = "슈모르가 무의식적으로 언급했다. 난 들은 모든 것을 기억하거든.",
  ui_story_6_13_11_dialog_content = "정보든, 과거든 말이지... 하, 이런 기억력은 저주나 다를 바가 없다고.",
  ui_story_6_13_12_dialog_content = "그 코드의 물품이 있는 곳에 도착하면, 너희가 찾는 물건도 그 근처에 있을 거야.",
  ui_story_6_13_14_dialog_content = "조심해. 슈모르가 이미 그 번호를 알고 있다면 그건...",
  ui_story_6_13_16_dialog_content = "진작에 그 물건이 어디 있는지 알고, 우리가 오기를 기다리고 있을지도 몰라.",
  ui_story_6_14_1_dialog_content = "아, 또 만났네.",
  ui_story_6_14_2_dialog_content = "슈...",
  ui_story_6_14_3_dialog_content = "슈모르!",
  ui_story_6_14_4_dialog_content = "아, 화가 많이 났네? PlayerName한테 져서 그래?",
  ui_story_6_14_5_dialog_content = "보아하니 포로로 붙잡혔나 봐? 내가 구해줄 테니 한 번 더 싸워볼래?",
  ui_story_6_14_6_dialog_content = "너, 그리고 그 녀석까지, 모두가 날 속였다... 스예트의 죽음에 대한 진실을 알려주지 않았다고!",
  ui_story_6_14_7_dialog_content = "우리가 널 속였다고? 아니, 거츠더.\n넌 「스예트가 백야성 놈들에게 죽었다」는 사실을 더 믿고 싶었을 뿐이야.",
  ui_story_6_14_8_dialog_content = "그래서 넌 백야성에 복수하려던 거 아냐?",
  ui_story_6_14_9_dialog_content = "우린 모두 너희들에게 속았다... 너희가 스예트를 속이고, 이용하고, 끝내 그녀를 버린 거냐!",
  ui_story_6_14_10_dialog_content = "너도 손을 닦은 후에는 티슈를 버리잖아?",
  ui_story_6_14_11_dialog_content = "티슈... 스예트가...",
  ui_story_6_14_12_dialog_content = "땀을 많이 흘린 것 같네, 순찰 힘들었지? 티슈 받아.",
  ui_story_6_14_13_dialog_content = "고...마워.",
  ui_story_6_14_14_dialog_content = "왜 멍하니 있어? 아, 혹시 얼굴에 그거 땀이 아니라 눈물이야?",
  ui_story_6_14_15_dialog_content = "거츠더, 왜 우는 거야? 넌 배신자잖아? 배신자 주제에 왜 우는 거야?",
  ui_story_6_14_16_dialog_content = "슈모르... 너... 그럼 네가 스예트를...",
  ui_story_6_14_17_dialog_content = "내가 뭐? 거츠더, 넌 우리가 준 힘도 잃어버렸어. 그런 네가 뭘 할 수 있는데?",
  ui_story_6_14_20_dialog_content = "슈모르, 네가 스예트 자매를 하나로 융합한 거냐!",
  ui_story_6_14_22_dialog_content = "아니. 아── 그렇다고 할 수도 있으려나?",
  ui_story_6_14_23_dialog_content = "이 자식...!",
  ui_story_6_14_24_dialog_content = "알겠어. 「왜 그런 건지」 듣고 싶은 거지?",
  ui_story_6_14_25_dialog_content = "알려줄게. 그건 우리가 그저 그렇게 할 수 있기 때문에 그랬던 거야.",
  ui_story_6_14_26_dialog_content = "다 쓴 물건은 정리하고, 버릴 건 버리고. 자연스럽잖아? 그게 뭐가 이상해? 왜 화를 내는 건데?",
  ui_story_6_14_27_dialog_content = "이러쿵저러쿵, 귀찮아 죽겠네.",
  ui_story_6_14_28_dialog_content = "PlayerName. 그리고 저 두 여자... 전부 저 쓰레기들이 널 그렇게 고통스럽게 만든 거잖아.",
  ui_story_6_14_29_dialog_content = "슈모르...",
  ui_story_6_14_30_dialog_content = "내가 녀석들을 없애줄게...",
  ui_story_6_14_31_dialog_content = "조심해──!",
  ui_story_6_14_32_dialog_content = "카렌?!",
  ui_story_6_14_33_dialog_content = "...!",
  ui_story_6_14_34_dialog_content = "아! 거...츠더?!",
  ui_story_6_14_35_dialog_content = "너!",
  ui_story_6_14_36_dialog_content = "나... 난...",
  ui_story_6_14_37_dialog_content = "쳇! 미쳤어? 거츠더! 개 주제에 주인도 못 알아보고 어디다 꼬리를 흔드는 거야?!",
  ui_story_6_14_38_dialog_content = "어째서...",
  ui_story_6_14_39_dialog_content = "너흴... 위한 게 아니다. 이건... 스예트를 위해...",
  ui_story_6_14_40_dialog_content = "......",
  ui_story_6_14_A1_dialog_content = "슈모르를... 죽여...",
  ui_story_6_14_A2_dialog_content = "난 할 수 없지만... 너흰... 너희라면, 가능하겠지...",
  ui_story_6_14_A3_dialog_content = "너희의 손으로... 죽여줘...!",
  ui_story_6_14_A5_dialog_content = "슈모르...",
  ui_story_6_14_A7_dialog_content = "...나와 스예트는... <anim type=Shake><size=50>지옥에서 널 기다리겠다!</size></anim>",
  ui_story_6_14_44_dialog_content = "거츠더... 너...",
  ui_story_6_14_45_dialog_content = "카렌, 거츠더는 이미... 방금 그게 마지막 유언이었어.",
  ui_story_6_14_46_dialog_content = "...지루해, 재미없어, 재미없어 죽겠다고! 거츠더도, 너희들도! 너희들...",
  ui_story_6_14_47_dialog_content = "슈모르! <color=#FFB400>놈들이 왔어</color>. 철수해.",
  ui_story_6_14_48_dialog_content = "시끄러워! 뭘 하려는 거야? 방해하지 마!",
  ui_story_6_14_49_dialog_content = "지금 거기서 벗어나. 당장.",
  ui_story_6_14_50_dialog_content = "어째서?!",
  ui_story_6_14_51_dialog_content = "...무슨 일이지?",
  ui_story_6_14_52_dialog_content = "PlayerName! 일루미나의 깃발을 든 「<color=#FFB400>군대</color>」가 다가오고 있어! 기세가 엄청난걸!",
  ui_story_6_14_53_dialog_content = "조금만 더 버텨. 군단이 도착하면 이 주변을 물샐틈없게 포위할 거야!",
  ui_story_6_14_54_dialog_content = "대규모의 적이 오고 있어. 부품을 가지고 어서 나와.",
  ui_story_6_14_56_dialog_content = "난 이놈들을 바로 죽일 수 있어! 그리고 PlayerName 저놈을 붙잡아서 천천히...",
  ui_story_6_14_57_dialog_content = "넌 못 해.",
  ui_story_6_14_58_dialog_content = "할 수 있다고! 3분, 아니 1분이면...",
  ui_story_6_14_59_dialog_content = "못 한다고 했잖아! 일루미나의 군대가 왔어... 난 괜한 위험을 무릅쓰고 싶지 않아.",
  ui_story_6_14_60_dialog_content = "오오오오! 연기와 먼지를 좀 더 일으켜라!",
  ui_story_6_14_61_dialog_content = "일루미나 3군단 연합 집단군의 선봉대, 나는...",
  ui_story_6_14_62_dialog_content = "암귀 사냥꾼, 기나긴 밤의 종결자, 지하성 폭발꾼, 삼도천 열차 카론이다!",
  ui_story_6_14_63_dialog_content = "지금 수만의 병사를 이끌고 속삭이는 회랑을 포위하고 있다! 전방의 암귀들이여, 도망칠 생각 마라!",
  ui_story_6_14_X64_dialog_content = "내가 강제 수단을 쓰게 만들지 마, 슈모르.",
  ui_story_6_14_65_dialog_content = "알았어, 알았다고! 흥, 어차피 부품은 손에 넣었으니까...",
  ui_story_6_14_66_dialog_content = "거기 서! 슈모르!",
  ui_story_6_14_67_dialog_content = "「<color=#FFB400>화염 제어 모듈</color>」은 어디 있지?!",
  ui_story_6_14_68_dialog_content = "<color=#FFB400>여기 있어</color>.",
  ui_story_6_14_69_dialog_content = "넌 도망치지 못해. 군대가 이미 도착했다면 널 놓치지 않을 거야!",
  ui_story_6_14_70_dialog_content = "그럴 힘이 있으면 차라리 백야성을 걱정하는 게 좋을 텐데.",
  ui_story_6_14_71_dialog_content = "백야성?",
  ui_story_6_14_72_dialog_content = "영원히 함락되지 않는 도시라니, 정말 우습고 터무니없는 칭호라니까...",
  ui_story_6_14_A8_dialog_content = "검은 콜로서스의 보완이 끝나면, 진짜 최강의 힘이란 게 무엇인지 보여줄게!",
  ui_story_6_14_73_dialog_content = "땅이! 모두 조심해!",
  ui_story_6_14_74_dialog_content = "아하하, 서프라이즈!",
  ui_story_6_14_75_dialog_content = "이건! 맥거핀! 죽은 게 아니었어?",
  ui_story_6_14_76_dialog_content = "<anim type=Shake><size=45>크아아아... 아아아악!</size></anim>",
  ui_story_6_14_77_dialog_content = "근검절약은 미덕이잖아? 물건은 쓸 수 있을 때까지 아껴 써야지.",
  ui_story_6_14_78_dialog_content = "시간을 지체하지 마. 검은 콜로서스가 착륙 중이니까...",
  ui_story_6_14_79_dialog_content = "휴, 이 재미있는 걸 끝까지 볼 수 없다니 정말 아쉽네.",
  ui_story_6_14_80_dialog_content = "...뭐, 어차피 앞으로가 더 재미있을 테니 됐어. 그럼, 바이바이~",
  ui_story_6_14_81_dialog_content = "이 암귀가... 맥거핀이라고? 녀석에게서 강렬한 원한이 느껴져!",
  ui_story_6_14_83_dialog_content = "지난번에 본 맥거핀과는 달라! 정신 바짝 차려야 해!",
  ui_story_6_14_84_dialog_content = "맥거핀은 지난번에 분명히 죽었어. 하지만 이번엔 전보다 더 상대하기 어렵겠어...",
  ui_story_6_14_85_dialog_content = "백야성에 오기 전에 저런 암귀를 본 적 있어?",
  ui_story_6_14_86_dialog_content = "만난 적 있어. 하지만... 녀석은 그때 분명히 죽었어.",
  ui_story_6_14_87_dialog_content = "그러니까 이클립스가 녀석의 시체를 가지고 부활시켜 새로운 전투 병력으로 만든 건가.\n정말 제정신이 아닌 놈들이네...",
  ui_story_6_14_90_dialog_content = "저들에게 다른 암귀들은 애초에 동료라는 생각조차 없는 거야.\n스예트나 샤를처럼 그저 도구로 여기는 거지.",
  ui_story_6_14_92_dialog_content = "「<color=#FFB400>화염 제어 모듈</color>」은 벌써 가져가 버렸어. 우린 이제 어떡하지?",
  ui_story_6_14_93_dialog_content = "아직 할 일이 있어. 거츠더를 처리해야 해...",
  ui_story_6_14_94_dialog_content = "카렌?",
  ui_story_6_14_97_dialog_content = "거츠더를 화장해야겠어.",
  ui_story_6_14_98_dialog_content = "안장하는 게 아니라? 화장은 백야성의 관습이 아니잖아...",
  ui_story_6_14_99_dialog_content = "우선, 거츠더는 배신자야. 원래대로라면 시신을 버리는 형에 처해야 해.\n그리고 이클립스가 녀석의 시신을 이용해 부활시킬 수도 있어.",
  ui_story_6_14_100_dialog_content = "시신조차 목적을 위한 도구로 사용하다니, 정말 최악이야...",
  ui_story_6_14_102_dialog_content = "바이스, PlayerName. 불에 탈 만한 걸 찾아와 줘.",
  ui_story_6_14_103_dialog_content = "카렌 드 솔라드, 백야성 호위대장이 이곳에서 백야성을 대표해 거츠더에 대한 최종 판결을 진행하겠다.",
  ui_story_6_14_104_dialog_content = "그는 본래 백야성의 기사였으며, 전란에서 전공을 세웠다.",
  ui_story_6_14_105_dialog_content = "그러나 자신의 미진함에 괴로워하다 타락했고, 암귀의 농락에 넘어가 백야성을 배신하는 만행을 저질렀다.",
  ui_story_6_14_106_dialog_content = "또한 악도들에게 선동되어 반란을 일으켰고, 우리 백야성 백성을 위험에 빠트렸으니,\n그 죄는 결코 용서받을 수 없다.",
  ui_story_6_14_107_dialog_content = "그러나 마지막 순간 잘못을 깨닫고 그 목숨으로 빚을 갚았다.\n그의 죄는 결코 씻을 수 없으나, 이를 참작하여 시신을 버리는 형은 면한다.",
  ui_story_6_14_108_dialog_content = "이에 죄인의 명예를 지키고자 시신을 태우는 바이다... 만물은 백야 아래에.",
  ui_story_6_14_109_dialog_content = "거츠더, 백야성의 영웅, 배신한 기사, 이클립스의 졸개, 이곳에 안식하기를.",
  ui_story_6_14_111_dialog_content = "이제 저 사람도 안식을 취할 수 있겠지... PlayerName, 슈모르가 어디 있는지 느껴져?",
  ui_story_6_14_112_dialog_content = "슈모르는 이미 속삭이는 회랑을 벗어났어.",
  ui_story_6_14_114_dialog_content = "방향은 확실하진 않아. 굳이 말하자면 고도가 높아졌다는 느낌이야...",
  ui_story_6_14_115_dialog_content = "높아졌다고...? 설마... 전에 말한 백야성이...",
  ui_story_6_14_116_dialog_content = "방해해서 미안! 아직 살아있니?!",
  ui_story_6_14_117_dialog_content = "당연하죠!",
  ui_story_6_14_118_dialog_content = "방금 엄청난 녀석이 갑자기 나타나서, 난 또 혹시나...",
  ui_story_6_14_119_dialog_content = "「화염 제어 모듈」을 손에 넣지 못한 것만 빼고, 모두 무사해요!",
  ui_story_6_14_120_dialog_content = "그래도 다행이네~",
  ui_story_6_14_121_dialog_content = "일루미나의 군대는요? 방금 지원군이 왔다고 하지 않았나요?",
  ui_story_6_14_122_dialog_content = "음, 그건 직접 보는 게 좋을 것 같아...",
  ui_story_6_14_123_dialog_content = "...다시 만났군, 바이스, PlayerName.",
  ui_story_6_14_124_dialog_content = "카론 님...?",
  ui_story_6_14_125_dialog_content = "우선 물 좀 마셔도 되겠나? 여기까지 달려오느라... 정말 지쳤거든...",
  ui_story_6_14_126_dialog_content = "도대체 무슨 상황이죠? 연합군은요?",
  ui_story_6_14_127_dialog_content = "몇 시간 전에 필리시 녀석이 너희한테 문제가 생긴 것 같다고 하더군...",
  ui_story_6_14_128_dialog_content = "하지만 자난 쪽은 출병하질 않으니, 내가 독단적으로 결정해서 온 거다...",
  ui_story_6_14_129_dialog_content = "그럼 설마 방금 샤엘 씨가 말한 「군대」는 카론 님이...",
  ui_story_6_14_130_dialog_content = "네 생각대로다, 바이스.",
  ui_story_6_14_131_dialog_content = "근처에 도착하자마자 괴상한 검은 콜로서스를 발견했다. 그리고 샤엘 양을 만났지.",
  ui_story_6_14_132_dialog_content = "샤엘 양은 너희가 슈모르를 이기지 못할까 걱정했고, 난 계략을 하나 떠올렸다.",
  ui_story_6_14_133_dialog_content = "그래서... 크흠, 기차 한 대로 수천 명의 군인들이 있는 것처럼 보이게 하는 게 쉽진 않았지...",
  ui_story_6_14_134_dialog_content = "그럼 결국 속임수였던 건가요... 만약 슈모르가 속지 않았으면요?",
  ui_story_6_14_135_dialog_content = "그래도 시도해 볼 가치는 있었지...\n게다가 일루미나의 열차에 병사가 얼마나 타고 있을지 누가 알 수 있겠나?",
  ui_story_6_14_136_dialog_content = "그러고 보니 슈모르 녀석은 어디로 도망쳤지?",
  ui_story_6_14_137_dialog_content = "조금 전엔 내가 일으킨 모래먼지 때문에 아무것도 안 보여서 말이지...",
  ui_story_6_14_138_dialog_content = "이제 기운이 향하는 곳을 거의 확신할 수 있어요. 하늘 위... 백야성 방향으로 가고 있어요.",
  ui_story_6_14_139_dialog_content = "백야성!",
  ui_story_6_14_140_dialog_content = "?! 백야성?",
  ui_story_6_14_141_dialog_content = "부품을 모은 후 바로 백야성으로 가다니... 설마 백야성을 공격하려는 건가?!",
  ui_story_6_14_142_dialog_content = "아니... 백야성 외부에는 강력한 보호막이 있어. 뜻대론 안 될 거야!",
  ui_story_6_14_A9_dialog_content = "하지만 지금 그쪽으로 가는 이유가 분명히 있을 거야...",
  ui_story_6_14_143_dialog_content = "그럼 녀석은 정말로 콜로서스를 보완하고 나면 백야성에 정면으로 맞설 수 있다고 생각한 거야?!",
  ui_story_6_14_144_dialog_content = "PlayerName, 지금 바로 백야성으로 가자!",
  ui_story_6_14_145_dialog_content = "알겠어... 출발하자!",
  ui_story_7_1_1_dialog_content = "백야의 주인은 내 갑옷, 피와 살이자 뼈. 그 어떤 사악함도 날 해치지 못하리...",
  ui_story_7_1_A1_dialog_content = "백야의 주인은 내 갑옷, 피와 살이자 뼈. 그 어떤 사악함도── 진정하십시오! 당황하지 마십시오!",
  ui_story_7_1_2_dialog_content = "저기 좀 봐! 부딪혔어! 와서 부딪혔다고!",
  ui_story_7_1_3_dialog_content = "저...저건... <color=#FFB400>흑룡</color>?",
  ui_story_7_1_4_dialog_content = "괘, 괜찮겠지? 우리의 실드는 아주 단단하잖아. 쉽게 깨질 리가 없어!",
  ui_story_7_1_5_dialog_content = "백야의 주인을 믿고 오로라의 비호를 믿어야 합니다!",
  ui_story_7_1_6_dialog_content = "실드가 있는 한 그 어떤 사악한 존재도 신성한 업타운 구역에 들어오지 못합니다! 당황하지 마십시오!",
  ui_story_7_1_7_dialog_content = "곧 도착해! 저 앞이 바로 백야성이야!",
  ui_story_7_1_8_dialog_content = "어째서 하늘이 이런 색으로 변한 거야?!",
  ui_story_7_1_9_dialog_content = "성주 전하께서 <color=#FFB400>실드</color>를 가동하신 거야.",
  ui_story_7_1_X1_dialog_content = "많은 사람들이 위험에 처했을지도 몰라. 어서 성으로 들어가야 해!",
  ui_story_7_1_X2_dialog_content = "그럼 슈모르는?",
  ui_story_7_1_10_dialog_content = "우선 사람부터 구하자. 바로 성으로 들어가!",
  ui_story_7_1_11_option_content = "좋아. 그럼 성안에 정박하자.",
  ui_story_7_1_12_option_content = "아니. 바깥에 세우는 게 좋겠어.",
  ui_story_7_1_13_dialog_content = "그건 불가능합니다... 제 크기, 그리고 백야성의 상황으로 봤을 때, 여러모로 곤란합니다.",
  ui_story_7_1_14_dialog_content = "안 돼. 백야성의 <color=#FFB400>실드가 이미 전개됐어</color>.",
  ui_story_7_1_A2_dialog_content = "실드는 암귀를 막아내지만, 스카이워커호도 마찬가지로 들어가지 못할 거야.",
  ui_story_7_1_16_dialog_content = "백야성의 실드가 그렇게 대단하면... 우린 왜 성으로 가야 하는 거야?",
  ui_story_7_1_17_dialog_content = "실드는 업타운 구역밖에 보호하지 못해. 나머지 구역은... 실드 밖에 완전히 노출되어 있어!",
  ui_story_7_1_F1_dialog_content = "암귀는 분명히 다운타운 구역으로 들어와 실드의 사각지대를 공격하려 들 거야!",
  ui_story_7_1_F2_dialog_content = "스카이워커호를 암귀가 잔뜩 있는 다운타운 구역에 정박할 순 없어.",
  ui_story_7_1_18_dialog_content = "PlayerName, 전 백야성 상공에서 비행하며 여러분의 연락을 기다리겠습니다.",
  ui_story_7_1_19_dialog_content = "그럼 네가 위험하지 않겠어?",
  ui_story_7_1_F3_dialog_content = "최대한 슈모르를 경계하며 계속 연락을 취하겠습니다.",
  ui_story_7_1_F4_dialog_content = "좋아. 그럼 부탁할게, 스카이워커.",
  ui_story_7_1_20_dialog_content = "카렌, 백야성이 함락되진 않겠지?",
  ui_story_7_1_21_dialog_content = "그럴 리 없어. <color=#FFB400>그분</color>이 있는 한, 백야성의 토대는 영원히 흔들리지 않을 거야.",
  ui_story_7_1_22_dialog_content = "확실히, 제 크기와 백야성의 현재 상태를 고려하면 들어갈 수 없을 것 같습니다.",
  ui_story_7_1_23_dialog_content = "PlayerName, 스카이워커호를 밖에 정박하는 게 더 좋을 것 같다는 거야?",
  ui_story_7_1_24_dialog_content = "응. 슈모르가 백야성을 목표로 하고 있다면, 스카이워커호는 반대로 최대한 멀리 두는 게 좋아...",
  ui_story_7_1_25_dialog_content = "찬성이야. 게다가 우리가 스카이워커호를 성으로 들이고 싶어도 불가능한 상황이야.",
  ui_story_7_1_26_dialog_content = "업타운 구역의 <color=#FFB400>실드가 전개</color>됐어. 이제 그 무엇도 안으로 들어갈 수 없어.",
  ui_story_7_1_F5_dialog_content = "하지만 암귀는 분명히 다운타운 구역으로 들어와 실드의 사각지대를 공격하려 들 거야!",
  ui_story_7_1_27_dialog_content = "PlayerName, 전 백야성 상공에서 비행하며 여러분의 연락을 기다리겠습니다.",
  ui_story_7_1_28_dialog_content = "그럼 네가 위험하지 않겠어?",
  ui_story_7_1_F6_dialog_content = "최대한 슈모르를 경계하며 계속 연락을 취하겠습니다.",
  ui_story_7_1_F7_dialog_content = "좋아. 그럼 부탁할게, 스카이워커.",
  ui_story_7_1_29_dialog_content = "서두르자. 슈모르가 정말 백야성을 무너트릴 자신이 있다면...",
  ui_story_7_1_30_dialog_content = "그럴 리 없어. <color=#FFB400>그분</color>이 있는 한, 백야성의 토대는 영원히 흔들리지 않을 거야.",
  ui_story_7_1_31_dialog_content = "성주님, 위협이 확인되었습니다. 콜로서스 한 척이 백야성을 공격하고 있습니다.",
  ui_story_7_1_32_dialog_content = "실드가 활성화되었으니, 업타운 구역은 변함없이 안전합니다.",
  ui_story_7_1_33_dialog_content = "방심은 금물이다. 지금은 아직 적의 힘과 의도를 판단할 수 없으니, 경계를 유지하라.",
  ui_story_7_1_34_dialog_content = "호위대는 상대의 동향을 계속 주시하라. 정보부는 새로운 소식이 있으면 즉각 보고하도록.",
  ui_story_7_1_35_dialog_content = "다운타운 구역의 상황은 어떠한가.",
  ui_story_7_1_36_dialog_content = "다운타운 구역에는 이미 암귀가 침입했습니다. 병력 지원을 준비하면 되겠습니까?",
  ui_story_7_1_37_dialog_content = "아니, 업타운 구역의 보호에 힘써라. 귀족들이 공포에 빠져 어리석은 짓을 하지 않도록 말이야.",
  ui_story_7_1_38_dialog_content = "다운타운 구역은 그들만의 생존 법칙이 있다.",
  ui_story_7_1_39_dialog_content = "일루미나의 군단은?",
  ui_story_7_1_40_dialog_content = "대부분의 군단은 이곳과 멀리 떨어진 구역에서 방어선을 구축했고,\n단시간에 지원을 올 수는 없는 상황입니다.",
  ui_story_7_1_41_dialog_content = "백야성 근처에는 두 개의 소부대만 도착한 것으로 보입니다.\n비비안 참모장과 시로나 군단장이 이끌고 있습니다.",
  ui_story_7_1_42_dialog_content = "그 둘인가... 음, 알겠다. 그리고... <color=#FFB400>카렌</color>은 소식이 있나?",
  ui_story_7_1_43_dialog_content = "방금 연락을 받았습니다. 호위대장 일행은 현재 걸어서 다운타운 구역으로 진입했습니다.",
  ui_story_7_1_44_dialog_content = "즉시 업타운 구역으로 돌아오라고 전해라. 지금은 애들 장난을 할 때가 아니다.\n더는 남들의 입에 오르는 모습을 보고 싶지 않군.",
  ui_story_7_1_45_dialog_content = "<color=#e8d9bb>백야성, 다운타운 구역</color>",
  ui_story_7_1_46_dialog_content = "호위대 사람은 한 명도 보이지 않아.",
  ui_story_7_1_47_dialog_content = "이미 암귀의 기운이 느껴져.",
  ui_story_7_1_48_dialog_content = "이런 혼란스러운 모습이라니, 이게 정말 전에 봤던 그 백야성인가...",
  ui_story_7_1_49_dialog_content = "...정박했습니다. 여러분의 위쪽... ■■...에 있습니다.",
  ui_story_7_1_A3_dialog_content = "백야성의 실드로 인해... ■■■... 간섭이 발생했습니다... 부디... 들리셨기를...",
  ui_story_7_1_50_dialog_content = "들려! 걱정하지 마. 우린 모두 안전하니까. 몸조심하고 있어!",
  ui_story_7_1_51_dialog_content = "그 말은... 제가 할 말입니다, PlayerName.",
  ui_story_7_1_52_dialog_content = "전... ■■■ 여러분을 기다리겠습니다. 여러분도 부디... ■■■■.",
  ui_story_7_1_53_dialog_content = "지금 상황이 어떤지 누가 좀 알려줄 수 있었으면 좋겠는데...",
  ui_story_7_1_54_dialog_content = "상황은 보이는 것만큼 심각하지는 않아요. 바이스, PlayerName.",
  ui_story_7_1_55_dialog_content = "<color=#FFB400>비비안</color> 참모장님!",
  ui_story_7_1_56_dialog_content = "대부분의 군단은 주변의 다른 구역을 지키고 있어서 일단은 우리만 올 수밖에 없었어요.",
  ui_story_7_1_57_dialog_content = "그나저나 「백야성 함락」이라니, 이 사람들 너무 과장이 심하네요.",
  ui_story_7_1_A4_dialog_content = "아이테르! 또 만났네요. 당신도 계속 귀찮은 일에 휘말리는군요. 매번 놓치지 않고 말이죠.",
  ui_story_7_1_58_dialog_content = "사실 나도 이런 일에 휘말리고 싶진 않았다고. 부디 내 탓을 하진 않았으면 좋겠어...",
  ui_story_7_1_59_dialog_content = "그럴 리가요~ 당신은 최선을 다해 슈모르를 막았잖아요?\n그저 우리가 이렇게 될 줄 미처 몰랐을 뿐이에요!",
  ui_story_7_1_60_dialog_content = "참모장님, 지금 백야성의 상황이 어떤지 아시나요?",
  ui_story_7_1_61_dialog_content = "업타운 구역은 당연히 다리 뻗고 편히 자고 있죠. 저 실드 보이세요?",
  ui_story_7_1_62_dialog_content = "저게 활성화된 이상, 그 어떤 공격도 뚫지 못할 거예요.\n저것도 「난공불락」의 명성에 한몫하고 있죠...",
  ui_story_7_1_63_dialog_content = "하지만 다운타운 구역은 좋지 않아.",
  ui_story_7_1_64_dialog_content = "<color=#FFB400>시로나</color> 님? 아니, 군단장님...",
  ui_story_7_1_65_dialog_content = "아, 말하는 걸 깜박했네요. 이번 긴급 지원의 병력은 대부분 제1군단에서 차출됐거든요.",
  ui_story_7_1_66_dialog_content = "저 실드는 다운타운은 조금도 지켜주지 않아. 암귀는커녕 세 살짜리 애들도 자유롭게 드나들 수 있다고.",
  ui_story_7_1_68_dialog_content = "대처할 수 있나? 현재 구체적인 상황은?",
  ui_story_7_1_70_dialog_content = "지금 최대한 빨리 처리하고 있어.\n조금 성가시긴 해도 이 정도 수라면 내 병사들이 어떻게든 상대할 수 있으니까.",
  ui_story_7_1_71_dialog_content = "우리 호위대는? 즉시 업타운 구역으로 귀환하라는 통신을 받았는데, 다른 호위대는 어디에 있지?",
  ui_story_7_1_72_dialog_content = "카렌 드 솔라드 아가씨, 아무래도 내 뜻을 아직 이해하지 못한 것 같네.",
  ui_story_7_1_A5_dialog_content = "네 아버지는 이미 명령을 내렸어.\n모든 호위대는 업타운 구역의 보호에만 집중하라고 말이야. 너도 마찬가지고.",
  ui_story_7_1_73_dialog_content = "예상했잖아. 안 그래? 네가 예상하지 못했을 리가 없어.",
  ui_story_7_1_74_dialog_content = "내게 그렇게 굴 필요는 없잖아, 시로나! 내 지난 행동들로 이미 충분히 답이 되었을 거라 생각하는데!",
  ui_story_7_1_75_dialog_content = "네가 그런다고 뭐가 달라졌는데? 백야성은 여전히 변한 게 없이 그대로잖아.",
  ui_story_7_1_76_option_content = "두 사람 다 그만 해요.",
  ui_story_7_1_77_option_content = "모두 조용히 해! 지금은 그럴 때가 아니라고!",
  ui_story_7_1_78_dialog_content = "나도 말싸움하고 싶은 생각은 전혀 없어.",
  ui_story_7_1_79_dialog_content = "PlayerName, 네가 중재할 자격은 없을 텐데.",
  ui_story_7_1_80_dialog_content = "이건 우리 일루미나와 백야성 사람들 사이의 문제라고.",
  ui_story_7_1_81_dialog_content = "지금 그게 문제가 아니잖아요... 게다가 당신들은 모두 오로리안이잖아요...",
  ui_story_7_1_82_dialog_content = "군단장님, PlayerName도 지금 상황이 걱정이 돼서 그러는 것뿐이에요. 다들 초조할 테니까요...",
  ui_story_7_1_83_dialog_content = "바이스는 감성 지수가 높네요. PlayerName의 말이 맞아요. 우린 모두 한 가족이잖아요?",
  ui_story_7_1_84_dialog_content = "우선 오로리안으로서 함께 싸우는 게 가장 중요하죠~ 맞죠? 그렇죠?",
  ui_story_7_1_85_dialog_content = "...동의해. 지금 중요한 건 입장이 아냐.",
  ui_story_7_1_86_dialog_content = "입장 얘기가 나와서 말인데, 카렌, 우선 업타운 구역으로 돌아가 보고해야 하지 않나요?\n성주 전하께서 당신을 찾으시는 것 같거든요.",
  ui_story_7_1_F8_dialog_content = "다들 지금 저 암귀들을 봤으면서 왜 우리끼리 싸우는 거야!",
  ui_story_7_1_87_dialog_content = "말을 가려서 하는 게 좋을 텐데, PlayerName!",
  ui_story_7_1_88_dialog_content = "PlayerName, 너도 알잖아. 저분은 일루미나 제1군단의 군단장님이라고... 그리고 카렌도 백야성의 호위대장이고.",
  ui_story_7_1_89_dialog_content = "알고 있어! 하지만 군단장이든 호위대장이든,\n말싸움 때문에 사람들을 구할 시간을 허비하고 싶진 않을 거잖아?",
  ui_story_7_1_90_dialog_content = "좋아, 지금 가장 중요한 건 암귀를 없애는 거야. 따분한 세력 갈등은 미뤄두자고.",
  ui_story_7_1_91_dialog_content = "미안하지만 나도 지금은 처세술 같은 걸 가르쳐 줄 아가씨는 필요하지 않아.",
  ui_story_7_1_92_dialog_content = "암귀를 없애는 일이라면 난 매일 전장의 최전선에서 수없이 거듭하고 있다고.",
  ui_story_7_1_93_dialog_content = "너도 최근에 꽤 많은 전투를 치렀다면서? 그럼 이젠 이해할 수 있겠지?",
  ui_story_7_1_94_dialog_content = "......",
  ui_story_7_1_95_dialog_content = "자, 자. 모두 한 가족이잖아요~ 그럴 기운이 있으면 차라리 암귀를 상대하는 건 어떨까요?",
  ui_story_7_1_96_dialog_content = "그럼 카렌은요? 우선 명령에 따라 돌아가는 건...",
  ui_story_7_1_97_dialog_content = "돌아가지 않을 거야. 전장에 나가 있는 장수는 명령을 받지 않는 법도 있으니까.",
  ui_story_7_1_98_dialog_content = "저기... 그래도 지금은 「전장에 나가 있는」 건 아니지 않아?\n이미 집 안까지 들어온 거나 마찬가지잖아...",
  ui_story_7_1_F9_dialog_content = "바이스, 쓸데없는 소리 좀 하지 마...",
  ui_story_7_1_99_dialog_content = "군단장님! 다운타운 구역에 나타난 암귀 수가 예상보다 많습니다! 벌써 방어가 뚫린 곳이 있습니다!",
  ui_story_7_1_A6_dialog_content = "시민들이 아직 대피하지 못했습니다! 지시를 내려주십시오!",
  ui_story_7_1_100_dialog_content = "내가 직접 가겠어! 너희들은 알아서 해.",
  ui_story_7_1_101_dialog_content = "우리도 함께 갈게요! 조금이라도 돕고 싶어요!",
  ui_story_7_1_102_dialog_content = "의욕이 넘치는군요, 바이스! <color=#FFB400>그럼 모두 함께 가죠</color>!",
  ui_story_7_1_103_dialog_content = "내가 안내하겠어. 다운타운 구역도 내가 수없이 순찰했던 곳이니, 나보다 잘 아는 사람은 없을 거야.",
  ui_story_7_1_104_dialog_content = "카렌... 정말 돌아가서 보고하지 않아도 괜찮은 거야?",
  ui_story_7_1_105_dialog_content = "난 이미 결정했어. 이 모든 걸... 반드시 끝내야만 해.",
  ui_story_7_1_106_dialog_content = "백야성의 껍데기는 정말 단단하네.",
  ui_story_7_1_107_dialog_content = "젠장. 어째서 안 말해준 거야?! 이런 방어 수단을 가지고 있다니, 역시 겁쟁이답네!",
  ui_story_7_1_108_dialog_content = "말했잖아, 재정비한 후에 다시 공격하자고. 결국 네가 자만에 빠져서 이성을 내팽개친 탓이잖아?",
  ui_story_7_1_109_dialog_content = "...설교할 시간에 빨리 네 졸개들이나 백야성에 보내서 소란이나 좀 피워 보는 게 어때!",
  ui_story_7_1_110_dialog_content = "쉿... 조용히 해. 난 시끄러운 건 질색이야.",
  ui_story_7_1_111_dialog_content = "백야성의 실드는 곧 에너지 소진 상태에 들어설 거야.",
  ui_story_7_1_A7_dialog_content = "그때가 되면... 마음대로 들어가라고.",
  ui_story_7_1_112_dialog_content = "그럼 난 이제 뭘 하라고? 기다려? 아니면 계속 공격해?",
  ui_story_7_1_113_dialog_content = "네 쓸모없는 잔챙이들이 하는 헛짓거리를 앉아서 보고만 있으라는 거야?",
  ui_story_7_1_114_dialog_content = "조급해하지 마, 슈모르. 마침 네 상대도 왔으니까. 게다가 바로 근처에 있어.",
  ui_story_7_1_116_dialog_content = "스카이워커호 말하는 거야? 그리고 PlayerName도?",
  ui_story_7_1_117_dialog_content = "맞아... 뭐야? 그 표정은? 설마 또 멋대로 놀러 갈 생각이야? 적당히 해.",
  ui_story_7_1_X3_dialog_content = "...난 내가 하고 싶은 대로 할 거야. 잊지 마, 난 그 누구의 명령도 듣지 않아.\n너도, 이클립스도 마찬가지라고.",
  ui_story_7_1_X4_dialog_content = "휴, 구제불능이라니까.",
  ui_story_7_2_1_dialog_content = "카렌, 지원이 필요한 구역까진 얼마나 더 가야 해?",
  ui_story_7_2_2_dialog_content = "도착했어! 바로 여기야. 방금 그 병사가 말한 곳은...",
  ui_story_7_2_3_dialog_content = "암귀의 기운이 엄청 짙어졌어. 지금 <color=#FFB400>가장 먼저</color> 해야 할 일은...",
  ui_story_7_2_4_option_content = "사람들을 먼저 피신시키자.",
  ui_story_7_2_5_option_content = "떠도는 암귀를 먼저 처리하자.",
  ui_story_7_2_6_dialog_content = "사람 중심의 결정을 내릴 줄 아는군요, PlayerName! 어쩌면 나중에 대단한 사람이 될지도 모르겠네요~",
  ui_story_7_2_7_dialog_content = "과한 칭찬이네, 비비안 씨...",
  ui_story_7_2_8_dialog_content = "좋아. 난 위험에 처한 주민들을 찾으러 가겠어. 내가 너희들보다 빠르니까.",
  ui_story_7_2_A1_dialog_content = "너희는 눈앞의 암귀를 죽이는 데 집중해. 그 정도는 할 수 있겠지?",
  ui_story_7_2_9_dialog_content = "알겠어요! 위험의 원인부터 해결해야 구조를 순조롭게 진행할 수 있겠죠.",
  ui_story_7_2_10_dialog_content = "그럼 분담해서 협력하죠. 구조와 전투를 동시에 진행할 수 있을 것 같네요.",
  ui_story_7_2_11_dialog_content = "난 위험에 처한 주민들을 찾으러 가겠어. 내가 너희들보다 빠르니까.",
  ui_story_7_2_A2_dialog_content = "너희는 눈앞의 암귀를 죽이는 데 집중해. 그 정도는 할 수 있겠지?",
  ui_story_7_2_12_dialog_content = "얕보는 것도 정도가 있어. 시로나.",
  ui_story_7_2_13_dialog_content = "아, 아하하, 모두 의욕이 넘치네요! 정말 다행이에요. 그럼 시작하죠!",
  ui_story_7_2_14_dialog_content = "전 이쪽으로 갈게요. 바이스, 그쪽은 여러분한테 맡길게요!",
  ui_story_7_2_15_dialog_content = "그리고 여러분의 콜로서스는요? 지금은 상황이 좋지 않으니 적한테 뒤통수를 맞지 않게 조심하세요!",
  ui_story_7_2_16_dialog_content = "성 밖에 정박해 뒀어요. 지금은 아주 안전할 거예요... 아마도.",
  ui_story_7_2_17_dialog_content = "우린 인원이 부족하니까, 다들 정신 바짝 차리세요.",
  ui_story_7_2_F1_dialog_content = "휴, 호위대의 지원을 받을 수 있었으면...",
  ui_story_7_2_18_dialog_content = "지금 난 호위대가 아니라는 거야?",
  ui_story_7_2_19_dialog_content = "아, 아! 누굴 탓하려던 건 아니에요~",
  ui_story_7_2_21_dialog_content = "그럼 어서 가볼까요! 오늘도 소소한 목표로 암귀를 세 자릿수 처치해 보겠어요!",
  ui_story_7_2_22_dialog_content = "소, 소소한 목표?!",
  ui_story_7_2_23_dialog_content = "일루미나의 장교들 중에는 평범한 사람이 없다니까... 우리도 주변의 적을 처리하자!",
  ui_story_7_6_1_dialog_content = "휴, 이쪽은 다 처리했어.",
  ui_story_7_6_2_dialog_content = "여기도! 군단장님, 다운타운 구역에 또 지원이 필요한 곳이 있나요?",
  ui_story_7_6_3_dialog_content = "새로운 벌레가 또 기어 나왔지만, 감당할 수 있는 수야. 수고했어.",
  ui_story_7_6_4_dialog_content = "후우... 놀라긴 했지만 그래도 해결했네. 우리가 빨리 움직여서 다행이야...",
  ui_story_7_6_6_dialog_content = "다행이에요. 바이스~ 일단 다운타운 구역은 더 많은 지원이 필요하진 않을 거예요.\n다른 구역을 살펴보죠!",
  ui_story_7_6_7_dialog_content = "교활한 적이 방어가 약한 곳을 몰래 기습하고 있을지도 몰라요!",
  ui_story_7_6_8_dialog_content = "저기, 참모장님은 옛날부터 「말이 씨가 되는」 능력이 있었던 거 아시나요...",
  ui_story_7_6_9_dialog_content = "혹시 모르니 스카이워커호의 상태를 다시 확인해 보자. PlayerName.",
  ui_story_7_6_10_dialog_content = "그러고 보니 스카이워커호가 나한테 연락한 지 꽤 됐네. 한 번 해볼게...",
  ui_story_7_6_12_dialog_content = "...정상입니다. 암귀는 없습니다... 하지만 기온이 갑자기 많이 내려간 것 같습니다. 제가...",
  ui_story_7_6_13_dialog_content = "<size=45>──?!</size>",
  ui_story_7_6_14_dialog_content = "왜 그래? 카렌, 어디 다쳤어?",
  ui_story_7_6_15_dialog_content = "아니... 방금 전달받은 소식이 있어. <color=#FFB400>업타운이 공격당했어</color>!",
  ui_story_7_6_16_dialog_content = "업타운 구역? 설마 다운타운 구역의 방어선을 돌파하고 업타운 구역에 침입한 암귀가 있는 거야?",
  ui_story_7_6_17_dialog_content = "아니, 다운타운 구역의 방어선은 뚫리지 않았어. 놈들이 따로 잠복 계획을 세웠던 게 분명해!",
  ui_story_7_6_18_dialog_content = "백야성의 핵심 구역을 바로 공격한다고? 업타운 구역 쪽의 방어는 아주 삼엄한 거 아니었어?",
  ui_story_7_6_19_dialog_content = "맞아, 아주 견고해. 하지만 방금 그 암귀들의 행동은 뭔가 이상했어...",
  ui_story_7_6_20_dialog_content = "슈모르가 백야성을 공격할 자신이 있다는 건, 그 암귀들도 만반의 준비를 했다는 뜻일 거야.",
  ui_story_7_6_21_dialog_content = "맞아, 갑자기 안 좋은 예감이 들어. 어서 돌아가야겠어.",
  ui_story_7_6_22_dialog_content = "우리도 같이 가자. PlayerName, 서둘러!",
  ui_story_7_6_23_dialog_content = "업타운에 잠입할 수 있는 적이라면 분명히 엄청난 힘을 지니고 있을 거야... 함께 가줘서 고마워.",
  ui_story_7_6_24_dialog_content = "알겠어! 그럼... 여기는 바이스, 보고드립니다.\n방금 업타운 구역이 특수한 암귀의 공격을 받았으니, 즉시 방어에 합류하라는 소식이 들어왔어요!",
  ui_story_7_6_25_dialog_content = "가는 중이에요~",
  ui_story_7_6_26_dialog_content = "난 곧 도착해.",
  ui_story_7_6_27_dialog_content = "역시 군단장은 뭔가 다른 건가?!",
  ui_story_7_7_1_dialog_content = "늦어서 미안해.",
  ui_story_7_7_2_dialog_content = "호위대장님! 드디어 오셨군요! 지금 암귀가...",
  ui_story_7_7_3_dialog_content = "쓸데없는 설명은 됐어! 적은 어디 있지?",
  ui_story_7_7_4_dialog_content = "이쪽입니다! 따라오십시오!",
  ui_story_7_7_5_dialog_content = "<size=45>...키이이이익...!</size>",
  ui_story_7_7_6_dialog_content = "계속해라! 더 이상 다가오게 하면 안 된다! 이곳만 지나면 업타운 구역이란 말이다!",
  ui_story_7_7_7_dialog_content = "키이익!",
  ui_story_7_7_8_dialog_content = "크, 큰일이다! 방어선이 무너졌다! 다시 정비해라! 놈들이 접근하게 해선 안 된다!",
  ui_story_7_7_9_dialog_content = "으앗! 카렌 언니!",
  ui_story_7_7_10_dialog_content = "여기서 뭘 하고 있어?! 저 녀석이 마음대로 날뛰는 걸 보고만 있을 생각이야?\n여긴 백야성의 핵심 요충지라고!",
  ui_story_7_7_11_dialog_content = "그게... 성주 전하의 명령이 있었어. <color=#FFB400>우린 업타운 구역의 방어만 맡는다</color>고...",
  ui_story_7_7_12_dialog_content = "엄밀히 말하면 저 큰 벌레는 아직 이곳을 돌파하지 못했으니까, 원칙상 우리도 나갈 수가 없어...",
  ui_story_7_7_13_dialog_content = "지금 그딴 걸 원칙이라고 말하는 거야?!",
  ui_story_7_7_15_dialog_content = "카렌, 호위대가 싸우지 못해도 우리한테는 일루미나의 지원군이 있어!\n도움을 받는다면 상대할 수 있을 거야!",
  ui_story_7_7_16_dialog_content = "또 호위대 녀석들의 뒤처리를 해야 하는 건가?",
  ui_story_7_7_17_dialog_content = "군단장님! 호위대는 명령 때문에... 업타운 구역 밖의 적을 처리할 수 없다고 해요. 우리가 나서는 게 좋겠어요!",
  ui_story_7_7_18_dialog_content = "백야성 녀석들과 협력할 때마다 「고리타분」이란 게 뭔지 새삼 깨닫게 된다니까.",
  ui_story_7_7_19_dialog_content = "됐어요, 시로나. 지금은 불평할 때가 아니잖아요~ 저 녀석, 병사들이 더는 못 막아낼 것 같네요...",
  ui_story_7_7_21_dialog_content = "밧줄과 견인차를 가져와! 저런 건 바로 토막 내버리면 돼!",
  ui_story_7_7_22_dialog_content = "토, 토막?!",
  ui_story_7_7_23_dialog_content = "......?",
  ui_story_7_7_24_dialog_content = "시체 처리에 편하도록 말이야! 이건 다 경험에서 하는 말이니까, 꼬맹이들은 전투에나 집중해!",
  ui_story_7_7_25_dialog_content = "아, 알겠습니다! 그럼 저흰 어떻게 하면 될지...",
  ui_story_7_7_26_dialog_content = "우선 이 녀석을 같이 때려눕혀! 비비안, 넌 타이밍에 맞춰 「잘라」버려. 하던 대로 말이야!",
  ui_story_7_7_27_dialog_content = "알겠어요. 하던 대로 말이죠!",
  ui_story_7_7_28_dialog_content = "내가 길을 뚫겠어! 죽고 싶지 않으면 관계없는 녀석들은 비켜! <color=#FFB400>지휘</color>는...",
  ui_story_7_7_29_dialog_content = "맡겨줘! 얼마든지 할 수 있어!",
  ui_story_7_7_30_dialog_content = "<color=#FFB400>녀석을 업타운 구역 밖에서 쓰러트려야 해</color>!",
  ui_story_7_7_31_dialog_content = "<anim type=Shake><size=45>크오오──!</size></anim>",
  ui_story_7_7_32_dialog_content = "비비안, 지금이야!",
  ui_story_7_7_33_dialog_content = "갑니다! 「라듐」!",
  ui_story_7_7_34_dialog_content = "「피에는 피로」!",
  ui_story_7_7_36_dialog_content = "쓰, 쓰러졌어! 드디어!",
  ui_story_7_7_37_dialog_content = "제압은 성공적이었어! 꼬마 녀석들도 가끔은 쓸모가 있잖아!",
  ui_story_7_7_38_dialog_content = "......",
  ui_story_7_7_39_dialog_content = "하하, 과찬이에요...",
  ui_story_7_7_40_dialog_content = "보고드립니다! 검은 콜로서스의 공격은 여전히 진행 중입니다. 약해질 기미가 보이지 않습니다!",
  ui_story_7_7_41_dialog_content = "슈모르...",
  ui_story_7_7_42_dialog_content = "여전히 고집을 피우고 있는 건가... 이런다고 해서 녀석에게 무슨 이점이 있는 거지?",
  ui_story_7_7_43_dialog_content = "주제도 모르네. 이 정도 암귀는 열 번은 더 들이닥쳐도 업타운의 털끝조차 건드리지 못해!",
  ui_story_7_7_44_dialog_content = "그저 미련한 걸지도 모르지.",
  ui_story_7_7_45_dialog_content = "업타운의 위협은 다 제거한 게 확실하지? 별다른 일 없으면 난 먼저 가겠어.",
  ui_story_7_7_46_dialog_content = "제1군단은 아직 동쪽 방어 임무가 남았거든. 「호위대 덕분에」 말이지.",
  ui_story_7_7_47_dialog_content = "...어찌 됐든, 협력해 준 건 감사하고 있어. 일루미나.",
  ui_story_7_7_48_dialog_content = "감사할 필요 없어. 바이스랑 PlayerName한테나 감사해.",
  ui_story_7_7_A2_dialog_content = "모든 사람이 인내심을 가지고 백야성 놈들과 협력할 수 있는 건 아니니까.\n뒤를 너희한테 맡기는 건 더더욱 말할 것도 없다고.",
  ui_story_7_7_49_dialog_content = "......",
  ui_story_7_7_50_dialog_content = "알 수 없는 말만 남기고 가버렸네요. 시로나는 가끔 저래요. 너무 신경 쓰지 마세요. 카렌.",
  ui_story_7_7_51_dialog_content = "위기가 일단락됐으니 이게 최선의 결과겠죠.",
  ui_story_7_7_52_dialog_content = "슈모르가 정면으로 백야성을 공격했지만, 이곳에 무너지지 않는 방어 수단이 있을 줄은 몰랐겠지...",
  ui_story_7_7_53_dialog_content = "다음은 어떻게 나올까? 방금 그 검은 콜로서스는 이미 보완이 끝난 건가?",
  ui_story_7_7_X1_dialog_content = "녀석은 이미 세 가지 부품을 모두 손에 넣었지만,\n다행히... 저 검은 콜로서스가 그리 강해 보이진 않아.",
  ui_story_7_7_54_dialog_content = "어쩌면 슈모르가 아직 보완을 마치지 않은 게 아닐까? 이번엔 우릴 너무 얕보고 공격해 온 것 같아.",
  ui_story_7_7_55_dialog_content = "그럼 여러분은 저쪽에서 약이 올라 예상 밖의 행동을 할 거라고 생각하나요?",
  ui_story_7_7_56_dialog_content = "설마 뭔가 엄청난 일이 일어나는 건 아니겠죠?",
  ui_story_7_7_57_dialog_content = "참모장님... 역시 그런 이야기는 안 하는 게 좋겠어요. 매번 하시는 말이 다 현실이 된다구요...",
  ui_story_7_7_58_option_content = "우리가 더 적극적으로 공격해야 해.",
  ui_story_7_7_59_option_content = "조용히 상황을 지켜보는 게 좋겠어.",
  ui_story_7_7_60_dialog_content = "동의해. 이럴 때일수록 기세를 몰아 적극적으로 공격할 필요가 있어!",
  ui_story_7_7_61_dialog_content = "맞아. 그동안 부품을 빼앗기면서 충분히 많이 당했어. 이젠 우리가 반격할 차례야!",
  ui_story_7_7_62_dialog_content = "PlayerName의 말도 일리가 있어요~ 더 많은 정보를 확보하기 전까진 움직이지 않는 게 좋겠어요.",
  ui_story_7_7_63_dialog_content = "지금 가장 조급한 건 오히려 슈모르일 테니까요...",
  ui_story_7_7_A3_dialog_content = "세 개의 부품을 손에 넣었는데도 난관에 부딪혔으니, 이젠 저쪽에서 실수하는 걸 기다리는 게 좋겠어요!",
  ui_story_7_7_64_dialog_content = "으윽...!",
  ui_story_7_7_65_dialog_content = "PlayerName? 왜 그래!?",
  ui_story_7_7_66_dialog_content = "(머릿속에서... 뭔가 찌르는 듯한 고통이?!)",
  ui_story_7_7_67_dialog_content = "......",
  ui_story_7_7_68_dialog_content = "스카이워커호!",
  ui_story_7_7_69_dialog_content = "적의 습격입니다! ■■... 제 안으로 침입을...■■■... 적은... 혼자가 아닙...",
  ui_story_7_7_X2_dialog_content = "잘 안 들려! 스카이워커호, 위치는 아직 그대로야?! 지금 바로 갈게!",
  ui_story_7_7_X3_dialog_content = "...근처입니다! 부디...■■... 적은 이미 침입...■■■■... 혼자가 아닙니다!",
  ui_story_7_7_A4_dialog_content = "...가능하다면... <color=#FFB400>■■■■</color>. 다시 한번 말합니다. <color=#FFB400>지원</color>■■■... ■■■!",
  ui_story_7_7_X4_dialog_content = "스카이워커호에 침입자가 들어왔어! 슈모르 녀석이 공격 목표를 바꾼 거야!",
  ui_story_7_7_X5_dialog_content = "?!",
  ui_story_7_7_X6_dialog_content = "백야성을 공격할 수 없으니까 이번엔 우리를 노린 거야?!",
  ui_story_7_7_70_dialog_content = "어서 지원하러 가세요. 이번엔 저도 비공정을 가지고 오지 않았는데...\n백야성에 좀 빌릴 수 있을까요? 카렌.",
  ui_story_7_7_71_dialog_content = "난...",
  ui_story_7_7_72_dialog_content = "호위대장님, 성주님께서 다시 명령을 내리셨습니다.\n대장님... 어서 업타운으로 돌아와 보고하셔야 합니다.",
  ui_story_7_7_73_dialog_content = "잠깐이면 돼. 긴급 상황이야. 우선 이쪽을 도와야...",
  ui_story_7_7_74_dialog_content = "이건 요청이 아닙니다... 죄송합니다. 그래도 돌아가지 않으신다면, 사천사를 동원할 수밖에 없습니다.",
  ui_story_7_7_75_dialog_content = "...에에?! 우린 가만히 있었는데 왜 갑자기 거기서 우리가 나와?",
  ui_story_7_7_76_dialog_content = "......",
  ui_story_7_7_77_dialog_content = "카렌, 너희 아버님도 생각해 둔 계획이 있으실 거야. 이제 돌아가.",
  ui_story_7_7_78_dialog_content = "걱정하지 마. 지금 스카이워커호의 문제는 우리 일루미나의 일이야. 우리가 직접 해결할게.",
  ui_story_7_7_79_dialog_content = "잠깐, 내가 언제부터 일루미나의 사람이 된 건데...",
  ui_story_7_7_80_dialog_content = "......",
  ui_story_7_7_81_dialog_content = "......",
  ui_story_7_7_82_dialog_content = "뭔가 차선책을 택하는 느낌인데... 내 콜로서스의 보완은 얼마나 더 걸려?",
  ui_story_7_7_83_dialog_content = "금방이야. 걱정하지 마. 뭘 하려는 거든 서두르는 게 좋을 거야.\n내 인내심에는 한계가 있으니까, 슈모르.",
  ui_story_7_7_85_dialog_content = "당연하지. 그저 전에 속삭이는 회랑에서 끝내지 못한 일을 마무리 짓고 싶은 것뿐이야...",
  ui_story_7_7_86_dialog_content = "PlayerName, 그 녀석은 너무 특이해. 아이테르의 목숨을 살려주고 싶은 생각이 들은 건 처음이라니까.",
  ui_story_7_7_87_dialog_content = "올 거야. 예감이 들어. 「인연」이든, 아니면 「도의」든...",
  ui_story_7_7_A5_dialog_content = "PlayerName 녀석은 분명히 그런 썩어빠진 관념 때문에 이곳으로 돌아올 거야.",
  ui_story_7_7_89_dialog_content = "그럼 기다리지 마. 쓸데없이 말을 많이 해서 죽은 녀석이 얼마나 많아?\n그 정도는 내가 말하지 않아도 알겠지.",
  ui_story_7_7_90_dialog_content = "<color=#FFB400>죽여버려</color>, 슈모르.",
  ui_story_7_7_91_dialog_content = "스카이워커호, 내 오랜 친구...",
  ui_story_7_7_92_dialog_content = "<size=45>아마 조금 아플 거야!</size>",
  ui_story_7_8_1_dialog_content = "스카이워커... 들려?",
  ui_story_7_8_2_option_content = "[감응을 시도한다]",
  ui_story_7_8_3_dialog_content = "스카이워커, 스카이워커...",
  ui_story_7_8_4_option_content = "[감응을 시도한다]",
  ui_story_7_8_5_dialog_content = "안 돼. 감응이 되질 않아! 거기다 실드의 방해까지 더해져서...",
  ui_story_7_8_6_dialog_content = "최대한 빨리 콜로서스로 돌아가야 해!",
  ui_story_7_8_7_dialog_content = "저도 백야성의 비공정을 호출할 권한은 없는 것 같네요. 역시 호위대의 허가를 받아야 하는 걸까요?",
  ui_story_7_8_8_dialog_content = "가장 가까운 일루미나 거점에서 불러오더라도 시간이 꽤 걸릴 텐데요...",
  ui_story_7_8_9_dialog_content = "하지만 카렌도 방법이 없어...",
  ui_story_7_8_11_dialog_content = "카렌은 성주의 딸로서, 그리고 백야성의 호위대장으로서 이미 우릴 위해 많은 것을 해줬어.",
  ui_story_7_8_12_dialog_content = "맞아요~ 만약 카렌이 또 항명해서 비공정을 가지고 나타난다면,\n우린 적어도 일 년 정도는 미안해해야 할걸요?",
  ui_story_7_8_13_dialog_content = "...망했어, 참모장님이 「말이 씨가 된다」 능력을 시전했어...",
  ui_story_7_8_14_dialog_content = "──저길 봐!",
  ui_story_7_8_15_dialog_content = "말 끊어서 미안한데, 저쪽에 갑자기 비공정 하나가 날아올랐는데?",
  ui_story_7_8_16_dialog_content = "비행이 영 서투른데? 우리 쪽으로 오고 있는 것 같지 않아...?",
  ui_story_7_8_17_dialog_content = "......?",
  ui_story_7_8_18_dialog_content = "에?",
  ui_story_7_8_19_dialog_content = "아니겠지?! 카렌, 너...",
  ui_story_7_8_20_dialog_content = "서둘러! 일단 올라와! 이건 <color=#FFB400>빼앗아</color> 온 거라고!",
  ui_story_7_8_21_dialog_content = "빼, 빼앗다니?! 너 호위대장 아니었어?",
  ui_story_7_8_22_dialog_content = "나중에 다시 설명할게! 스카이워커호로 돌아가야 하는 거 아냐? 그래서 안 갈 거냐고!",
  ui_story_7_8_23_dialog_content = "이거면 늦지 않겠어!",
  ui_story_7_8_24_dialog_content = "미안해, PlayerName... 내가 늦었어...",
  ui_story_7_8_25_option_content = "아니. 넌 이미 우릴 위해 너무 많은 걸 했어.",
  ui_story_7_8_26_option_content = "괜찮아, 네가 비공정도 조정할 수 있을 줄은 몰랐네.",
  ui_story_7_8_27_dialog_content = "그래. 지금까지 난 그저 백야성을 지키는 일만 생각해 왔어...",
  ui_story_7_8_28_dialog_content = "하지만 이제 알겠어. 나도 지키고 싶은 다른 게 있는 것 같아.",
  ui_story_7_8_29_dialog_content = "농담하는 걸 보니 기분은 나쁘지 않은 모양이네.",
  ui_story_7_8_30_dialog_content = "어서 스카이워커호로 돌아가자!...분명히 우릴 기다리고 있을 테니까.",
  ui_story_7_8_31_dialog_content = "난 죽음이 두렵지 않습니다. <color=#FFB400>그때</color>, 당신의 앞에서 물러서지 않았던 것처럼 말입니다.",
  ui_story_7_8_32_dialog_content = "당신은 빛의 신조를 져버리고, 어둠의 저편에 숨어들 수 있겠지요...",
  ui_story_7_8_A1_dialog_content = "하지만 오직 오로라만이 모든 생명의 귀착점이 될 것입니다.",
  ui_story_7_8_33_dialog_content = "슈모르, 당신은 내 의식을 파괴할 수 있지만, 절대... PlayerName까지 무너트릴 순 없을 겁니다.",
  ui_story_7_9_1_dialog_content = "역시, 슈모르가 스카이워커호를 공격한 거였어!",
  ui_story_7_9_2_dialog_content = "이미 수많은 암귀가 침입했어요. 공기 속에서 다크매터의 악취가 풍겨와요.",
  ui_story_7_9_3_dialog_content = "이놈들이... 내 스카이워커호를 이 지경으로 만들다니!",
  ui_story_7_9_4_dialog_content = "아홉 시 방향에서 온다. 이 더러운 녀석들이 우릴 발견했어...",
  ui_story_7_9_5_dialog_content = "우선 싸우자!",
  ui_story_7_9_6_dialog_content = "다행히 큰 소란으로 이어지진 않았어. 다른 녀석들을 자극하진 않은 것 같아.",
  ui_story_7_9_7_dialog_content = "그럼 최고 속도로 돌진해서 슈모르가 반응하기도 전에...",
  ui_story_7_9_8_dialog_content = "그, 그건 무리일 것 같은데...",
  ui_story_7_9_9_dialog_content = "카렌, 지금 같은 상황에서... 꼭 우리와 위험을 무릅쓸 필요는 없어.",
  ui_story_7_9_10_dialog_content = "우린 동료야. 너희가 그렇게 말했잖아. 그렇지?",
  ui_story_7_9_11_dialog_content = "게다가 강적이 눈앞에 나타났는데, 내 창으로 직접 쓰러트리지 않으면 편히 잠들 수 없을 거야.",
  ui_story_7_9_12_option_content = "...역시 카렌답네.",
  ui_story_7_9_13_option_content = "맞아, 우린 동료야.",
  ui_story_7_9_14_dialog_content = "음? 그건 무슨 뜻이지?",
  ui_story_7_9_15_dialog_content = "PlayerName의 말은 카렌이 역시 백야성의 호위대장답다는 뜻이겠지?",
  ui_story_7_9_A1_dialog_content = "책임감도 있고, 정말 용감하잖아.",
  ui_story_7_9_16_dialog_content = "그런가. 하지만 지금 날 치켜세운다고 상황이 바뀌진 않을 거야.",
  ui_story_7_9_17_dialog_content = "굳이 그렇게 말하지 않아도 나는... 함께 싸울 거니까. 그래, 우린 <color=#FFB400>동료</color>니까.",
  ui_story_7_9_18_dialog_content = "비록 다들 백야성이 무정하다고들 하지만, 카렌 넌 달라.",
  ui_story_7_9_19_dialog_content = "...나도 그 점이 모순이라고 생각해. 난 백야성을 대표해야 할까, 아니면 나 자신을 대표해야 할까?",
  ui_story_7_9_20_dialog_content = "그 결론은 이미 행동으로 내린 것 같은데?",
  ui_story_7_9_21_dialog_content = "훗, 그럴지도.",
  ui_story_7_9_22_dialog_content = "우리가 동료인 건 알고 있어. 근데 왜 반복해서 강조하는 거야?",
  ui_story_7_9_23_dialog_content = "네가 방금 「그렇지?」라고 물어봤잖아... 됐어, 지금 이런 잡담을 할 상황은 아니니까.",
  ui_story_7_9_24_dialog_content = "카렌, 이제부터 우리한테 어떤 일이 닥칠지는 알고 있지?\n지금까지는 곤경에 빠지긴 했어도 그렇게 위험하진 않았어. 하지만...",
  ui_story_7_9_25_dialog_content = "아, 왠지 안 좋은 예감이 드는데요?",
  ui_story_7_9_26_dialog_content = "참모장님, 그만 좀 하세요...",
  ui_story_7_9_27_dialog_content = "슈모르가 얼마나 강하든지 간에, 우린 반드시 이겨야만 하는 이유가 있어. 안 그래?",
  ui_story_7_9_28_dialog_content = "비록 「<color=#FFB400>지키고 싶은 게 있다</color>」는 말은 진부하겠지만...",
  ui_story_7_9_A2_dialog_content = "결국, 필사적으로 싸우는 건 소중한 사람과 소중한 무언가를 지키기 위해서야.",
  ui_story_7_9_29_dialog_content = "응, 스카이워커호라든지.",
  ui_story_7_9_30_dialog_content = "그래, 스카이워커호...",
  ui_story_7_9_31_dialog_content = "PlayerName, 스카이워커호와 감응할 수 있어? 무사한지 확인하는 게 좋을 것 같아...",
  ui_story_7_9_32_dialog_content = "감응은 되지 않아. 하지만 아직 살아있을 거라고 믿어.",
  ui_story_7_9_33_dialog_content = "그러고 보니 콜로서스와 대화를 나눠볼 기회는 아직까지 한 번도 없었네요. 과연 어떨지 조금 궁금한걸요.",
  ui_story_7_9_A3_dialog_content = "아, 미안해요. 쓸데없는 말을 했네요.",
  ui_story_7_9_34_dialog_content = "그보다 어째서 비비안 씨도 따라온 건데...?",
  ui_story_7_9_35_dialog_content = "카렌과 같은 이유겠죠? 그 녀석 때문에 이래저래 고생했으니까,\n저도 이 짜증을 실컷 퍼부어주고 싶은걸요~",
  ui_story_7_9_36_dialog_content = "좋아요. 그럼 서두르죠. PlayerName, 슈모르는 어디 있어?",
  ui_story_7_9_37_dialog_content = "느껴져. 이 한기의 근원... <color=#FFB400>함교</color>에 있어!",
  ui_story_7_9_A4_dialog_content = "가는 길에 암귀가 꽤 많을 거야. 다들 준비됐지?",
  ui_story_7_9_A5_dialog_content = "당연하지, 내 손에서 창을 한순간도 놓은 적 없다고!",
  ui_story_7_12_1_dialog_content = "PlayerName... 이 말이 전해질지는 모르겠지만...",
  ui_story_7_12_2_dialog_content = "당신과 함께한 건 최고의 영광이었습니다.\n17년 전에 당신을 지킬 수 있었던 건 제 행운이었습니다. 세상의 희망을 지켰으니 말입니다.",
  ui_story_7_12_3_dialog_content = "가능하다면 <color=#FFB400>오지 마십시오</color>. 다시 한번 말합니다. <color=#FFB400>지원은 필요 없습니다</color>──",
  ui_story_7_12_A1_dialog_content = "적은 우리가 상상한 것보다 훨씬 강합니다.",
  ui_story_7_12_4_dialog_content = "힘을 모으십시오, PlayerName. 제 죽음에 슬퍼할 필요는 없습니다...",
  ui_story_7_12_5_dialog_content = "콜로서스는 <color=#FFB400>본래 당신들을 위해 태어난 것이니</color> 말입니다.",
  ui_story_7_13_1_dialog_content = "<size=45>으윽──!</size>",
  ui_story_7_13_2_dialog_content = "(<color=#FFB400>심장 박동</color>이... 격해지기 시작했어...)",
  ui_story_7_13_3_dialog_content = "이제 곧 함교야! 적을 조심해!",
  ui_story_7_13_4_dialog_content = "아직도 스카이워커호와 연락이 되지 않는 건가요?",
  ui_story_7_13_5_dialog_content = "시도 중이야. 뭔가 은은하게 들리고 있어... 어떤 말을 계속 반복하는 것 같아.",
  ui_story_7_13_6_dialog_content = "하지만 조금 전부터 그 말조차 들리지 않아. 설마...",
  ui_story_7_13_7_dialog_content = "(이건── 심장의 박동이 또 격해졌어?!)",
  ui_story_7_13_8_dialog_content = "왜 그래, PlayerName?",
  ui_story_7_13_9_dialog_content = "이곳의 다크매터가 너무 짙어서 그런가? PlayerName의 몸이 적응하기 힘들 거야.",
  ui_story_7_13_10_dialog_content = "아니면 무언가 감응한 거야?",
  ui_story_7_13_11_dialog_content = "에? 정말? 스카이워커호야?",
  ui_story_7_13_12_dialog_content = "아니, 아니야. 나도 느꼈어... <color=#FFB400>공기가 갑자기 싸늘해진 것</color> 같지 않아?",
  ui_story_7_13_13_dialog_content = "이 낯설고도 익숙한 느낌, 그 오만하고 역겨운 녀석...",
  ui_story_7_13_14_dialog_content = "...?!",
  ui_story_7_13_15_dialog_content = "하아~암.",
  ui_story_7_13_16_dialog_content = "<size=45><color=#FFB400>슈모르</color>──!</size>",
  ui_story_7_13_17_dialog_content = "PlayerName! 슈모르가 느껴져?! 어디 있는 거야?",
  ui_story_7_13_18_dialog_content = "너... 슈모르... 스카이워커호에 무슨 짓을... 으윽...!",
  ui_story_7_13_19_dialog_content = "역시 여전하네... 학습 능력이 전혀 없잖아, PlayerName.",
  ui_story_7_13_20_dialog_content = "내가 스카이워커호에 뭘 할 수 있겠어? 의식 모듈을 부수는 것밖에 없잖아?",
  ui_story_7_13_21_dialog_content = "의식 모듈? 지금 스카이워커호의 「자아의식」을 파괴했다는 거야?!",
  ui_story_7_13_22_dialog_content = "그래. 「심장이 산 채로 뽑히고 영혼까지 꿰뚫리는 느낌」, 못 느꼈어?",
  ui_story_7_13_23_dialog_content = "슈모르... 이 자식──!",
  ui_story_7_13_24_dialog_content = "못 알아들을까 다시 말해줄게... 네 스카이워커호는 <color=#FFB400>이미 죽었어</color>.",
  ui_story_7_14_1_dialog_content = "...놓쳤다고?",
  ui_story_7_14_2_dialog_content = "우아앗! 죄송합니다! 카렌 언니가 너무 빨라서... 눈 깜짝할 사이에 날아가서 사라져버렸어요...",
  ui_story_7_14_3_dialog_content = "라파엘도 공중을 한 바퀴 살펴봤지만, 그 무시무시한 검은 콜로서스와 작고 하얀 콜로서스밖에 없었어요!",
  ui_story_7_14_4_dialog_content = "하얀 콜로서스라... PlayerName... 하, 꼬마들을 한데 모은 건가.",
  ui_story_7_14_5_dialog_content = "검은 콜로서스의 움직임은?",
  ui_story_7_14_6_dialog_content = "없습니다. 여전히 실드를 공격하고 있습니다. 암귀의 공세도 줄어들지 않고 있습니다.",
  ui_story_7_14_7_dialog_content = "실드에 필요한 에너지 소모량은 계속 유지하라.\n비축한 루미나는 귀족 구역과 기초 시설에 우선적으로 공급하도록.",
  ui_story_7_14_A1_dialog_content = "그리고 병력을 신속히 다운타운 구역에 보내 지원하라.",
  ui_story_7_14_9_dialog_content = "...그, 그, 그럼, 카렌 언니는요...?",
  ui_story_7_14_10_dialog_content = "카렌은 자신의 선택을 했을 뿐이다. 그에 걸맞은 각오를 했겠지.",
  ui_story_7_14_11_dialog_content = "나로서는 지금 호위대를 그런 쓸데없는 「추격」에 출동시킬 이유가 전혀 없다.",
  ui_story_7_14_12_dialog_content = "네...",
  ui_story_7_14_13_dialog_content = "허나 그 비공정을 어떻게 빼앗은 것이냐... 좋지 않은 선례가 되겠군.",
  ui_story_7_14_14_dialog_content = "만약 다른 호위대원까지 사적으로 백야성을 이탈해 <color=#FFB400>지원하러 간다면</color>...",
  ui_story_7_14_15_dialog_content = "에? 왜 갑자기 라파엘을 쳐다보시는 거죠...?",
  ui_story_7_14_16_dialog_content = "음, 다른 문제가 더 있느냐.",
  ui_story_7_14_17_dialog_content = "아...아하! ...음... 아니요! 알겠습니다!",
  ui_story_7_14_18_dialog_content = "그럼 라파엘도 지금 바로 출발... 아, 아니! 이만 물러...가겠습니다...",
  ui_story_7_14_19_dialog_content = "느려 빠진 쥐새끼들, 자기 집에서 길을 잃기라도 한 거야?",
  ui_story_7_14_20_dialog_content = "닥쳐라, 암귀. 헛소리를 할 시간에 차라리 유언이나 남기지 그래!",
  ui_story_7_14_21_dialog_content = "뭔가 잘못 알고 있는 거 아니야, 아가씨? 지금 난 <color=#FFB400>모든 부품</color>의 힘을 가지고 있다고.",
  ui_story_7_14_X1_dialog_content = "PlayerName 녀석과 같이 죽으러 올 바에는 백야성에 틀어박히는 편이 낫지 않았을까?",
  ui_story_7_14_22_dialog_content = "하지만 넌 백야성의 실드를 뚫을 수 없어. 안 그래?\n보아하니 그 잘난 「보완」의 결과도 결국 그게 전부였던 모양이지?",
  ui_story_7_14_23_dialog_content = "닥쳐, 아이테르. 지금의 검은 콜로서스는 아직 완전하지 않아...",
  ui_story_7_14_A2_dialog_content = "그때가 되면 너희들을 위해 「일등석」을 남겨줄게.",
  ui_story_7_14_X2_dialog_content = "(역시 콜로서스의 보완이 아직 끝난 게 아니었어...!)",
  ui_story_7_14_X3_dialog_content = "그런 눈빛으로 날 보지 마, PlayerName.",
  ui_story_7_14_24_dialog_content = "백야성을 공격하는 와중에 직접 너흴 처리하러 온 것만으로도 이미 내 인내심의 한계니까.",
  ui_story_7_14_25_dialog_content = "그나저나 바이스, PlayerName. 저 암귀가 그렇게 강한가요?",
  ui_story_7_14_26_dialog_content = "확실히 보기엔 만만치 않은 상대지만, 우리가 힘을 합친다면 또 다르지 않겠어요?",
  ui_story_7_14_27_dialog_content = "시로나 군단장도 불러올 수 있다면 더 좋겠지만요...",
  ui_story_7_14_28_dialog_content = "꿈도 야무지네. 지금 너희 연합군을 다 불러와도 「이 아이」의 상대는 안 될걸...",
  ui_story_7_14_A3_dialog_content = "내 검은 콜로서스는 지금 무럭무럭 자라고 있거든...",
  ui_story_7_14_29_dialog_content = "뭐, 너희의 그 낙관적인 태도는 정말 감탄스럽다니까. 일루미나 사람들은 모두 그렇게 자신만만한 거야?",
  ui_story_7_14_30_dialog_content = "적당히 해 둬, 슈모르. 더는 변수를 만들지 마.",
  ui_story_7_14_31_dialog_content = "알겠다고. 지긋지긋한 잔소리.",
  ui_story_7_14_32_dialog_content = "......",
  ui_story_7_14_33_dialog_content = "왜 그래? 비비안 씨?",
  ui_story_7_14_34_dialog_content = "슈모르 뒤의 저 사람... 왠지 <color=#FFB400>눈에 익어요</color>.",
  ui_story_7_14_38_dialog_content = "뭐라고 속닥거리는 거야? 크게 말하지 않으면 네 유언은 아무도 못 들을걸.",
  ui_story_7_14_39_dialog_content = "하지만 PlayerName, 넌 특별해...",
  ui_story_7_14_A4_dialog_content = "난 알아. 넌 밑바닥의 약자로 살아가는 거로는 영원히 만족하지 못할 거야... 너도 나랑 똑같아.",
  ui_story_7_14_40_dialog_content = "자, 나한테 와. 네가 있어야 할 곳으로 오는 거야.",
  ui_story_7_14_41_dialog_content = "그래야만 너도 네 운명을 바꿀 힘을 얻을 수 있어.",
  ui_story_7_14_42_dialog_content = "운명을 바꿀 힘? 그게 어떤 힘인데?",
  ui_story_7_14_43_dialog_content = "세상을 보는 눈, 무한한 수명, 끝없는 지혜, 강력한 다크매터, 그리고 숨겨진 진실.",
  ui_story_7_14_44_dialog_content = "가장 중요한 건 더는 누군가에게 죽을 걱정을 하지 않아도 된다는 거야...\n남을 죽이는 건 오직 너야. 넌 모든 사람들을 압도하는 강자가 될 거라고.",
  ui_story_7_14_46_dialog_content = "좀 더 빨리 말해줄래? 내가 좀 바쁘거든.",
  ui_story_7_14_47_dialog_content = "뭐...?",
  ui_story_7_14_48_dialog_content = "미안, 난 네가 하는 말에는 조금도 관심이 없어.",
  ui_story_7_14_49_dialog_content = "뜬구름 잡는 소리만 입에 달고 사는 게 그렇게 좋아? 자기가 하는 말이 무슨 뜻인지는 알아?",
  ui_story_7_14_50_dialog_content = "「내 신념이 옳다」, 「운명을 바꾸고 싶다」, 「남이 날 해치려고 하니까 강해지려는 거다」...",
  ui_story_7_14_51_dialog_content = "그런 말도 안 되는 이유로 남의 목숨을 해치는 녀석이야말로 이 세계에서 사라져야 한다고.",
  ui_story_7_14_52_dialog_content = "넌 약자를 만나면 없애고, 강자를 만나면 무릎 꿇고 자비를 구하고,\n강자에게 빌붙어서 힘을 갈구해온 거지?",
  ui_story_7_14_A5_dialog_content = "이해할 수 없어. 어떻게 그런 자신이 옳다고 믿을 수 있는 거지?\n내가 너처럼 되고 싶어 할 거라고 생각했어?",
  ui_story_7_14_53_dialog_content = "그러니까 결론을 내자면... 너처럼 「이 세상에서 내 말만이 맞아」라고 생각하는 녀석은...",
  ui_story_7_14_54_dialog_content = "일루미나든 백야성이든 병원에 가서 검사를 받아 봐.\n머리에 든 게 뇌가 아니고 어딘가의 면 요리일 수도 있으니까.",
  ui_story_7_14_55_dialog_content = "............",
  ui_story_7_14_56_dialog_content = "PlayerName... 단숨에 그렇게...",
  ui_story_7_14_57_dialog_content = "속시원한 말을 잘도 해버렸네...",
  ui_story_7_14_F1_dialog_content = "아, 맞다. 하나 더 궁금한 게 있는데... 넌 그 힘을 얻기 위해 몇 번이나 무릎을 꿇은 거야?",
  ui_story_7_14_58_dialog_content = "아하하.",
  ui_story_7_14_59_dialog_content = "<size=50>하하하, 아하하하하하!</size>",
  ui_story_7_14_60_dialog_content = "이런 쓰레기 같은 게... 호의도 모르고! 멍청하긴!",
  ui_story_7_14_61_dialog_content = "감히 날 화나게 해? 죽고 싶다 이거지?\n죽음 따윈 두렵지 않다고 증명하고 싶은 거야? 네 생각대론 안 될 거야...",
  ui_story_7_14_63_dialog_content = "헤에, 드디어 진짜로 움직이려나 보네.",
  ui_story_7_14_A6_dialog_content = "「힘」의 성장에는 역시 분노가 특효약이란 말이지.",
  ui_story_7_14_64_dialog_content = "오래도록 천천히, 고통스럽게 만들어 줄게. 힘없는 자의 굴욕이 뭔지 뼈저리게 느낄 수 있도록 말이야!",
  ui_story_7_14_F2_dialog_content = "내 말이 옳다는 걸 알게 될 거야!",
  ui_story_7_14_65_dialog_content = "그건 내가 할 말이라고. <color=#FFB400>「아이테르의 배신자」, 슈모르</color>!",
  ui_story_7_14_66_dialog_content = "계속해! 덤비라고! 뭘 꾸물대고 있어?!",
  ui_story_7_14_67_dialog_content = "너, 너무 강하잖아... 이런 힘이라니...",
  ui_story_7_14_68_dialog_content = "...난 아직 움직일 수 있어. 다음 공격을 준비해! 절대 살려 보내서는...",
  ui_story_7_14_69_dialog_content = "이성적으로 생각해! 우린... 다른 방법을 찾아야 해.",
  ui_story_7_14_70_dialog_content = "아아, 인정하고 싶지 않지만 PlayerName의 말이 맞아요...",
  ui_story_7_14_A7_dialog_content = "다른 사람들을 데리고 오지 않아 다행이에요. 아니면 모두 이곳에 발목이 잡혔겠죠?",
  ui_story_7_14_71_dialog_content = "지금은 도망가라고 해도 도망치지 못할 것 같은걸요...",
  ui_story_7_14_72_dialog_content = "도망쳐?! 떠나고 싶나? 좋아, 내가 너흴 갈기갈기 찢어서 밖에 뿌려주는 건 어때?!",
  ui_story_7_14_73_dialog_content = "백야성의 하늘에서 피의 비가 내리게 말이야!",
  ui_story_7_14_74_dialog_content = "보완이 끝났어. 슈모르, 검은 콜로서스가 이제 「<color=#FFB400>완성</color>」됐어.",
  ui_story_7_14_75_dialog_content = "딱 맞췄네. 그렇지? 눈앞의 가축들을 새로운 탄생의 제물로 바치면 되지 않겠어?!",
  ui_story_7_14_76_dialog_content = "저기... 방해해서 미안한데, 조금 전부터 계속 신경 쓰였거든요... 당신은 도대체 누구죠?",
  ui_story_7_14_77_dialog_content = "하아?! 아직도 모르는 거냐?",
  ui_story_7_14_78_dialog_content = "좀 비켜봐요. 제가 말한 건 당신 뒤의 그... 고위 암귀 말이에요.",
  ui_story_7_14_79_dialog_content = "......",
  ui_story_7_14_80_dialog_content = "아니, 암귀라기보단 당신은 <color=#FFB400>오로리안</color> 같은데요.",
  ui_story_7_14_81_dialog_content = "?! 오로리안?",
  ui_story_7_14_82_dialog_content = "체형, 기운, 그리고 말투... 제 직감이 말해주고 있어요. 당신은 태생적인 암귀가 아니군요.",
  ui_story_7_14_83_dialog_content = "...직감이라... 시시한 근거네.",
  ui_story_7_14_84_dialog_content = "<color=#FFB400>당신은 누구죠?</color> 말해줘요. 전 반드시 알아야겠어요.",
  ui_story_7_14_85_dialog_content = "거절할게.",
  ui_story_7_14_86_dialog_content = "<size=45>말해요! 당장!</size>",
  ui_story_7_14_87_dialog_content = "비비안 씨, 갑자기 왜...",
  ui_story_7_14_88_dialog_content = "다시 한번 거절하지. 이유는...",
  ui_story_7_14_89_dialog_content = "내 이름은 진작에 「<color=#FFB400>박탈</color>」당했으니까.",
  ui_story_7_14_90_dialog_content = "......",
  ui_story_7_14_91_dialog_content = "이 아름다운 세상, 「<color=#FFB400>여명의 빛</color>」 아래에서... 이름 없는 자가 어떻게 살아갈 수 있겠어?",
  ui_story_7_14_92_dialog_content = "...당신은 한때 일루미나의 일원이었군요.",
  ui_story_7_14_94_dialog_content = "맞아.",
  ui_story_7_14_95_dialog_content = "내 얼굴, 이 흉터를 봐... 이건 불에 탔던 흔적이야. 보여?",
  ui_story_7_14_97_dialog_content = "......",
  ui_story_7_14_F3_dialog_content = "어때...",
  ui_story_7_14_98_dialog_content = "생각이 좀 났나?",
  ui_story_7_14_99_dialog_content = "...생각났기보다는 확실해졌다고 해야겠죠.",
  ui_story_7_14_100_dialog_content = "감각이 예민하네. 오랜 시간이 지났는데도 그 통찰력은 여전한걸...",
  ui_story_7_14_101_dialog_content = "비비안 씨, 둘이... 아는 사이야?",
  ui_story_7_14_102_dialog_content = "아는 사이일 뿐만이 아니라, PlayerName...",
  ui_story_7_14_103_dialog_content = "이 잔혹한 일에 가담한 저 고위 암귀는 한때... <color=#FFB400>일루미나의 동료</color>였어요!",
  ui_story_7_14_104_dialog_content = "놀랄 것도 없잖아?",
  ui_story_7_14_A8_dialog_content = "그것보다 <color=#FFB400>노라</color> 너, 평소에는 나한테 시끄럽다고 해놓고,\n지금은 네가 이 바퀴벌레들이랑 잡담을 하고 있잖아? 뭐 하자는 거야?",
  ui_story_7_14_105_dialog_content = "<color=#FFB400>노라</color>...?",
  ui_story_7_14_109_dialog_content = "얘기나 조금 했을 뿐이야. 볼일은 끝났어. 마음껏 날뛰어 봐.",
  ui_story_7_14_110_dialog_content = "그건 그렇고... 검은 콜로서스가 보완된 후 방출하지 못한 대량의 에너지가 있거든.",
  ui_story_7_14_A9_dialog_content = "적절한 대상을 찾아봐.",
  ui_story_7_14_111_dialog_content = "그거라면 역시 눈앞의 이 도시가 가장 적합하지 않겠어?",
  ui_story_7_14_112_dialog_content = "오만하고 썩어 빠진, 실드가 절대 깨지지 않을 거라 생각하는 녀석들,\n오늘 오로리안의 그 믿음을 철저히 박살 내주겠어!",
  ui_story_7_14_113_dialog_content = "네 뜻대로 되진 않아! 백야성은 영원히 함락되지 않을 테니까. 암귀 주제에 그런...",
  ui_story_7_14_114_dialog_content = "<size=45>입 닥쳐, 오로리안!</size>",
  ui_story_7_14_115_dialog_content = "와라... 내 소중한 콜로서스!",
  ui_story_7_14_116_dialog_content = "네 거대한 몸과 핏빛 눈으로 저들을 두려움에 떨게 만드는 거야!",
  ui_story_7_14_117_dialog_content = "봤어?! 검은 콜로서스? 흑룡? 아니, 그런 이름이 아냐.",
  ui_story_7_14_118_dialog_content = "그래! 바로 이거야! 무릎을 꿇고 경배하라고! 이게 바로 내 <size=45><color=#FFB400>「디바우러호」</color></size>야!",
  ui_story_7_14_119_dialog_content = "저게 뭐지? 콜로서스라고? ...대체 슈모르가 무슨 짓을 한 거야?! PlayerName, 설명해 봐!",
  ui_story_7_14_120_dialog_content = "나한테 물어봤자 나도 몰라!",
  ui_story_7_14_121_dialog_content = "루미나가... 사라지고 있어?! 안 돼, 이대로 가만히 당할 순 없어!",
  ui_story_7_14_122_dialog_content = "몸이 말을 안 들어... 다들 움직일 수 있어?",
  ui_story_7_14_123_dialog_content = "...여러분, 제가 시간을 벌어 드릴게요.",
  ui_story_7_14_128_dialog_content = "여섯 시 방향이 가장 취약해요. 그쪽으로 도망쳐서 뛰어내려요. 살 수 있는 마지막 방법이에요.",
  ui_story_7_14_129_dialog_content = "그럼 또 봐요, 바이스, PlayerName, 그리고 카렌~",
  ui_story_7_14_130_dialog_content = "비비안 씨?!",
  ui_story_7_14_131_dialog_content = "<size=50>꿈 깨시지──!</size>",
  ui_story_7_14_133_dialog_content = "(대체...)",
  ui_story_7_14_134_dialog_content = "(뭐가 어떻게 된 거야...)",
  ui_story_8_1_1_1_dialog_content = "PlayerName? 어딜 보고 있어?",
  ui_story_8_1_1_2_dialog_content = "따라오지 않으면 길 잃을 거라구.",
  ui_story_8_1_1_3_dialog_content = "자, 내 손을 잡아.",
  ui_story_8_1_1_4_dialog_content = "왜 그런 표정을 하고 있어? 우리 같이 백야성 축제에 오기로 했었잖아?",
  ui_story_8_1_1_5_dialog_content = "저기 노점상에서 먹을 걸 파네! 한번 가볼까?",
  ui_story_8_1_1_6_option_content = "여긴... 어디야?",
  ui_story_8_1_1_7_dialog_content = "정말 잊어버린 거야? 여긴 백야성이야.",
  ui_story_8_1_1_8_option_content = "무슨 일이 생긴 거야?",
  ui_story_8_1_1_9_dialog_content = "무슨 일이라니? 일 년에 한 번 열리는 성대한 축제잖아. 당연히 다 같이 축하해야지!",
  ui_story_8_1_1_10_dialog_content = "갑자기 왜 그러는데~ 나 놀리는 건 아니지?",
  ui_story_8_1_1_11_dialog_content = "계속 그러면 나 화낼 거야! 이렇게, 으우우... 나 화났어! 흥!",
  ui_story_8_1_1_12_option_content = "바이스, 너 이상해.",
  ui_story_8_1_1_13_dialog_content = "내가? 뭐가 이상한데? 네가 아는 바이스가 나 말고 누가 있어~",
  ui_story_8_1_1_14_dialog_content = "쓸데없는 생각 말고 빨리 와. 또 그러면 진짜 화낼 거야!",
  ui_story_8_1_1_15_option_content = "...넌 누구지?",
  ui_story_8_1_1_16_dialog_content = "...응? 바이스지, 누구긴 누구야?",
  ui_story_8_1_1_17_dialog_content = "왜 그런 이상한 걸 묻는 거야! 빨리 와. 또 그러면 진짜 화낼 거야!",
  ui_story_8_1_1_18_dialog_content = "......",
  ui_story_8_1_1_19_dialog_content = "무슨 소리지...?",
  ui_story_8_1_1_20_dialog_content = "응? 뭐가 들렸어?",
  ui_story_8_1_1_21_dialog_content = "여긴 좀 이상해. 바이스, 뭔가 불편한 게 마치...",
  ui_story_8_1_1_22_dialog_content = "착각이야. PlayerName. 나랑 있으면서도 안심이 안 되는 거야? 날 믿어.",
  ui_story_8_1_1_23_dialog_content = "네가... 그 어떤 의문을 가지고 있든, 내가 다 답해줄 수 있어. 일단 내 손을 먼저 잡아줘. 응?",
  ui_story_8_1_1_24_dialog_content = "내가 알려줄게. 뭐든지 전부 다...",
  ui_story_8_1_1_25_dialog_content = "...PlayerName.",
  ui_story_8_1_1_26_dialog_content = "과거, 미래, 네가 알고 싶은 모든 것...",
  ui_story_8_1_1_27_dialog_content = "우리 같이 「내일」을 맞이하는 거야!",
  ui_story_8_1_1_28_dialog_content = "날 혼자 두지 마... 약속했잖아. 아니야?",
  ui_story_8_1_1_29_dialog_content = "...이 정도도 안 들리는 건가? 대체 언제까지 잘 생각이냐, PlayerName!",
  ui_story_8_1_1_30_option_content = "좋아. 절대로 떠나지 않을게.",
  ui_story_8_1_1_31_dialog_content = "다행이야! 드디어 이해했구나. 이제 받아들인 거지...? 그럼 약속대로, 영원히 떠나지 말아줘...",
  ui_story_8_1_1_32_dialog_content = "아이테르의 빈 껍데기는 내려놓고... 진정한 힘을 맞이하는 거야!",
  ui_story_8_1_1_33_option_content = "난 가야겠어. 넌 바이스가 아냐.",
  ui_story_8_1_1_34_dialog_content = "안 돼! 돌아와, 돌아와! 돌아오라고! 이 멍청한 아이테르가!",
  ui_story_8_1_1_35_dialog_content = "이게 얼마나 많은 사람이 바라던 기회인지 알아?! 어리석긴, 가엾기 짝이 없다니까!",
  ui_story_8_1_1_36_dialog_content = "내 목소리가 들린다면 어서 이 위험하고 달콤한 환상에서 벗어나...",
  ui_story_8_1_1_37_dialog_content = "자, 「지난날의 꿈」의 인도를 따르면 돼. 무엇이 진실인지 알려줄 테니까...",
  ui_story_8_1_1_38_dialog_content = "쿠우──!",
  ui_story_8_1_1_39_dialog_content = "(으윽! 아파, 이게 뭐야?!)",
  ui_story_8_1_1_42_dialog_content = "(뭔가가 내 몸 안에서 날아갔어?!)",
  ui_story_8_1_1_43_dialog_content = "(저건 뭐지? 어째서 저런 게...)",
  ui_story_8_1_1_44_dialog_content = "크오오──!",
  ui_story_8_1_1_45_dialog_content = "쿠우──!",
  ui_story_8_1_1_47_dialog_content = "아, 넌... 「퀴리」? 비비안 옆에 있던 녀석이지?",
  ui_story_8_1_1_48_dialog_content = "쿠우!",
  ui_story_8_1_1_49_dialog_content = "네 주인은? ...그리고 바이스는 어디 있어?",
  ui_story_8_1_1_50_dialog_content = "아까 그거, 설마 내 몸 안에서... 대체 그건 뭐였지...",
  ui_story_8_1_1_51_dialog_content = "으, 머리가 아픈데... 으윽, 어디 부딪히기라도 한 건가?",
  ui_story_8_1_1_52_dialog_content = "쿠우!",
  ui_story_8_1_1_53_dialog_content = "불쌍한 녀석, 넌 왜 온몸이 상처투성이인 건데... 너도 모두와 따로 떨어진 거야?",
  ui_story_8_1_1_54_dialog_content = "다들 어떻게 된 거지...",
  ui_story_8_1_1_55_dialog_content = "꿈 깨시지──!",
  ui_story_8_1_1_58_dialog_content = "으으, 아파라... 그 후의 일은 전혀 기억이 나질 않아.",
  ui_story_8_1_1_59_dialog_content = "바이스 쪽 상황은 어떤지 모르겠네...",
  ui_story_8_1_1_60_dialog_content = "PlayerName!",
  ui_story_8_1_1_61_dialog_content = "바이스?!",
  ui_story_8_1_1_62_dialog_content = "쉿! 나야, 목소리 좀 낮춰...",
  ui_story_8_1_1_63_dialog_content = "괜찮아? 사방에 다크매터의 기운이 가득해! 조금 전에...",
  ui_story_8_1_1_64_dialog_content = "알고 있어. 난 괜찮으니까 걱정 마! 넌? 괜찮아? 어디 다친 데는 없는 거지?",
  ui_story_8_1_1_65_option_content = "별로 좋지 않아.",
  ui_story_8_1_1_66_dialog_content = "별로... 좋지 않아. 다친 덴 없는데 몸이 엄청... 무거워.",
  ui_story_8_1_1_67_dialog_content = "머릿속도 좀 뿌옇고... 대체 여긴 어디야?",
  ui_story_8_1_1_68_dialog_content = "...아무것도 기억이 안 나는 거야? 여긴 「디바우러호」의 내부야, PlayerName.",
  ui_story_8_1_1_69_option_content = "모르겠어.",
  ui_story_8_1_1_70_dialog_content = "...잘 모르겠어. 조금 전에 깨어나서... 맞다. 나 꿈, 악몽을 꿨어! 꿈속에서...",
  ui_story_8_1_1_71_dialog_content = "음... 네가 있었어. 근데 너 같지가 않았어... 아니, 아냐. 분명히 네가 아니었어.",
  ui_story_8_1_1_F1_dialog_content = "참, 그리고 다른 녀석도 있었는데...",
  ui_story_8_1_1_72_dialog_content = "꿈? 꿈에서 날 봤다고? 근데 나 같지가 않았다고? 다른 녀석은 누군데?",
  ui_story_8_1_1_F2_dialog_content = "나도 정확히는 잘 모르겠어... 미안해.",
  ui_story_8_1_1_73_dialog_content = "그래서... 그리고는? 깨어나니 여기였던 거야?",
  ui_story_8_1_1_F3_dialog_content = "난... 응, 정신을 차려 보니 여기였어.",
  ui_story_8_1_1_74_dialog_content = "그래. 어쩌면 다크매터가 네 머리에 영향을 준 걸지도 몰라.\n그것도 그럴 게 여긴 「디바우러호」 안이니까...",
  ui_story_8_1_1_75_option_content = "여긴 대체 어디야?",
  ui_story_8_1_1_76_dialog_content = "여긴 「디바우러호」 안이야.",
  ui_story_8_1_1_77_dialog_content = "나도 이런 형태의 콜로서스는 처음 봐. 아니지, 이미 콜로서스라고 할 수도 없는 것 같아...",
  ui_story_8_1_1_78_dialog_content = "봐봐, 곳곳에 다크매터의 침식 흔적이 있어. 그야말로 암귀의 낙원이라니까.",
  ui_story_8_1_1_79_dialog_content = "오는 도중에 암귀를 잔뜩 만났어. 다른 녀석들이 눈치채지 못했어야 할 텐데...",
  ui_story_8_1_1_80_dialog_content = "잠깐, 잠깐만... 방금 네 말은 그러니까...",
  ui_story_8_1_1_81_dialog_content = "여기가 디바우러호의 내부라고?",
  ui_story_8_1_1_82_dialog_content = "응. 네가 슈모르한테 잡혀서 여기에 있다는 걸 알아낸 뒤에...",
  ui_story_8_1_1_83_dialog_content = "나도 따라 들어왔어.",
  ui_story_8_1_1_84_dialog_content = "뭐?! 왜 따라 들어온 거야? 너무 위험하잖아!",
  ui_story_8_1_1_88_dialog_content = "당연히 널 구하려고 온 거지! 네가 우릴 밀어버리고 혼자 스카이워커호에 남았는데, 내가 어떻게...",
  ui_story_8_1_1_89_dialog_content = "스톱, 스톱... 다시 천천히 이야기해봐... 대체 무슨 일이 벌어진 거야?",
  ui_story_8_1_1_90_dialog_content = "아니, 무슨 일이 있었든, 너 혼자 여기 오는 건 잘못됐어! 너무 위험하다고!",
  ui_story_8_1_1_91_dialog_content = "알아! 하지만 아무것도 안 할 순 없잖아?!",
  ui_story_8_1_1_92_dialog_content = "네가... 살아있을 수도 있다고 생각했어... 그래서 내가 뭘 할 수 있을까 싶어서... 결국...",
  ui_story_8_1_1_93_dialog_content = "무슨 뜻인지 알아. 바이스. 하지만...",
  ui_story_8_1_1_94_dialog_content = "이제 와서 그런 말 해봤자 소용없어. PlayerName, 난 이미 왔잖아!",
  ui_story_8_1_1_95_dialog_content = "이젠 같이 상황을 파악해야 해! 정신 바짝 차려!",
  ui_story_8_1_1_96_dialog_content = "쿠우!",
  ui_story_8_1_1_97_dialog_content = "퀴리, 네가 바이스랑 말 좀 해봐... 하아.",
  ui_story_8_1_1_98_dialog_content = "일단 그건 됐고, 그러니까 대체 무슨 일이 있었던 거야? 난 기억이 안 나.\n생각하려고만 하면 머리가 핑 돌면서 아파...",
  ui_story_8_1_1_99_dialog_content = "일단 움직이자! 여기서 멍하니 있지 말고 가면서 말하는 게 좋겠어.",
  ui_story_8_1_1_100_dialog_content = "그때 비비안 참모장님이 기회를 틈타서 우릴 내보내려고 했고, 그러자 슈모르가...",
  ui_story_8_1_1_101_dialog_content = "...여러분, 제가 시간을 벌어 드릴게요.",
  ui_story_8_1_1_103_dialog_content = "여섯 시 방향이 가장 취약해요. 그쪽으로 도망쳐서 뛰어내려요. 살 수 있는 마지막 방법이에요.",
  ui_story_8_1_1_104_dialog_content = "그럼 또 봐요, 바이스, PlayerName, 그리고 카렌~",
  ui_story_8_1_1_105_dialog_content = "비비안 씨?!",
  ui_story_8_1_1_106_dialog_content = "꿈 깨시지──!",
  ui_story_8_1_1_107_dialog_content = "당신 상대는 저예요!",
  ui_story_8_1_1_108_dialog_content = "생각보다... 잘 싸우네. 하찮은 녀석이!",
  ui_story_8_1_1_109_dialog_content = "......",
  ui_story_8_1_1_110_dialog_content = "불쾌해... 불쾌하다고... 그럼 조금만 더 진지해져 볼까...",
  ui_story_8_1_1_111_dialog_content = "그리고 거기! 살금살금 어딜 가는 거야?!",
  ui_story_8_1_1_112_dialog_content = "어서! 뛰, 뛰어내려!",
  ui_story_8_1_1_113_dialog_content = "이 정도 높이면... 하지만 다른 방법은 없어! 가자!",
  ui_story_8_1_1_114_dialog_content = "내 손을 잡아. 우리 같이...",
  ui_story_8_1_1_115_dialog_content = "크오오──!",
  ui_story_8_1_1_116_dialog_content = "이거 놔!",
  ui_story_8_1_1_117_dialog_content = "PlayerName!",
  ui_story_8_1_1_118_dialog_content = "(끌려간다!)",
  ui_story_8_1_1_119_dialog_content = "힘이 안 들어가... 어떡하지?! 반드시 같이...",
  ui_story_8_1_1_120_dialog_content = "......",
  ui_story_8_1_1_121_option_content = "너희라도 어서 가!",
  ui_story_8_1_1_122_dialog_content = "?!",
  ui_story_8_1_1_123_dialog_content = "PlayerName!",
  ui_story_8_1_1_124_dialog_content = "너, 너무 높잖아! 죽을 거야!",
  ui_story_8_1_1_125_dialog_content = "균형을 잡아. 바이스! 최소한 떨어질 때...",
  ui_story_8_1_1_126_dialog_content = "카──렌──언──니──!",
  ui_story_8_1_1_127_dialog_content = "받았어!",
  ui_story_8_1_1_128_dialog_content = "라파엘...? 네가 왜... 으윽, 아파!",
  ui_story_8_1_1_129_dialog_content = "이 비공정은... 카렌, 네가 지원을 부른 거야?",
  ui_story_8_1_1_130_dialog_content = "헤헤... 뭐라고 해야 하나? 지원군이라고 칠게! 라파엘이 도우러 온 거니까!",
  ui_story_8_1_1_131_dialog_content = "제시간에 도착해서 다행이야... 2초만 더 늦었어도...",
  ui_story_8_1_1_132_dialog_content = "쿠에엑──",
  ui_story_8_1_1_133_dialog_content = "무슨 소리지?",
  ui_story_8_1_1_134_dialog_content = "에? 엉덩이 밑에 뭔가...",
  ui_story_8_1_1_135_dialog_content = "쿠우──!",
  ui_story_8_1_1_136_dialog_content = "퀴리?!",
  ui_story_8_1_1_137_dialog_content = "미안, 미안해! 내가 널 깔고 앉았구나!",
  ui_story_8_1_1_138_dialog_content = "쿠우!",
  ui_story_8_1_1_139_dialog_content = "이건 바이스의 애완동물이야?",
  ui_story_8_1_1_140_dialog_content = "아니, 비비안 참모장님 거야.",
  ui_story_8_1_1_141_dialog_content = "에? 그럼 그 참모장은? 그리고 아이테르도 있지 않았어?",
  ui_story_8_1_1_142_dialog_content = "두 사람은...",
  ui_story_8_1_1_143_dialog_content = "......",
  ui_story_8_1_1_144_dialog_content = "라파엘, 우선 지금은 그게 중요한 게 아냐. 상황이 변했어.\n우린 최대한 빨리 돌아가서 성주님께 보고해야 해.",
  ui_story_8_1_1_145_dialog_content = "PlayerName 덕분에 겨우 벗어날 수 있었어, 그러니까 이 기회를 낭비해선 안 돼...",
  ui_story_8_1_1_146_dialog_content = "반드시 반격할 방법을 찾아야 해.",
  ui_story_8_1_1_147_dialog_content = "카렌, 무슨 계획이라도 있어?",
  ui_story_8_1_1_148_dialog_content = "돌아가서 「다모클레스」를 사용하도록 설득할 거야.",
  ui_story_8_1_1_149_dialog_content = "?!",
  ui_story_8_1_1_150_dialog_content = "그게 슈모르를 상대할 수 있는 유일한 방법이야.",
  ui_story_8_1_1_151_dialog_content = "하지만 「다모클레스」라면 10년 동안 가동하지 않았잖아? 전하께서 동의하실까?",
  ui_story_8_1_1_152_dialog_content = "동의하게 만들어야지. 디바우러호를 막을 수 있는 건 그것뿐이니까.",
  ui_story_8_1_1_153_dialog_content = "하지만... PlayerName도 구해야 해...",
  ui_story_8_1_1_154_dialog_content = "이건 온 백야성 전체의 존망이 걸린 문제야. 내겐 선택지가 없어... 그리고 그건 우리 모두 마찬가지야. 바이스.",
  ui_story_8_1_1_155_dialog_content = "......",
  ui_story_8_1_1_156_dialog_content = "뭐야? 뭘 하려는 건데?",
  ui_story_8_1_1_157_dialog_content = "너... 설마 스카이워커호로 돌아가려는 거야?",
  ui_story_8_1_1_158_dialog_content = "맞아...",
  ui_story_8_1_1_159_dialog_content = "카렌, 미안. 난 PlayerName, 그리고 비비안 참모장님을 포기할 수 없어.",
  ui_story_8_1_1_160_dialog_content = "바이스, 너...",
  ui_story_8_1_1_161_dialog_content = "네 생각은 이해해. 카렌. 하지만 동료를 버리는 건 못하겠어. 정말로...",
  ui_story_8_1_1_162_dialog_content = "바이스. 냉정하게 생각해. 지금 돌아가는 건 너무 위험해!",
  ui_story_8_1_1_164_dialog_content = "설마 PlayerName의 노력 덕분에 얻은 유일한 기회를 날려버릴 셈이야?",
  ui_story_8_1_1_165_dialog_content = "위험하다는 건 알고 있어, 카렌! 난... 스스로 방법을 찾겠어.",
  ui_story_8_1_1_166_dialog_content = "무슨 방법? 비공정은 한 척뿐이잖아!",
  ui_story_8_1_1_167_dialog_content = "마, 맞아...",
  ui_story_8_1_1_168_dialog_content = "바이스는 날지도 못하잖아... 아니면 일단...",
  ui_story_8_1_1_169_dialog_content = "......",
  ui_story_8_1_1_170_dialog_content = "퀴리... 부탁할게.",
  ui_story_8_1_1_171_dialog_content = "쿠우?",
  ui_story_8_1_1_172_dialog_content = "...쿠우?!",
  ui_story_8_1_1_173_dialog_content = "난 퀴리랑 함께 돌아갈 거야.",
  ui_story_8_1_1_174_dialog_content = "녀석이 정말로 널 태우고 날 수 있을 것 같아?",
  ui_story_8_1_1_175_dialog_content = "카렌, 내 몸무게가 좀 무겁긴 해도... 퀴리는 무척 강해!",
  ui_story_8_1_1_176_dialog_content = "쿠우!",
  ui_story_8_1_1_177_dialog_content = "알고 있어, 퀴리. 너도 돌아가서 네 주인을 구하고 싶지?",
  ui_story_8_1_1_180_dialog_content = "가려면 지금뿐이야. 여기서 돌아가는 건 그리 멀지 않아.",
  ui_story_8_1_1_181_dialog_content = "카렌...",
  ui_story_8_1_1_182_dialog_content = "네가 내 고집을 꺾을 수 없는 것처럼, 나도 네 고집을 꺾을 수 없겠지.\n우린 모두 자신의 신념에 충실한 사람이니까.",
  ui_story_8_1_1_183_dialog_content = "하지만 한 가지 명심해 둬... 확실히 지금까지 네 「운」은 나쁘지 않았어.",
  ui_story_8_1_1_184_dialog_content = "스카이워커를 가동해서 탈출한 것도, 물불 가리지 않고 그로누 씨를 구한 것도 그랬지.",
  ui_story_8_1_1_185_dialog_content = "하지만 만약... 이번엔 「행운」이 네 그런 순진함을 보살펴 주지 않는다면?",
  ui_story_8_1_1_186_dialog_content = "...난 PlayerName 그 애를 믿어. 그리고 우리가 이번에도 다시 해낼 수 있을 거라고 믿어.",
  ui_story_8_1_1_187_dialog_content = "노력한다면 분명히 기적을 만들 수 있을 거야.",
  ui_story_8_1_1_188_dialog_content = "네 그런 낙천적인 성격은 정말 존경스럽다니까, 바이스.",
  ui_story_8_1_1_189_dialog_content = "어서 가 봐. 난 너 말고도 고집불통 한 사람을 또 설득하러 가야 하니까, 이번엔 같이 가줄 수 없어.",
  ui_story_8_1_1_190_dialog_content = "그럼 그 아이테르를 잘 지켜줘. 바이스!",
  ui_story_8_1_1_191_dialog_content = "너도 조심해. 카렌! 정말 그걸 가동할 수 있다면... 분명히 슈모르한테 한 방 먹일 수 있을 거야!",
  ui_story_8_1_1_192_dialog_content = "한 방뿐이겠어? 그때가 되면 너희도 무사히 탈출할 수 있길 바랄 뿐이야.",
  ui_story_8_1_1_193_dialog_content = "그럼 나중에 봐, 카렌.",
  ui_story_8_1_1_194_dialog_content = "응, 다시 보게 될 거야, 바이스.",
  ui_story_8_1_1_195_dialog_content = "『이쪽도 뜯어내라. 어서.』",
  ui_story_8_1_1_196_dialog_content = "『쓸모 있는 거라면 전부 뜯어라! 주인님께서 콜로서스의 보완을 마치셨으니, 많은 재료가 필요하실 거다!』",
  ui_story_8_1_1_197_dialog_content = "『어이! 못 들었냐?!』",
  ui_story_8_1_1_198_dialog_content = "...끼익?!",
  ui_story_8_1_1_200_dialog_content = "조용히 해. 이 방엔 너 하나 남았거든. 다른 암귀는 어디 갔어? 모두 스카이워커호를 떠났나?",
  ui_story_8_1_1_201_dialog_content = "PlayerName의 소중한 집을 이렇게 부수다니, 절대 용서할 수 없어!",
  ui_story_8_1_1_202_dialog_content = "『오...오로리안... 조무래기, 주인님께 알려드려야...』",
  ui_story_8_1_1_203_dialog_content = "미안, 원래라면 단숨에 해치웠겠지만, 지금 난 꼭 물어봐야 할 게 있거든.",
  ui_story_8_1_1_204_dialog_content = "끄에엑──?!",
  ui_story_8_1_1_205_dialog_content = "네가 내 말을 못 알아들을 수도 있는 건 알아. 하지만...",
  ui_story_8_1_1_206_dialog_content = "무척 소중한 두 사람이 있어. PlayerName, 그리고 비비안 님, 두 사람이 어디로 갔는지 알고 싶어.",
  ui_story_8_1_1_207_dialog_content = "『넌 그 아이테르의 동료인가? 도망친 거 아니었나... 어리석은 여자로군...』",
  ui_story_8_1_1_208_dialog_content = "못 알아듣는다고. 에이, 진짜 시간 낭비네...",
  ui_story_8_1_1_209_dialog_content = "네가 통용어를 모른다면... 아, 그림을 그리면 되겠네!",
  ui_story_8_1_1_210_dialog_content = "?",
  ui_story_8_1_1_211_dialog_content = "이 정도면 되겠지...",
  ui_story_8_1_1_212_dialog_content = "이 사람... 어디 있어?",
  ui_story_8_1_1_213_dialog_content = "『...역시 그 아이테르 때문에 온 거였군!』",
  ui_story_8_1_1_214_dialog_content = "『아이테르라면 내 기억엔... 아니지.』",
  ui_story_8_1_1_215_dialog_content = "저기, 어딜 보는 거야?",
  ui_story_8_1_1_216_dialog_content = "『내가 말할 것 같으냐! 이 쓰레기, 벌레 녀석! 주인님의 계획을 계속 방해한다면...』",
  ui_story_8_1_1_217_dialog_content = "크으악...!",
  ui_story_8_1_1_218_dialog_content = "디바우러호... 방향인가?",
  ui_story_8_1_1_219_dialog_content = "쿠, 쿠우...",
  ui_story_8_1_1_220_dialog_content = "괜찮아? 아직 기운이 남아 있니? 날 데리고 이렇게 멀리까지 날아왔으니, 정말 힘들었을 거야.",
  ui_story_8_1_1_221_dialog_content = "쿠우...!",
  ui_story_8_1_1_222_dialog_content = "괜찮다면 다행이네... 미안해, 근데 한 번만 더 부탁해야 할 것 같아.",
  ui_story_8_1_1_223_dialog_content = "이제 디바우러호로 날아가야 해! 그쪽에 PlayerName하고 비비안 님이 있을지도 몰라!",
  ui_story_8_1_1_224_dialog_content = "쿠우?!",
  ui_story_8_1_1_225_dialog_content = "그래서... 여기까지 잠입한 거야? 그런 방법으로?",
  ui_story_8_1_1_226_dialog_content = "이렇게 들으면 조금 믿기 어렵겠지만, 정말 퀴리 덕분에 올 수 있었어.",
  ui_story_8_1_1_227_dialog_content = "쿠우...",
  ui_story_8_1_1_228_dialog_content = "이 녀석은 벌써 지쳐서 죽을 것 같은데.",
  ui_story_8_1_1_229_dialog_content = "퀴리가 정말 고생했어. 돌아가면 내가 잘 돌봐줄 거야!",
  ui_story_8_1_1_230_option_content = "그럼 얼른 여길 떠나자.",
  ui_story_8_1_1_231_dialog_content = "쿠우!",
  ui_story_8_1_1_232_dialog_content = "하지만 우린 아직 비비안 참모장님을 못 찾았어, PlayerName.",
  ui_story_8_1_1_233_dialog_content = "괜찮다면 같이 조금 더 들어가 줬으면 해...",
  ui_story_8_1_1_234_dialog_content = "참모장님을 구해오자!",
  ui_story_8_1_1_235_option_content = "하지만 비비안 씨는 못 봤어.",
  ui_story_8_1_1_236_dialog_content = "쿠우...",
  ui_story_8_1_1_237_dialog_content = "난 참모장님도 여기에 잡혀 있을 거라고 생각해. 그러니까 이제 참모장님을 찾아야 해.",
  ui_story_8_1_1_238_dialog_content = "슈모르가 무슨 속셈인지는 몰라도, 절대로 참모장님을 포기해선 안 돼!",
  ui_story_8_1_1_239_dialog_content = "분명히 여기 있을 거야. 나도 지금은 상태가 괜찮아진 것 같으니까, 어서 가자.",
  ui_story_8_1_1_240_dialog_content = "좋아, 그럼 들어가 보자!",
  ui_story_8_1_1_241_dialog_content = "쿠우!",
  ui_story_8_2_1_1_dialog_content = "선생님. 죄송해요... 한 번만 더 보여주시면 안 될까요?",
  ui_story_8_2_1_2_dialog_content = "또 감응에 실패했어요. 역시 안 되나 봐요...",
  ui_story_8_2_1_3_dialog_content = "선생님? 선생님?",
  ui_story_8_2_1_4_dialog_content = "뭐 해?",
  ui_story_8_2_1_5_dialog_content = "또 어디 정신이 팔렸었던 거야?",
  ui_story_8_2_1_6_dialog_content = "......",
  ui_story_8_2_1_7_dialog_content = "정신을 집중해. 이제 곧 증명해 보일 수 있을 거잖아. 그렇지?",
  ui_story_8_2_1_8_dialog_content = "넌 쓸데없는 말이 너무 많아.",
  ui_story_8_2_1_9_dialog_content = "내가 뭘 하든 네가 시시콜콜 설명할 필요 없다고.",
  ui_story_8_2_1_10_dialog_content = "그래.",
  ui_story_8_2_1_11_dialog_content = "......",
  ui_story_8_2_1_12_dialog_content = "내가 PlayerName의 목숨을 살려둔 건 그런 시시한 「증명」 따위를 하기 위해서가 아니야. 노라.",
  ui_story_8_2_1_13_dialog_content = "난...",
  ui_story_8_2_1_14_dialog_content = "...설명해도 넌 이해할 수 없겠지.",
  ui_story_8_2_1_15_dialog_content = "사실 네가 그 일루미나 녀석을 남겨둔 것과 같은 이유일 거야.",
  ui_story_8_2_1_16_dialog_content = "아니, 난 너와 다른걸.",
  ui_story_8_2_1_17_dialog_content = "어차피 난 애초에 일루미나와 상관 없는 사람이 됐지만, 넌 여전히 아이테르잖아. 훗.",
  ui_story_8_2_1_18_dialog_content = "죽고 싶어?! 누구 보고 아이테르래?!",
  ui_story_8_2_1_19_dialog_content = "흥분하지 마. 너랑 이런 이야기를 계속할 생각은 없으니까. 재미없어.",
  ui_story_8_2_1_20_dialog_content = "...변덕하고는.",
  ui_story_8_2_1_21_dialog_content = "간다.",
  ui_story_8_2_1_22_dialog_content = "어디 가는데?",
  ui_story_8_2_1_23_dialog_content = "난 이미 널 도와서 그 녀석에게 「같은 힘」을 줬어. 너흰 곧 다시 「동족」이 될 거야.",
  ui_story_8_2_1_24_dialog_content = "뭐 하자는 거야? 내가 그렇게 하라고 한 적은 없을 텐데?",
  ui_story_8_2_1_25_dialog_content = "쳇, 정말 이해할 수가 없다니까!",
  ui_story_8_2_1_26_dialog_content = "저 자식, 대체 뭘 하려는 거지? 처음 만났을 때부터 항상 저랬어!",
  ui_story_8_2_1_27_dialog_content = "안 도와줄 거면 가만히나 있지, 내가 백야성에 집중하고 있을 때 귀찮은 일이나 만들고...",
  ui_story_8_2_1_28_dialog_content = "슈모르, 전 노라 님의 명을 받고 도와드리기 위해 남았습니다만...",
  ui_story_8_2_1_29_dialog_content = "부디 노라 님에 대한 언사를 주의해주셨으면 좋겠군요.",
  ui_story_8_2_1_30_dialog_content = "...하, 아무래도 전혀 신경을 안 쓰는 건 아닌 모양이지?",
  ui_story_8_2_1_31_dialog_content = "이곳 상태는... 완전 엉망이네...",
  ui_story_8_2_1_32_dialog_content = "PlayerName? 어때? 할 수 있는 거야?",
  ui_story_8_2_1_33_dialog_content = "이미 성공하긴 했어. 이 콜로서스랑 감응했지만... 녀석을 전혀 이해할 수가 없어.",
  ui_story_8_2_1_F1_dialog_content = "아니, 내가 이해할 수 없는 게 아니라...",
  ui_story_8_2_1_34_dialog_content = "이 콜로서스는 애초에 자신만의 의식 모듈이 없는 것 같아. 완전히 텅 빈 느낌이야.",
  ui_story_8_2_1_35_dialog_content = "조심해. 경보 같은 게 울릴지도 모르니까...",
  ui_story_8_2_1_36_dialog_content = "괜찮아, 바이스. 조심할 테니까.",
  ui_story_8_2_1_37_dialog_content = "그리고 난 감응으로 우리의 움직임을 숨겼거든. 이제 경보가 울리지 않을 거야.",
  ui_story_8_2_1_F2_dialog_content = "감응 능력으로 그런 것까지 할 수 있단 말이야?",
  ui_story_8_2_1_F3_dialog_content = "응, 감응을 통한 「잠입」을 배운 뒤로... 아무튼 감응으로 몇 가지 일을 할 수 있게 됐어.",
  ui_story_8_2_1_38_dialog_content = "그럼 비비안 참모장님의 위치까지 감응할 수 있는 거야?",
  ui_story_8_2_1_F4_dialog_content = "미안, 무턱대고 지금보다 더 깊게 감응하는 건 무리야.",
  ui_story_8_2_1_F5_dialog_content = "여긴 디바우러호의 내부니까, 직접 접촉해서 감응할 수 있어...",
  ui_story_8_2_1_39_dialog_content = "하지만 감응 능력을 넓은 범위에 전개하면, 슈모르에게 발각될 수도 있어.",
  ui_story_8_2_1_40_dialog_content = "알겠어. 역시 우리가 직접 찾는 수밖에 없겠네...",
  ui_story_8_2_1_41_dialog_content = "네 상태는 어때? 다크매터에 적응할 수 있겠어?",
  ui_story_8_2_1_42_dialog_content = "응. 문제없어. 머리도 이제 안 아파.",
  ui_story_8_2_1_43_dialog_content = "오히려 더 기운이 난 게... 잠을 푹 잔 것 같은 느낌이야...",
  ui_story_8_2_1_44_dialog_content = "그래? 이상하네... 전에 속삭이는 회랑에선 분명히 다크매터에 적응하지 못했는데...",
  ui_story_8_2_1_45_dialog_content = "쿠우!",
  ui_story_8_2_1_46_dialog_content = "퀴리! 무슨 냄새가 나?",
  ui_story_8_2_1_47_dialog_content = "에취!",
  ui_story_8_2_1_48_dialog_content = "쿠우...",
  ui_story_8_2_1_49_dialog_content = "다크매터가 너무 짙어. 퀴리도 괴로워하고 있어...",
  ui_story_8_2_1_50_dialog_content = "너무 느리잖아.",
  ui_story_8_2_1_51_dialog_content = "넌...?!",
  ui_story_8_2_1_52_dialog_content = "생각보다 시간을 많이 끌었지만, 그래도 운명의 바퀴는 예정대로 움직이고 있어.",
  ui_story_8_2_1_53_dialog_content = "아이테르, 이쪽으로 가. 네가 원하는 건 이 복도 끝에 있으니까...",
  ui_story_8_2_1_54_dialog_content = "넌 누구지? 오로리안? 아니면 암귀?",
  ui_story_8_2_1_55_dialog_content = "쉿... 그런 건 중요하지 않아. 중요한 건 앞으로 일어날 일과 우리가 열심히 찾고 있는...",
  ui_story_8_2_1_56_dialog_content = "진리, 그것뿐이야.",
  ui_story_8_2_1_57_dialog_content = "PlayerName, 왜 그래? 갑자기 안색이 엄청나게 안 좋아졌어.",
  ui_story_8_2_1_58_dialog_content = "이, 이상한 걸 봤어...",
  ui_story_8_2_1_59_dialog_content = "하얀 옷을 입고 상자를 든 남자였는데, 나보고... 저쪽으로 가래.",
  ui_story_8_2_1_60_dialog_content = "뭐라고? 남자가 어디 있는데?",
  ui_story_8_2_1_F6_dialog_content = "어쩌면... 내가 감응으로 본 건지도 몰라...\n그 사람이 저쪽으로 가라고 했어. 왠지 믿을 수 있을 것 같아.",
  ui_story_8_2_1_F7_dialog_content = "그렇다면... 역시 어디로 가야 할지는 정확히 알 수 없는 거네.",
  ui_story_8_2_1_61_dialog_content = "음, 난 디바우러호의 내부 구조엔 아직 익숙하지 않지만, 그래도 지금까지 왔던 길을 종합해 보면...",
  ui_story_8_2_1_62_dialog_content = "음, 그럼 내가 간단히 지도를 그려볼게!",
  ui_story_8_2_1_63_dialog_content = "마침 이 종이도 아직 쓸 수 있고...",
  ui_story_8_2_1_64_dialog_content = "바이스, 뭘 그린 거야?",
  ui_story_8_2_1_65_dialog_content = "아, 아무것도 아니니까 신경 쓰지 마!",
  ui_story_8_2_1_66_dialog_content = "여기 그린 이 사람...",
  ui_story_8_2_1_68_dialog_content = "그, 그러니까 암귀 녀석들한테 네가 어디 있는지 물어보려고 그린 거야!",
  ui_story_8_2_1_F8_dialog_content = "날 그린 거였어?",
  ui_story_8_2_1_69_dialog_content = "인정해. 확실히 좀 못 그리긴 했지만... 그래도 쓸모는 있었어!",
  ui_story_8_2_1_70_dialog_content = "아무튼! 잊어버리기 전에 지금까지 확인했던 경로를 그려볼게...",
  ui_story_8_2_1_72_dialog_content = "(암귀가 저 그림을 이해했다니...)",
  ui_story_8_2_1_73_dialog_content = "여기에... 척도를 추가하고... 그리고...",
  ui_story_8_2_1_74_dialog_content = "됐어!",
  ui_story_8_2_1_75_dialog_content = "(참자. 아무리 이상한 지도를 그렸어도 웃으면 안 돼... 어쨌든 바이스가 고생해서 그린 거니까...)",
  ui_story_8_2_1_76_dialog_content = "...엄청 잘 그렸잖아! 이 정도면 거의 도면 수준 아냐?!",
  ui_story_8_2_1_77_dialog_content = "뭐, 그런대로? 시간이 촉박해서 간단히 그려봤어.",
  ui_story_8_2_1_78_dialog_content = "간단히?! 사람은 저렇게 그려놓고 지도 그리는 건 어떻게 이런 수준인 거지?!",
  ui_story_8_2_1_79_dialog_content = "말했잖아. 내가 일루미나에서 배운 게 이런 거라고.",
  ui_story_8_2_1_80_dialog_content = "게다가 콜로서스의 정비와 점검을 위해서도 이런 지식이 필요하거든.",
  ui_story_8_2_1_81_dialog_content = "쿠우!",
  ui_story_8_2_1_82_dialog_content = "퀴리! 왜 그래?",
  ui_story_8_2_1_83_dialog_content = "쿠! 쿠우!",
  ui_story_8_2_1_84_dialog_content = "이쪽이야? 이 방향은...",
  ui_story_8_2_1_85_dialog_content = "아까 그 남자가 가리키던 방향인데...?",
  ui_story_8_2_1_86_dialog_content = "참모장님의 냄새를 맡았나 봐! 가자! PlayerName!",
  ui_story_8_2_1_87_dialog_content = "(그 남자, 적이 아닌가...?)",
  ui_story_8_2_1_88_dialog_content = "앞쪽에 분명히 더 많은 암귀가 있을 거야. 빠르게 처리하자!",
  ui_story_8_2_1_89_dialog_content = "전투 준비──!",
  ui_story_8_2_2_1_dialog_content = "<color=#e8d9bb>백야성 업타운 구역, 하이가든</color>",
  ui_story_8_2_2_2_dialog_content = "다모클레스를...",
  ui_story_8_2_2_3_dialog_content = "...가동하겠다고?",
  ui_story_8_2_2_5_dialog_content = "네. 현재 상황을 고려했을 때, 그것이 유일한 해결 방안입니다!",
  ui_story_8_2_2_6_dialog_content = "카렌, 지금 자네가 무슨 소리를 하고 있는지 알고 있는 건가?",
  ui_story_8_2_2_7_dialog_content = "그걸 가동하려면 반드시 삼자 결의를 거쳐야 한다! 그리고 그건 둘째치고...",
  ui_story_8_2_2_F1_dialog_content = "그게 얼마나 많은 에너지를 소비하는지 알고 있나?!",
  ui_story_8_2_2_8_dialog_content = "실드를 유지하기 위한 모든 에너지를 다 흡수해버릴 거다! 백야성마저도 멈출 수 있단 말이다!",
  ui_story_8_2_2_9_dialog_content = "...알고 있습니다.",
  ui_story_8_2_2_10_dialog_content = "머리가 어떻게 된 거 아니냐!",
  ui_story_8_2_2_11_dialog_content = "아우토.",
  ui_story_8_2_2_12_dialog_content = "...흥.",
  ui_story_8_2_2_13_dialog_content = "성주 전하, 전하께선 슈모르와 검은 콜로서스의 위력을 직접 보지 못하셨습니다.\n하지만 전 그 위에서 그걸 직접 보았습니다!",
  ui_story_8_2_2_14_dialog_content = "보완된 검은 콜로서스는 그 누구도 막을 수 없습니다. 게다가 슈모르에겐 다른 한패가 있습니다!",
  ui_story_8_2_2_15_dialog_content = "우리도 최후를 각오하고 싸워야 합니다!\n실드가 언제까지 우릴 보호해줄 순 없습니다. 언젠가 파괴될 겁니다...",
  ui_story_8_2_2_16_dialog_content = "다쳤느냐?",
  ui_story_8_2_2_17_dialog_content = "에?",
  ui_story_8_2_2_18_dialog_content = "카렌, 다쳤냐고 물었다.",
  ui_story_8_2_2_19_dialog_content = "라파엘이 네 상태가 매우 좋지 않았다고 하더군. 네가 그렇게 좌절한 모습은 처음 봤다고 하던데.",
  ui_story_8_2_2_20_dialog_content = "......",
  ui_story_8_2_2_21_dialog_content = "성주 전하, 전 괜찮습니다. 걱정하지 않으셔도 됩니다.",
  ui_story_8_2_2_22_dialog_content = "좋다.",
  ui_story_8_2_2_23_dialog_content = "그대들은 어떻게 생각하나?",
  ui_story_8_2_2_24_dialog_content = "난 이미 내 의견을 말했다. 백야성을 멈추는 것도 불사하겠다니, 그야말로 미친 짓이 아닌가.",
  ui_story_8_2_2_25_dialog_content = "심판소 쪽은?",
  ui_story_8_2_2_26_dialog_content = "전 절차를 따를 뿐입니다. 어떤 제안이든 삼자 결의만 통과한다면 시행할 수 있습니다.",
  ui_story_8_2_2_27_dialog_content = "반대로 말하자면, 결의를 어기는 자에게는 심판소의 준엄한 제재가 따를 것입니다. 그 누구라도 말입니다.",
  ui_story_8_2_2_28_dialog_content = "그럼 간단하게 결의를 시작해볼까.",
  ui_story_8_2_2_29_dialog_content = "아우토, 원로원의 대표, 그대의 결정은 부결 쪽이겠군.",
  ui_story_8_2_2_30_dialog_content = "물론이다.",
  ui_story_8_2_2_31_dialog_content = "이리돈, 심판소의 대심판관, 그대의 결정은?",
  ui_story_8_2_2_32_dialog_content = "기권하겠습니다.",
  ui_story_8_2_2_33_dialog_content = "좋다.",
  ui_story_8_2_2_34_dialog_content = "그럼 마지막으로, 나, 솔라드, 백야성의 성주이자 대귀족의 대표로서...",
  ui_story_8_2_2_35_dialog_content = "이 안건을 부결한다.",
  ui_story_8_2_2_36_dialog_content = "──!",
  ui_story_8_2_2_37_dialog_content = "거부 2표, 기권 1표. 심판소에서는 각하된 것으로 알겠습니다.",
  ui_story_8_2_2_38_dialog_content = "확실히 자네 부친은 자네보다 백야성을 지키는 근간이 무엇인지 잘 알고 있군. 카렌.",
  ui_story_8_2_2_39_dialog_content = "이게 무슨 장난입니까! 삼자 결의라는 게 이런 말 몇 마디로 끝나는 거였습니까?!",
  ui_story_8_2_2_40_dialog_content = "긴급한 경우라면 결의에 형식적인 절차는 필요하지 않습니다.\n심판소가 현장에 있고, 이를 승인했다면 결의는 유효합니다.",
  ui_story_8_2_2_41_dialog_content = "질서를 존중해주십시오. 카렌.",
  ui_story_8_2_2_42_dialog_content = "전...",
  ui_story_8_2_2_43_dialog_content = "들었어요? 그걸 사용하면 에너지를 집중해야 하고 심지어 실드까지 없애야 한데요...",
  ui_story_8_2_2_44_dialog_content = "그렇게 하는 게 자살이랑 무슨 차이가 있죠? 최소한 지금은 실드의 보호를 받고 있지만...",
  ui_story_8_2_2_45_dialog_content = "쯧쯧, 성주의 딸이면서 자신이 뭘 해야 하는지도 모르는군요...",
  ui_story_8_2_2_46_dialog_content = "......",
  ui_story_8_2_2_47_dialog_content = "카렌.",
  ui_story_8_2_2_48_dialog_content = "......",
  ui_story_8_2_2_49_dialog_content = "고개를 들어라. 카렌 드 솔라드!",
  ui_story_8_2_2_50_dialog_content = "여긴 백야성이다. 소꿉장난이나 하는 콜로서스 모험단 따위가 아니란 말이다!",
  ui_story_8_2_2_51_dialog_content = "내 성에선 그런 방식은 용납되지 않는다. 알겠느냐?",
  ui_story_8_2_2_52_dialog_content = "......",
  ui_story_8_2_2_53_dialog_content = "알겠냐고 물었다!",
  ui_story_8_2_2_54_dialog_content = "네. 성주 전하.",
  ui_story_8_2_2_55_dialog_content = "사태가 명확해지기 전까진, 실드를 유지하는 것이 상책이다. 다모클레스의 가동이라니...",
  ui_story_8_2_2_56_dialog_content = "정말 어처구니가 없군.",
  ui_story_8_2_2_57_dialog_content = "일의 경중과 절차를 조금도 생각하지 않는구나! 카렌, 넌 어렸을 때와 달라진 게 전혀 없다.\n지난 경험에서 교훈을 얻지 못한 게냐!",
  ui_story_8_2_2_58_dialog_content = "......?",
  ui_story_8_2_2_59_dialog_content = "난 네가 어릴 적에 고집스럽게 고양이 한 마리를 구하겠다고 하다가\n나무집에서 떨어졌던 것에서 네 어리석음이 그칠 줄 알았다.",
  ui_story_8_2_2_60_dialog_content = "하지만, 넌 조금도 성장하지 않았구나!",
  ui_story_8_2_2_61_dialog_content = "(...나무집? 고양이...?)",
  ui_story_8_2_2_62_dialog_content = "그래도 결국엔 고양이를 구했으니, 넌 네 고집이 옳았다고 생각했겠지.\n하지만 그게 정녕 올바른 선택이었느냐?",
  ui_story_8_2_2_63_dialog_content = "남의 조언도 듣지 않고, 고양이 한 마리를 구하면서 다리까지 부러졌지. 그만한 가치가 있었느냐?",
  ui_story_8_2_2_64_dialog_content = "(......?!)",
  ui_story_8_2_2_65_dialog_content = "그럴 가치가 있었냐고 물었다!",
  ui_story_8_2_2_66_dialog_content = "솔라드, 지금 이게 무슨 뜻인가? 왜 갑자기 집안 이야기를 꺼내는 거지?",
  ui_story_8_2_2_67_dialog_content = "내가 그대에게 물었나? 아우토 트로이?",
  ui_story_8_2_2_68_dialog_content = "......",
  ui_story_8_2_2_69_dialog_content = "가치가 있었습니다.",
  ui_story_8_2_2_70_dialog_content = "전 그럴 가치가 있었다고 생각합니다. 아버님.",
  ui_story_8_2_2_71_dialog_content = "그래. 역시 넌 구제 불능이로군.",
  ui_story_8_2_2_72_dialog_content = "어디 그 고양이처럼 계속 자신의 상아탑에 틀어박혀 보아라.",
  ui_story_8_2_2_73_dialog_content = "......",
  ui_story_8_2_2_74_dialog_content = "으아아... 성주 전하 방금 너무 무서웠어...",
  ui_story_8_2_2_75_dialog_content = "그리고 갑자기 왜 옛날 일을 꺼내신 거지? 느낌이 이상해. 소름이 끼칠 정도였다니까...",
  ui_story_8_2_2_77_dialog_content = "으에에──? 카렌 언니는 또 왜 웃는 건데? 더 소름 끼치잖아!",
  ui_story_8_2_2_78_dialog_content = "왜냐면... 그게 무슨 말인지... 이해했거든.",
  ui_story_8_2_2_79_dialog_content = "에?",
  ui_story_8_2_2_80_dialog_content = "나무집, 그리고 고양이... 훗, 어렸을 때 그런 일이 있었던 건 사실이야.",
  ui_story_8_2_2_81_dialog_content = "하지만...",
  ui_story_8_2_2_82_dialog_content = "...그 때 난 그 고양이를 구하지 못했어.",
  ui_story_8_2_2_83_dialog_content = "그럼 성주님이 잘못 기억하시는 거야? 음... 아니면...",
  ui_story_8_2_2_84_dialog_content = "아, 설마...",
  ui_story_8_2_2_85_dialog_content = "전하께서 치매에 걸리셨나?",
  ui_story_8_2_2_86_dialog_content = "넌 이해 못 할 거야. 괜찮아, 가야 할 곳이 있으니까... 날 따라와.",
  ui_story_8_2_2_87_dialog_content = "오오! 좋아! 어딘데?",
  ui_story_8_2_2_88_dialog_content = "......",
  ui_story_8_2_2_89_dialog_content = "다모클레스의 제어실.",
  ui_story_8_3_1_1_dialog_content = "<color=#e8d9bb>디바우러호 안</color>",
  ui_story_8_3_1_2_dialog_content = "후후~ 후후후♪",
  ui_story_8_3_1_3_dialog_content = "아, 미안, 나도 모르게 좀 흥분했네.",
  ui_story_8_3_1_4_dialog_content = "자, 계속 이쪽으로 가면 돼... 나도 이곳을 「구경」하는 건 처음이라서 말이지...",
  ui_story_8_3_1_5_dialog_content = "쿠우!",
  ui_story_8_3_1_6_dialog_content = "(퀴리는 비비안의 흔적을 추적할 수 있어. 퀴리도 이 방향으로 가야 하는 게 맞다고 한다면...)",
  ui_story_8_3_1_7_dialog_content = "계속 전진해. 이쪽이 맞을 거야.",
  ui_story_8_3_1_8_dialog_content = "......",
  ui_story_8_3_1_9_dialog_content = "왜 그래? 왜 갑자기 날 그렇게 보는 거야...",
  ui_story_8_3_1_10_dialog_content = "너 정말 괜찮아? 나도 이곳의 다크매터는 견디기 힘든데, 어떻게 네가 아무렇지도 않은 거야?",
  ui_story_8_3_1_11_dialog_content = "응. 진짜 괜찮아.",
  ui_story_8_3_1_12_dialog_content = "이상하긴 한데, 지금 이곳에 다크매터에 아무런 거부감이 안 들어. 오히려 반대로...",
  ui_story_8_3_1_13_dialog_content = "냄새가 좋은 거 같은데?",
  ui_story_8_3_1_14_dialog_content = "에...",
  ui_story_8_3_1_15_dialog_content = "대신 몸이 좀 간지러울 뿐이야. 알레르긴 아니겠지?",
  ui_story_8_3_1_16_dialog_content = "간지럽다고? 어디야? 내가 좀 봐도 돼?",
  ui_story_8_3_1_17_dialog_content = "괜찮아. 등 쪽이야. 옷 위로 긁으면 좀 가라앉는 것 같아...",
  ui_story_8_3_1_18_dialog_content = "그것보다...",
  ui_story_8_3_1_19_option_content = "바이스, 넌 좀 힘들다고?",
  ui_story_8_3_1_20_dialog_content = "역시 넌 자기보다 남을 걱정하는구나...",
  ui_story_8_3_1_21_dialog_content = "난 괜찮아. 좀 힘들긴 해도 슈모르한테 제압되었을 때보다는 훨씬 나으니까.",
  ui_story_8_3_1_22_dialog_content = "게다가 그동안 나도 많이 성장했는걸, PlayerName.",
  ui_story_8_3_1_23_dialog_content = "우리가 모든 난관을 순조롭게 이겨낼 수 있었으면 좋겠어!",
  ui_story_8_3_1_24_dialog_content = "분명히 그럴 수 있을 거야. 슈모르를 쓰러트리기 전까지 절대 포기할 수 없어.",
  ui_story_8_3_1_25_dialog_content = "바로 그 기세야. PlayerName.",
  ui_story_8_3_1_26_option_content = "카렌은 어떻게 됐을까.",
  ui_story_8_3_1_27_dialog_content = "아마 지금쯤 백야성에 도착했을 거야.",
  ui_story_8_3_1_28_dialog_content = "지금 카렌도 다른 방식으로 슈모르를 쓰러트리기 위해 열심히 싸우고 있겠지...",
  ui_story_8_3_1_29_dialog_content = "그래서 그 「다모클레스」라는 게 대체 뭔데? 엄청난 무기인 거야?",
  ui_story_8_3_1_30_dialog_content = "나도 직접 본 적은 없지만, 유학하는 동안에 그 「위력」에 대해 들어본 적이 있어...",
  ui_story_8_3_1_31_dialog_content = "아무튼 결정적인 순간이 아니면 쓸 수 없는 비장의 무기 아닐까?",
  ui_story_8_3_1_32_dialog_content = "그러니까 너도 전혀 모른다는 거네...",
  ui_story_8_3_1_33_option_content = "비비안 씨는 대체 어디 있는 거지?",
  ui_story_8_3_1_34_dialog_content = "잘 모르겠어. 하지만 퀴리의 반응을 봐서는 이 앞인 게 틀림없어!",
  ui_story_8_3_1_35_dialog_content = "분명히 우릴 참모장님께 데려다줄 거야.",
  ui_story_8_3_1_36_dialog_content = "비비안 씨가 아니었으면 우린 탈출할 기회조차 없었을 거야.",
  ui_story_8_3_1_37_dialog_content = "너도 많은 걸 했어. PlayerName. 마지막엔 네가 그런 결정을 해서...",
  ui_story_8_3_1_38_dialog_content = "너흴 밀었던 거 말이야?",
  ui_story_8_3_1_39_dialog_content = "그건 아마 무의식적으로 나온 반응이었을 거야.\n난 애초에 그런 일이 있었다는 것도 거의 잊어버렸는걸...",
  ui_story_8_3_1_40_dialog_content = "앞으론 그렇게 무턱대고 자길 「희생」하려는 일은... 하지 않았으면 좋겠어.",
  ui_story_8_3_1_41_dialog_content = "지난번에 그로누 선배랑 함께 있을 때도 그래. 너 혼자 달려들어서...",
  ui_story_8_3_1_42_dialog_content = "쿠우!",
  ui_story_8_3_1_43_dialog_content = "미안, 퀴리가 초조한 모양이야. 좀 더 서두르자.",
  ui_story_8_3_1_44_dialog_content = "PlayerName, 아무튼 너도 지금 네 몸 상태에 계속 주의해야 돼.",
  ui_story_8_3_1_46_dialog_content = "그래. 내 걱정은 하지 마...",
  ui_story_8_6_1_1_dialog_content = "어, 엄청 밝네...",
  ui_story_8_6_1_3_option_content = "안 되겠어! 숨어야겠어!",
  ui_story_8_6_1_4_dialog_content = "PlayerName? 왜 구석에 숨은 거야?",
  ui_story_8_6_1_5_dialog_content = "뭐 하고 있어? 빨리 와!",
  ui_story_8_6_1_6_dialog_content = "쿠우!",
  ui_story_8_6_1_7_dialog_content = "미, 미안. 여긴 너무 밝아서, 잠깐만...",
  ui_story_8_6_1_8_dialog_content = "밝다고? 그냥 평범한 방이잖아...",
  ui_story_8_6_1_9_dialog_content = "이 정도 밝기도 그렇게 반응한다니... 너 설마 지금 빛이 무서운 건 아니지?",
  ui_story_8_6_1_10_dialog_content = "모르겠어. 음... 이제 좀 적응됐어.",
  ui_story_8_6_1_11_option_content = "으... 가려워...",
  ui_story_8_6_1_12_dialog_content = "눈은 괜찮아졌는데, 등이 또 가려운 거야?",
  ui_story_8_6_1_13_dialog_content = "응. 나 설마 어디 아픈 건가...?",
  ui_story_8_6_1_14_dialog_content = "좀 쉬자. 여긴 적이 없는 것 같으니까, 잠깐 정비도 할 겸...",
  ui_story_8_6_1_15_dialog_content = "쿠우!",
  ui_story_8_6_1_16_dialog_content = "퀴리? 어디 가는 거야?!",
  ui_story_8_6_1_17_dialog_content = "쿠! 쿠우!",
  ui_story_8_6_1_18_dialog_content = "비비안 님?! 바로 이 방 뒤에 계신 거야?",
  ui_story_8_6_1_19_dialog_content = "쿠──! 쿠우! 쿠!",
  ui_story_8_6_1_20_dialog_content = "퀴리! 우리가 문을 열 방법을 찾아볼게. 부딪히면 안 돼. 이러다 들켜버릴 거야...",
  ui_story_8_6_1_21_dialog_content = "음? 이 냄새... 이 냄새는?!",
  ui_story_8_6_1_22_dialog_content = "바이스, 조심해!",
  ui_story_8_6_1_23_dialog_content = "키이익...!",
  ui_story_8_6_1_24_dialog_content = "놈들이... 너한테 달려들고 있어!",
  ui_story_8_6_1_25_dialog_content = "맞혔어! 아직 몇 마리 남았어. 다른 암귀한테 말하러 가게 해선 안 돼!",
  ui_story_8_6_1_26_dialog_content = "나머지도 어서 처리하자!",
  ui_story_8_6_1_27_dialog_content = "좋아! 내게 맡겨. 속전속결로 처리할게!",
  ui_story_8_6_2_1_dialog_content = "좋아! 다행히 큰 소란은 없었어...",
  ui_story_8_6_2_2_dialog_content = "빠져나간 녀석이 있는지 모르겠...",
  ui_story_8_6_2_3_dialog_content = "?! 뒤를 조심해!",
  ui_story_8_6_2_4_dialog_content = "크에에엑!",
  ui_story_8_6_2_5_dialog_content = "(날 그냥 지나쳤어?!)",
  ui_story_8_6_2_6_dialog_content = "후... 역시 이곳의 다크매터가 내 판단력에 영향을 주는 것 같아. 한 마리를 놓치다니...",
  ui_story_8_6_2_7_dialog_content = "바이스, 방금...",
  ui_story_8_6_2_8_dialog_content = "저 암귀가 날 그냥 지나쳤어. 아니, 날 아예 못 본 것 같았어!",
  ui_story_8_6_2_9_dialog_content = "응. 나도 느꼈어. 방금뿐만 아니라 이 길에서 모든 녀석들이\n너한테 점점 더 관심을 보이지 않는 것 같았어.",
  ui_story_8_6_2_10_dialog_content = "마치...",
  ui_story_8_6_2_11_dialog_content = "...널 적으로 생각하지 않는 것처럼 말이야.",
  ui_story_8_6_2_12_dialog_content = "......",
  ui_story_8_6_2_13_dialog_content = "하지만... 어째서지?",
  ui_story_8_6_2_14_dialog_content = "잘 모르겠어, PlayerName. 괜찮아? 어디 불편한 곳 없어?",
  ui_story_8_6_2_15_dialog_content = "잘 모르겠어. 바이스...",
  ui_story_8_6_2_16_dialog_content = "쿠우!",
  ui_story_8_6_2_17_dialog_content = "알고 있어, 퀴리. 하지만 PlayerName의 몸이...",
  ui_story_8_6_2_18_dialog_content = "괜찮아. 비비안 씨가 바로 저기 있으니까, 일단 구하고 나서 이야기하자!",
  ui_story_8_7_1_A1_dialog_content = "음... 아빠... 엄마...?",
  ui_story_8_7_1_A2_dialog_content = "마을은 이미... 점령된 거 아니었어요? 무사해서 다행이에요...",
  ui_story_8_7_1_1_dialog_content = "그래. 깊이 빠져라... 가장 달콤한 꿈, 가장 진실한 꿈을 꾸게 해주마...",
  ui_story_8_7_1_2_dialog_content = "순결하고, 순수한, 근원의 인장으로부터 온... 『어머니의 은총이다.』",
  ui_story_8_7_1_3_dialog_content = "그것이 네 몸의 잠재력을 끌어내고, 유일무이한 힘이 되어줄 거다.",
  ui_story_8_7_1_4_dialog_content = "더 중요한 건, 그것이 널 우리의 일원으로 만들어줄 것이다...",
  ui_story_8_7_1_5_dialog_content = "어서, 더 빨리... 근원의 전당으로 와라.",
  ui_story_8_7_1_6_dialog_content = "들고 있는 게 뭔지는 모르겠지만, 일단 좀 떨어지시지. 암귀!",
  ui_story_8_7_1_7_dialog_content = "오로리안? 어떻게 들어왔지?",
  ui_story_8_7_1_8_dialog_content = "참모장님! 제 말이 들리시나요?",
  ui_story_8_7_1_9_dialog_content = "아...",
  ui_story_8_7_1_10_dialog_content = "다행이야. 아직 무사하셔!",
  ui_story_8_7_1_11_dialog_content = "동료를 구하겠다고 온 건가, 분수를 모르는구나...",
  ui_story_8_7_1_12_dialog_content = "아니면 이클립스에 감화되고 싶어서 찾아온 건가?",
  ui_story_8_7_1_A3_dialog_content = "내 이름은 「그립」, 기꺼이 너희의 안내자가 되어 주마.",
  ui_story_8_7_1_13_dialog_content = "「감화」라는 건 너처럼 추한 암귀가 되는 걸 말하는 건가? 고맙지만 필요 없어.",
  ui_story_8_7_1_14_dialog_content = "『아이테르! 지금쯤이면 벌써 변했어야 하는데!』",
  ui_story_8_7_1_15_dialog_content = "무슨 말을 하는 건지 모르겠으니까 통용어로 말해.",
  ui_story_8_7_1_16_dialog_content = "그분께선 왜 아무런 언질을 안 해주신 거지?\n경보조차도 제대로 울리지 않다니. 네놈들... 대체 무슨 짓을...",
  ui_story_8_7_1_17_dialog_content = "내 기술이야. 암귀. 난 디바우러호도 어느 정도 감응할 수 있으니까. 이해했어?",
  ui_story_8_7_1_18_dialog_content = "너무 많은 소란을 일으키지만 않는다면, 경보를 차단하거나 행적을 감추는 정도는 쉬운 일이라고.",
  ui_story_8_7_1_19_dialog_content = "예상 밖의 변수인가... 하지만 상관없지. 내 후각이 틀리지 않았다면...",
  ui_story_8_7_1_20_dialog_content = "넌 곧 우리와 함께하게 될 거다. 아이테르.",
  ui_story_8_7_1_21_dialog_content = "...무슨 뜻이야?",
  ui_story_8_7_1_F1_dialog_content = "PlayerName, 녀석의 말은 신경 쓰지 마.",
  ui_story_8_7_1_22_dialog_content = "아까 참모장님께 뭘 하려고 했지? 그 빛나는 물건은 또 뭔데?",
  ui_story_8_7_1_23_dialog_content = "『쓸데없는 질문이군.』",
  ui_story_8_7_1_24_dialog_content = "내 인내심을 시험하지 마. 암귀. 난 지금 너랑 수수께끼를 풀 시간이 없어.",
  ui_story_8_7_1_25_dialog_content = "그건 은총이다! 어머니께서 내려주시는 은총!",
  ui_story_8_7_1_26_dialog_content = "주인님이 너흴 배려했다는 건 알고 있나?\n분명히 순식간에 가루로 만들 수도 있었는데 특별히 목숨을 살려주셨지.",
  ui_story_8_7_1_27_dialog_content = "게다가 너희를 이 낙원으로 초대하셨다. 아무런 대가도 없이, 너희에게 힘을 선사하셨지...",
  ui_story_8_7_1_28_dialog_content = "영광! 이건 영광스러운 일이란 말이다!",
  ui_story_8_7_1_29_dialog_content = "힘이라니? 무슨 소리야? 똑바로 말해!",
  ui_story_8_7_1_30_dialog_content = "곧 알게 될 거다. 의미 없는 질문을 하지 마라.",
  ui_story_8_7_1_31_dialog_content = "설마...",
  ui_story_8_7_1_32_dialog_content = "헛소리하는 건 듣지 마. 어서 해치워. 아직 늦지 않았어!",
  ui_story_8_7_1_33_dialog_content = "또 당신이야?! 어디 있는 거야?",
  ui_story_8_7_1_34_dialog_content = "관중석, 일등석에 있지. 그게 중요한가?",
  ui_story_8_7_1_35_dialog_content = "아직 아이테르로 살고 싶다면 내 말대로... 어서 싸워!",
  ui_story_8_7_1_36_dialog_content = "『더 넓어진 시야 속에서, 한때의 무지와 부끄러움에 몸부림쳐라!』",
  ui_story_8_7_1_37_dialog_content = "으윽──!",
  ui_story_8_7_1_38_dialog_content = "바이스, 내... 몸속에서 뭔가 움직여! 아냐, 이건 에너지야...",
  ui_story_8_7_1_39_dialog_content = "어떤... 에너지가...",
  ui_story_8_7_1_40_dialog_content = "PlayerName! 침착해! 이성을 유지해!",
  ui_story_8_7_1_41_dialog_content = "으윽... 머리, 머리가 터질 것 같아!",
  ui_story_8_7_1_43_dialog_content = "가, 강해! PlayerName, 빨리 정신 차려!",
  ui_story_8_7_1_44_option_content = "알고 있어... 의식을 진정시켜야 해...",
  ui_story_8_7_1_45_dialog_content = "이미 늦었다. 모든 게 형체를 갖추었다.",
  ui_story_8_7_1_46_dialog_content = "「씨앗」은 벌써 뿌리를 내렸다. 녀석의 날카로운 소리가 들리는군...",
  ui_story_8_7_1_47_dialog_content = "어머니의 곁에 소중한 영혼이 하나 더 늘어났도다!",
  ui_story_8_7_1_48_option_content = "(의식을... 진정시켜야 해...)",
  ui_story_8_7_1_49_dialog_content = "쿠우!",
  ui_story_8_7_1_51_dialog_content = "퀴리. 같이 해보자...",
  ui_story_8_7_1_52_dialog_content = "정말 슬픈 일이군. 아이테르의 도움 없이 너희는 먼지나 다름없지.",
  ui_story_8_7_1_53_dialog_content = "으윽!",
  ui_story_8_7_1_54_dialog_content = "PlayerName...",
  ui_story_8_7_1_55_dialog_content = "뭐 하고 있어?",
  ui_story_8_7_1_56_dialog_content = "여기서 이렇게 지면 안 된다고!",
  ui_story_8_7_1_57_dialog_content = "넌 아이테르야... 누구도 네 의식을 제어할 수 없다고!",
  ui_story_8_7_1_58_option_content = "(의식을 진정시켜!)",
  ui_story_8_7_1_59_dialog_content = "......?",
  ui_story_8_7_1_60_dialog_content = "자칫하면... 정신을 빼앗길 뻔했어...",
  ui_story_8_7_1_61_dialog_content = "뭐, 뭐냐! 지금 강제로 전환을 멈춘 거냐!?",
  ui_story_8_7_1_62_dialog_content = "쉿, 시끄러워...",
  ui_story_8_7_1_63_dialog_content = "아까부터 네가 계속 떠들어대서 머리가 아프잖아...",
  ui_story_8_7_1_64_dialog_content = "아니야! 말도 안 돼! 어떻게 「씨앗」의 제어에서 벗어날 수가 있지?!",
  ui_story_8_7_1_65_dialog_content = "이러쿵저러쿵... 재잘재잘...",
  ui_story_8_7_1_66_dialog_content = "네 목소리가 너무 커서 슈모르한테까지 들릴 지경이라고.",
  ui_story_8_7_1_67_dialog_content = "하지만 지금은 뭐라고 외쳐도 상관없어... 내가 다시 디바우러호와 감응했거든.",
  ui_story_8_7_1_F2_dialog_content = "이 콜로서스는 내가 제어하고 있어. 이 방에서는 소리 하나 새 나가지 않을 거야...",
  ui_story_8_7_1_68_dialog_content = "네가 마지막으로 내뱉는 소음조차 그 「어머니」인지 뭔지의 귀에 들리지 않을 거라고.",
  ui_story_8_7_1_69_dialog_content = "PlayerName... 다행이야. 다시 돌아왔구나?",
  ui_story_8_7_1_70_dialog_content = "응, 이제 괜찮아. 미안해, 이런 녀석을 혼자 상대하게 해서.",
  ui_story_8_7_1_71_dialog_content = "머리가 다시 아파지긴 했지만... 그래도 조금은 더 참을 수 있어.",
  ui_story_8_7_1_73_dialog_content = "무지하고 어리석구나, 아무것도 모르는 모독자가! 널 「그곳」으로 인도할 수 있었다고!",
  ui_story_8_7_1_74_dialog_content = "그래, 지금이 아니더라도, 넌 언젠가 우리와 함께하게 될 거다!",
  ui_story_8_7_1_75_dialog_content = "바이스. 쟤 입 좀 다물게 해 줘.",
  ui_story_8_7_1_76_dialog_content = "비비안 씨가 아직 우릴 기다리고 있잖아...",
  ui_story_8_7_1_77_dialog_content = "좋아!",
  ui_story_8_7_2_1_dialog_content = "비비안 님!",
  ui_story_8_7_2_2_dialog_content = "쿠! 쿠우!",
  ui_story_8_7_2_4_dialog_content = "아...",
  ui_story_8_7_2_5_dialog_content = "비비안 님, 어째서... 이렇게까지 약해지셨다니... 죄송해요. 너무 늦어서...",
  ui_story_8_7_2_6_dialog_content = "지금 다른 사람 걱정할 상황이 아닐 텐데.",
  ui_story_8_7_2_7_dialog_content = "누구냐?!",
  ui_story_8_7_2_8_dialog_content = "당신이구나... 바이스, 나 저 사람을 본 적이 있어. 나한테 길을 안내해 준 그 사람이야.",
  ui_story_8_7_2_9_dialog_content = "아, 저 사람이 그 「손에 흰 상자를 든」 사람인 거지?",
  ui_story_8_7_2_10_dialog_content = "난 너희들의 적이 아니야. 보다시피 나도 오로리안이야.",
  ui_story_8_7_2_11_dialog_content = "「파우스트」라고 부르면 돼. 난 진리를 섬기는 사람이야...",
  ui_story_8_7_2_12_dialog_content = "「진리」? 조금 수상하게 들리는데...",
  ui_story_8_7_2_13_dialog_content = "진리는 영원히 변하지 않는 참된 이치이자, 만물의 법이야.\n걱정할 거 없어. 난 널 도와주러 온 거니까.",
  ui_story_8_7_2_14_dialog_content = "지금 당신 자기소개로는 여전히 정체를 알 수가 없는데?",
  ui_story_8_7_2_15_dialog_content = "알 필요 없어. 우선 자신의 몸에 집중해...",
  ui_story_8_7_2_16_dialog_content = "네 몸에 있는 「씨앗」이 곧 싹트려고 해.",
  ui_story_8_7_2_17_dialog_content = "...그래서 그 「씨앗」이 대체 뭔데?",
  ui_story_8_7_2_18_dialog_content = "일단 처리하고 설명할게.",
  ui_story_8_7_2_19_dialog_content = "PlayerName, 옷을 벗어.",
  ui_story_8_7_2_20_dialog_content = "뭐, 뭐라고?!",
  ui_story_8_7_2_21_dialog_content = "미안하지만 지금은 부끄러워할 때가 아니야. 내가 말하는 대로 해.",
  ui_story_8_7_2_22_dialog_content = "몸에 이상한 느낌이 드는 곳이 있지?",
  ui_story_8_7_2_23_dialog_content = "음, 그렇게 말하니까 또 등이 가렵긴 한데...",
  ui_story_8_7_2_24_dialog_content = "등인가.",
  ui_story_8_7_2_25_dialog_content = "날 믿어. 내가 도와줄 수 있으니까.",
  ui_story_8_7_2_26_option_content = "알겠어. 그럼...",
  ui_story_8_7_2_27_dialog_content = "......",
  ui_story_8_7_2_28_dialog_content = "안에 입은 것도 벗어줘.",
  ui_story_8_7_2_29_dialog_content = "...PlayerName, 내가 돌아서 있을까?",
  ui_story_8_7_2_30_dialog_content = "이상한 곳도 아니고 등일 뿐이잖아. 더는 시간 끌지 말았으면 좋겠는데...",
  ui_story_8_7_2_31_option_content = "아, 알겠다고... 벗으면 되잖아...",
  ui_story_8_7_2_32_dialog_content = "이건...",
  ui_story_8_7_2_33_dialog_content = "역시...",
  ui_story_8_7_2_34_dialog_content = "왜? 내 등에 뭐가 있어?",
  ui_story_8_7_2_35_dialog_content = "이런 상황에서 제정신을 유지할 수 있다니... 굉장하다고 해야 할지, 아니면 둔하다고 해야 할지...",
  ui_story_8_7_2_36_dialog_content = "그러니까 무슨 상황인데!",
  ui_story_8_7_2_37_dialog_content = "바이스 양, 「저걸」 파낼 수 있겠어?",
  ui_story_8_7_2_38_dialog_content = "이미 피부 깊숙한 곳까지 들어간 것 같네. 어디에 있는지 보일 때 짧고 굵게 끝내자고.",
  ui_story_8_7_2_39_dialog_content = "...당신한테 내 이름을 알려준 적은 없는 것 같은데.",
  ui_story_8_7_2_40_dialog_content = "맞아, 하지만 그건 중요하지 않아. 특히 지금은.",
  ui_story_8_7_2_41_dialog_content = "내 몸에서 조금이라도 적의를 느낄 수 있겠어?",
  ui_story_8_7_2_42_dialog_content = "......",
  ui_story_8_7_2_43_dialog_content = "알겠어. 강제로 꺼내도 문제는 없겠지?",
  ui_story_8_7_2_44_dialog_content = "어이! 내 몸에 대체...",
  ui_story_8_7_2_45_dialog_content = "함부로 움직이지 마!",
  ui_story_8_7_2_46_dialog_content = "바이스 양, 부탁해.",
  ui_story_8_7_2_47_dialog_content = "...조금 아플지도 몰라. PlayerName.",
  ui_story_8_7_2_48_dialog_content = "으억──?!",
  ui_story_8_7_2_50_dialog_content = "(아, 아파서 말도 안 나온다고! 이게 어디가 「조금 아프다」는 거야?!)",
  ui_story_8_7_2_51_dialog_content = "물러서. 바이스 양! 가까이 다가가선 안 돼...",
  ui_story_8_7_2_52_dialog_content = "...이 물건, 정말 위험하면서도... 매력적이네...",
  ui_story_8_7_2_53_option_content = "그건 대체 뭐야?",
  ui_story_8_7_2_54_dialog_content = "「씨앗」이야. 암귀들은 그렇게 부르는 것 같더라고.",
  ui_story_8_7_2_55_dialog_content = "다른 자료에서는 「힘의 근원」, 「어머니의 입맞춤」, 「승천의 인장」 등이라고도 불리지.",
  ui_story_8_7_2_56_dialog_content = "하지만 결국 동일한 의미야. 암귀는 이걸 통해서 강하고 특별한 힘을 얻을 수 있어.",
  ui_story_8_7_2_57_dialog_content = "더 중요한 건, 바로 이 「씨앗」이 다른 생물을 암귀로 변하게 만드는 유일한 방법이라는 거지...",
  ui_story_8_7_2_58_dialog_content = "변한다니... 설마 거츠더처럼?",
  ui_story_8_7_2_59_dialog_content = "그리고... 슈모르도.",
  ui_story_8_7_2_60_dialog_content = "누굴 이야기하는 건지는 모르겠지만, 만일 빛에 속했던 자가 이 그림자의 힘을 사용한다면...",
  ui_story_8_7_2_61_dialog_content = "「씨앗」은 이미 그 사람의 몸에 뿌리를 내렸을 거야.",
  ui_story_8_7_2_62_option_content = "그럼 난 이제 「치료」된 거야?",
  ui_story_8_7_2_63_dialog_content = "그런 셈이야. 하지만 너 자신의 의지가 더 중요했어.\n아니었으면 내가 나타나기도 전에 넌 이미 침식됐을 테니까.",
  ui_story_8_7_2_64_dialog_content = "그리고 「씨앗」은 질병이 아니야. 오히려... 일종의 의식이라고 해야 맞겠지.",
  ui_story_8_7_2_65_dialog_content = "지금 느낌이 어때?",
  ui_story_8_7_2_66_dialog_content = "분명히 홀가분하겠지? 이런 걸...",
  ui_story_8_7_2_67_dialog_content = "아니, 엄청... 괴로워.",
  ui_story_8_7_2_68_dialog_content = "에?",
  ui_story_8_7_2_69_dialog_content = "맥이 확 풀린 것처럼 숨을 쉬기 힘든 데다가... 가슴이 답답해. 눈앞도 핑 돌고, 목도...",
  ui_story_8_7_2_70_dialog_content = "그게 정상이야.",
  ui_story_8_7_2_71_dialog_content = "이곳의 다크매터는 매우 짙어. 너 같은 아이테르라면 당연히 그런 반응이 있어야 해.",
  ui_story_8_7_2_72_dialog_content = "지금까지 아무 이상이 없었던 건 이 「씨앗」이 널 암귀로 변하게 만들고 있었기 때문이야. 이해했어?",
  ui_story_8_7_2_73_dialog_content = "그런 거였구나... 쿨럭...",
  ui_story_8_7_2_74_dialog_content = "그럼 이건 정말 위험한 물건이잖아. 어서 부숴버리자!",
  ui_story_8_7_2_75_dialog_content = "잠깐, 바이스 양.",
  ui_story_8_7_2_76_dialog_content = "이건 누군가에겐 독약이지만, 누군가에겐 애타게 찾는 보물이라고... 나한테도 말이야.",
  ui_story_8_7_2_77_dialog_content = "...?!",
  ui_story_8_7_2_78_dialog_content = "안심해. 난 이걸로 다른 불쌍한 녀석을 해치려는 아니야. 그저 호기심일 뿐.",
  ui_story_8_7_2_79_dialog_content = "진리의 명을 따르는 사람으로서, 우린 우리만의 추구하는 바가 있어. 단지 그것뿐이야.",
  ui_story_8_7_2_80_dialog_content = "그리고 그걸 내 상자에 넣는다면, 위험할 일도 없을 거야.",
  ui_story_8_7_2_81_dialog_content = "...그 상자... 방금 직접 움직인 거야?",
  ui_story_8_7_2_82_dialog_content = "걱정할 거 없어. 이 상자는 특별하거든. 날 믿어.\n오로리안과 암귀의 비밀은 언젠가 밝혀질 날이 올 거야.",
  ui_story_8_7_2_83_dialog_content = "그리고 우린 이 기나긴 탐구의 길에서 서로를 도우며 나아가야 해.",
  ui_story_8_7_2_84_dialog_content = "좀 알아들을 수 있게 말해 봐... 그걸 가지고 대체 뭘 하려는 건데?",
  ui_story_8_7_2_85_dialog_content = "너도 곧 알게 될 거야. 그럼 다음에 또 보자고. PlayerName, 바이스 양.",
  ui_story_8_7_2_86_dialog_content = "순조롭게 이 난관을 극복하길 바랄게. 음, 아니지, 정확히 말하자면...",
  ui_story_8_7_2_87_dialog_content = "난 머지않은 미래에 너희들이 탈출하는 멋진 모습을 이미 봤거든.",
  ui_story_8_7_2_88_dialog_content = "진리가 그대들을 축복하기를.",
  ui_story_8_7_2_89_dialog_content = "바이...스?",
  ui_story_8_7_2_90_dialog_content = "쿠! 쿠우!",
  ui_story_8_7_2_91_dialog_content = "아, 참모장님! 죄송해요. 조금 전에 급하게 PlayerName의 상처를 치료하느라...",
  ui_story_8_7_2_92_dialog_content = "네, 방금 여러분의 대화를 들은 것 같아요... PlayerName, 괜찮나요?",
  ui_story_8_7_2_F1_dialog_content = "이제 괜찮아요. 비비안 님은 지금 좀 어떠세요?",
  ui_story_8_7_2_F2_dialog_content = "저도 괜찮아요. 방금 전에는 적의 「환상」에 당한 모양이에요. 이젠 정신을 차렸어요.",
  ui_story_8_7_2_93_dialog_content = "쿠우!",
  ui_story_8_7_2_94_dialog_content = "퀴리, 걱정했구나.",
  ui_story_8_7_2_95_dialog_content = "미안해요. 모두에게 폐를 끼쳤네요.",
  ui_story_8_7_2_96_option_content = "그런 말 하지 마.",
  ui_story_8_7_2_97_dialog_content = "비비안 씨가 아니었으면 우린 탈출할 기회조차 없었을 거야...",
  ui_story_8_7_2_98_dialog_content = "그래서 절 구하려고 다시 돌아온 건가요?",
  ui_story_8_7_2_99_dialog_content = "...많은 일이 있었어요. 일단 여길 탈출하고 나서 천천히 말씀드릴게요!",
  ui_story_8_7_2_100_dialog_content = "노라는...요? 그리고 그 신경질적이던 여자애는...",
  ui_story_8_7_2_101_dialog_content = "슈모르 말이지? 지금 근처엔 없지만, 이대로면 들키는 건 시간 문제야.",
  ui_story_8_7_2_102_dialog_content = "방금 벌어진 소란을 슈모르가 이미 느꼈을지도 몰라. 최대한 빨리 여길 벗어나자!",
  ui_story_8_7_2_103_option_content = "괜찮아. 비비안 씨.",
  ui_story_8_7_2_104_dialog_content = "이제 괜찮아. 그 암귀가 당신한테 「씨앗」을 심는 건 막았으니까.",
  ui_story_8_7_2_105_dialog_content = "「씨앗」...? 그러니까... 조금 전에 말했던 그건가요...",
  ui_story_8_7_2_106_dialog_content = "일단 여길 떠나죠. 자세한 건 나중에 말씀드릴게요.",
  ui_story_8_7_2_107_dialog_content = "알겠어요. 그럼... 부탁해요.",
  ui_story_8_7_2_108_dialog_content = "맞다. 노라는요? 그리고 그 엄청나게 강한 녀석은...",
  ui_story_8_7_2_109_dialog_content = "이 근처엔 없는 것 같아. 하지만 그렇다고 방심해선 안 돼.",
  ui_story_8_7_2_110_dialog_content = "방금 벌어진 소란 때문에 슈모르한테 들켰을지도 몰라. 최대한 빨리 여길 벗어나자!",
  ui_story_8_7_2_111_dialog_content = "적을 앞에 두고도 도망칠 수밖에 없는 건가요...",
  ui_story_8_7_2_112_dialog_content = "자난으로 돌아가면 대원수님께 징계를 청해야겠네요...",
  ui_story_8_7_2_113_dialog_content = "......",
  ui_story_8_7_2_114_dialog_content = "부수고 꿰뚫어, 가루로 만들어버려.",
  ui_story_8_7_2_115_dialog_content = "따분한 가치관, 도덕, 그리고 눈앞에 있는 저 역겨운 도시까지... 모두 흔적도 없이 으깨는 거야.",
  ui_story_8_7_2_116_dialog_content = "눈을 크게 뜨고 보라고, PlayerName.",
  ui_story_8_7_2_117_dialog_content = "이 지옥 같은 모습을 네 두 눈동자에, 마지막 아이테르인 네게 보여줄 테니까.",
  ui_story_8_7_2_118_dialog_content = "너희의 그 나약한 유전자에까지 새겨주겠어.",
  ui_story_8_8_1_1_dialog_content = "여긴 백야성이다. 소꿉장난이나 하는 콜로서스 모험단 따위가 아니란 말이다!",
  ui_story_8_8_1_2_dialog_content = "난 네가 어릴 적에 고집스럽게 고양이 한 마리를 구하겠다고 하다가\n나무집에서 떨어졌던 것에서 네 어리석음이 그칠 줄 알았다.",
  ui_story_8_8_1_3_dialog_content = "그래도 결국엔 고양이를 구했으니, 넌 네 고집이 옳았다고 생각했겠지.\n하지만 그게 정녕 올바른 선택이었느냐?",
  ui_story_8_8_1_4_dialog_content = "그럴 가치가 있었냐고 물었다!",
  ui_story_8_8_1_5_dialog_content = "......",
  ui_story_8_8_1_6_dialog_content = "내가 이해한 게 틀리지 않았으면 좋겠네.",
  ui_story_8_8_1_7_dialog_content = "하지만 이상하긴 해... 그분이 그런 식으로 말씀하시는 건 처음 봤거든.",
  ui_story_8_8_1_8_dialog_content = "카렌 언니가 틀렸다고 해도, 이미 늦었잖아.",
  ui_story_8_8_1_9_dialog_content = "벌써 몰래 들어와 버렸는걸...",
  ui_story_8_8_1_10_dialog_content = "다모클레스의 제어실에 말이야.",
  ui_story_8_8_1_11_dialog_content = "음. 만약 다른 사람들에게 잡힌다면, 넌 내가 협박한 거라고 해.",
  ui_story_8_8_1_12_dialog_content = "라파엘이 신경 쓰는 건 그게 아니야~",
  ui_story_8_8_1_13_dialog_content = "카렌 언니는 가끔 유난히 고집스러운 눈빛을 할 때가 있어. 아까처럼.",
  ui_story_8_8_1_14_dialog_content = "라파엘은 항상 어떻게 해야 할지 모르겠을 때마다,\n언니의 그런 눈빛을 보면 「그럼 카렌 언니를 따라가자」고 생각해!",
  ui_story_8_8_1_15_dialog_content = "선택 자체에 옳고 그름은 없어. 선택을 내릴 수 있다는 점이 역시 가장 중요한 거 아닐까?",
  ui_story_8_8_1_16_dialog_content = "......",
  ui_story_8_8_1_17_dialog_content = "언뜻 들으면 철학적으로 들리는데, 가만히 생각해 보면 정말 비논리적이네.",
  ui_story_8_8_1_18_dialog_content = "......",
  ui_story_8_8_1_19_dialog_content = "오! 미카엘! 빨리 왔네!",
  ui_story_8_8_1_20_dialog_content = "......",
  ui_story_8_8_1_21_dialog_content = "고마워. 미카엘. 호위대에선 아무도 내 부탁에 답하지 않을 거라 생각했어. 네가 온 것만으로도 충분해.",
  ui_story_8_8_1_22_dialog_content = "미카엘은 정말 믿음직스럽다니까~! 쓸데없는 질문은 절대 하는 일이 없잖아, 그렇지?",
  ui_story_8_8_1_23_dialog_content = "............",
  ui_story_8_8_1_24_dialog_content = "밖의 상황은 어때? 실드는 아직 괜찮아?",
  ui_story_8_8_1_25_dialog_content = "......",
  ui_story_8_8_1_26_dialog_content = "조금 전에 들어온 보고로는 실드가 이미 눈에 띄게 감소했대.",
  ui_story_8_8_1_27_dialog_content = "그렇게 견고한 루미나 배리어를 파괴할 수 있다니, 역시 그 녀석은 장난이 아냐!",
  ui_story_8_8_1_28_dialog_content = "더는 예전의 그 슈모르가 아니니까. 그리고 난 막지 못했어...",
  ui_story_8_8_1_29_dialog_content = "하지만 이번에야말로! 반드시 해내겠어!",
  ui_story_8_8_1_30_dialog_content = "응! 나 라파엘도 의욕 만땅이야!",
  ui_story_8_8_1_31_dialog_content = "미카엘도 준비된 거지?",
  ui_story_8_8_1_32_dialog_content = "......",
  ui_story_8_8_1_33_dialog_content = "좋아. 그럼 설명해 줄게. 너희가 해야 할 일은 아주 간단해...",
  ui_story_8_8_1_34_dialog_content = "너흰 제어실의 문만 막아줘. 그 누구도 들어오게 해선 안 돼!",
  ui_story_8_8_1_35_dialog_content = "내가 다모클레스를 가동하면 모든 백야성의 에너지가 이곳으로 집중될 거야...",
  ui_story_8_8_1_36_dialog_content = "실드가 일시적으로 사라질 테니, 분명히 큰 혼란에 빠지겠지.",
  ui_story_8_8_1_37_dialog_content = "라파엘, 다른 호위대원들과 다시 연락할 수 있어?",
  ui_story_8_8_1_38_dialog_content = "다른 지역을 수비하라고 해 줘. 다모클레스가 에너지를 충전할 동안 버텨내야 해!",
  ui_story_8_8_1_39_dialog_content = "좋아. 다시 연락해 볼게!",
  ui_story_8_8_1_40_dialog_content = "카렌 언니, 안심해도 좋아. 언니는 옳다고 생각하는 일을 하면 되니까!",
  ui_story_8_8_1_41_dialog_content = "수고해 줘. 그럼... 너희한테 맡길게.",
  ui_story_8_8_1_42_dialog_content = "......",
  ui_story_8_8_1_43_dialog_content = "아버님. 어쩌면 이건 제가 벌이는 가장 미친 짓일지도 모르겠네요.",
  ui_story_8_8_1_44_dialog_content = "하지만...",
  ui_story_8_8_1_45_dialog_content = "「자신의 방식으로 지키고 싶은 사람을 지킨다」...",
  ui_story_8_8_1_46_dialog_content = "전 제 선택이 옳다고 믿어요.",
  ui_story_8_8_1_47_dialog_content = "<color=#e8d9bb>제어실 밖</color>",
  ui_story_8_8_1_48_dialog_content = "대심판관님, 역시나 카렌 님이 들어가셨습니다.",
  ui_story_8_8_1_49_dialog_content = "......",
  ui_story_8_8_1_50_dialog_content = "출동하실 겁니까? 지금이라면...",
  ui_story_8_8_1_51_dialog_content = "그냥 다모클레스 제어실에 들어가기만 한 것이라면,\n카렌은 아무런 규정도 위반하지 않았어요. 그렇지 않나요?",
  ui_story_8_8_1_52_dialog_content = "호위대장으로서 어디든 출입할 권한이 있으니까요.",
  ui_story_8_8_1_53_dialog_content = "하지만 다모클레스를 가동한다면 이야기는 달라지겠죠.",
  ui_story_8_8_1_54_dialog_content = "하지만 그때까지 기다린다면... 늦고 말 겁니다.",
  ui_story_8_8_1_55_dialog_content = "뭐가 늦는다는 거죠?",
  ui_story_8_8_1_56_dialog_content = "백야성의 존재는 질서와 규칙 위에 세워졌어요. 이곳의 철칙을 깨트리고 함부로 행동한다면...",
  ui_story_8_8_1_57_dialog_content = "그것이야말로 돌이킬 수 없는 일이겠죠.",
  ui_story_8_8_1_58_dialog_content = "알겠습니다. 그럼 언제라도 움직일 수 있도록 대기하고 있겠습니다.",
  ui_story_8_8_1_59_dialog_content = "그리고 일부 병력은 다른 지역의 지원 준비를 해 두세요.",
  ui_story_8_8_1_60_dialog_content = "지원... 말씀이십니까?",
  ui_story_8_8_1_61_dialog_content = "카렌이 정말로 다모클레스를 가동한다면 백야성의 성문이 잠시 열리게 될 테니까요.",
  ui_story_8_8_1_62_dialog_content = "이제 곧 찾아오게 될 것은 과연 구사일생의 기회일까요, 아니면 심연으로 떨어질 위기일까요.",
  ui_story_8_8_1_63_dialog_content = "...카렌 드 솔라드.",
  ui_story_8_9_1_1_dialog_content = "이쪽이야! 내가 기억하고 있는 경로가 틀리지 않았다면 우린...",
  ui_story_8_9_1_2_dialog_content = "잠깐만요. 바이스...",
  ui_story_8_9_1_3_dialog_content = "왜 그러세요?",
  ui_story_8_9_1_4_dialog_content = "우...우리, 잠깐 기다리는 게 좋겠어요.",
  ui_story_8_9_1_5_dialog_content = "참모장님, 지금은 시간을 지체할 수 없어요... 제가 업어드릴게요! 자!",
  ui_story_8_9_1_6_dialog_content = "그런 뜻이 아니에요. 우린 지금 디바우러호의 어디에 있는 거죠?",
  ui_story_8_9_1_7_dialog_content = "위치 말인가요? 이제 출구까지 거의 다 왔어요.",
  ui_story_8_9_1_8_dialog_content = "디바우러호가... 싸우고 있나요?",
  ui_story_8_9_1_9_dialog_content = "안에서는 정확히 알 수 없지만, 아마 디바우러호는 지금 계속해서 백야성의 실드를 공격하고 있을 거예요.",
  ui_story_8_9_1_10_dialog_content = "하지만 지금 상황이 계속된다면, 실드가 파괴되는 것도 시간문제예요...",
  ui_story_8_9_1_11_dialog_content = "백야성에선... 무슨 대책이 있나요?",
  ui_story_8_9_1_12_dialog_content = "카렌이 돌아가서 다모클레스를 가동하려고 애쓰고 있을 거예요.",
  ui_story_8_9_1_13_dialog_content = "그 정도로 심각한 거군요...",
  ui_story_8_9_1_14_dialog_content = "네. 디바우러호는 벌써 보완을 마쳤고, 지금의 힘이라면...",
  ui_story_8_9_1_15_dialog_content = "......",
  ui_story_8_9_1_16_dialog_content = "슈모르는요? 아직 우릴 발견하지 못했나요?",
  ui_story_8_9_1_17_dialog_content = "지금까진 PlayerName의 감응 능력 덕분에 이 콜로서스를 억제하고 있었어요.",
  ui_story_8_9_1_18_dialog_content = "맞아. 내가 내부의 정보 연결을 끊어놔서, 지금 슈모르는 우리가 도망쳤다는 걸 알아차리지 못했을 거야.",
  ui_story_8_9_1_19_dialog_content = "하지만 어느 정도까지 감응을 해도 될지 모르겠어. 실수로 더 깊게 감응하기라도 한다면...\n슈모르가 이상한 점을 눈치챌 거야.",
  ui_story_8_9_1_20_dialog_content = "그렇다면, 지금은 형세가 역전됐네요...",
  ui_story_8_9_1_21_dialog_content = "적의 정세는 드러나 있고, 저들은 우리 상황을 아직 몰라요.",
  ui_story_8_9_1_22_dialog_content = "참모장님. 설마...",
  ui_story_8_9_1_23_dialog_content = "우린 가면 안 돼요. 바이스.",
  ui_story_8_9_1_24_dialog_content = "네?",
  ui_story_8_9_1_25_dialog_content = "기본적인... 전략 분석법, 잊은 건 아니겠죠? 지금 우린 내부에서 적을 무너트릴 수 있는...",
  ui_story_8_9_1_26_dialog_content = "유일한 희망이에요.",
  ui_story_8_9_1_27_dialog_content = "하지만 참모장님 상태가...",
  ui_story_8_9_1_28_dialog_content = "이럴 때 절 신경 쓸 필요는 없어요.",
  ui_story_8_9_1_29_dialog_content = "우린 이 절호의 기회를 포기해선 안 돼요. 만약 성공한다면 온 도시를 지켜낼 수 있을 거예요.",
  ui_story_8_9_1_30_dialog_content = "......",
  ui_story_8_9_1_31_dialog_content = "우선순위는 당신도 알고 있겠죠. 그렇죠?",
  ui_story_8_9_1_32_dialog_content = "바이스, 예전의 당신은 무척 냉정하고 결단력 있는 사람이었죠.\n하지만 요즘엔 조금 망설이게 된 것 같네요.",
  ui_story_8_9_1_33_dialog_content = "참모장님. 저는 ... 그 누구도 포기하고 싶지 않은 것뿐이에요. 게다가 두 사람은...",
  ui_story_8_9_1_34_dialog_content = "그럼 묻죠. 만약에 우리의 역할이 서로 바뀌었다면,\n당신은 제가 이런 절호의 기회를 포기하는 걸 허락했을까요...?",
  ui_story_8_9_1_35_dialog_content = "전...",
  ui_story_8_9_1_36_dialog_content = "그리고 PlayerName 덕분에 제 상처는 어느 정도는 해결됐어요.",
  ui_story_8_9_1_37_dialog_content = "바이스. 적을 눈앞에 두고 도망칠 생각인가요?",
  ui_story_8_9_2_1_dialog_content = "<color=#e8d9bb>백야성 안, 몇 년 전</color>",
  ui_story_8_9_2_2_dialog_content = "(「자신의 방식으로 지키고 싶은 사람을 지킨다...」)",
  ui_story_8_9_2_3_dialog_content = "......",
  ui_story_8_9_2_4_dialog_content = "하지만...",
  ui_story_8_9_2_5_dialog_content = "고양이가... 죽었어요.",
  ui_story_8_9_2_6_dialog_content = "어떤 생물이든 언젠가는 죽는다, 카렌.",
  ui_story_8_9_2_7_dialog_content = "제가 구하지 못했어요... 조금만 더 조심했더라면...",
  ui_story_8_9_2_8_dialog_content = "고양이는 무서워서 스스로 나무집에서 떨어진 거다. 네 잘못이 아니야.",
  ui_story_8_9_2_9_dialog_content = "하지만 분명히 도울 수 있었어요... 분명히 할 수 있었는데.",
  ui_story_8_9_2_10_dialog_content = "휴, 넌 아직 너무 어려.",
  ui_story_8_9_2_11_dialog_content = "네가 여기서 얻어야 할 교훈은 「남을 도울 수 있었다」가 아니라\n「앞으로 더 조심해서 자신을 지켜야 한다」는 점이다.",
  ui_story_8_9_2_F1_dialog_content = "얼마나 많은 사람들이 네 안위를 걱정하고 있는지 아는 거냐?",
  ui_story_8_9_2_12_dialog_content = "하지만 고양이와 함께 나무집에서 떨어졌는데 고양이는 죽고, 넌 찰과상조차 없구나.",
  ui_story_8_9_2_13_dialog_content = "솔라드 가문 아니랄까 봐, 하나같이 괴물들이로군...",
  ui_story_8_9_2_14_dialog_content = "아무튼 여기 얌전히 있거라. 네 아버지께 이미 말씀드렸으니, 의사에게 진찰부터 받는 게 좋겠다.",
  ui_story_8_9_2_15_dialog_content = "아우토 씨.",
  ui_story_8_9_2_16_dialog_content = "음?",
  ui_story_8_9_2_17_dialog_content = "하나만 물어봐도 될까요?",
  ui_story_8_9_2_18_dialog_content = "하아, 말해 보거라.",
  ui_story_8_9_2_19_dialog_content = "어머니께서... 돌아가셨을 때, 같이 계셨나요?",
  ui_story_8_9_2_20_dialog_content = "......",
  ui_story_8_9_2_21_dialog_content = "난 그 자리에 없었다, 카렌. 너희 아버지 외엔 그 누구도 그때 상황에 대해 자세히 알지 못해.",
  ui_story_8_9_2_22_dialog_content = "......",
  ui_story_8_9_2_23_dialog_content = "제가 북방에 가지 않았어야 했어요. 어머니 곁에 남아서 잘 지켜드렸어야 했는데...",
  ui_story_8_9_2_24_dialog_content = "만약 제가 지켜드렸다면... 어쩌면 그렇게 되지 않았겠죠...?",
  ui_story_8_9_2_25_dialog_content = "네가 있었다고 해도, 뭔가 꼭 반드시 변할 거란 보장은 없다.",
  ui_story_8_9_2_26_dialog_content = "네?",
  ui_story_8_9_2_27_dialog_content = "이건 사실이야. 솔라드도 바꾸지 못한 현실이 너 하나 더 있다고 해서 달라졌을 것 같으냐?",
  ui_story_8_9_2_28_dialog_content = "...그러니까, 전 여전히 아무도 지켜낼 수 없는... 어린아이인 건가요?",
  ui_story_8_9_2_29_dialog_content = "그게 아니면 뭐란 말이냐.",
  ui_story_8_9_2_30_dialog_content = "......",
  ui_story_8_9_2_31_dialog_content = "고양이가 죽은 것뿐이다, 카렌.",
  ui_story_8_9_2_32_dialog_content = "다음부턴 함부로 혼자서 여기저기 돌아다니지 않도록 해라. 교양 있게 행동해야지.",
  ui_story_8_9_2_33_dialog_content = "......",
  ui_story_8_9_2_34_dialog_content = "카렌 언니!",
  ui_story_8_9_2_35_dialog_content = "말해.",
  ui_story_8_9_2_36_dialog_content = "심판소 사람들이 벌써 에워쌌어!",
  ui_story_8_9_2_37_dialog_content = "그래? 진입을 시도하진 않은 거지?",
  ui_story_8_9_2_38_dialog_content = "아직! 하지만 다들 우리 쪽을 주시하고 있어서... 안 좋은 예감이 들어...",
  ui_story_8_9_2_39_dialog_content = "이리돈 대심판관님도 같이 있는 것 같아...",
  ui_story_8_9_2_40_dialog_content = "......",
  ui_story_8_9_2_41_dialog_content = "라파엘, 미카엘하고 같이 준비해.",
  ui_story_8_9_2_42_dialog_content = "응, 알겠어!",
  ui_story_8_9_2_43_dialog_content = "문을 지켜줘. 그 누구도 다모클레스의 제어실에 들어오게 해선 안 돼. 알겠지?",
  ui_story_8_9_2_44_dialog_content = "알겠어!",
  ui_story_8_9_2_45_dialog_content = "다모클레스...",
  ui_story_8_9_2_46_dialog_content = "부디 백야의 주인의 날카로운 검이 되어, 우리 앞에 놓인 절망의 먹구름을 꿰뚫어 줘...",
  ui_story_8_9_2_47_dialog_content = "다모클레스, <color=#FFB400>가동</color>!",
  ui_story_8_10_1_1_dialog_content = "무, 무슨 일이죠?!",
  ui_story_8_10_1_2_dialog_content = "정전인가?",
  ui_story_8_10_1_3_dialog_content = "...제어실! 다모클레스의 제어실로 가라!",
  ui_story_8_10_1_4_dialog_content = "멍하니 있지 말고! 빨리 가서 무슨 상황인지 확인해라!",
  ui_story_8_10_1_5_dialog_content = "......",
  ui_story_8_10_1_6_dialog_content = "솔라드, 만일 이게 카렌이 벌인 짓이라면, 어떻게 감당할 생각이지?!",
  ui_story_8_10_1_7_dialog_content = "내가 지시한 일이 아니다. 카렌은 자유의지를 지니고 스스로 선택했을 뿐이다.",
  ui_story_8_10_1_8_dialog_content = "그렇다 해서 책임을 피할 순 없을 거다...!",
  ui_story_8_10_1_9_dialog_content = "이리돈은?! 심판소의 병력들도...",
  ui_story_8_10_1_10_dialog_content = "대심판관님은 이미 제어실 입구에 계십니다!",
  ui_story_8_10_1_11_dialog_content = "하, 하이가든 구역에서 소란이 발생했습니다! 귀족들이 공황 상태에 빠져 다들...",
  ui_story_8_10_1_12_dialog_content = "우선 질서를 유지해라! 당황할 거 없다.\n설령 다모클레스가 가동된다 해도 백야성의 에너지가 곧바로 떨어지진...",
  ui_story_8_10_1_14_dialog_content = "...성이... 추락하고 있는 거냐?!",
  ui_story_8_10_1_15_dialog_content = "에너지가 전부 다모클레스 쪽으로 모이고 있군. 이제 모든 설비들이 그쪽으로 에너지를 양보해줄 거다.",
  ui_story_8_10_1_16_dialog_content = "나도 안다고! 어떻게 좀 해 보란 말이다!",
  ui_story_8_10_1_17_dialog_content = "호위대에게 각 지역에서 대기하도록 이미 명령해뒀다.\n설마 내게 원로원을 움직일 권한이라도 넘겨줄 셈인가?",
  ui_story_8_10_1_18_dialog_content = "솔라드...!",
  ui_story_8_10_1_19_dialog_content = "성주님, 아우토 님, 실드가...!",
  ui_story_8_10_1_20_dialog_content = "<color=#e8d9bb>같은 시각, 디바우러호 안</color>",
  ui_story_8_10_1_22_dialog_content = "방금 그건...?!",
  ui_story_8_10_1_23_dialog_content = "디바우러호가 움직인 건가요? 밖에 무슨 일이 생긴 거죠?",
  ui_story_8_10_1_24_dialog_content = "쿠우──!",
  ui_story_8_10_1_25_dialog_content = "......",
  ui_story_8_10_1_26_dialog_content = "백야성의 실드가... 사라지고 있어요.",
  ui_story_8_10_1_27_dialog_content = "확실한가요? 그럼 카렌이 다모클레스를 가동하는 데 성공한 게 분명해요!",
  ui_story_8_10_1_28_dialog_content = "어쩌면 슈모르가 방어막을 파괴했을 수도 있죠. 지금은 그 무엇도 확신할 순 없어요.",
  ui_story_8_10_1_29_dialog_content = "...전 카렌이 해냈다고 믿어요.",
  ui_story_8_10_1_30_dialog_content = "잠깐만... 왜 실드가 사라지는 건데?",
  ui_story_8_10_1_31_dialog_content = "다모클레스의 충전에는 백야성의 모든 에너지를 집중해야 해. 실드에 공급하던 것까지 포함해서 말이야.",
  ui_story_8_10_1_32_dialog_content = "하지만 그리 오래 걸리진 않을 거야. 그 시간만 버틸 수 있으면...",
  ui_story_8_10_1_34_dialog_content = "이런! 감응에 문제가 생겼어... 슈모르가 우릴 발견했어!",
  ui_story_8_10_1_35_dialog_content = "미안, 녀석이 갑자기 거세게 움직여서 미처 준비를...",
  ui_story_8_10_1_36_dialog_content = "PlayerName!",
  ui_story_8_10_1_37_dialog_content = "슈모르...!",
  ui_story_8_10_1_38_dialog_content = "너, 어째서... 언제 도망친 거지?",
  ui_story_8_10_1_39_dialog_content = "먼저 내 질문에 대답해... 대체 뭘 한 거야!",
  ui_story_8_10_1_40_dialog_content = "왜 네 운명을 받아들이지 않는 거야? 어째서 그런 의미도 없는 저항을 계속하는 거냐고?!",
  ui_story_8_10_1_41_dialog_content = "너도 결국엔 이 도시처럼 내게 문을 열게 될 거잖아!",
  ui_story_8_10_1_42_dialog_content = "디바우러호의 공격이 효과가 있었다고 생각해? 넌...",
  ui_story_8_10_1_43_dialog_content = "(아냐, 아직 다모클레스에 대해 모를지도 몰라!)",
  ui_story_8_10_1_F1_dialog_content = "아하하, 디바우러호의 위력을 제대로 못 본 거 아냐?",
  ui_story_8_10_1_44_dialog_content = "PlayerName, 넌 궁금하지 않아? 왜 내가 널 몇 번이나 쓰러트리고도 죽이지 않았는지...",
  ui_story_8_10_1_45_dialog_content = "......",
  ui_story_8_10_1_46_dialog_content = "처음엔 무시했고, 동정했어. 그러다 나중엔 네 미련함에... 화가 났어.",
  ui_story_8_10_1_47_dialog_content = "하지만 이젠 지겨워졌어. 난 너희 아이테르에게 한 가지만 증명하면 되거든.",
  ui_story_8_10_1_48_dialog_content = "너희가 입으로만 말하는 그런 게 아닌... 진정한 힘을!",
  ui_story_8_10_1_49_dialog_content = "무슨 소리 하는지 하나도 모르겠다고!",
  ui_story_8_10_1_50_dialog_content = "곧 알게 될 거야.",
  ui_story_8_10_1_51_dialog_content = "알게 될 거라고...",
  ui_story_8_10_1_52_dialog_content = "PlayerName, 왜 그래? 괜찮아? 정신 차려!",
  ui_story_8_10_1_53_dialog_content = "걱정 마. 정신은 멀쩡하니까. 방금 슈모르와... 대화를 하고 있었어.",
  ui_story_8_10_1_54_dialog_content = "우린 이미 들켰어! 이젠 녀석을 막으러 가는 수밖에 없어!",
  ui_story_8_10_1_55_dialog_content = "동의해요. 가죠. 서둘러야 해요!",
  ui_story_8_10_1_56_dialog_content = "쿠우!",
  ui_story_8_10_1_57_dialog_content = "알겠어. 그럼 난동을 부려서 최대한 슈모르를 방해하면 되겠지?",
  ui_story_8_10_1_58_dialog_content = "우리가 카렌을 위해 시간을 충분히 벌어야 할 텐데...",
  ui_story_8_10_2_1_dialog_content = "비비안 님... 조심하세요!",
  ui_story_8_10_2_2_dialog_content = "몸이 아직도 많이 굳어있네요... 미안해요. 별로 도움이 되지 않는 것 같아요...",
  ui_story_8_10_2_3_dialog_content = "참모장님. 아니면 여기서 저흴 기다려주세요! 함교에 갈수록 암귀가 더 많아질 테니...",
  ui_story_8_10_2_4_dialog_content = "상관을 무시하지 마세요, 바이스. 제가 어떻게 부하와 젊은 친구만 싸우게 둘 수 있겠어요?",
  ui_story_8_10_2_5_dialog_content = "으윽... 꽉 잡아!",
  ui_story_8_10_2_6_dialog_content = "녀석이 필사적으로 백야성을 공격하고 있어...! 바깥은 지금 대체 어떻게 된 거지...",
  ui_story_8_10_2_7_dialog_content = "...가라 ...3분대! 어서...",
  ui_story_8_10_2_8_dialog_content = "...합류해! ...녀석의 외피 틈새를 공격...",
  ui_story_8_10_2_9_dialog_content = "이건! 호위대의 통신인가?!",
  ui_story_8_10_2_10_dialog_content = "하지만 디바우러호가 우리 통신을 간섭할 수 있을 텐데, 어떻게...",
  ui_story_8_10_2_11_dialog_content = "아마 가까운 거리의 신호라서 그런 건 아닐까요?\n아무튼 통신 내용을 보면 지금 병사들은 이 바깥에 있어요.",
  ui_story_8_10_2_12_dialog_content = "이 바깥에 있다고? 호위대가 디바우러호를 공격하고 있는 건가?",
  ui_story_8_10_2_13_dialog_content = "맞아요. 많은 병사들이 근처에 있겠죠. 물러서지 않고, 목숨을 걸고 말이에요...",
  ui_story_8_10_2_14_dialog_content = "...가라! 물러서지 마라! 뒤에는 백야성이...",
  ui_story_8_10_2_15_dialog_content = "날 따라... 계속! 버텨라... 놈들이...",
  ui_story_8_10_2_16_dialog_content = "비공정 통제 불능! 추락...■■■... ■■... 녀석에게 충돌시키겠다!",
  ui_story_8_10_2_17_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_8_10_2_18_dialog_content = "......",
  ui_story_8_10_2_19_dialog_content = "방금... 병사들이 자길 희생한 거야?!",
  ui_story_8_10_2_20_dialog_content = "으윽...",
  ui_story_8_10_2_21_dialog_content = "참모장님, 상처가...",
  ui_story_8_10_2_22_dialog_content = "가요. 멍하니 있을 시간이 없어요.",
  ui_story_8_10_2_23_dialog_content = "17년 전처럼 되기 전에... 녀석들을 막아야 해요.",
  ui_story_8_10_2_24_dialog_content = "알겠어...",
  ui_story_8_10_2_25_dialog_content = "함교에 거의 다 왔어. PlayerName, 정말 슈모르가 저기 있는 거야?",
  ui_story_8_10_2_26_dialog_content = "확실해. 가자, 이 모든 걸 끝내러.",
  ui_story_8_10_2_27_dialog_content = "이제 어떤 암귀도 우리의 앞을 막을 수 없어.",
  ui_story_8_13_2_1_dialog_content = "선생님. 저... 또 실패했어요.",
  ui_story_8_13_2_2_dialog_content = "괜찮아. 다시 한번 해봐.",
  ui_story_8_13_2_3_dialog_content = "하지만 전...",
  ui_story_8_13_2_4_dialog_content = "태어났을 때부터 강한 사람은 없어.\n성장하고, 시련을 겪고, 끊임없는 실패에서 다시 일어나야 하는 거야...",
  ui_story_8_13_2_5_dialog_content = "넌 분명히 「강해질」 수 있을 거야.",
  ui_story_8_13_2_6_dialog_content = "하지만...",
  ui_story_8_13_2_7_dialog_content = "슈모르~",
  ui_story_8_13_2_8_dialog_content = "너희 왔구나. 슈모르, 네 친구들이 왔어. 어서 가서 놀거라. 오늘 훈련은 여기까지 하는 게 좋겠다.",
  ui_story_8_13_2_9_dialog_content = "맞아요! 어서 와, 우린 네 「친구」잖아!",
  ui_story_8_13_2_10_dialog_content = "하하하하!",
  ui_story_8_13_2_11_dialog_content = "......",
  ui_story_8_13_2_12_dialog_content = "왜 그래?",
  ui_story_8_13_2_13_dialog_content = "...난...",
  ui_story_8_13_2_14_dialog_content = "......",
  ui_story_8_13_2_15_dialog_content = "난 모두를 죽였어.",
  ui_story_8_13_2_16_dialog_content = "직접 목을 끊어버렸지. 뼈가 부서지는 소리가 노래처럼 이어졌어.",
  ui_story_8_13_2_17_dialog_content = "진정한 힘을... 찬양하는 노래였다고.",
  ui_story_8_13_2_18_dialog_content = "슈모르, 상황은 어떻습니까?",
  ui_story_8_13_2_19_dialog_content = "방해하지 마. 백야성은 이미 파괴됐고, 오로리안들은 최후의 발악을 하고 있다고.",
  ui_story_8_13_2_20_dialog_content = "어때? 내가 말했지. 난 할 수 있다고 말이야!",
  ui_story_8_13_2_22_dialog_content = "난 너희 누구도 못 했던 일을 해냈다고. 아하하...",
  ui_story_8_13_2_23_dialog_content = "하하하하...!",
  ui_story_8_13_2_24_dialog_content = "......",
  ui_story_8_13_2_25_dialog_content = "앞에서 알짱거리지 말아 줄래?",
  ui_story_8_13_2_26_dialog_content = "그 아이테르가 곧 올 겁니다.",
  ui_story_8_13_2_27_dialog_content = "잘됐네. 지금 마침 학살의 서막이 열릴 참이었거든. 들어오라고 해.",
  ui_story_8_13_2_28_dialog_content = "안 죽일 겁니까?",
  ui_story_8_13_2_29_dialog_content = "어째서? 내 「동족」이잖아.",
  ui_story_8_13_2_30_dialog_content = "...하지만 전에는...",
  ui_story_8_13_2_31_dialog_content = "귀찮아 죽겠네. 이놈이고 저놈이고, 왜 다들 자꾸 날 귀찮게 하는 걸까?",
  ui_story_8_13_2_32_dialog_content = "어서 와, PlayerName. 내 옆에 서는 게 좋을 거야.",
  ui_story_8_13_2_33_dialog_content = "내가 어떻게 됐는지... 두 눈을 크게 뜨고 똑똑히 보라고...",
  ui_story_8_14_1_1_dialog_content = "......",
  ui_story_8_14_1_3_dialog_content = "미카엘! 도와주러 왔어!",
  ui_story_8_14_1_4_dialog_content = "......?",
  ui_story_8_14_1_5_dialog_content = "카렌 언니 말이야? 아주 순조로워! 다른 사람들이 문을 잘 지키고 있거든!",
  ui_story_8_14_1_6_dialog_content = "<color=#e8d9bb>다모클레스의 제어실, 문밖</color>",
  ui_story_8_14_1_7_dialog_content = "비켜! 비키란 말이다!",
  ui_story_8_14_1_8_dialog_content = "이리돈, 뭘 하는 건가?! 왜 쳐들어가지 않는 거냔 말이다!",
  ui_story_8_14_1_9_dialog_content = "보시는 대로입니다.",
  ui_story_8_14_1_10_dialog_content = "너무 조급해하지 마세요. 아우토 님...",
  ui_story_8_14_1_11_dialog_content = "물러서! 원로원을 대표하여 전원 물러날 것을 명령한다!",
  ui_story_8_14_1_F1_dialog_content = "누가 너희한테 제어실을 지키라고 한 것이냐?! 어서 비켜라!",
  ui_story_8_14_1_12_dialog_content = "솔라드는? 이런 상황에 대체 어딜 간 거냐! 딸자식 간수는 포기했단 말이냐!",
  ui_story_8_14_1_13_dialog_content = "아우토 님, 진정하고 제 말 좀 들어보세요...",
  ui_story_8_14_1_14_dialog_content = "저길 보세요. 하늘엔 온통 암귀 뿐이잖아요~ 심판소와 원로원에서는 소탕하러 가지 않는 건가요?",
  ui_story_8_14_1_15_dialog_content = "가브리엘...",
  ui_story_8_14_1_16_dialog_content = "내가 암귀들을 전부 태워버려도 될까?",
  ui_story_8_14_1_17_dialog_content = "물론이지~ 귀족들의 집을 태우지 않게 조심해~",
  ui_story_8_14_1_18_dialog_content = "응, 하지만... 쉽진 않을 거야...",
  ui_story_8_14_1_19_dialog_content = "......",
  ui_story_8_14_1_20_dialog_content = "가브리엘, 정말 제 앞을 막아설 생각인가요?",
  ui_story_8_14_1_21_dialog_content = "음... 맞아요.",
  ui_story_8_14_1_22_dialog_content = "아니지, 정확히 말하자면 당신 앞에 앉아있을 생각이에요~",
  ui_story_8_14_1_23_dialog_content = "심판소 병사! 전진...",
  ui_story_8_14_1_24_dialog_content = "<size=45>어디 해 봐.</size>",
  ui_story_8_14_1_25_dialog_content = "거, 건물이 무너졌습니다! 뒤에 있는 건물이, 어서 피하십시오...",
  ui_story_8_14_1_26_dialog_content = "!",
  ui_story_8_14_1_27_dialog_content = "너무 많아! 이러다가 놓칠 것 같아!",
  ui_story_8_14_1_28_dialog_content = "...!",
  ui_story_8_14_1_29_dialog_content = "알겠어! 좁은 곳으로 철수해서 방어하자!",
  ui_story_8_14_1_30_dialog_content = "암귀가 여길 넘어가게 할 순 없어!",
  ui_story_8_14_1_31_dialog_content = "크오오──!",
  ui_story_8_14_1_33_dialog_content = "<color=#e8d9bb>다모클레스의 제어실</color>",
  ui_story_8_14_1_34_dialog_content = "......",
  ui_story_8_14_1_35_dialog_content = "(라파엘, 미카엘... 그리고 달려온 가브리엘까지 모두 싸우고 있는 건가...)",
  ui_story_8_14_1_36_dialog_content = "다모클레스... 부탁이야. 어서...",
  ui_story_8_14_1_37_dialog_content = "백야성의 백성과 이 도시엔... 네 도움이 필요해...!",
  ui_story_8_14_1_38_dialog_content = "시간이 없어. 충전을 서둘러야 해... 내 모든 힘을 써버린다 해도...",
  ui_story_8_14_1_39_dialog_content = "<color=#e8d9bb>디바우러호, 함교</color>",
  ui_story_8_14_1_40_dialog_content = "탑.",
  ui_story_8_14_1_41_dialog_content = "성벽.",
  ui_story_8_14_1_42_dialog_content = "그리고 파리 같은 비공정들...",
  ui_story_8_14_1_43_dialog_content = "전차는 이미 움직이기 시작했어. 너희가 수백 번을 죽어도 날 막진 못할 거라고...",
  ui_story_8_14_1_44_dialog_content = "아하하, 이제... 그 누구도 날 막을 순 없어...!",
  ui_story_8_14_1_45_dialog_content = "슈모르.",
  ui_story_8_14_1_46_dialog_content = "PlayerName.",
  ui_story_8_14_1_47_dialog_content = "숨이 찬 걸 보니 조급한 모양이지? 연극은 이제 막 시작했을 뿐이야.",
  ui_story_8_14_1_48_dialog_content = "자, 앉아.",
  ui_story_8_14_1_49_dialog_content = "그만... 멈춰. 그만하라고...",
  ui_story_8_14_1_50_dialog_content = "PlayerName! 슈모르는 디바우러호를 조종하느라 바쁘니까 그 틈을 타서...",
  ui_story_8_14_1_51_dialog_content = "바이스, 9시 방향을 봐요.",
  ui_story_8_14_1_52_dialog_content = "크오오...",
  ui_story_8_14_1_53_dialog_content = "고위 암귀예요!",
  ui_story_8_14_1_54_dialog_content = "기운이 무척 특이하네요. 아무래도 우릴 계속 공격하려는 것 같네요...",
  ui_story_8_14_1_55_dialog_content = "저들이 오게 내버려 둬, 잡종. 내 흥을 깨지 말고.",
  ui_story_8_14_1_56_dialog_content = "모처럼 시작된 공연인데 아무도 보는 사람이 없으면 너무 아깝잖아.",
  ui_story_8_14_1_57_dialog_content = "...슈모르, 매번 노라 님의 명령을 거역하더니, 이런 때마저 고집을 부리겠다는 겁니까?",
  ui_story_8_14_1_58_dialog_content = "제게 당신을 막을 권한은 없지만, 당신도 제게 명령할 순 없습니다.",
  ui_story_8_14_1_59_dialog_content = "우린 모두 어머니 한 분께만 충성을 다할 뿐... 개인의 사욕을 우선해선 안 됩니다!",
  ui_story_8_14_1_60_dialog_content = "어머니, 어머니, 그놈의 어머니... 재미없어.",
  ui_story_8_14_1_61_dialog_content = "PlayerName, 보다시피 내가 지금 좀 바빠.",
  ui_story_8_14_1_62_dialog_content = "하지만 백야성의 멸망은 어떻게 해서든 네게 직접 보여주고 싶어. 그러니까...",
  ui_story_8_14_1_63_dialog_content = "처음으로 하는 부탁이긴 한데... 얼른 그 암귀를 죽이고 내 옆으로 와.",
  ui_story_8_14_1_64_dialog_content = "...?!",
  ui_story_8_14_1_65_dialog_content = "이건 또 무슨 속셈이지? PlayerName, 조심해야 해!",
  ui_story_8_14_1_66_dialog_content = "알고 있어. 하지만 녀석의 말도 한 가지는 맞아. 우선 이 녀석부터 처리해야 해!",
  ui_story_8_14_1_67_dialog_content = "「존함」은 오래전부터 들었습니다. 아이테르, 그리고 오로리안.",
  ui_story_8_14_1_68_dialog_content = "당신들은 우릴 여러 번 귀찮게 만들었죠. 전 반드시 이클립스와 어머니의 의지를 관철해야 하니...",
  ui_story_8_14_1_69_dialog_content = "자, 오십시오.",
  ui_story_8_14_1_70_dialog_content = "...날 실망하게 하지 마. PlayerName.",
  ui_story_8_14_2_1_dialog_content = "아냐, 그럴 리가... 이럴 리가 없어!",
  ui_story_8_14_2_2_dialog_content = "노라 님... 한 번 더 제게 기회를 주십시오... 어머니께서 제게 다시 힘을...",
  ui_story_8_14_2_3_dialog_content = "넌 말이 너무 많아...",
  ui_story_8_14_2_4_dialog_content = "크아악──!",
  ui_story_8_14_2_5_dialog_content = "슈모르... 배신을...!",
  ui_story_8_14_2_6_dialog_content = "배신? 헛소리, 난 처음부터 그 누구한테도 충성한 적 없어.",
  ui_story_8_14_2_7_dialog_content = "슈모르... 이제 끝이야.",
  ui_story_8_14_2_8_dialog_content = "응? 뭐가 끝났다는 거지? 이제 막 시작했잖아?",
  ui_story_8_14_2_9_dialog_content = "디바우러호... 감응 전개!",
  ui_story_8_14_2_10_dialog_content = "PlayerName!",
  ui_story_8_14_2_11_dialog_content = "뭐 하는 거야!",
  ui_story_8_14_2_12_dialog_content = "널 막겠어... 네 콜로서스부터!",
  ui_story_8_14_2_13_dialog_content = "넌 조종할 수 없어. 디바우러호는 곧 나고, 내가 곧 디바우러호니까!",
  ui_story_8_14_2_14_dialog_content = "그런 건 모르겠고, 내가 아는 건 그저 네가 백야성을 공격하게 둘 수 없다는 거야...",
  ui_story_8_14_2_15_dialog_content = "거긴 오로리안의 터전... 모두의 집이자...",
  ui_story_8_14_2_16_dialog_content = "소중한 내 동료들이... 있는 곳이니까!",
  ui_story_8_14_2_18_dialog_content = "그러니까... 모든 걸 걸고서라도... 크아아아...!",
  ui_story_8_14_2_19_dialog_content = "...PlayerName! 코피가 나고 있어!",
  ui_story_8_14_2_20_dialog_content = "오지 마! 공격해... 슈모르를 공격하라고!",
  ui_story_8_14_2_21_dialog_content = "말했잖아, 넌 할 수 없다고...",
  ui_story_8_14_2_22_dialog_content = "바이스, 조심하세요!",
  ui_story_8_14_2_23_dialog_content = "(다시 한번 디바우러호와 감응하겠어!)",
  ui_story_8_14_2_24_dialog_content = "지겹지도 않아? PlayerName?!",
  ui_story_8_14_2_25_dialog_content = "그래. 내가 죽지 않는 한... 포기하지 않을 거야!",
  ui_story_8_14_2_26_dialog_content = "슈모르! 네겐 승산이 없어!",
  ui_story_8_14_2_27_dialog_content = "하아? 무슨 헛소리를 하는 거야? 눈을 크게 뜨고 보라고!",
  ui_story_8_14_2_28_dialog_content = "백야성은 이미 끝났어! 그곳의 병사, 그 껍데기, 전부 끝장이라고!",
  ui_story_8_14_2_29_dialog_content = "내가 해낸 거야. PlayerName! 그 누구도 하지 못했던 일을 내가 해냈어!",
  ui_story_8_14_2_30_dialog_content = "왜 인정하지 않는 건데?! 절대적인 힘 앞에 순순히 굴복하면 되는데, 왜 자꾸 거부하는 거냐고!",
  ui_story_8_14_2_31_dialog_content = "디바우러호, 엔진... 정지...",
  ui_story_8_14_2_32_dialog_content = "이건 내 콜로서스야!",
  ui_story_8_14_2_33_dialog_content = "으아아아아악──!",
  ui_story_8_14_2_35_dialog_content = "으... 윽, 어, 어지러워. 난...",
  ui_story_8_14_2_36_dialog_content = "PlayerName...",
  ui_story_8_14_2_37_dialog_content = "미안, 나와 참모장님만으론... 슈모르를 막을 수 없었어...",
  ui_story_8_14_2_38_dialog_content = "힘의 차이를 알겠어? 너랑 이 조무래기들로 이 차이를 뛰어넘을 수 있을 것 같아?",
  ui_story_8_14_2_39_dialog_content = "똑바로 보고 있으라고, PlayerName. 난 널 괴롭히고 싶지 않으니까, 특히 지금은...",
  ui_story_8_14_2_40_dialog_content = "난 증인이 필요해. 아이테르로서... 이 모든 것을...",
  ui_story_8_14_2_41_dialog_content = "...음?",
  ui_story_8_14_2_42_dialog_content = "......?",
  ui_story_8_14_2_43_dialog_content = "(뭔가... 주변이... 조용해진 것 같은데?)",
  ui_story_8_14_2_44_dialog_content = "......",
  ui_story_8_14_2_45_dialog_content = "...너희, 또 무슨 수작을 부린 거지?",
  ui_story_8_14_2_46_dialog_content = "(슈모르도 모르는 눈치인데? 슈모르가 한 짓이 아니라고?)",
  ui_story_8_14_2_47_dialog_content = "에?",
  ui_story_8_14_2_48_dialog_content = "왜... 갑자기 온몸에 소름이...",
  ui_story_8_14_2_49_dialog_content = "바이스... 공기야. 공기가 변했어.",
  ui_story_8_14_2_50_dialog_content = "아, 그리고 소리도... 왜 소리가 다 사라진 거지?",
  ui_story_8_14_2_51_dialog_content = "확실히 너무 조용해. 어떻게 아무 소리도 안 들릴 수가 있지...?",
  ui_story_8_14_2_52_dialog_content = "바이스, 바닥을 보세요!",
  ui_story_8_14_2_53_dialog_content = "바닥의 흙먼지가... 한 방향으로 움직이고 있어요...",
  ui_story_8_14_2_54_dialog_content = "바람... 같아요. 느껴지나요? 공기도 어디론가 모여들고 있어요. 마치...",
  ui_story_8_14_2_55_dialog_content = "뭔가 쌓이는 것 같은데...?",
  ui_story_8_14_2_56_dialog_content = "여러분... 이 느낌, 뭔가 좋지 않아요!",
  ui_story_8_14_2_58_dialog_content = "PlayerName, 참모장님. 몸을 낮추고 뭐라도 꽉 잡으세요...",
  ui_story_8_14_2_59_dialog_content = "이게 제가 생각하는 그거라면... 이제 시간이 된 거예요.",
  ui_story_8_14_2_62_dialog_content = "백야성 상공에... 저건 또 뭐야?",
  ui_story_8_14_2_63_dialog_content = "빛...?",
  ui_story_8_14_2_64_dialog_content = "......",
  ui_story_8_14_2_65_dialog_content = "...만물은 백야 아래에, 내 선언은 여기까지야.",
  ui_story_8_14_2_66_dialog_content = "슈모르... 아이테르의 배신자, 나 카렌 드 솔라드가 네게...",
  ui_story_8_14_2_67_dialog_content = "마지막 판결을 내린다!",
  ui_story_8_14_2_68_dialog_content = "저건... 대체 뭐야?!",
  ui_story_8_14_2_69_dialog_content = "모두 엎드려어어!",
  ui_story_8_14_2_70_dialog_content = "<color=#e8d9bb>콰콰콰아앙──!</color>",
  ui_story_8_14_2_73_dialog_content = "(뭐야?! 광선 공격...? 내 눈...!)",
  ui_story_8_14_2_74_dialog_content = "(...왜 움직일 수가 없지? 어째서... 못 움직이는 거냐고?!)",
  ui_story_8_14_2_75_dialog_content = "(슈모르...)",
  ui_story_8_14_2_76_dialog_content = "(이 자식!)",
  ui_story_8_14_2_77_dialog_content = "(내가 말했었지... 죽을 때까지... 계속해서 널 막을 거라고...)",
  ui_story_8_14_2_78_dialog_content = "(이 정도로 날 막을 수 있을 것 같아?!)",
  ui_story_8_14_2_82_dialog_content = "슈모르!",
  ui_story_8_14_2_83_dialog_content = "쓸데없는 발악은 집어치워!",
  ui_story_8_14_2_F1_dialog_content = "다모클레스의 광선이 너와 네 디바우러호를 꿰뚫을 테니까!",
  ui_story_8_14_2_84_dialog_content = "(카, 카렌!)",
  ui_story_8_14_2_87_dialog_content = "디바우러호, 피해! 움직여!",
  ui_story_8_14_2_88_dialog_content = "도망치게... 두지 않을 거야... 으아아아!",
  ui_story_8_14_2_89_dialog_content = "포구 방향에서 벗어나! 움직이라고!",
  ui_story_8_14_2_90_dialog_content = "(모든 힘을 다 써서라도... 절대로! 콜로서스를 움직이지 못하게 해야 해!)",
  ui_story_8_14_2_91_dialog_content = "내 콜로서스를 건드리지 마! PlayerName! 감응을 끊으라고!",
  ui_story_8_14_2_92_dialog_content = "(안 돼... 광선이... 빗나가고 있어?!)",
  ui_story_8_14_2_93_dialog_content = "카렌, 네 루미나는 너무 약하다! 이대로는 빛을 인도할 수 없다! 물러서라!",
  ui_story_8_14_2_94_dialog_content = "?!",
  ui_story_8_14_2_95_dialog_content = "어, 어떻게?!",
  ui_story_8_14_2_96_dialog_content = "다모클레스를 인도하려는 것뿐이다!",
  ui_story_8_14_2_97_dialog_content = "고개를 돌리지 말고 앞을 봐라. 네 목표는 앞에 있지 않으냐!",
  ui_story_8_14_2_98_dialog_content = "적을 섬멸할 마지막 순간에, 가장 해선 안 되는 게 무엇인지 기억하고 있겠지!",
  ui_story_8_14_2_99_dialog_content = "당연하죠! 아버님!",
  ui_story_8_14_2_100_dialog_content = "「적의 심장을 꿰뚫을 때까지, 창을 쥔 손에 힘을 빼지 않는다!」",
  ui_story_8_14_2_101_dialog_content = "(주, 죽을 거야! 이대로 가면, 난──)",
  ui_story_8_14_2_102_dialog_content = "(비켜! 꺼지라고! PlayerName──!)",
  ui_story_8_14_2_103_dialog_content = "슈모르!",
  ui_story_8_14_2_104_dialog_content = "네가 죽는 그 순간까지! 내 눈을 똑바로 봐라!",
  ui_story_8_14_2_105_dialog_content = "아, 안──",
  ui_story_8_14_2_106_dialog_content = "안 돼──!",
  ui_story_8_14_2_112_dialog_content = "슈모르.",
  ui_story_8_14_2_113_dialog_content = "네? 선생님, 저 여기 있어요.",
  ui_story_8_14_2_114_dialog_content = "왜... 이런 짓을 하는 거지?",
  ui_story_8_14_2_115_dialog_content = "......",
  ui_story_8_14_2_116_dialog_content = "넌...",
  ui_story_8_14_2_117_dialog_content = "...왜... 우릴 죽이는 거지?",
  ui_story_8_14_2_118_dialog_content = "내 남은 목숨으로 널 저주한다. 슈모르... 배신자, 아이테르의 변절자, 내 실패작...",
  ui_story_8_14_2_119_dialog_content = "네가 죽는 순간, 우리보다 백 배는 더 고통스럽기를, 슈모르...",
  ui_story_8_14_2_120_dialog_content = "널 저주한다. 영원히...",
  ui_story_8_14_2_121_dialog_content = "...평안을... 얻을 수 없을 거다...",
  ui_story_8_15_1_1_dialog_content = "늦었군. 노라.",
  ui_story_8_15_1_2_dialog_content = "여긴 너무 멀잖아. 꼭 여기까지 숨을 필요가 있었어?",
  ui_story_8_15_1_3_dialog_content = "물건은?",
  ui_story_8_15_1_4_dialog_content = "아직 슈모르한테 있어. 거의 다 됐으니까 재촉하지 마.",
  ui_story_8_15_1_5_dialog_content = "왜 슈모르가 백야성을 공격하도록 용인했지?\n네가 해야 할 일은 간단하지 않았나? 그저 슈모르의 몸에서...",
  ui_story_8_15_1_6_dialog_content = "어린애잖아. 세상 물정을 몰랐을 뿐이야.",
  ui_story_8_15_1_7_dialog_content = "그게 중요해?",
  ui_story_8_15_1_8_dialog_content = "......",
  ui_story_8_15_1_9_dialog_content = "네 신분을 잊지 마라. 오로리안.",
  ui_story_8_15_1_10_dialog_content = "하아~암.",
  ui_story_8_15_1_11_dialog_content = "...이상으로 다운타운의 피해 보고를 마칩니다. 다음은 호위대장에 대한 처벌로...",
  ui_story_8_15_1_12_dialog_content = "되었다. 우선 여기까지 듣도록 하지.",
  ui_story_8_15_1_13_dialog_content = "먼저 나가라. 5분 후에 다시 이어서 보고하도록.",
  ui_story_8_15_1_14_dialog_content = "예!",
  ui_story_8_15_1_15_dialog_content = "말해라.",
  ui_story_8_15_1_16_dialog_content = "오랜만이야. 솔라드.",
  ui_story_8_15_1_17_dialog_content = "위로 인사라도 할 생각인가?",
  ui_story_8_15_1_18_dialog_content = "하하하, 그런다고 네가 믿겠어?",
  ui_story_8_15_1_19_dialog_content = "비장의 카드까지 꺼낸 사람치곤 상태가 나쁘진 않네.",
  ui_story_8_15_1_20_dialog_content = "겨우 한 장 내보였을 뿐이다. 심심풀이로 치자고.",
  ui_story_8_15_1_21_dialog_content = "그리고 지금 이 도시를 지키고 있는 건 나 혼자만이 아니다.",
  ui_story_8_15_1_22_dialog_content = "난 자녀 교육 같은 건 관심 없으니까 그건 집어치워.",
  ui_story_8_15_1_23_dialog_content = "오히려 이번에 내가 도와주지 않았다고 마음에 두는 건 아니겠지?",
  ui_story_8_15_1_24_dialog_content = "깊게 생각할 거 없어. 이건 내가 백야성의 힘을 믿었기 때문이라고.\n영원히 함락되지 않는 도시의 성주 나리.",
  ui_story_8_15_1_25_dialog_content = "그리고 내 쪽에도 꽤 재미있는 일이 벌어지고 있거든... 너도 곧 알게 될 거야.",
  ui_story_8_15_1_26_dialog_content = "좋아. 일루미나 연방이 과연 어디까지 할 수 있는지 지켜보도록 하지.",
  ui_story_8_15_1_27_dialog_content = "흔들리는 불씨가 마침내 밤의 장막에 흠집을 낼 때가 되었으니까...",
  ui_story_8_15_1_28_dialog_content = "여명의 빛을 위하여...!",
  ui_story_9_1_1_1_dialog_content = "들어가셔서 참관하시면 됩니다.",
  ui_story_9_1_1_2_dialog_content = "고마워요... PlayerName, 가자.",
  ui_story_9_1_1_3_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_9_1_1_4_dialog_content = "바이스, 아직 뭐가 뭔지 잘 모르겠는데...",
  ui_story_9_1_1_5_option_content = "여긴 뭐 하는 곳이야?",
  ui_story_9_1_1_6_dialog_content = "여긴 백야성 하이가든의 심판소야.",
  ui_story_9_1_1_7_dialog_content = "저기 위에 지팡이를 들고 있는 여자가 바로 대심판관 <color=#FFB400>이리돈</color> 씨일 거야.",
  ui_story_9_1_1_8_option_content = "저 사람들은 누구야?",
  ui_story_9_1_1_9_dialog_content = "내가 아는 게 맞다면...",
  ui_story_9_1_1_10_dialog_content = "저기 위에 지팡이를 들고 있는 여자가 바로\n이 심판소를 주관하는 대심판관, <color=#FFB400>이리돈</color> 씨일 거야.",
  ui_story_9_1_1_11_dialog_content = "그리고 그 옆의 엄숙한 표정을 한 남자는...",
  ui_story_9_1_1_12_dialog_content = "...알고 있어! 카렌의 아버지였지?",
  ui_story_9_1_1_13_dialog_content = "응, 백야성의 성주, <color=#FFB400>다니엘 드 솔라드</color> 씨야.",
  ui_story_9_1_1_14_dialog_content = "왠지 조금 떨리는 기분인걸...",
  ui_story_9_1_1_15_dialog_content = "쉿...",
  ui_story_9_1_1_16_dialog_content = "......",
  ui_story_9_1_1_17_dialog_content = "그대들이 바로 카렌 호위대장이 말했던 「동료」들인 모양이로군.",
  ui_story_9_1_1_18_dialog_content = "콜록... 안녕하세요, 성주님.",
  ui_story_9_1_1_19_dialog_content = "전 일루미나 연방의 바이스예요. 이쪽은 PlayerName, 그 콜로서스의 조종사구요.",
  ui_story_9_1_1_20_dialog_content = "...안녕하세요. PlayerName입니다.",
  ui_story_9_1_1_21_dialog_content = "격식 차릴 것 없다.",
  ui_story_9_1_1_22_dialog_content = "그대들이 적의 공격을 늦추기 위해 용감하게 적과 맞섰고,\n백야성을 지키는 과정에서 매우 중요한 역할을 했다고 들었다.",
  ui_story_9_1_1_23_dialog_content = "이에 백야성을 대표해 감사의 뜻을 표하는 바다.",
  ui_story_9_1_1_24_dialog_content = "감사합니다, 성주님. 저흰 그저 저희가 할 수 있는 일을 했을 뿐인걸요.",
  ui_story_9_1_1_25_dialog_content = "부상은 좀 어떠한가. 호전되었는가?",
  ui_story_9_1_1_26_dialog_content = "의료진을 보내주신 덕분에 많이 좋아졌어요.",
  ui_story_9_1_1_27_dialog_content = "좋다. 일전의 위급한 시기에 지원군을 보낸 일루미나 연방의 우애는\n백야성의 모두가 기억할 것이다.",
  ui_story_9_1_1_28_dialog_content = "부디 내 대신 백야성의 감사를 일루미나의 백성들에게도 전해주길 바란다.",
  ui_story_9_1_1_29_dialog_content = "네, 성주님. 제가 꼭 전해드릴게요.",
  ui_story_9_1_1_X29_dialog_content = "좋다.",
  ui_story_9_1_1_X30_dialog_content = "대심판관이여, 이제 개정을 선포해도 좋다.",
  ui_story_9_1_1_X31_dialog_content = "네. 성주 전하.",
  ui_story_9_1_1_30_dialog_content = "이제 개정하겠습니다. 당사자에게 법정에 입장하라고 하세요.",
  ui_story_9_1_1_31_dialog_content = "예!",
  ui_story_9_1_1_32_dialog_content = "(카렌...)",
  ui_story_9_1_1_33_dialog_content = "만물은 백야 아래에.",
  ui_story_9_1_1_34_dialog_content = "저는 심판소를 대표하여, 이곳에서 카렌 드 솔라드의 재판 결과를 대독하겠습니다.",
  ui_story_9_1_1_35_dialog_content = "현임 백야성 호위대장, 카렌 드 솔라드.",
  ui_story_9_1_1_36_dialog_content = "확인된 바에 따르면, 피고인은 재임 기간 동안...",
  ui_story_9_1_1_37_dialog_content = "삼자 결의를 위반하고, 기사장들을 협박하여 제어실을 강제로 점거해,\n독단적으로 다모클레스를 발동시켰습니다.",
  ui_story_9_1_1_38_dialog_content = "그 행위는 백야성의 실드 가동을 중단시키는 직접적인 원인으로 작용하였으며,\n이로 인해 백야성 하이가든과 미드가든의 습격을 초래했습니다.",
  ui_story_9_1_1_39_dialog_content = "그 결과 108명의 귀족 부상자가 발생하였습니다.\n하인 사상자는 계산하지 않았으며, 그 외 막대한 재산 피해를 유발했습니다.",
  ui_story_9_1_1_40_dialog_content = "이러한 행위는 백야성의 법률을 위반한 것이며, 엄중히 처벌해야 마땅합니다.",
  ui_story_9_1_1_41_dialog_content = "단, 습격자를 물리치고 백야성의 수호에 공로를 세운 것을 참작하여,\n이에 따라 법리와 공과를 판단하였습니다.",
  ui_story_9_1_1_42_dialog_content = "이에 심판소는 다음과 같이 의결하는 바입니다. 카렌 드 솔라드에게 1년 정직 및 보호관찰을...",
  ui_story_9_1_1_43_dialog_content = "정말 터무니없군! 어째서 이런 판결이 가능하단 말인가!",
  ui_story_9_1_1_44_dialog_content = "......",
  ui_story_9_1_1_45_dialog_content = "호위대장이 벌인 일은 백야성의 모든 귀족의 목숨을 걸고 장난을 친 엄중한 만행이다!",
  ui_story_9_1_1_46_dialog_content = "이번에는 요행이 따랐을 뿐, 이대로 방임한다면 다음에는 또 무슨 수작을 벌일지 누가 알겠냔 말이다!",
  ui_story_9_1_1_47_dialog_content = "솔라드, 이건 지금 그대가 심판소와 결탁하여 노골적으로 그대의 여식을 감싸들고 있는 게 아닌가?",
  ui_story_9_1_1_48_dialog_content = "아우토 트로이, 심판소에서 대심판관의 선고를 방해하는 것은 귀족으로서 마땅한 예의가 아닐 텐데.",
  ui_story_9_1_1_49_dialog_content = "흥.",
  ui_story_9_1_1_50_dialog_content = "대심판관, 계속하게.",
  ui_story_9_1_1_51_dialog_content = "이에 심판소는 다음과 같이 의결하는 바입니다. 카렌 드 솔라드, 1년 정직 및 보호관찰을 명합니다.",
  ui_story_9_1_1_52_dialog_content = "이 1년간, 카렌 드 솔라드는 반드시 백야성 습격의 진상을 밝혀내야 합니다.",
  ui_story_9_1_1_53_dialog_content = "또한 이를 백야성의 모든 귀족들에게 확실하게 해명해 주시기 바랍니다.",
  ui_story_9_1_1_54_dialog_content = "만약 이를 명확히 조사해내지 못한다면, 심판소는 카렌 드 솔라드의 직위와 귀족 신분...",
  ui_story_9_1_1_55_dialog_content = "...그리고 백야성에 거주할 권리를 박탈할 것입니다.",
  ui_story_9_1_1_56_dialog_content = "만물은 백야 아래에, 부디 「빛의 신」께서 백야의 백성들을 지켜주시길.",
  ui_story_9_1_1_57_dialog_content = "만물은 백야 아래에.",
  ui_story_9_1_1_58_dialog_content = "바이스, PlayerName, 이쪽이야.",
  ui_story_9_1_1_59_dialog_content = "카렌, 괜찮아?",
  ui_story_9_1_1_60_dialog_content = "난 괜찮아. 신경 써 줘서 고마워.",
  ui_story_9_1_1_61_dialog_content = "그것보다 PlayerName 너, 몸은 괜찮아진 거야?",
  ui_story_9_1_1_62_dialog_content = "방금 그 분위기... 너무 무서웠어...",
  ui_story_9_1_1_63_dialog_content = "...못난 꼴을 보여버렸네.",
  ui_story_9_1_1_64_dialog_content = "PlayerName 네 몸은 이미 나은 것 같구나.",
  ui_story_9_1_1_65_dialog_content = "낫기야 나았지만... 하, 하하...",
  ui_story_9_1_1_66_dialog_content = "방금 그 아우토라는 남자...",
  ui_story_9_1_1_67_dialog_content = "대심판관이 선고를 마치기도 전에 큰 소리로 반대하고 말이야...",
  ui_story_9_1_1_68_dialog_content = "어떻게 그럴 수가 있는 거지? 성주님이나 카렌을 존중하는 태도가 전혀 없잖아!",
  ui_story_9_1_1_69_dialog_content = "카렌 네가 다모클레스를 가동한 것도 분명히 백야성을 보호하기 위해서였잖아.",
  ui_story_9_1_1_70_dialog_content = "게다가 끝내 적을 물리치기까지 했어.",
  ui_story_9_1_1_71_dialog_content = "그런데도 어떻게 네가 큰 죄를 짓기라도 한 것처럼 생각할 수가 있는 거지?",
  ui_story_9_1_1_72_dialog_content = "정말 백야성의 귀족답게 조금도 논리적이지가 않아!",
  ui_story_9_1_1_73_dialog_content = "......",
  ui_story_9_1_1_74_dialog_content = "...!",
  ui_story_9_1_1_75_dialog_content = "미안... 백야성을 나쁘게 말하려던 건 아냐...",
  ui_story_9_1_1_76_dialog_content = "괜찮아. 네게 악의가 없는 건 알고 있어. 그리고 난 백야성의 법과 판단도 믿어.",
  ui_story_9_1_1_77_dialog_content = "심판소에서 명령을 내리지 않았어도 난 이 문제를 확인할 생각이었어.",
  ui_story_9_1_1_78_dialog_content = "네 마음은 알겠어. 나도... 진실을 알아내고 싶어.",
  ui_story_9_1_1_79_dialog_content = "하지만 심판소는 카렌한테 조사를 명령했으면서, 병력은 왜 더 지원해 주질 않는 거야?",
  ui_story_9_1_1_80_dialog_content = "어쩌면... 성주 전하께선 처음부터 슈모르를 위협으로 여기지 않으셨을지도 몰라...",
  ui_story_9_1_1_81_dialog_content = "어...어째서?",
  ui_story_9_1_1_82_dialog_content = "재판이 끝나고, 난 혼자 성주 전하를 뵈러 갔어...",
  ui_story_9_1_1_83_dialog_content = "아버님, 슈모르가 백야성을 공격한 일에 대해... 여쭙고 싶은 게 있습니다.",
  ui_story_9_1_1_84_dialog_content = "말해라.",
