  ui_story_9_1_1_86_dialog_content = "오히려 실드를 공격하도록 놔두신 건가요?",
  ui_story_9_1_1_87_dialog_content = "카렌, 하이가든 호위대의 대장으로서, 네 직무를 이해하고 있느냐?",
  ui_story_9_1_1_88_dialog_content = "네...?",
  ui_story_9_1_1_89_dialog_content = "알고 있습니다. 호위대의 직무는 백성들을 보호하는 겁니다.",
  ui_story_9_1_1_90_dialog_content = "외람되지만, 전 아버님께서 왜 제 질문에 답하시는 대신,\n오히려 저와 관계없는 질문을 하시는지 잘 이해가 되지 않습니다.",
  ui_story_9_1_1_91_dialog_content = "역시나 이해하지 못한 모양이로구나.",
  ui_story_9_1_1_92_dialog_content = "하이가든 호위대는 본디 하이가든만을 책임져 왔다.\n다시 말해 고위 귀족들이 살고 있는 구역 말이지.",
  ui_story_9_1_1_93_dialog_content = "그러나 최근 하이가든 호위대의 관할 구역이 확대된 것은\n어디까지나 인력 부족 문제 때문일 뿐이다.",
  ui_story_9_1_1_94_dialog_content = "그래서 다운타운 구역의 치안 문제까지 담당하게 된 것이지.",
  ui_story_9_1_1_95_dialog_content = "결국 사람들은 고위 귀족들의 안전을 지키는 것이 네 의무라고 생각하고 있을 것이다.",
  ui_story_9_1_1_96_dialog_content = "......",
  ui_story_9_1_1_97_dialog_content = "난 네가 자기 잘못을 깨달았으리라 생각한다.",
  ui_story_9_1_1_98_dialog_content = "그리고 방금 네 질문에 대한 답이라면...",
  ui_story_9_1_1_99_dialog_content = "정녕 그런 것 따위가 백야성의 실드를 깨트릴 수 있다고 생각했느냐?",
  ui_story_9_1_1_100_dialog_content = "아버님, 그럼 그 말씀은...",
