  ui_story_9_1_1_103_dialog_content = "성주님의 그 말씀은 무슨 뜻인 거지...?",
  ui_story_9_1_1_104_dialog_content = "나도 전혀 모르겠어. 그분이 대체 무슨 생각을 하시는 건지...",
  ui_story_9_1_1_105_dialog_content = "백야성이든... 일루미나든... 내가 걱정할 일은 아니라고 생각해...",
  ui_story_9_1_1_106_dialog_content = "난... 그저 과거의 진실을 찾고 싶어!",
  ui_story_9_1_1_107_dialog_content = "PlayerName...",
  ui_story_9_1_1_108_dialog_content = "크흠, 그건 그렇고. 그때를 생각하면 아직도 정말 소름 끼쳐.",
  ui_story_9_1_1_109_dialog_content = "광선이 눈앞까지 왔는데도 PlayerName 네가 꼼짝도 안 할 줄은 몰랐다니까!",
  ui_story_9_1_1_110_dialog_content = "나랑 비비안 님이 그렇게 붙잡고 가려고 해도 움직이질 않다니 말이야.",
  ui_story_9_1_1_111_dialog_content = "다행히 퀴리도 도와주러 왔고, 디바우러호가 광선을 맞기 전에 탈출해서 망정이지.",
  ui_story_9_1_1_112_dialog_content = "그때 난 디바우러호를 잡아두는 것만 생각했으니까...",
  ui_story_9_1_1_113_dialog_content = "그래도 카렌이 다모클레스를 이끈 덕분에 디바우러호를 명중시킬 수 있었어.",
