  ui_story_9_1_1_115_dialog_content = "어, 어떻게?!",
  ui_story_9_1_1_116_dialog_content = "다모클레스를 인도하려는 것뿐이다!",
  ui_story_9_1_1_117_dialog_content = "...백야성을 지키는 건 내 사명이니까.",
  ui_story_9_1_1_118_dialog_content = "그럼 비비안 씨랑 퀴리는 일루미나로 돌아간 거야?",
