  ui_story_9_1_1_122_dialog_content = "슈모르는 정말 죽은 걸까?",
  ui_story_9_1_1_123_dialog_content = "우리가 디바우러호에서 탈출하기 직전까지, 슈모르는 계속 함교에 있었어.\n왠지 움직일 수 없는 것처럼 보였어.",
  ui_story_9_1_1_124_dialog_content = "다모클레스를 정면으로 맞았다면, 어떤 생물이든 살아남지 못했을 거야.",
