  ui_story_9_1_1_129_dialog_content = "반응이 없어...",
  ui_story_9_1_1_130_dialog_content = "헤헷, 마침 잘 왔어.",
  ui_story_9_1_1_131_dialog_content = "그로누 선배?! 자난성으로 휴가 간 거 아니었어요?",
  ui_story_9_1_1_132_dialog_content = "에헤헤, 겨우 발생한 「서브 퀘스트」를 놓칠 순 없잖아. 게다가 무려 콜로서스인걸!",
  ui_story_9_1_1_133_dialog_content = "라파엘이 데려왔어~ 내 무적의 파트너 누누!",
  ui_story_9_1_1_134_dialog_content = "라파엘이 일루미나에 처음 갔을 때 우린 진짜 한눈에 서로를 알아봤다니까!\n게다가 손발도 잘 맞아서 그 뒤로 바로 친해졌지 뭐야!",
