  ui_story_9_1_1_136_dialog_content = "아무튼 내가 이미 재료를 다 찾아서, PlayerName 녀석을 위해 콜로서스를 고쳐놨다 이거지~",
  ui_story_9_1_1_137_dialog_content = "지난번에 PlayerName한테 「HP 회복」 도움을 받은 것도 있으니까,\n이번엔 「클리어 보상」은 안 받는 거로 해줄게.",
