  ui_story_9_1_1_151_dialog_content = "아르카누스호는 이미 콜로서스의 기능을 상실했으니까...",
  ui_story_9_1_1_152_dialog_content = "그래서 사용할 수 있는 재료를 회수해서 스카이워커호의 수리에 사용해 봤어.",
  ui_story_9_1_1_153_dialog_content = "<color=#FFB400>멘델슨</color>! 내 스카이워커호를 너와 함께 나눌게!",
  ui_story_9_1_1_154_dialog_content = "지금부터 영원히, 스카이워커가 네 눈과 귀가 되어... 구름 위의 풍경을 모두 보여줄 거야...",
  ui_story_9_1_1_155_dialog_content = "이게... 죽음이구나... 상상했던 것과는, 조금... 다르네... 외로워...",
  ui_story_9_1_1_156_dialog_content = "(멘델슨, 결국 너와 아르카누스호가 우릴 도와준 거구나...)",
  ui_story_9_1_1_157_dialog_content = "근데... 여전히 스카이워커호의 의식과 감응할 수가 없어...",
  ui_story_9_1_1_158_dialog_content = "그게... 안 그래도 함교에서 부품처럼 보이는 물건을 하나 찾았거든.",
  ui_story_9_1_1_159_dialog_content = "근데 외부는 이미 너무 심하게 파손됐고, 그나마 멀쩡한 건 이 작은 조각뿐이었어.",
  ui_story_9_1_1_160_dialog_content = "이건... 전에 스카이워커가 의식 모듈에 코어라 불리는 부분이 있다고 말해준 적이 있었어.",
  ui_story_9_1_1_161_dialog_content = "그리고 자기 「의식」은 그 코어 안에 「담겨」 있다고 했었어.",
  ui_story_9_1_1_162_dialog_content = "만약 이게 바로 그 코어라면, 스카이워커의 의식을 다시 회복시킬 수 있을지도 몰라!",
  ui_story_9_1_1_163_dialog_content = "다행이네! 그럼 이게 그 코어가 맞겠지?",
  ui_story_9_1_1_164_dialog_content = "그게... 아마 그렇지 않을까? 스카이워커가 나한테 모듈 얘기를 한 적은 있지만,\n나한테 직접 보여준 적은 없거든...",
  ui_story_9_1_1_165_dialog_content = "음, 그렇다고 이걸 뜯어서 확인할 순 없겠지?",
  ui_story_9_1_1_166_dialog_content = "그럼... 일단은 이게 그 코어라고 생각하는 거지?",
  ui_story_9_1_1_167_dialog_content = "아마... 그럴 거야.",
  ui_story_9_1_1_168_dialog_content = "그럼 어떻게 고치는지 알아?",
  ui_story_9_1_1_169_dialog_content = "......",
  ui_story_9_1_1_170_dialog_content = "난...",
  ui_story_9_1_1_171_dialog_content = "그럼 PlayerName도, 그로누 선배도 방법을 모르는 거야...?",
  ui_story_9_1_1_172_dialog_content = "정말 미안해.",
  ui_story_9_1_1_173_dialog_content = "내 수준으로는 이런 구시대의 기술을 해독할 수가 없거든.",
  ui_story_9_1_1_174_dialog_content = "나도... 콜로서스에 대한 지식은 스카이워커한테서 조금 배웠을 뿐이야.",
  ui_story_9_1_1_175_dialog_content = "하지만 지금까지 이런 문제에 대해 생각해본 적도 없었고,\n언젠가... 스카이워커가 내 곁을 떠날 거란 생각도 전혀 해본 적 없었어...",
  ui_story_9_1_1_X175_dialog_content = "내가 스카이워커를 조금이라도 더 신경 써줬더라면...",
  ui_story_9_1_1_176_dialog_content = "이것은 시련입니다, PlayerName. 외로움을 받아들이고 의지를 연마해야만, 강자가 될 수 있습니다.",
  ui_story_9_1_1_177_dialog_content = "현실은 당신이 아직 살아있다는 것입니다.\n그리고 당신이 계속 살아갈 수 있도록 보장하는 것이 제가 할 일입니다.",
  ui_story_9_1_1_178_dialog_content = "PlayerName, 전 백야성 상공에서 비행하며 여러분의 연락을 기다리겠습니다.",
  ui_story_9_1_1_179_dialog_content = "좋아. 그럼 부탁할게, 스카이워커.",
  ui_story_9_1_1_180_dialog_content = "스카이워커, 내 말 듣고 있지? 그렇지?",
  ui_story_9_1_1_181_dialog_content = "미안해... 내가...",
  ui_story_9_1_1_182_dialog_content = "널 지켜주지 못했어. 내가 왜 그렇게 방심했던 걸까...",
  ui_story_9_1_1_183_dialog_content = "PlayerName...",
  ui_story_9_1_1_184_dialog_content = "에? 라파엘은 잘 모르겠는데. 지금 콜로서스는 전보다 더 튼튼해진 거 아냐?",
  ui_story_9_1_1_185_dialog_content = "왜 그렇게 슬퍼하는 건데? PlayerName.",
  ui_story_9_1_1_186_dialog_content = "라파엘, 조용히 있어.",
  ui_story_9_1_1_187_dialog_content = "아, 미안...",
  ui_story_9_1_1_188_dialog_content = "PlayerName, 그때 네가 스카이워커호와 떨어진 건 백야성의 사람들을 보호하기 위해서였어.",
  ui_story_9_1_1_189_dialog_content = "그러니까 난 이 문제에 대한 책임이 있어.",
  ui_story_9_1_1_190_dialog_content = "아니야, 스카이워커의 일은 너흴 탓할 순 없어. 다들 날 충분히 많이 도와줬는걸.",
  ui_story_9_1_1_191_dialog_content = "이건 전부... 슈모르와 그 암귀들 때문이야!",
  ui_story_9_1_1_192_dialog_content = "슈모르... 아! 잊어버릴 뻔했네...",
  ui_story_9_1_1_193_dialog_content = "사실 라파엘... 카렌 언니한테 전할 중요한 소식이 있었어...",
  ui_story_9_1_1_194_dialog_content = "무슨 일인데?",
  ui_story_9_1_1_195_dialog_content = "기사단이 조사해 봤는데, 디바우러호가 <color=#FFB400>헤븐즈 밸리</color> 방향으로 추락했어!",
  ui_story_9_1_1_196_dialog_content = "...그렇구나. 고생했어. 아무래도 진실을 알아내려면 PlayerName 네 고향으로 가야 할 것 같네.",
  ui_story_9_1_1_197_dialog_content = "헤...헤븐즈 밸리...?",
  ui_story_9_1_1_198_dialog_content = "디바우러호가 헤븐즈 밸리에 추락하다니... 정말 아이러니한걸.",
  ui_story_9_1_1_199_dialog_content = "PlayerName, 한 가지 더... 말해줄 게 있어.",
  ui_story_9_1_1_200_dialog_content = "난 디바우러호가 백야성을 공격했던 구체적인 방법과 세 부품에 대한 이야기를...",
  ui_story_9_1_1_201_dialog_content = "백야성에 보고했어.",
  ui_story_9_1_1_202_dialog_content = "PlayerName, 부디 이해해 줬으면 좋겠어.",
  ui_story_9_1_1_203_dialog_content = "응... 괜찮아. 네 입장은 이해하니까.",
  ui_story_9_1_1_204_dialog_content = "세 부품... 설마...",
  ui_story_9_1_1_205_dialog_content = "PlayerName, 세 가지 부품 중에 「<color=#FFB400>싱크탱크 컴포넌트</color>」라는 게 있었잖아?",
  ui_story_9_1_1_206_dialog_content = "맞아. 멘델슨이 말했던 게 기억나...",
  ui_story_9_1_1_207_dialog_content = "「싱크탱크 컴포넌트」엔 수많은 정보가 저장되어 있다고 했어.",
  ui_story_9_1_1_208_dialog_content = "맞아! 나도 마침 그게 생각이 났거든!",
  ui_story_9_1_1_209_dialog_content = "...아, 그럼 「싱크탱크 컴포넌트」를 찾으면...\n의식 모듈을 고칠 방법을 찾을 수 있을지도 몰라!",
  ui_story_9_1_1_210_dialog_content = "응! PlayerName, 카렌, 그럼 이제...",
  ui_story_9_1_1_211_dialog_content = "헤븐즈 밸리로 가자!",
  ui_story_9_1_1_212_dialog_content = "<color=#e8d9bb>헤븐즈 밸리</color>",
  ui_story_9_1_1_213_dialog_content = "역시나. 네가 아무리 부정해도 네가 아이테르란 사실은 변하지 않아.",
  ui_story_9_1_1_214_dialog_content = "죽음을 앞두고 굳이 묘지로 변해버린 이 헤븐즈 밸리까지 도망쳐 온 걸 보라고.",
  ui_story_9_1_1_215_dialog_content = "......",
  ui_story_9_1_1_216_dialog_content = "말썽만 피우는 녀석.",
  ui_story_9_1_1_217_dialog_content = "내가 마지막 결과를 손에 넣기 전까지...",
  ui_story_9_1_1_218_dialog_content = "넌 아직 죽을 수 없어.",
  ui_story_9_1_1_219_dialog_content = "콜록... 콜록콜록...",
  ui_story_9_1_1_220_dialog_content = "드디어 깨어났구나.",
  ui_story_9_1_1_221_dialog_content = "크윽... 눈을 뜨자마자... 보이는 게 너라니... 정말... 화를 참을 수가... 없잖아.",
  ui_story_9_1_1_222_dialog_content = "무참히 당한 주제에 생명의 은인한테 화를 내려는 거야?",
  ui_story_9_1_1_223_dialog_content = "헛...소리... 콜록...",
  ui_story_9_1_1_224_dialog_content = "인정해, 슈모르. 넌 졌어. 그것도 아주 비참하게.",
  ui_story_9_1_1_225_dialog_content = "그딴... 개미 새끼들한테... 내가... 질 줄 알아...?",
  ui_story_9_1_1_226_dialog_content = "입은 아직도 살아있네. 네가 왜 졌는지 알아?",
  ui_story_9_1_1_227_dialog_content = "다...닥쳐... 크윽...",
  ui_story_9_1_1_228_dialog_content = "네가 충분히 강하지 않았기 때문이야.",
  ui_story_9_1_1_229_dialog_content = "듣기... 싫다고...",
  ui_story_9_1_1_230_dialog_content = "하지만 난 너한테 다시 기회를 줄 수 있어.",
  ui_story_9_1_1_231_dialog_content = "내가 실험을 마칠 수 있도록 도와준다면, 내가 가르쳐줄게.",
  ui_story_9_1_1_232_dialog_content = "진정한 강자가 어떤 건지 말이야.",
  ui_story_9_1_1_233_dialog_content = "...「씨앗」을... 더... 강화할 수 있다는 거야?",
  ui_story_9_1_1_234_dialog_content = "그래도 머리는 멀쩡한 모양이네.",
  ui_story_9_1_1_235_dialog_content = "콜록... 한 가지만 묻겠어...",
  ui_story_9_1_1_236_dialog_content = "정말 귀찮은 녀석이라니까.",
  ui_story_9_1_1_237_dialog_content = "왜 날... 도와주는 건데?",
  ui_story_9_1_1_238_dialog_content = "오해하지 마. 난 내 실험을 마치고 싶을 뿐이야.",
  ui_story_9_1_1_239_dialog_content = "......",
  ui_story_9_1_1_240_dialog_content = "넌 내 가장 귀중한 실험체인걸.",
  ui_story_9_1_1_241_dialog_content = "......",
  ui_story_9_1_1_242_dialog_content = "왜 날 도와주려는 건데?",
  ui_story_9_1_1_243_dialog_content = "나, 난... 저들이 틀렸다고 생각해...",
  ui_story_9_2_1_1_dialog_content = "...이 좌표는 디바우러호의 추락 지점. <color=#FFB400>헤븐즈 밸리</color>의 위치야.",
  ui_story_9_2_1_2_dialog_content = "여기가 바로...",
