  ui_story_9_2_1_5_dialog_content = "걱정하지 마, PlayerName. 우리가 있잖아.",
  ui_story_9_2_1_6_dialog_content = "PlayerName, 잊지 마. 네 곁엔 이제 「동료」들이 있다는 걸.",
  ui_story_9_2_1_7_dialog_content = "바이스, 카렌... 고마워...",
  ui_story_9_2_1_8_dialog_content = "PlayerName, 말했잖아. 우리 사이에 그렇게 예의 차릴 필요 없다니까.",
  ui_story_9_2_1_9_dialog_content = "그래도 정말 고마워.",
  ui_story_9_2_1_10_dialog_content = "너희가 곁에 있어 줘서 난 이 세상과 마주할 용기를 낼 수 있었어.",
  ui_story_9_2_1_11_dialog_content = "그렇게 말하면 나도 두 사람에게 고마워해야겠는걸.",
  ui_story_9_2_1_12_dialog_content = "너희 둘 덕분에 이 세상을 진정으로 이해할 수 있는 기회를 얻었으니까.",
  ui_story_9_2_1_13_dialog_content = "PlayerName, 카렌...",
  ui_story_9_2_1_14_dialog_content = "뭐, 우리 여정은 이제부터가 시작이니까!",
