  ui_story_9_2_1_16_dialog_content = "나도 자료를 조금 읽긴 했지만, 아마 우리보단 PlayerName 네가 더 잘 알고 있을 거라 생각해.",
  ui_story_9_2_1_17_dialog_content = "헤븐즈 밸리, 내 고향... 거긴 「사계절이 온화하고 항상 날씨가 좋은」 곳이었어...",
  ui_story_9_2_1_18_dialog_content = "스카이워커, 헤븐즈 밸리의 영상 자료를 재생해 줘.",
