  ui_story_9_2_1_23_dialog_content = "......",
  ui_story_9_2_1_24_dialog_content = "다시 재생해 줘, 스카이워커.",
  ui_story_9_2_1_25_dialog_content = "「헤븐즈 밸리」 재생 준비, 누적 재생 횟수 16회.",
  ui_story_9_2_1_26_dialog_content = "「헤븐즈 밸리는 세계의 등마루 남부에 위치한... 산으로 둘러싸인 비옥한 계곡입니다.」",
  ui_story_9_2_1_27_dialog_content = "「이곳은 사계절이 온화하고 항상 날씨가 좋으며...\n부지런하고 선한 아이테르들이 대를 이어 살아가고 있는 곳입니다.」",
  ui_story_9_2_1_28_dialog_content = "스카이워커, 이 복슬복슬한 건 뭐야?",
