  ui_story_9_2_1_30_dialog_content = "왜 잡을 수가 없는 거야?",
  ui_story_9_2_1_31_dialog_content = "PlayerName, 그건 그저 영상입니다.",
  ui_story_9_2_1_32_dialog_content = "마음에 드신다면 다시 재생해 드리겠습니다.",
