  ui_story_9_2_1_39_dialog_content = "도착했어.",
  ui_story_9_2_1_40_dialog_content = "여기가 바로... 헤븐즈 밸리?",
  ui_story_9_2_1_41_dialog_content = "전혀 달라...",
