  ui_story_9_2_1_43_dialog_content = "우리가 잘못 온 거 아냐?",
  ui_story_9_2_1_44_dialog_content = "좌표는 정확히 이곳을 가리키고 있어.",
  ui_story_9_2_1_45_dialog_content = "......",
  ui_story_9_2_1_46_dialog_content = "전부 말라버린 잡초들뿐인걸...",
  ui_story_9_2_1_47_dialog_content = "아, 잡초 밑에 하얀 돌들이 숨어있어.",
  ui_story_9_2_1_48_dialog_content = "이 돌들, 규칙적으로 놓여있어. 아마 집터의 흔적일 거야.",
