  ui_story_9_2_1_50_dialog_content = "아무래도 여긴 어느 정도 규모가 있었던 주거 지역이었던 것 같아.",
  ui_story_9_2_1_51_option_content = "[감응한다]",
  ui_story_9_2_1_52_dialog_content = "(텅 비어 있어...)",
  ui_story_9_2_1_53_dialog_content = "왜... 아무것도 느낄 수가 없는 거지...",
  ui_story_9_2_1_54_dialog_content = "PlayerName, 이미 오랜 시간이 흘렀어. 이 돌들조차 풍화돼서 모습이 변해버렸잖아.",
  ui_story_9_2_1_55_option_content = "[감응한다]",
  ui_story_9_2_1_56_dialog_content = "......",
  ui_story_9_2_1_57_dialog_content = "PlayerName, 조금 더 가 보자. 어쩌면...",
  ui_story_9_2_1_58_option_content = "[감응한다]",
  ui_story_9_2_1_59_dialog_content = "엣취!",
  ui_story_9_2_1_60_dialog_content = "조심해, 이 느낌... <color=#FFB400>다크매터</color>야!",
  ui_story_9_2_1_61_dialog_content = "설마 디바우러호가 근처에 있는 건가?",
  ui_story_9_2_1_62_dialog_content = "그건 아닌 것 같아... 여긴 다크매터의 기운이 무척 짙어. 게다가 다른 것들도 섞여 있어.",
  ui_story_9_2_1_63_dialog_content = "PlayerName, 괜찮아?",
  ui_story_9_2_1_64_dialog_content = "걱정 마. 지금 내 머릿속은 그 어느 때보다 뚜렷하니까.",
  ui_story_9_2_1_65_dialog_content = "카렌, 6시 방향!",
  ui_story_9_2_1_66_dialog_content = "크오오──!",
  ui_story_9_2_1_67_dialog_content = "흩어져라! 빙화여!",
  ui_story_9_2_1_68_dialog_content = "암귀 녀석들, 감히 PlayerName의 고향을 더럽혀?!",
  ui_story_9_2_1_69_dialog_content = "PlayerName, 그럼 지휘를 부탁할게!",
  ui_story_9_2_2_1_dialog_content = "<color=#e8d9bb>디바우러호 안</color>",
  ui_story_9_2_2_2_dialog_content = "누워.",
  ui_story_9_2_2_3_dialog_content = "이건... 「<color=#FFB400>리커버리 코쿤</color>」?",
  ui_story_9_2_2_4_dialog_content = "기분이 어때?",
  ui_story_9_2_2_5_dialog_content = "그럼 넌 이렇게 될 것까지 예상하고 있었다는 거야...? 콜록...",
  ui_story_9_2_2_6_dialog_content = "그래서 처음부터... 내 콜로서스에 이딴 장난감을 갖다둔 거였어...?",
  ui_story_9_2_2_7_dialog_content = "말을 좀 예쁘게 하지 그러니.",
  ui_story_9_2_2_8_dialog_content = "이건... 너무 역겹게 생겼잖아.",
  ui_story_9_2_2_9_dialog_content = "정말 구제 불능이네.",
  ui_story_9_2_2_10_dialog_content = "뭐야? 설마... 콜록... 네 귀중한 실험체를... 살려주지 않겠다는 거야?",
  ui_story_9_2_2_11_dialog_content = "말했잖아. 네가 아이테르에 대한 모든 걸 포기하기만 하면,\n넌 최고의 힘을 얻게 될 거라고.",
  ui_story_9_2_2_12_dialog_content = "나도 몇 번이나 말했을 텐데... 난 더는 아이테르가 아니라고.",
  ui_story_9_3_2_1_dialog_content = "야! 정말 이쪽 맞아?",
  ui_story_9_3_2_2_dialog_content = "레디젤 렌치에서 가장 믿음직한 남자가 앞장서는데, 당연히 맞지 않겠어?",
  ui_story_9_3_2_3_dialog_content = "뭐? 그럼 지금까지 길 안내를 한 게 너였어?!",
  ui_story_9_3_2_4_dialog_content = "이런 곳에서 폭탄을 발견하다니! 정말 운이 좋은걸! 아하하하!",
  ui_story_9_3_2_5_dialog_content = "어라, 이상하네. 이 폭탄... 내가 아까 버린 불발탄이잖아...",
  ui_story_9_3_2_6_dialog_content = "그럼... 우리 지금 계속 한 곳을 빙빙 돌고 있다는 거야?",
  ui_story_9_3_2_7_dialog_content = "무슨 소리야, 난 지도대로 가고 있다고!",
  ui_story_9_3_2_8_dialog_content = "렉커! 이 입만 산 바보 자식아! 지도가 거꾸로잖아!",
  ui_story_9_3_2_9_dialog_content = "...그럼 길을 안 잃는 게 이상하지.",
  ui_story_9_3_2_10_dialog_content = "<size=45>레에엑──커어어!</size>",
  ui_story_9_3_2_11_dialog_content = "지금 바로 네 머리를 해킹해서 어디 맛이 간 게 아닌지 뒤져봐야겠어!",
  ui_story_9_3_2_12_dialog_content = "걱정하지 마~ 바바라가 모두를 응원할게♪",
  ui_story_9_3_2_13_dialog_content = "<anim type=Shake>사랑이 있는 한 희망은 있으니까~♪</anim>",
  ui_story_9_3_2_14_dialog_content = "으아아아! 대장, 나 폭발할 것 같아! 쟤 좀 때려도 될까?!",
  ui_story_9_3_2_X14_dialog_content = "대장이 오늘은 사이좋게 지내라고 했어~\n그러니까 완벽한 바바라는 너랑 싸울 생각 없다구~",
  ui_story_9_3_2_X15_dialog_content = "한 마디만 더 지껄여 봐. 대장이 안 된다고 해도 내가...",
  ui_story_9_3_2_15_dialog_content = "어라? 대장은?",
  ui_story_9_3_2_16_dialog_content = "어이, 누구 대장 본 사람?",
  ui_story_9_3_2_17_dialog_content = "내 기세에 쫄아서 도망쳤겠지! 역시 언젠간 내가 일인자가 될 줄 알았다니까!",
  ui_story_9_3_2_18_dialog_content = "대장? 아까까지만 해도 있었는데!",
  ui_story_9_3_2_19_dialog_content = "사메야마 대장이 사라졌다고?!",
  ui_story_9_3_2_20_dialog_content = "아니지, 보프도 없어졌잖아...",
  ui_story_9_3_2_21_dialog_content = "부하들아, 이제 내 명령에 따라! 앞으로 전진!",
  ui_story_9_3_2_22_dialog_content = "렉커! 당장 이리 안 와?!",
  ui_story_9_3_2_23_dialog_content = "<size=45><anim type=Shake>&*#%#%...!</anim></size>",
  ui_story_9_3_2_24_dialog_content = "<color=#e8d9bb>콰당──! 탕──!</color>",
  ui_story_9_3_2_25_dialog_content = "으아아아아... 아파...!",
  ui_story_9_3_2_26_dialog_content = "어이! 어떤 빌어먹을 놈이 감히 날 함정에 빠트려?!",
  ui_story_9_3_2_27_dialog_content = "기습 공격이라니, 사나이가 할 짓이냐!",
  ui_story_9_3_2_28_dialog_content = "자신 있으면 당장 나와! 모조리 죽여주마!",
  ui_story_9_3_2_29_dialog_content = "방금 우리가 밟은 곳... 분명히 주변의 바닥이랑 다를 게 없어 보였어...",
  ui_story_9_3_2_30_dialog_content = "이건 얼핏 보기엔 인공적으로 파놓은 함정처럼 보이긴 하지만...",
  ui_story_9_3_2_31_dialog_content = "터널의 식생 환경을 분석해 보자면...",
  ui_story_9_3_2_32_dialog_content = "빨리 나와!",
  ui_story_9_3_2_33_dialog_content = "대장, 내 말 듣고 있어?",
  ui_story_9_3_2_34_dialog_content = "응? 뭐라고?",
  ui_story_9_3_2_35_dialog_content = "이건 함정이 아니라 그냥 자연적으로 생긴 구덩이야! 누가 우릴 기습한 것도 아니라고!",
  ui_story_9_3_2_36_dialog_content = "......",
  ui_story_9_3_2_37_dialog_content = "보프, 넌 방금 아무것도 못 들은 거다... 절대 내가 험한 말 했다고 이브한테 이르지 마!",
  ui_story_9_3_2_38_dialog_content = "대장이 내 말을 못 들은 척하지만 않는다면 말이지...",
  ui_story_9_3_2_39_dialog_content = "<anim type=Shake>부하들아, 이제 내 명령에 따라! 앞으로 전진!</anim>",
  ui_story_9_3_2_40_dialog_content = "<anim type=Shake>렉커! 당장 이리 안 와?!</anim>",
  ui_story_9_3_2_41_dialog_content = "아, 그래. 알겠다고.",
  ui_story_9_3_2_42_dialog_content = "함정이 아니라면 매복을 걱정할 필요도 없겠지. 그럼 얼른 나가자.",
  ui_story_9_3_2_X42_dialog_content = "레지나! 렉커! 내 말 들리냐!",
  ui_story_9_3_2_43_dialog_content = "낙하할 때 걸린 시간과 중력가속도를 분석해 보면...",
  ui_story_9_3_2_44_dialog_content = "우리가 여기서 목이 터져라 소리를 쳐도 저쪽에선 들리지 않을 거야.",
  ui_story_9_3_2_45_dialog_content = "레지나──!",
  ui_story_9_3_2_46_dialog_content = "대장! 이브한테 대장이 나쁜 말 했다고 이를 거야!",
  ui_story_9_3_2_47_dialog_content = "아, 아, 안 돼! 방금 뭐라고 했지? 시간이랑 속도가 어쨌다고?",
  ui_story_9_3_2_48_dialog_content = "음... 쉽게 말해서, 이 구덩이가 너무 깊어서 저쪽에선 우리 소리를 들을 수 없을 거야.",
  ui_story_9_3_2_49_dialog_content = "크흠, 그런 거냐...",
  ui_story_9_3_2_50_dialog_content = "역시 우리 「<color=#FFB400>트래블러호</color>」의 파일럿답다니까. 대단한 분석력이야!",
  ui_story_9_3_2_51_dialog_content = "좋아, 가자! 어디 이 구멍이 어디로 이어지는지 보자고.",
  ui_story_9_3_2_52_dialog_content = "<color=#e8d9bb>땡그랑── 철컹!</color>",
  ui_story_9_3_2_53_dialog_content = "대장, 이것 좀 봐. 여기 콜로서스의 부품이 잔뜩 있어!",
  ui_story_9_3_2_54_dialog_content = "우와! 이 동그란 머리... 이 귀여운 날개... 이 섬세한 솜씨...",
  ui_story_9_3_2_55_dialog_content = "이렇게 멋진 파이어플라이는 처음 봐... 「트래블러」가 분명히 좋아할 거야!",
  ui_story_9_3_2_56_dialog_content = "이 파이어플라이는 날개가 하나밖에 없잖아. 어디다 쓸 수 있는데? 공놀이?",
  ui_story_9_3_2_57_dialog_content = "저기도 잔뜩 있어! 이건 꼭 가지고 갈래! 그리고 저것도...",
  ui_story_9_3_2_58_dialog_content = "너무 많이 챙기진 마. 우리가 여기 온 이유를 잊지 말라고!",
  ui_story_9_3_2_59_dialog_content = "알고 있어. 하지만 「트래블러」한테 기념품을 주겠다고 약속했는걸...",
  ui_story_9_3_2_60_dialog_content = "그 추락한 검은 콜로서스를 찾고 나면 돈이 될 만한 것들이 더 많이 있을 거다.",
  ui_story_9_3_2_61_dialog_content = "아...",
  ui_story_9_3_2_62_dialog_content = "그나저나, 이 동굴엔 왜 콜로서스의 부품이 이렇게 많이 있는 거지?",
  ui_story_9_3_2_63_dialog_content = "설마...?",
  ui_story_9_3_2_64_dialog_content = "...?",
  ui_story_9_3_2_65_dialog_content = "가자! 얼른 출구를 찾아야 해.",
  ui_story_9_3_2_66_dialog_content = "아무래도 여긴 우리 말고도 다른 녀석들이 있어.",
  ui_story_9_4_1_1_dialog_content = "조심해! 누군가 있어!",
  ui_story_9_4_1_2_dialog_content = "꿰뚫어주마!",
  ui_story_9_4_1_3_dialog_content = "어이, 꼬마 아가씨, 비겁하게 기습을 하면 안 되지!",
  ui_story_9_4_1_4_dialog_content = "당신들은... 오로리안?",
  ui_story_9_4_1_5_dialog_content = "실력은 상당해 보이는데, 판단 능력은... 영 아니군그래!",
  ui_story_9_4_1_6_dialog_content = "뭐라고...?!",
  ui_story_9_4_1_7_dialog_content = "카렌, 무슨 일이야?",
  ui_story_9_4_1_8_dialog_content = "대장, 괜찮아?",
  ui_story_9_4_1_9_dialog_content = "아주 멀쩡해!",
  ui_story_9_4_1_10_dialog_content = "당신이었어?",
  ui_story_9_4_1_11_dialog_content = "PlayerName, 이 레디젤 렌치 사람을 알아?",
  ui_story_9_4_1_12_option_content = "전에 일루미나에서...",
  ui_story_9_4_1_13_dialog_content = "나랑 스카이워커가 지하에서 막 벗어났을 때, 실수로 일루미나 지하성 근처에 떨어졌거든.",
  ui_story_9_4_1_14_dialog_content = "그때 저 사람들이 그 틈에 우릴 약탈하려고 했었어.",
  ui_story_9_4_1_15_dialog_content = "어이, 이 자식, 무슨 말을 그렇게 해?\n그땐 암귀한테 습격당하는 걸 우리가 구해준 거였잖아. 안 그래?",
  ui_story_9_4_1_16_dialog_content = "그러다 나중엔 레디젤 사막에선 스카이워커가 분해당할 뻔했다니까.",
  ui_story_9_4_1_17_option_content = "전에 레디젤 사막에서...",
  ui_story_9_4_1_18_dialog_content = "우리가 레디젤 사막을 떠나려고 할 때 저 사람들이 우릴 가로막았어.",
  ui_story_9_4_1_19_dialog_content = "게다가 스카이워커가 조각조각 분해당할 뻔했다니까.",
  ui_story_9_4_1_20_dialog_content = "그렇게 말한다면 할 말이 없긴 하군. 그땐 확실히 내가 경솔했다.",
  ui_story_9_4_1_21_dialog_content = "그리고 네 덕분에 내 동생을 구한 것도 있고 말이야.",
  ui_story_9_4_1_22_dialog_content = "그러니 이 사메야마는 PlayerName 너한테 빚이 있다고 할 수 있겠지.",
  ui_story_9_4_1_23_dialog_content = "...너희 레디젤 사막도 가 봤던 거야?",
  ui_story_9_4_1_24_dialog_content = "저번에 우리가 백야성에서 나온 뒤의 일이야...",
  ui_story_9_4_1_25_dialog_content = "근데 이 백야성 「아가씨」는 계속 기세등등하단 말이지.",
  ui_story_9_4_1_26_dialog_content = "제대로 보지도 않고 밑도 끝도 없이 공격부터 해놓고 말이야.\n무고한 사람이 다쳤으면 어쩔 뻔했어?",
  ui_story_9_4_1_27_dialog_content = "사메야마, 카렌도 일부러 그런 건 아니야...",
  ui_story_9_4_1_28_dialog_content = "방금 공격은 확실히 내 착오였어.",
  ui_story_9_4_1_29_dialog_content = "방금 전 공격에 대해선 사과하겠어.",
  ui_story_9_4_1_30_dialog_content = "하지만 계속해서 백야성에 대해 무엄한 언행을 일삼는다면...",
  ui_story_9_4_1_31_dialog_content = "그간 레디젤 렌치의 문제를 당신한테 지금 바로 책임을 물을 수도 있어.",
  ui_story_9_4_1_X31_dialog_content = "싸움을 걸고 싶어도 때와 장소를 가려야 되지 않겠어?",
  ui_story_9_4_1_32_dialog_content = "이 친구 꽤나 개성적이네. PlayerName, 너흰 어쩌다 같이 다니게 된 거야?",
  ui_story_9_4_1_33_dialog_content = "저기... 두 사람이 전에 무슨 일이 있었는지는 모르겠지만...",
  ui_story_9_4_1_34_dialog_content = "두 사람 다 우리한텐 함께 싸운 동료야. 그러니까 서로 다투지 않았으면 좋겠어.",
  ui_story_9_4_1_35_dialog_content = "좋아. PlayerName 네가 그렇게까지 말한다면, 여기서 분위기를 깰 필요는 없겠지.",
  ui_story_9_4_1_36_dialog_content = "그건 내가 할 말이라고.",
  ui_story_9_4_1_X36_dialog_content = "잊지 마. 난 그저 다른 임무가 있어서 협력하는 거지, 너희랑 얽힐 시간 따윈 없어.",
  ui_story_9_4_1_X37_dialog_content = "하, 거 말 한번 참...",
  ui_story_9_4_1_37_dialog_content = "크흠, 저기! 다들 이러지 말고... 아, 맞다. 사메야마...",
  ui_story_9_4_1_38_option_content = "뒤에 있는 여자애는...",
  ui_story_9_4_1_39_dialog_content = "하하, 이쪽은 보프다.",
  ui_story_9_4_1_40_dialog_content = "안녕, 난 보프라고 해.",
  ui_story_9_4_1_41_dialog_content = "당신이 그 PlayerName 씨 맞지? 이브한테 얘기 많이 들었어!",
  ui_story_9_4_1_42_dialog_content = "우린 검은 콜로서스가 이 부근으로 추락하는 걸 보고 쫓아온 거다.",
  ui_story_9_4_1_43_dialog_content = "그러다 실수로 구덩이에 빠졌는데, 나와 보니 너희랑 마주친 거지.",
  ui_story_9_4_1_44_option_content = "근데 왜 여기 있는 거야?",
  ui_story_9_4_1_45_dialog_content = "그야 뻔한 거 아니겠어? 전리품을 챙기러 온 거지! 하하하!",
  ui_story_9_4_1_46_dialog_content = "전리품? 그게 무슨 말이야?",
  ui_story_9_4_1_47_dialog_content = "우린 검은 콜로서스가 이 부근으로 추락하는 걸 보고 쫓아온 거다.",
  ui_story_9_4_1_48_dialog_content = "그러다 나랑 보프는 실수로 구덩이에 빠졌는데, 나와 보니 너희랑 마주친 거지.",
  ui_story_9_4_1_49_dialog_content = "난 보프야. 당신이 바로 그 PlayerName 씨 맞지? 이브한테 얘기 많이 들었어!",
  ui_story_9_4_1_50_dialog_content = "PlayerName, 너희들도 「보물찾기」 중인 거냐?",
  ui_story_9_4_1_51_dialog_content = "그건... 말하자면 길어.",
  ui_story_9_4_1_52_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_9_4_1_53_dialog_content = "<size=45>헤븐즈 밸리?!</size>",
  ui_story_9_4_1_54_dialog_content = "여기가 정말 헤븐즈 밸리였다니...",
  ui_story_9_4_1_55_dialog_content = "그나저나 PlayerName, 넌 그 짧은 시간에 그렇게나 많은 일을 겪은 거였냐.",
  ui_story_9_4_1_56_dialog_content = "어쩔 수 없어. 이건 내가 지상으로 돌아와서 반드시 겪어야만 했던 시련일지도 몰라.",
  ui_story_9_4_1_57_dialog_content = "하지만 난... 그래도 「희망」을 버리지 않을 거야...",
  ui_story_9_4_1_58_dialog_content = "하하하하! 그렇다면 이 사메야마도 잠깐이지만 한몫 거들어 주마.",
  ui_story_9_4_1_59_dialog_content = "뭐?",
  ui_story_9_4_1_60_dialog_content = "뭐야, 불만 있어?",
  ui_story_9_4_1_61_dialog_content = "아, 아니. 얼마든지 환영이야!",
  ui_story_9_4_1_62_dialog_content = "앞으로 어떤 일이 있을지 모르니까, 전투력을 확보하는 건 올바른 선택이야.",
  ui_story_9_4_1_63_dialog_content = "두 아가씨가 반대하지 않는다면, 그렇게 하자고!",
  ui_story_9_4_1_64_dialog_content = "대장, 레지나 씨랑 일행들은 그럼 어떡하지?",
  ui_story_9_4_1_65_dialog_content = "아, 맞다. 혹시 오는 길에 다른 레디젤 렌치 사람들 못 봤어?",
  ui_story_9_4_1_66_dialog_content = "여기 다른 사람들도 온 거야?",
  ui_story_9_4_1_X66_dialog_content = "그래. 우리 레디젤 렌치는 다 같이 나들이하는 걸 좋아하거든.",
  ui_story_9_4_1_67_dialog_content = "아무도 못 봤어. 오는 동안 본 거라곤 암귀뿐이었어.",
  ui_story_9_4_1_X67_dialog_content = "그르르...",
  ui_story_9_4_1_68_dialog_content = "그래. 호랑이도 제 말하면 온다더니. 암귀가 나타났군.",
  ui_story_9_4_1_69_dialog_content = "PlayerName, 그럼 어디 네 지휘 능력이 얼마나 발전했는지 한번 보자고!",
  ui_story_9_4_2_1_dialog_content = "『주인님, 밖에 오로리안 무리가 접근하고 있습니다.』",
  ui_story_9_4_2_2_dialog_content = "『그들 중에는 아이테르도 있습니다.』",
  ui_story_9_4_2_3_dialog_content = "『하지만 저흰 병력이 부족해 저들을 막을 수가 없습니다.』",
  ui_story_9_4_2_4_dialog_content = "아이테르?",
  ui_story_9_4_2_5_dialog_content = "설마 지난번 그 PlayerName인가 하는 그 아이테르 녀석이려나.",
  ui_story_9_4_2_6_dialog_content = "아니야. 그 녀석은 지금쯤...",
  ui_story_9_4_2_7_dialog_content = "......",
  ui_story_9_4_2_8_dialog_content = "슈모르, 넌 정말 하나라도 일을 똑바로 하는 게 없구나.",
  ui_story_9_4_2_9_dialog_content = "『가서 그 백야성에서 잡아 온 병사들을 데리고 와.』",
  ui_story_9_4_2_10_dialog_content = "『네, 주인님.』",
  ui_story_9_4_2_11_dialog_content = "난 의외의 변수 같은 건 질색이라고.",
  ui_story_9_4_2_12_dialog_content = "실험 재료를 낭비하고 싶지도 않아.",
  ui_story_9_4_2_13_dialog_content = "게다가 무슨 일이 있어도 내 실험 계획을 방해하게 둘 순 없어.",
  ui_story_9_5_2_1_dialog_content = "<color=#e8d9bb>진리의 결사, 비밀 거점</color>",
  ui_story_9_5_2_2_dialog_content = "존경하는 빅토리아 님, 다른 분부는 없으신지요.",
  ui_story_9_5_2_3_dialog_content = "파우스트, 위대한 「진리의 주인」을 위해 더 많은 「<color=#FFB400>씨앗</color>」을 가지고 와 줘.",
  ui_story_9_5_2_4_dialog_content = "진리를 위해 봉사하는 것은 제 영광입니다. 빅토리아 님.",
  ui_story_9_5_2_5_dialog_content = "펙트와 나일즈, 두 사람도 데리고 가.",
  ui_story_9_5_2_6_dialog_content = "지시를 따르겠습니다, 빅토리아 님. 진리가 당신을 축복하길.",
  ui_story_9_5_2_7_dialog_content = "이게 바로 네가 말한 그 물건이야?",
  ui_story_9_5_2_8_dialog_content = "사람들을 두렵게 만들면서도 갈망하게 만드는, 어둠의 힘 말이지.",
  ui_story_9_5_2_9_dialog_content = "햇살이 비치는 대지 위에도, 역시나 진리의 가르침을 어기고\n「씨앗」의 힘을 추구하는 자들이 있었어.",
  ui_story_9_5_2_10_dialog_content = "그 가련한 자들은 이미 오로리안으로서의 「본성」을 포기했어.",
  ui_story_9_5_2_11_dialog_content = "정말 이걸 먹어버릴 생각이야?",
  ui_story_9_5_2_12_dialog_content = "아, 잠깐 깜빡했네. 넌 그냥 책이니까 「본성」이 뭔지도 모르겠구나.",
  ui_story_9_5_2_13_dialog_content = "「빅토리아 왈라키아.」",
  ui_story_9_5_2_X13_dialog_content = "「쓸데없는 말은 삼가라. 넌 그저 그걸 내게 올려두면 된다.」",
  ui_story_9_5_2_14_dialog_content = "그럼 어디 네가 이걸 소화시킬 수 있을지 볼까?",
  ui_story_9_5_2_15_dialog_content = "<color=#e8d9bb>콰직── 꿀꺽──</color>",
  ui_story_9_5_2_16_dialog_content = "맛이 어때?",
  ui_story_9_5_2_17_dialog_content = "「살과 피의 맛이 나는군.」",
  ui_story_9_5_2_18_dialog_content = "그 「씨앗」은 아이테르의 몸에서 꺼낸 거야.",
  ui_story_9_5_2_19_dialog_content = "「아이테르?」",
  ui_story_9_5_2_20_dialog_content = "왜, 이번엔 아이테르의 몸에 관심이 생기기 시작한 거야?",
  ui_story_9_5_2_21_dialog_content = "「빅토리아 왈라키아, 무엄하다!」",
  ui_story_9_5_2_22_dialog_content = "아무래도 흡수가 잘 된 모양이네.",
  ui_story_9_5_2_23_dialog_content = "「이건 시작일 뿐이다.」",
  ui_story_9_5_2_24_dialog_content = "그러게, 상황이 점점 더 재미있어지고 있잖아.",
  ui_story_9_5_2_25_dialog_content = "「우리가 맺은 계약을 잊지 마라.」",
  ui_story_9_5_2_26_dialog_content = "그걸 어떻게 잊겠어. 이미 「씨앗」을 더 찾으라고 사람을 보내뒀어.",
  ui_story_9_5_2_27_dialog_content = "「네가 처리해야 할 녀석들도 잊지 마라.」",
  ui_story_9_5_2_28_dialog_content = "너무 욕심내진 마.",
  ui_story_9_5_2_29_dialog_content = "우린 천천히 기회를 기다리면 되니까.",
  ui_story_9_5_2_30_dialog_content = "<color=#e8d9bb>헤븐즈 밸리 안</color>",
  ui_story_9_5_2_31_dialog_content = "잘하잖아, 애송이!",
  ui_story_9_5_2_32_dialog_content = "지휘 능력이 점점 더 좋아지는 것 같단 말이지!",
  ui_story_9_5_2_33_dialog_content = "고, 고마워...",
  ui_story_9_5_2_X33_dialog_content = "크윽, 쿨럭...",
  ui_story_9_5_2_34_dialog_content = "PlayerName, 왜 그래?",
  ui_story_9_5_2_35_option_content = "너무 추워...",
  ui_story_9_5_2_36_dialog_content = "자, 마셔라. 뜨거운 물이다.",
  ui_story_9_5_2_37_dialog_content = "사메야마 당신... 이렇게 세심한 사람이었어?",
  ui_story_9_5_2_38_dialog_content = "대장은 이브를 돌보려고 항상 보온병을 가지고 다니거든.",
  ui_story_9_5_2_39_dialog_content = "별거 아냐. 그저 습관일 뿐이지.",
  ui_story_9_5_2_40_option_content = "아무것도 아냐...",
  ui_story_9_5_2_41_dialog_content = "PlayerName, 손 이리 줘 봐.",
  ui_story_9_5_2_42_dialog_content = "뭐야, 손이 왜 이렇게 차가워?!",
  ui_story_9_5_2_43_dialog_content = "괜찮아, 바이스.",
  ui_story_9_5_2_44_dialog_content = "이상하군. 갈수록 온도가 내려가는 것 같은데 말이야.",
  ui_story_9_5_2_45_dialog_content = "전설 속 헤븐즈 밸리는 따뜻한 곳 아니었나...?",
  ui_story_9_5_2_46_dialog_content = "......",
  ui_story_9_5_2_47_dialog_content = "다크매터가 점점 더 강해지고 있어. 모두 정신 바짝 차려!",
  ui_story_9_5_2_48_dialog_content = "아무래도 헤븐즈 밸리는 이미 암귀 소굴이 되어버렸을지도 모르겠군.",
  ui_story_9_5_2_49_dialog_content = "...!",
  ui_story_9_5_2_50_dialog_content = "우리가 오면서 그렇게 많은 암귀와 마주친 것도...",
  ui_story_9_5_2_51_dialog_content = "그럼 디바우러호가 여기 추락한 것도 우연이 아닐지도 몰라.",
  ui_story_9_5_2_52_dialog_content = "설마...",
  ui_story_9_7_1_1_dialog_content = "캬악──!",
  ui_story_9_7_1_2_dialog_content = "벌레 같은 놈들, 끝도 없네!",
  ui_story_9_7_1_3_dialog_content = "유후~ 헤헤... 으흥흥♪",
  ui_story_9_7_1_4_dialog_content = "보프, 뭐 하는 거야...?",
  ui_story_9_7_1_5_dialog_content = "보물을 챙기는 중이야.",
  ui_story_9_7_1_6_dialog_content = "왜 여기까지 와서 쓰레기를 줍고 있어?",
  ui_story_9_7_1_7_dialog_content = "대장, 이건 쓰레기가 아냐!",
  ui_story_9_7_1_8_dialog_content = "이 근육 소재는 두께도 적당하고 튼튼한 데다가 내마모성도 있어. \n「트래블러」가 분명히 좋아할 거야!",
  ui_story_9_7_1_9_dialog_content = "그리고 이런 종류의 나사는 처음 본단 말이야.\n얼른 가져가서 타이니한테 보여줘야지!",
  ui_story_9_7_1_10_dialog_content = "게다가... 봐! 벌써 빨강, 노랑, 파랑, 초록색 파이어플라이를 모았다니까!",
  ui_story_9_7_1_11_dialog_content = "보프는 정말 대단하네.",
  ui_story_9_7_1_12_dialog_content = "나도 길가에 이렇게 좋은 것들이 잔뜩 있는 줄은 몰랐어!",
  ui_story_9_7_1_13_dialog_content = "아, 그리고...",
  ui_story_9_7_1_14_dialog_content = "PlayerName, 이것들...",
  ui_story_9_7_1_15_dialog_content = "이건 확실히 콜로서스의 부품이 맞아. 하지만 디바우러호에서 나온 건 아냐...",
  ui_story_9_7_1_16_dialog_content = "그럼 설마... 다른 콜로서스에서 떨어진 것들인가?",
  ui_story_9_7_1_17_dialog_content = "...17년 전 그날 밤...?",
  ui_story_9_7_1_18_dialog_content = "이 근육 소재들이 심하게 훼손된 걸 보면, 그때의 참상이 어땠는지 짐작할 수 있겠어.",
  ui_story_9_7_1_19_dialog_content = "......",
  ui_story_9_7_1_20_dialog_content = "미안... 난 그냥 여기 놔두는 게 아깝다고 생각돼서...",
  ui_story_9_7_1_21_dialog_content = "PlayerName 씨 기분을 상하게 만든다면 이것들은 그냥 놔둘게...",
  ui_story_9_7_1_22_dialog_content = "괜찮아, 보프.",
  ui_story_9_7_1_23_dialog_content = "이것들도 아마 자길 이해하고 소중히 여겨주는 동료를 기다리고 있었을 거야.",
  ui_story_9_7_1_24_dialog_content = "정말? 고마워! PlayerName 씨!",
  ui_story_9_7_1_25_dialog_content = "보프.",
  ui_story_9_7_1_26_dialog_content = "PlayerName 씨도 괜찮다고 했는데...",
  ui_story_9_7_1_27_dialog_content = "우린 앞으로 얼마나 더 가야 할지. 얼마나 더 많은 싸움을 해야 할지 아직 몰라.",
  ui_story_9_7_1_28_dialog_content = "이럴 때일수록 마음을 비우는 법도 배워야 하는 거다.",
  ui_story_9_7_1_29_dialog_content = "...알겠어.",
  ui_story_9_7_1_30_dialog_content = "그럼 이건 가져도 돼?",
  ui_story_9_7_1_31_dialog_content = "그런 작은 것들은 거치적거리지도 않을 테니까 챙겨!",
  ui_story_9_7_1_32_dialog_content = "...!",
  ui_story_9_7_1_33_dialog_content = "카렌, 저게 뭔지 알아?",
  ui_story_9_7_1_34_dialog_content = "그건 <color=#FFB400>백야성 경비병</color>의 휘장이야... 어째서 그게 여기 있는 거지?",
  ui_story_9_7_1_35_dialog_content = "보프, 그 휘장, 어디서 찾은 거야?",
  ui_story_9_7_1_36_dialog_content = "아마... 마지막으로 지났던 갈림길에서 주운 것 같아. 암귀한테 습격당한 그 갈림길 말이야!",
  ui_story_9_7_1_37_dialog_content = "내가 좀 볼 수 있을까?",
  ui_story_9_7_1_38_dialog_content = "자, 여기.",
  ui_story_9_7_1_39_option_content = "[감응한다]",
  ui_story_9_7_1_40_dialog_content = "마침내! 드디어 이 휘장을 달게 됐어!",
  ui_story_9_7_1_41_dialog_content = "어머니, 보이세요?",
  ui_story_9_7_1_42_dialog_content = "아들이 드디어 위풍당당한 백야성 경비병이 됐어요!",
  ui_story_9_7_1_43_dialog_content = "이제 더는 그 업타운의 늙어빠진 주인 나리들을 섬기지 않아도 된다구요!",
  ui_story_9_7_1_44_dialog_content = "하지만... 어머니는 이미 절 떠나셨죠...",
  ui_story_9_7_1_45_dialog_content = "신참! 뭘 멍하니 있는 거냐?! 어서 저 암귀들을 막아라!",
  ui_story_9_7_1_46_dialog_content = "...예!",
  ui_story_9_7_1_47_dialog_content = "크오오──!",
  ui_story_9_7_1_48_dialog_content = "어머니, 부디 절 지켜주세요!",
  ui_story_9_7_1_49_dialog_content = "여긴... 어디지...?",
  ui_story_9_7_1_50_dialog_content = "『주인님, 백야성에서 잡아 온 병사들입니다.』",
  ui_story_9_7_1_51_dialog_content = "『좋아.』",
  ui_story_9_7_1_52_dialog_content = "암귀?! 너희... 나한테 뭘 하려는 거냐?!",
  ui_story_9_7_1_53_dialog_content = "빨리 날 풀어줘!",
  ui_story_9_7_1_54_dialog_content = "두려워하지 마. 하나도 안 아플 테니까.",
  ui_story_9_7_1_55_dialog_content = "안 돼... 오지 마!",
  ui_story_9_7_1_56_dialog_content = "으아아악──!",
  ui_story_9_7_1_57_dialog_content = "...!",
  ui_story_9_7_1_58_dialog_content = "PlayerName, 뭐가 보였어?",
  ui_story_9_7_1_59_dialog_content = "방금...",
  ui_story_9_7_1_60_option_content = "경비병을 봤어...",
  ui_story_9_7_1_61_dialog_content = "이 휘장은 백야성 경비병이 가지고 있던 게 맞았어.",
  ui_story_9_7_1_62_dialog_content = "...!",
  ui_story_9_7_1_63_dialog_content = "그 사람은 이제 막 경비병이 됐는데, 암귀와의 전투에 참가하게 됐어.",
  ui_story_9_7_1_64_dialog_content = "하지만... 끝내 암귀가 되어버렸어.",
  ui_story_9_7_1_65_option_content = "암귀를 봤어...",
  ui_story_9_7_1_66_dialog_content = "이 휘장은 한 암귀가 가지고 있던 거야.",
  ui_story_9_7_1_67_dialog_content = "말도 안 돼!",
  ui_story_9_7_1_68_dialog_content = "하지만 그 암귀는... 원래 백야성의 경비병이었어.",
  ui_story_9_7_1_69_dialog_content = "그래서 암귀라는 거야, 경비병이라는 거야? 뭐가 뭔지 하나도 모르겠잖아.",
  ui_story_9_7_1_70_dialog_content = "이 경비병은 누군가가 강제로 암귀로 만든 거야...",
  ui_story_9_7_1_71_dialog_content = "이건 <color=#FFB400>노라</color>가 한 짓이 틀림없어!",
  ui_story_9_7_1_72_dialog_content = "슈모르 옆에 있던 그 정체불명의 여자 말이야?",
  ui_story_9_7_1_73_dialog_content = "맞아! 그리고 바이스 네가 나한테서 꺼낸 「씨앗」을 봤어.",
  ui_story_9_7_1_74_dialog_content = "아, 그거 때문에 너도 암귀가 될 뻔했었잖아!",
  ui_story_9_7_1_75_dialog_content = "허, 그런 일까지 있었단 말이야?",
  ui_story_9_7_1_76_dialog_content = "노라가... 그 「씨앗」을 경비병의 몸에 강제로 밀어 넣는 모습이 보였어!",
  ui_story_9_7_1_77_dialog_content = "...!",
  ui_story_9_7_1_78_dialog_content = "그때 하얀 상자를 든 남자가 그랬잖아.",
  ui_story_9_7_1_79_dialog_content = "바로 이 「씨앗」이 다른 생물을 암귀로 변하게 만드는 유일한 방법이라는 거지.",
  ui_story_9_7_1_80_dialog_content = "그러니까... 그 노라가 백야성의 경비병을 암귀로 만들었다는 거야?!",
  ui_story_9_7_1_81_dialog_content = "그래...",
  ui_story_9_7_1_82_dialog_content = "그럼 우리가 방금 죽인 암귀가... 사실은 백야성의 경비병이었던 거야...?",
  ui_story_9_7_1_83_dialog_content = "맞아...",
  ui_story_9_7_1_84_dialog_content = "......",
  ui_story_9_7_1_85_dialog_content = "이런 풋내기 자식들, 여기서 멍청하게 자기 탓이나 하고 있을 거냐!",
  ui_story_9_7_1_86_dialog_content = "경비병을 죽인 건 우리가 아니라 그 노라인가 뭔가 하는 녀석이잖아!",
  ui_story_9_7_1_87_dialog_content = "음... 어쩌면 사메야마 말도 맞다고 생각해.",
  ui_story_9_7_1_88_dialog_content = "비록 우리가... 직접 이 경비병을... 죽이긴 했지만.",
  ui_story_9_7_1_89_dialog_content = "그래도 노라가 아니었다면 이 경비병은 암귀가 되지 않았을 거야...",
  ui_story_9_7_1_90_dialog_content = "......",
  ui_story_9_7_1_91_dialog_content = "카렌 씨, 이 휘장...",
  ui_story_9_7_1_92_dialog_content = "아무래도 카렌 씨한테 주는 게 맞을 것 같아.",
  ui_story_9_7_1_93_dialog_content = "...좋아.",
  ui_story_9_7_1_94_dialog_content = "나 카렌 드 솔라드는 이곳에서 사자를 위해 애도한다.",
  ui_story_9_7_1_95_dialog_content = "이 휘장의 소유자, 백야성의 경비병은...",
  ui_story_9_7_1_96_dialog_content = "자신의 직무에 최선을 다하여 용감히 적과 맞서 싸웠다.",
  ui_story_9_7_1_97_dialog_content = "비록 적의 손에 넘어가 암귀가 되어, 이성을 잃고 오로리안을 공격했으나,\n이는 그의 의도에서 비롯된 것은 아니다.",
  ui_story_9_7_1_98_dialog_content = "우린 그의 고통을 우리의 손으로 끝냈다. 그가 우릴 용서하길.",
  ui_story_9_7_1_99_dialog_content = "부디 이곳에서 안식하기를. 만물은 백야 아래에.",
  ui_story_9_7_1_100_dialog_content = "편히 쉬길 바랄게...",
  ui_story_9_7_1_101_dialog_content = "......",
  ui_story_9_7_1_102_dialog_content = "디바우러호, 헤븐즈 밸리, 노라... 모든 게 너무 이상해.",
  ui_story_9_7_1_103_dialog_content = "...뭔가 불길한 예감이 들어.",
  ui_story_9_7_1_104_dialog_content = "슈모르...",
  ui_story_9_7_1_105_dialog_content = "역시 슈모르가 아직 살아있는 게 아닐까?!",
  ui_story_9_7_1_106_dialog_content = "...!",
  ui_story_9_7_1_107_dialog_content = "어쨌든 서둘러야 해!",
  ui_story_9_7_1_108_dialog_content = "크오오──!",
  ui_story_9_7_1_109_dialog_content = "또 목숨 아까운 줄 모르는 녀석이 나타났군! 다들 조심해!",
  ui_story_9_7_1_110_dialog_content = "고위 암귀인가?",
  ui_story_9_7_1_111_dialog_content = "저렇게 몸이 부서진 암귀는... 처음 보는 것 같아.",
  ui_story_9_7_1_112_dialog_content = "<anim type=Shake>가고... 집...... 에...</anim>",
  ui_story_9_7_1_113_dialog_content = "<anim type=Shake>...싶... 어...... 집...</anim>",
  ui_story_9_7_1_114_dialog_content = "지금 통용어를 말한 거야?",
  ui_story_9_7_1_115_dialog_content = "난 왜 전혀 이해가 안 되지...",
  ui_story_9_7_1_116_dialog_content = "몸에서... 오로리안의 기운이 느껴져...",
  ui_story_9_7_1_117_dialog_content = "그럼 이 녀석도 오로리안이 변한 거란 말이냐?",
  ui_story_9_7_1_118_dialog_content = "...!",
  ui_story_9_7_1_119_dialog_content = "틀림없어. 강렬한 감정이 감응으로 느껴져.",
  ui_story_9_7_1_120_dialog_content = "고통, 절망, 무력감, 분노... 출구를 찾을 수 없는 급류처럼 감정을 발산하고 있어...",
  ui_story_9_7_1_121_dialog_content = "이 불쌍한 「오로리안」은... 그저 집에 가고 싶어하고 있어...",
  ui_story_9_7_1_122_dialog_content = "......",
  ui_story_9_7_1_123_dialog_content = "<anim type=Shake>크오오──!</anim>",
  ui_story_9_7_1_124_dialog_content = "아무래도 이 녀석, 자기가 암귀가 됐다는 걸 모르는 모양이야. 저래서는 집에도 갈 수 없을 거라고...",
  ui_story_9_7_1_125_dialog_content = "녀석이 더 큰 고통을 느끼기 전에 눈을 감겨주는 수밖에 없겠어!",
  ui_story_9_7_2_1_dialog_content = "<anim type=Shake>...집...에...... 갈...래...... 집...</anim>",
  ui_story_9_7_2_2_dialog_content = "만물은 백야 아래에. 부디 이곳에서 안식하기를.",
  ui_story_9_7_2_3_dialog_content = "부디... 고통에서 해방되길 바랄게...",
  ui_story_9_7_2_4_dialog_content = "미안해, 널 구하지 못해서... 정말 미안해...",
  ui_story_9_7_2_5_dialog_content = "방금 전투에서 우린 더 많은 고통을 주지 않으려고 노력했잖아. 이미 최선을 다했다고 생각해...",
  ui_story_9_7_2_6_dialog_content = "PlayerName, 너무 자책하지 마.",
  ui_story_9_7_2_X6_dialog_content = "지금 우리가 이 오로리안들을 위해서 할 수 있는 유일한 일은 노라를 찾아서 막는 것뿐이야.",
  ui_story_9_7_2_7_dialog_content = "...응!",
  ui_story_9_7_2_8_dialog_content = "그 말이 맞아... 어서 노라를 찾아서 암귀를 만들어내는 걸 막아야 해!",
  ui_story_9_7_2_9_dialog_content = "그 노라란 자는 대체 어떤 녀석이지? 설마 오로리안이냐?",
  ui_story_9_7_2_10_option_content = "맞아.",
  ui_story_9_7_2_11_dialog_content = "체형이나 느껴지는 기운, 말하는 방식까지... 노라는 암귀보다는 오로리안에 더 가까워 보였어.",
  ui_story_9_7_2_12_dialog_content = "하지만 그 녀석은 암귀 편이야.",
  ui_story_9_7_2_13_dialog_content = "게다가... 비비안 씨 말로는 노라가 한때 일루미나의 일원이었다고 했어...",
  ui_story_9_7_2_14_option_content = "아니야.",
  ui_story_9_7_2_15_dialog_content = "비록 전에는 오로리안이었을지 몰라도, 지금은 우릴 위협하는 암귀일 뿐이야.",
  ui_story_9_7_2_16_dialog_content = "하지만... 비비안 씨 말로는 노라가 한때 일루미나의 일원이었다고 했어...",
  ui_story_9_7_2_17_dialog_content = "비비안?",
  ui_story_9_7_2_18_dialog_content = "일루미나의 참모장님이야. 내 상관인 분이시고.",
  ui_story_9_7_2_19_dialog_content = "우리가 출발하기 전에 비비안 님은 우리한테 노라를 특히 조심하라고 하셨어...",
  ui_story_9_7_2_20_dialog_content = "정말 말이 씨가 된 모양이네.",
  ui_story_9_7_2_21_dialog_content = "하지만 모르겠어... 노라가 한때 정말 일루미나의 동료였던 걸까...?",
  ui_story_9_7_2_22_dialog_content = "그런데 어떻게 이런 잔인한 짓들을 할 수 있는 거지?",
  ui_story_9_7_2_23_dialog_content = "마치 오로리안을 암귀로 만드는 실험에 집착하고 있는 것 같잖아.",
  ui_story_9_7_2_24_dialog_content = "내가 일루미나에 있을 땐 거기 그런 사람이 있다는 건 들어본 적 없단 말이야...",
  ui_story_9_7_2_25_dialog_content = "그런 떳떳하지 않은 짓을 일루미나의 고위층이 너희 같은 부하들한테 말해줄 리가 없다고.",
  ui_story_9_7_2_26_dialog_content = "사메야마, 난 당신이 이브의 일 때문에 일루미나를 믿지 않는다는 건 알아.",
  ui_story_9_7_2_27_dialog_content = "하지만 일루미나의 고위 장교들은 모두 솔선수범하는 모범적인 분들이야...",
  ui_story_9_7_2_X27_dialog_content = "어쩌면 지금도 따로 이 일에 대해 조사를 하고 계실지도 몰라...",
  ui_story_9_7_2_28_dialog_content = "하하하하하. 그런 말도 안 되는 소릴 믿다니. 역시 너흰 너무 순진하다니까.",
  ui_story_9_7_2_29_dialog_content = "오래전... 내 동생 이브는 암귀의 습격을 받아 심각한 후유증을 얻었었다.",
  ui_story_9_7_2_30_dialog_content = "그리고 그때 난 이브를 치료해 주겠다는 일루미나의 번지르르한 말을 믿어버렸지.",
  ui_story_9_7_2_31_dialog_content = "......",
  ui_story_9_7_2_32_dialog_content = "그리고 어떻게 됐냐고?! 이브의 상태는 전혀 좋아지지도 않았고,\n자칫하면 일루미나에서 일어난 대화재 때 죽을 뻔했단 말이다!",
  ui_story_9_7_2_33_dialog_content = "대화재라면...",
  ui_story_9_7_2_34_dialog_content = "...!",
  ui_story_9_7_2_35_dialog_content = "...그렇구나. 진작에 눈치챘어야 했어...\n노라의 얼굴에도... 불에 덴 흉터가 있었잖아...",
  ui_story_9_7_2_36_dialog_content = "뭐라고?!",
  ui_story_9_7_2_37_dialog_content = "일루미나의 대화재...",
  ui_story_9_7_2_38_dialog_content = "아아아아악!",
  ui_story_9_7_2_39_dialog_content = "노라의 흉터...",
  ui_story_9_7_2_40_dialog_content = "내 얼굴, 이 흉터를 봐... 이건 불에 뎄던 흔적이야. 보여?",
  ui_story_9_7_2_41_dialog_content = "설마...",
  ui_story_9_7_2_42_dialog_content = "사메야마, 하나만 더 물어볼게. 그럼 그때 이브의 치료를 담당했던 연구원이 어디로 갔는지 알아?",
  ui_story_9_7_2_43_dialog_content = "내가 일루미나로 찾아갔을 때, 그들은 사람을 보내서 내게 말했지...",
  ui_story_9_7_2_44_dialog_content = "그 지하성에서 실험을 담당했던 사람은 이미 대화재 때 사망했다고 말이야.",
  ui_story_9_7_2_45_dialog_content = "그게 진짜야?",
  ui_story_9_7_2_46_dialog_content = "물론 난 책임을 피하려는 일루미나의 변명 따윈 믿지 않았다.",
  ui_story_9_7_2_47_dialog_content = "게다가 놈들은 그 연구원의 이름을 언급하는 걸 계속 억지로 피했었지.",
  ui_story_9_7_2_48_dialog_content = "그래서 난 부하를 보내 비밀리에 조사를 시작했다.",
  ui_story_9_7_2_49_dialog_content = "하지만 조사 결과는... 별반 다를 게 없었다.",
  ui_story_9_7_2_50_dialog_content = "그래도 그 녀석의 이름... 「<color=#FFB400>드니에르</color>」... 난 평생 잊지 않을 거다.",
  ui_story_9_7_2_X50_dialog_content = "우린 전에 얻은 정보 때문에 잘못 판단하고 있었어.\n전부 그 연구원이 대화재 때 죽었다고 생각한 거지.",
  ui_story_9_7_2_51_dialog_content = "그래서 내가 노라를 처음 봤을 때도 알아보지 못했던 거야!",
  ui_story_9_7_2_52_dialog_content = "맞아. 지금 생각해보면 노라가 바로 그 드니에르일 가능성이 커.",
  ui_story_9_7_2_53_dialog_content = "...!",
  ui_story_9_7_2_54_dialog_content = "아...!",
  ui_story_9_7_2_55_dialog_content = "이브...",
  ui_story_9_7_2_56_dialog_content = "제길! 반드시 그 노라란 녀석을 찾아서 진상을 제대로 듣고 말겠어!",
  ui_story_9_7_2_57_dialog_content = "만약 그 녀석이 정말로 이브한테 무슨 짓을 한 거라면, 절대 용서하지 않을 거다!",
  ui_story_9_8_1_1_dialog_content = "<color=#e8d9bb>디바우러호, 리커버리 코쿤 속</color>",
  ui_story_9_8_1_2_dialog_content = "선생님...",
  ui_story_9_8_1_3_dialog_content = "죄송해요... 선생님... 다시...",
  ui_story_9_8_1_4_dialog_content = "어째서...",
  ui_story_9_8_1_5_dialog_content = "<color=#e8d9bb>헤븐즈 밸리, 콜로서스 교육 선착장</color>",
  ui_story_9_8_1_6_dialog_content = "한드로 선생님, 죄송해요! 한 번만 더 기회를 주실 순 없나요?",
  ui_story_9_8_1_7_dialog_content = "슈모르, 넌 세 번의 기회를 이미 다 사용했다.",
  ui_story_9_8_1_8_dialog_content = "안타깝지만 넌 이번 「콜로서스 조종 실습」 시험을 통과하지 못했다.",
  ui_story_9_8_1_9_dialog_content = "하...하지만... 이번에 못 통과하면 전 「디바우러호」의 조종사 선발에 참여할 수 없단 말이에요...",
  ui_story_9_8_1_10_dialog_content = "전 이번 시험을 반드시 통과해야 해요!",
  ui_story_9_8_1_11_dialog_content = "슈모르, 네 마음은 나도 이해한다.",
  ui_story_9_8_1_12_dialog_content = "넌 내가 가장 자랑스러워하는 학생 중 하나란다. 물론 나도 네가 선발에 참여할 수 있길 바란다.",
  ui_story_9_8_1_13_dialog_content = "하지만 시험과 선발은 반드시 공정하고 공평해야만 한다.",
  ui_story_9_8_1_14_dialog_content = "한드로 선생님, 이제 준비됐어요! 시험은 언제 시작되나요?",
  ui_story_9_8_1_15_dialog_content = "알았다. 바로 가마.",
  ui_story_9_8_1_16_dialog_content = "슈모르, 네가 그토록 노력하는 모습을 보니 선생님은 무척 기쁘단다.",
  ui_story_9_8_1_17_dialog_content = "선생님은 네가 계속해서 자신을 단련한다면, 분명히 감응 능력도 더 강해질 거라고 믿는다.",
  ui_story_9_8_1_18_dialog_content = "그럼 다음 선발 때 너도 반드시 「디바우러호」의 조종사가 될 수 있을 거다. 알겠니?",
  ui_story_9_8_1_19_dialog_content = "하지만... 다음이라고 해도 언제가 될지 모르잖아요...",
  ui_story_9_8_1_20_dialog_content = "......",
  ui_story_9_8_1_21_dialog_content = "너한테 그런 날이 또 올 것 같아? 지난번 선발도 몇십 년 전이었잖니!",
  ui_story_9_8_1_X1_dialog_content = "(시끄러워. 평소엔 날 없는 사람 취급하더니, 내가 선발에 참여한다고 하니까 떠들어대기는.)",
  ui_story_9_8_1_X2_dialog_content = "슈모르, 비록 넌 이전 테스트에서는 1등을 차지했지만...",
  ui_story_9_8_1_X3_dialog_content = "그것만으로 자만해선 안 된다. 콜로서스와 감응하는 건 평소의 테스트와 다르니, 더 노력해야 한다.",
  ui_story_9_8_1_X4_dialog_content = "(알고 있어. 쓸데없이 강조할 거 없다고.)",
  ui_story_9_8_1_22_dialog_content = "슈모르, 넌 매번 시험마다 1등만 하던 모범생 아니었어?",
  ui_story_9_8_1_23_dialog_content = "근데 오히려 콜로서스 조종 같은 간단한 일은 왜 못 하는 거야?",
  ui_story_9_8_1_X5_dialog_content = "(난 해낼 거야. 똑똑히 봐.)",
  ui_story_9_8_1_X6_dialog_content = "지금 중요한 건 콜로서스와 감응을 못 하는 사람이 있다는 거야! 슈모르, 너 정말 아이테르 맞아?",
  ui_story_9_8_1_X7_dialog_content = "(닥쳐, 고작 감응 좀 할 수 있는 녀석이 뭘 우쭐대고 있어.)",
  ui_story_9_8_1_24_dialog_content = "슈모르가 조종 시험에 떨어졌다고? 말도 안 돼...",
  ui_story_9_8_1_X8_dialog_content = "(고작 시험일 뿐이라고. 다음엔 반드시...)",
  ui_story_9_8_1_X9_dialog_content = "네가 디바우러호의 조종사로 적합하다고 한드로가 그랬다고?",
  ui_story_9_8_1_X10_dialog_content = "휴... 그냥 미리 포기하지 그러냐. 그게 너한테도 좋을 거다.",
  ui_story_9_8_1_X11_dialog_content = "넌 그럴 재능도 없고, 그럴 자격도 없으니까...",
  ui_story_9_8_1_X12_dialog_content = "(닥쳐! 너흰 다 멍청이들이야. 아무것도 모른다고!)",
  ui_story_9_8_1_X13_dialog_content = "(언젠가는... 반드시 증명해내겠어!)",
  ui_story_9_8_1_X14_dialog_content = "......",
  ui_story_9_8_1_25_dialog_content = "지금 중요한 건 콜로서스와 감응을 못 하는 사람이 있다는 거야! 슈모르, 너 정말 아이테르 맞아?",
  ui_story_9_8_1_26_dialog_content = "너...너희...",
  ui_story_9_8_1_27_dialog_content = "쳇, 누군가 했네. 「겁쟁이」 멘델슨이잖아?",
  ui_story_9_8_1_28_dialog_content = "할 말 있으면 어디 해 봐!",
  ui_story_9_8_1_29_dialog_content = "너희... 그만해...",
  ui_story_9_8_1_30_dialog_content = "우리가 왜? 네가 하지 말라고 하면 그만해야 돼?",
  ui_story_9_8_1_31_dialog_content = "하, 한드로 선생님...",
  ui_story_9_8_1_32_dialog_content = "뭐? 선생님이 어쨌다고?",
  ui_story_9_8_1_33_dialog_content = "선생님한테... 말할 거야...",
  ui_story_9_8_1_34_dialog_content = "한드로 선생님한테 말할 거라고? 흥, 선생님만 믿는다고 네가 뭘 할 수 있는데?",
  ui_story_9_8_1_35_dialog_content = "자, 자, 다들 그만해...",
  ui_story_9_8_1_36_dialog_content = "흥, 가자!",
  ui_story_9_8_1_X15_dialog_content = "너, 너희... 한 번만 더 그러면... 지, 진짜로 한드로 선생님한테 다 말할 거야.",
  ui_story_9_8_1_37_dialog_content = "괘...괜찮아?",
  ui_story_9_8_1_38_dialog_content = "넌 또 누구야? 내가 안 괜찮을 건 뭔데? 네가 참견할 거 없다고.",
  ui_story_9_8_1_39_dialog_content = "나, 난 멘델슨이라고 해... 쟤들이 너도 괴롭히는 것 같아서...",
  ui_story_9_8_1_X16_dialog_content = "그래서... 조금 걱정이 돼서...",
  ui_story_9_8_1_X17_dialog_content = "그러니까, 내가 괴롭힘당하는 걸 보고 몇 마디 해주러 왔다 이거야?",
  ui_story_9_8_1_40_dialog_content = "넌 그냥 자기만족을 위해서 그러는 것뿐이잖아.\n그렇게 남을 동정하면 네가 뭐 대단한 사람이라도 되는 것 같아?",
  ui_story_9_8_1_X18_dialog_content = "너도 결국 똑같은 녀석이잖아?",
  ui_story_9_8_1_X19_dialog_content = "기분 좋을 땐 와서 빈말이나 몇 마디 하고, 기분 나쁘면 와서 비웃을 거잖아?",
  ui_story_9_8_1_41_dialog_content = "그, 그런 거 아냐...",
  ui_story_9_8_1_X20_dialog_content = "아냐? 그럼 뭔데?",
  ui_story_9_8_1_42_dialog_content = "왜 날 도와주려는 건데?",
  ui_story_9_8_1_43_dialog_content = "나, 난... 저들이 틀렸다고 생각해...",
  ui_story_9_8_1_44_dialog_content = "(당연히 틀렸지...)",
  ui_story_9_8_1_45_dialog_content = "(자기만 잘난 줄 아는 녀석들...)",
  ui_story_9_8_1_46_dialog_content = "슈모르, 왜 혼자 여기 있어?",
  ui_story_9_8_1_47_dialog_content = "...!",
  ui_story_9_8_1_48_dialog_content = "하, 「콜로서스도 조종할 줄 모르는」 슈모르잖아?",
  ui_story_9_8_1_49_dialog_content = "콜로서스와 감응하는 방법을 배우려고 온 거야? 정말 고생이네.",
  ui_story_9_8_1_50_dialog_content = "다들 괜히 방해하지 말고 얼른 가자...",
  ui_story_9_8_1_51_dialog_content = "잠깐만, 방금 좋은 생각이 떠올랐거든.",
  ui_story_9_8_1_52_dialog_content = "우리 내기 하나 할래?",
  ui_story_9_8_1_53_dialog_content = "무슨 내기?",
  ui_story_9_8_1_54_dialog_content = "슈모르, 너 우리랑 헤븐즈 밸리 밖으로 나가볼래?",
  ui_story_9_8_1_X21_dialog_content = "뭐? 그건 저번에 우리가 계획했던 거잖아...",
  ui_story_9_8_1_X22_dialog_content = "하하, 슈모르 좀 봐. 고개도 못 들고 있잖아. 겁먹은 모양이야.",
  ui_story_9_8_1_55_dialog_content = "일단 할지 말지부터 말해. 설마 그럴 배짱도 없나?",
  ui_story_9_8_1_56_dialog_content = "못 할 줄 알고!",
  ui_story_9_8_1_57_dialog_content = "너흰 콜로서스랑 감응할 순 있겠지... 근데 콜로서스를 타고 헤븐즈 밸리 밖으로 나갈 순 있겠어?",
  ui_story_9_8_1_58_dialog_content = "하지만 내가 저번에도 말했잖아...\n한드로 선생님은 바깥엔 암귀가 있을지도 모르니까 위험하다고 하셨어.",
  ui_story_9_8_1_59_dialog_content = "뭐야, 무서워?",
  ui_story_9_8_1_60_dialog_content = "뭐가 무서워? 콜로서스를 타고 갔다 오면 그만인데.",
  ui_story_9_8_1_61_dialog_content = "너희가 콜로서스를 타고 바깥을 한 바퀴 돌고 올 수 있다면 너희가 이긴 거야.",
  ui_story_9_8_1_62_dialog_content = "그럼 우리가 갔다 오면 어디 두고 봐!",
  ui_story_9_8_1_63_dialog_content = "대신 콜로서스는... 「견습 1호」를 쓸 거야!",
  ui_story_9_8_1_64_dialog_content = "정말 안 들킬 수 있을까?",
  ui_story_9_8_1_65_dialog_content = "걱정할 거 없어. 넌 「디바우러호」의 차기 조종사잖아. 한드로 선생님한테 인정받은 승리자라고!",
  ui_story_9_8_1_66_dialog_content = "...!",
  ui_story_9_8_1_67_dialog_content = "응, 우린 네 능력을 믿어!",
  ui_story_9_8_1_68_dialog_content = "혹시라도 들켜봤자... 누가 너한테 뭐라고 할 수 있겠어?",
  ui_story_9_8_1_69_dialog_content = "알았어... 그럼 딱 이번 한 번만이야!",
  ui_story_9_8_1_70_dialog_content = "오오! 이륙한다!",
  ui_story_9_8_1_X23_dialog_content = "슈모르, 너도 갈 수 있겠어?",
  ui_story_9_8_1_X24_dialog_content = "난 못 한다에 한 표! 책 세 권을 걸게!",
  ui_story_9_8_1_71_dialog_content = "(디바우러호는... 내 거라고...)",
  ui_story_9_8_1_72_dialog_content = "(너흰 아무것도 몰라... 그러니까...)",
  ui_story_9_8_1_73_dialog_content = "<color=#e8d9bb>헤븐즈 밸리 밖</color>",
  ui_story_9_8_1_74_dialog_content = "콜로서스를... 가동할 수가 없어!",
  ui_story_9_8_1_75_dialog_content = "......",
  ui_story_9_8_1_76_dialog_content = "암귀다! 암귀가 문을 부수고 있어...!",
  ui_story_9_8_1_77_dialog_content = "어...어떡하지?!",
  ui_story_9_8_1_78_dialog_content = "크크크크...",
  ui_story_9_8_1_79_dialog_content = "사냥감이 제 발로 찾아올 줄이야.",
  ui_story_9_8_1_X25_dialog_content = "(너흰 이제 다 죽었어.)",
  ui_story_9_8_1_80_dialog_content = "싸...싸우자!",
  ui_story_9_8_1_81_dialog_content = "으아아아악!",
  ui_story_9_8_1_82_dialog_content = "하늘 무서운 줄 모르는 짐승들, 조금이라도 더 살 수 있었는데 말이야.",
  ui_story_9_8_1_83_dialog_content = "으윽...",
  ui_story_9_8_1_84_dialog_content = "아...",
  ui_story_9_8_1_85_dialog_content = "겨우 이 정도인 것이냐?",
  ui_story_9_8_1_86_dialog_content = "그저 좀 선별해보려던 것뿐인데, 이렇게 쉽게 죽어버리다니, 정말 골치가 아프군.",
  ui_story_9_8_1_87_dialog_content = "......",
  ui_story_9_8_1_88_dialog_content = "이렇게 약해서야. 살짝 쥐었을 뿐인데 뼈가 부러졌잖아.",
  ui_story_9_8_1_89_dialog_content = "너희의 뼈를 갈아서 목걸이로 만들어, 매일 몸에 지니고 감상할 생각이었는데 말이야.",
  ui_story_9_8_1_90_dialog_content = "......",
  ui_story_9_8_1_91_dialog_content = "(도망쳐야 해... 어디로... 가야 하지...)",
  ui_story_9_8_1_X91_dialog_content = "그르르...",
  ui_story_9_8_1_92_dialog_content = "음? 새끼 한 마리가 더 숨어 있다고?",
  ui_story_9_8_1_X92_dialog_content = "크크크, 재미있군.",
  ui_story_9_8_1_X26_dialog_content = "(...!)",
  ui_story_9_8_1_S1_dialog_content = "가까이 오지 마!",
  ui_story_9_8_1_X27_dialog_content = "조용히 해라... 네게 좋은 소식이 하나 있으니 말이야.",
  ui_story_9_8_1_X28_dialog_content = "듣고 싶으냐?",
  ui_story_9_8_1_X29_dialog_content = "...아, 암귀가 통용어를 할 수 있다고?",
  ui_story_9_8_1_S2_dialog_content = "크크크, 이런 상황에서 그런 생각부터 들다니, 내가 널 죽일지도 모르는 게 무섭지 않은 게냐?",
  ui_story_9_8_1_S3_dialog_content = "...무서워요.",
  ui_story_9_8_1_X30_dialog_content = "크하하하! 그럼 한 글자도 놓치지 말고 똑바로 잘 들어라.",
  ui_story_9_8_1_93_dialog_content = "위대한 어머니께서 그분의 뜻을 우리에게 주셨으니,\n아이테르는 종말의 날에 영원한 소멸을 맞이할 것이다.",
  ui_story_9_8_1_94_dialog_content = "이것은 아이테르에 내리는 최후의 심판이요. 어머니께서 아이테르에게 베푸는 행복의 결말이다!",
  ui_story_9_8_1_95_dialog_content = "그러니 기뻐하거라! 너희는 이 역사적인 순간을 목도할 증언자들이니!",
  ui_story_9_8_1_96_dialog_content = "...뭐, 뭐라구요?!",
  ui_story_9_8_1_97_dialog_content = "넌 질문할 자격이 없다!",
  ui_story_9_8_1_98_dialog_content = "약자에겐 그저 죽음만이 있을 뿐!",
  ui_story_9_8_1_99_dialog_content = "네 저 친구들처럼 말이지. 한 덩어리로 뭉개져 고통 속에 죽는 거다.",
  ui_story_9_8_1_100_dialog_content = "...!",
  ui_story_9_8_1_101_dialog_content = "크크크, 뭐, 괜찮다. 난 널 선택했고, 네게 기회를 줄 생각이다.",
  ui_story_9_8_1_102_dialog_content = "난 네게 아이테르를 초월한 힘을 줄 수 있다! 이제 약자의 신분에서 해방되는 거다!",
  ui_story_9_8_1_103_dialog_content = "해방...",
  ui_story_9_8_1_104_dialog_content = "슈모르, 넌 매번 시험마다 1등만 하던 모범생 아니었어?",
  ui_story_9_8_1_105_dialog_content = "근데 오히려 콜로서스 조종 같은 간단한 일은 왜 못 하는 거야?",
  ui_story_9_8_1_106_dialog_content = "슈모르가 조종 시험에 떨어졌다고? 말도 안 돼...",
  ui_story_9_8_1_107_dialog_content = "지금 중요한 건 콜로서스와 감응을 못 하는 사람이 있다는 거야! 슈모르, 너 정말 아이테르 맞아?",
  ui_story_9_8_1_108_dialog_content = "정말 안 들킬 수 있을까?",
  ui_story_9_8_1_109_dialog_content = "걱정할 거 없어. 넌 「디바우러호」의 차기 조종사잖아. 한드로 선생님한테 인정받은 승리자라고!",
  ui_story_9_8_1_110_dialog_content = "이 씨앗이 보이느냐? 이게 바로 네 희망이다.",
  ui_story_9_8_1_111_dialog_content = "...내... 희망...",
  ui_story_9_8_1_112_dialog_content = "좋다. 난 네가 힘을 갈망하고 있다는 걸 알 수 있다.",
  ui_story_9_8_1_113_dialog_content = "힘...",
  ui_story_9_8_1_114_dialog_content = "슈...슈모르, 너...",
  ui_story_9_8_1_115_dialog_content = "그래, 오직 어머니의 백성이 되어야만 살아남을 수 있는 것이다!",
  ui_story_9_8_1_116_dialog_content = "살아...남아...",
  ui_story_9_8_1_117_dialog_content = "넌 이제 더는 약하지도, 두려워하지도 않게 될 거다!",
  ui_story_9_8_1_118_dialog_content = "이 은총을 받아 힘을 얻고, 우리와 함께하는 거다!",
  ui_story_9_8_1_119_dialog_content = "그럼 이 세상, 그리고 모든 것을 지배할 수 있을 것이다!",
  ui_story_9_8_1_120_dialog_content = "모든 걸... 지배...",
  ui_story_9_8_1_121_dialog_content = "슈모르... 다...다가오지 마...",
  ui_story_9_8_1_122_dialog_content = "그래, 바로 그거다. 이리 와라.",
  ui_story_9_8_1_123_dialog_content = "제...제발... 부탁이야...",
  ui_story_9_8_1_124_dialog_content = "......",
  ui_story_9_8_1_125_dialog_content = "뭐냐?",
  ui_story_9_8_1_126_dialog_content = "저...",
  ui_story_9_8_1_127_dialog_content = "어서 칼을 들어라!",
  ui_story_9_8_1_128_dialog_content = "난...",
  ui_story_9_8_1_129_dialog_content = "꾸물대지 마라. 내 인내심엔 한계가 있단 말이다! 뭘 망설이는 거지?",
  ui_story_9_8_1_130_dialog_content = "저, 전 이제... 암귀가 되는 건가요?",
  ui_story_9_8_1_131_dialog_content = "흥, 됐다.",
  ui_story_9_8_1_132_dialog_content = "아아아아악!",
  ui_story_9_8_1_133_dialog_content = "뭐라고...?!",
  ui_story_9_8_1_134_dialog_content = "넌 이 계집애를 싫어했지. 내 말이 맞지?",
  ui_story_9_8_1_135_dialog_content = "......",
  ui_story_9_8_1_136_dialog_content = "내가 널 대신해 죽여줬으니, 내게 고마워해야 하는 게 아닌가?",
  ui_story_9_8_1_137_dialog_content = "절... 죽일 건가요?",
  ui_story_9_8_1_138_dialog_content = "그럴 리가.",
  ui_story_9_8_1_139_dialog_content = "난 네가 저들과 다르다는 걸 안다. 넌 강자가 될 수 있는 좋은 씨앗이거든.",
  ui_story_9_8_1_140_dialog_content = "당연하지. 암귀가 되면 넌 아이테르를 초월한, 심지어는 오로리안보다도 더 강한 힘을 얻게 된다!",
  ui_story_9_8_1_141_dialog_content = "그...그건 어떤 힘인 거죠?",
  ui_story_9_8_1_142_dialog_content = "그것은 대지를 기르는 어머니의 달콤한 샘이요, 어머니께서 만물에 베푸는 지고의 은총이니라.",
  ui_story_9_8_1_143_dialog_content = "널 살아가게 만들고, 더는 아무것도 두려워하지 않게 할 수 있지.",
  ui_story_9_8_1_144_dialog_content = "그걸... 받아들여야만... 제가 살 수 있는 건가요?",
  ui_story_9_8_1_145_dialog_content = "물론이다. 심지어 이 계곡보다 더 오래 살아남을 것이다.",
  ui_story_9_8_1_146_dialog_content = "그럼 그걸... 받아들이면... 전 더는 약하지 않을 수 있는 거죠?",
  ui_story_9_8_1_147_dialog_content = "당연하지. 오늘 이후로는 그 누구도 널 약하다고 말하지 못할 것이다.",
  ui_story_9_8_1_S147_dialog_content = "그걸 받아들이면... 디바우러호를 가질 자격이 생기는 건가요?",
  ui_story_9_8_1_S148_dialog_content = "디바우러호? 콜로서스 말이냐?",
  ui_story_9_8_1_S149_dialog_content = "크크크, 말해봐라. 네가 원하는 그 콜로서스가 어떤 모습이지?",
  ui_story_9_8_1_S150_dialog_content = "디바우러호는... 가장 강력한 콜로서스예요.\n오직 가장 강한 아이테르만이... 그걸 가질 자격을 얻어요.",
  ui_story_9_8_1_S151_dialog_content = "크하하! 그렇다면 넌 그 어느 아이테르보다도 그걸 가질 자격이 있게 될 것이다!\n넌 모든 아이테르를 뛰어넘을 테니까!",
  ui_story_9_8_1_148_dialog_content = "......",
  ui_story_9_8_1_149_dialog_content = "전...",
  ui_story_9_8_1_150_dialog_content = "...받아들일게요.",
  ui_story_9_8_1_151_dialog_content = "크하하하하하!",
  ui_story_9_8_1_152_dialog_content = "으윽...!",
  ui_story_9_8_1_153_dialog_content = "위대한 어머니시여. 이 세상에 당신의 종이 한 명 더 늘어났나이다!",
  ui_story_9_8_1_154_dialog_content = "...정말 저한테 힘을 주신 건가요?",
  ui_story_9_8_1_155_dialog_content = "왜 아무런 느낌도 없는 거죠...",
  ui_story_9_8_1_156_dialog_content = "슈모르, 그게 네 이름이냐?",
  ui_story_9_8_1_157_dialog_content = "명심해라, 슈모르. 그 누구도 어머니의 힘에 의문을 품어서는 안 된다. 넌 기다리는 법을 배워야 한다.",
  ui_story_9_8_1_158_dialog_content = "......",
  ui_story_9_8_1_159_dialog_content = "이제 절 어디로 데려가실 거죠?",
  ui_story_9_8_1_160_dialog_content = "슈모르, 우린 아무 데도 가지 않는다. 넌 이제 헤븐즈 밸리로 돌아가면 된다. 물론 날 데리고 말이지.",
  ui_story_9_8_1_161_dialog_content = "다시 헤븐즈 밸리로 가라구요?!",
  ui_story_9_8_1_162_dialog_content = "잊은 게냐? 네 「디바우러호」가 아직 헤븐즈 밸리에서 널 기다리고 있지 않느냐.",
  ui_story_9_8_1_163_dialog_content = "「디바우러호」가 있어야만 네 힘이 더욱 완전해지고,\n그 누구도 범접할 수 없게 될 것이다!",
  ui_story_9_8_1_164_dialog_content = "잊지 않았어요. 하지만... 전 남들과 달라요.",
  ui_story_9_8_1_165_dialog_content = "전... 콜로서스와 감응할 수 없어요. 전 이 모든 게 끝나고 나면...",
  ui_story_9_8_1_166_dialog_content = "호오? 감응할 수 없는 아이테르라고?",
  ui_story_9_8_1_167_dialog_content = "그렇게 말하지 마세요!",
  ui_story_9_8_1_168_dialog_content = "뭐, 되었다. 어차피 「씨앗」이 네 몸에서 울부짖기 시작했으니 말이야.",
  ui_story_9_8_1_169_dialog_content = "오늘부터 넌 더는 아이테르가 아니다.",
  ui_story_9_8_1_170_dialog_content = "이제 가서 콜로서스를 가동해 봐라.",
  ui_story_9_8_1_171_dialog_content = "...알겠어요.",
  ui_story_9_8_1_172_dialog_content = "아니야... 아니라고...!",
  ui_story_9_8_1_173_dialog_content = "난 진 적 없어... 절대 안 진다고...!",
  ui_story_9_8_1_174_dialog_content = "슈모르!",
  ui_story_9_8_1_175_dialog_content = "네가 죽는 그 순간까지! 내 눈을 똑바로 봐라!",
  ui_story_9_8_1_176_dialog_content = "아, 안──",
  ui_story_9_8_1_177_dialog_content = "안 돼!",
  ui_story_9_9_1_1_dialog_content = "다들 조심해!",
  ui_story_9_9_1_2_dialog_content = "뭐, 뭐야?!",
  ui_story_9_9_1_3_dialog_content = "<color=#e8d9bb>우── 우우── 우──</color>",
  ui_story_9_9_1_4_dialog_content = "소리... 수많은 소리가 들리고 있어...",
  ui_story_9_9_1_5_dialog_content = "어라? 땅이 흔들리는 소리인가?",
  ui_story_9_9_1_6_dialog_content = "아, 아냐... 이건... 디바우러호의 울음소리와 비명이야...",
  ui_story_9_9_1_7_dialog_content = "<color=#e8d9bb>우── 우우── 우──</color>",
  ui_story_9_9_1_8_dialog_content = "(전부... 콜로서스가 내는 소리야... 마치 주변에 묻힌 콜로서스들도 따라서 울고 있는 것 같아...)",
  ui_story_9_9_1_9_dialog_content = "<color=#e8d9bb><anim type=Shake>우── 우우── 우──</anim></color>",
  ui_story_9_9_1_10_dialog_content = "(심장에 구멍이 난 것 같은 느낌이야...)",
  ui_story_9_9_1_11_dialog_content = "(뭔가 뜨거운 액체가 흐르고 있어...)",
  ui_story_9_9_1_12_dialog_content = "누, 눈물?",
  ui_story_9_9_1_13_dialog_content = "PlayerName...",
  ui_story_9_9_1_14_dialog_content = "PlayerName... 너, 지금 우는 거야?",
  ui_story_9_9_1_15_dialog_content = "PlayerName...",
  ui_story_9_9_1_16_dialog_content = "아, 괜찮아... 그냥... 갑자기 스카이워커가 생각이 나서...",
  ui_story_9_9_1_X16_dialog_content = "PlayerName...",
  ui_story_9_9_1_17_dialog_content = "바이스...",
  ui_story_9_9_1_18_dialog_content = "뭔가 또 감응한 거야? 괜찮아. 우린 여기 있어!",
  ui_story_9_9_1_19_dialog_content = "저기... 괜찮으면 이거... 써도 좋아.",
  ui_story_9_9_1_20_dialog_content = "이건...?",
  ui_story_9_9_1_21_dialog_content = "손수건이야... PlayerName 씨, 이걸로 눈물 닦아도 돼.",
  ui_story_9_9_1_22_dialog_content = "미안해. 내가 갑자기 왜 이러는 건지 모르겠어...",
  ui_story_9_9_1_23_dialog_content = "PlayerName, 우리한테 사과할 필요는 없어.",
  ui_story_9_9_1_24_dialog_content = "눈물은 약자만의 전유물이 아냐. 누구나 자기 감정을 표출해야 할 때가 있는 법이니까.",
  ui_story_9_9_1_25_dialog_content = "응...",
  ui_story_9_9_1_26_dialog_content = "어이, 뭔가 느껴진 거냐?",
  ui_story_9_9_1_27_dialog_content = "수많은 콜로서스들의 울부짖음... 목소리들이... 물결처럼 밀려왔어.",
  ui_story_9_9_1_28_dialog_content = "누군가는 운명을 한탄했고... 누군가는 가까운 사람들과의 이별을 슬퍼하는 듯했어...",
  ui_story_9_9_1_29_dialog_content = "꼭 누가 내 심장을 틀어쥐는 느낌이야... 너무 괴로워...",
  ui_story_9_9_1_30_dialog_content = "...여기 다른 콜로서스가 있어?",
  ui_story_9_9_1_31_dialog_content = "...내가 들은 소리가 진짜는 아닐 거라 생각해...",
  ui_story_9_9_1_32_dialog_content = "그건 그저 콜로서스들이 헤븐즈 밸리에 남긴 잔류 의식 같은 거겠지...",
  ui_story_9_9_1_33_dialog_content = "하지만 그게 왜 지금 들리는 건데...?",
  ui_story_9_9_1_34_dialog_content = "......",
  ui_story_9_9_1_35_dialog_content = "PlayerName, 다시 디바우러호와 감응할 수 있어?",
  ui_story_9_9_1_36_dialog_content = "헤븐즈 밸리의 다크매터가 너무 짙어.",
  ui_story_9_9_1_37_dialog_content = "그래서 지금까진 디바우러호의 희미한 숨결밖에 느끼질 못했어.",
  ui_story_9_9_1_38_dialog_content = "하지만 지금은... 아무것도 느껴지지 않아.",
  ui_story_9_9_1_39_dialog_content = "PlayerName 씨는 콜로서스의 의식과 감응할 수 있는 거구나. 정말 부럽네...",
  ui_story_9_9_1_40_dialog_content = "감응 능력은 아이테르의 본능이자 재능이야. 너희가 빛의 힘으로 싸울 수 있는 것처럼 말이야.",
  ui_story_9_9_1_41_dialog_content = "사실 예전부터 궁금했는데...",
  ui_story_9_9_1_42_dialog_content = "콜로서스와 감응하는 건 어떤 느낌이야?",
  ui_story_9_9_1_43_dialog_content = "어떤... 느낌이냐고?",
  ui_story_9_9_1_44_dialog_content = "갑자기 그렇게 물어보니까 뭐라고 대답해야 할지 잘 모르겠네.",
  ui_story_9_9_1_45_dialog_content = "(난 17년 동안 스카이워커가 내 곁에 있어 주던 날들에 너무 익숙해져 있었어...)",
  ui_story_9_9_1_46_dialog_content = "(만약... 만에 하나... 다시는 스카이워커호를 만날 수 없게 된다면...)",
  ui_story_9_9_1_47_dialog_content = "PlayerName 씨, 말하기 곤란하면... 무리하지 않아도 괜찮아.",
  ui_story_9_9_1_48_dialog_content = "괜찮아. 그런 건 아냐.",
  ui_story_9_9_1_49_dialog_content = "그저 내가 이 문제에 대해 진지하게 생각해 본 적이 없다는 걸 이제야 깨달았거든.",
  ui_story_9_9_1_50_dialog_content = "콜로서스와 감응하면... 안심이 되고, 마음이 따뜻해지는 기분이 들어...",
  ui_story_9_9_1_51_dialog_content = "콜로서스는 마치 내 마음을 이해하는 친구처럼, 내가 무슨 생각을 하고 있는지 다 알고 있어.",
  ui_story_9_9_1_52_dialog_content = "그리고 너도 마찬가지로, 콜로서스가 무슨 말을 하는지 알 수 있는 유일한 사람이 되는 거야.",
  ui_story_9_9_1_53_dialog_content = "비록 가끔은 잔소리를 할 때도 있지만...",
  ui_story_9_9_1_54_dialog_content = "잔소리를 안 할 때면 뭔가 허전하다는 느낌이 들 거야...",
  ui_story_9_9_1_55_dialog_content = "그러니까 콜로서스와 감응할 수 있는 건... 무척... 행복한 느낌이라고 할 수 있을 것 같아.",
  ui_story_9_9_1_56_dialog_content = "행복한 느낌...",
  ui_story_9_9_1_57_dialog_content = "나도 「트래블러」가 무슨 생각을 하는지 정말 알고 싶어...",
  ui_story_9_9_1_58_dialog_content = "아, 그럼 네가 말하는 그 「트래블러」도 콜로서스인 거야?",
  ui_story_9_9_1_59_dialog_content = "하하, 「트래블러호」는 우리 레디젤 렌치의 자랑스러운 멤버라고!",
  ui_story_9_9_1_60_dialog_content = "그때 우린 레디젤 사막에서 모래에 반쯤 묻혀 있던 근육 소재를 발견했었지.",
  ui_story_9_9_1_61_dialog_content = "그래서 땅을 한참 파 봤더니, 낡아빠진 콜로서스가 나왔지 뭐야.",
  ui_story_9_9_1_62_dialog_content = "우리 기술팀 녀석들이 정말 갖은 고생을 한 끝에 그걸 고칠 수 있었다.",
  ui_story_9_9_1_63_dialog_content = "하지만 「트래블러호」는 보프만 조종할 수 있거든.",
  ui_story_9_9_1_64_dialog_content = "다른 사람한테 시키면 꼬리조차 꿈쩍도 안 한다고.",
  ui_story_9_9_1_65_dialog_content = "나도 「트래블러」 조종을 익히는 데 한참 시간이 걸렸어.",
  ui_story_9_9_1_66_dialog_content = "콜로서스와 감응할 수 없는데, 콜로서스를 조종할 수 있단 말이야?",
  ui_story_9_9_1_67_dialog_content = "음... 나도 어떻게 된 건지는 잘 모르겠지만...",
  ui_story_9_9_1_68_dialog_content = "하지만 나도 가끔은 「트래블러」의 감정을 조금은 느낄 수 있는 것 같아.",
  ui_story_9_9_1_69_dialog_content = "내가 「트래블러」를 처음 발견했을 때, 녀석은 무척 외롭고 혼란스러웠던 것 같았어...",
  ui_story_9_9_1_70_dialog_content = "녀석이 무슨 생각을 하고 있는진 잘 모르겠지만, 난 매일 녀석과 이야기를 나누곤 해.",
  ui_story_9_9_1_71_dialog_content = "이제 녀석은 레디젤 렌치의 생활을 좋아하게 된 것 같아.",
  ui_story_9_9_1_72_dialog_content = "하하하, 감응을 할 수 있고 없고는 보프한테는 문제가 되지 않는다고.",
  ui_story_9_9_1_73_dialog_content = "보프의 지금 조종 실력이라면 부족할 게 없으니까!",
  ui_story_9_9_1_74_dialog_content = "사막을 떠도는 강도들에게도 콜로서스가 있을 줄은 몰랐는걸.",
  ui_story_9_9_1_75_dialog_content = "꼬마 아가씨, 바깥세상엔 네가 모르는 일들이 아주 많이 있다고.",
  ui_story_9_9_1_76_dialog_content = "그러니까 항상 성에만 있는 건 좋지 않아!",
  ui_story_9_9_1_77_dialog_content = "......",
  ui_story_9_9_1_78_dialog_content = "뒤를 조심해!",
  ui_story_9_9_1_79_dialog_content = "설마... 또 암귀로 변한 오로리안...?",
  ui_story_9_9_1_80_dialog_content = "하지만 수가... 너무 많잖아...",
  ui_story_9_9_1_81_dialog_content = "아무래도 지금까지 이곳을 정찰하러 온 백야성의 경비병들이 전부 붙잡혀 실험체로 쓰인 모양이군.",
  ui_story_9_9_1_82_dialog_content = "...!",
  ui_story_9_9_1_83_dialog_content = "PlayerName, 지휘를 부탁해! 저들이 더 고통스러워지기 전에 끝내주고 싶어.",
  ui_story_9_13_1_1_dialog_content = "만물은 백야 아래에. 부디 이곳에서 안식하기를.",
  ui_story_9_13_1_2_dialog_content = "편히 쉬길 바랄게...",
  ui_story_9_13_1_3_dialog_content = "PlayerName, 얼마나 더 가야 하지?",
  ui_story_9_13_1_4_dialog_content = "기운이 희미하긴 하지만, 디바우러호는 분명히 이 근처에 있어!",
  ui_story_9_13_1_X4_dialog_content = "「근처」라면 어느 쪽인데? 왼쪽? 오른쪽? 아니면 앞쪽?",
  ui_story_9_13_1_5_dialog_content = "크오오──!",
  ui_story_9_13_1_6_dialog_content = "조심해! 앞에 암귀들이 잔뜩 몰려오고 있어!",
  ui_story_9_13_1_7_dialog_content = "PlayerName, 방향을 알려줘! 그쪽으로 길을 뚫을 테니까!",
  ui_story_9_13_2_1_dialog_content = "여기 하나 있는 것 같아! 저 암귀 시체의 목구멍 안에 있어.",
  ui_story_9_13_2_2_dialog_content = "으윽... 말도 안 돼, 이 암귀는 왜 이렇게 더러운 건데? 전혀 손을 댈 수가 없잖아.",
  ui_story_9_13_2_3_dialog_content = "나일즈, 펙트 양을 좀 도와주시죠.",
  ui_story_9_13_2_4_dialog_content = "......",
  ui_story_9_13_2_5_dialog_content = "위대하신 진리의 주인이시여, 부디 저를 용서해 주소서...",
  ui_story_9_13_2_6_dialog_content = "교리에 이르기를, 「더러운 것으로 자신을 더럽히지 말라」고 하였습니다.",
  ui_story_9_13_2_7_dialog_content = "하지만 당신의 발자취를 따르기 위해, 전 이제 봐서는 아니 될 것을 보고,\n만져선 아니 될 것을 만지려 합니다...",
  ui_story_9_13_2_8_dialog_content = "돌아간 후, 저는 3일간 목욕을 하며 당신의 용서를 빌겠나이다...",
  ui_story_9_13_2_9_dialog_content = "......",
  ui_story_9_13_2_10_dialog_content = "이제 그걸 세티한테 먹여 주세요.",
  ui_story_9_13_2_11_dialog_content = "<color=#e8d9bb>슈욱──!</color>",
  ui_story_9_13_2_12_dialog_content = "왜 굳이 씨앗을 세티한테 먹이는 거야?",
  ui_story_9_13_2_X12_dialog_content = "세티는 먹을 걸 좋아하잖아? 만약에 토해내지 않으면 어떡해?",
  ui_story_9_13_2_X13_dialog_content = "어차피 나일즈가 손도 댔으니까, 그냥 계속 들고 있으라 하지 그래?",
  ui_story_9_13_2_X14_dialog_content = "......",
  ui_story_9_13_2_13_dialog_content = "빅토리아 님, 부디 용서하십시오. 화를 참지 못했습니다...",
  ui_story_9_13_2_14_dialog_content = "펙트, 이 「씨앗」을 무시하면 안 됩니다.",
  ui_story_9_13_2_X15_dialog_content = "비록 크기는 작지만, 그 안에 담긴 다크매터는 평범한 오로리안의 정신에\n매우 심각한 영향을 줄 수 있을 정도입니다.",
  ui_story_9_13_2_X16_dialog_content = "우리의 몸은 확실히 강력한 루미나를 지니고 있지만, 이러한 영향을 견딜 수 있는 것도 잠깐뿐입니다.",
  ui_story_9_13_2_X17_dialog_content = "그러니 오랜 시간 접촉하지 않는 게 좋습니다.",
  ui_story_9_13_2_15_dialog_content = "그래, 그것도 일종의 「규율」인 모양이네. 확실히 내가 과소평가한 것 같아.",
  ui_story_9_14_1_1_dialog_content = "이 앞이야.",
  ui_story_9_14_1_2_dialog_content = "다들 정신 바짝 차려!",
  ui_story_9_14_1_3_dialog_content = "이게... 디바우러호?",
  ui_story_9_14_1_4_dialog_content = "너무 무서워... 역시 「트래블러」가 더 귀여운 것 같아...",
  ui_story_9_14_1_5_dialog_content = "다모클레스의 공격에 추락으로 인한 충격까지...",
  ui_story_9_14_1_6_dialog_content = "정말 끔찍한 모습이네...",
  ui_story_9_14_1_7_dialog_content = "맞아. 그리고 방금... 디바우러호가 울부짖었을 때... 마치 녀석이 죽음을 앞둔 듯한 느낌이었어.",
  ui_story_9_14_1_8_dialog_content = "역시 빨리 들어가서 슈모르의 시체를 찾아보는 게 좋겠어.",
  ui_story_9_14_1_9_dialog_content = "잠깐만, 누군가 나오고 있어!",
  ui_story_9_14_1_10_dialog_content = "슈모르인가?!",
  ui_story_9_14_1_11_dialog_content = "아냐... 그럴 리가 없어.",
  ui_story_9_14_1_12_dialog_content = "<color=#FFB400>노라</color>야!",
  ui_story_9_14_1_13_dialog_content = "!!!",
  ui_story_9_14_1_14_dialog_content = "...!",
  ui_story_9_14_1_15_dialog_content = "방금 전까지 생각하고 있었어. 누가 이 순간에 내 계획을 방해하러 올지 말이야.",
  ui_story_9_14_1_16_dialog_content = "이제 보니 너희들이었구나.",
  ui_story_9_14_1_17_dialog_content = "혹시 손님으로 왔으면 집주인한테 인사를 해야 한다고 배운 적 없는 거니?",
  ui_story_9_14_1_18_dialog_content = "그건 우리가 할 말 아냐?",
  ui_story_9_14_1_19_dialog_content = "여긴 헤븐즈 밸리야. 네가 있을 곳이 아니라고!",
  ui_story_9_14_1_20_dialog_content = "그럼 내가 여기 있는 이상, 규칙은 너희가 정하는 게 아닐 텐데?",
  ui_story_9_14_1_21_dialog_content = "이 자식...",
  ui_story_9_14_1_22_dialog_content = "그때 죽었다고 생각했는데!",
  ui_story_9_14_1_23_dialog_content = "설령 잿더미가 됐더라도 네 모습을 절대 잊지 않았을 거다! 이름만 바꾸면 내가 모를 거라 생각했냐!",
  ui_story_9_14_1_24_dialog_content = "......",
  ui_story_9_14_1_25_dialog_content = "「<color=#FFB400>드니에르</color>」! 그때 대체 내 동생한테 무슨 짓을 한 거냐!",
  ui_story_9_14_1_26_dialog_content = "......",
  ui_story_9_14_1_27_dialog_content = "어이! 귀가 먹었냐?!",
  ui_story_9_14_1_28_dialog_content = "PlayerName... 왜 네 몸에서 다크매터가 느껴지지 않는 거지?",
  ui_story_9_14_1_29_option_content = "넌 대체 누구지?",
  ui_story_9_14_1_30_dialog_content = "정말 네가 한때 일루미나의 연구원이었어?",
  ui_story_9_14_1_31_dialog_content = "그러면 어떻고, 안 그러면 어때?",
  ui_story_9_14_1_32_dialog_content = "그게 중요해?",
  ui_story_9_14_1_33_dialog_content = "나랑은 전혀 상관도 없는걸.",
  ui_story_9_14_1_34_dialog_content = "그것보다 PlayerName 너, 대답해. 네 몸의 「씨앗」은 어떻게 됐어?",
  ui_story_9_14_1_35_dialog_content = "내 등에 「씨앗」을 심은 게 너였던 거냐!",
  ui_story_9_14_1_36_dialog_content = "간지러워 죽는 줄 알았다고.",
  ui_story_9_14_1_37_dialog_content = "간지러워?",
  ui_story_9_14_1_38_dialog_content = "그리고? 가려운 증상은 얼마나 지속됐는데?",
  ui_story_9_14_1_39_dialog_content = "그게 아마... 아니지, 내가 왜 그걸 너한테 말해야 되는데?!",
  ui_story_9_14_1_40_dialog_content = "PlayerName, 조심해! 녀석한테 휘말리지 마!",
  ui_story_9_14_1_41_dialog_content = "어떻게 등에서 「씨앗」을 꺼낸 거야?",
  ui_story_9_14_1_42_dialog_content = "알고 싶어? 그럼 내 질문에 먼저 대답해.",
  ui_story_9_14_1_43_option_content = "왜 네가 헤븐즈 밸리에 있는 거지?",
  ui_story_9_14_1_44_dialog_content = "그리고 왜 오로리안을 암귀로 만들고 있는 거야?! 왜 그런 잔인한 실험을 하는 거냐고!",
  ui_story_9_14_1_45_option_content = "왜 나한테 「씨앗」을 심은 거야?",
  ui_story_9_14_1_46_dialog_content = "내가 「씨앗」을 꺼내지 않았다면, 나도 암귀로 변하게 되는 거였어?!",
  ui_story_9_14_1_47_dialog_content = "질문이 너무 많잖아.",
  ui_story_9_14_1_48_dialog_content = "PlayerName, 내가 해줄 말은 하나뿐이야. 난 정말 실망했어.",
  ui_story_9_14_1_49_dialog_content = "난 네게 더 강한 힘과 세상의 진리에 다가갈 수 있는 기회를 줬어.",
  ui_story_9_14_1_50_dialog_content = "하지만 넌 그걸 소중히 여기지 않았고, 자기 손으로 모든 걸 망쳐버렸지.",
  ui_story_9_14_1_51_dialog_content = "정말 낭비라니까.",
  ui_story_9_14_1_52_dialog_content = "PlayerName, 이제 네가 그 답을 들을 기회는 없을 거야.",
  ui_story_9_14_1_53_dialog_content = "저딴 헛소리에 정신 팔리지 마!",
  ui_story_9_14_1_54_dialog_content = "난 확신할 수 있다고. 지금 저 녀석은 내가 알던 그 일루미나 연구원, 「드니에르」가 분명해!",
  ui_story_9_14_1_55_dialog_content = "「드니에르」? 잘 모르는 이름인걸.",
  ui_story_9_14_1_56_dialog_content = "헛소리 집어치워!",
  ui_story_9_14_1_57_dialog_content = "이브가 지금까지 그토록 고생한 게 전부 네 녀석에게 이용당해서 벌어진 일이잖아!",
  ui_story_9_14_1_58_dialog_content = "이브?",
  ui_story_9_14_1_59_dialog_content = "뭐냐, 이제야 기억이 난 거냐?",
  ui_story_9_14_1_60_dialog_content = "그런 애가 있었던 것 같긴 한데, 기억은 안 나네.",
  ui_story_9_14_1_61_dialog_content = "내 손을 거친 실험체가 너무 많아서 말이야.",
  ui_story_9_14_1_62_dialog_content = "뭐라고...?!",
  ui_story_9_14_1_63_dialog_content = "사메야마, 진정해. 누가 봐도 지금 녀석은 일부러 널 도발하고 있어.",
  ui_story_9_14_1_64_dialog_content = "난 지금 아주 침착하다고!",
  ui_story_9_14_1_65_dialog_content = "저 자식을 조각조각 찢어버릴 방법을 수백 개는 떠올릴 수 있을 만큼 말이야!",
  ui_story_9_14_1_66_dialog_content = "내가 보기엔 넌 지금 사서 고생하는 방법 수백 개를 생각해낸 것 같은데?",
  ui_story_9_14_1_67_dialog_content = "아무래도 쓴맛을 보여줘야 똑바로 말을 할 모양이지!",
  ui_story_9_14_1_68_dialog_content = "......",
  ui_story_9_14_1_69_dialog_content = "겨우 그 정도 힘으로 큰소리를 쳤던 거구나.",
  ui_story_9_14_1_70_dialog_content = "대장! 괜찮아?",
  ui_story_9_14_1_71_dialog_content = "크윽, 멀쩡해!",
  ui_story_9_14_1_72_dialog_content = "방금 대체 뭐가 어떻게 된 거야...?",
  ui_story_9_14_1_73_dialog_content = "한 손으로... 사메야마를 날려버렸다고?!",
  ui_story_9_14_1_74_dialog_content = "저것도 다크매터의 힘이야.",
  ui_story_9_14_1_75_dialog_content = "아무래도 저 녀석은 이미 오로리안임을 포기하고 괴물로 변해버린 것 같아!",
  ui_story_9_14_1_76_dialog_content = "이 빌어먹을 자식, 가만두지 않겠어!",
  ui_story_9_14_1_77_dialog_content = "조용히 해. 분수도 모르고 설치지 말고.",
  ui_story_9_14_1_78_dialog_content = "난 싸움을 좋아하지 않아.",
  ui_story_9_14_1_79_dialog_content = "소꿉놀이를 하고 싶은 거라면 너한테 적당한 상대를 소개해줄 순 있어.",
  ui_story_9_14_1_80_dialog_content = "매드혼, 새 친구들과 좀 놀아주렴.",
  ui_story_9_14_1_81_dialog_content = "<anim type=Shake>타바...드... 다시... 살아났다!</anim>",
  ui_story_9_14_1_82_dialog_content = "매드혼이라니? 이건 아무리 봐도 지난번의 타바드 그 녀석이잖아!",
  ui_story_9_14_1_X82_dialog_content = "이름은 그냥 쉽게 기록하기 위한 코드네임일 뿐이야...",
  ui_story_9_14_1_83_dialog_content = "본 적 있는 암귀야?",
  ui_story_9_14_1_84_dialog_content = "분명 히이로 님이 아르카누스호에서 쓰러트렸었는데...",
  ui_story_9_14_1_85_dialog_content = "또 수작을 부려서 시체를 되살린 모양이네.",
  ui_story_9_14_1_86_dialog_content = "그럼 지금까지 고위 암귀들을 부활시켰던 것도 노라였던 거네!",
  ui_story_9_14_1_87_dialog_content = "불량품을 재사용했을 뿐이야.",
  ui_story_9_14_1_88_dialog_content = "그래도 너희들과 놀아주기엔 충분하겠지.",
  ui_story_9_14_1_89_dialog_content = "<anim type=Shake>크오오오──!</anim>",
  ui_story_9_14_1_90_dialog_content = "<anim type=Shake>타바...드는... 죽지... 않는다!</anim>",
  ui_story_9_14_2_1_dialog_content = "<anim type=Shake>크아악──!</anim>",
  ui_story_9_14_2_2_dialog_content = "조심해! 노라가 뭔가 꾸미고 있어!",
  ui_story_9_14_2_3_dialog_content = "PlayerName, 조심해!",
  ui_story_9_14_2_4_dialog_content = "...!",
  ui_story_9_14_2_5_dialog_content = "녀석한테 손대지 마──!",
  ui_story_9_14_2_6_dialog_content = "......",
  ui_story_9_14_2_7_dialog_content = "대장...!",
  ui_story_9_14_2_8_dialog_content = "사메야마, 괜찮아...?",
  ui_story_9_14_2_9_dialog_content = "난 괜찮아! 크윽...",
  ui_story_9_14_2_10_dialog_content = "타락한 오로리안, 한 발짝만 더 내디딘다면, 이 창으로 정의를 집행하겠어!",
  ui_story_9_14_2_11_dialog_content = "너희들, 그렇게 흥분할 거 없어.",
  ui_story_9_14_2_12_dialog_content = "난 그저 PlayerName의 상태를 살펴보고 싶었을 뿐이야.",
  ui_story_9_14_2_13_dialog_content = "노라! 대체 PlayerName한테 무슨 짓을 할 생각이지?!",
  ui_story_9_14_2_14_dialog_content = "너희가 내 질문에 대답하길 거부했으니까, 내가 직접 확인하는 수밖에 없어.",
  ui_story_9_14_2_15_dialog_content = "PlayerName, 네 몸엔 확실히 「씨앗」의 흔적이 없는 것 같네.",
  ui_story_9_14_2_16_dialog_content = "마지막으로 물어볼게. 「씨앗」을 어떻게 꺼낸 거야?",
  ui_story_9_14_2_17_dialog_content = "내 질문에나 먼저 대답해. 그런 「씨앗」 실험을 벌이는 이유가 대체 뭐야?",
  ui_story_9_14_2_18_dialog_content = "PlayerName, 아직 상황을 잘 파악하지 못한 모양이구나.",
  ui_story_9_14_2_19_dialog_content = "넌 나랑 조건을 협상할 자격도 없고, 그럴 힘도 없어.",
  ui_story_9_14_2_20_dialog_content = "PlayerName, 상대하지 마!",
  ui_story_9_14_2_21_dialog_content = "음?",
  ui_story_9_14_2_22_dialog_content = "PlayerName한테 심은 씨앗은 내가 꺼냈어. 무슨 문제라도 있어?",
  ui_story_9_14_2_23_dialog_content = "일루미나에 어째서 당신 같은 배신자가 나올 수 있는 거지?!",
  ui_story_9_14_2_24_dialog_content = "바이스, 진정해!",
  ui_story_9_14_2_25_dialog_content = "사실대로 말하는 게 좋을 거야.",
  ui_story_9_14_2_26_dialog_content = "꺄아악──! 으윽...",
  ui_story_9_14_2_27_dialog_content = "바이스!",
  ui_story_9_14_2_28_dialog_content = "노라! 바이스를 놔줘!",
  ui_story_9_14_2_29_dialog_content = "그래줄 순 있어. 하지만 너도 성의를 보여야지.",
  ui_story_9_14_2_30_dialog_content = "말해. 「씨앗」은 어디로 갔지?",
  ui_story_9_14_2_31_dialog_content = "......",
  ui_story_9_14_2_32_dialog_content = "(바이스를 위험에 빠트릴 순 없어...)",
  ui_story_9_14_2_33_dialog_content = "(말하는 수밖에 없겠어...)",
  ui_story_9_14_2_34_dialog_content = "네가 알고 싶은 걸 다 말해줄 테니까, 먼저 바이스를 놔줘! 약속할 테니까!",
  ui_story_9_14_2_X34_dialog_content = "좋아.",
  ui_story_9_14_2_X35_dialog_content = "콜록, 콜록...",
  ui_story_9_14_2_X36_dialog_content = "바이스! 얼른 이쪽으로 와라!",
  ui_story_9_14_2_X37_dialog_content = "자, 이제 말해.",
  ui_story_9_14_2_35_dialog_content = "내 몸에 있던 「씨앗」은 흰 상자를 든 남자가 가지고 갔어.",
  ui_story_9_14_2_36_dialog_content = "흰 상자... 남자...",
  ui_story_9_14_2_37_dialog_content = "그게 누군데?",
  ui_story_9_14_2_38_dialog_content = "모르는 사람이야. 그리고 왜 「씨앗」을 가지고 갔는지도 몰라.",
  ui_story_9_14_2_39_dialog_content = "하지만 그 사람이 나한테 「씨앗」이 오로리안을 암귀로 만든다고 말했어!",
  ui_story_9_14_2_40_dialog_content = "넌 「씨앗」으로 날 암귀로 만들려고 했고, 게다가 백야성의 경비병들까지도 암귀로 만들었어!",
  ui_story_9_14_2_41_dialog_content = "네가 말한 실험체란 것도 결국 전부 널 위해 「씨앗」을 시험할 희생자들이었겠지!",
  ui_story_9_14_2_42_dialog_content = "안 그래?!",
  ui_story_9_14_2_43_dialog_content = "그렇게 자기 판단을 믿는다면, 나한테 물어볼 필요도 없잖아.",
  ui_story_9_14_2_44_dialog_content = "아니, 난 알아야겠어. 대체 왜 그런 잔인한 실험을 벌인 거야?",
  ui_story_9_14_2_45_dialog_content = "어째서 오로리안이면서 암귀의 편에 서 있는 거냐고!",
  ui_story_9_14_2_46_dialog_content = "말했을 텐데, PlayerName. 네가 그걸 알 기회는 이미 존재하지 않아.",
  ui_story_9_14_2_47_dialog_content = "<color=#e8d9bb>쿠구구궁──!</color>",
  ui_story_9_14_2_48_dialog_content = "음? 시간이 다 된 모양이네.",
  ui_story_9_14_2_49_dialog_content = "무슨 소리지?",
  ui_story_9_14_2_50_dialog_content = "디바우러호의... 안에서 났어...",
  ui_story_9_14_2_51_dialog_content = "마치... 콜로서스가 멈추는 소리 같았어.",
  ui_story_9_14_2_52_dialog_content = "(방금 전까진 디바우러호의 기운이 희미하게 느껴졌는데... 갑자기 하나도 느껴지질 않아.)",
  ui_story_9_14_2_53_dialog_content = "(설마... 디바우러호가... 죽은 건가?)",
  ui_story_9_14_2_54_dialog_content = "노라! 너 설마 디바우러호까지?!",
  ui_story_9_14_2_55_dialog_content = "대체 또 무슨 짓을 한 거야?!",
  ui_story_9_14_2_56_dialog_content = "PlayerName, 넌 정말 질문이 많구나.",
  ui_story_9_14_2_57_dialog_content = "무슨 일이 일어났는지 알고 싶다면, 콜로서스에서 네 「<color=#FFB400>오랜 친구</color>」한테 직접 물어보는 게 어때?",
  ui_story_9_14_2_58_dialog_content = "녀석이 디바우러호로 들어간다!",
  ui_story_9_14_2_59_dialog_content = "어이! 거기 안 서?!",
  ui_story_9_14_2_60_dialog_content = "「<color=#FFB400>오랜 친구</color>」...?",
  ui_story_9_14_2_61_dialog_content = "......",
  ui_story_9_14_2_62_dialog_content = "슈모르...",
  ui_story_9_14_2_63_dialog_content = "<size=45>슈모르가 아직 살아있어!</size>",
  ui_story_10_1_1_1_dialog_content = "<color=#e8d9bb>백야성, 진료소 앞</color>",
  ui_story_10_1_1_2_dialog_content = "백야성의 미드가든 구역은 이런 모습이었던 거냥.",
  ui_story_10_1_1_S1_dialog_content = "건물들이... 하나같이 화려하다냥.",
  ui_story_10_1_1_3_dialog_content = "비비안 님이 여기서 좀 오래 쉬고 계셨으면 좋겠다냥.\n그럼 필리시도 더 많이 쉴 수 있을 텐데...",
  ui_story_10_1_1_4_dialog_content = "우냥?",
  ui_story_10_1_1_5_dialog_content = "새로운 환자는 어디 있어? 지금 바로 갈게!",
  ui_story_10_1_1_6_dialog_content = "라파엘 기사장님, 제발 여기서 날아다니지 좀 마십시오!",
  ui_story_10_1_1_7_dialog_content = "...가버렸다냥?",
  ui_story_10_1_1_8_dialog_content = "아무래도 필리시가 움직일 기회가 온 것 같다냥.",
  ui_story_10_1_1_9_dialog_content = "<color=#e8d9bb>샤샤샥──</color>",
  ui_story_10_1_1_10_dialog_content = "휴, 상처가 대체 언제쯤 나으려나... 여기 있는 동안은 아무것도 할 수가 없잖아.",
  ui_story_10_1_1_11_dialog_content = "쿠우!",
  ui_story_10_1_1_12_dialog_content = "위로해줘서 고마워, 퀴리. 난 괜찮아, 그냥 조금 불안해서 그래...",
  ui_story_10_1_1_13_dialog_content = "그럼 가서 망을 좀 봐주겠니?",
  ui_story_10_1_1_14_dialog_content = "쿠우!",
  ui_story_10_1_1_15_dialog_content = "그리고...",
  ui_story_10_1_1_16_dialog_content = "<color=#e8d9bb>바스락바스락──</color>",
  ui_story_10_1_1_17_dialog_content = "거기 「고양이」, 귀가 바닥을 쓸고 있잖아요.",
  ui_story_10_1_1_18_dialog_content = "에? 필리시가 언제 바닥을 쓸었다는 거냥.",
  ui_story_10_1_1_19_dialog_content = "필리시는 바닥에 귀를 대고 주변 사람들의 활동을 감시하고 있던 거다냥~",
  ui_story_10_1_1_20_dialog_content = "당신이 뭘 걱정하는 건지는 알고 있어요.",
  ui_story_10_1_1_21_dialog_content = "여긴 저들이 절 위해 특별히 마련해 준 방인걸요. 물론 이미 제가 자세히 확인했지만요...",
  ui_story_10_1_1_22_dialog_content = "다행히 절 감시하고 있진 않더군요.",
  ui_story_10_1_1_S2_dialog_content = "저들은 그저 제가 백야성에 좀 더 오래 머무르길 바라고 있을 뿐이에요.",
  ui_story_10_1_1_23_dialog_content = "그럼 어떤 정보를 가져왔는지 어서 말해보세요.",
  ui_story_10_1_1_24_dialog_content = "역시나 참모장님이다냥. 필리시를 아주 잘 알고 있다냥.",
  ui_story_10_1_1_25_dialog_content = "필리시는 <color=#FFB400>「노라」</color>에 대한 소식을 듣자마자 바로 달려왔다냥.",
  ui_story_10_1_1_26_dialog_content = "그 사람에 대한 정보를 찾았나요?",
  ui_story_10_1_1_27_dialog_content = "그건 쉽지 않다냥.",
  ui_story_10_1_1_28_dialog_content = "...내부 보고에서조차 그 사람은 9년 전에 「<color=#FFB400>죽은</color>」 사람이니 말이다냥.",
  ui_story_10_1_1_29_dialog_content = "9년 전, 대규모의 화재가 그 지하성 전체를 집어삼켰다냥...",
  ui_story_10_1_1_30_dialog_content = "사람들은 다들 그 여자도 그때 죽었다고 생각했다냥.",
  ui_story_10_1_1_31_dialog_content = "그러나 그 뒤에 조사단은 폐허에서 암귀와 오로리안의 시신을 발견했다냥.",
  ui_story_10_1_1_32_dialog_content = "필리시는 노라가 PlayerName의 몸에 「<color=#FFB400>씨앗</color>」을 넣었다는 얘길 들은 순간...",
  ui_story_10_1_1_33_dialog_content = "바로 그 사실들을 떠올렸다냥.",
  ui_story_10_1_1_34_dialog_content = "어쩌면 노라는 그때부터 그런 연구를 하고 있었을지도 모른다냥.",
  ui_story_10_1_1_35_dialog_content = "어쨌든 지금 그 여자는... <color=#FFB400>이미 암귀가 되었을 가능성</color>이 매우 커요.",
  ui_story_10_1_1_36_dialog_content = "대원수님께선 노라가 아직 살아있다는 알았을 때 어떤 반응을 보이셨죠?",
  ui_story_10_1_1_37_dialog_content = "우냥... 그건 말이지...",
  ui_story_10_1_1_38_dialog_content = "뭐죠? 왜 망설이는 건가요?",
  ui_story_10_1_1_39_dialog_content = "참모장님도 대원수님과 노라가 어떤 사이일지 알고 있을 거다냥. 그래서...",
  ui_story_10_1_1_40_dialog_content = "무슨 걱정을 하는 건지 알아요. <color=#FFB400>노라는 대원수님의 동생이니까요</color>.",
  ui_story_10_1_1_41_dialog_content = "역시 참모장님이다냥. 필리시가 무슨 생각을 하는지 아주 잘 알고 있다냥.",
  ui_story_10_1_1_42_dialog_content = "무슨 일이 있었는지 말해보세요.",
  ui_story_10_1_1_43_dialog_content = "대원수님께선 군단장님들을 데리고 나가셨다냥. 명목상으로는 군단장 회의였지만...",
  ui_story_10_1_1_44_dialog_content = "필리시는 이번엔 좀 다르다고 생각했다냥.",
  ui_story_10_1_1_45_dialog_content = "네 분의 군단장님들은 대원수님이 가장 신뢰하는 사람들이고, 일루미나의 최정예 전사다냥.",
  ui_story_10_1_1_46_dialog_content = "그럼 참모장님은 대원수님이 사람들을 데리고 노라를 찾으러 갔다고 생각하는 거다냥?",
  ui_story_10_1_1_47_dialog_content = "필리시, 당신은 암귀에 대해 무척 뛰어난 정보력을 가지고 있죠.",
  ui_story_10_1_1_48_dialog_content = "하지만 동료들의 정보를 어떻게 분석하고 처리해야 하는지에 대해선 아직 요령이 부족해요.",
  ui_story_10_1_1_49_dialog_content = "우냥...",
  ui_story_10_1_1_50_dialog_content = "그럼 그냥 말해달라냥. 필리시는 지금 머리가 잘 안 돌아간다냥...",
  ui_story_10_1_1_51_dialog_content = "당신은 우리의 대원수님이 개인적인 감정을 앞세워 행동할 사람이라고 생각하나요?",
  ui_story_10_1_1_52_dialog_content = "에엣──? 필리시는 대원수님을 의심한 적 없다냥! 정말이다냥!",
  ui_story_10_1_1_53_dialog_content = "알고 있어요... 당황하지 말고 끝까지 들으세요.",
  ui_story_10_1_1_54_dialog_content = "노라가 나타난 건 우리에겐 일종의 신호예요.",
  ui_story_10_1_1_55_dialog_content = "포식자가 사냥감을 노리고 공격을 준비하는 그 순간은,\n포식자 자신의 경계가 가장 소홀해지는 순간이기도 하죠.",
  ui_story_10_1_1_56_dialog_content = "이해했다냥! 참모장님 얘기는 필리시가 대원수님의 일에 너무 신경을 쓰지 말라는 거다냥?",
  ui_story_10_1_1_57_dialog_content = "알았다냥. 대원수님이라면 분명히 계획이 있으실 거다냥.",
  ui_story_10_1_1_58_dialog_content = "휴, 정말 이해한 게 맞았으면 좋겠네요.\n어쨌든 대원수님에 대해서라면 멋대로 추측하지 않는 게 좋아요.",
  ui_story_10_1_1_59_dialog_content = "알겠다냥.",
  ui_story_10_1_1_60_dialog_content = "그럼 필리시는 계속 「씨앗」을 조사해야 하는 거다냥?",
  ui_story_10_1_1_61_dialog_content = "물론이죠.",
  ui_story_10_1_1_62_dialog_content = "그럼 필리시는 이제 바이스 일행을 찾으러 가야 하는 걸까냥?",
  ui_story_10_1_1_63_dialog_content = "네? 어째서 그런 결론이 나오는 거죠?",
  ui_story_10_1_1_64_dialog_content = "간단하잖냥. 「씨앗」에 대한 정보는 PlayerName하고 바이스가 제공한 거다냥!",
  ui_story_10_1_1_65_dialog_content = "필리시는 이쪽으로 오는 길에 디바우러호가 추락했다는 소식을 들었다냥!",
  ui_story_10_1_1_66_dialog_content = "그리고 며칠 전에 콜로서스 한 대가 백야성을 떠났다냥!",
  ui_story_10_1_1_67_dialog_content = "바이스 일행은 분명히 <color=#FFB400>디바우러호</color>를 쫓아갔을 거다냥!",
  ui_story_10_1_1_68_dialog_content = "「씨앗」이 디바우러호와 관계가 있다면,\n필리시가 바로 디바우러호를 조사하면 되는 거 아니다냥?",
  ui_story_10_1_1_69_dialog_content = "역시 이럴 땐 참 똑똑하다니까요...",
  ui_story_10_1_1_70_dialog_content = "당신 생각이 맞아요. PlayerName, 그리고 바이스는 디바우러호가 있는 곳으로 향했어요.",
  ui_story_10_1_1_71_dialog_content = "그럼 필리시도 가도 되는 거 아니다냥?",
  ui_story_10_1_1_72_dialog_content = "우선 한 가지만 물어보죠. 가서 놀 생각은 아니죠?",
  ui_story_10_1_1_73_dialog_content = "당연하다냥. 필리시는 지금 안 좋은 예감이 든다냥...",
  ui_story_10_1_1_74_dialog_content = "슈모르도 결국 노라랑 관계가 있으니까, 조사 목적이든 안전을 위해서든...",
  ui_story_10_1_1_75_dialog_content = "필리시가 같이 가는 게 도움이 될 거다냥.",
  ui_story_10_1_1_76_dialog_content = "게다가 노라에 대한 정보를 생각하는 것만으로도 필리시는 벌써 소름이 끼친다냥!",
  ui_story_10_1_1_77_dialog_content = "만약 노라가 PlayerName하고 바이스를 잡아서 실험체로 쓰면 어떡한다냥?",
  ui_story_10_1_1_78_dialog_content = "그렇군요. 당신 생각은 이해했어요.",
  ui_story_10_1_1_79_dialog_content = "하지만 바이스 일행을 그렇게 걱정할 필요는 없어요.",
  ui_story_10_1_1_80_dialog_content = "사실 바이스 일행이 출발하기 전에, 전 이미 노라와 마주칠 가능성에 대해 저들과 논의했어요.",
  ui_story_10_1_1_81_dialog_content = "가장 중요한 것은 지금 그 일행에 백야성의 호위대장 카렌이 있다는 거예요.",
  ui_story_10_1_1_82_dialog_content = "그 말은 곧... 백야성이 벌써 슈모르의 문제에 대해 개입하기 시작했다는 뜻이겠죠.",
  ui_story_10_1_1_83_dialog_content = "에? 그런 거냥...",
  ui_story_10_1_1_84_dialog_content = "그럼 필리시가 따라가는 것도 불편할 것 같다냥...",
  ui_story_10_1_1_85_dialog_content = "맞아요. 상황이 더 확실해지기 전까지 우린 바이스의 소식을 기다리고 있는 게 좋겠어요.",
  ui_story_10_2_1_1_dialog_content = "저기...",
  ui_story_10_2_1_2_dialog_content = "이제 우린 어떡하지?",
  ui_story_10_2_1_3_dialog_content = "뭘 어떡해? 당연히 쳐들어가야지! 저렇게 도망치는 걸 보고만 있을 거냐?",
  ui_story_10_2_1_4_dialog_content = "좀 진정해.",
  ui_story_10_2_1_5_dialog_content = "아무리 봐도 우릴 유인하고 있는 게 확실하잖아.",
  ui_story_10_2_1_6_dialog_content = "당연히 나도 알고 있다고!",
  ui_story_10_2_1_7_dialog_content = "쫓아가면 저 녀석이 준비한 함정에 빠지겠지.",
  ui_story_10_2_1_8_dialog_content = "하지만 안 쫓아가면 녀석을 그냥 놔주는 거랑 똑같잖아!",
  ui_story_10_2_1_9_dialog_content = "그리고 너희가 쫓고 있는 그 <color=#FFB400>슈모르</color>도 말이야.",
  ui_story_10_2_1_10_dialog_content = "맞아. 다른 건 몰라도 그건 확실해. 슈모르는 아직 살아있어.\n그리고 저 디바우러호 안에 있어!",
  ui_story_10_2_1_11_dialog_content = "기운이 무척 약하게 느껴져. 분명히 큰 중상을 입었을 거야.",
  ui_story_10_2_1_12_dialog_content = "흥분하지 마. 아니면 일단 여길 지키면서...",
  ui_story_10_2_1_13_dialog_content = "백야성이나 일루미나에 지원을 요청하자고 말하려는 건 아니겠지?",
  ui_story_10_2_1_14_dialog_content = "꿈 깨라고. 지원 병력이 올 때면 이미 다 끝난 뒤일 거다.",
  ui_story_10_2_1_15_dialog_content = "상황을 멋대로 억측하지 마.",
  ui_story_10_2_1_16_dialog_content = "하, 이번 일에 너 하나만 보낸 것만 봐도 뻔하지 않아?",
  ui_story_10_2_1_17_dialog_content = "여기서 이렇게 많은 백야성 병사들이 죽은 걸 봐라.\n그쪽에선 무슨 일이 벌어지고 있는지 진작에 알고 있었을 거다.",
  ui_story_10_2_1_18_dialog_content = "지원을 요청할 거라면 알아서 해라. 난 기다릴 생각 없으니까.",
  ui_story_10_2_1_19_dialog_content = "저기, 우리끼리 싸운다고 해결이 되는 건 아니잖아...",
  ui_story_10_2_1_20_dialog_content = "아니면 소리를 질러보면 어떨까? 우리 일행들이 듣고 올지도 모르잖아...",
  ui_story_10_2_1_21_dialog_content = "구덩이에 빠져서 딴 길로 샌 건 우린데, 다른 사람들이 뭘 어떻게 알고 찾아오겠어?\n그럼 죄다 구덩이에 빠질 때까지 기다려야 하잖아!",
  ui_story_10_2_1_22_dialog_content = "그것도 그렇네... 게다가 다들 길치잖아...",
  ui_story_10_2_1_23_dialog_content = "그럼 노라가 함정을 준비해서 우릴 유인하고, 우릴 한 번에 전부 없애려는 걸까?",
  ui_story_10_2_1_24_dialog_content = "왠지 그건 아닐 것 같은데...",
  ui_story_10_2_1_25_dialog_content = "방금 전에 우린 녀석한테 손도 못 댔잖아.",
  ui_story_10_2_1_26_dialog_content = "그렇게 강한 힘을 지니고 있으면서... 왠지...",
  ui_story_10_2_1_27_dialog_content = "<color=#FFB400>우릴 공격할 생각이 없는 것처럼 보였잖아?</color>",
  ui_story_10_2_1_28_dialog_content = "그럼 설마 우리가 정말 가서 슈모르를 보길 바라는 걸까?",
  ui_story_10_2_1_29_dialog_content = "좀 더 정보를 알아낼 수 있다면 좋을 텐데...",
  ui_story_10_2_1_30_dialog_content = "PlayerName 씨, 혹시 감응으로 노라의 생각을 읽는 것도 가능해?",
  ui_story_10_2_1_31_dialog_content = "그게... 사실 안 그래도 시도는 해봤거든...",
  ui_story_10_2_1_32_dialog_content = "하지만 난 <color=#FFB400>노라와 전혀 감응할 수 없었어</color>.",
  ui_story_10_2_1_33_dialog_content = "어째서지?",
  ui_story_10_2_1_34_dialog_content = "어떻게 설명해야 할지 잘 모르겠지만, 아무튼...",
  ui_story_10_2_1_35_dialog_content = "상대의 생각과 감응하는 건 애초에 그리 쉬운 일이 아니야.",
  ui_story_10_2_1_36_dialog_content = "상대와의 거리, 감응 능력의 강도, 상대의 저항 등 다양한 요소가 감응 효과에 영향을 미치거든.",
  ui_story_10_2_1_37_dialog_content = "사실 지금 난 슈모르와 감응하는 건 무척 쉽게 해낼 수 있어...",
  ui_story_10_2_1_38_dialog_content = "그리고 왠지... 점점 더 쉬워지고 있는 것 같아.",
  ui_story_10_2_1_39_dialog_content = "지금 내가 확실하게 알 수 있는 건 슈모르가 심각한 상처를 입어서 약해진 상태라는 거야.",
  ui_story_10_2_1_40_dialog_content = "바이스, 카렌... 난...",
  ui_story_10_2_1_41_dialog_content = "가자! 그동안 그 많은 위험한 상황에서도 우린 용감하게 나섰잖아. 오늘이라고 다를 건 없어.",
  ui_story_10_2_1_42_dialog_content = "알겠어. 가서 진상을 확인하자. 내가 앞장설게.",
  ui_story_10_2_1_43_dialog_content = "뭐야, 다들 가기로 한 거냐? 이렇게 빨리?",
  ui_story_10_2_1_44_dialog_content = "네가 한 말들은 듣기엔 뭔가 일리가 있어 보이지만, 사실 지금 상황은 아무것도 달라진 게 없어.",
  ui_story_10_2_1_45_dialog_content = "바이스가 너랑 사이가 좋다는 건 알고 있어. 근데 카렌이 네 말을 듣는 이유는 뭐야?",
  ui_story_10_2_1_46_dialog_content = "내 말을 듣는 게 아니야... 어쨌든 바이스랑 카렌한테는 정말 고맙게 생각하고 있어.\n지금까지 계속해서 날 도와줬으니까.",
  ui_story_10_2_1_47_dialog_content = "이번 일이 끝나면 내가 꼭 보답할 수 있었으면 좋겠어.",
  ui_story_10_2_1_48_dialog_content = "그럼 가자...",
  ui_story_10_2_1_49_dialog_content = "이게 디바우러호야?",
  ui_story_10_2_1_50_dialog_content = "하, 내부는 별로 무서울 것도 없잖아. 낡아 빠져서 볼품없고 말이지.",
  ui_story_10_2_1_51_dialog_content = "그럴 수밖에. 백야성에서 이걸 격추시켰거든.",
  ui_story_10_2_1_52_dialog_content = "알고 있어. 나한테 그렇게 강조할 거 없다고.",
  ui_story_10_2_1_53_dialog_content = "난 그냥 당신 질문에 대답했을 뿐이야. 방금 이게 왜 낡아 빠진 건지 투덜댔잖아?",
  ui_story_10_2_1_54_dialog_content = "콜록, 콜록... 아마... 디바우러호의 에너지가 바닥 난 것도 이유 중 하나일 거야.",
  ui_story_10_2_1_55_dialog_content = "콜록콜록...",
  ui_story_10_2_1_56_dialog_content = "왜 그래? 우리가 싸우기라도 할까 걱정인 거냐? 뭘 그리 기침을 하고 있어?",
  ui_story_10_2_1_57_dialog_content = "아니... 다크매터 때문에 그래...",
  ui_story_10_2_1_58_dialog_content = "분명히 추락한 잔해일 뿐인데, 안에 이렇게 강력한 다크매터가 있다니...",
  ui_story_10_2_1_59_dialog_content = "크르르...",
  ui_story_10_2_1_60_dialog_content = "...암귀 소리인가? 다들 조심해!",
  ui_story_10_2_1_61_dialog_content = "크오오──!",
  ui_story_10_2_2_1_dialog_content = "캬악──!",
  ui_story_10_2_2_2_dialog_content = "이런! PlayerName. 조심해!",
  ui_story_10_2_2_3_dialog_content = "저리 꺼져!",
  ui_story_10_2_2_4_dialog_content = "어이, 괜찮냐?",
  ui_story_10_2_2_5_dialog_content = "아, 아... 고, 고마워...",
  ui_story_10_2_2_6_dialog_content = "괜찮아. 자칫하면 바지까지 태워버릴 뻔했지만...",
  ui_story_10_2_2_7_dialog_content = "미안, 실수로 한 마리를 놓쳤어...",
  ui_story_10_2_2_8_dialog_content = "하나 더 있어!",
  ui_story_10_2_2_9_dialog_content = "크오오──!",
  ui_story_10_2_2_10_dialog_content = "어라? 왜 도망치는 거지? 가지 마...",
  ui_story_10_2_2_11_dialog_content = "도망칠 수 있을 것 같냐!",
  ui_story_10_2_2_12_dialog_content = "끄으으...",
  ui_story_10_2_2_13_dialog_content = "이 암귀 놈들 뭔가 이상한데. 우릴 못 보는 것 같잖아. 꼭 눈이 먼 것처럼 말이야.",
  ui_story_10_2_2_14_dialog_content = "확실히 뭔가 이상해. 원래라면 암귀는 우릴 보자마자 달려들었어야 해.",
  ui_story_10_2_2_15_dialog_content = "하지만 이 암귀들은 우릴 공격하는 것보다...",
  ui_story_10_2_2_16_dialog_content = "오히려 도망치는 데 정신이 팔린 것 같아.",
  ui_story_10_2_2_17_dialog_content = "그럼 잘 됐네. 이 조무래기들은 무시하고 바로 노라 녀석부터 찾아서 결판을 내자고.",
  ui_story_10_2_2_18_dialog_content = "지금 이 상황도 노라와 관계가 있을지도 몰라. 조심하는 게 좋아.",
  ui_story_10_2_2_19_dialog_content = "응, 맞아.",
  ui_story_10_2_2_20_dialog_content = "가능하면 암귀들을 쓰러트리면서 이동하는 게 좋겠어. 그냥 놔뒀다간...",
  ui_story_10_2_2_21_dialog_content = "놓쳤던 암귀들이 다시 몰려와서 우리가 포위당할 수도 있으니까.",
  ui_story_10_2_2_22_dialog_content = "PlayerName, 지금 이곳의 다크매터 때문에 많이 힘들다는 거 알아.",
  ui_story_10_2_2_23_dialog_content = "하지만 지금 상황을 더 파악하려면 네 감응 능력의 도움이 필요할 것 같아.",
  ui_story_10_2_2_24_dialog_content = "한번 해볼게.",
  ui_story_10_2_2_25_dialog_content = "......",
  ui_story_10_2_2_26_dialog_content = "<color=#e8d9bb>휘잉── 휘이잉──</color>",
  ui_story_10_2_2_27_dialog_content = "으으, 웬 바람이 이렇게...",
  ui_story_10_2_2_28_dialog_content = "쉿! 조용히 있어. PlayerName 녀석이 집중하고 있는 거 안 보여?",
  ui_story_10_2_2_29_dialog_content = "하지만... 대장 목소리가 나보다 크면서...",
  ui_story_10_2_2_30_dialog_content = "...쉿.",
  ui_story_10_2_2_31_dialog_content = "(다크매터...)",
  ui_story_10_2_2_32_dialog_content = "(다크매터가... 모두 한 방향으로 모여들고 있어.)",
  ui_story_10_2_2_33_dialog_content = "(역겨워... 옅어졌다 짙어졌다... 도저히 참을 수가 없어.)",
  ui_story_10_2_2_34_dialog_content = "(암귀... 암귀...)",
  ui_story_10_2_2_35_dialog_content = "(전부 암귀투성이야.)",
  ui_story_10_2_2_36_dialog_content = "(못 참겠어... 비린내가 나...)",
  ui_story_10_2_2_37_dialog_content = "(그리고...)",
  ui_story_10_2_2_38_dialog_content = "<color=#e8d9bb>아그작...</color>",
  ui_story_10_2_2_39_dialog_content = "(무슨 소리지?)",
  ui_story_10_2_2_40_dialog_content = "<color=#e8d9bb>아그작.</color>",
  ui_story_10_2_2_41_dialog_content = "(이를 가는 건가?)",
  ui_story_10_2_2_42_dialog_content = "<color=#e8d9bb>아그작.</color>",
  ui_story_10_2_2_43_dialog_content = "(아니야. 뭔가를 씹는 소리야...)",
  ui_story_10_2_2_44_dialog_content = "<color=#e8d9bb>아그작.</color>",
  ui_story_10_2_2_45_dialog_content = "(미끄럽고... 냄새 나는 뭔가가 있어...)",
  ui_story_10_2_2_46_dialog_content = "(비린내가 너무 심해... 괴로워...)",
  ui_story_10_2_2_47_dialog_content = "(그리고 온몸에 통증이...)",
  ui_story_10_2_2_48_dialog_content = "(뭔가가... 이랑 혀에 느껴져...)",
  ui_story_10_2_2_49_dialog_content = "(뭔가 진흙 같은 게... 목구멍으로 넘어가고 있잖아?!)",
  ui_story_10_2_2_50_dialog_content = "쳇...",
  ui_story_10_2_2_51_dialog_content = "암귀는 정말 맛이 없다니까.",
  ui_story_10_3_1_1_dialog_content = "우욱──!",
  ui_story_10_3_1_2_dialog_content = "PlayerName! 어, 어서 감응을 멈춰!",
  ui_story_10_3_1_3_dialog_content = "우웨엑... 커억, 컥...",
  ui_story_10_3_1_4_dialog_content = "머... 멈췄어... 욱!",
  ui_story_10_3_1_5_dialog_content = "어떻게 된 거야? 대체 뭘 감응했길래 그런 꼴이 된 거야?",
  ui_story_10_3_1_6_dialog_content = "콜록, 콜록, 미안... 정말 못 볼 걸 봐서... 우욱!",
  ui_story_10_3_1_7_dialog_content = "휴, 됐으니까 일단 숨이나 돌려 보라고.",
  ui_story_10_3_1_8_dialog_content = "음... 일단 다 토해내고 나서 다시 말하는 게 좋을 것 같아. 안 그러면 목이 막힐지도 몰라.",
  ui_story_10_3_1_9_dialog_content = "바이스 씨, 아이테르가 감응 능력을 쓸 때마다 이렇게 부작용이 심한 거야?",
  ui_story_10_3_1_10_dialog_content = "아니, 전에는 안 그랬는데... 아마 지금은...",
  ui_story_10_3_1_11_dialog_content = "엄청나게 나쁜 걸 느껴서 그런 것 같아.",
  ui_story_10_3_1_12_dialog_content = "크르르...",
  ui_story_10_3_1_13_dialog_content = "이리 와. 명령이야.",
  ui_story_10_3_1_14_dialog_content = "끄르르...",
  ui_story_10_3_1_15_dialog_content = "기어서 들어가.",
  ui_story_10_3_1_16_dialog_content = "끄륵...",
  ui_story_10_3_1_17_dialog_content = "좋아.",
  ui_story_10_3_1_18_dialog_content = "끼이익!",
  ui_story_10_3_1_19_dialog_content = "닥쳐... 날 누르고 있잖아...",
  ui_story_10_3_1_20_dialog_content = "끄윽... 캬악!",
  ui_story_10_3_1_21_dialog_content = "......",
  ui_story_10_3_1_22_dialog_content = "이제 좀 얌전해졌네.",
  ui_story_10_3_1_23_dialog_content = "노라... 들어올 때 좀 조심하라고 시킬 순 없어?",
  ui_story_10_3_1_24_dialog_content = "온몸이 아파 죽겠다고... 그런 와중에 이 썩은내 나는 녀석한테 깔려야 하는 거야?",
  ui_story_10_3_1_25_dialog_content = "뭐라고? 잘 안 들리네.",
  ui_story_10_3_1_26_dialog_content = "헛소리 집어치워.",
  ui_story_10_3_1_27_dialog_content = "내가 네 말이 들리는데... 내가 소리치는 걸 네가 어떻게 못 들을 수가 있어?",
  ui_story_10_3_1_28_dialog_content = "네가 소리치는 거랑 나한테 들리는 거랑 관계가 있을까?",
  ui_story_10_3_1_29_dialog_content = "잡담이라도 해서 네게 더 먹일 수 있다면, 몇 마디 정도 더 해줄 수 있어.",
  ui_story_10_3_1_30_dialog_content = "이런 역겨운 걸 대체 누가 기분 좋게 먹겠냐고...",
  ui_story_10_3_1_31_dialog_content = "분노는 네 성장을 촉진시킬 거야. 넌 그걸 다루는 법을 배워야 해.",
  ui_story_10_3_1_32_dialog_content = "암귀를 진짜 음식처럼 먹는다고 생각하지 말고, 적당히 씹어서 다크매터만 흡수하는 거야.",
  ui_story_10_3_1_33_dialog_content = "그게 지금 너한테 가장 손쉬운 방법이거든.\n설마 지금까지 먹는 법도 못 배웠다고 말할 건 아니겠지?",
  ui_story_10_3_1_34_dialog_content = "무시하지 마...",
  ui_story_10_3_1_35_dialog_content = "근데 이 「씨앗」들... 너무 딱딱해서 못 씹겠어.",
  ui_story_10_3_1_36_dialog_content = "껍데기만 딱딱할 뿐이야. 갈아서 부숴버려.\n네 입안에 자란 암귀의 이빨은 네가 생각하는 것보다 훨씬 튼튼하니까.",
  ui_story_10_3_1_37_dialog_content = "알고 있다고... 그냥 불평하려던 거지.",
  ui_story_10_3_1_38_dialog_content = "......",
  ui_story_10_3_1_39_dialog_content = "부상을 회복한 뒤로 기분이 꽤 좋아진 모양이네.",
  ui_story_10_3_1_40_dialog_content = "아무래도 「칭찬」을 좀 해줄 필요가 있겠는걸.",
  ui_story_10_3_1_41_dialog_content = "갑자기 무슨 헛소리야?",
  ui_story_10_3_1_42_dialog_content = "네 안목이 생각보다 나쁘지 않았거든. PlayerName 그 녀석, 쓸모가 있겠어.",
  ui_story_10_3_1_43_dialog_content = "비록 초대에는 실패했지만, 녀석을 살려두면 네가 계속해서 성장하도록 자극할 수 있을 테니까.",
  ui_story_10_3_1_44_dialog_content = "녀석과 백야성한테 제대로 한 방 먹어서 너도 무척 기쁘겠지?",
  ui_story_10_3_1_45_dialog_content = "한 마디만 더 지껄여 봐... 내가 나가면 네 혀부터 뽑아버릴 테니까...",
  ui_story_10_3_1_46_dialog_content = "조금 놀렸다고 그것도 못 참으면 안 되지. 넌 정신력도 좀 단련할 필요가 있어.",
  ui_story_10_3_1_47_dialog_content = "대체 하고 싶은 말이 뭐야?",
  ui_story_10_3_1_48_dialog_content = "그러니까 말이야... 네 오랜 친구 PlayerName 녀석이 이미 디바우러호에 들어와 있거든.",
  ui_story_10_3_1_49_dialog_content = "그 아이테르는 무슨 일이 있어도 널 죽여서 자신의 복수를 마치고 싶어 할 거야.",
  ui_story_10_3_1_50_dialog_content = "......",
  ui_story_10_3_1_51_dialog_content = "그러니까 내가 시간을 벌어줄게.",
  ui_story_10_3_1_52_dialog_content = "네가 에너지를 흡수하고 탈피를 마칠 때까지, 내가 녀석들을 붙잡아 볼게.",
  ui_story_10_3_1_53_dialog_content = "하지만 우린 시간이 많지 않아.",
  ui_story_10_3_1_54_dialog_content = "<color=#e8d9bb>아그작.</color>",
  ui_story_10_3_1_55_dialog_content = "그러니 네가 그때까지 「<color=#FFB400>보완</color>」을 마칠 수 있길 바랄게.",
  ui_story_10_3_1_56_dialog_content = "부디 네 디바우러호 같은 신세는 되지 말라고...",
  ui_story_10_3_1_57_dialog_content = "겨우 백야성에 갔더니만 한 방에 커다란 구멍이 나 버렸잖아.",
  ui_story_10_3_1_58_dialog_content = "닥쳐...",
  ui_story_10_3_1_59_dialog_content = "굳이 또 말할 거 없잖아.",
  ui_story_10_3_1_60_dialog_content = "넌 적을 과소평가하는 게 문제야.",
  ui_story_10_3_1_61_dialog_content = "......",
  ui_story_10_3_1_62_dialog_content = "내가 유일하게 실수한 건... 내가 PlayerName 녀석의 머리를 너무 과대평가했다는 거야.",
  ui_story_10_3_1_63_dialog_content = "기회를 잡고 힘을 얻어서 강자가 될 수 있었는데...",
  ui_story_10_3_1_64_dialog_content = "녀석한텐 고작 나한테 화풀이나 하는 게 그것보다 더 중요했단 말이야?",
  ui_story_10_3_1_65_dialog_content = "정말 우습다니까... 오로리안 몇 명이랑 알게 됐다고\n자기가 강해졌다고 착각이라도 한 거냐고...",
  ui_story_10_3_1_66_dialog_content = "그 녀석은 내가 자비를 베풀 때마다 몇 번이고 날 실망시켰어...",
  ui_story_10_3_1_67_dialog_content = "그 더러운 아이테르들처럼 세상 물정도 모르고 말이야...",
  ui_story_10_3_1_68_dialog_content = "전부 얼간이들이라고.",
  ui_story_10_3_1_69_dialog_content = "그럼 결국... 다 죽여버리는 수밖에.",
  ui_story_10_3_1_70_dialog_content = "난 녀석이 대가를 치르고, 후회와 두려움 속에서 죽게 만들 거야.",
  ui_story_10_3_1_71_dialog_content = "좀 괜찮아진 거냐? 네가 감응으로 뭘 본 건지 말해봐.",
  ui_story_10_3_1_72_dialog_content = "슈모르가 암귀를 먹고 있었어...",
  ui_story_10_3_1_73_dialog_content = "하아? 뭔 대단한 걸 봤나 했더니만, 고작 암귀를 먹는 거였냐.",
  ui_story_10_3_1_74_dialog_content = "녀석이 심각한 상처를 입고 며칠 만에 깨어났다면, 꽤나 배가 고팠을 테니 말이야.",
  ui_story_10_3_1_75_dialog_content = "암귀를 먹을 수 있다고? 죽으면 바로 가루가 되어 버리잖아?",
  ui_story_10_3_1_76_dialog_content = "살아있을 때 씹으면 된다더군. 듣기로는 짐승의 토사물보다 더 맛이 끔찍하다고 하더라고.",
  ui_story_10_3_1_77_dialog_content = "암귀를 먹을 수 있는 놈이라면 미각도 머리도 맛이 간 게 분명하다니까.",
  ui_story_10_3_1_78_dialog_content = "지금까지의 정보에 따르면 암귀는 음식을 섭취할 필요도 없고, 동종포식 습성도 없어.",
  ui_story_10_3_1_79_dialog_content = "왠지 녀석은... 에너지를 흡수하고 있는 것 같아... 아주 짙은 다크매터가 느껴져.",
  ui_story_10_3_1_80_dialog_content = "그렇게 해서 자길 치료하려는 거야... 서두르는 게 좋겠어... 우욱...",
  ui_story_10_3_1_81_dialog_content = "으... 말만 들어도 벌써 토할 것 같아.",
  ui_story_10_3_1_82_dialog_content = "난 이제... 더 게워낼 것도 없다고... 우욱...",
  ui_story_10_3_1_83_dialog_content = "으, 그래도 너무 끔찍해. 괜찮은 거 맞아? 온몸이 떨리고 있잖아.",
  ui_story_10_3_1_84_dialog_content = "...일단 가자.",
  ui_story_10_3_1_85_dialog_content = "잠깐만, 너 지금 제대로 서는 것도 힘들잖아! 앉아서 5분만 쉬었다 가자!",
  ui_story_10_3_1_86_dialog_content = "5분만!",
  ui_story_10_3_1_87_dialog_content = "난 괜찮아... 지휘는 할 수 있으니까...",
  ui_story_10_3_1_88_dialog_content = "됐어. 쉬라고 하면 쉬어.",
  ui_story_10_3_1_89_dialog_content = "너희가 쫓는 그 슈모르가 지금 치료 중이라면, 어차피 못 도망칠 거다.",
  ui_story_10_3_1_90_dialog_content = "자, 마셔라. 뜨거운 물이다.",
  ui_story_10_3_1_91_dialog_content = "뭐라도 좀 먹어서 에너지를 보충해야 되지 않겠어? 여기 레디젤 특산품도 있다.",
  ui_story_10_3_1_92_dialog_content = "보프, 도마뱀 육포도 각자 먹을 수 있게 좀 나눠 줘!",
  ui_story_10_3_1_93_dialog_content = "응, 맞아. 슈모르도 에너지를 보충하고 있는데, 우리도 뭔가 준비를 해야지. 좀 먹어 둬.",
  ui_story_10_3_1_94_dialog_content = "너무 긴장을 풀진 마.",
  ui_story_10_3_1_95_dialog_content = "하나만 줘. 난 앞쪽을 정찰하고 올 테니까.",
  ui_story_10_3_1_96_dialog_content = "아, 알겠어. 이거 정말 편해. 뜯으면 바로 먹을 수 있어.\n매콤해서 맛도 좋고 체력 보충에도 도움이 될 거야.",
  ui_story_10_3_1_97_dialog_content = "PlayerName, 봐. 카렌도 먹잖아. 그러니까 너도 하나 먹어.",
  ui_story_10_3_1_98_dialog_content = "방금 토해서 위가 텅 비었을 거잖아. 배고픈 채로는 싸울 수 없어.",
  ui_story_10_3_1_99_dialog_content = "미안... 곧바로 뭘 먹는 건 힘들 것 같아... 잘못하면 또 토할지도 모르니까.",
  ui_story_10_3_1_100_dialog_content = "에? 그렇구나... 그럼 물을 좀 더 마실래?",
  ui_story_10_3_1_101_dialog_content = "자, 여기 한 병 더 있다.",
  ui_story_10_3_1_102_dialog_content = "앞쪽에 암귀 무리가 움직이고 있는 것 같아. 곧 우리 쪽으로 올 거야.",
  ui_story_10_3_1_103_dialog_content = "PlayerName, 무리해서 지휘할 필요는 없어.",
  ui_story_10_3_1_104_dialog_content = "우리가 싸우는 동안 숨 좀 돌리고 있어.",
  ui_story_10_3_1_105_dialog_content = "그래, 암귀 놈들이 못 오게 막아줄 테니까. 걱정 말고 여기 앉아 있으라고!",
  ui_story_10_3_1_106_dialog_content = "암귀가 나타났다. 모두 준비해!",
  ui_story_10_3_2_1_dialog_content = "PlayerName! 방금 왜 또 지휘한 거야?",
  ui_story_10_3_2_2_dialog_content = "지금이라도 좀 쉬어두라고 했잖아...",
  ui_story_10_3_2_3_dialog_content = "난 괜찮아... 이미 많이 나아졌어.",
  ui_story_10_3_2_4_dialog_content = "게다가 너희랑 감응하는 게 암귀한테 감응하는 것보단 훨씬 나으니까.",
  ui_story_10_3_2_5_dialog_content = "이 암귀들은... 공격성이 다시 생긴 것 같은데?",
  ui_story_10_3_2_6_dialog_content = "그래. 아무래도 모두 쓰러트리면서 가는 게 최선의 선택일 것 같네.",
  ui_story_10_3_2_7_dialog_content = "가자... 난 이제 괜찮으니까.",
  ui_story_10_3_2_8_dialog_content = "미안... 괜히 내가 감응을 해보라고 해서...",
  ui_story_10_3_2_9_dialog_content = "네 잘못이 아냐.",
  ui_story_10_3_2_10_dialog_content = "방금 그건 암귀를 먹는 감각이 너무 생생하게 느껴져서, 내가 적응을 못 한 것뿐이야.",
  ui_story_10_3_2_11_dialog_content = "앞으로는 그렇게 심하진 않을 거야.",
  ui_story_10_3_2_12_dialog_content = "애송이, 전보다 꽤 강해진 것 같잖아?",
  ui_story_10_3_2_13_dialog_content = "그나저나, 방금 감응할 때 노라의 기운도 있었나?",
  ui_story_10_3_2_14_dialog_content = "아깐 좀 흐릿하긴 했지만...",
  ui_story_10_3_2_15_dialog_content = "두 녀석이 같은 곳에 있는 것 같았어.",
  ui_story_10_3_2_16_dialog_content = "가자. 그럼 우린 목적지가 같으니까.",
  ui_story_10_3_2_17_dialog_content = "<color=#e8d9bb>휘잉── 휘이잉──</color>",
  ui_story_10_3_2_18_dialog_content = "이 콜로서스, 안으로 들어갈수록 상태가 더 엉망인걸...",
  ui_story_10_3_2_19_dialog_content = "언제 무너져도 이상하지 않을 것 같아. 콜로서스라면 이렇지 않을 텐데...",
  ui_story_10_3_2_20_dialog_content = "이 녀석은 다모클레스에 맞았으니까.",
  ui_story_10_3_2_21_dialog_content = "게다가 슈모르가 에너지를 빼먹고 있어.",
