  ui_story_10_3_2_24_dialog_content = "자기 손으로 자기 콜로서스를 「죽였다」는 거야?",
  ui_story_10_3_2_25_dialog_content = "암귀는 동족을 잡아먹지 않는다. 하지만 녀석은 먹고 있지.\n그 녀석은 그런 역겨운 짓조차 할 수 있다는 거다.",
  ui_story_10_3_2_26_dialog_content = "그런 녀석이 자기 손으로 콜로서스를 박살 내더라도 이상할 게 없잖아?\n그렇다면 에너지 흡수 정도는 일도 아니라고.",
  ui_story_10_3_2_27_dialog_content = "그 녀석이 얼마나 끔찍한 존재인지는 PlayerName 네가 우리보다 훨씬 더 잘 알고 있겠지.",
  ui_story_10_3_2_28_dialog_content = "가자, 녀석이 회복을 마칠 때까지 내버려 둬선 안 돼...",
  ui_story_10_7_1_1_dialog_content = "다크매터를 강화하기 위해서는 직접 흡수하는 것도 좋은 방법이지.",
  ui_story_10_7_1_2_dialog_content = "하지만 모든 암귀가 다크매터를 흡수하는 능력을 터득하진 못해...",
  ui_story_10_7_1_3_dialog_content = "......",
  ui_story_10_7_1_4_dialog_content = "아, 벌써 잠든 거야? 아무래도 이번 실험은 성공할지도 모르겠네.",
  ui_story_10_7_1_5_dialog_content = "지난번에 마지막으로 나랑 힘에 대해 이야기했던 게 누구였더라... 아, 생각났다.",
  ui_story_10_7_1_6_dialog_content = "백야성에서 온... 벌레 꼬리가 달린 애들... 이름이...",
  ui_story_10_7_1_7_dialog_content = "「<color=#FFB400>보레돔</color>」이었나?",
  ui_story_10_7_1_8_dialog_content = "<color=#e8d9bb>우우── 우우우──</color>",
  ui_story_10_7_1_9_dialog_content = "또... 바람 소리인가?",
  ui_story_10_7_1_10_dialog_content = "아니야... 이건...",
  ui_story_10_7_1_11_dialog_content = "우우... 흐윽...",
  ui_story_10_7_1_12_dialog_content = "우는 소리?",
  ui_story_10_7_1_13_dialog_content = "암귀도 운단 말이야?",
  ui_story_10_7_1_14_dialog_content = "물러서. 녀석이 나타났어.",
  ui_story_10_7_1_15_dialog_content = "이, 이 암귀... 엄청 끔찍하게 생겼잖아.",
