  ui_story_10_7_1_18_dialog_content = "이 모습, 나무뿌리 같은 팔다리... 그리고 이 목소리... 내가 떠올린 게 맞다면...",
  ui_story_10_7_1_19_dialog_content = "<color=#FFB400>스예트</color>, <color=#FFB400>샤를</color> 자매야. 마지막에 저런 괴물이 됐었잖아.",
  ui_story_10_7_1_20_dialog_content = "자매? ...근데 암귀는 한 마리인데?",
  ui_story_10_7_1_21_dialog_content = "우린 두 사람이 강제로 융합되는 걸 직접 봤어.",
  ui_story_10_7_1_22_dialog_content = "맞아. 「그분께서 우리에게 새로운 힘을 주셨다」고 했었지.\n그리고... 결국 저런 모습이 됐고 말이야.",
  ui_story_10_7_1_23_dialog_content = "흑... 흐윽...",
  ui_story_10_7_1_24_dialog_content = "저기, 우리한테 다가오는 것 같은데? 조금 느리긴 한데... 먼저 공격해야 하나?",
  ui_story_10_7_1_25_dialog_content = "흐윽... 흑... 죽여...",
  ui_story_10_7_1_26_dialog_content = "죽여? 방금 「죽여」라고 말한 거야? 우릴 죽이려는 건가?",
  ui_story_10_7_1_27_dialog_content = "아니... 고통에서 해방시켜 달라는 거야.",
  ui_story_10_7_1_28_dialog_content = "그때도 그랬으니까... 「<color=#FFB400>우릴 죽여</color>」달라고.",
  ui_story_10_7_1_29_dialog_content = "하지만 지금도 여전히 고통 속에 갇혀 있어...",
  ui_story_10_7_1_30_dialog_content = "죽은 자의 시체를 가져다 부활시켜 또 사용한 거야.",
  ui_story_10_7_1_31_dialog_content = "이런 미친 짓을 거리낌 없이 자행하다니, 절대 용서할 수 없어!",
  ui_story_10_7_1_32_dialog_content = "흐아아──!",
  ui_story_10_7_1_33_dialog_content = "저들에겐 이미 이성이 존재하지 않아. 이대로는 그저 고통만 길어질 뿐이야.",
  ui_story_10_7_1_34_dialog_content = "쓰러트려!",
  ui_story_10_7_1_35_dialog_content = "그리고 이 모든 비극의 주범을 지옥으로 보내는 거야!",
  ui_story_10_7_2_1_dialog_content = "이, 이제 끝난 건가?",
  ui_story_10_7_2_2_dialog_content = "그래, 저들은 죽었어... 그것도 두 번째로...",
  ui_story_10_7_2_3_dialog_content = "바이스, PlayerName. 불에 탈 만한 걸 찾아와 줘.",
  ui_story_10_7_2_4_dialog_content = "저들을 화장해 주겠어.",
  ui_story_10_7_2_5_dialog_content = "부디 <color=#FFB400>거츠더</color>처럼, 안식을 얻을 수 있기를...",
  ui_story_10_7_2_6_dialog_content = "응, 찾아볼게.",
  ui_story_10_7_2_7_dialog_content = "거츠더란 건 또 누구지?",
  ui_story_10_7_2_8_dialog_content = "백야성의 기사였어. 저 스예트의 연인이기도 했고.",
  ui_story_10_7_2_9_dialog_content = "스예트와 함께 암귀 놈들에게 가담했지만, 결국...",
  ui_story_10_7_2_10_dialog_content = "자신을 희생해서 우릴 지켰어.",
  ui_story_10_7_2_11_dialog_content = "또 백야성이냐... 지금 상황에서 마땅한 질문은 아니긴 한데, 그래도 난 물어야겠어.",
  ui_story_10_7_2_12_dialog_content = "왜 너희 백야성엔 암귀의 편에 서려는 사람이 있는 거지?",
  ui_story_10_7_2_13_dialog_content = "거기 살면 암귀에게 습격당할 일도 없고, 먹고 사는 걱정도 없을 텐데 말이야.",
  ui_story_10_7_2_14_dialog_content = "아무리 생각해도 말이 안 되지 않아?",
  ui_story_10_7_2_15_dialog_content = "사메야마, 지금 우린 같은 목표를 위해 함께 싸우는 동료들이야.",
  ui_story_10_7_2_16_dialog_content = "괜한 말은 하지 말아줘.",
  ui_story_10_7_2_17_dialog_content = "괜찮아.",
  ui_story_10_7_2_18_dialog_content = "나도 이때 아니면 언제 물어보겠어? 백야성 사람을 만날 기회가 많은 것도 아니잖아.",
  ui_story_10_7_2_19_dialog_content = "참, 딱히 꺼리는 게 아니라면 내 불을 사용해도 좋아. 저들을 화장하는 걸 도와줄 테니 말이야.",
  ui_story_10_7_2_20_dialog_content = "이건 내가 책임져야 할 일이야, 사메야마. 당신이 걱정할 필요는 없어.",
  ui_story_10_7_2_21_dialog_content = "물론 당신이 나설 필요도 없고.",
  ui_story_10_7_2_22_dialog_content = "나도 나설 생각 없다고. 네가 자기 책임이 뭔지 알고 있다면 그걸로 됐어.",
  ui_story_10_7_2_23_dialog_content = "그럼 난 망이나 보러 간다.",
  ui_story_10_7_2_24_dialog_content = "......",
  ui_story_10_7_2_25_dialog_content = "저기... 그럼 나도 가서 불을 피울 만한 걸 찾아볼게...",
  ui_story_10_7_2_26_dialog_content = "사메야마 대장은 가끔 과격할 때도 있고... 하고 싶은 말은 뭐든 하는 스타일이지만...",
  ui_story_10_7_2_27_dialog_content = "악의는 없다는 점은 알아줘.",
  ui_story_10_7_2_28_dialog_content = "응, 나도 알 수 있어.",
  ui_story_10_7_2_29_dialog_content = "이제 불을 붙이자.",
  ui_story_10_7_2_30_dialog_content = "만물은 백야 아래에...",
  ui_story_10_7_2_31_dialog_content = "스예트, 샤를, 자유를 추구하다 길을 잃은 자들이여.\n부디 안식을 얻고 다시 자유를 향해 날아가길.",
  ui_story_10_7_2_32_dialog_content = "심판은 이들을 미혹한 자에게 향해야만 해.",
  ui_story_10_7_2_33_dialog_content = "이제 매장해야 할 것은 모든 것의 원흉, <color=#FFB400>슈모르</color>야.",
  ui_story_10_7_2_34_dialog_content = "어느 쪽으로 가야 하는지 내가 길을 찾아볼게...",
  ui_story_10_7_2_35_dialog_content = "PlayerName? 또 감응 능력을 쓰기 시작한 거야?",
  ui_story_10_7_2_36_dialog_content = "응...",
  ui_story_10_7_2_37_dialog_content = "어서 멈춰! 또 영향을 받기라도 하면...",
  ui_story_10_7_2_38_dialog_content = "크윽...",
  ui_story_10_7_2_39_dialog_content = "PlayerName?!",
  ui_story_10_7_2_40_dialog_content = "선생님...",
  ui_story_10_7_2_41_dialog_content = "잠깐만... 뭔가가 보여...",
  ui_story_10_7_2_42_dialog_content = "난 괜찮아. 지금 보이는 게 뭔지 알아내야만 해... 걱정하지 마...",
  ui_story_10_7_2_43_dialog_content = "한드로 선생님...",
  ui_story_10_7_2_44_dialog_content = "대체 무슨 짓을 한 거냐? 어째서 그런 거냐?!",
  ui_story_10_7_2_45_dialog_content = "왜 친구들을 죽게 만든 거냐! 어서 말해라!",
  ui_story_10_7_2_46_dialog_content = "선생님, 전 아무것도 안 했어요.",
  ui_story_10_7_2_47_dialog_content = "전 그저 제 용기를 증명하려고 했을 뿐이라구요...",
  ui_story_10_7_2_48_dialog_content = "지금 그게 무슨 소리냐!",
  ui_story_10_7_2_49_dialog_content = "그저 네 용기를 증명하려고 친구들을 죽게 만들었다고?!",
  ui_story_10_7_2_50_dialog_content = "또 그러시네요. 선생님은 매번 남의 말만 듣고 멋대로 판단하죠...",
  ui_story_10_7_2_51_dialog_content = "?!",
  ui_story_10_7_2_52_dialog_content = "그래, 어디 말해 봐라! 대체 어떻게 된 거냐?",
  ui_story_10_7_2_53_dialog_content = "녀석들이 저한테 내기를 하자고 한 거예요. 전 그저 하자는 대로 했을 뿐이구요!",
  ui_story_10_7_2_54_dialog_content = "그 바보들은 자기들이 암귀한테 충분히 도전할 힘이 있다고 생각했어요.",
  ui_story_10_7_2_55_dialog_content = "그래서 전 하겠다고 했죠. 어디 누가 밖에 나갈 용기가 있는지 보자고요.",
  ui_story_10_7_2_56_dialog_content = "겨우... 그런 이유로 말이냐...",
  ui_story_10_7_2_57_dialog_content = "선생님, 우린 그냥 바깥에 나갔다 오려고만 한 거지, 정말로 암귀를 만날 줄은 아무도 몰랐어요...",
  ui_story_10_7_2_58_dialog_content = "그 녀석들은 절 따돌리고 무시했어요!\n제가 감응 능력을 잘 다루지 못한다는 이유만으로요!",
  ui_story_10_7_2_59_dialog_content = "선생님은 매번 다른 사람의 잠재력을 무시하면 안 된다고 하셨지만...\n그 녀석들이 귀담아들었을 것 같아요?",
  ui_story_10_7_2_60_dialog_content = "전혀 안 들었다구요!",
  ui_story_10_7_2_61_dialog_content = "그래서 전 끝내 증명했어요! 살아남은 건 저예요!",
  ui_story_10_7_2_62_dialog_content = "제가 가장 강하다구요!",
  ui_story_10_7_2_63_dialog_content = "휴...",
  ui_story_10_7_2_64_dialog_content = "네가 살아서 돌아온 건... 네가 운이 좋았을 뿐이야!",
  ui_story_10_7_2_65_dialog_content = "슈모르, 이미 여러 번 네게 말하지 않았니.",
  ui_story_10_7_2_66_dialog_content = "우리 아이테르는 항상 평화를 사랑해 온 종족이라고 말이야.",
  ui_story_10_7_2_67_dialog_content = "우린 그 누구한테도 그 무얼 증명하려 들 필요가 없어.",
  ui_story_10_7_2_68_dialog_content = "힘이 강하고 약하고가 중요한 게 아니야.\n중요한 건 서로를 돕고 함께 외부의 위험에 맞서는 거란 말이다.",
  ui_story_10_7_2_69_dialog_content = "맞선다구요? 선생님, 그게 고작 헤븐즈 밸리 안에 틀어박혀서,\n밖에 나갈 엄두도 못 내는 걸 말하는 건 아니죠?",
  ui_story_10_7_2_70_dialog_content = "그런 게 아니다. 내가 수없이 경고했지 않니...",
  ui_story_10_7_2_71_dialog_content = "헤븐즈 밸리 밖에는 수많은 암귀들이 있다.",
  ui_story_10_7_2_72_dialog_content = "우린 오로리안과 달리 루미나를 이용해 싸우는 능력이 없어.",
  ui_story_10_7_2_73_dialog_content = "그래서 조금이라도 강한 암귀와 마주친다면 맞서 싸울 방법이 없단 말이다.",
  ui_story_10_7_2_74_dialog_content = "하지만 우리에겐 헤븐즈 밸리와 콜로서스가 있다.",
  ui_story_10_7_2_75_dialog_content = "헤븐즈 밸리는 우릴 지켜주고 있고, 콜로서스가 하늘로 날아오르면 암귀들의 공격을 피할 수 있다.",
  ui_story_10_7_2_76_dialog_content = "가장 중요한 건 우리에게 <color=#FFB400>감응 능력</color>이 있다는 거다. 이건 아이테르만의 힘이니까.",
  ui_story_10_7_2_77_dialog_content = "우린 빛의 궤적을 느낄 수 있고, 동료의 생각을 읽고, 위험한 적을 감지할 수 있지.",
  ui_story_10_7_2_78_dialog_content = "하지만 너흰 아직 경험이 부족하고, 능력도 강하지 않아.\n그래서 감응 능력으로 정찰을 하거나 위험을 피할 방법이 없다.",
  ui_story_10_7_2_79_dialog_content = "그런 너희가 헤븐즈 밸리 밖으로 나간다면, 죽으러 가는 거나 다름이 없단 말이다!",
  ui_story_10_7_2_80_dialog_content = "정찰하고... 피하고... 여기 사람들은 다 그런 식일 뿐이죠!",
  ui_story_10_7_2_81_dialog_content = "만에 하나 암귀가 여기까지 들이닥쳤을 때 어떻게 할지는 생각해 본 적이나 있는 건가요?!",
  ui_story_10_7_2_82_dialog_content = "헤븐즈 밸리가 우릴 영원히 보호해줄 수 있을 것 같아요?!",
  ui_story_10_7_2_83_dialog_content = "그럼 그땐 어떻게 할 건데요? 콜로서스를 타고 도망칠 건가요? 어디로 가는데요?",
  ui_story_10_7_2_84_dialog_content = "「나가자마자 죽을지도 모르는」 바깥으로?",
  ui_story_10_7_2_85_dialog_content = "누가 「나가자마자 죽을지도」 모른다고 했다는 거냐!",
  ui_story_10_7_2_86_dialog_content = "내가 몇 번이나 말했니, 콜로서스가 있는 한...",
  ui_story_10_7_2_87_dialog_content = "됐어요... 저도 알고 있으니까요.",
  ui_story_10_7_2_88_dialog_content = "선생님, 우리가 평화를 사랑하는 건... 우리가 맞서 싸울 힘이 없어서일 뿐이에요.",
  ui_story_10_7_2_89_dialog_content = "휴... 넌 아직 이해하지 못했을 뿐이다. 널 탓하고 싶진 않아.",
  ui_story_10_7_2_90_dialog_content = "너도 언젠가는 이해할 수 있을 거다...",
  ui_story_10_7_2_91_dialog_content = "전 모르겠어요... 그리고 앞으로도 모를 거예요...",
  ui_story_10_7_2_92_dialog_content = "가세요, 선생님.",
  ui_story_10_7_2_93_dialog_content = "전 마음을 바꾸지 않을 거니까요.",
  ui_story_10_7_2_94_dialog_content = "아무래도 아직 안정의 시간이 필요한 것 같구나.",
  ui_story_10_7_2_95_dialog_content = "장로님께선 이 문제를 조사하기 위해 사람을 보냈다.",
  ui_story_10_7_2_96_dialog_content = "난 네가 고의로 친구들을 죽게 만든 게 아니라고 믿는다...",
  ui_story_10_7_2_97_dialog_content = "하지만 장로님들이 네게 내릴 징계를 정하기 전까지, 난 너를 이곳에 가둬둘 수밖에 없다.",
  ui_story_10_7_2_98_dialog_content = "그리고 이 책은 네 친구가 주는 거다. 나한테 전해달라고 부탁하더구나.",
  ui_story_10_7_2_99_dialog_content = "친구요? 누군데요? 전 그런 거 없어요...",
  ui_story_10_7_2_100_dialog_content = "<color=#FFB400>멘델슨</color>이 준 거다. 그 아이는 널 무척 걱정하고 있단다.\n그 아이도 전에 성적이 좋지 않았었지.",
  ui_story_10_7_2_101_dialog_content = "난 그 애라면 네 상황을 이해해 주고, 너와 친구가 되어줄 거라고 생각한다.",
  ui_story_10_7_2_102_dialog_content = "절 걱정한다구요?",
  ui_story_10_7_2_103_dialog_content = "슈모르... 사람들은 모두 널 좋아한단다. 언젠가는 너도 그걸 깨달았으면 좋겠구나.",
  ui_story_10_7_2_104_dialog_content = "격리와 금식 기간 동안 충분히 반성하거라.\n부디 너에 대한 사람들의 기대를 저버리지 않길 바란다.",
  ui_story_10_7_2_105_dialog_content = "......",
  ui_story_10_7_2_106_dialog_content = "「<color=#FFB400>모두가 날 좋아한다고</color>」...?",
  ui_story_10_7_2_107_dialog_content = "그런 거짓말, 이젠 지긋지긋해...",
  ui_story_10_7_2_108_dialog_content = "......",
  ui_story_10_7_2_109_dialog_content = "책은 또 왜 주는 건데...",
  ui_story_10_7_2_110_dialog_content = "<color=#FFB400>《아이다와 콜로서스》</color>?!",
  ui_story_10_7_2_111_dialog_content = "이딴 걸 왜 준 거야?! 내가 콜로서스와 감응할 수 없는 걸 알면서 놀리는 거야?!",
  ui_story_10_7_2_112_dialog_content = "......",
  ui_story_10_7_2_113_dialog_content = "멘델슨...",
  ui_story_10_7_2_114_dialog_content = "그래, 나보다 머리가 더 빨갛고... 나보다 더 약해 보이는 그 녀석.",
  ui_story_10_7_2_115_dialog_content = "분명히 나처럼 콜로서스와 감응도 못 하는 녀석이겠지.",
  ui_story_10_7_2_116_dialog_content = "<color=#e8d9bb>찰랑──</color>",
  ui_story_10_7_2_117_dialog_content = "뭐야, 이건?",
  ui_story_10_7_2_118_dialog_content = "<color=#FFB400>열쇠</color>?!",
  ui_story_10_7_2_119_dialog_content = "쳇, 이딴 문... 지금의 난 얼마든지 부술 수 있다고...",
  ui_story_10_8_1_1_dialog_content = "「씨앗」의 다크매터를 더욱 강화하고 나면...",
  ui_story_10_8_1_2_dialog_content = "다크매터는 녀석들을 더 편안하게 만들어 주지.",
  ui_story_10_8_1_3_dialog_content = "그리고 점점 판단력을 잃게 돼.",
  ui_story_10_8_1_4_dialog_content = "다크매터를 얻은 실험체는 자신의 강렬한 욕망을 더 쉽게 드러내게 되지.",
  ui_story_10_8_1_5_dialog_content = "이때 그들의 자율적 행동에 가장 쉽게 영향을 미치는 건, 무언가에 대한 집착이야...",
  ui_story_10_8_1_6_dialog_content = "조급해할 거 없다. 감응 능력은 천천히 훈련하면 되니까.",
  ui_story_10_8_1_7_dialog_content = "디바우러호는 특별한 콜로서스다. 단기간에 적합한 조종사를 찾는 건 쉽지 않겠지.",
  ui_story_10_8_1_8_dialog_content = "네가 노력해서 더 강해진다면, 분명히 기회가 올 거다...",
  ui_story_10_8_1_9_dialog_content = "디바우러호... 어디 있지...",
  ui_story_10_8_1_10_dialog_content = "콜로서스...",
  ui_story_10_8_1_11_dialog_content = "콜로서스...",
  ui_story_10_8_1_12_dialog_content = "그냥 콜로서스잖아...",
  ui_story_10_8_1_13_dialog_content = "이건 아니야...",
  ui_story_10_8_1_14_dialog_content = "이것도 아니야...",
  ui_story_10_8_1_15_dialog_content = "내가 뭘 해야 되는 거였지...",
  ui_story_10_8_1_16_dialog_content = "한 대만 남기고, 모든 콜로서스의 동력원을 파괴해라.",
  ui_story_10_8_1_17_dialog_content = "이건 명령이다.",
  ui_story_10_8_1_18_dialog_content = "동력원을 파괴해야 해...",
  ui_story_10_8_1_19_dialog_content = "디바우러호를 빼고... 나머지 모든 콜로서스의 동력원을 파괴하는 거야...",
  ui_story_10_8_1_20_dialog_content = "찾았다...",
  ui_story_10_8_1_21_dialog_content = "의식 모듈만 파괴하면... 앞으로 나한테 복종하겠지?",
  ui_story_10_8_1_22_dialog_content = "<color=#e8d9bb>「엔진 점검... 이상 무. 가동 개시...」</color>",
  ui_story_10_8_1_23_dialog_content = "검고... 강하고... 특별한...",
  ui_story_10_8_1_24_dialog_content = "<color=#e8d9bb>「16%... 33%...」</color>",
  ui_story_10_8_1_25_dialog_content = "<color=#FFB400>내 디바우러호...</color>",
  ui_story_10_8_1_26_dialog_content = "<color=#e8d9bb>「100%, 가동 성공.」</color>",
  ui_story_10_8_1_27_dialog_content = "역시 성공했어!",
  ui_story_10_8_1_28_dialog_content = "디바우러호가 있는 한...",
  ui_story_10_8_1_29_dialog_content = "슈──모──르──",
  ui_story_10_8_1_30_dialog_content = "?!",
  ui_story_10_8_1_31_dialog_content = "모, 목소리가...?!",
  ui_story_10_8_1_32_dialog_content = "내 부름을 듣고도... 조금도 예를 갖추지 않는 것이냐?!",
  ui_story_10_8_1_33_dialog_content = "「예, 부름에 답하겠습니다. 피제로 님」이라고 말해야지!",
  ui_story_10_8_1_34_dialog_content = "네... <color=#FFB400>피, 피제로 님</color>...",
  ui_story_10_8_1_35_dialog_content = "내 말을 그대로 따라 하는 것조차 어려운 것이냐. 정말 우둔하구나...",
  ui_story_10_8_1_36_dialog_content = "크크크, 뭐, 괜찮다. 널 다른 놈들처럼 대하진 않으마.",
  ui_story_10_8_1_37_dialog_content = "넌 이제 우리에게 특별한 존재가 되었으니 말이야.",
  ui_story_10_8_1_38_dialog_content = "넌 이제 막 암귀가 되었으니 아직 이해가 되지 않는 게 많을 것이다.",
  ui_story_10_8_1_39_dialog_content = "이것이 바로 암귀의 의사소통 방식이다.\n나는 어머니께서 우리에게 주신 능력을 사용하고 있는 것이다.",
  ui_story_10_8_1_40_dialog_content = "아무리 멀리 있어도 내 목소리를 네게 직접 전할 수 있지...",
  ui_story_10_8_1_41_dialog_content = "어머니께서 주신 능력...이요?",
  ui_story_10_8_1_42_dialog_content = "너를 선택하고, 기회와 힘을 준 것은 모두 「어머니」의 의지임을 기억해라.",
  ui_story_10_8_1_43_dialog_content = "네가 이토록 빠르게 「씨앗」에 적응하고 힘을 얻은 것은\n「어머니」의 혜안이 결코 틀림이 없으심을 뜻한다.",
  ui_story_10_8_1_44_dialog_content = "하지만 지금의 넌 아직 더 많은 것을 알 자격이 없다.",
  ui_story_10_8_1_45_dialog_content = "더 강해지고, 더 많은 공헌을 해야만 「어머니」의 가르침을 들을 자격을 얻을 수 있지.",
  ui_story_10_8_1_46_dialog_content = "이제 말해라. 내가 명령한 일은 마쳤느냐?",
  ui_story_10_8_1_47_dialog_content = "다 했어요.",
  ui_story_10_8_1_48_dialog_content = "좋다. 이제 네 콜로서스를 조종해서 내게 와라.",
  ui_story_10_8_1_49_dialog_content = "암귀 군단은 이미 헤븐즈 밸리에 진입했다. 심판이 곧 다가온다.",
  ui_story_10_8_1_50_dialog_content = "네게 남은 시간은 얼마 없다... 네게는 사도로서의 사명이 있다는 걸 잊지 마라.",
  ui_story_10_8_1_51_dialog_content = "...사도요?",
  ui_story_10_8_1_S1_dialog_content = "그렇다. 넌 가서 힘을 얻을 자격이 있다고 생각되는 아이테르를 내게 보여라.",
  ui_story_10_8_1_52_dialog_content = "내가 그들에게 <color=#FFB400>구원을 얻을 수 있는</color> 기회를 주겠다.",
  ui_story_10_8_1_S2_dialog_content = "으음...",
  ui_story_10_8_1_S3_dialog_content = "슈모르, 뭘 중얼거리고 있는 것이냐?",
  ui_story_10_8_1_S4_dialog_content = "갑자기... 뭔가... 간지러워요...",
  ui_story_10_8_1_S5_dialog_content = "간지럽다고?",
  ui_story_10_8_1_S6_dialog_content = "크크크, 몸이 불편해지기 시작한 게냐? 다른 이상한 점은 없느냐?",
  ui_story_10_8_1_S7_dialog_content = "다른 이상한 점이라면...",
  ui_story_10_8_1_S8_dialog_content = "눈을 못 뜨겠어요... 바깥의 빛이 너무 눈이 부셔요...",
  ui_story_10_8_1_S9_dialog_content = "그렇군... 이처럼 빠르게 몸속의 「씨앗」을 변화시킬 수 있다니, 잘했다!",
  ui_story_10_8_1_S10_dialog_content = "네 몸의 다크매터가 이미 성숙해진 것이 느껴지는구나.",
  ui_story_10_8_1_S11_dialog_content = "넌 이제 전과는 전혀 다른 모습으로 우리와 함께 헤븐즈 밸리로 가게 될 것이다.",
  ui_story_10_8_1_S12_dialog_content = "전과는 전혀 다른...",
  ui_story_10_8_1_S13_dialog_content = "그렇다. 넌 이미 아이테르를 초월했다. 아이테르 같은 열등한 존재의 모습은 네게 맞지 않는다.",
  ui_story_10_8_1_S14_dialog_content = "하지만... 전 이런 모습으로 태어났는걸요...",
  ui_story_10_8_1_S15_dialog_content = "넌 그 모습에서 탈피할 수 있다. 언젠가는 소멸될 나약한 아이테르의 운명에서 벗어난 것처럼 말이지...",
  ui_story_10_8_1_S16_dialog_content = "탈피... 제가 어떻게 해야 하죠?",
  ui_story_10_8_1_S17_dialog_content = "어떻게 해야 하나고? 크크크.",
  ui_story_10_8_1_S18_dialog_content = "힘을 갈망해라! 그러면 네 몸에 숨겨진 힘이 네게 무엇을 해야 할지를 알려줄 것이다!",
  ui_story_10_8_1_S19_dialog_content = "......",
  ui_story_10_8_1_S20_dialog_content = "더 강한 힘...",
  ui_story_10_8_1_S21_dialog_content = "나약한 운명에서 벗어날 힘...",
  ui_story_10_8_1_S22_dialog_content = "탈피...",
  ui_story_10_8_1_S23_dialog_content = "아냐... 난 이미 저들과 달라...",
  ui_story_10_8_1_S24_dialog_content = "난 이미 모든 걸 손에 넣었다고!",
  ui_story_10_8_1_53_dialog_content = "어서 가! 저쪽이야!",
  ui_story_10_8_1_54_dialog_content = "무기! 무기를 챙겨!",
  ui_story_10_8_1_55_dialog_content = "뭐가 어떻게 된 거지...",
  ui_story_10_8_1_56_dialog_content = "무슨 일이 생긴 건가?",
  ui_story_10_8_1_57_dialog_content = "여기 숨어 있었구나...",
  ui_story_10_8_1_58_dialog_content = "누, 누구야, 넌?!",
  ui_story_10_8_1_59_dialog_content = "아하하, 나야, 슈모르. 보고도 모르겠어?",
  ui_story_10_8_1_60_dialog_content = "슈모르? 아니... 그 뿔... 그리고 머리카락... 전혀 다르잖아!",
  ui_story_10_8_1_61_dialog_content = "의심하지 마. 무서워할 것도 없어. 이건 내가 사도가 되었다는 증거니까.",
  ui_story_10_8_1_62_dialog_content = "난 선택됐고, 그래서 이 힘을 얻었어. 아이테르를 초월하는 힘을 말이야.",
  ui_story_10_8_1_63_dialog_content = "사, 사도? 힘? 무슨 뜻이야?",
  ui_story_10_8_1_64_dialog_content = "......",
  ui_story_10_8_1_65_dialog_content = "설명해도 넌 몰라! 그저 내가 모든 아이테르보다 더 강하다는 것만 알면 돼!",
  ui_story_10_8_1_66_dialog_content = "대답해. 넌 왜 날 도와줬어? 왜 책에 열쇠를 숨겨서 나한테 준 건데?",
  ui_story_10_8_1_67_dialog_content = "사, 사람들이... 널 죽을 때까지... 거기 가둬 둔다고 했어...",
  ui_story_10_8_1_68_dialog_content = "내가 선생님한테 말하기라도 한다면... 다음 차례는 내가 될 거랬어...",
  ui_story_10_8_1_69_dialog_content = "하지만 우, 우린... 우린 동족이고, 형제잖아... 우린...",
  ui_story_10_8_1_70_dialog_content = "아, 재미없는 동정이었던 거야?",
  ui_story_10_8_1_71_dialog_content = "그러니까, 넌 내 처지를 동정했던 거지?",
  ui_story_10_8_1_72_dialog_content = "그 녀석들, 내가 갇힌 걸 보고 그런 소리를 지껄이다니... 정말 우습네.",
  ui_story_10_8_1_73_dialog_content = "이, 이해가 안 가... 대체 뭐가 어떻게 된 거야? ...넌 그 애들한테 괴롭힘을 당했잖아.",
  ui_story_10_8_1_74_dialog_content = "학생들이 멋대로 헤븐즈 밸리 밖으로 나갔다가 \n암귀한테 죽었다는 걸 장로들이 사실대로 밝힐 수 있겠어?",
  ui_story_10_8_1_75_dialog_content = "저들은 두려운 거야. 모두가 심판이 다가온다는 걸 알게 되면 자신들의 말을 듣지 않게 될 테니까.",
  ui_story_10_8_1_76_dialog_content = "잘 들어. 오해하지 마. 난 그 책이나 열쇠를 받을 생각 따윈 없었어.",
  ui_story_10_8_1_77_dialog_content = "하지만 나도 그리 무정한 사람은 아냐. 네가 날 도우려고 한 이상, 나도 네게 살 기회를 줄게.",
  ui_story_10_8_1_78_dialog_content = "너도 이제 큰 힘을 얻게 될 거야. 그럼 이제부터...",
  ui_story_10_8_1_79_dialog_content = "무, 무슨 소리야... 살 기회라니...",
  ui_story_10_8_1_80_dialog_content = "아직도 모르는 거야?",
  ui_story_10_8_1_81_dialog_content = "헤븐즈 밸리의 종말이 다가왔어. 암귀가 이 세계를 심판할 거야.",
  ui_story_10_8_1_82_dialog_content = "모두 죽을 거라고...",
  ui_story_10_8_1_83_dialog_content = "그러니까 너도 나처럼 암귀가 되는 거야!",
  ui_story_10_8_1_84_dialog_content = "아...아니... 나, 난...",
  ui_story_10_8_1_85_dialog_content = "그 녀석이냐?",
  ui_story_10_8_1_86_dialog_content = "난 바쁜 사람이다. 빨리 끝내자고.",
  ui_story_10_8_1_87_dialog_content = "!!!",
  ui_story_10_8_1_88_dialog_content = "네가 동의하지 않으면, 죽게 될 거야.",
  ui_story_10_8_1_89_dialog_content = "말해. 죽고 싶어?",
  ui_story_10_8_1_90_dialog_content = "난...",
  ui_story_10_8_1_91_dialog_content = "끄르르...",
  ui_story_10_8_1_92_dialog_content = "암귀 한 마리조차 이렇게 상대하기가 힘들다니...",
  ui_story_10_8_1_93_dialog_content = "한드로! 큰일이야! 동쪽에도 암귀가 나타났어!",
  ui_story_10_8_1_94_dialog_content = "너흰 먼저 가! 곧 따라갈 테니까!",
  ui_story_10_8_1_95_dialog_content = "선생님! 저예요!",
  ui_story_10_8_1_96_dialog_content = "저랑 같이 가요!",
  ui_story_10_8_1_97_dialog_content = "너...?!",
  ui_story_10_8_1_98_dialog_content = "슈모르냐?!",
  ui_story_10_8_1_99_dialog_content = "선생님, 무서워하지 마세요.",
  ui_story_10_8_1_100_dialog_content = "장로는 헤븐즈 밸리가 암귀한테 멸망당할 운명이었다는 걸 사람들한테 숨기고 있었어요.\n그러니까 다들 이렇게 당황한 거죠.",
  ui_story_10_8_1_101_dialog_content = "무슨 소리냐?",
  ui_story_10_8_1_102_dialog_content = "이 심판은 사실 정해져 있던 거라구요...",
  ui_story_10_8_1_103_dialog_content = "이건 세상의 선택이고, 진화의 선택이에요.",
  ui_story_10_8_1_104_dialog_content = "하지만 자격이 있는 사람이라면... 암귀도 해치지 않을 거예요...",
  ui_story_10_8_1_105_dialog_content = "그럼 심판에서 살아남을 수 있다구요!",
  ui_story_10_8_1_106_dialog_content = "전 이제 암귀의 사도가 됐어요. 선생님을 저들한테 추천할 수 있어요!",
  ui_story_10_8_1_107_dialog_content = "잡아! 어서! 녀석을 붙잡아!",
  ui_story_10_8_1_108_dialog_content = "어서! 다 같이!",
  ui_story_10_8_1_109_dialog_content = "...?",
  ui_story_10_8_1_110_dialog_content = "밀실 문을 열어! 빨리!",
  ui_story_10_8_1_111_dialog_content = "슈모르를... 가둬...",
  ui_story_10_8_1_112_dialog_content = "......",
  ui_story_10_8_1_113_dialog_content = "이게 당신 선택인가요...",
  ui_story_10_8_1_114_dialog_content = "정말 겁쟁이네...",
  ui_story_10_8_1_115_dialog_content = "뭐, 상관없어...",
  ui_story_10_8_1_116_dialog_content = "후회하게 될 테니까...",
  ui_story_10_8_1_117_dialog_content = "그들이 오면, 모두가 후회하며 나한테 빌게 될 거야...",
  ui_story_10_8_1_118_dialog_content = "기회를 달라고 빌겠지...",
  ui_story_10_8_1_119_dialog_content = "으아아악!",
  ui_story_10_8_1_120_dialog_content = "서둘러! 빨리! 저쪽으로 도망쳐!",
  ui_story_10_8_1_121_dialog_content = "가동할 수 있는 콜로서스가 없는 거야?!",
  ui_story_10_8_1_122_dialog_content = "감응할 수 있는 사람들은 길을 찾아! 아이들부터 데려가!",
  ui_story_10_8_1_123_dialog_content = "안 돼... 암귀가 너무 많아... 너무 많다고...",
  ui_story_10_8_1_124_dialog_content = "으음. 얼마나 멋진 소리인가.",
  ui_story_10_8_1_125_dialog_content = "짐승처럼 열등한 아인족들을 몰살시킨 이후로...",
  ui_story_10_8_1_126_dialog_content = "심장을 꿰뚫는 비명을 듣는 건 정말 오랜만이로군.",
  ui_story_10_8_1_127_dialog_content = "이 아이테르들의 비명은 그 아인족들처럼 크진 않지만, 날카로운 목소리가 무척 듣기 좋군.",
  ui_story_10_8_1_128_dialog_content = "역시 노래를 좋아하는 종족답다니까. 크크크.",
  ui_story_10_8_1_129_dialog_content = "그르르...",
  ui_story_10_8_1_130_dialog_content = "가라. 더 많은 비명을 연주해라. 놈들을 없애라!",
  ui_story_10_8_1_131_dialog_content = "크아아!",
  ui_story_10_8_1_132_dialog_content = "움직일 수 있는 콜로서스를 꺼내!",
  ui_story_10_8_1_133_dialog_content = "어서! 생존자들을 도와줘!",
  ui_story_10_8_1_134_dialog_content = "콜록...",
  ui_story_10_8_1_135_dialog_content = "콜록, 콜록...",
  ui_story_10_8_1_136_dialog_content = "살아있는 사람이 있었구나... 다행이야...",
  ui_story_10_8_1_137_dialog_content = "서, 선생님...",
  ui_story_10_8_1_138_dialog_content = "멘델슨, 다행이야... 어서 가자...",
  ui_story_10_8_1_139_dialog_content = "선생님... 모두 죽었어요...",
  ui_story_10_8_1_140_dialog_content = "선생님... 우리가 도망칠 수 있을까요... 어디로 갈 수 있죠...?",
  ui_story_10_8_1_141_dialog_content = "당연하지. 우린 살아남을 거야... 콜록... 어서 가자...",
  ui_story_10_8_1_142_dialog_content = "이쪽이다. 서둘러... <color=#FFB400>아르카누스호</color>가 근처에 있어...",
  ui_story_10_8_1_143_dialog_content = "......",
  ui_story_10_8_1_144_dialog_content = "선생님?",
  ui_story_10_8_1_145_dialog_content = "멘델슨, 내 말을 잘 듣거라. 우릴 도와줄 사람들은 이미 모두 죽었다...",
  ui_story_10_8_1_146_dialog_content = "이제 내가 주변의 암귀들을 유인하는 수밖에 없다. 넌 그 틈에 아르카누스호로 들어가라.\n아르카누스호는 아직 가동할 수 있을 거다.",
  ui_story_10_8_1_147_dialog_content = "아르카누스호 안에는 특별한 방이 하나 있단다.\n헤븐즈 밸리를 벗어나고 나면... 그 방을 찾거라...",
  ui_story_10_8_1_148_dialog_content = "안에는 <color=#FFB400>특별한 부품</color>이 있다. 그 부품의 존재는...",
  ui_story_10_8_1_149_dialog_content = "콜로서스에 대한 인식을 완전히 바꿔놓을 거다.",
  ui_story_10_8_1_150_dialog_content = "만약 그게 악한 자들의 손에 넘어간다면, 그 결과는 참혹할 거다.",
  ui_story_10_8_1_151_dialog_content = "아르카누스호를 조종할 수 있는 사람은 이미 죽었고, 이제 너만 남았다.",
  ui_story_10_8_1_152_dialog_content = "저, 전 못 해요... 콜로서스와 감응에 성공한 적도 없는걸요...",
  ui_story_10_8_1_153_dialog_content = "난 네가 할 수 있다고 믿는다. 넌 큰 잠재력을 지니고 있어. 단지 자신감이 부족할 뿐이야.",
  ui_story_10_8_1_154_dialog_content = "넌 아르카누스호의 조종사로 적합한 아이란다.\n우린 원래 널 아르카누스호의 차기 조종사로 육성하려 했었다.",
  ui_story_10_8_1_155_dialog_content = "하지만 선생님... 선생님도 콜로서스와 감응할 수 있잖아요... 설마 같이 안 가실 건가요?",
  ui_story_10_8_1_156_dialog_content = "난 너와 함께 갈 수 없단다. <color=#FFB400>컬쳐리스트호</color>가 날 기다리고 있어.",
  ui_story_10_8_1_157_dialog_content = "널 믿는다. 너라면 분명히 가동할 수 있을 거다.",
  ui_story_10_8_1_158_dialog_content = "아르카누스호에는 <color=#FFB400>피닉스</color>와 <color=#FFB400>피니</color>라는 수호자들이 있다.\n그들이 널 도와주고, 너와 동행할 거다...",
  ui_story_10_8_1_159_dialog_content = "서, 선생님... 저 혼자선 못 해요... 감응에 성공한 적도 없잖아요...",
  ui_story_10_8_1_160_dialog_content = "넌 분명히 할 수 있을 거야. 이제 더는 자신을 의심해선 안 돼.",
  ui_story_10_8_1_161_dialog_content = "하지만 그 암귀들은... 어디에나 있어요... 게다가 엄청 무서운 암귀가 있어요...",
  ui_story_10_8_1_162_dialog_content = "콜로서스를 가동해도... 도망칠 수 없을 거예요...",
  ui_story_10_8_1_163_dialog_content = "이대로면 모두 다 죽을 거예요... 죽을 거라구요...",
  ui_story_10_8_1_164_dialog_content = "선생님... 슈모르는 우리가 살 수 있는 방법이 있다고 했어요...",
  ui_story_10_8_1_165_dialog_content = "슈모르?! 슈모르가 널 찾아왔던 거냐?",
  ui_story_10_8_1_166_dialog_content = "어쩌면 우린 다른 방식으로 살아갈 수 있을지도 몰라요...",
  ui_story_10_8_1_167_dialog_content = "종말 뒤에도...",
  ui_story_10_8_1_168_dialog_content = "슈모르, 놀이는 끝났나?",
  ui_story_10_8_1_169_dialog_content = "피제로 님... 더는 선택하고 싶은 사람이 없어요.",
  ui_story_10_8_1_170_dialog_content = "정말 불쌍하네요. 전 이미 충분히 기다렸어요.",
  ui_story_10_8_1_171_dialog_content = "이제 저들에겐 더는 살아남을 기회 따윈 없을 거예요.",
  ui_story_10_8_1_172_dialog_content = "크하하하! 그렇다면 이제 위대한 종말의 날을 목도하거라!",
  ui_story_10_8_1_173_dialog_content = "일식이 시작된다!",
  ui_story_10_9_1_1_dialog_content = "PlayerName?!",
  ui_story_10_9_1_2_dialog_content = "종말... 그리고 <color=#FFB400>일식</color>...",
  ui_story_10_9_1_3_dialog_content = "종말이라니? 무슨 소리야? 일단 정신 좀 차리고 나서 좀 더 자세하게 설명해 봐.",
  ui_story_10_9_1_4_dialog_content = "전에 난 헤븐즈 밸리가 멸망하는 꿈을 꿨어...",
  ui_story_10_9_1_5_dialog_content = "그리고 그건 모두 사실이었어.",
  ui_story_10_9_1_6_dialog_content = "방금 헤븐즈 밸리에 대한 슈모르의 기억을 읽었어.\n암귀들이 헤븐즈 밸리를 습격한 그날이었어.",
  ui_story_10_9_1_7_dialog_content = "슈모르가 암귀를 헤븐즈 밸리로 데려갔어...",
  ui_story_10_9_1_8_dialog_content = "하늘이 어두워지고... 일식이 일어났어...",
  ui_story_10_9_1_9_dialog_content = "그리고 제일 중요한 건, 그 자리에 「<color=#FFB400>피제로</color>」라는 인간의 모습을 한 암귀가 있었어...",
  ui_story_10_9_1_10_dialog_content = "그자가 암귀를 이끌고 헤븐즈 밸리를 멸망시킨 거였어!",
  ui_story_10_9_1_11_dialog_content = "...너, 괜찮은 거냐?",
  ui_story_10_9_1_12_dialog_content = "괜찮아. 그리고 지금 암귀들이 이쪽으로 몰려오고 있어. 맞설 준비를 해야 돼.",
  ui_story_10_9_1_13_dialog_content = "아무 소리도 안 나는 이런 곳에서도 암귀의 습격을 감지할 수 있는 거냐?",
  ui_story_10_9_1_14_dialog_content = "소, 소리가 조금 들려! 암귀들이 왔어!",
  ui_story_10_9_1_15_dialog_content = "하, 방금 잔뜩 흥분한 것 같아서 난 네가 또 감정을 주체하지 못하는 줄 알았지.",
  ui_story_10_9_1_16_dialog_content = "의외로 침착하게 상황을 판단하고 있잖아.",
  ui_story_10_9_1_17_dialog_content = "그래도 하나 당부해 두지. 복수의 일념만으로는 문제를 해결할 수 없어.",
  ui_story_10_9_1_18_dialog_content = "넌 지휘관이니까, 적을 만났을 때도 침착하게 네 역할을 수행해야 한다고.",
  ui_story_10_9_1_19_dialog_content = "그럴게. 고마워.",
  ui_story_10_9_1_20_dialog_content = "냉정하게... 복수를 마칠 거야.",
  ui_story_10_13_1_1_dialog_content = "암귀가 된다고 해서 꼭 암귀의 힘을 제어할 수 있는 건 아냐.",
  ui_story_10_13_1_2_dialog_content = "심지어 다크매터의 영향으로 자신을 제어하지 못하게 될 수도 있지...",
  ui_story_10_13_1_3_dialog_content = "슈모르처럼 온종일 힘을 갈망하는 녀석조차 힘을 기르는 건 이 정도가 한계인 모양이네.",
  ui_story_10_13_1_4_dialog_content = "이대로라면... 이번 실험은 더는 기록할 필요가 없겠는걸.",
  ui_story_10_13_1_5_dialog_content = "『주인님, 이제 어떻게 할까요?』",
  ui_story_10_13_1_6_dialog_content = "『그 오로리안들이 곧 이곳에 도착합니다.』",
  ui_story_10_13_1_7_dialog_content = "슈모르가 알아서 성장하길 기대하긴 힘들겠어.",
  ui_story_10_13_1_8_dialog_content = "내가 자극하는 수밖에.",
  ui_story_10_13_1_9_dialog_content = "넌 계속해서 그 오로리안들의 움직임을 감시해.",
  ui_story_10_13_1_10_dialog_content = "『예.』",
  ui_story_10_13_1_11_dialog_content = "슈모르.",
  ui_story_10_13_1_12_dialog_content = "시끄...러워...",
  ui_story_10_13_1_13_dialog_content = "아직도 안 일어났어?",
  ui_story_10_13_1_14_dialog_content = "아...?",
  ui_story_10_13_1_15_dialog_content = "얼빠진 표정 그만 지어. 난 네 실험 결과를 말해주러 왔어.",
  ui_story_10_13_1_16_dialog_content = "뭐라고...?",
  ui_story_10_13_1_17_dialog_content = "내가 내린 최종 결론은... 넌 역시 <color=#FFB400>확실한 쓰레기</color>야.",
  ui_story_10_13_1_18_dialog_content = "...노...라.",
  ui_story_10_13_1_19_dialog_content = "흥분할 거 없어, 슈모르. 내가 하는 말은 객관적인 사실이니까.",
  ui_story_10_13_1_20_dialog_content = "넌 암귀 무리에 디바우러호까지 먹어 치웠지만, 여전히 탈피에 실패했어.",
  ui_story_10_13_1_21_dialog_content = "디바우러호를... 먹어...?",
  ui_story_10_13_1_22_dialog_content = "그래, 이 리커버리 코쿤은 네 디바우러호와 연결돼 있어.",
  ui_story_10_13_1_23_dialog_content = "넌 리커버리 코쿤을 통해 녀석의 에너지를 전부 흡수했고, 이제 녀석은 그저 고철 더미일 뿐이야.",
  ui_story_10_13_1_24_dialog_content = "어...째서... 말하지 않은... 거야...",
  ui_story_10_13_1_25_dialog_content = "네가 이 콜로서스를 무척 신경 쓴다는 건 알아.",
  ui_story_10_13_1_26_dialog_content = "어릴 적부터 가장 갖고 싶었던 장난감을 겨우 손에 넣었으니,\n절대 놓치고 싶지 않겠지. 그건 당연해.",
  ui_story_10_13_1_27_dialog_content = "그러니까 넌 여전히 뼛속까지 나약한 아이테르인 거야.",
  ui_story_10_13_1_28_dialog_content = "그래서 PlayerName 녀석을 봤을 때도 차마 죽이지 못했고,\n그렇다고 놓아주지도 못한 거겠지.",
  ui_story_10_13_1_29_dialog_content = "넌 과거의 그늘에서 전혀 벗어나지 못했어. 불쌍하게도 말이야.",
  ui_story_10_13_1_30_dialog_content = "네가 자기 운명을 결정할 수 있다는 망상은 하지 않았길 바랄게.",
  ui_story_10_13_1_31_dialog_content = "약자에겐 그럴 자격 따윈 없으니까.",
  ui_story_10_13_1_32_dialog_content = "빌어...먹을...",
  ui_story_10_13_1_33_dialog_content = "더 분노하는 게 좋을 거야.",
  ui_story_10_13_1_34_dialog_content = "이 모든 건 모두 네가 자초한 일이거든.",
  ui_story_10_13_1_35_dialog_content = "다 네가 유치하고, 약하고, 천박하고, 어리석어서 이렇게 된 거라고.",
  ui_story_10_13_1_36_dialog_content = "죽여...버리겠어...",
  ui_story_10_13_1_37_dialog_content = "아니, 네 분노가 향할 대상은 내가 아냐.",
  ui_story_10_13_1_38_dialog_content = "잊은 거야?",
  ui_story_10_13_1_39_dialog_content = "누가 널 이 지경으로 만든 건지?",
  ui_story_10_13_1_40_dialog_content = "그 아이테르가 했던 말 기억해?",
  ui_story_10_13_1_41_dialog_content = "「넌 강자에게 빌붙어서 힘을 갈구해온 거지?」",
  ui_story_10_13_1_42_dialog_content = "녀석은 널 꿰뚫어 본 거야.",
  ui_story_10_13_1_43_dialog_content = "이제 녀석들이 왔어.",
  ui_story_10_13_1_44_dialog_content = "저들은 널 찾아와서 죽일 거야.",
  ui_story_10_13_1_45_dialog_content = "어쩌면 녀석들한테 용서를 빌어보는 것도 괜찮겠네.",
  ui_story_10_13_1_46_dialog_content = "말도... 안 돼...",
  ui_story_10_13_1_47_dialog_content = "어디 PlayerName한테 널 죽이지 말아 달라고, 살려달라고 빌어 봐.",
  ui_story_10_13_1_48_dialog_content = "헛소리... 집어... 치우라고...",
  ui_story_10_13_1_49_dialog_content = "만약 죽고 싶지 않다면...",
  ui_story_10_13_1_50_dialog_content = "살고 싶고, 그 녀석들을 죽이고 싶다면.",
  ui_story_10_13_1_51_dialog_content = "네게 남은 방법은 단 하나뿐이야.",
  ui_story_10_13_1_52_dialog_content = "더 많은 힘을 갈망하는 거야.",
  ui_story_10_13_1_53_dialog_content = "힘...",
  ui_story_10_13_1_54_dialog_content = "......",
  ui_story_10_13_1_55_dialog_content = "슈모르?",
  ui_story_10_13_1_56_dialog_content = "<size=45>힘을 줘──!</size>",
  ui_story_10_13_1_57_dialog_content = "......",
  ui_story_10_13_1_58_dialog_content = "어느 정도는 감정 조절이 어려워질 거라고 예상은 했지만...",
  ui_story_10_13_1_59_dialog_content = "완전히 이성을 잃어버릴 줄은 몰랐네.",
  ui_story_10_13_1_60_dialog_content = "<size=45>힘을───!</size>",
  ui_story_10_13_1_61_dialog_content = "정말 구제 불능이네.",
  ui_story_10_13_1_62_dialog_content = "<color=#e8d9bb>크오오──!</color>",
  ui_story_10_13_1_63_dialog_content = "무, 무슨 소리지?",
  ui_story_10_13_1_64_dialog_content = "PlayerName, 무슨 일인지 알 수 있어?",
  ui_story_10_13_1_65_dialog_content = "모르겠어... 아무리 집중해도 슈모르의 생각이 조금밖에 느껴지지 않아...",
  ui_story_10_13_1_66_dialog_content = "「강력한」... 「힘」... 「특별한」... 같은 단편적인 사념뿐이야.",
  ui_story_10_13_1_67_dialog_content = "그리고... 아주 강렬한...",
  ui_story_10_13_1_68_dialog_content = "<color=#FFB400>증오</color>...",
  ui_story_10_13_1_69_dialog_content = "그 녀석... 완전히 미쳐버린 것 같아!",
  ui_story_10_13_1_70_dialog_content = "미쳐? 암귀를 잡아먹더니, 이젠 미친 거냐?",
  ui_story_10_13_1_71_dialog_content = "말이 좀 이상한걸...",
  ui_story_10_13_1_72_dialog_content = "그 노라와 관계가 있는 게 분명해.",
  ui_story_10_13_1_73_dialog_content = "아마 녀석이 슈모르한테 우리가 여기 있다고 말했겠지.",
  ui_story_10_13_1_74_dialog_content = "지금쯤 우리와 싸울 준비를 마쳤을 거다.",
  ui_story_10_13_1_75_dialog_content = "만약 녀석이 널 노리고 있다면, 우릴 무시하고 바로 네게 달려들 거다.",
  ui_story_10_13_1_76_dialog_content = "거기다 노라가 합세한다면, 우리가 널 지킬 수 있다는 보장은 없다.",
  ui_story_10_13_1_77_dialog_content = "내가 상황을 알아볼 테니, 너흰 PlayerName 곁을 지켜줘.",
  ui_story_10_13_1_78_dialog_content = "알겠어.",
  ui_story_10_13_1_79_dialog_content = "전방에 암귀가 있어!",
  ui_story_10_13_1_80_dialog_content = "빠르게 해치우자고!",
  ui_story_10_13_1_81_dialog_content = "캬아악!",
  ui_story_10_13_1_82_dialog_content = "어떻게 된 거야?! 암귀들이 갑자기 흥분했잖아?",
  ui_story_10_13_1_83_dialog_content = "방금 그 지진 때문인가?!",
  ui_story_10_13_1_84_dialog_content = "뭔가 불길한 예감이 드는걸...",
  ui_story_10_13_1_85_dialog_content = "펙트 양도 느낀 거군요.",
  ui_story_10_13_1_86_dialog_content = "매우 위험한 뭔가가 나타난 게 확실합니다.",
  ui_story_10_13_1_87_dialog_content = "빅토리아 님께선...",
  ui_story_10_13_1_88_dialog_content = "지금은 분쟁에 휘말려선 안 된다고 당부하셨습니다.",
  ui_story_10_13_1_89_dialog_content = "그래요. 「씨앗」도 어느 정도 회수했으니, 이제 이 무대에서 퇴장할 시간입니다.",
  ui_story_10_13_1_90_dialog_content = "이제 거대한 전쟁이 시작될 테니까요.",
  ui_story_10_13_2_1_dialog_content = "캬악!",
  ui_story_10_13_2_2_dialog_content = "......",
  ui_story_10_13_2_3_dialog_content = "슈모르?!",
  ui_story_10_13_2_4_dialog_content = "아, 아...암귀한테 곧장 달려들었는데?!",
  ui_story_10_13_2_5_dialog_content = "암귀를 먹고 있잖아?",
  ui_story_10_13_2_6_dialog_content = "저...저게 슈모르라고? 전혀 딴판이잖아?!",
  ui_story_10_13_2_7_dialog_content = "슈모르!",
  ui_story_10_13_2_8_dialog_content = "난 이미 네 모든 죄를 알고 있어...",
  ui_story_10_13_2_9_dialog_content = "죽기 싫었으면, 너 혼자 암귀가 됐으면 되는 거잖아?",
  ui_story_10_13_2_10_dialog_content = "왜 암귀를 헤븐즈 밸리로 데려온 거야!",
  ui_story_10_13_2_11_dialog_content = "어째서 모두를 죽게 만든 거냐고!",
  ui_story_10_13_2_12_dialog_content = "......",
  ui_story_10_13_2_13_dialog_content = "배신자... 반드시 대가를 치르게 하겠어!",
  ui_story_10_13_2_14_dialog_content = "크아아──!",
  ui_story_10_13_2_15_dialog_content = "PlayerName! 조심해!",
  ui_story_10_13_2_16_dialog_content = "크에엑?!",
  ui_story_10_13_2_17_dialog_content = "뭐야... 왜 구석에 있는 암귀부터 공격하는 거지?!",
  ui_story_10_13_2_18_dialog_content = "......",
  ui_story_10_13_2_19_dialog_content = "힘...",
  ui_story_10_13_2_20_dialog_content = "대체 뭐가 어떻게 된 거야...",
  ui_story_10_13_2_21_dialog_content = "왠지... 우릴 전혀 신경 쓰지 않는 것 같은데?",
  ui_story_10_13_2_22_dialog_content = "PlayerName... 방금 그건 너무 위험했잖아!",
  ui_story_10_13_2_23_dialog_content = "지휘를 해야 할 네가 싸우는 우리보다 더 충동적으로 나서면 어쩌자는 거냐!",
  ui_story_10_13_2_24_dialog_content = "미안해... 이제 진정했어.",
  ui_story_10_13_2_25_dialog_content = "......",
  ui_story_10_13_2_26_dialog_content = "이제 어떡하지?",
  ui_story_10_13_2_27_dialog_content = "슈모르는... 힘을 얻기 위해 어떤 수단도 가리지 않았고, 결국 이성을 잃어버린 것 같아.",
  ui_story_10_13_2_28_dialog_content = "조심해서 맞서자. 우선 슈모르의 힘이 어느 정도인지 알아볼 필요가 있어.",
  ui_story_10_13_2_29_dialog_content = "그르르...",
  ui_story_10_13_2_30_dialog_content = "이쪽을... 보고 있어! 암귀를 다 먹어서 그런가?!",
  ui_story_10_13_2_31_dialog_content = "......",
  ui_story_10_13_2_32_dialog_content = "PlayerName...",
  ui_story_10_13_2_33_dialog_content = "뭐야, 반응을 보이잖아?!",
  ui_story_10_13_2_34_dialog_content = "PlayerName... 너흴 죽여버리겠어...",
  ui_story_10_13_2_35_dialog_content = "녀석한테 손을 대시겠다?! 나부터 넘고 보라고!",
  ui_story_10_13_2_36_dialog_content = "<anim type=Shake><size=50>PlayerName! 죽어! 죽으라고!</size></anim>",
  ui_story_10_14_2_1_dialog_content = "이겼나?!",
  ui_story_10_14_2_2_dialog_content = "숨통을 끊어버려! 어서!",
  ui_story_10_14_2_3_dialog_content = "슈모르! 심판을 받아라!",
  ui_story_10_14_2_4_dialog_content = "크아아──!",
  ui_story_10_14_2_5_dialog_content = "기나긴 꿈이었어... 역겨운 꿈...",
  ui_story_10_14_2_6_dialog_content = "17년 전의 기억일 뿐인데...",
  ui_story_10_14_2_7_dialog_content = "정말 지긋지긋해...",
  ui_story_10_14_2_8_dialog_content = "이제 지겹다고──!",
  ui_story_10_14_2_9_dialog_content = "PlayerName 씨! 조심해!",
  ui_story_10_14_2_10_dialog_content = "콰아앙──!",
  ui_story_10_14_2_11_dialog_content = "크윽...",
  ui_story_10_14_2_12_dialog_content = "이 녀석... 한번 쓰러지고도 이런 힘이 있다니...",
  ui_story_10_14_2_13_dialog_content = "이 어이없는 힘은... 대체 뭐냐...",
  ui_story_10_14_2_14_dialog_content = "......",
  ui_story_10_14_2_15_dialog_content = "바이스, PlayerName... 괜찮아?",
  ui_story_10_14_2_16_dialog_content = "아직... 괜찮아...",
  ui_story_10_14_2_17_dialog_content = "난 괜찮아... 보프가 날 지켜줬어... 고마워.",
  ui_story_10_14_2_18_dialog_content = "천만에. 안전이 제, 제일 중요하니까...",
  ui_story_10_14_2_19_dialog_content = "......",
  ui_story_10_14_2_20_dialog_content = "죽었나?",
  ui_story_10_14_2_21_dialog_content = "아, 아니야...",
  ui_story_10_14_2_22_dialog_content = "하, 하하... 아하하하...",
  ui_story_10_14_2_23_dialog_content = "슈모르가 정신을 되찾았어! 다들 조심해... 녀석은 아직 힘이 남이 있어!",
  ui_story_10_14_2_24_dialog_content = "정신?",
  ui_story_10_14_2_25_dialog_content = "그래... 방금... 난 무척 화가 났어...",
  ui_story_10_14_2_26_dialog_content = "근데... PlayerName 네가 올 걸 생각하니까... 무척 기뻤어.",
  ui_story_10_14_2_27_dialog_content = "...!",
  ui_story_10_14_2_28_dialog_content = "이건 또 무슨 변태 같은 소리야?!",
  ui_story_10_14_2_29_dialog_content = "PlayerName, 뒤로 물러서!",
  ui_story_10_14_2_30_dialog_content = "보프! 그 녀석은 네가 지켜줘!",
  ui_story_10_14_2_31_dialog_content = "알겠어!",
  ui_story_10_14_2_32_dialog_content = "어이! 정신 나간 변태! 노라는 어디 있어? 어서 말해!",
  ui_story_10_14_2_33_dialog_content = "「정신 나간 변태」? 지금 날 욕하는 거야?",
  ui_story_10_14_2_34_dialog_content = "뭐, 상관없어. 화내지 않을게... 너한텐 그럴 가치도 없거든.",
  ui_story_10_14_2_35_dialog_content = "노라는... 신경 쓸 거 없어.",
  ui_story_10_14_2_36_dialog_content = "도망친 그 녀석은 내가 가서 끝장낼 테니까.",
  ui_story_10_14_2_37_dialog_content = "하지만 그 전에... PlayerName, 우리 사이의 문제를 끝내자고.",
  ui_story_10_14_2_38_dialog_content = "약속할게. 이번엔... 전력을 다해...",
  ui_story_10_14_2_39_dialog_content = "너희가 고통 속에서 죽을 수 있게 해줄 테니까──!",
  ui_story_10_14_2_40_dialog_content = "!!!",
  ui_story_10_14_2_41_dialog_content = "녀석들한테 목숨을 걸 생각이야? 그럴 순 없지...",
  ui_story_10_14_2_42_dialog_content = "노...라...?!",
  ui_story_10_14_2_43_dialog_content = "잘했어. 네가 품은 적의 덕분에 「씨앗」이 드디어 성장했어...",
  ui_story_10_14_2_44_dialog_content = "하지만 방금 전투에서 넌 이미 대부분의 에너지를 소모했어.",
  ui_story_10_14_2_45_dialog_content = "계속 그런 식이라면 내가 겨우 배양해 낸 「씨앗」에 영향을 주고 말 거야.",
  ui_story_10_14_2_46_dialog_content = "너... 뭘 하려고...?!",
  ui_story_10_14_2_47_dialog_content = "얌전히 있어. 「씨앗」을 꺼낼 거니까.",
  ui_story_10_14_2_48_dialog_content = "사메야마! 노라의 목적은 슈모르의 「<color=#FFB400>씨앗</color>」이야!",
  ui_story_10_14_2_49_dialog_content = "그렇겐 안 되지!",
  ui_story_10_14_2_50_dialog_content = "너무 흥분하지 마. 따지고 보면 내가 너흴 구해준 셈이니까.",
  ui_story_10_14_2_51_dialog_content = "슈모르의 처분은 너희한테 맡길게. 난 씨앗만 가져가면 되거든.",
  ui_story_10_14_2_52_dialog_content = "각자 원하는 걸 손에 넣으니까, 모두 해피엔딩 아냐?",
  ui_story_10_14_2_53_dialog_content = "게다가... 넌 날 막을 수 없어...",
  ui_story_10_14_2_54_dialog_content = "사메야마! 조심해!",
  ui_story_10_14_2_55_dialog_content = "뭐야, 이 공격은?!",
  ui_story_10_14_2_56_dialog_content = "모두 얌전히 엎어져 있어.",
  ui_story_10_14_2_57_dialog_content = "그리고 마지막으로...",
  ui_story_10_14_2_58_dialog_content = "죽기 전에 할 말이 더 있니? 슈모르.",
  ui_story_10_14_2_59_dialog_content = "힘을 잃은 소감이나, 아이테르로 돌아간 소감이 어떤지 들어보고 싶은걸.",
  ui_story_10_14_2_60_dialog_content = "그럴 만한 가치가 있다면, 내 실험 기록에 같이 적어줄게.",
  ui_story_10_14_2_61_dialog_content = "......",
  ui_story_10_14_2_62_dialog_content = "퉤엣...",
  ui_story_10_14_2_63_dialog_content = "...알겠어.",
  ui_story_10_14_2_64_dialog_content = "그럼 너희가 내 실험을 완성시켜준 것에 대한 답례로, 슈모르는 너희한테 넘겨줄게.",
  ui_story_10_14_2_65_dialog_content = "잘 가, 슈모르...",
  ui_story_10_14_2_66_dialog_content = "크윽...",
  ui_story_10_14_2_67_dialog_content = "사메야마 씨... 절대... 쫓아가지 마...",
  ui_story_10_14_2_68_dialog_content = "...알고 있다고.",
  ui_story_10_14_2_69_dialog_content = "PlayerName, 슈모르는 어쩔 거냐... 네가 결정해라.",
  ui_story_10_14_2_70_dialog_content = "슈모르는 중상 때문에 곧 죽을 거야. 지금이라면 움직이는 것도 힘들겠지.",
  ui_story_10_14_2_71_dialog_content = "방금 전 일은 생각하지 마. 이제 네 숙원을 이룰 차례야.",
  ui_story_10_14_2_72_dialog_content = "PlayerName, 이 얼음 가시로 네가 녀석을 직접 심판할 수 있어.",
  ui_story_10_14_2_73_dialog_content = "그 전에... 아직 물어볼 것들이 있어.",
  ui_story_10_14_2_74_dialog_content = "하... 날 심판해? 뭘 물어?",
  ui_story_10_14_2_75_dialog_content = "그래... 어디... 물어나 보라고...",
  ui_story_10_14_2_76_dialog_content = "콜로서스의 세 부품은 어디 있지?",
  ui_story_10_14_2_77_dialog_content = "죽어버려!",
  ui_story_10_14_2_78_dialog_content = "쓰레기 아이테르! ...빌어먹을 자식! 내 부품을 갖고 싶어? ...꿈 깨시지!",
  ui_story_10_14_2_79_dialog_content = "넌 그 부품들의 가치를 전혀 몰라! ...그건 오직 디바우러호를 위해 존재하는 거라고!",
  ui_story_10_14_2_80_option_content = "디바우러호가 그렇게 소중해?",
  ui_story_10_14_2_81_dialog_content = "아이테르를 배신한 것도... 그저 디바우러호를 손에 넣고 싶어서였어?",
  ui_story_10_14_2_82_dialog_content = "네가 암귀한테 죽고 싶지 않은 마음은 이해할 수 있어...",
  ui_story_10_14_2_83_dialog_content = "그럼 너 혼자 암귀가 돼서, 놈들을 따라갔으면 되는 거잖아...\n어째서 암귀들을 헤븐즈 밸리로 데려온 거냐고!",
  ui_story_10_14_2_84_dialog_content = "어째서!",
  ui_story_10_14_2_85_dialog_content = "하하...",
  ui_story_10_14_2_86_dialog_content = "넌 아무것도 몰라.",
  ui_story_10_14_2_87_dialog_content = "너흰 종말을 맞이한 적도 없고, 진정한 심판을 받지도 않았어. 너흰 모른다고...",
  ui_story_10_14_2_88_dialog_content = "저들은... 헤븐즈 밸리에 나타날 운명이었어!",
  ui_story_10_14_2_89_dialog_content = "그 누구도! 도망칠 수 없었다고!",
  ui_story_10_14_2_90_dialog_content = "너희도 마찬가지야... 곧 멸망할 거야...",
  ui_story_10_14_2_91_dialog_content = "헛소리! 이 녀석, 암귀한테 완전히 세뇌당했어!",
  ui_story_10_14_2_92_dialog_content = "PlayerName, 더 들을 것도 없어!",
  ui_story_10_14_2_93_option_content = "알고 싶지도 않아! 부품이나 내놔!",
  ui_story_10_14_2_94_dialog_content = "그건 네가 가질 물건이 아냐!",
  ui_story_10_14_2_95_dialog_content = "부품은 아이테르의 것이야!",
  ui_story_10_14_2_96_dialog_content = "암귀 따위가 아니라!",
  ui_story_10_14_2_97_dialog_content = "아이테르를 위한 거라고!",
  ui_story_10_14_2_98_dialog_content = "너 같은 배신자는 그걸 가질 자격이 없어!",
  ui_story_10_14_2_99_dialog_content = "......",
  ui_story_10_14_2_100_dialog_content = "네가 뭘 알아!",
  ui_story_10_14_2_101_dialog_content = "아이테르? 약해 빠진 것도 모자라서, 옳고 그름조차 모르는 녀석들...",
  ui_story_10_14_2_102_dialog_content = "그 아이테르들은 콜로서스의 진정한 가치도, 힘의 가치도 전혀 모르는 멍청한 것들이었어!",
  ui_story_10_14_2_103_dialog_content = "너희도 마찬가지야. 하나같이 무지하고 나약한 머저리들이라고!",
  ui_story_10_14_2_104_dialog_content = "닥쳐!",
  ui_story_10_14_2_105_dialog_content = "PlayerName, 녀석한테 휘말리지 마!",
  ui_story_10_14_2_106_dialog_content = "나도 알아...",
  ui_story_10_14_2_107_dialog_content = "알고 있다고...",
  ui_story_10_14_2_108_dialog_content = "오는 동안 난 이미 그렇게 생각했어. 암귀들의 목표가 처음부터 헤븐즈 밸리의 멸망이었다면...",
  ui_story_10_14_2_109_dialog_content = "어떤 수단을 써서라도, 언제든 습격을 시작할 수 있었을 거야.",
  ui_story_10_14_2_110_dialog_content = "슈모르, 넌 그저 불쌍한 희생양일 뿐이야.",
  ui_story_10_14_2_111_dialog_content = "하아?",
  ui_story_10_14_2_112_dialog_content = "무슨 헛소리야?",
  ui_story_10_14_2_113_dialog_content = "난 선택받았다고... 살아갈 자격을 부여받은 선택받은 존재라고!",
  ui_story_10_14_2_114_dialog_content = "바이스, 상처는 좀 어때?",
  ui_story_10_14_2_115_dialog_content = "아, 응? 나, 난 괜찮아...",
  ui_story_10_14_2_116_dialog_content = "...야!",
  ui_story_10_14_2_117_dialog_content = "내 말 안 들려?!",
  ui_story_10_14_2_118_dialog_content = "바이스, 콜로서스는 구조가 대부분 비슷하니까, 부품이 어디 있는지는 내가 찾을 수 있을 거야.",
  ui_story_10_14_2_119_dialog_content = "나랑 같이 챙기러 가자.",
  ui_story_10_14_2_120_dialog_content = "...알겠어.",
  ui_story_10_14_2_121_dialog_content = "......",
  ui_story_10_14_2_122_dialog_content = "............",
  ui_story_10_14_2_123_dialog_content = "네 증오심은 어디 간 건데?",
  ui_story_10_14_2_124_dialog_content = "왜 소리치고 욕하지 않는 거야? 복수할 생각이 없어졌어? 상대가 암귀라서?",
  ui_story_10_14_2_125_dialog_content = "얼른 부품이나 찾고, 날 죽인 뒤에 네가 좋아하는 친구랑 집에 가서 여유롭게 차나 마실 생각이야?",
  ui_story_10_14_2_126_dialog_content = "PlayerName, 너만 괜찮다면 내가 대신 저 주둥이를 막아줄 수도 있는데 말이지...",
  ui_story_10_14_2_127_dialog_content = "내버려 둬! 사메야마, 당신 상처가 더 나빠지지 않게 조심해...",
  ui_story_10_14_2_128_dialog_content = "보프, 너도 같이 부품 챙기는 거 좀 도와줘.",
  ui_story_10_14_2_129_dialog_content = "아, 알겠어.",
  ui_story_10_14_2_130_dialog_content = "하, 하하하하...",
  ui_story_10_14_2_131_dialog_content = "정말 평화를 사랑하는 종족이네...",
  ui_story_10_14_2_132_dialog_content = "멍청한... 아이테르...",
  ui_story_10_14_2_133_dialog_content = "카렌, 얼음 가시를 줘.",
  ui_story_10_14_2_134_dialog_content = "그래.",
  ui_story_10_14_2_135_dialog_content = "......",
  ui_story_10_14_2_136_dialog_content = "슈모르, 말해. 「<color=#FFB400>피제로</color>」가 누구지?",
  ui_story_10_14_2_137_dialog_content = "「<color=#FFB400>이클립스</color>」가 대체 뭐야?",
  ui_story_10_14_2_138_dialog_content = "...!",
  ui_story_10_14_2_139_dialog_content = "너, 내 기억을 읽었어?!",
  ui_story_10_14_2_140_dialog_content = "그래, 봤어. 비록 일부였지만.",
  ui_story_10_14_2_141_dialog_content = "나머지는 네가 직접 말하게 만들 거야.",
  ui_story_10_14_2_142_dialog_content = "......",
  ui_story_10_14_2_143_dialog_content = "하, 하하하...",
  ui_story_10_14_2_144_dialog_content = "그래, 가까이 와. 말해줄 테니까...",
  ui_story_10_14_2_145_dialog_content = "더 가까이, 이리 와.",
  ui_story_10_14_2_146_dialog_content = "그걸로 날 심판하려는 거 아냐?",
  ui_story_10_14_2_147_dialog_content = "PlayerName! 조심해. 녀석이 무슨 짓을 할지 몰라.",
  ui_story_10_14_2_148_dialog_content = "걱정 마. 그럴 생각 없으니까.",
  ui_story_10_14_2_149_dialog_content = "이미 늦었어...",
  ui_story_10_14_2_150_dialog_content = "그르르...",
  ui_story_10_14_2_151_dialog_content = "크르르...",
  ui_story_10_14_2_152_dialog_content = "뒤를 조심해!",
  ui_story_10_14_2_153_dialog_content = "캬아악!",
  ui_story_10_14_2_154_dialog_content = "아하하... 하하...",
  ui_story_10_14_2_155_dialog_content = "말했잖아. 난 선택받았다고! 난 「이클립스」의 사도야!",
  ui_story_10_14_2_156_dialog_content = "이리 와... 놈들을 포위해...",
  ui_story_10_14_2_157_dialog_content = "그르르...",
  ui_story_10_14_2_158_dialog_content = "크르르...",
  ui_story_10_14_2_159_dialog_content = "마지막에 이기는 건 나라고...",
  ui_story_10_14_2_160_dialog_content = "PlayerName.",
  ui_story_10_14_2_161_dialog_content = "경쟁과 진화... 그건 남들의 머리를 밟고 올라서는 거야!",
  ui_story_10_14_2_162_dialog_content = "너희, 그리고 헤븐즈 밸리야말로 진짜 희생양이라고!",
  ui_story_10_14_2_163_dialog_content = "난 너흴 넘어서고, 이 시험을 통과하면... 이제 누구보다도 더 강해질 거야!",
  ui_story_10_14_2_164_dialog_content = "......",
  ui_story_10_14_2_165_dialog_content = "다들... 도망칠 준비를 해 둬...",
  ui_story_10_14_2_166_dialog_content = "어이! 애송이, 이게 어떻게 얻은 기회인데... 끝까지 싸워야지!",
  ui_story_10_14_2_167_dialog_content = "다들 저 많은 암귀를 상대하는 건 이제 무리잖아. 알고 있다고.",
  ui_story_10_14_2_168_dialog_content = "그리고 그건 각자 나보다 더 잘 느끼고 있을 거야...",
  ui_story_10_14_2_169_dialog_content = "물론 난 복수하고 싶어... 하지만 내 복수를 이루기 위해 모두를 희생시키는 일은 있을 수 없어...",
  ui_story_10_14_2_170_dialog_content = "도망치겠다고? 어디 해 봐. 얼마든지 지켜봐 줄 테니까...",
  ui_story_10_14_2_171_dialog_content = "다 죽어가는 너희가 빠를지, 내 암귀들이 빠를지 어디 보자고!",
  ui_story_10_14_2_172_dialog_content = "전부 죽여버려!",
  ui_story_10_14_2_173_dialog_content = "그르르...",
  ui_story_10_14_2_174_dialog_content = "뭘 멍하니 있어?! 죽이라고!",
  ui_story_10_14_2_175_dialog_content = "캬아악!",
  ui_story_10_14_2_176_dialog_content = "뭐, 뭐야?!",
  ui_story_10_14_2_177_dialog_content = "아, 아파! 이거 놔──!",
  ui_story_10_14_2_178_dialog_content = "내가 아냐! 내가 아니라고!",
  ui_story_10_14_2_179_dialog_content = "싫어어어!",
  ui_story_10_14_2_180_dialog_content = "캬아악!",
  ui_story_10_14_2_181_dialog_content = "......",
  ui_story_10_14_2_182_dialog_content = "지, 지금이야... 어서 도망치자!",
  ui_story_10_14_2_183_dialog_content = "안 그러면 다음은 우리야!",
  ui_story_10_14_2_184_dialog_content = "PlayerName!",
  ui_story_10_14_2_185_dialog_content = "PlayerName 녀석을 끌고 가! 어서!",
  ui_story_10_14_2_186_dialog_content = "가자!",
  ui_story_10_14_2_187_dialog_content = "이런 결말은...",
  ui_story_10_14_2_188_dialog_content = "(받아들일 수 없어!)",
  ui_story_10_14_2_189_dialog_content = "(내가 어떻게... 살아남아서 이 모든 걸 얻었는데...)",
  ui_story_10_14_2_190_dialog_content = "(전부 거짓말쟁이야!)",
  ui_story_10_14_2_191_dialog_content = "(다 가짜라고!)",
  ui_story_10_14_2_192_dialog_content = "(힘도... 심판도... 전부 거짓이야!)",
  ui_story_10_14_2_193_dialog_content = "(노라, 피제로, 이클립스...)",
  ui_story_10_14_2_194_dialog_content = "(너흰... 처음부터... 날 살려둘 생각이 없었던 거야...)",
  ui_story_10_14_2_195_dialog_content = "(너흴 저주하겠어...)",
  ui_story_10_14_2_196_dialog_content = "(나약한 종족의 멸망은 정해진 운명이야...)",
  ui_story_10_14_2_197_dialog_content = "(아이테르는 태어나는 순간부터 저주받은 거라고...)",
  ui_story_10_14_2_198_dialog_content = "(너도 결국엔 나처럼... 비참하게 죽을 거야...)",
  ui_story_10_14_2_199_dialog_content = "(널 저주하겠어...)",
  ui_story_10_14_2_200_dialog_content = "(PlayerName...)",
  ui_story_10_14_2_201_dialog_content = "(파멸의 공포를 느껴 봐...)",
  ui_story_10_14_2_202_dialog_content = "(<color=#FFB400>일식이 시작될 테니까!</color>)",
  ui_story_10_15_1_1_dialog_content = "(내가 뭘 더 할 수 있을까...)",
  ui_story_10_15_1_2_dialog_content = "(녀석은 이미 죽었어...)",
  ui_story_10_15_1_3_dialog_content = "(암귀한테 먹혀서... 그렇게... 비참하게 죽어버렸어...)",
  ui_story_10_15_1_4_dialog_content = "(이제... 우린 어쩌면 좋지... 난 뭘 해야 하는 거지...)",
  ui_story_10_15_1_5_dialog_content = "그르르...",
  ui_story_10_15_1_6_dialog_content = "(다들 다쳤어... 이 암귀들은... 절대 우릴 놓아주지 않을 거야...)",
  ui_story_10_15_1_7_dialog_content = "(그 「일식」 때처럼...)",
  ui_story_10_15_1_8_dialog_content = "(모두를 죽일 거야...)",
  ui_story_10_15_1_9_dialog_content = "어떻게 해야 하냐고...",
  ui_story_10_15_1_10_dialog_content = "달려!",
  ui_story_10_15_1_11_dialog_content = "PlayerName 녀석을 일으켜!",
  ui_story_10_15_1_12_dialog_content = "녀석은 겁에 질려서 넋이 나갔어! 그냥 끌고 가!",
  ui_story_10_15_1_13_dialog_content = "달려! 앞으로 계속 가!",
  ui_story_10_15_1_14_dialog_content = "아, 암귀가 따라오고 있어...",
  ui_story_10_15_1_15_dialog_content = "내가 막을게!",
  ui_story_10_15_1_16_dialog_content = "캬아악!",
  ui_story_10_15_1_17_dialog_content = "카렌?!",
  ui_story_10_15_1_18_dialog_content = "크윽... 괜찮아, 가자!",
  ui_story_10_15_1_19_dialog_content = "이 자식... 겨우 끝이 보일 것 같은데 이제 와서 고생을 시키다니...",
  ui_story_10_15_1_20_dialog_content = "......",
  ui_story_10_15_1_21_dialog_content = "또 쫓아온 건가?! 정말 지긋지긋하네!",
  ui_story_10_15_1_22_dialog_content = "캬아악!",
  ui_story_10_15_1_23_dialog_content = "...!",
  ui_story_10_15_1_24_dialog_content = "PlayerName! 정신 차려!",
  ui_story_10_15_1_25_dialog_content = "모두가 네 힘을 필요로 하고 있단 말이야!",
  ui_story_10_15_1_26_dialog_content = "......",
  ui_story_10_15_1_27_dialog_content = "............",
  ui_story_10_15_1_28_dialog_content = "바이스... 암귀가 길을 막고 있어! 사격해!",
  ui_story_10_15_1_29_dialog_content = "카렌... 먼저 거리를 벌리고... 왼쪽으로 우회해서 공격해!",
  ui_story_10_15_1_30_dialog_content = "속사 감지!",
  ui_story_10_15_1_31_dialog_content = "알겠어!",
  ui_story_10_15_1_32_dialog_content = "끼이익!",
  ui_story_10_15_1_33_dialog_content = "이제야 정신을 차린 모양이네!",
  ui_story_10_15_1_34_dialog_content = "미안해... 방금은... 슈모르가 죽기 전의 감정이 전해져서 정신을 차릴 수가 없었어...",
  ui_story_10_15_1_35_dialog_content = "사과할 필요는 없어. 하지만 어서 평소 상태로 돌아오는 게 좋을 거야.",
  ui_story_10_15_1_36_dialog_content = "우리 싸움이 아직 끝나지 않았으니까.",
  ui_story_10_15_1_37_dialog_content = "난 백야성으로 돌아가 보고해야 하고, 넌 돌아가서 네 스카이워커호를 고쳐야지.",
  ui_story_10_15_1_38_dialog_content = "그러려면 이 암귀들을 전부 해치우고, 살아남아야 해!",
  ui_story_10_15_1_39_dialog_content = "응, 맞아.",
  ui_story_10_15_1_40_dialog_content = "이미 정신 차렸으니까... 이제 내가 모두를 지원할게!",
  ui_story_10_15_1_41_dialog_content = "저기... PlayerName, 다시 기운을 차려서 다행이지만...",
  ui_story_10_15_1_42_dialog_content = "암귀가 너무 많아...",
  ui_story_10_15_1_43_dialog_content = "크오오──!",
  ui_story_10_15_1_44_dialog_content = "솔직히 말하자면 난 죽는 건 두렵지 않아.",
  ui_story_10_15_1_45_dialog_content = "하지만 그렇다고 여기서 죽을 순 없어. 내 동생이 아직 날 기다리고 있다고!",
  ui_story_10_15_1_46_dialog_content = "<size=45>그러니까 다들, 목숨 걸고 싸우는 거다! 그 대신, 죽는 건 허락 못 해!</size>",
  ui_story_10_15_1_47_dialog_content = "사메야마, 목소리가 너무 크잖아... 그리고 당신이 명령을 내릴 차례도 아니라고!",
  ui_story_10_15_1_48_dialog_content = "그르르...",
  ui_story_10_15_1_49_dialog_content = "캬아악!",
  ui_story_10_15_1_50_dialog_content = "전부 이리 오라고!",
  ui_story_10_15_1_51_dialog_content = "암귀가 끌려가고 있잖아?!",
  ui_story_10_15_1_52_dialog_content = "얌전히 엎어져!",
  ui_story_10_15_1_53_dialog_content = "끼이익!",
  ui_story_10_15_1_54_dialog_content = "사메야마! 이 렉커 님이 구해주러 왔다!",
  ui_story_10_15_1_55_dialog_content = "하하하! 너한테도 이런 날이 오다니! 으하하하!",
  ui_story_10_15_1_56_dialog_content = "폭발 조심해!",
  ui_story_10_15_1_57_dialog_content = "우왓?!",
  ui_story_10_15_1_58_dialog_content = "똑바로 좀 못 해?! 나까지 터질 뻔했잖아!",
  ui_story_10_15_1_59_dialog_content = "그러게 제대로 때려잡았어야지, 끌어당기기만 하면 어쩌자는 거야!",
  ui_story_10_15_1_60_dialog_content = "어떻게 된 거야?",
  ui_story_10_15_1_61_dialog_content = "하하하...",
  ui_story_10_15_1_62_dialog_content = "미안하군. 우리 레디젤 렌치 녀석들이다...",
  ui_story_10_15_1_63_dialog_content = "힘은 좋은데, 좀 시끄럽단 말이지.",
  ui_story_10_15_1_64_dialog_content = "휴우... 살았다! 다행이야!",
  ui_story_10_15_1_65_dialog_content = "응... 정말 다행이야...",
  ui_story_10_15_1_66_dialog_content = "휴, 이번엔 정말 힘들었다고... 암귀가 뭐 이리 많은 거야?",
  ui_story_10_15_1_67_dialog_content = "사메야마, 우리가 여기 어떻게 왔는지 알아? 들어 봐. 아까 산이 막 흔들리더니...",
  ui_story_10_15_1_68_dialog_content = "대장! 괜찮아?! 상처가 심하잖아!",
  ui_story_10_15_1_69_dialog_content = "괜찮아. 별거 아니니까...",
  ui_story_10_15_1_70_dialog_content = "오오오! 이 콜로서스, 정말 멋져!",
  ui_story_10_15_1_71_dialog_content = "이걸 가지고 가면 이번에 고생한 대가로 충분할 것 같아!",
  ui_story_10_15_1_72_dialog_content = "다들 빨리 와서 분해해!",
  ui_story_10_15_1_73_dialog_content = "기다려!",
  ui_story_10_15_1_74_dialog_content = "...뭐야, 백야성 사람이잖아?",
  ui_story_10_15_1_75_dialog_content = "오디, 정신이 없어서 소개를 못 했네...",
  ui_story_10_15_1_76_dialog_content = "이쪽은 백야성의 카렌이고, 저기 둘은 PlayerName, 그리고 바이스다.",
  ui_story_10_15_1_77_dialog_content = "잠깐, 잠깐만... 대장, 그 녀석... 백야성의 호위대장이잖아?",
  ui_story_10_15_1_78_dialog_content = "렉커, 조용히 하고 내 말부터 들어!",
  ui_story_10_15_1_79_dialog_content = "오늘 우린 함께 싸운 동료였다.",
  ui_story_10_15_1_80_dialog_content = "안 그런가? 카렌.",
  ui_story_10_15_1_81_dialog_content = "......",
  ui_story_10_15_1_82_dialog_content = "좋아, 그럼 저쪽도 이 콜로서스를 원한다는 거지?",
  ui_story_10_15_1_83_dialog_content = "그럼 누가 더 기여했는지 따져서 분배하는 게 맞지 않겠어?",
  ui_story_10_15_1_84_dialog_content = "오늘 일은 내 말대로 한다. 너흰 아무도 토 달지 마.",
  ui_story_10_15_1_85_dialog_content = "이해가 안 된다면 기지로 돌아가서 내가 다시 설명해 줄 테니까.",
  ui_story_10_15_1_86_dialog_content = "PlayerName!",
  ui_story_10_15_1_87_dialog_content = "이 검은 콜로서스, 필요한 거냐? 우리가 옮겨다 주마!",
  ui_story_10_15_1_88_dialog_content = "뭐?",
  ui_story_10_15_1_89_dialog_content = "아직도 얼빠져 있는 건 아니겠지? 정신 차리라고.",
  ui_story_10_15_1_90_dialog_content = "아, 난 괜찮아... 이미 정신 차렸어.",
  ui_story_10_15_1_91_dialog_content = "그럼 됐다.",
  ui_story_10_15_1_92_dialog_content = "내 말은 그러니까, 이건 네가 가져야 옳다고 생각한다. 이건 너희 아이테르의 콜로서스잖냐.",
  ui_story_10_15_1_93_dialog_content = "대신 제안이 하나 있는데 말이지...",
  ui_story_10_15_1_94_dialog_content = "제안?",
  ui_story_10_15_1_95_dialog_content = "이참에 우리 레디젤 렌치에 들어오지 그래?\n그럼 우리가 이걸 기지로 가져가도 명분이 생기잖아?",
  ui_story_10_15_1_96_dialog_content = "난...",
  ui_story_10_15_1_97_dialog_content = "뭐, 지금 대답할 필요는 없어. 내 생각이 그렇다는 말이니까.",
  ui_story_10_15_1_98_dialog_content = "나중에라도 네가 레디젤 렌치에 오겠다고 한다면, 언제든지 환영이다.",
  ui_story_10_15_1_99_dialog_content = "...고마워.",
  ui_story_10_15_1_100_dialog_content = "하지만 난 세 가지 부품만 있으면 돼.",
  ui_story_10_15_1_101_dialog_content = "디바우러호는... 너희가 알아서 해도 괜찮아.",
  ui_story_10_15_1_102_dialog_content = "좋다. 그럼 거기 두 사람은 어때? 따로 생각이 있나?",
  ui_story_10_15_1_103_dialog_content = "연방이나 백야성 쪽에서도 이 콜로서스에 관심이 있는 거라면,\n우리가 이걸 끌고 가게 내버려 두진 않을 거잖아?",
  ui_story_10_15_1_104_dialog_content = "PlayerName도 괜찮다고 했으니까, 내가 당신들을 막을 이유는 없어.",
  ui_story_10_15_1_105_dialog_content = "나도 상관없어.",
  ui_story_10_15_1_106_dialog_content = "응, 그리고 너희랑 처음 마주쳤을 때부터 난 이미 너희가 콜로서스를 노리고 온 거라고 생각했어.",
  ui_story_10_15_1_107_dialog_content = "그때부터 난 디바우러호를 놓고 너희랑 다툴 생각은 없었어.",
  ui_story_10_15_1_108_dialog_content = "좋아, 역시 의리가 있다니까.",
  ui_story_10_15_1_109_dialog_content = "의리는 무슨 의리야... 난 그냥 이 콜로서스에 관심이 없을 뿐이야.",
  ui_story_10_15_1_110_dialog_content = "PlayerName.",
  ui_story_10_15_1_111_dialog_content = "네가 오늘 겪은 일들 때문에 머리가 복잡할 거라는 건 안다.",
  ui_story_10_15_1_112_dialog_content = "하지만 너무 고민하진 말라고. 넌 충분히 잘했으니까!",
  ui_story_10_15_1_113_dialog_content = "네가 평범한 삶을 되찾고 싶다고 해서, 널 비난할 수 있는 사람은 아무도 없어!",
  ui_story_10_15_1_114_dialog_content = "사메야마...",
  ui_story_10_15_1_115_dialog_content = "고마워.",
  ui_story_10_15_1_116_dialog_content = "방금... 내가 뭘 들은 거지?",
  ui_story_10_15_1_117_dialog_content = "그냥 좀 격려해 준 것뿐이잖아! 뭘 그런 표정으로 보는 거야?!",
  ui_story_10_15_1_118_dialog_content = "아, 됐으니까. 이제 각자 할 일 하러 가자고!",
  ui_story_10_15_1_119_dialog_content = "윽, 쓰읍... 쉴 사람은 쉬고, 일할 사람은 얼른 시작해!",
  ui_story_10_15_1_120_dialog_content = "자, 해산!",
  ui_story_10_15_1_121_dialog_content = "자, 하나 둘 셋 세면 당기는 거야!",
  ui_story_10_15_1_122_dialog_content = "흐읍──!",
  ui_story_10_15_1_123_dialog_content = "렉커! 거기서 뭐 하러 혼자 힘을 쓰고 있어?!",
  ui_story_10_15_1_124_dialog_content = "아, 이건 워밍업이라고!",
  ui_story_10_15_1_125_dialog_content = "설마 이 몸이 네가 「시작해」라고 하면 순순히 시작할 줄 알았어?!",
  ui_story_10_15_1_126_dialog_content = "정말 끌고 갈 수 있을 거라 생각했냐! 이렇게 큰 콜로서스 본 적 있어?!",
  ui_story_10_15_1_127_dialog_content = "아니면... 그냥 쓸만한 부품만 떼서 가는 게 어떨까...",
  ui_story_10_15_1_128_dialog_content = "나도 같은 생각이야.",
  ui_story_10_15_1_129_dialog_content = "보프, 우린 먼저 스카이워커호로 돌아갈게. 혹시 도움이 더 필요해?",
  ui_story_10_15_1_130_dialog_content = "아니, 괜찮아. 이젠 됐어.",
  ui_story_10_15_1_131_dialog_content = "우리가 알아서 해결할게. 신경 안 써도 돼.",
  ui_story_10_15_1_132_dialog_content = "다들 얼른 콜로서스로 돌아가서 쉬는 게 좋겠어. 먼저 치료부터 받는 거 잊지 말고.",
  ui_story_10_15_1_133_dialog_content = "응, 그래야지. 지금도 아프단 말이야...",
  ui_story_10_15_1_134_dialog_content = "가기 전에 사메야마한테 말하고 가려고 했는데, 어디 갔어?",
  ui_story_10_15_1_135_dialog_content = "아... 그게... 아까 대장이 갈 때 따로 인사할 필요는 없다고 했거든.",
  ui_story_10_15_1_136_dialog_content = "알겠어...",
  ui_story_10_15_1_137_dialog_content = "그럼 우리 진짜 간다? 또 봐.",
  ui_story_10_15_1_138_dialog_content = "응, 안녕...",
  ui_story_10_15_1_139_dialog_content = "몸조심해! 다음에 또 봐!",
  ui_story_10_15_1_140_dialog_content = "응, 또 만나자...",
  ui_story_10_15_1_141_dialog_content = "내가... 어떻게 오늘까지 오게 된 걸까?",
  ui_story_10_15_1_142_dialog_content = "처음엔... 그 꿈 때문이었던 것 같은데...",
  ui_story_10_15_1_143_dialog_content = "「살아남아...」",
  ui_story_10_15_1_144_dialog_content = "...또 <color=#FFB400>그 꿈</color>을 꾸신 겁니까?",
  ui_story_10_15_1_145_dialog_content = "응.",
  ui_story_10_15_1_146_dialog_content = "꿈이란 미지에 대한 갈망의 형상화이자, 그것이 가져오는 환상입니다.",
  ui_story_10_15_1_147_dialog_content = "그리고... 멘델슨이 죽었어...",
  ui_story_10_15_1_148_dialog_content = "...17년 전 그날, 난 살아남기 위해 <color=#FFB400>암귀의 힘</color>을 받아들였어...",
  ui_story_10_15_1_149_dialog_content = "한 번 더... 하늘을 보고 싶어...",
  ui_story_10_15_1_150_dialog_content = "그리고 난 마침내 슈모르의 죽음을 봤어...",
  ui_story_10_15_1_151_dialog_content = "(널 저주하겠어...)",
  ui_story_10_15_1_152_dialog_content = "(PlayerName...)",
  ui_story_10_15_1_153_dialog_content = "환상이 아니야... 이 모든 게 현실이야...",
  ui_story_10_15_1_154_dialog_content = "스카이워커...",
  ui_story_10_15_1_155_dialog_content = "드디어 싱크탱크 컴포넌트를 손에 넣었어...\n하지만 네게 이 부품과 연결할 수 있는 시스템이 있는지는... 잘 모르겠어.",
  ui_story_10_15_1_156_dialog_content = "네가 6레벨 콜로서스라는 사실도... 남한테 듣고 나서야 알았으니까...",
  ui_story_10_15_1_E1_dialog_content = "......",
  ui_story_10_15_1_E2_dialog_content = "뭐, 푸념은 네가 「돌아온」 뒤로 미뤄둘게.",
  ui_story_10_15_1_157_dialog_content = "싱크탱크 컴포넌트의 연결부 3개가...",
  ui_story_10_15_1_158_dialog_content = "딱 맞는 것 같아...",
  ui_story_10_15_1_159_dialog_content = "......",
  ui_story_10_15_1_160_dialog_content = "<color=#e8d9bb>「제어 시스템 점검... 이상 무.」</color>",
  ui_story_10_15_1_161_dialog_content = "<color=#e8d9bb>「바이오 모듈 점검... 휴면 중.」</color>",
  ui_story_10_15_1_162_dialog_content = "<color=#e8d9bb>「생명유지 시스템 점검... 작동 중. 현재 탑승자, 1명.」</color>",
  ui_story_10_15_1_163_dialog_content = "<color=#e8d9bb>「엔진 점검... 이상 무.」</color>",
  ui_story_10_15_1_164_dialog_content = "<color=#e8d9bb>「싱크탱크 컴포넌트... 연결 중.」</color>",
  ui_story_10_15_1_165_dialog_content = "<color=#e8d9bb>「1%... 3%... 8%...」</color>",
  ui_story_10_15_1_166_dialog_content = "결국...",
  ui_story_10_15_1_167_dialog_content = "이렇게 끝나버렸네.",
  ui_story_10_15_1_168_dialog_content = "슈모르는 시체조차 안 남았어.",
  ui_story_10_15_1_169_dialog_content = "그래... PlayerName도... 더는 눈길조차 주질 않았어.",
  ui_story_10_15_1_170_dialog_content = "아마 감응 능력으로 슈모르의 숨이 끊어지는 것도 미리 느꼈을 거야.",
  ui_story_10_15_1_171_dialog_content = "이미 죽었으니까, 더는 신경 쓸 필요가 없었던 거겠지.",
  ui_story_10_15_1_172_dialog_content = "하지만... 정말 그걸로 마음이 풀릴까?",
  ui_story_10_15_1_173_dialog_content = "슈모르는 죽었지만... 헤븐즈 밸리를 멸망시킨 암귀는...",
  ui_story_10_15_1_174_dialog_content = "어디에나 있잖아.",
  ui_story_10_15_1_175_dialog_content = "게다가 PlayerName도 말했잖아. 그 「<color=#FFB400>피제로</color>」라는 암귀...",
  ui_story_10_15_1_176_dialog_content = "정작 그 「피제로」가 누구인지는 끝내 알아내질 못했어.",
  ui_story_10_15_1_177_dialog_content = "...그 짧은 시간 동안, 너무 많은 일이 있었으니까.",
  ui_story_10_15_1_178_dialog_content = "어쩌면 미처 물어보지 못한 건지도 몰라...",
  ui_story_10_15_1_179_dialog_content = "슈모르의 죽음을 보고 나서, 조종사는 뭔가 넋이 나간 것처럼 보였어.",
  ui_story_10_15_1_180_dialog_content = "그 뒤에 금방 정신을 차리긴 했지만, 난 그래도 뭔가 잘못된 것 같다는 느낌이 들어.",
  ui_story_10_15_1_181_dialog_content = "우리가 걱정할까 봐 괜찮아진 척했을지도 모르지.",
  ui_story_10_15_1_182_dialog_content = "그게 아니라면... 조종사는 지금 더 중요한 일이 뭔지 잘 알고 있을 거야...",
  ui_story_10_15_1_183_dialog_content = "아무튼, 우리 도움이 필요하게 되면, 분명히 우리한테 말할 거라고 생각해.",
  ui_story_10_15_1_184_dialog_content = "응, 그것도 그래.",
  ui_story_10_15_1_185_dialog_content = "근데... PlayerName 혼자 스카이워커호에 들어간 지 벌써 한참이나 됐는데... 아직도 나오질 않잖아.",
  ui_story_10_15_1_186_dialog_content = "그래서 조금 걱정이 돼...",
  ui_story_10_15_1_187_dialog_content = "부품을 가지고 혼자 가겠다고 한 건, 그만한 이유가 있었을 거야.",
  ui_story_10_15_1_188_dialog_content = "조금 더 기다려 봐.",
  ui_story_10_15_1_189_dialog_content = "그래...",
  ui_story_10_15_1_190_dialog_content = "<color=#e8d9bb>「10%... 23%...」</color>",
  ui_story_10_15_1_191_dialog_content = "<color=#e8d9bb>「33%... 35%...」</color>",
  ui_story_10_15_1_192_dialog_content = "<color=#e8d9bb>「연결 실패. 누적 실패 횟수, 1회.」</color>",
  ui_story_10_15_1_193_dialog_content = "괜찮아, 다시... 한 번 더...",
  ui_story_10_15_1_194_dialog_content = "싱크탱크 컴포넌트 접속...",
  ui_story_10_15_1_195_dialog_content = "<color=#e8d9bb>「싱크탱크 컴포넌트... 연결 중.」</color>",
  ui_story_10_15_1_196_dialog_content = "<color=#e8d9bb>「1%... 3%... 8%...」</color>",
  ui_story_10_15_1_197_dialog_content = "<color=#e8d9bb>「61%... 67%...」</color>",
  ui_story_10_15_1_198_dialog_content = "<color=#e8d9bb>「76%... 85%...」</color>",
  ui_story_10_15_1_199_dialog_content = "<color=#e8d9bb>「연결 실패. 누적 실패 횟수, 2회.」</color>",
  ui_story_10_15_1_200_dialog_content = "그래봤자 고작 두 번이라고... 우리가 처음 엔진을 가동했을 때를 생각해 봐.",
  ui_story_10_15_1_201_dialog_content = "삼천 번 이상 실패했다고.",
  ui_story_10_15_1_202_dialog_content = "괜찮아...",
  ui_story_10_15_1_203_dialog_content = "다시, 다시 시도해 보자.",
  ui_story_10_15_1_204_dialog_content = "첫 번째 단계부터... 다시 시도하는 거야.",
  ui_story_10_15_1_205_dialog_content = "<color=#e8d9bb>「제어 시스템 점검... 이상 무.」</color>",
  ui_story_10_15_1_206_dialog_content = "<color=#e8d9bb>「바이오 모듈 점검... 휴면 중.」</color>",
  ui_story_10_15_1_207_dialog_content = "<color=#e8d9bb>「의식 모듈 점검... 손상됨.」</color>",
  ui_story_10_15_1_208_dialog_content = "<color=#e8d9bb>「생명유지 시스템 점검... 작동 중. 현재 탑승자, 1명.」</color>",
  ui_story_10_15_1_209_dialog_content = "<color=#e8d9bb>「엔진 점검... 이상 무.」</color>",
  ui_story_10_15_1_210_dialog_content = "<color=#e8d9bb>「싱크탱크 컴포넌트... 연결 중.」</color>",
  ui_story_10_15_1_211_dialog_content = "<color=#e8d9bb>「1%... 3%... 8%...」</color>",
  ui_story_10_15_1_212_dialog_content = "<color=#e8d9bb>「10%... 25%...」</color>",
  ui_story_10_15_1_213_dialog_content = "......",
  ui_story_10_15_1_214_dialog_content = "......",
  ui_story_10_15_1_215_dialog_content = "안 되겠어. 역시 들어가 보자!",
  ui_story_10_15_1_216_dialog_content = "아니면 어떻게 되고 있는지 가서 물어보는 정도는 괜찮잖아!",
  ui_story_10_15_1_217_dialog_content = "바이스... 조종사한테 방해가 될지도 몰라.",
  ui_story_10_15_1_218_dialog_content = "나도 알아... 하지만...",
  ui_story_10_15_1_219_dialog_content = "만약 싱크탱크 컴포넌트와 콜로서스를 연결할 수 없다면...",
  ui_story_10_15_1_220_dialog_content = "그렇게 돼서 결국 스카이워커호를 수리할 방법을... 찾을 수 없다면...",
  ui_story_10_15_1_221_dialog_content = "난 조종사가... 그걸 혼자 감당하게 두고 싶지 않아.",
  ui_story_10_15_1_222_dialog_content = "상황을 확인해야겠어! 방해되지 않게 조심할 테니까!",
  ui_story_10_15_1_223_dialog_content = "휴... 너 정말...",
  ui_story_10_15_1_224_dialog_content = "그렇게 걱정되면 밖에서 이름을 부르지 그래?",
  ui_story_10_15_1_225_dialog_content = "녀석은 아이테르잖아. 예민한 감각과 감응 능력이 있으니까...",
  ui_story_10_15_1_226_dialog_content = "분명히 들을 수 있을 거야.",
  ui_story_10_15_1_227_dialog_content = "그럼 혼자 들어가게 두기로 했던 약속도 깨지 않는 셈이잖아?",
  ui_story_10_15_1_228_dialog_content = "그렇구나! 당장 해 볼게!",
  ui_story_10_15_1_229_dialog_content = "그런 방법을 떠올리다니, 역시 카렌이라니까.",
  ui_story_10_15_1_230_dialog_content = "이런 엉뚱한 방법을 떠올릴 수 있는 건... 다 너한테서 배운 거라고...",
  ui_story_10_15_1_231_dialog_content = "후우우...",
  ui_story_10_15_1_232_dialog_content = "PlayerName──!",
  ui_story_10_15_1_233_dialog_content = "<color=#e8d9bb>「89%... 97%...」</color>",
  ui_story_10_15_1_234_dialog_content = "<color=#e8d9bb>「100%, 연결 성공.」</color>",
  ui_story_10_15_1_235_dialog_content = "<color=#e8d9bb>「싱크탱크 컴포넌트 가동을 시작합니다.」</color>",
  ui_story_10_15_1_236_dialog_content = "바이스! 카렌!",
  ui_story_10_15_1_237_dialog_content = "싱크탱크 컴포넌트가 연결됐어! 의식 모듈을 고칠 방법을 찾았다고!",
  ui_story_10_15_1_238_dialog_content = "이제 스카이워커호를 살릴 수 있어!",
  ui_story_10_15_1_239_dialog_content = "그러니까...",
  ui_story_10_15_1_240_dialog_content = "PlayerName, 그 아이테르가 슈모르라는 아이테르 배신자를 물리쳤고...",
  ui_story_10_15_1_241_dialog_content = "레디젤 렌치 쪽에 검은 콜로서스를 넘겨줬다...",
  ui_story_10_15_1_242_dialog_content = "그런데 노라는 그들을 막지 않았고, 돕기까지 했다... 이건가?",
  ui_story_10_15_1_243_dialog_content = "그렇습니다.",
  ui_story_10_15_1_244_dialog_content = "그 아이테르가 우리 계획에 영향을 줄까요?",
  ui_story_10_15_1_245_dialog_content = "아니, 녀석은 일을 더 재미있게 만들어 줄 거야.",
  ui_story_10_15_1_246_dialog_content = "솔라드도 분명히 그렇게 생각하고 있을 거라고.",
  ui_story_70000101_1_dialog_content = "<color=#e8d9bb>「점검 시스템 작동.」</color>",
  ui_story_70000101_2_dialog_content = "<color=#e8d9bb>「제어 시스템 점검... 작동 중. 부품 손상률 39%, 유지 관리 필요.」</color>",
  ui_story_70000101_3_dialog_content = "<color=#e8d9bb>「바이오 모듈 점검... 작동 중. 부품 손상률 46%, 유지 관리 필요.」</color>",
  ui_story_70000101_4_dialog_content = "<color=#e8d9bb>「생명유지 시스템 점검... 작동 중. 경고, 현재 부하량 최대, 유지 관리 필요.」</color>",
  ui_story_70000101_5_dialog_content = "<color=#e8d9bb>「유지 관리 기능 점검... 이상 무. 가동 개시...」</color>",
  ui_story_70000101_6_dialog_content = "<color=#e8d9bb>「에러, 의식 모듈 손상, 유지 관리 작동 불가.」</color>",
  ui_story_70000101_7_dialog_content = "<color=#e8d9bb>「가동 실패. 누적 실패 횟수, 1012회.」</color>",
  ui_story_70000101_8_dialog_content = "<color=#e8d9bb>「의식 모듈을 설치한 후 유지 관리 기능을 사용하십시오.」</color>",
  ui_story_70000101_9_dialog_content = "<color=#e8d9bb>「경고, 부품 손상률이 50%를 넘으면 정상적으로 기능을 실행할 수 없습니다.」</color>",
  ui_story_70000101_10_dialog_content = "<color=#e8d9bb>「서명하십시오.」</color>",
  ui_story_70000101_11_dialog_content = "스카이워커...",
  ui_story_70000101_12_dialog_content = "PlayerName, 스카이워커호는 좀 어때?",
  ui_story_70000101_13_dialog_content = "......",
  ui_story_70000101_14_dialog_content = "아직도 똑같아. 의식 모듈이 없으면 자가 수리를 할 수 없어. 상황이 많이 안 좋아.",
  ui_story_70000101_15_dialog_content = "애초에 가장 먼저 스카이워커호의 복구부터 했어야 했어. 다른 일을 할 게 아니라.",
  ui_story_70000101_16_dialog_content = "네 잘못이 아냐. 스카이워커와 오랫동안 함께 있었는데도 이상을 몰랐던 내 책임도 있어.",
  ui_story_70000101_17_dialog_content = "그리고 너무 걱정할 거 없어. 우린 벌써 해결 방법을 찾았잖아!",
  ui_story_70000101_18_dialog_content = "단서를 찾았어!",
  ui_story_70000101_19_dialog_content = "「싱크탱크 컴포넌트」가 좌표 한 곳을 가리키고 있어. 근데... 이건 어디지?",
  ui_story_70000101_20_dialog_content = "나도 좀 볼게.",
  ui_story_70000101_21_dialog_content = "이 좌표라면... <color=#FFB400>「어둠의 밑바닥」</color>이잖아?!",
  ui_story_70000101_22_dialog_content = "내 기억이 맞다면 여긴 아마... <color=#FFB400>「80호 지하성」</color>이 있는 곳이야.",
  ui_story_70000101_23_option_content = "어둠의 밑바닥...?",
  ui_story_70000101_24_option_content = "80호 지하성...?",
  ui_story_70000101_25_dialog_content = "「어둠의 밑바닥」은 영원한 밤의 땅 근처를 통틀어 부르는 말이야.",
  ui_story_70000101_26_dialog_content = "「80호 지하성」은 이 좌표가 가리키는 위치에 있어.",
  ui_story_70000101_27_dialog_content = "어둠의 밑바닥은 아주 위험한 곳이야.",
  ui_story_70000101_28_dialog_content = "거긴 낮이 짧고 밤이 긴 데다가, 수많은 암귀가 모여 있다고 해.",
  ui_story_70000101_29_dialog_content = "PlayerName, 들리니?",
  ui_story_70000101_30_dialog_content = "어라? 샤엘 씨가 통신을 보냈는데...?",
  ui_story_70000101_31_dialog_content = "「어둠의 밑바닥」에 대해서 알아보고 있다면서? 마침 나한테 단서가 좀 있는데 관심 있어?",
  ui_story_70000101_32_dialog_content = "네? 어떻게 알았어요?!",
  ui_story_70000101_33_dialog_content = "움브라톤의 상인은 비즈니스 찬스를 결코 놓치지 않거든.",
  ui_story_70000101_34_dialog_content = "뭐, 알겠어요... 아마 또 무슨 「특수한 정보망」 같은 거겠죠.",
  ui_story_70000101_35_dialog_content = "역시 단골 손님답네. 말하지 않아도 잘 알고 있잖아.",
  ui_story_70000101_X35_dialog_content = "그럼 무료로 충고 하나 해 줄게.",
  ui_story_70000101_36_dialog_content = "네가 받은 그 좌표에 나온 구역은 아주 위험해. <color=#FFB400>「늪」</color>이라는 별명이 있을 정도거든.",
  ui_story_70000101_37_dialog_content = "...아무리 위험해도 전 가야 해요.",
  ui_story_70000101_38_dialog_content = "싱크탱크 컴포넌트가 준 유일한 단서가 그 장소를 가리키고 있어요.\n스카이워커를 구할 수 있는 기회를 절대 포기할 순 없어요.",
  ui_story_70000101_39_dialog_content = "PlayerName, 일시적인 충동으로 판단을 흐리면 안 돼.",
  ui_story_70000101_40_dialog_content = "준비도 정보도 없이 「늪」에 발을 들이는 건 무모한 짓이야.",
  ui_story_70000101_41_dialog_content = "......",
  ui_story_70000101_42_dialog_content = "맞아, 나도 같은 의견이야.",
  ui_story_70000101_43_dialog_content = "대신 약간의 「대가」를 치를 생각이 있다면, 나도 얼마든지 정보 수집을 도와줄 수 있는데 말이지...",
  ui_story_70000101_44_dialog_content = "윽... 설마 또 나이티움인가요...",
  ui_story_70000101_45_dialog_content = "백야성에도 그 지역에 대한 기록이 있을 거야.",
  ui_story_70000101_46_dialog_content = "내가 가서 찾아봐 줄 수 있어.",
  ui_story_70000101_47_dialog_content = "그럼 부탁할게. 지금은 어떤 도움이든 필요하니까.",
  ui_story_70000101_48_dialog_content = "스카이워커호의 상태를 한 번 더 점검해 봤는데, 아직까진 정상적으로 작동하고 있어.\n그러니까 당분간은 너무 걱정하지 않아도 될 거야.",
  ui_story_70000101_49_dialog_content = "응, 지금쯤이면 아마 카렌이랑 샤엘 씨도 뭔가 정보를 얻었겠지...",
  ui_story_70000101_50_dialog_content = "일루미나의 동료들한테도 단서를 찾아 달라고 부탁했으니까 걱정 마.",
  ui_story_70000101_51_dialog_content = "도움이 될 만한 단서가 있었으면 좋겠는데...",
  ui_story_70000101_52_dialog_content = "지금은 이 좌표가 스카이워커를 구할 수 있는 유일한 희망이니까.",
  ui_story_70000101_53_dialog_content = "이 좌표가 정확하다면, 아마 우린 지하성 하나를 전부 수색해야 할지도 몰라.",
  ui_story_70000101_54_dialog_content = "가장 작은 규모의 지하성이라도 수색에는 며칠이 걸려.",
  ui_story_70000101_55_dialog_content = "구체적인 위치를 확인할 순 없을까?",
  ui_story_70000101_56_dialog_content = "지금은 아직 방향 정도밖에 몰라.",
  ui_story_70000101_57_dialog_content = "대신 목적지에 가까워지면 더 정확한 위치를 알 수 있을지도 몰라.",
  ui_story_70000101_58_dialog_content = "PlayerName, 들려?",
  ui_story_70000101_59_dialog_content = "카렌! 들려!",
  ui_story_70000101_60_dialog_content = "좋아. 난 지금 여명 아카데미 도서관에 있어. 통신 신호가 불안정하니까 간단히 말할게.",
  ui_story_70000101_61_dialog_content = "도서관에 「80호 지하성」의 전쟁에 대한 기록이 있었어.",
  ui_story_70000101_62_dialog_content = "기록에 따르면 「80호 지하성」은 과거 일루미나의 전초기지 겸 수송 중계소였어.",
  ui_story_70000101_63_dialog_content = "그 지하성은 영원한 밤의 땅에 가까워서, 줄곧 일루미나 연방이 암귀에 맞서는 최전선이었어.",
  ui_story_70000101_64_dialog_content = "하지만 <color=#FFB400>「그림자 전투」</color> 때 암귀의 맹공격을 받았고,\n다른 지하성과 거리가 먼 탓에 보급이 끊기고 말았어...",
  ui_story_70000101_65_dialog_content = "결국 일루미나군은 지하성을 포기하고 황급히 철수했지.",
  ui_story_70000101_66_option_content = "「그림자 전투」?",
  ui_story_70000101_67_dialog_content = "들어본 적 있어. 20여 년 전에 있었던 암귀의 대규모 공격 사건이었던 것 같아.",
  ui_story_70000101_68_dialog_content = "수많은 암귀들이 영원한 밤의 땅에서부터 몰려왔고, 전투는... 매우 참혹했다고 해.",
  ui_story_70000101_69_dialog_content = "마지막엔 우리 일루미나 연방이 승리를 거뒀지만, 그 대가는 막대했어.\n여러 개의 지하성을 잃고 수많은 군인들이 목숨을 잃었으니까.",
  ui_story_70000101_70_dialog_content = "여기 책에도 그렇게 쓰여 있었어.",
  ui_story_70000101_71_dialog_content = "일루미나군이 철군하면서 못 가져간 설비도 많았다고 해.\n네가 찾는 것도 아마 그중에 있을 거야.",
  ui_story_70000101_72_dialog_content = "알겠어, 고마워!",
  ui_story_70000101_73_dialog_content = "천만에. 큰일도 아닌걸.",
  ui_story_70000101_X74_dialog_content = "<color=#e8d9bb>뚜── 뚜──</color>",
  ui_story_70000101_75_dialog_content = "또 통신 요청인데? 여보세요?",
  ui_story_70000101_76_dialog_content = "PlayerName, 나야.",
  ui_story_70000101_77_dialog_content = "샤엘 씨! 어때요? 뭔가 좀 알아낸 게 있나요?",
  ui_story_70000101_X77_dialog_content = "정보는 이미 얻었는데... 그리 좋은 소식은 아냐.",
  ui_story_70000101_78_dialog_content = "정보상 말로는 거긴 이미 암귀 소굴이 된 모양이야.",
  ui_story_70000101_79_dialog_content = "스카이워커호가 없다면 아마 그 「늪」의 외곽에도 접근할 수 없을걸.",
  ui_story_70000101_80_dialog_content = "그 지하성 안은 폐허와 전투의 흔적 외에는 아무것도 없다고 해.",
  ui_story_70000101_81_dialog_content = "에너지 코어는 작동을 유지하고 있지만, 상황이 많이 안 좋은 것 같아.\n방어 시스템도 유지할 수 없는 데다가, 언제라도 가동을 멈출 수 있어.",
  ui_story_70000101_82_dialog_content = "혼자 거기서 살아 도망쳐 나온 사람이 남긴 말에 따르면, 지금 지하성의 유일한 통로는...",
  ui_story_70000101_83_dialog_content = "지하성이 붕괴하면서 생긴 <color=#FFB400>갈라진 틈</color>이라고 해.",
  ui_story_70000101_84_dialog_content = "그렇군요...",
  ui_story_70000101_85_dialog_content = "알겠어요.",
  ui_story_70000101_86_dialog_content = "그럼 행운을 빌게.",
  ui_story_70000101_87_dialog_content = "제대로 살아서 돌아와서 잔금을 지불해 줘.",
  ui_story_70000101_88_dialog_content = "아, 알겠어요...",
  ui_story_70000101_89_dialog_content = "이상하네, 필리시 선배 쪽은 아직 정보를 못 찾은 건가...?",
  ui_story_70000101_90_dialog_content = "<color=#e8d9bb>삐비빅──</color>",
  ui_story_70000101_91_dialog_content = "어라? 마침 필리시 선배가 파일을 하나 보냈어.",
  ui_story_70000101_92_dialog_content = "뭔데? 나도 볼래.",
  ui_story_70000101_93_dialog_content = "<color=#FFB400>「어둠의 밑바닥 전투 수첩」...?</color>",
  ui_story_70000101_94_option_content = "이런 수첩도 있어?",
  ui_story_70000101_95_dialog_content = "내가 알기로 이런 건 없었던 것 같은데...",
  ui_story_70000101_96_dialog_content = "근데 내용은 되게 단순해.",
  ui_story_70000101_97_dialog_content = "목차도 없고, 양식도 제대로 갖추고 있지 않아.",
  ui_story_70000101_98_dialog_content = "정규 전투 수첩은 아닌 것 같아.",
  ui_story_70000101_99_dialog_content = "수상한데...",
  ui_story_70000101_100_dialog_content = "하지만 필리시 선배가 잘못된 정보를 줄 리는 없어.",
  ui_story_70000101_101_option_content = "필리시가 도와준 거야?",
  ui_story_70000101_102_dialog_content = "평소 필리시답지 않네.",
  ui_story_70000101_103_dialog_content = "중요한 건 그게 아냐. 뭐, 알려줘도 상관없겠지...",
  ui_story_70000101_104_dialog_content = "필리시 선배는 지난번에 근무 땡땡이치고 낮잠 자러 간 걸\n내가 덮어주길 바라고 있거든...",
  ui_story_70000101_105_dialog_content = "그 조건으로 「80호 지하성」 자료를 주겠다고 약속한 거야.",
  ui_story_70000101_106_dialog_content = "역시 그래야 필리시답지...",
  ui_story_70000101_107_dialog_content = "그래도 정보에 있어서는 필리시 선배가 제일 믿음직하니까.",
  ui_story_70000101_108_dialog_content = "근데... 이 수첩, 아무리 봐도 너무 간략한데?",
  ui_story_70000101_109_dialog_content = "뭐라고 쓰여 있어?",
  ui_story_70000101_110_dialog_content = "「어둠의 밑바닥 전투수첩 제1조...」",
  ui_story_70000101_111_dialog_content = "「어떤 병사도 불필요한 경우에는 어둠의 밑바닥 구역에서 작전을 수행하지 마라!」",
  ui_story_70000101_112_dialog_content = "뭐야?",
  ui_story_70000101_113_dialog_content = "어둠의 밑바닥이... 그렇게나 위험한 곳인 건가?",
  ui_story_70000101_114_dialog_content = "「알려진 정보에 따르면 어둠의 밑바닥은 매우 위험한 구역이다.」",
  ui_story_70000101_115_dialog_content = "「그곳은 짙은 다크매터가 가득 차 있어 오로리안의 행동이 어려워진다.\n또한, 다크매터의 작용은 밤이 되면 더 강해진다.」",
  ui_story_70000101_116_dialog_content = "「한편, 그곳은 암귀가 다수 분포해 있고, 그중에는 극도로 강한 개체도 있어 매우 위험하다!」",
  ui_story_70000101_117_dialog_content = "일루미나의 병사가 들어갈 수 없는 곳이라니... 나랑 같이 가면 너도 곤란해지는 거 아냐?",
  ui_story_70000101_119_dialog_content = "너까지 휘말려서 처벌을 받게 만들 순 없어.",
  ui_story_70000101_120_dialog_content = "아니면... 내가 지금 바로 히이로 씨한테 가서 사정을 설명할게!",
  ui_story_70000101_121_dialog_content = "PlayerName...",
  ui_story_70000101_122_dialog_content = "난 괜찮아.",
  ui_story_70000101_123_dialog_content = "스카이워커호는 PlayerName의 소중한 가족이잖아. 그리고 나한테도 소중한 동료야.",
  ui_story_70000101_124_dialog_content = "동료가 곤란한데 어떻게 보고만 있을 수 있겠어!",
  ui_story_70000101_125_dialog_content = "그리고 난 이미 지금 상황을 알고 있잖아.\n알면서도 보고하지 않는 건 일루미나의 군법에 따라 공범으로 처벌되게 돼 있어.",
  ui_story_70000101_126_dialog_content = "이번 일이 대원수님과 군단장님들한테만 알려지지 않는다면 괜찮을 거야...",
  ui_story_70000101_127_dialog_content = "그래, 분명히 문제없을 거야!",
  ui_story_70000101_128_dialog_content = "미안, 너까지 위험하게 만들어서...",
  ui_story_70000101_129_dialog_content = "괜찮아. 그리고 이 수첩 말인데, 그곳에서 싸울 때 주의해야 할 점은\n오히려 자세히 적혀 있는 것 같아.",
  ui_story_70000101_130_dialog_content = "근데... 대체 누가 이걸 쓴 거지?",
  ui_story_70000101_131_dialog_content = "그건 다음에 다시 생각해 보자.",
  ui_story_70000101_132_dialog_content = "지금 급한 건 이 정보에 따라 작전 계획을 세우는 거니까.",
  ui_story_70000101_133_dialog_content = "대량의 암귀가 있고, 다크매터의 영향이 밤에 증가하는 곳...\n그리고 밤이 길고 낮이 짧은 제약까지...",
  ui_story_70000101_134_dialog_content = "상당히 어려운 작전이 되겠는걸...",
  ui_story_70000101_135_dialog_content = "스카이워커의 우세를 이용해서 날아가면 도중의 암귀는 무시할 수 있어.",
  ui_story_70000101_136_dialog_content = "지하성에 들어가고 나면 싱크탱크 컴포넌트의 위치 측정 기능으로 목표물을 찾자.",
  ui_story_70000101_137_dialog_content = "최대한 속전속결을 목표로 하면 낮 동안에 작전을 마칠 수 있을지도 몰라...",
  ui_story_70000101_138_dialog_content = "그래도 위험한 건 마찬가지야. 만약 지하에 고위 암귀가 숨어 있으면 어떡해?",
  ui_story_70000101_139_dialog_content = "피해서 가야지. 우리 목적은 싸우는 게 아냐. 부품만 찾으면 바로 철수하자.",
  ui_story_70000101_140_dialog_content = "알았어.",
  ui_story_70000101_141_dialog_content = "좋아, 그럼 출발하자. 목적지는 「80호 지하성」!",
  ui_story_70000101_142_dialog_content = "<color=#e8d9bb>일루미나 안전 구역</color>",
  ui_story_70000101_143_dialog_content = "스카이워커호는 곧 안전 구역을 벗어나 「80호 지하성」 방향으로 갈 거예요.",
  ui_story_70000101_144_dialog_content = "...정말 두 사람을 그냥 내버려 두실 건가요?",
  ui_story_70000101_145_dialog_content = "음? 나 불렀어?",
  ui_story_70000101_146_dialog_content = "네... 이번 일에 대한 결정을 내릴 수 있는 건... 대원수님뿐이니까요.",
  ui_story_70000101_147_dialog_content = "두 사람이 필리시 쪽에 80호 지하성의 조사를 부탁한 걸 알아챈 건 너잖아.\n그럼 두 사람의 목적도 알고 있겠지?",
  ui_story_70000101_148_dialog_content = "네, 두 사람은 80호 지하성에 콜로서스의 의식 모듈을 복구할\n고대 기술의 부품이 있다는 정보를 얻은 것 같아요.",
  ui_story_70000101_149_dialog_content = "저들이 왜 그걸 찾는 거지?",
  ui_story_70000101_150_dialog_content = "그건... 지난번 슈모르, 노라와의 일전에서 그의 콜로서스...\n스카이워커호의 의식 모듈이 파괴당했거든요.",
  ui_story_70000101_151_dialog_content = "그에게 콜로서스는 가족과 같은 존재예요.\n그러니까 콜로서스가 의식 모듈을 잃은 건 목숨을 잃은 것이나 다름없겠죠.",
  ui_story_70000101_152_dialog_content = "그렇다면 이해할 수 있는 일이잖아.",
  ui_story_70000101_153_dialog_content = "가족을 구하려는 사람을 막을 이유는 없어.",
  ui_story_70000101_154_dialog_content = "그에게 악의가 없다면, 어느 정도는 내버려 두는 것도 상관없다고 생각하는데 말이지.",
  ui_story_70000101_155_dialog_content = "그동안 일루미나가 암귀에 맞서 싸우는 걸 도와줬으니, 그에 대한 보상인 셈 치자고.",
  ui_story_70000101_156_dialog_content = "하지만 위원회에는 어떻게 해명하실 거죠? 그쪽에선 누구든지 어둠의 밑바닥 구역을\n탐색하는 걸 용납하지 않았어요. 대원수님도 마찬가지고요.",
  ui_story_70000101_157_dialog_content = "그건 확실히 문제란 말이지...",
  ui_story_70000101_158_dialog_content = "그럼 이렇게 전해. 아이테르가 어둠의 밑바닥 구역에 들어간 건 자기 의지였고,\n우린 도중에 막으려고 했지만 실패한 거지.",
  ui_story_70000101_159_dialog_content = "위원회의 금지령 때문에 일루미나군은 어둠의 밑바닥에 들어가지 않았고,\n안전 구역에서 대기하기로 했다고 말이야.",
  ui_story_70000101_160_dialog_content = "저 아이테르는 일루미나 사람도 아니고, 게다가 각 세력에 인맥을 가지고 있지.",
  ui_story_70000101_161_dialog_content = "그 점만으로도 위원회는 그자를 곤란하게 하지 않을 거야.",
  ui_story_70000101_162_dialog_content = "하지만 대원수님, 그래도 거긴 너무 위험해요.",
  ui_story_70000101_163_dialog_content = "저들은 많은 전투를 겪었어. 그 능력은 일단 신뢰할 만해.",
  ui_story_70000101_164_dialog_content = "그저 신중하게, 그 「지휘 수첩」대로만 행동한다면 문제없을 거다.",
  ui_story_70000101_165_dialog_content = "그럼... 대원수님은 왜 아직도 여기 계신 거죠?",
  ui_story_70000101_166_dialog_content = "저들에겐 뛰어난 전투 능력 외에도 필요한 게 있을 테니까. 예를 들면──",
  ui_story_70000101_167_dialog_content = "언제든 저들을 「늪」에서 끌어올려 줄 수 있는 생명줄이라든지 말이야.",
  ui_story_70000101_168_dialog_content = "각 부대에 경계를 늦추지 않도록 명령해라. 어둠의 밑바닥 쪽 상황을 계속 주시하도록.",
  ui_story_70000101_169_dialog_content = "네, 대원수님.",
  ui_story_70000101_170_dialog_content = "필리시?",
  ui_story_70000101_171_dialog_content = "우냐앙?!",
  ui_story_70000101_172_dialog_content = "네 단말기는 내가 잠시 맡아두지.",
  ui_story_70000101_173_dialog_content = "그리고 네 태업 건은 이번 일이 끝난 뒤에 다시 이야기하자고.",
  ui_story_70000101_174_dialog_content = "네...",
  ui_story_70000101_175_dialog_content = "넌 가서 「80호 지하성」 방향의 상황을 감시하고, 뭔가 이상이 있으면 즉시 내게 보고해라.",
  ui_story_70000101_176_dialog_content = "알겠습니다냥...",
  ui_story_70000101_177_dialog_content = "휴, 바이스, 너흰 엄청 귀찮은 일에 말려들어 버렸다냥...",
  ui_story_70000101_178_dialog_content = "「80호 지하성」...",
  ui_story_70000101_179_dialog_content = "거긴 아무나 마음대로 갈 수 있는 곳이 아니라고.\n그 두 녀석, 배짱 하나는 대단하네.",
  ui_story_70000201_1_dialog_content = "우린 이미 일루미나 연방이 영원한 밤의 땅 변경에 설치한 안전 구역 경계선을 넘었어.",
  ui_story_70000201_2_dialog_content = "이제 곧 80호 지하성에 도착할 거야.",
  ui_story_70000201_3_dialog_content = "하늘이 확실히 어두워지고 있어. 저게 바로 「어둠의 밑바닥」이란 건가?",
  ui_story_70000201_4_dialog_content = "저런 어두운 환경을 보니까 확실히 기분이 나빠져. 숨 쉬는 것까지 갑갑해지는 느낌이야.",
  ui_story_70000201_5_dialog_content = "전투에 영향이 없었으면 좋겠는데...",
  ui_story_70000201_6_dialog_content = "수첩에는 뭐라고 적혀 있어?",
  ui_story_70000201_7_dialog_content = "어디 보자...",
  ui_story_70000201_8_dialog_content = "「제3조: 『늪』에서의 작전 시 최대한 전투를 피하고, 자신의 역량에 맞게 행동한다.」",
  ui_story_70000201_9_dialog_content = "「80호 지하성에는 숨을 쉴 수 없을 정도로 무겁고 짙은 다크매터가 가득하다.\n때문에 『늪』이라는 별명으로 불리기도 한다.」",
  ui_story_70000201_10_dialog_content = "「그 다크매터는 통신 전파마저도 교란시키며,\n몇 미터만 떨어져도 통신기를 정상적으로 사용할 수 없게 된다.」",
  ui_story_70000201_11_dialog_content = "「게다가 이러한 다크매터의 영향은 시간이 갈수록 더 심해진다.」",
  ui_story_70000201_12_dialog_content = "「야간의 영향력은 주간의 2배 이상이다.」",
  ui_story_70000201_13_dialog_content = "그럼 평범한 암귀라도 상대하기 힘들게 된다는 거겠네.",
  ui_story_70000201_14_dialog_content = "아무래도 되도록 전투를 피하는 수밖에 없겠어.",
  ui_story_70000201_15_dialog_content = "그래. 게다가 시간제한도 있잖아. 밤이 되면 상황이 더 불리해질 거야.",
  ui_story_70000201_16_dialog_content = "스카이워커의 기동력을 활용해서 최대한 낮에 모든 걸 끝내야 해.",
  ui_story_70000201_17_dialog_content = "PlayerName... 왠지 듬직해진 것 같네.",
  ui_story_70000201_18_dialog_content = "응? 그, 그래?",
  ui_story_70000201_19_dialog_content = "갑자기 그런 말을 하니까 좀 부끄러운데...",
  ui_story_70000201_20_dialog_content = "근데 그러고 보니까 아까부터 든 생각이 있어.",
  ui_story_70000201_21_dialog_content = "이 수첩을 쓴 사람, 80호 지하성에 대해 이렇게 잘 알고 있다는 건...\n전에 거기서 싸운 적이 있다는 거겠지?",
  ui_story_70000201_22_dialog_content = "그건 잘 모르겠어...",
  ui_story_70000201_23_dialog_content = "이 수첩은 정규 양식으로 쓰인 것도 아니고, 서명도 없어.",
  ui_story_70000201_24_dialog_content = "어느 전선의 지휘관이 임시로 부하들에게 남긴 「주의사항」 같다는 느낌이야.",
  ui_story_70000201_25_dialog_content = "이상하네...",
  ui_story_70000201_26_dialog_content = "그래도 필리시 선배가 준 자료니까, 분명히 믿을 수 있을 거야.",
  ui_story_70000201_27_dialog_content = "그저 최악의 상황만 안 오길 빌어야겠지.",
  ui_story_70000201_28_dialog_content = "PlayerName, 밖을 봐!",
  ui_story_70000201_29_dialog_content = "저게 80호 지하성인가?",
  ui_story_70000201_30_dialog_content = "도착한 거야?",
  ui_story_70000201_31_dialog_content = "상상했던 거랑 전혀 다른데...",
  ui_story_70000201_32_dialog_content = "내가 아는 일루미나 지하성은 단단한 철벽이랑 대포들이 삼엄하게 늘어선 곳이었는데...",
  ui_story_70000201_33_dialog_content = "보이는 건 불에 탄 흔적, 총탄 자국이 남은 무너진 담벼락...\n곳곳에 버려진 못쓸 무기 잔해들밖에 없어.",
  ui_story_70000201_34_dialog_content = "재난과 전쟁에 계속 짓밟혀 온 것처럼 말이야...",
  ui_story_70000201_35_dialog_content = "이런 곳에... 정말 우리가 찾는 모듈이 있을까?",
  ui_story_70000201_36_dialog_content = "격전이 벌어졌던 곳이고, 게다가 오랜 시간 동안 버려졌으니까...",
  ui_story_70000201_37_dialog_content = "지금은 이미 암귀의 소굴이 되어 있겠지...",
  ui_story_70000201_38_dialog_content = "그래도 난 언젠가는 일루미나가 이곳으로 돌아올 거라고 믿고 있어.",
  ui_story_70000201_39_dialog_content = "모든 지하성은 귀중한 에너지와 물자, 그리고 과학 기술을 간직하고 있으니까.",
  ui_story_70000201_40_dialog_content = "일루미나는... 절대로 그걸 암귀의 손에 넘어가게 두지 않을 거야.",
  ui_story_70000201_41_dialog_content = "......",
  ui_story_70000201_42_dialog_content = "지금 지상에는 암귀가 많이 돌아다니고 있어... 놈들과 싸우는 건 시간 낭비야.",
  ui_story_70000201_43_dialog_content = "어딘가 숨을 수 있는 곳에 멈춰서 몰래 지하성으로 들어가자.",
  ui_story_70000201_44_dialog_content = "지금은 아직 새벽이니까 시간은 충분할 거야!",
  ui_story_70000201_45_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_70000201_46_dialog_content = "이게... 다크매터의 부작용인가?",
  ui_story_70000201_47_dialog_content = "몸이 엄청 무거워... 마치 수십 킬로그램짜리 모래주머니를 메고 다니는 것 같아...",
  ui_story_70000201_48_dialog_content = "나도 그래, 몇 걸음만 걸어도 숨이 차...",
  ui_story_70000201_49_dialog_content = "아마 이게 수첩에 적혀 있던... 어둠의 밑바닥의 영향인 거겠지.",
  ui_story_70000201_50_dialog_content = "이런 상황에선 전투는 거의 불가능할 것 같아...",
  ui_story_70000201_51_dialog_content = "일단 어떻게든 입구부터 찾자.",
  ui_story_70000201_52_dialog_content = "이런 식으로 붕괴한 이상, 기존의 입구를 찾아내는 건 무리야.",
  ui_story_70000201_53_dialog_content = "버려진 철판에 희미하게 「80」이라는 흰 글씨가 보여.\n여기가 한때 일루미나의 지하성이었다는 증거겠지...",
  ui_story_70000201_54_dialog_content = "골조가 끊어져서 바깥쪽 방어벽이 완전히 무너졌어. 건물의 형체도 이미 변해버렸어...",
  ui_story_70000201_55_dialog_content = "이 정도면 진도 9 이상의 지진이 벌어진 정도의 피해야.\n아니면 정예 암귀의 공격을 24시간 이상 받았거나...",
  ui_story_70000201_56_dialog_content = "그렇지 않고서는 일루미나의 방어시설이 이렇게까지 파괴될 순 없어.",
  ui_story_70000201_57_dialog_content = "입구 상황은 어때?",
  ui_story_70000201_58_dialog_content = "완전히 묻혀버렸어.",
  ui_story_70000201_59_dialog_content = "적어도 보이는 범위 내에선 지하 구역으로 들어갈 통로는 안 보여.",
  ui_story_70000201_60_dialog_content = "역시 샤엘 씨가 말한 <color=#FFB400>갈라진 틈</color>을 찾는 수밖에 없겠어.",
  ui_story_70000201_61_dialog_content = "크오오──!",
  ui_story_70000201_62_dialog_content = "PlayerName! 옆에 조심해!",
  ui_story_70000201_63_dialog_content = "갑자기 어디서 나타난 거야?!",
  ui_story_70000201_64_dialog_content = "놈들이 나타난 방향에 갈라진 틈이 있어!",
  ui_story_70000201_65_dialog_content = "아무래도 싸움을 피할 수 없을 것 같아...",
  ui_story_70000201_66_dialog_content = "바이스, 수첩에 적혀 있는 대로 신중하게 대응하자.",
  ui_story_70000201_67_dialog_content = "맡겨줘!",
  ui_story_70000202_1_dialog_content = "후우... 후우...",
  ui_story_70000202_2_dialog_content = "이제... 끝난 건가?",
  ui_story_70000202_3_dialog_content = "머리가... 깨질 것처럼 아파.",
  ui_story_70000202_4_dialog_content = "빛의 궤적도 잘 보이지 않을 정도야...",
  ui_story_70000202_5_dialog_content = "PlayerName?!",
  ui_story_70000202_6_dialog_content = "괜찮아... 거의 기절할 뻔하긴 했지만.",
  ui_story_70000202_7_dialog_content = "또 문제가 생기기 전에 조용히 이동하자.",
  ui_story_70000202_8_dialog_content = "이 정도로 힘든 환경일 줄은 몰랐는데...",
  ui_story_70000202_9_dialog_content = "그래도 포기할 순 없어. 스카이워커를 구하기 위해서라면...",
  ui_story_70000202_10_dialog_content = "일단 틈 안을 살펴보자.",
  ui_story_70000202_11_dialog_content = "뭐야...",
  ui_story_70000202_12_dialog_content = "이게 어딜 봐서 틈이냐고...",
  ui_story_70000202_13_dialog_content = "이건 그냥 수직으로 떨어지는 절벽이잖아!",
  ui_story_70000202_14_dialog_content = "밑에 뭔가 반짝이는 게 보여.",
  ui_story_70000202_15_dialog_content = "기계의 지시등인 것 같아!",
  ui_story_70000202_16_dialog_content = "이 지하성... 설마 아직도 가동되고 있는 건가?!",
  ui_story_70000202_17_dialog_content = "저쪽에 튀어나온 배관 같은 게 있어. 저걸 발판으로 쓸 수 있을 것 같아...",
  ui_story_70000202_18_dialog_content = "이 높이라면 내가 널 데리고 아래까지 내려갈 수 있을 거야.",
  ui_story_70000202_19_dialog_content = "대신 나갈 때는 다른 길을 찾아야겠지.",
  ui_story_70000202_20_dialog_content = "출구에 대한 정보도... 수첩에 적혀 있어?",
  ui_story_70000202_21_dialog_content = "있었던 것 같아. 확인해 볼게!",
  ui_story_70000202_22_dialog_content = "「80호 지하성에는 심층부 코어 룸에서 지상으로 통하는 대피로가 있다.」",
  ui_story_70000202_23_dialog_content = "「그러나 적의 진입을 막기 위해 이 통로는 안에서만 열 수 있다.」",
  ui_story_70000202_24_dialog_content = "「통로의 입구는 감춰져 있으며, 지하성의 에너지 코어 쪽 숨겨진 문 안에 있다.」",
  ui_story_70000202_25_dialog_content = "「가볍게 3번, 세게 3번, 다시 가볍게 3번\n코어 룸의 북쪽 벽을 두드리면 숨겨진 문을 열 수 있다.」",
  ui_story_70000202_26_dialog_content = "샤엘 씨도 모르는 자세한 정보가 쓰여 있잖아?!",
  ui_story_70000202_27_dialog_content = "80호 지하성에 대해 이렇게까지 자세히 알고 있는 걸 보면...\n이걸 쓴 사람은 전에 여기서 근무했거나, 전투에 참여한 게 분명해.",
  ui_story_70000202_28_dialog_content = "지상으로 돌아가는 방법은 알았으니까, 이제 움직일 차례야.",
  ui_story_70000202_29_dialog_content = "PlayerName, 날 꽉 잡아.",
  ui_story_70000202_30_dialog_content = "안 하면 안 될까...? 이러면 꼭 내가...",
  ui_story_70000202_31_dialog_content = "에잇!",
  ui_story_70000202_32_dialog_content = "<anim type=Shake>으아아악──!</anim>",
  ui_story_70000202_33_dialog_content = "이건 꼭──",
  ui_story_70000202_34_dialog_content = "PlayerName, 혀 안 깨물게 조심해!",
  ui_story_70000202_35_dialog_content = "<size=45><anim type=Shake>으아아아──!</anim></size>",
  ui_story_70000202_36_dialog_content = "에잇!",
  ui_story_70000202_37_dialog_content = "<size=50><anim type=Shake>아아아악──!</anim></size>",
  ui_story_70000202_38_dialog_content = "...PlayerName, 벌써 다 왔어.",
  ui_story_70000202_39_dialog_content = "아... 어? 그, 그래?",
  ui_story_70000202_40_dialog_content = "괜찮아?",
  ui_story_70000202_41_dialog_content = "벌써... 다 내려왔다고?",
  ui_story_70000202_42_dialog_content = "머리가 어지러워... 안 되겠어...",
  ui_story_70000202_43_dialog_content = "어라? 착지가 불안정했나? 좀 쉬었다 갈래?",
  ui_story_70000202_44_dialog_content = "조금만 쉬면 괜찮아질 것 같아...",
  ui_story_70000202_45_dialog_content = "주변 상황은 어때?",
  ui_story_70000202_46_dialog_content = "일단 암귀는 안 보여.",
  ui_story_70000202_47_dialog_content = "여긴... 아직 지하성의 표면인 것 같아.",
  ui_story_70000202_48_dialog_content = "폐허랑 기계 잔해가 곳곳에 널려 있어. 일루미나 제식 장비의 파편들도 섞여 있고.",
  ui_story_70000202_49_dialog_content = "벽의 표지엔... <color=#FFB400>「2호 환기 샤프트」</color>라고 쓰여 있어.",
  ui_story_70000202_50_dialog_content = "지하성 내부로 들어온 건 맞는 것 같네.",
  ui_story_70000202_51_dialog_content = "벽엔 온통 총탄 자국투성이야. 분명히 여기서 무척 참혹한 전투가 벌어졌겠지...",
  ui_story_70000202_52_dialog_content = "「그림자 전투」 말이지?",
  ui_story_70000202_53_dialog_content = "땅에 떨어진 총탄의 모델 넘버를 보면 예전 일루미나의 제식 장비가 맞아.\n그러니까 아마 그때가 맞을 거야.",
  ui_story_70000202_54_dialog_content = "다른 사람이 여기로 돌아오는 걸 이 수첩의 주인이 원하지 않는 이유가 있었어.",
  ui_story_70000202_55_dialog_content = "이곳은 마치... 생명을 집어삼키는 늪 같은 곳이니까.",
  ui_story_70000202_56_dialog_content = "......",
  ui_story_70000202_57_option_content = "[총탄 자국을 만진다]",
  ui_story_70000202_58_option_content = "[탄피를 줍는다]",
  ui_story_70000202_59_dialog_content = "오, 오지 마!",
  ui_story_70000202_60_dialog_content = "크오오──!",
  ui_story_70000202_61_dialog_content = "사... 살려줘...",
  ui_story_70000202_62_dialog_content = "흐이익──!",
  ui_story_70000202_63_dialog_content = "제발 먹지 마... 나 같은 건 맛도 없다고!",
  ui_story_70000202_64_dialog_content = "그어어어!",
  ui_story_70000202_65_dialog_content = "으아악... 어, 엄마...",
  ui_story_70000202_66_dialog_content = "나... 이제 돌아갈 수 없어...",
  ui_story_70000202_67_dialog_content = "......",
  ui_story_70000202_68_dialog_content = "PlayerName... 전쟁 때 일이 보였어?",
  ui_story_70000202_69_dialog_content = "응...",
  ui_story_70000202_70_dialog_content = "그건... 우리가 어떻게 할 수 없는 일이야. 너무 괴로워하지 마.",
  ui_story_70000202_71_dialog_content = "목표물의 위치를 다시 찾아보자.",
  ui_story_70000202_72_dialog_content = "알았어, 감응해 볼게.",
  ui_story_70000202_73_option_content = "(감응 전개!)",
  ui_story_70000202_74_dialog_content = "...!",
  ui_story_70000202_75_dialog_content = "우리가 찾는 물건은 더 아래에 있어.",
  ui_story_70000202_76_dialog_content = "간섭이 심해서 감응할 수 있는 건 대략적인 방향뿐이야.",
  ui_story_70000202_77_dialog_content = "저쪽이야!",
  ui_story_70000202_78_dialog_content = "또 절벽이네...",
  ui_story_70000202_79_dialog_content = "이건 아까보다 더 깊은 것 같아. 게다가 발판이 될 만한 것도 없어...",
  ui_story_70000202_80_dialog_content = "이대로 뛰어내리면 엄청 큰 소리가 날 거야.",
  ui_story_70000202_81_dialog_content = "그럼 주변의 암귀들이 우리 쪽으로 몰려올지도 몰라.",
  ui_story_70000202_82_dialog_content = "그래도 감응 능력이 우릴 이쪽으로 안내한 건 여기가 가장 지름길이라는 거잖아.",
  ui_story_70000202_83_dialog_content = "시간이 얼마나 남았지?",
  ui_story_70000202_84_dialog_content = "여유는 없을 것 같아.",
  ui_story_70000202_85_dialog_content = "여긴 다른 곳보다 낮이 훨씬 짧아서 6시간 정도밖에 안 돼.",
  ui_story_70000202_86_dialog_content = "해가 지기 전까지 돌아가려면 우리한테 남은 건 이제 3시간뿐이야.",
  ui_story_70000202_87_dialog_content = "이 길로 가자. 아래로 내려가서 바로 숨으면 괜찮을 거야!",
  ui_story_70000202_88_dialog_content = "...알았어, 널 믿을게.",
  ui_story_70000301_1_dialog_content = "두 녀석은 지금 어디쯤이지?",
  ui_story_70000301_2_dialog_content = "보고드립니다냥. 장치의 위치 측정 정보에 따르면 아직 80호 지하성 안에 있습니다냥.",
  ui_story_70000301_3_dialog_content = "다크매터의 간섭 때문인지 신호가 자꾸 끊겨서...\n어쩌면 이미 심층부에 들어갔을지도 모르겠습니다냥.",
  ui_story_70000301_4_dialog_content = "일이 순조롭게 풀렸으면 좋겠는데 말이죠...",
  ui_story_70000301_5_dialog_content = "조급해하지 말고 평정을 유지하라.",
  ui_story_70000301_6_dialog_content = "잠입 작전을 수행 중인 병사에게 있어서는 무소식이 희소식이다.",
  ui_story_70000301_7_dialog_content = "그렇게 판단하신 근거가 있나요?",
  ui_story_70000301_8_dialog_content = "모든 일루미나인은 나의 병사다.\n대원수로서 난 당연히 부하들의 능력을 충분히 파악하고 있지.",
  ui_story_70000301_9_dialog_content = "게다가 <color=#FFB400>그자</color>와 함께하면서부터 바이스는 내 「특별한 관심」을 받게 됐거든.",
  ui_story_70000301_10_dialog_content = "너도 그리 걱정할 필요 없다. 내가 「수첩」에 보험을 남겨 놨으니까.",
  ui_story_70000301_11_dialog_content = "「보험」이요...?",
  ui_story_70000301_12_dialog_content = "1시간 반 이후에 저들이 아직도 지하성 안에 있다면 통신기로 저들에게 연락해라.",
  ui_story_70000301_13_dialog_content = "네.",
  ui_story_70000301_14_dialog_content = "......",
  ui_story_70000301_15_dialog_content = "PlayerName, 이쪽이야.",
  ui_story_70000301_16_dialog_content = "이쪽은 암귀들이 확실히 많아졌어...",
  ui_story_70000301_17_dialog_content = "걷는 것도... 더 힘들어진 것 같아.",
  ui_story_70000301_18_dialog_content = "조금만 더 힘내, PlayerName.",
  ui_story_70000301_19_dialog_content = "안 되겠어. 너무 힘들어...",
  ui_story_70000301_20_dialog_content = "여긴 너무 위험해. 쉬고 싶으면 적어도 어디 숨을 곳이라도 찾아야지.",
  ui_story_70000301_21_dialog_content = "봐, 몇백 미터만 더 걸으면 코어 룸 바로 위에 도착할 거야.",
  ui_story_70000301_22_dialog_content = "도저히 못 걷겠으면... 내가 업어줄까?",
  ui_story_70000301_23_dialog_content = "아, 아니야. 그럴 필요 없어...",
  ui_story_70000301_24_dialog_content = "숨만 조금 고르면 괜찮을 거야!",
  ui_story_70000301_25_dialog_content = "물건을 손에 넣고 스카이워커호로 돌아가면 내가 맛있는 걸 잔뜩 만들어 줄게!",
  ui_story_70000301_26_dialog_content = "...그건 진짜로 필요 없어!",
  ui_story_70000301_27_dialog_content = "나, 나 하나도 안 피곤해! 가자!",
  ui_story_70000301_28_dialog_content = "앞에 암귀가 있어. 수는... 안 되겠어. 너무 어두워서 그림자밖에 안 보여.",
  ui_story_70000301_29_dialog_content = "코어 룸으로 향하는 통로 입구를 딱 막고 있는 건가... 곤란한데.",
  ui_story_70000301_30_dialog_content = "피해 갈 순 없을까?",
  ui_story_70000301_31_dialog_content = "지도를 좀 볼게!",
  ui_story_70000301_32_dialog_content = "뭐? 지도는 어디서 난 건데?!",
  ui_story_70000301_33_dialog_content = "어라? 아까 못 봤어?",
  ui_story_70000301_34_dialog_content = "아까 네가 잠깐 쉴 때 찢어진 지도 반쪽이 폐허에 있길래 공책에 베껴놨어.",
  ui_story_70000301_35_dialog_content = "그런 기억력이 가능한 거구나...",
  ui_story_70000301_36_dialog_content = "제도라면 나한텐 식은 죽 먹기니까.",
  ui_story_70000301_37_dialog_content = "게다가 지하성의 건설 방식은 전부 일정한 규칙성을 따르고 있거든.\n그것만 알고 있으면 지도를 기억하는 것도 어렵지 않아.",
  ui_story_70000301_38_dialog_content = "예를 들어 대피로는 보통 2개 이상이고, 환풍구는 보통 지하성의...",
  ui_story_70000301_39_dialog_content = "거기까지! 내가 지금 알고 싶은 건 암귀를 피해서 갈 방법이 있는지야...",
  ui_story_70000301_40_dialog_content = "길은 있어. 근데 뚫려 있는지는 모르겠어.",
  ui_story_70000301_41_dialog_content = "게다가 그쪽 길은 거리가 멀어. 지금 우리 속도로는 30분 이상을 더 쓰게 될 거야.",
  ui_story_70000301_42_dialog_content = "30분이라... 지금도 시간이 아슬아슬한데, 더 늦어지면 위험해...",
  ui_story_70000301_43_dialog_content = "PlayerName, 어떡하지? 돌아서 갈 거야?",
  ui_story_70000301_44_dialog_content = "시간이 없어.",
  ui_story_70000301_45_dialog_content = "돌아서 가는 것도 리스크가 너무 커. 시간도 부족하고.",
  ui_story_70000301_46_dialog_content = "이렇게 하자. 각자 암귀의 양쪽으로 잠입하는 거야.",
  ui_story_70000301_X46_dialog_content = "내가 소리를 내서 놈들의 주의를 끌게. 너는 그 틈에 기습해서 빠르게 처리해 줘.",
  ui_story_70000301_47_dialog_content = "알겠어.",
  ui_story_70000301_48_dialog_content = "PlayerName, 조심해!",
  ui_story_70000302_1_dialog_content = "지금 싸운 암귀들, 아까 녀석들보다 더 강해진 것 같지 않아?",
  ui_story_70000302_2_dialog_content = "암귀가 강해진 게 아니라 우리가 약해진 걸지도 몰라.",
  ui_story_70000302_3_dialog_content = "지하로 더 깊이 내려갈수록 호흡이 거칠어지고 있어.",
  ui_story_70000302_4_dialog_content = "어쩌면 이곳의 다크매터 농도는 밤낮의 변화만이 아니라 깊이도 관계가 있을지도 몰라.",
  ui_story_70000302_5_dialog_content = "깊이 빠질수록 짙어진다니... 괜히 「늪」이라고 불리는 게 아니었네...",
  ui_story_70000302_6_dialog_content = "여기가 코어룸 바로 위야. 주변에 암귀는 없어. 일단은 안전해.",
  ui_story_70000302_7_dialog_content = "PlayerName, 안색이 많이 안 좋아. 좀 쉬는 게 좋을 것 같아.",
  ui_story_70000302_8_dialog_content = "아직 한 시간 반 남았으니까, 몇 분 정도 쉬는 건 괜찮을 거야.",
  ui_story_70000302_9_dialog_content = "조금 더 버텨볼게. 시간을 끌 순 없어...",
  ui_story_70000302_10_dialog_content = "수첩에도 적혀 있었잖아. 어둠의 밑바닥에서의 싸움은\n확실하게 휴식을 취해서 체력을 보존해야 한다고 말이야.",
  ui_story_70000302_11_dialog_content = "내 말은 안 들어도, 「선배」의 충고는 들어야지.",
  ui_story_70000302_12_dialog_content = "알았어... 미안, 바이스. 역시 내가 짐이 되고 있네...",
  ui_story_70000302_13_dialog_content = "무슨 소리야, 우린 동료잖아.",
  ui_story_70000302_14_dialog_content = "자, 여기 돌이 있으니까 일단 여기 좀 앉아.",
  ui_story_70000302_15_dialog_content = "우리 이제 어디쯤 온 거야?",
  ui_story_70000302_16_dialog_content = "수첩 내용대로라면 여긴 예전에 창고였던 곳이야. 이미 꽤 깊은 곳까지 온 것 같아.",
  ui_story_70000302_17_dialog_content = "확실히 주변에 이런저런 물건들이 잔뜩 있네.",
  ui_story_70000302_18_dialog_content = "통조림 상자, 빈 구급상자, 곳곳에 널려 있는 탄피...",
  ui_story_70000302_19_dialog_content = "그리고 더러워진 천이랑 철판을 쌓아서 만든 구멍투성이의 방어 시설...",
  ui_story_70000302_20_dialog_content = "여길 지키던 일루미나 병사들은 분명히 마지막까지 싸웠을 거야.",
  ui_story_70000302_21_dialog_content = "하지만 결국엔 지켜내지 못했어...",
  ui_story_70000302_22_dialog_content = "......",
  ui_story_70000302_23_dialog_content = "내가 아는 건 그저 이 전투에서 일루미나가 정말... 정말 많은 사람을 잃었다는 것뿐이야...",
  ui_story_70000302_24_dialog_content = "천천히 살펴볼 시간이 있으면 여기서 병사들의 인식표를 찾을 수 있을 텐데...",
  ui_story_70000302_25_dialog_content = "일루미나로 가져갈 수 있다면 남은 가족들한테 조금은 위안이 될지도 몰라...",
  ui_story_70000302_26_dialog_content = "바이스...",
  ui_story_70000302_27_dialog_content = "나도 찾는 걸 도와주면...",
  ui_story_70000302_28_dialog_content = "어라...",
  ui_story_70000302_29_dialog_content = "저건...",
  ui_story_70000302_30_dialog_content = "PlayerName, 뭔가 찾았어?",
  ui_story_70000302_31_dialog_content = "폐허에 묻힌 저 파편들, 왠지 익숙한 느낌이야.",
  ui_story_70000302_32_dialog_content = "먼지를 뒤집어쓰고 있긴 한데, 저 하얀 파편의 무늬, 왠지...",
  ui_story_70000302_33_dialog_content = "<color=#FFB400>콜로서스 같은데?</color>",
  ui_story_70000302_34_dialog_content = "어라?",
  ui_story_70000302_35_dialog_content = "그러고 보니 확실히...",
  ui_story_70000302_36_dialog_content = "얼핏 보기엔 평범한 쓰레기지만, 자세히 보면──",
  ui_story_70000302_37_dialog_content = "콜로서스의 부품 같은데?",
  ui_story_70000302_38_dialog_content = "콜로서스의 부품이 아니더라도 왠지 「헤븐즈 밸리밖에 없는 물건」처럼 보여.",
  ui_story_70000302_39_dialog_content = "역시 싱크탱크 컴포넌트가 스카이워커호를 고칠 방법이 여기 있다고 한 이유가 있었어.",
  ui_story_70000302_40_dialog_content = "우리가 맞게 찾아온 것 같아.",
  ui_story_70000302_41_dialog_content = "한 번 더 부품의 위치를 감응해 볼게.",
  ui_story_70000302_42_option_content = "[감응한다]",
  ui_story_70000302_43_dialog_content = "이건...",
  ui_story_70000302_44_dialog_content = "크어어어──!",
  ui_story_70000302_45_dialog_content = "?!",
  ui_story_70000302_46_dialog_content = "PlayerName, 괜찮아?!",
  ui_story_70000302_47_dialog_content = "엄청 강력한 무언가를 느꼈어...",
  ui_story_70000302_48_dialog_content = "암귀야?",
  ui_story_70000302_49_dialog_content = "비슷해. 근데... 확실하진 않아.",
  ui_story_70000302_50_dialog_content = "그 녀석의 몸에서 강력한 다크매터가 뿜어져 나오고 있었어.\n근데 동시에 희미하게 루미나도 느껴졌어.",
  ui_story_70000302_51_dialog_content = "마치...",
  ui_story_70000302_52_dialog_content = "설마 여기도 노라가 개조한 암귀가 있는 건가?",
  ui_story_70000302_53_dialog_content = "잘 모르겠어.",
  ui_story_70000302_54_dialog_content = "확실한 건 그 녀석의 힘이 보통이 아니라는 거야.",
  ui_story_70000302_55_dialog_content = "이 근처는 아냐. 몰래 움직여서 녀석 모르게 부품을 가지고 얼른 떠나자.",
  ui_story_70000302_56_dialog_content = "몰래...",
  ui_story_70000302_57_dialog_content = "조심조심...",
  ui_story_70000302_58_dialog_content = "시간이 된 것 같군. 연락은 되나?",
  ui_story_70000302_59_dialog_content = "안 됩니다냥. 신호가 전혀 잡히지 않습니다냥.",
  ui_story_70000302_60_dialog_content = "구조대를 파견하실 건가요?",
  ui_story_70000302_61_dialog_content = "...휴, 구조대에 장비 준비 명령을 내려라. 나와 함께 간다.",
  ui_story_70000302_62_dialog_content = "대원수님이 직접 가시겠다고요?",
  ui_story_70000302_63_dialog_content = "물론이지. 나도 몸을 좀 풀 때가 됐으니까.",
  ui_story_70000302_64_dialog_content = "과연 저 정도의 시련은 아직 저들에겐 이른 것이었나...",
  ui_story_70000302_65_dialog_content = "아무래도 역시 천천히 단계를 밟는 게 좋겠군.",
  ui_story_70000302_66_dialog_content = "...알겠습니다.\n구조대, 대오 정렬!",
  ui_story_70000302_67_dialog_content = "『일루미나의 군대가 영원한 밤의 땅 변경에 집결하고 있습니다.』",
  ui_story_70000302_68_dialog_content = "『그자도 거기 있습니다.』",
  ui_story_70000302_69_dialog_content = "『그리고 동시에 아이테르도 80호 지하성에 진입했습니다.』",
  ui_story_70000302_70_dialog_content = "80호 지하성이라...",
  ui_story_70000302_71_dialog_content = "설마 그 여자도 <color=#FFB400>「그것」</color>을 찾고 있는 건가.",
  ui_story_70000302_72_dialog_content = "뭐, 확실히 세계 어딜 가도 단서가 남아있는 건 그곳뿐일 테니까.",
  ui_story_70000302_73_dialog_content = "그럼 과연 거기서 뭘 발견할지 한번 지켜봐 줄게.",
  ui_story_70000302_74_dialog_content = "「언니」.",
  ui_story_70000401_1_dialog_content = "PlayerName, 손 이리 줘.",
  ui_story_70000401_2_dialog_content = "에잇!",
  ui_story_70000401_3_dialog_content = "휴... 드디어... 도착했어...",
  ui_story_70000401_4_dialog_content = "여기 다크매터는 말도 안 되게 농도가 짙어... 조금만 몸을 움직여도 힘들어지고 있어.",
  ui_story_70000401_5_dialog_content = "PlayerName, 우리가 찾는 게 정말 이 근처에 있는 거야?",
  ui_story_70000401_6_dialog_content = "응, 느껴져. 이 근처에 있어.",
  ui_story_70000401_7_dialog_content = "아마... 코어 룸의 기계에 달려 있을 거야.",
  ui_story_70000401_8_dialog_content = "찾았어! 저거 같아!",
  ui_story_70000401_9_dialog_content = "저게... 진짜 의식 모듈이야?",
  ui_story_70000401_10_dialog_content = "스카이워커의 의식 모듈이랑은 전혀 다르잖아...",
  ui_story_70000401_11_dialog_content = "근데 싱크탱크 컴포넌트는 분명히 저걸 가리키고 있어.",
  ui_story_70000401_12_dialog_content = "게다가 이 근처에 의식 모듈처럼 보이는 다른 건 없어.",
  ui_story_70000401_13_dialog_content = "아무튼 일단 저걸 스카이워커로 가져가 보자!",
  ui_story_70000401_14_dialog_content = "알았어. 근데 지금은 코어에 부착돼 있잖아.",
  ui_story_70000401_15_dialog_content = "떼어낼 수 있는지 한번 해 볼게.",
  ui_story_70000401_16_dialog_content = "으음...",
  ui_story_70000401_17_dialog_content = "안 돼, 꽉 붙어 있어.",
  ui_story_70000401_18_dialog_content = "PlayerName, 도와줘.",
  ui_story_70000401_19_dialog_content = "알겠어!",
  ui_story_70000401_20_dialog_content = "셋 셀 테니까 같이 힘껏 당기는 거야.",
  ui_story_70000401_21_dialog_content = "3──",
  ui_story_70000401_22_dialog_content = "2──",
  ui_story_70000401_23_dialog_content = "1!",
  ui_story_70000401_24_dialog_content = "당겨!",
  ui_story_70000401_25_dialog_content = "으아아아──!",
  ui_story_70000401_26_dialog_content = "뒤통수를... 부딪힌 것 같아. 부품은 괜찮아?",
  ui_story_70000401_27_dialog_content = "딱히 이상은 없어 보여. 이제 얼른 가자!",
  ui_story_70000401_28_dialog_content = "<color=#e8d9bb>쿠르릉──</color>",
  ui_story_70000401_29_dialog_content = "지진인가?!",
  ui_story_70000401_30_dialog_content = "<color=#e8d9bb>쿠구구구──!</color>",
  ui_story_70000401_31_dialog_content = "지하성의 에너지 공급이... 멈췄잖아?!",
  ui_story_70000401_32_dialog_content = "우리가 부품을 뜯어서 그런 거야?",
  ui_story_70000401_33_dialog_content = "모르겠어. 근데... 뭔가가...",
  ui_story_70000401_34_dialog_content = "<color=#e8d9bb>쿠구구구──!</color>",
  ui_story_70000401_36_dialog_content = "점점 가까워지고 있어!",
  ui_story_70000401_37_dialog_content = "무너진다!",
  ui_story_70000401_37X1_dialog_content = "PlayerName! 얼른 벽에서 떨어져!",
  ui_story_70000401_37X2_dialog_content = "쿨럭, 쿨럭쿨럭!",
  ui_story_70000401_37X3_dialog_content = "먼지가 엄청 심하네...",
  ui_story_70000401_37X4_dialog_content = "......",
  ui_story_70000401_37X5_dialog_content = "무너진 벽 뒤에 공간이 있는데...?",
  ui_story_70000401_37X6_dialog_content = "안에 있는 건...",
  ui_story_70000401_37X7_dialog_content = "............",
  ui_story_70000401_37X8_dialog_content = "엄청난 다크매터야!",
  ui_story_70000401_37X9_dialog_content = "설마 PlayerName 네가 느꼈던 그 암귀야...?!",
  ui_story_70000401_37X10_dialog_content = "...!",
  ui_story_70000401_37X11_dialog_content = "확실히 암귀가 맞아. 게다가 지금까지 한 번도 본 적 없는 타입 같아!",
  ui_story_70000401_37X12_dialog_content = "아무 반응이 없는 것 같은데... 자고 있나?",
  ui_story_70000401_37X13_dialog_content = "일단 자극하지 말고 조용히 여길 벗어나자. 출구를 찾아야 해...",
  ui_story_70000401_37X14_dialog_content = "하지만 출구를 열려면 벽을 두드려야 해. 그럼 녀석도 분명히 깨어날 거야.",
  ui_story_70000401_37X15_dialog_content = "그럼 그땐 네가 먼저...",
  ui_story_70000401_37X16_dialog_content = "...미...나...",
  ui_story_70000401_37X17_dialog_content = "...잠꼬대인가...?",
  ui_story_70000401_37X18_dialog_content = "멀어서 뭐라는 건지 잘 안 들려.",
  ui_story_70000401_37X19_dialog_content = "말할 줄 아는 암귀도 이젠 신기할 거 없잖아...",
  ui_story_70000401_37X20_dialog_content = "녀석한테 신경 쓰지 마. 얼른 여길 떠날 방법을 찾아야 돼!",
  ui_story_70000401_37X21_dialog_content = "응, 맞아...",
  ui_story_70000401_37X22_dialog_content = "...일루...미나!",
  ui_story_70000401_37X23_dialog_content = "잠깐만, 들었어? 지금 녀석이...",
  ui_story_70000401_37X24_dialog_content = "크어어어──!",
  ui_story_70000401_37X25_dialog_content = "이런! 깨어났어!",
  ui_story_70000401_37X26_dialog_content = "어서 도망쳐! 우릴 봤어!",
  ui_story_70000401_38_dialog_content = "PlayerName! 조심해!",
  ui_story_70000401_39_dialog_content = "바이스! 괜찮아?!",
  ui_story_70000401_39X1_dialog_content = "여긴 다크매터가 너무 짙어서 녀석과 싸울 수 없어... 어떻게든 기회를 봐서 도망치자!",
  ui_story_70000401_40_dialog_content = "알았어, 넌 일단 녀석을 막아줘! 내가 출구를 찾을게!",
  ui_story_70000401_41_dialog_content = "크윽...!",
  ui_story_70000401_42_dialog_content = "서둘러! 몇 분 못 버틸 거야! 얼른 비밀 문을 찾아!",
  ui_story_70000402_1_dialog_content = "가볍게 3번──",
  ui_story_70000402_2_dialog_content = "<color=#e8d9bb>똑똑똑!</color>",
  ui_story_70000402_3_dialog_content = "세게 3번──",
  ui_story_70000402_4_dialog_content = "<color=#e8d9bb>쿵──! 쿵──! 쿵──!</color>",
  ui_story_70000402_5_dialog_content = "가볍게 3번──",
  ui_story_70000402_6_dialog_content = "<color=#e8d9bb>똑똑똑!</color>",
  ui_story_70000402_7_dialog_content = "......",
  ui_story_70000402_8_dialog_content = "왜 아무 반응도 없는 건데?!",
  ui_story_70000402_9_dialog_content = "얼른 열리라고!",
  ui_story_70000402_10_dialog_content = "PlayerName! 아직이야?!",
  ui_story_70000402_11_dialog_content = "안 돼! 전혀 반응이 없어!",
  ui_story_70000402_12_dialog_content = "크오오──!",
  ui_story_70000402_13_dialog_content = "으으윽──!",
  ui_story_70000402_14_dialog_content = "안 되겠어! 일단 밑으로 도망가자!",
  ui_story_70000402_15_dialog_content = "밑으로 도망치면 도망갈 길도 없잖아?!",
  ui_story_70000402_16_dialog_content = "지금 그런 거 따질 때가 아니야!",
  ui_story_70000402_17_dialog_content = "상부로 통하는 길은 저 암귀가 막고 있어. 돌파는 무리야!",
  ui_story_70000402_18_dialog_content = "밑으로 도망쳐서 숨으면 뭔가 다른 기회를 만들 수 있을지도 몰라!",
  ui_story_70000402_19_dialog_content = "...알겠어!",
  ui_story_70000402_20_dialog_content = "그럼 우물쭈물하지 말고 얼른 뛰어!",
  ui_story_70000402_21_dialog_content = "그어어어!",
  ui_story_70000402_22_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_70000402_23_dialog_content = "보, 보고드립니다!",
  ui_story_70000402_24_dialog_content = "80호 지하성 폐허 쪽에서 강한 지진이 발생했습니다!",
  ui_story_70000402_25_dialog_content = "진정해라. 당황하지 마라!",
  ui_story_70000402_26_dialog_content = "방어 진형을 유지하고 계속 80호 지하성을 향해 전진한다.",
  ui_story_70000402_27_dialog_content = "예!",
  ui_story_70000402_28_dialog_content = "<color=#e8d9bb>크오오오──!</color>",
  ui_story_70000402_29_dialog_content = "?!",
  ui_story_70000402_30_dialog_content = "이건...",
  ui_story_70000402_31_dialog_content = "...!",
  ui_story_70000402_32_dialog_content = "(이 느낌...)",
  ui_story_70000402_33_dialog_content = "(그럴 리가... 어째서...)",
  ui_story_70000402_34_dialog_content = "대원수님, 괜찮으십니까?!",
  ui_story_70000402_35_dialog_content = "......",
  ui_story_70000402_36_dialog_content = "(...안 돼. 저들을 보내선 안 돼.)",
  ui_story_70000402_37_dialog_content = "(저들은 감당할 수 없는 상대다.)",
  ui_story_70000402_38_dialog_content = "명령을 하달하겠다. 구조대는 즉시 안전 구역으로 돌아가라.",
  ui_story_70000402_39_dialog_content = "무슨 일이 발생하든 「어둠의 밑바닥」으로 진입해선 안 된다.",
  ui_story_70000402_40_dialog_content = "예! 하지만... 대원수님께선...",
  ui_story_70000402_41_dialog_content = "걱정할 거 없다. 내가 직접 처리해야 할 일이 있을 뿐이다.",
  ui_story_70000402_42_dialog_content = "그리고 비비안에게 전해라.",
  ui_story_70000402_43_dialog_content = "내가 돌아올 때까지 「녀석들」을 상대해 달라고.",
  ui_story_70000402_44_dialog_content = "예!",
  ui_story_70000402_45_dialog_content = "<color=#e8d9bb>크오오오──!</color>",
  ui_story_70000402_46_dialog_content = "......",
  ui_story_70000402_47_dialog_content = "역시 여기 「단서」가 있었어.",
  ui_story_70000402_48_dialog_content = "「발을 들여놓으면, 반드시 흔적을 남기는 법.」",
  ui_story_70000402_49_dialog_content = "이 퍼즐 조각은 내가 가져갈게.",
  ui_story_70000402_50_dialog_content = "노라──",
  ui_story_70000402_51_dialog_content = "약속을 잊지 마라.",
  ui_story_70000402_52_dialog_content = "쳇...",
  ui_story_70000402_53_dialog_content = "알고 있다고.",
  ui_story_70000402_54_dialog_content = "넌 내 신호에 맞춰서 저 벌레들이나 몰아내.",
  ui_story_70000402_55_dialog_content = "네 그 동요하는 마음은 결국 실패를 초래할 거다.",
  ui_story_70000402_56_dialog_content = "반쪽짜리여.",
  ui_story_70000402_57_dialog_content = "...멍청한 녀석이.",
  ui_story_70000501_1_dialog_content = "(미량의 루미나틱스 흔적인가. 아직 다크매터에 삼켜지지 않았군. 얼마 안 됐어.)",
  ui_story_70000501_2_dialog_content = "(암귀의 흔적은... 10마리 정도, 전투의 흔적은 많지 않군.)",
  ui_story_70000501_3_dialog_content = "(아무래도 기습 전술로 되도록 전투를 피한 모양인데.)",
  ui_story_70000501_4_dialog_content = "(전술 운용도 나쁘지 않아. 게다가 지형을 충분히 활용하고 있고...)",
  ui_story_70000501_5_dialog_content = "(꽤 하잖아. 조금씩은 지휘관다워지고 있어.)",
  ui_story_70000501_6_dialog_content = "(하지만 이런 곳에서 너흰 얼마나 더 버틸 수 있을까?)",
  ui_story_70000501_7_dialog_content = "<color=#e8d9bb>쿠르릉──</color>",
  ui_story_70000501_8_dialog_content = "(역시 갇혀버린 건가.)",
  ui_story_70000501_9_dialog_content = "(수첩에 분명히 몇 번이나 강조해 뒀는데, 이런 초보적인 실수를 저지르다니.)",
  ui_story_70000501_10_dialog_content = "(돌아가면 똑바로 가르쳐 줘야겠어.)",
  ui_story_70000501_11_dialog_content = "바이스! 오른쪽 뒤로 피해!",
  ui_story_70000501_12_dialog_content = "알았어!",
  ui_story_70000501_13_dialog_content = "이거나 받아라!",
  ui_story_70000501_14_dialog_content = "크오오──!",
  ui_story_70000501_15_dialog_content = "안 돼! 공격이 전혀 안 먹혀!",
  ui_story_70000501_16_dialog_content = "여긴 다크매터가 너무 강해!",
  ui_story_70000501_17_dialog_content = "녀석을 방해할 수 있는지 시험해 볼게!",
  ui_story_70000501_18_option_content = "(강제 감응──!)",
  ui_story_70000501_19_dialog_content = "일루...",
  ui_story_70000501_20_dialog_content = "일루?",
  ui_story_70000501_21_dialog_content = "...무슨 말을 하려는 거지?",
  ui_story_70000501_22_dialog_content = "일루...미나...",
  ui_story_70000501_23_dialog_content = "일루미나...? 일루미나 연방?!",
  ui_story_70000501_24_dialog_content = "일루미나──!",
  ui_story_70000501_25_dialog_content = "으윽! 엄청난 증오가...",
  ui_story_70000501_26_dialog_content = "PlayerName?!",
  ui_story_70000501_27_dialog_content = "난 괜찮아!",
  ui_story_70000501_28_dialog_content = "저 암귀, 이상해. 일루미나에 엄청 큰 원한을 품고 있는 것 같아!",
  ui_story_70000501_29_dialog_content = "일루미나... 크어어어!!",
  ui_story_70000501_30_dialog_content = "설마 내 일루미나 제복에 반응해서 공격하는 건가?",
  ui_story_70000501_31_dialog_content = "PlayerName! 내가 녀석을 유인할게! 넌 틈을 타서 밖으로 도망가!",
  ui_story_70000501_32_dialog_content = "넌 어쩌려고?!",
  ui_story_70000501_33_dialog_content = "내 신경 쓰지 말고 네 몸부터 지켜!",
  ui_story_70000501_34_dialog_content = "일루미나──!",
  ui_story_70000501_35_dialog_content = "으으윽──!",
  ui_story_70000501_36_dialog_content = "바이스!",
  ui_story_70000501_37_dialog_content = "어떻게든 바이스를 도와야 해...!",
  ui_story_70000501_38_dialog_content = "이 크기만 한 멍청한 자식아! 난 여기 있으니까 이쪽을 보라고!",
  ui_story_70000501_39_dialog_content = "그어어어!",
  ui_story_70000501_40_dialog_content = "PlayerName... 빨리... 도망가...",
  ui_story_70000501_41_dialog_content = "어디 잡아보라고!",
  ui_story_70000501_42_dialog_content = "그어어어!",
  ui_story_70000501_43_dialog_content = "(빠, 빨라!)",
  ui_story_70000501_44_dialog_content = "으윽──!",
  ui_story_70000501_45_dialog_content = "PlayerName?!",
  ui_story_70000501_46_dialog_content = "설마... 이런 데서 죽는 거야...?",
  ui_story_70000501_47_dialog_content = "사...살려줘... 누구든 좋으니까... 우릴...",
  ui_story_70000501_48_dialog_content = "그어어──",
  ui_story_70000501_49_dialog_content = "<color=#e8d9bb>채앵──!</color>",
  ui_story_70000501_50_dialog_content = "지휘관이라면 시선을 눈앞이 아닌 전황에 두어야 한다.",
  ui_story_70000501_51_dialog_content = "...이 목소리...",
  ui_story_70000501_52_dialog_content = "라인하르트 씨?!",
  ui_story_70000501_53_dialog_content = "아이테르 PlayerName, 넌 지휘관의 소질이 있다. 하지만 훈련이 부족해.",
  ui_story_70000501_54_dialog_content = "돌아가면 바튼하고 그람한테 똑바로 가르쳐 달라고 해!",
  ui_story_70000501_55_dialog_content = "으엑?!",
  ui_story_70000501_56_dialog_content = "일루미나── 일루미나──!",
  ui_story_70000501_57_dialog_content = "──!!!",
  ui_story_70000501_58_dialog_content = "대원수님...!",
  ui_story_70000501_59_dialog_content = "너희들, 아직 움직일 수 있다면 적당한 곳을 찾아서 숨어라.",
  ui_story_70000501_60_dialog_content = "바이스! 이쪽이야!",
  ui_story_70000501_61_dialog_content = "크어어어──!",
  ui_story_70000501_62_dialog_content = "설마, 정말로 네 녀석이었을 줄이야.",
  ui_story_70000501_63_dialog_content = "겉모습은 반쯤 암귀지만, 싸우는 방식은 전혀 변하지 않았군.",
  ui_story_70000501_64_dialog_content = "이상한데...? 라인하르트 씨... 저 암귀랑 얘기하고 있어.",
  ui_story_70000501_65_dialog_content = "설마 과거를 잊은 거냐?",
  ui_story_70000501_66_dialog_content = "「나의 친구」여.",
  ui_story_70000501_67_dialog_content = "「친구」...?",
  ui_story_70000501_68_dialog_content = "크오오!",
  ui_story_70000501_69_dialog_content = "이런! 여긴 다크매터가 짙어서 라인하르트 씨한테 불리해!",
  ui_story_70000501_70_dialog_content = "저 암귀와 감응할 수 있는지 시도해 봐야겠어...",
  ui_story_70000501_71_dialog_content = "(감응 연결──!)",
  ui_story_70000501_72_dialog_content = "크아아!",
  ui_story_70000501_73_dialog_content = "으아악!",
  ui_story_70000501_74_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_70000501_75_dialog_content = "저 녀석... 완전 막무가내잖아!",
  ui_story_70000501_76_dialog_content = "지하성이 무너져도 상관없다는 건가?!",
  ui_story_70000501_77_dialog_content = "PlayerName, 일단 멈춰라!",
  ui_story_70000501_78_dialog_content = "그리 당황할 거 없다.",
  ui_story_70000501_78X1_dialog_content = "──!!!",
  ui_story_70000501_78X2_dialog_content = "라인하르트 씨?! 피하세요!",
  ui_story_70000501_78X3_dialog_content = "대원수님!",
  ui_story_70000501_78X4_dialog_content = "걱정할 거 없다. 난 괜찮으니까.",
  ui_story_70000501_78X5_dialog_content = "그저... 시도해 보고 싶은 게 하나 있거든.",
  ui_story_70000501_79_dialog_content = "하, 하지만...",
  ui_story_70000501_80_dialog_content = "PlayerName, 일단 대원수님을 믿자.",
  ui_story_70000501_81_dialog_content = "라인하르트 씨... 어째서 반격하지 않는 거지?",
  ui_story_70000501_82_dialog_content = "...기억하고 있나?",
  ui_story_70000501_83_dialog_content = "우린 과거에 함께 싸웠고, 수많은 적을 무찔렀지.",
  ui_story_70000501_84_dialog_content = "......",
  ui_story_70000501_85_dialog_content = "수많은 참호를 파고, 연이어 들어오는 공격을 막아냈었다.\n우리의 고향 자난성을 지키기 위해서 말이야.",
  ui_story_70000501_86_dialog_content = "자...난... 성...",
  ui_story_70000501_87_dialog_content = "그래. 자난성 말이야. 우린 한때 자난성 앞에서 자신의 이름을 걸고 맹세했다.",
  ui_story_70000501_88_dialog_content = "넌 아직 네 이름을 기억하나?",
  ui_story_70000501_89_dialog_content = "크어어...",
  ui_story_70000501_90_dialog_content = "네 이름은── <color=#FFB400>헬리오스</color>다.",
  ui_story_70000501_91_dialog_content = "일루...미나...",
  ui_story_70000501_92_dialog_content = "일루미나──!",
  ui_story_70000501_93_dialog_content = "크오오──!",
  ui_story_70000501_94_dialog_content = "쳇, 역시 안 되는 거냐...",
  ui_story_70000501_95_dialog_content = "대원수님! 위험해요!",
  ui_story_70000501_96_dialog_content = "여기는 구조가 너무 취약해요! 더는 충격을 견딜 수가 없어요!",
  ui_story_70000501_97_dialog_content = "이대로 싸우다간 지하성이 통째로 무너지고 말 거예요!",
  ui_story_70000501_98_dialog_content = "...크어어!",
  ui_story_70000501_99_dialog_content = "자기가 지금 어떤 꼴인지를 좀 보라고...",
  ui_story_70000501_100_dialog_content = "떠올려라. 네가 누구인지.",
  ui_story_70000501_101_dialog_content = "나와 함께 일루미나로 돌아가는 거다. 원래 모습으로 돌아갈 방법을 함께 찾자!",
  ui_story_70000501_102_dialog_content = "그어어어!",
  ui_story_70000501_103_dialog_content = "쿨럭쿨럭──!",
  ui_story_70000501_104_dialog_content = "PlayerName! 이쪽에 숨어!",
  ui_story_70000501_105_dialog_content = "<color=#e8d9bb>띠리링──</color>",
  ui_story_70000501_106_dialog_content = "──!",
  ui_story_70000501_107_dialog_content = "이건...",
  ui_story_70000501_108_dialog_content = "벨소리? 어디서 나는 거지?",
  ui_story_70000501_109_dialog_content = "크어어어──!",
  ui_story_70000501_110_dialog_content = "저 고위 암귀... 뒤도 안 돌아보고 절벽 위로 올라가 버렸잖아?",
  ui_story_70000501_111_dialog_content = "설마 저 벨소리가 암귀를 제어하는 건가?",
  ui_story_70000501_112_dialog_content = "아니다.",
  ui_story_70000501_113_dialog_content = "저 벨소리는 <color=#FFB400>「지원군 도착, 철수 개시」</color>라는 의미의 신호거든.",
  ui_story_70000501_114_dialog_content = "저 암귀는... 아는 사람이었던 건가요?",
  ui_story_70000501_115_dialog_content = "알기만 할까. 내 전우였다.",
  ui_story_70000501_116_dialog_content = "서로 목숨을 맡긴 전우였지.",
  ui_story_70000501_117_dialog_content = "녀석은 「그림자 전투」 때 실종됐었다. 바로 이 지하성에서 말이야.",
  ui_story_70000501_118_dialog_content = "난 「그」가 죽었다고 생각했다. 설마...",
  ui_story_70000501_119_dialog_content = "아직 살아 있었고, 심지어 암귀가 되었을 줄은 전혀 몰랐지.",
  ui_story_70000501_120_dialog_content = "암귀가 됐다구요? 그거 설마...",
  ui_story_70000501_121_dialog_content = "「그」에 대한 일은 나도 아직 생각을 다 정리하지 못했다.",
  ui_story_70000501_122_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_70000501_123_dialog_content = "이 지하성은 이제 끝이 난 모양이군.",
  ui_story_70000501_124_dialog_content = "일단 여길 떠나지. 나머지는 가면서 얘기하자고.",
  ui_story_70000501_125_dialog_content = "그래야겠네요...",
  ui_story_70000501_126_dialog_content = "출구는 내가 알고 있으니까, 따라와라!",
  ui_story_70000601_1_dialog_content = "한때 내겐 가장 좋은 동료가 둘 있었다. 그중 하나가 바로 저 <color=#FFB400>헬리오스</color>였지.",
  ui_story_70000601_1X1_dialog_content = "그리고 다른 하나는 너희도 알고 있겠지. 그땐 아직 <color=#FFB400>드니에르</color>라고 불렸지만 말이야.",
  ui_story_70000601_1X2_dialog_content = "노라...?!",
  ui_story_70000601_1X3_dialog_content = "그래. 그게 지금의 이름이지.",
  ui_story_70000601_2_dialog_content = "우리 세 사람은 일루미나의 고아원에서 함께 자랐고, 군에 들어가 함께 싸웠다.",
  ui_story_70000601_3_dialog_content = "드니에르, 라인하르트, 다들 목표는 정했나?",
  ui_story_70000601_4_dialog_content = "교관 말로는 내가 소질이 있다고 하더라고. 아마 정찰병이 될 것 같다.",
  ui_story_70000601_5_dialog_content = "난 너희랑 달라. 실험실이야말로 내 전장이야.",
  ui_story_70000601_6_dialog_content = "열혈 바보 캐릭터는 나보다 더 적합한 녀석이 있잖아.",
  ui_story_70000601_7_dialog_content = "넌 여전히 사람 놀리는 걸 좋아하는구나.",
  ui_story_70000601_8_dialog_content = "그럼 넌? 라인하르트.",
  ui_story_70000601_9_dialog_content = "나?",
  ui_story_70000601_10_dialog_content = "아직 정하진 않았어. 그래도 작은 목표 정도는 세워두는 게 좋겠지.",
  ui_story_70000601_11_dialog_content = "먼저 일루미나의 대원수가 돼야겠어.",
  ui_story_70000601_12_dialog_content = "얼마 후 우리의 공적은 마침내 일루미나 지도층, 위원회의 주목을 받게 됐지.",
  ui_story_70000601_13_dialog_content = "그리고 3명 모두 대원수 후보자가 되었다.",
  ui_story_70000601_14_dialog_content = "너희는 일루미나에서 가장 우수한 병사이며, 일루미나의 미래를 짊어지고 있다.",
  ui_story_70000601_15_dialog_content = "이제 너희가 치러야 할 것은 일루미나에서 가장 가혹한 훈련이다.",
  ui_story_70000601_16_dialog_content = "매일마다, 심지어 1시간마다 누군가가 도태된다.",
  ui_story_70000601_17_dialog_content = "그러나 그 훈련을 이겨내는 자는 일루미나의 대원수가 된다.",
  ui_story_70000601_18_dialog_content = "최강의 존재가 되는 것이다!",
  ui_story_70000601_19_dialog_content = "자신 있나?!",
  ui_story_70000601_20_dialog_content = "있습니다.",
  ui_story_70000601_21_dialog_content = "있습니다!",
  ui_story_70000601_22_dialog_content = "있습니다──!",
  ui_story_70000601_23_dialog_content = "<color=#FFB400>위원회</color>? 그게 뭐죠?",
  ui_story_70000601_24_dialog_content = "어? PlayerName, 위원회 못 들어봤어?",
  ui_story_70000601_25_dialog_content = "전혀!",
  ui_story_70000601_26_dialog_content = "뭐? 위원회는 대원수님과 함께 일루미나의 각종 사무를 관리하는 기구야!",
  ui_story_70000601_27_dialog_content = "일루미나 사람들은 항상 「대원수」만 입에 달고 살잖아!",
  ui_story_70000601_28_dialog_content = "「위원회」 같은 얘길 해준 사람은 하나도 없었다고.",
  ui_story_70000601_29_dialog_content = "크흠...",
  ui_story_70000601_30_dialog_content = "(이런! 푸념에만 정신이 팔려서 대원수 본인이 여기 있는 것도 잊어버렸잖아!)",
  ui_story_70000601_31_dialog_content = "위원회의 정식 명칭은 <color=#FFB400>「일루미나 연방 군사 및 정무위원회」</color>다.",
  ui_story_70000601_32_dialog_content = "상대하기 힘든 골동품들의 모임이지. 저들은 일루미나의 모든 일을 직접 살핀다.",
  ui_story_70000601_33_dialog_content = "하지만 녀석들은 겉으로 드러나는 걸 좋아하지 않거든. 외부인이 모르는 건 당연하지.",
  ui_story_70000601_34_dialog_content = "(다행이다... 라인하르트 씨도 그냥 넘어가 주는 것 같네...)",
  ui_story_70000601_35_dialog_content = "어라? 잠깐만요. 그 말은 그럼──",
  ui_story_70000601_36_dialog_content = "일루미나의 대원수는 위원회에서 정한다는 말이 되잖아요?",
  ui_story_70000601_37_dialog_content = "에?",
  ui_story_70000601_38_dialog_content = "대원수는... 가장 많은 전공을 세운 사람이 되는 게 아닌가요?",
