  ui_story_70000601_40_dialog_content = "전공은 조건 중의 하나일 뿐이다.",
  ui_story_70000601_41_dialog_content = "사람의 마음을 단결시키는 것은 쉬운 일이 아니지.",
  ui_story_70000601_41X_dialog_content = "일루미나 연방은 수많은 지하성으로 이루어져 있다.\n「전공」만 가지고는 신망을 얻을 수 없다.",
