  ui_story_70000601_49_dialog_content = "이런 데에 비밀 통로가 있는 건가요?!",
  ui_story_70000601_50_dialog_content = "정확히 말하자면 대피로다.",
  ui_story_70000601_51_dialog_content = "이 지하성의 대피로에는 특수한 보강 처리가 되어 있다.\n아마 지진이 잦은 지대인 것을 고려했겠지.",
