  ui_story_70000601_53_dialog_content = "들어와라.",
  ui_story_70000601_54_dialog_content = "엄청 조용하네요...",
  ui_story_70000601_55_dialog_content = "바이스, 도와줄게.",
  ui_story_70000601_56_dialog_content = "고마워, PlayerName.",
  ui_story_70000601_57_dialog_content = "근데 난 정말 괜찮아.",
