  ui_story_70000601_61_dialog_content = "수, 수첩에 대해 아세요? 설마...",
  ui_story_70000601_62_dialog_content = "당연히 내가 쓴 거지.\n게다가 네가 필리시한테 부탁해서 80호 지하성을 조사한 것도 알고 있다.",
  ui_story_70000601_63_dialog_content = "!!!",
  ui_story_70000601_64_dialog_content = "왜 그런 눈으로 보는 거지?",
  ui_story_70000601_65_dialog_content = "난 일루미나 연방에서 유일하게 어둠의 밑바닥에서 전투를 치르고 살아서 돌아온 사람이다.",
  ui_story_70000601_66_dialog_content = "이 80호 지하성이 바로 우리의 전장이었지.",
