  ui_story_70000601_68_dialog_content = "그럼 왜 여기 오신 거죠...?",
  ui_story_70000601_69_dialog_content = "대원수님은 자난성에 계실 줄 알았는데요...",
  ui_story_70000601_70_dialog_content = "너희가 이 구역을 탐색하는 걸 묵인한 건 너희들의 능력을 믿었기 때문이다.",
  ui_story_70000601_71_dialog_content = "하지만 그렇다고 예상 밖의 상황이 벌어질 가능성을 무시하거나,\n너희가 위험에 빠지도록 내버려두겠다는 것도 아니다.",
  ui_story_70000601_72_dialog_content = "대원수의 책무는 일루미나의 모든 사람을 지키는 것이니까.",
