  ui_story_70000601_78_dialog_content = "너희가 위험에 처할 뻔한 건 예상밖의 일이었다.",
  ui_story_70000601_79_dialog_content = "맞아요. 원래 계획은 순조롭게 진행되고 있었어요.\n근데 지하에 저렇게 강한 적이 있을 줄 몰라서...",
  ui_story_70000601_79X_dialog_content = "만약 내가 헬리오스의 존재를 느끼고 제때 오지 않았다면, 아마 큰일이 벌어졌겠지.",
  ui_story_70000601_80_dialog_content = "믿을 수 있는 정보라 해도, 모든 것을 믿어서는 안 된다.",
