  ui_story_70000602_60_dialog_content = "가장 강력한 화염만이 모든 구석까지 빛을 비추고,\n절망 속에 있는 모든 이들에게 희망을 보여줄 수 있지.",
  ui_story_70000602_61_dialog_content = "희망이 있어야만 단결할 수 있고, 이 고통스러운 세상에서 계속해서 나아갈 수 있다.",
  ui_story_70000602_62_dialog_content = "하지만... 강한 자가 세상에 나타나길 마냥 기다리기만 해서는,\n죽을 때까지 기다려도 한 사람조차 나타나지 않을지도 모른다.",
  ui_story_70000602_63_dialog_content = "그래서 그 어떤 고난과 고통을 겪더라도,\n나는 일루미나의 대원수가 되고 싶었다.",
  ui_story_70000602_63X_dialog_content = "그 최강의 존재가 되고자 했다.",
  ui_story_70000602_64_dialog_content = "......",
  ui_story_70000602_65_dialog_content = "애송이, 그런 표정을 지을 필요는 없다.",
  ui_story_70000602_66_dialog_content = "그런 말도 있지 않았나──",
  ui_story_70000602_67_dialog_content = "「왕관을 쓰려는 자, 그 무게를 견뎌라」.",
  ui_story_70000602_68_dialog_content = "안심해라. 하늘이 무너져도 받쳐줄 사람이 있을 테니까.",
  ui_story_70000602_69_dialog_content = "마찬가지로 일루미나에 무슨 일이 있으면 대원수가 나선다.",
  ui_story_70000602_70_dialog_content = "물론 너도 포함해서 말이지.",
  ui_story_70000602_71_dialog_content = "도착했군.",
  ui_story_70000701_1_dialog_content = "여긴 왠지 지하성의 표면 같은데요. 저희가 처음에 들어왔을 때 있었던 곳이랑 비슷해요.",
  ui_story_70000701_2_dialog_content = "근데 대피로를 빙글빙글 돌아서 그런지 어지러워서 방향을 잘 모르겠어요...",
  ui_story_70000701_3_dialog_content = "PlayerName, 여긴 우리가 들어온 곳이랑 전혀 다른 곳이야.",
  ui_story_70000701_4_dialog_content = "오히려... 완전 반대 방향이야.",
  ui_story_70000701_5_dialog_content = "뭐?!",
  ui_story_70000701_6_dialog_content = "잘 모르겠어? 천장의 배관 분포랑 기능 구역을 나눈 걸 보면 알 수 있잖아.\n그리고 환기 덕트 방향도──",
  ui_story_70000701_7_dialog_content = "(바이스가 또 내가 모르는 말을 하기 시작했다...)",
  ui_story_70000701_8_dialog_content = "으엑... 저, 저기, 질문이 있는데요!",
  ui_story_70000701_9_dialog_content = "왕성한 호기심도 아이테르의 특징인가?",
  ui_story_70000701_10_dialog_content = "죄송해요! 진짜로 마지막이에요!",
  ui_story_70000701_11_dialog_content = "상관없다. 호기심이 많은 건 나쁜 게 아니니까. 말해라.",
  ui_story_70000701_12_dialog_content = "아까 도망친 그 고위 암귀는... 그러니까 전에 라인하르트 씨의 전우였다는 거잖아요.",
  ui_story_70000701_13_dialog_content = "근데 왜 저렇게 변한 거죠?",
  ui_story_70000701_14_dialog_content = "설마 또 노라의 소행인가요? 근데 「씨앗」의 흔적은 못 느꼈던 것 같은데요.",
  ui_story_70000701_15_dialog_content = "내가 할 수 있는 답은 모르겠다는 것뿐이다.",
  ui_story_70000701_16_dialog_content = "당시 전황은 참혹했고, 우린 모두 그가 죽었다고 생각할 수밖에 없었지.",
  ui_story_70000701_17_dialog_content = "그때... 대체 무슨 일이 있었죠?",
  ui_story_70000701_18_dialog_content = "......",
  ui_story_70000701_19_dialog_content = "그때 대원수 후보로 훈련을 받던 우린 한 특수부대에 속해 있었다.",
  ui_story_70000701_20_dialog_content = "그리고 11년 전, 우린 위원회의 명령을 받고 기술 물자를 회수하러\n오래전에 버려졌던 80호 지하성으로 향했었지.",
  ui_story_70000701_21_dialog_content = "당시 정보에 따르면 80호 지하성은 다크매터의 영향 범위 안에 있지만,\n그래도 암귀의 수는 많지 않다고 했었다.",
  ui_story_70000701_22_dialog_content = "그래서 우린 너희들과 마찬가지로 빠른 기동이 가능한 경무장을 택했다.",
  ui_story_70000701_22X_dialog_content = "짧은 낮 시간에 지하성으로 들어가, 목적을 달성하면 빠르게 퇴각할 생각이었지.",
  ui_story_70000701_23_dialog_content = "그러나... 실제 상황은 정보와 크게 달랐다.",
  ui_story_70000701_24_dialog_content = "안 되겠어! 암귀가 너무 많아!",
  ui_story_70000701_25_dialog_content = "지원을 요청한다! 지원을──",
  ui_story_70000701_26_dialog_content = "지하성 안에는 어항 속 물고기처럼 암귀가 가득 차 있었다.\n아무리 쓰러트려도 놈들은 끝없이 몰려왔지.",
  ui_story_70000701_27_dialog_content = "기술 물자가 있는 창고까지 도달하는 것만으로도 이미 20%의 전우를 잃고 말았다.",
  ui_story_70000701_28_dialog_content = "그러니까 저희가 창고에서 본 그 방어 시설이나 장비의 잔해는...",
  ui_story_70000701_29_dialog_content = "모두 그때 용감하게 싸웠던 병사들의 유품이다.",
  ui_story_70000701_30_dialog_content = "......",
  ui_story_70000701_31_dialog_content = "그리고 우리가 물건을 확보하고 철수하려던 때는...",
  ui_story_70000701_32_dialog_content = "이미 해가 진 뒤였다.",
  ui_story_70000701_33_dialog_content = "더 많은 강력한 암귀들이 무언가에 이끌린 것처럼 80호 지하성으로 밀려들었다...",
  ui_story_70000701_34_dialog_content = "바로 지금처럼 말이야.",
  ui_story_70000701_35_dialog_content = "크어어어──!",
  ui_story_70000701_36_dialog_content = "바이스, PlayerName, 전투 준비다!",
  ui_story_70000702_1_dialog_content = "그어어...",
  ui_story_70000702_2_dialog_content = "끝났네요!",
  ui_story_70000702_3_dialog_content = "주변에... 일단은 적이 없는 것 같아요.",
  ui_story_70000702_4_dialog_content = "바이스...!",
  ui_story_70000702_5_dialog_content = "으윽... 몸이... 무거워...",
  ui_story_70000702_6_dialog_content = "지금은 자정이다. 다크매터가 가장 짙어질 때지.",
  ui_story_70000702_7_dialog_content = "너흰 그나마 나은 편이다. 그때 우리가 여기 왔을 땐 많은 사람들이 그대로 정신을 잃었다.",
  ui_story_70000702_8_dialog_content = "그때 우리가 맞섰던 암귀는 지금의 100배, 1000배가 넘는 수였다...",
  ui_story_70000702_9_dialog_content = "<color=#e8d9bb>「그림자 전투」 시기</color>",
  ui_story_70000702_10_dialog_content = "3시 방향!",
  ui_story_70000702_11_dialog_content = "그어어어!",
  ui_story_70000702_12_dialog_content = "<color=#e8d9bb>탕탕탕──!</color>",
  ui_story_70000702_13_dialog_content = "타깃 소멸!",
  ui_story_70000702_14_dialog_content = "10시 방향에 고위 암귀 발견!",
  ui_story_70000702_15_dialog_content = "수는... 하나, 둘... 안 돼! 너무 많아!",
