  ui_story_70000702_17_dialog_content = "지나가게 둘 줄 알고!",
  ui_story_70000702_18_dialog_content = "크오오──",
  ui_story_70000702_19_dialog_content = "정보에서는 암귀가 이렇게 많다고 안 했잖아!",
  ui_story_70000702_20_dialog_content = "위원회의 정보에 오류가 존재할 수 있는 거야...?",
  ui_story_70000702_21_dialog_content = "이런 상황은 되도록 피하고 싶었는데...\n어차피 벌어진 이상, 회수한 물자를 가지고 도망치는 수밖에 없어!",
  ui_story_70000702_22_dialog_content = "그 뒤의 일들은 너희도 대충 짐작이 가겠지.",
  ui_story_70000702_23_dialog_content = "지하성 내의 다크매터는 통신 전파를 차단한 탓에,\n포위를 뚫고 지원을 요청하는 임무는 내가 맡게 되었다.",
  ui_story_70000702_24_dialog_content = "그러나 내가 안전 구역으로 돌아와 지원을 요청했을 때,\n지하성은 이미 함락됐고, 붕괴가 발생한 뒤였다.",
  ui_story_70000702_25_dialog_content = "그런 상황에서 암귀에게 포위된 지하성으로 가서,\n무너진 잔해에서 사람을 구하며 암귀와 싸운다는 건...",
  ui_story_70000702_26_dialog_content = "얼마나 많은 대가를 치러야 할지 상상할 수 있을 거다.\n그리고 그 결실은 아주 적거나, 심지어 전무할 수도 있지.",
