  ui_story_70000702_28_option_content = "어째서 그런...",
  ui_story_70000702_29_dialog_content = "남겨진 사람들은 모두 일루미나의 병사들이잖아요? 다 같은 목숨이라구요...",
  ui_story_70000702_30_dialog_content = "어째서... 왜 그들을 포기한 거죠?",
  ui_story_70000702_31_dialog_content = "......",
  ui_story_70000702_32_dialog_content = "그 물음은 한때 날 오랫동안 괴롭혔지. 네가 이해하지 못하는 것도 당연하다.",
  ui_story_70000702_33_dialog_content = "그때 지하성으로 향했던 것은 내가 몸담고 있던 부대,\n즉 일루미나에서 가장 좋은 장비를 갖추고, 가장 강력한 전투력을 지닌 부대였다.",
  ui_story_70000702_34_dialog_content = "그런 우리조차 80호 지하성에서 승리를 거두지 못했는데,\n안전 구역을 지키는 일반 부대는 말할 것도 없을 것이다.",
  ui_story_70000702_35_dialog_content = "지하에 갇힌 자들은 모두 내 전우들이었다. 저들이 죽는 것은 나도 당연히 바라지 않았다.",
  ui_story_70000702_36_dialog_content = "하지만 우리보다 약한 저 보통의 병사들도 똑같은 내 전우들이 아닌가?",
  ui_story_70000702_37_dialog_content = "만약 열 사람의 목숨으로 한 사람을 생환시킬 수 있다면, 넌 그렇게 할 건가?",
  ui_story_70000702_38_dialog_content = "......",
  ui_story_70000702_39_dialog_content = "너도 이해할 수 있겠지. 누구나 가족과 친구, 그리고 소중한 것이 있다.",
