  ui_story_70000801_11_dialog_content = "근데 주변은 온통 암귀투성이인데요...",
  ui_story_70000801_12_dialog_content = "이런 상황에서 접근하실 건가요?",
  ui_story_70000801_13_dialog_content = "이건 내 개인적인 부탁이다. 5분만 시간을 벌어줘.",
  ui_story_70000801_14_dialog_content = "마지막으로 시도해 보고 싶거든.",
  ui_story_70000801_15_dialog_content = "5분이 지나면 전원 철수다.",
  ui_story_70000801_16_dialog_content = "네! 도와드릴게요!",
  ui_story_70000801_17_dialog_content = "PlayerName 넌?",
  ui_story_70000801_18_dialog_content = "저도 도울게요.",
  ui_story_70000801_19_dialog_content = "이번엔 반드시 구해내자구요!",
  ui_story_70000801_20_dialog_content = "하하, 그럼 잘 봐 둬라.",
  ui_story_70000801_21_dialog_content = "일루미나의 의지를.",
  ui_story_70000801_22_dialog_content = "그럼 평소대로 나눠져서 행동할게요.",
  ui_story_70000801_23_dialog_content = "바이스, 우린 반대편으로 가는 거야.",
  ui_story_70000801_24_dialog_content = "알았어.",
  ui_story_70000801_25_dialog_content = "여기면 괜찮을 거야!",
  ui_story_70000801_26_dialog_content = "좋아, 라인하르트 씨도 준비된 것 같아.",
  ui_story_70000801_27_dialog_content = "그럼...",
  ui_story_70000801_28_dialog_content = "이 암귀 조무래기들! 자신 있으면 날 잡아 봐!",
  ui_story_70000801_29_dialog_content = "그어...?",
  ui_story_70000801_30_dialog_content = "크어어어──!",
  ui_story_70000801_31_dialog_content = "흐이익!",
  ui_story_70000801_32_dialog_content = "왜 이렇게 많아?!",
  ui_story_70000801_33_dialog_content = "PlayerName! 조금만 버텨줘!",
  ui_story_70000802_1_dialog_content = "벌써 잊어버린 거냐.",
  ui_story_70000802_2_dialog_content = "일루미나의 꿈을.",
  ui_story_70000802_3_dialog_content = "일루미나의 신념을.",
  ui_story_70000802_4_dialog_content = "일루미나의 영광을.",
  ui_story_70000802_5_dialog_content = "일루미나의 기억을...",
  ui_story_70000802_6_dialog_content = "모두 잊었냔 말이다!",
  ui_story_70000802_7_dialog_content = "그어어어!",
  ui_story_70000802_8_dialog_content = "말해라...",
  ui_story_70000802_9_dialog_content = "어째서 빛을 등지고, 어둠에 몸을 던진 거지?",
  ui_story_70000802_10_dialog_content = "살기 위해서였나?!",
  ui_story_70000802_11_dialog_content = "아니면 누가 사주한 거냐?",
  ui_story_70000802_12_dialog_content = "말해──",
  ui_story_70000802_13_dialog_content = "<size=45>대답해!</size>",
  ui_story_70000802_14_dialog_content = "크오오──!",
  ui_story_70000802_15_dialog_content = "<color=#e8d9bb>띠리링──</color>",
  ui_story_70000802_16_dialog_content = "...!",
  ui_story_70000802_17_dialog_content = "또 벨소리야!",
  ui_story_70000802_18_dialog_content = "이번에는 엄청 가까웠어... 저기다!",
  ui_story_70000802_19_dialog_content = "<color=#e8d9bb>띠리링──</color>",
  ui_story_70000802_20_dialog_content = "저건...",
  ui_story_70000802_21_dialog_content = "노라?!",
  ui_story_70000802_22_dialog_content = "......",
  ui_story_70000802_23_dialog_content = "오랜만이네. 꽤 수다스러워졌잖아.",
  ui_story_70000802_24_dialog_content = "라인하르트.",
  ui_story_70000802_25_dialog_content = "드니에르... 아니, 노라.",
  ui_story_70000802_26_dialog_content = "헬리오스가 저렇게 된 게 네 짓인가?",
  ui_story_70000802_27_dialog_content = "그 일에 대해선 내가 아는 것도 너와 다를 게 없어.",
  ui_story_70000802_28_dialog_content = "하지만 그가 좋은 실험 재료라는 것은 부정하지 않을게.",
  ui_story_70000802_29_dialog_content = "그럼 그가 저렇게 된 건 대체...",
  ui_story_70000802_30_dialog_content = "아직도 모르겠어?",
  ui_story_70000802_31_dialog_content = "그는 아무것도 잊어버리지 않았어.",
  ui_story_70000802_32_dialog_content = "그저... 너무 생생하게 기억하고 있을 뿐이지.",
  ui_story_70000802_33_dialog_content = "...?!",
  ui_story_70000802_34_dialog_content = "불쌍하게 버려진 체스말, 그가 유일하게 잊은 건 오히려 일루미나에 대한 원망뿐이야.",
  ui_story_70000802_35_dialog_content = "그리고 이제 그걸 기억해낼 때가 됐어!",
  ui_story_70000802_36_dialog_content = "<size=45>크아아악!</size>",
  ui_story_70000802_37_dialog_content = "으으윽──!",
  ui_story_70000802_38_dialog_content = "이건... 기억인가?!",
  ui_story_70000802_39_dialog_content = "라인하르트가 포위를 돌파한 지 벌써 4시간째야...",
  ui_story_70000802_40_dialog_content = "그런데도 아직 「벨소리」는 들리지 않아.",
  ui_story_70000802_41_dialog_content = "난 아직 힘이 남아 있어. 설령 이 주먹만 남게 되더라도 암귀들을 패줄 수 있다고.",
  ui_story_70000802_42_dialog_content = "넌 어때? 보급이랑 탄약은 얼마나 남았지?",
  ui_story_70000802_43_dialog_content = "탄약 10발... 그리고 톱밥 빵 2개.",
  ui_story_70000802_44_dialog_content = "이럴 줄 알았으면 애초에 자난성에 남아서 실험실의 성가신 규칙에\n얽매여 있는 편이 훨씬 나았겠어.",
  ui_story_70000802_45_dialog_content = "소총이나 탄약보단 역시 메스로 암귀를 해부하는 게 내 특기니까.",
  ui_story_70000802_46_dialog_content = "하하, 역시 주목받는 연구원답다니까.",
  ui_story_70000802_47_dialog_content = "너라면 분명히 암귀의 몸을 봉합할 때 나비매듭을 묶어줄 수도 있겠지.",
  ui_story_70000802_48_dialog_content = "흥, 잘도 여유롭네.",
  ui_story_70000802_49_dialog_content = "근데 우리가 얼마나 더 버틸 수 있을까?",
  ui_story_70000802_50_dialog_content = "아니면... 벌써 버려진 걸까?",
  ui_story_70000802_51_dialog_content = "......",
  ui_story_70000802_52_dialog_content = "무슨 일이 있어도 삶의 희망을 버려선 안 돼.",
  ui_story_70000802_53_dialog_content = "라인하르트는... 분명히 지원군을 데리고 우릴 구하러 올 거다.",
  ui_story_70000802_54_dialog_content = "그때까지 우린 어떻게든 살아남자고.",
  ui_story_70000802_55_dialog_content = "봐! 앞에 출구가 있어!",
  ui_story_70000802_56_dialog_content = "주변에 돌아다니는 암귀들이 너무 많아. 그리고...",
  ui_story_70000802_57_dialog_content = "<color=#e8d9bb>콰르릉──!</color>",
  ui_story_70000802_58_dialog_content = "아까 전투 때문에 여긴 곧 무너질 것 같아.",
  ui_story_70000802_59_dialog_content = "지금은 날이 밝으니까, 암귀의 힘이 가장 약해질 때다.",
  ui_story_70000802_60_dialog_content = "지금 도망가지 않으면 우린 정말 여기 갇혀서 죽을 거라고.",
  ui_story_70000802_61_dialog_content = "바짝 따라 와. 암귀가 최대한 멀어졌을 때를 노려서 포위를 돌파하자.",
  ui_story_70000802_62_dialog_content = "11시 방향!",
  ui_story_70000802_63_dialog_content = "알겠어!",
  ui_story_70000802_64_dialog_content = "빌어먹을... 끝이 없잖아!",
  ui_story_70000802_65_dialog_content = "난 아직 버틸 수 있어! 드니에르, 출구로 나가!",
  ui_story_70000802_66_dialog_content = "<color=#e8d9bb>콰르릉──!</color>",
  ui_story_70000802_67_dialog_content = "지면이 갈라진다! 조심해!",
  ui_story_70000802_68_dialog_content = "크아아악!",
  ui_story_70000802_69_dialog_content = "헬리오스──!",
  ui_story_70000802_70_dialog_content = "나는 반드시... 살아남는다.",
  ui_story_70000802_71_dialog_content = "지원이... 올 때까지.",
  ui_story_70000802_72_dialog_content = "며칠이나 지난 거지...",
  ui_story_70000802_73_dialog_content = "몸에... 좋지 않은 변화가 일어난 것 같다...",
  ui_story_70000802_74_dialog_content = "벨소리... 빨리 울리란 말이다...",
  ui_story_70000802_75_dialog_content = "하루... 이틀...",
  ui_story_70000802_76_dialog_content = "일 년... 이 년...",
  ui_story_70000802_77_dialog_content = "대체 지원은 왜 아직도 안 오는 거냐...",
  ui_story_70000802_78_dialog_content = "어째서 날 버린 거냐!",
  ui_story_70000802_79_dialog_content = "크어어어──!",
  ui_story_70000802_80_dialog_content = "생각난 모양이네.",
  ui_story_70000802_81_dialog_content = "하지만 아직 부족해.",
  ui_story_70000802_82_dialog_content = "「씨앗」과 마찬가지로 분노는 최고의 양분이야...",
  ui_story_70000802_83_dialog_content = "내가 조금만 더 도와줄게.",
  ui_story_70000802_84_dialog_content = "노라! 뭘 하려는 거지?!",
  ui_story_70000802_85_dialog_content = "......",
  ui_story_70000802_86_dialog_content = "라인하르트...",
  ui_story_70000802_87_dialog_content = "어째서... 구하러 오지 않은 거야?",
  ui_story_70000802_88_dialog_content = "......",
  ui_story_70000802_89_dialog_content = "그때 상황에선 너희를 희생시키는 게 최선의 선택이었다.",
  ui_story_70000802_90_dialog_content = "넌 역시──",
  ui_story_70000802_91_dialog_content = "조금도 성장하질 않았구나.",
  ui_story_70000802_92_dialog_content = "너도, 일루미나도 똑같이 말이야.",
  ui_story_70000802_93_dialog_content = "크어어어──!",
  ui_story_70000802_94_dialog_content = "조심하세요! 이쪽으로 돌진하고 있어요!",
  ui_story_70000802_95_dialog_content = "분노해. 그리고... 성장해.",
  ui_story_70000802_96_dialog_content = "이 어둠의 밑바닥에서 모든 걸 집어삼켜.",
  ui_story_70000802_97_dialog_content = "크어어어──!",
  ui_story_70000802_98_dialog_content = "이제 이 일에 매듭을 지을 때가 된 건가.",
  ui_story_70000802_99_dialog_content = "바이스! 전투 준비야!",
  ui_story_70000802_100_dialog_content = "응!",
  ui_story_70000902_1_dialog_content = "크오오...",
  ui_story_70000902_2_dialog_content = "이런 상황에서마저 제압당한 거야?",
  ui_story_70000902_3_dialog_content = "역시 그냥 <color=#FFB400>「불량품」</color>이었구나.",
  ui_story_70000902_4_dialog_content = "그래도 아직 움직일 수 있다는 점 하나는 실험의 예측 밖이었어.",
  ui_story_70000902_5_dialog_content = "조금은 가치가 있다고 할 수 있겠네.",
  ui_story_70000902_6_dialog_content = "하지만 내 시간은 한정적이거든.",
  ui_story_70000902_7_dialog_content = "으으윽──!",
  ui_story_70000902_8_dialog_content = "주변의 다크매터가... 모여들고 있어!",
  ui_story_70000902_9_dialog_content = "다크매터가... 너무 짙어! 안 되겠어!",
  ui_story_70000902_10_dialog_content = "하, 몇 년 못 본 사이에 허약한 연구원이 싸움에 능숙해졌잖아.",
  ui_story_70000902_11_dialog_content = "닥쳐.",
  ui_story_70000902_12_dialog_content = "약자는 무릎을 꿇어야지.",
  ui_story_70000902_13_dialog_content = "그리고 넌 이 다크매터를 가지고 네 마지막 가치를 보여봐.",
  ui_story_70000902_14_dialog_content = "크어어어──!",
  ui_story_70000902_15_dialog_content = "암귀가... 사라지고 있어...!",
  ui_story_70000902_16_dialog_content = "크아아악!",
  ui_story_70000902_17_dialog_content = "...비명 소리야!",
  ui_story_70000902_18_dialog_content = "노라가 녀석들의 생명력을... 다크매터를 흡수하고 있어!",
  ui_story_70000902_19_dialog_content = "이런 엄청난 힘을 그대로 공격에 쓴다면...",
  ui_story_70000902_20_dialog_content = "단순한 폭발로도 지하성이 통째로... 재가 될 거야!",
  ui_story_70000902_21_dialog_content = "라인하르트 씨, 조심해요!",
  ui_story_70000902_22_dialog_content = "...!",
  ui_story_70000902_23_dialog_content = "PlayerName! 어서 숨어!",
  ui_story_70000902_24_dialog_content = "늦었어.",
  ui_story_70000902_25_dialog_content = "(그것은 지금까지 본 것 중에서 가장 절망적인 장면이었다.)",
  ui_story_70000902_26_dialog_content = "(온 하늘을 뒤덮은 다크매터가 극야의 어둠을 휩쓸고,\n해일처럼 포효하며 지상에 있는 모든 것에 몰아치고 있었다.)",
  ui_story_70000902_27_dialog_content = "(막대한 위압감 앞에서 나와 바이스는 거대한 돌이 지워진 듯 일어설 수조차 없었다.)",
  ui_story_70000902_28_dialog_content = "(나는 그저 어떻게든 고개를 들어 다크매터가 자신을 집어삼키는 것을 바라만 볼 뿐이었다.)",
  ui_story_70000902_29_dialog_content = "그러나 그 칠흑 같은 어둠 속에서──",
  ui_story_70000902_30_dialog_content = "나는 <color=#FFB400>빛</color>을 보았다.",
  ui_story_70000902_31_dialog_content = "너희 뜻대론 안 될 거다.",
  ui_story_70000902_32_dialog_content = "라인하르트 씨?!",
  ui_story_70000902_33_dialog_content = "(극야의 장막 아래, 그 빛은 결코 밝다고 할 수 없었고, 언제라도 삼켜질 것만 같았다.)",
  ui_story_70000902_34_dialog_content = "(그러나 그 빛은 그럼에도 애써 빛줄기를 뻗어 사방을 비추고 있었다.)",
  ui_story_70000902_35_dialog_content = "(마치 태양이 지평선에서 솟아오르듯, 희미하게 밝아진 하늘은 여명의 시작을 알려왔다.)",
  ui_story_70000902_36_dialog_content = "고작... 다크매터일 뿐이잖아.",
  ui_story_70000902_37_dialog_content = "내가 짊어지고 있는 건... 여명의 빛이란 말이다!",
  ui_story_70000902_38_dialog_content = "일루미나에서는 하늘이 무너져도 내가 받쳐낸다──!",
  ui_story_70000902_39_dialog_content = "(어둠이 점차 걷혔다.)",
  ui_story_70000902_40_dialog_content = "(그리고, 빛이 지평선을 꿰뚫었다.)",
  ui_story_70000902_41_dialog_content = "으윽!",
  ui_story_70000902_42_dialog_content = "...!",
  ui_story_70000902_43_dialog_content = "라인하르트 씨!",
  ui_story_70000902_44_dialog_content = "방어를 포기하고 목숨도 내던진 공격인가.",
  ui_story_70000902_45_dialog_content = "그러면서도 대부분의 공격을 막아내다니...",
  ui_story_70000902_46_dialog_content = "후훗, 역시 넌 미친 녀석이야.",
  ui_story_70000902_47_dialog_content = "어리석고... 미쳤어.",
  ui_story_70000902_48_dialog_content = "뭐, 이 정도 힘은 실험 예측 범위 안이지만.",
  ui_story_70000902_49_dialog_content = "하지만 보통의 오로리안이라면 이런 압도적인 다크매터 앞에서 진작 정신을 잃었을 거야.",
  ui_story_70000902_50_dialog_content = "역시 대단해.",
  ui_story_70000902_51_dialog_content = "과연 살아서 늪을 빠져나갔던 가장 걸출한 「괴물」답다니까.",
  ui_story_70000902_52_dialog_content = "그 녀석들, 널 정말 잘 「교육」했구나.",
  ui_story_70000902_53_dialog_content = "흥, 피차일반이지.",
  ui_story_70000902_54_dialog_content = "그런 수준의 기술이 있으면서 더 나아가지 않고 영웅놀이에 만족하다니.",
  ui_story_70000902_55_dialog_content = "그리고 넌... 아무래도 그 배역에 너무 빠져버린 것 같네.",
  ui_story_70000902_56_dialog_content = "이건 우리 세 사람이 처음부터 가졌던 꿈이었어...",
  ui_story_70000902_57_dialog_content = "일루미나의 대원수가 되어 일루미나인들을 이끌고 더 나은 삶을 찾는 것 말이야.",
  ui_story_70000902_58_dialog_content = "「일루미나를 위해, 사람들을 위해」...",
  ui_story_70000902_59_dialog_content = "듣기 좋은 말이네. 근데 저들은 너한테 요구하고, 네 보호를 갈구하면서,\n정작 너한테는 뭘 해줬지?",
  ui_story_70000902_60_dialog_content = "저들 눈에 넌 그저 상징화된 기호일 뿐이야. 다 쓰고 나면 언제든지 버려지겠지.",
  ui_story_70000902_61_dialog_content = "그렇게 보면 저 실험동물들이나 너나 다를 것도 없어.",
  ui_story_70000902_62_dialog_content = "연구원이 신경 쓰는 건 언제나 동물에게서 얻어낼 실험 데이터뿐.",
  ui_story_70000902_63_dialog_content = "그리고 저 녀석들이 신경 쓰는 건... 강해 보이는 상징일 뿐.\n그 역할을 누구에게 맡길지는 아무래도 상관없어.",
  ui_story_70000902_64_dialog_content = "훗...",
  ui_story_70000902_65_dialog_content = "하하하!",
  ui_story_70000902_66_dialog_content = "노라, 아니 드니에르...",
  ui_story_70000902_67_dialog_content = "수다스러워진 건 너도 마찬가지잖아.",
  ui_story_70000902_68_dialog_content = "옛날에는 실험실에 틀어박혀 공부만 했었는데 말이야.",
  ui_story_70000902_69_dialog_content = "내가 뭐라고 하든, 넌 네가 가장 우수하다는 걸 증명하겠다는 말밖에 안 했었지.",
  ui_story_70000902_70_dialog_content = "......",
  ui_story_70000902_71_dialog_content = "그때 넌 남들이 널 어떻게 보든 전혀 개의치 않았어.",
  ui_story_70000902_72_dialog_content = "나도 마찬가지다. 나는 일루미나의 대원수다.\n그러니 나는 일루미나를 지키고 일루미나인들을 지키는 거다.",
  ui_story_70000902_73_dialog_content = "일루미나인들이 날 어떻게 생각하는지는 상관없어.",
  ui_story_70000902_74_dialog_content = "그 점은 너한테 배운 거라고.",
  ui_story_70000902_75_dialog_content = "......",
  ui_story_70000902_76_dialog_content = "너에 대한 연구 기록에는 「광기」란 태그를 하나 더 붙여줄게.",
  ui_story_70000902_77_dialog_content = "재료는 이미 손에 넣었으니까, 그럼 슬슬 돌아가서 실험을 계속해야겠어.",
  ui_story_70000902_78_dialog_content = "노...라...",
  ui_story_70000902_79_dialog_content = "벌레의 생명력은 정말 끈질기네.",
  ui_story_70000902_80_dialog_content = "이 실패한 실험체랑은 다르게 말이야...",
  ui_story_70000902_81_dialog_content = "......",
  ui_story_70000902_82_dialog_content = "이제 한계인가...",
  ui_story_70000902_83_dialog_content = "뭐, 어떻게든 연구 재료로 쓸 순 있을 것 같네.",
  ui_story_70000902_84_dialog_content = "오로리안도 아니고, 암귀도 아니야.",
  ui_story_70000902_85_dialog_content = "그저... 소소한 이용 가치만 남은 반쪽짜리일 뿐이지만.",
  ui_story_70000902_86_dialog_content = "뭘 하려는 거냐! 녀석을 내려놔!",
  ui_story_70000902_87_dialog_content = "지금 네 꼴로 날 막을 수 있겠어?",
  ui_story_70000902_88_dialog_content = "「때가 됐어.」",
  ui_story_70000902_89_dialog_content = "...지평선 너머로... 진동이 전해지고 있어... 그리고... 모래먼지?",
  ui_story_70000902_90_dialog_content = "PlayerName, 저것들... 뭐야?",
  ui_story_70000902_91_dialog_content = "모르겠어. 한번 살펴볼게...",
  ui_story_70000902_92_option_content = "(강제 감응!)",
  ui_story_70000902_93_dialog_content = "...!",
  ui_story_70000902_94_dialog_content = "(저게... 다 암귀라고?!)",
  ui_story_70000902_95_dialog_content = "(암귀... 군단이야!)",
  ui_story_70000902_96_dialog_content = "『노라를... 엄호한다!』",
  ui_story_70000902_97_dialog_content = "(이쪽을 향해 오는 건가?!",
  ui_story_70000902_98_dialog_content = "(수가 너무 많아... 라인하르트 씨가 있다 해도...)",
  ui_story_70000902_99_dialog_content = "(아니야, 방금 그 공격으로 라인하르트 씨도 중상을 입었어.)",
  ui_story_70000902_100_dialog_content = "(지금 버틸 수 있는 건 아마 의지로 겨우 참아내고 있는 거야!)",
  ui_story_70000902_101_dialog_content = "(당장 물러나야 해!)",
  ui_story_70000902_102_dialog_content = "라인하르트 씨! 상황이 안 좋아요!",
  ui_story_70000902_103_dialog_content = "뭐?",
  ui_story_70000902_104_dialog_content = "암귀 군단이 오고 있어요! 지금 바로 이쪽으로 오고 있다구요!",
  ui_story_70000902_105_dialog_content = "그중엔 엄청 강한 개체도 있어요!",
  ui_story_70000902_106_dialog_content = "지금 당장 철수해야 돼요!",
  ui_story_70000902_107_dialog_content = "3분만 있으면 돼. 전부 끝낼 테니까!",
  ui_story_70000902_108_dialog_content = "크어어어──!",
  ui_story_70000902_109_dialog_content = "더는 안 돼요! 라인하르트 씨!",
  ui_story_70000902_110_dialog_content = "이러다간... 포위될 거라구요!",
  ui_story_70000902_111_dialog_content = "......",
  ui_story_70000902_112_dialog_content = "「제3조: 『늪』에서의 작전 시 최대한 전투를 피하고, 자신의 역량에 맞게 행동한다」\n라인하르트 씨가 했던 말이잖아요!",
  ui_story_70000902_113_dialog_content = "............",
  ui_story_70000902_114_dialog_content = "약자네.",
  ui_story_70000902_115_dialog_content = "너도 잘 알고 있겠지. 그는 우리와 함께 싸웠던 전우다.",
  ui_story_70000902_116_dialog_content = "만약 네가 그를 해친다면... 일루미나의 군인을 해친다면,\n그 대가를 반드시 치르게 될 거다.",
  ui_story_70000902_117_dialog_content = "하.",
  ui_story_70000902_118_dialog_content = "큰소리는 살아남은 뒤에나 다시 쳐.",
  ui_story_70000902_119_dialog_content = "지금의 넌 선택권이 없으니까.",
  ui_story_70000902_120_dialog_content = "......",
  ui_story_70000902_121_dialog_content = "바이스, PlayerName, 철수다.",
  ui_story_70000902_122_dialog_content = "......",
  ui_story_70000902_123_dialog_content = "너한테 주어진 시간은 이제 얼마 없어...",
  ui_story_70000902_124_dialog_content = "「언니」.",
  ui_story_70001001_1_dialog_content = "바이스, 라인하르트 씨를 부축해 줘. 난 콜로서스를 가동할 테니까!",
  ui_story_70001001_2_dialog_content = "응!",
  ui_story_70001001_3_dialog_content = "벌써... 이륙했나?",
  ui_story_70001001_4_dialog_content = "네! 이미 이륙했어요!",
  ui_story_70001001_5_dialog_content = "다행히 암귀 군단에 휘말리기 전에 이륙할 수 있었어요...",
  ui_story_70001001_6_dialog_content = "전속력으로... 귀환해라...",
  ui_story_70001001_7_dialog_content = "대원수님?!",
  ui_story_70001001_8_dialog_content = "상처가 깊어. 분명히 처음부터 억지로 버티고 있었을 거야.",
  ui_story_70001001_9_dialog_content = "PlayerName, 넌 스카이워커호를 조종해. 난 가서 구급 물자를 찾아볼게!",
  ui_story_70001001_10_dialog_content = "응!",
  ui_story_70001001_11_dialog_content = "라인하르트 씨, 조금만 더 참아요...",
  ui_story_70001001_12_dialog_content = "으윽...",
  ui_story_70001001_13_dialog_content = "이런... 대원수님 상태가 너무 안 좋아!",
  ui_story_70001001_14_dialog_content = "당장 치료가 필요해!",
  ui_story_70001001_15_dialog_content = "<color=#e8d9bb>「치료 키워드를 탐지했습니다.」</color>",
  ui_story_70001001_16_dialog_content = "<color=#e8d9bb>「데이터 스캔 중... 스캔 완료.」</color>",
  ui_story_70001001_17_dialog_content = "<color=#e8d9bb>「스캔 결과, 의식 모듈 복구기에 업그레이드 데이터가 있습니다.」</color>",
  ui_story_70001001_18_dialog_content = "<color=#e8d9bb>「복구기를 설치하면 생명유지 시스템을 의료시스템으로 업그레이드할 수 있습니다.」</color>",
  ui_story_70001001_19_option_content = "스카이워커?!",
  ui_story_70001001_20_dialog_content = "갑자기 기동했어?!",
  ui_story_70001001_21_dialog_content = "의식 모듈 복구기라면... 이거 얘긴가? 그래... 왜 잊고 있었지?!",
  ui_story_70001001_22_dialog_content = "의료 시스템이라면... 라인하르트 씨를 구하는 데 도움이 될지도 몰라.",
  ui_story_70001001_23_dialog_content = "일단 설치해 보자!",
  ui_story_70001001_24_dialog_content = "<color=#e8d9bb>「의식 모듈 복구기를 감지했습니다.」</color>",
  ui_story_70001001_25_dialog_content = "<color=#e8d9bb>「연결 중... 연결 완료.」</color>",
  ui_story_70001001_26_dialog_content = "<color=#e8d9bb>「우선도 판정... 판정 완료.」</color>",
  ui_story_70001001_27_dialog_content = "<color=#e8d9bb>「생명유지 시스템 업그레이드 데이터를 감지했습니다. 업그레이드를 진행합니다.」</color>",
  ui_story_70001001_28_dialog_content = "복구기가... 변하고 있어!",
  ui_story_70001001_29_dialog_content = "<color=#e8d9bb>「업그레이드 완료. 의료 시스템 정상 작동 중.」</color>",
  ui_story_70001001_30_dialog_content = "<color=#e8d9bb>「현재 부하량: 1, 잔여 공간: 1.」</color>",
  ui_story_70001001_31_dialog_content = "<color=#e8d9bb>「서명하십시오.」</color>",
  ui_story_70001001_32_dialog_content = "어? 근데... 먼저 테스트 안 해봐도 될까?",
  ui_story_70001001_33_dialog_content = "으윽...",
  ui_story_70001001_34_dialog_content = "지금은... 그런 걸 따질 겨를이 없다.",
  ui_story_70001001_35_dialog_content = "시도해... 보는 수밖에...",
  ui_story_70001001_36_dialog_content = "...네!",
  ui_story_70001001_37_dialog_content = "의료 시스템이 도움이 됐으면 좋겠는데...",
  ui_story_70001001_38_dialog_content = "분명히 괜찮을 거야.",
  ui_story_70001001_39_dialog_content = "난 라인하르트 씨를 믿어. 그리고 스카이워커라면 분명히 해낼 거라고 믿어.",
  ui_story_70001001_40_dialog_content = "아까 그 메시지도 그래...\n어쩌면 우리가 곤란해하는 걸 스카이워커가 느끼고 도와준 건지도 몰라...",
  ui_story_70001001_41_dialog_content = "응...",
  ui_story_70001001_42_dialog_content = "의료 시스템이 효과를 발휘하려면 시간이 조금 걸릴 것 같아.",
  ui_story_70001001_43_dialog_content = "우선은 의식 모듈의 복구 방법부터 살펴보자.",
  ui_story_70001001_44_dialog_content = "응, 나도 도와줄게.",
  ui_story_70001001_45_dialog_content = "<color=#e8d9bb>「의식 모듈 복구 프로세스를 계속 실행합니다.」</color>",
  ui_story_70001001_46_dialog_content = "<color=#e8d9bb>「먼저 콜로서스 의식 표준 데이터베이스 플러그인을 설치하십시오.」</color>",
  ui_story_70001001_47_dialog_content = "으응...?",
  ui_story_70001001_48_dialog_content = "뭐라는 거야...?",
  ui_story_70001001_49_dialog_content = "PlayerName, 다른 모듈 가져온 거 있어?",
  ui_story_70001001_50_dialog_content = "없지... 이거 하나뿐이야!",
  ui_story_70001001_51_dialog_content = "스카이워커, 그 데이터베이스 플러그인 어쩌고 하는 건 또 뭐야?",
  ui_story_70001001_52_dialog_content = "<color=#e8d9bb>「콜로서스 의식 표준 데이터베이스 플러그인에 대한 정보 검색 중... 검색 완료.」</color>",
  ui_story_70001001_53_dialog_content = "<color=#e8d9bb>「답변, 콜로서스 의식 표준 데이터베이스 플러그인은 콜로서스 의식 템플릿입니다.」</color>",
  ui_story_70001001_54_dialog_content = "<color=#e8d9bb>「현재 해당 모듈의 저장량은 0입니다.」</color>",
  ui_story_70001001_55_dialog_content = "<color=#e8d9bb>「콜로서스 의식 표준 데이터베이스 플러그인은 각 콜로서스의 정비 기지에서 제공됩니다.」</color>",
  ui_story_70001001_56_dialog_content = "<color=#e8d9bb>「가장 가까운 콜로서스 정비 기지 검색 중... 검색 완료.」</color>",
  ui_story_70001001_57_dialog_content = "<color=#e8d9bb>「가장 가까운 위치는 헤븐즈 밸리입니다.」</color>",
  ui_story_70001001_58_dialog_content = "헤븐즈 밸리...?!",
  ui_story_70001001_59_dialog_content = "거기 기지가 있다고?!",
  ui_story_70001001_60_dialog_content = "그런 건 들어본 적 없어...",
  ui_story_70001001_61_dialog_content = "<color=#e8d9bb>「플러그인을 설치할 수 없는 경우 의식 모듈 복구기는 대기 상태로 진입합니다.」</color>",
  ui_story_70001001_62_dialog_content = "...대기 상태로 진입해.",
  ui_story_70001001_63_dialog_content = "<color=#e8d9bb>「스카이워커호 의식 모듈 복구기, 대기 상태로 진입합니다.」</color>",
  ui_story_70001001_64_dialog_content = "헤븐즈 밸리로 돌아가면 그 <color=#FFB400>「콜로서스 정비 기지」</color>를 조사하러 가자.",
  ui_story_70001001_65_dialog_content = "계곡을 전부 뒤져서라도 스카이워커를 구할 방법을 찾아내겠어...",
  ui_story_70001001_66_dialog_content = "하지만 지금 우린 대원수님을 어서 안전 구역으로 보내드려야 해...",
  ui_story_70001001_67_dialog_content = "아, 그것도 그렇네...",
  ui_story_70001001_68_dialog_content = "라인하르트 씨는 어때?",
  ui_story_70001001_69_dialog_content = "의료 시스템이 지금 치료를 진행하는 중이야.",
  ui_story_70001001_70_dialog_content = "효과는 어떨지 모르겠지만...",
  ui_story_70001001_71_dialog_content = "결과가 좋길 바랄 수밖에 없겠네.",
  ui_story_70001001_72_dialog_content = "<color=#e8d9bb>삐비비비──</color>",
  ui_story_70001001_73_dialog_content = "이건... 일루미나의 통신 요청이야. 근데 발신자 이름이 없는데?",
  ui_story_70001001_74_dialog_content = "지원군일지도 몰라. 일단 연결해 보자!",
  ui_story_70001001_75_dialog_content = "바이스 중위님, 응답 바랍니다. 아이테르 PlayerName, 응답 바랍니다.\n스카이워커호, 응답 바랍니다.",
  ui_story_70001001_76_dialog_content = "들립니까?",
  ui_story_70001001_77_dialog_content = "음... 뭐라고 대답하더라...?",
  ui_story_70001001_78_dialog_content = "아, 맞다. 여기는 스카이워커호. 수신 양호.",
  ui_story_70001001_79_dialog_content = "이쪽은 일루미나 정보장교 에센입니다.",
  ui_story_70001001_80_dialog_content = "현재 위치를 알려 주십시오.",
  ui_story_70001001_81_dialog_content = "지금 80호 지하성 남동쪽에 있어요.\n아마 10분 정도 뒤에 일루미나 방위선에 도착할 거예요.",
  ui_story_70001001_82_dialog_content = "그리고 보고해야 할 긴급 상황이 있어요!",
  ui_story_70001001_83_dialog_content = "대원수님께서 전투 중 중상을 입어 치료가 필요해요!",
  ui_story_70001001_84_dialog_content = "역시...",
  ui_story_70001001_85_dialog_content = "알겠습니다.",
  ui_story_70001001_86_dialog_content = "의무부대를 일루미나 방위선에 대기시키겠습니다.\n여러분께서는 즉시 대원수님을 일루미나 방위선으로 호송해 주십시오.",
